pub(crate) struct ToolCall {
    pub(crate) id: String,
    pub(crate) name: String,
    pub(crate) input: JsonObject,
}

#[derive(Clone, Debug)]
pub(crate) struct ToolExecution {
    pub(crate) call: ToolCall,
    pub(crate) result: ToolResult,
    pub(crate) subagent: Option<SubagentRunRecord>,
}

#[derive(Clone, Debug)]
pub(crate) struct Exchange {
    pub(crate) continuation: Value,
    pub(crate) executions: Vec<ToolExecution>,
    /// Background-task completions the host delivered while this exchange was
    /// the batch of tool results still owed to the model. They go out in the
    /// same request as those results, immediately after them, each as its own
    /// fabricated `box` exchange.
    ///
    /// Transient by construction: the durable side of the delivery is the
    /// host-signed timeline card, which projects into the very same call and
    /// result on every later turn (`wire_history::host_task_delivery`).
    /// Whenever a branch drops the live exchanges it also syncs `generated`
    /// into `request.contexts`, so the card takes over the carrier duty in the
    /// same step.
    pub(crate) host_deliveries: Vec<crate::wire_history::HostDelivery>,
    /// Tools that joined the conversation at the boundary after this exchange
    /// (`tool_append.rs`), projected after its deliveries. Transient like them:
    /// the durable side is the marker in the timeline, which takes over once
    /// the exchange is dropped.
    pub(crate) tool_additions: Vec<Vec<String>>,
    /// System prompts appended at the boundary after this exchange
    /// (`system_append.rs`), projected after its deliveries and before its
    /// tool additions, the order the boundary records them in. Transient on
    /// the same terms as `tool_additions`.
    pub(crate) system_appends: Vec<String>,
}

impl Exchange {
    fn new(continuation: Value, executions: Vec<ToolExecution>) -> Self {
        Self {
            continuation,
            executions,
            host_deliveries: Vec::new(),
            tool_additions: Vec::new(),
            system_appends: Vec::new(),
        }
    }
}

/// Cancellation probe interval when no renderer-visible event is flowing, including
/// retry waits, quiet stream gaps, and background search-worker settlement.
pub(crate) const CANCELLATION_PROBE_INTERVAL: Duration = Duration::from_millis(500);

/// Sleeps a retry backoff in slices, probing the event sink between slices so
/// user cancellation (or a closed channel) aborts the wait promptly.
pub(crate) fn probe_sleep(delay: Duration, event_sink: &ModelEventSink<'_>) -> Result<(), String> {
    let deadline = Instant::now() + delay;
    loop {
        let remaining = deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            return Ok(());
        }
        std::thread::sleep(remaining.min(CANCELLATION_PROBE_INTERVAL));
        event_sink(ModelStreamEvent::Ping)?;
    }
}

pub type ModelEventSink<'a> = dyn Fn(ModelStreamEvent) -> Result<(), String> + Send + Sync + 'a;

/// A session-level sink owned by detached workers and stored in `TaskSurface`.
/// It must not fail: disconnected subscribers or settled rounds must not kill tasks.
pub type OwnedModelEventSink = dyn Fn(ModelStreamEvent) -> Result<(), String> + Send + Sync;

struct HookRunServices<'sink> {
    event_sink: &'sink ModelEventSink<'sink>,
    /// Cancellation signal for hook commands in this run, derived by ownership:
    /// task rounds use the task signal and top-level rounds use this run's signal.
    /// Hook waits use it to terminate the process tree promptly after user stop.
    cancellation: CancelSignal,
}
/// Who is asking for a dangerous call. `agent` is the addressable child name
/// (subagent / pool worker), `call_id` the parent-timeline call id of that
/// child's turn; both `None` for the main session's own calls. With up to
/// `MAX_LIVE_AGENTS` children able to prompt concurrently, a confirmation that
/// does not name the requester is not an informed decision — and the call id is
/// what lets the renderer open the requester's own page, because a streaming
/// workflow step is keyed by it rather than by the displayed pool name.
#[derive(Clone, Copy, Default)]
pub struct ApprovalRequester<'a> {
    pub agent: Option<&'a str>,
    pub call_id: Option<&'a str>,
}

/// The requester identity a request carries into every approval prompt it
/// raises. One derivation point so the name and the call id can never come
/// from different children.
pub(crate) fn approval_requester(request: &RunModelRequest) -> ApprovalRequester<'_> {
    ApprovalRequester {
        agent: request.subagent_name.as_deref(),
        call_id: request.subagent_call_id.as_deref(),
    }
}

/// The third parameter names the requester — see [`ApprovalRequester`].
pub type DangerousToolApproval<'a> = dyn Fn(&ToolExecutionRequest, &ToolDescriptor, ApprovalRequester<'_>) -> Result<bool, String>
    + Send
    + Sync
    + 'a;

/// The borrowed four-argument form: the same contract as
/// [`OwnedTaskApproval`], threaded down to whichever worker is going to wait on
/// the card. Only the worker knows its own stop flag, so the flag is supplied at
/// the call rather than captured at construction.
pub type TaskApproval<'a> = dyn Fn(
        &ToolExecutionRequest,
        &ToolDescriptor,
        ApprovalRequester<'_>,
        Option<&std::sync::atomic::AtomicBool>,
    ) -> Result<bool, String>
    + Send
    + Sync
    + 'a;

/// Session-level approval closure owned by detached workers.
///
/// The caller passes its own cancellation signal. Task and top-level calls must
/// observe only their respective signal, never a conversation-wide union.
/// When no run is active, approvals are delivered through the app push channel.
pub type OwnedTaskApproval = dyn Fn(
        &ToolExecutionRequest,
        &ToolDescriptor,
        ApprovalRequester<'_>,
        Option<&std::sync::atomic::AtomicBool>,
    ) -> Result<bool, String>
    + Send
    + Sync;

/// The three-argument form the run loop consumes, in owned shape. A worker
/// binds its own stop flag onto [`OwnedTaskApproval`] with a closure to produce
/// one of these.
pub type OwnedDangerousToolApproval = dyn Fn(&ToolExecutionRequest, &ToolDescriptor, ApprovalRequester<'_>) -> Result<bool, String>
    + Send
    + Sync;

/// Builds one conversation's approval closure, shared by the top-level run and
/// every detached task worker of that conversation.
///
/// Approval cards travel on either an unsettled run stream or the app push
/// channel. Run-owned cards are retracted when the run ends; task-owned cards
/// end only when answered, stopped by their own flag, or timed out.
///
/// When present, `task_cancel` is the only cancellation flag this closure
/// observes. It prevents an unrelated foreground stop from withdrawing a
/// background task approval.
///
/// `security_level` is the live cell rather than a value: a detached worker may
/// still be classifying calls after the level moved under it, and it must obey
/// the level in force now, not the one its run started with.
pub(crate) fn session_task_approval(
    state: &AppState,
    conversation_id: String,
    security_level: Arc<crate::model::LiveSecurityLevel>,
    app_data_path: String,
    additional_directories: Vec<String>,
    workspaces: crate::workspace_set::WorkspaceSet,
) -> Arc<OwnedTaskApproval> {
    let approval_state = state.clone();
    Arc::new(
        move |tool_request: &ToolExecutionRequest,
              descriptor: &ToolDescriptor,
              requester: ApprovalRequester<'_>,
              task_cancel: Option<&std::sync::atomic::AtomicBool>| {
            // Observe only this call's cancellation signal. A task call uses its
            // task signal and a top-level call uses this run's signal, preventing
            // an unrelated foreground stop from withdrawing a task approval.
            // The signal may be absent in direct tests; `PROMPT_TIMEOUT` still bounds it.
            let mut cancellations: Vec<&std::sync::atomic::AtomicBool> = Vec::new();
            if let Some(flag) = task_cancel {
                cancellations.push(flag);
            }
            let mcp = descriptor.category == ToolCategory::Mcp;
            // Call-site-required confirmation cannot be answered or persisted by
            // an existing permanent permission.
            let forced = descriptor.force_confirmation;
            let (mandatory, risk, reason) = if mcp {
                // An MCP call is dispatched by a server Mework cannot audit, so
                // the classifier has nothing to say about it. Treating it as
                // mandatory is what keeps a blanket allowance off remote side
                // effects.
                (
                    true,
                    security::RiskLevel::High,
                    security::Reason::new(
                        "MCP Server 或本地包会收到这些参数，可能访问网络或产生其他副作用",
                        "The MCP server or local package receives these arguments and may reach the network or have other side effects",
                    ),
                )
            } else {
                // Classify using this call's workspace. Isolated workflow steps rely
                // on `workspace_path` to distinguish an allowed isolated edit from a
                // write escaping to the parent checkout; the host constructs this trusted field.
                let decision = security::classify_model_call_in_workspaces(
                    security_level.get(),
                    &workspaces,
                    Path::new(&tool_request.workspace_path),
                    Path::new(&app_data_path),
                    &additional_directories,
                    tool_request,
                )?;
                (
                    decision.mandatory_prompt,
                    decision.risk_level,
                    decision.reason.clone(),
                )
            };
            let mandatory = mandatory || forced;
            // Permanent allowances apply only to a class narrower than arbitrary
            // shell execution, only when the host can classify the call, and never
            // when the configured security level requires confirmation.
            let allow_always_offered = !mcp
                && !mandatory
                && !crate::tool_prompt::never_blanket_allowed(&tool_request.tool_name);
            let language = approval_card_language(&approval_state, &app_data_path);
            let card = crate::tool_prompt::PendingToolPrompt {
                // Minted by the registry; see `ToolPromptRegistry::ask`.
                prompt_id: String::new(),
                tool_name: tool_request.tool_name.clone(),
                kind: crate::tool_prompt::PromptKind::Tool,
                label: descriptor.label.clone(),
                summary: crate::tool_prompt::summarize_tool_input(
                    &tool_request.tool_name,
                    &public_tool_input(&tool_request.tool_name, &tool_request.input),
                ),
                risk_level: risk.label(language).to_owned(),
                reason: reason.text(language).to_owned(),
                requester: requester.agent.map(crate::tool_prompt::escape_display_text),
                // Preserve machine-readable coordinates: `requester` is escaped
                // display text, while these fields are renderer lookup keys.
                source_agent: requester.agent.map(str::to_owned),
                source_call_id: requester.call_id.map(str::to_owned),
                allow_always_offered,
                mandatory,
                questions: None,
            };
            // A prompt belongs to a run only when a run is unsettled and this
            // request was not initiated by a task worker.
            let owner = match approval_state
                .run_streams()
                .live_request_id(&conversation_id)
            {
                Some(request_id) if task_cancel.is_none() => {
                    crate::tool_prompt::PromptOwner::Run(request_id)
                }
                _ => crate::tool_prompt::PromptOwner::Task,
            };
            ask_announced_prompt(
                &approval_state,
                &conversation_id,
                owner,
                mandatory,
                risk,
                &cancellations,
                card,
            )
            .map(|answer| answer.decision.allows())
        },
    )
}

/// The stream mirror of a card. `ModelStreamEvent::ToolApprovalRequested`
/// repeats `PendingToolPrompt` field for field, so building it anywhere but
/// here invites the two shapes to drift.
fn approval_requested_event(prompt: &crate::tool_prompt::PendingToolPrompt) -> ModelStreamEvent {
    ModelStreamEvent::ToolApprovalRequested {
        prompt_id: prompt.prompt_id.clone(),
        tool_name: prompt.tool_name.clone(),
        kind: prompt.kind,
        label: prompt.label.clone(),
        summary: prompt.summary.clone(),
        risk_level: prompt.risk_level.clone(),
        reason: prompt.reason.clone(),
        requester: prompt.requester.clone(),
        source_agent: prompt.source_agent.clone(),
        source_call_id: prompt.source_call_id.clone(),
        allow_always_offered: prompt.allow_always_offered,
        mandatory: prompt.mandatory,
        questions: prompt.questions.clone(),
    }
}

/// The language approval cards are worded in: the app's, as the renderer last
/// resolved it. Not the prompt profile's, which is the model's language and can
/// differ from the UI's. Read as each card is raised, so a switch mid-run
/// applies to the next card.
pub(crate) fn approval_card_language(
    state: &AppState,
    app_data_path: &str,
) -> crate::model::ResolvedLanguage {
    state
        .document_store
        .current_snapshot(&Path::new(app_data_path).join("document.v1.json"))
        .map(|document| document.global_settings.resolved_app_language)
        .unwrap_or_default()
}

/// Raises one approval card, blocks until it is answered, and takes it down
/// again whichever way it ended.
///
/// The card is announced on the live run stream when one is open and on the
/// push channel otherwise; the resolution follows the same rule, because a card
/// the renderer drew from one channel is only retracted by that channel. The
/// retraction covers every ending the renderer did not itself produce —
/// cancelled run, stopped task, timeout — and is skipped entirely when a
/// standing allowance answered without a card ever being shown.
pub(crate) fn ask_announced_prompt(
    state: &AppState,
    conversation_id: &str,
    owner: crate::tool_prompt::PromptOwner,
    mandatory: bool,
    risk: security::RiskLevel,
    cancellations: &[&std::sync::atomic::AtomicBool],
    card: crate::tool_prompt::PendingToolPrompt,
) -> Result<crate::tool_prompt::PromptAnswer, String> {
    // The prompt id is minted inside `ask_answer`, but the retraction event has
    // to name it, so `announce` hands it back out.
    let mut announced_prompt_id = None;
    let answer = state.tool_prompts().ask_answer(
        conversation_id,
        owner,
        mandatory,
        risk,
        cancellations,
        card,
        |prompt| {
            announced_prompt_id = Some(prompt.prompt_id.clone());
            let published = state
                .run_streams()
                .publish_live(conversation_id, approval_requested_event(prompt));
            if !published {
                state.push_events.publish(
                    crate::push_events::AppPushEvent::ToolApprovalRequested {
                        conversation_id: conversation_id.to_owned(),
                        prompt: prompt.clone(),
                    },
                );
            }
            Ok(())
        },
    );
    if let Some(prompt_id) = announced_prompt_id {
        let granted = answer
            .as_ref()
            .map(|answer| answer.decision.allows())
            .unwrap_or(false);
        let published = state.run_streams().publish_live(
            conversation_id,
            ModelStreamEvent::ToolApprovalResolved {
                prompt_id: prompt_id.clone(),
                approved: granted,
            },
        );
        if !published {
            state
                .push_events
                .publish(crate::push_events::AppPushEvent::ToolApprovalResolved {
                    conversation_id: conversation_id.to_owned(),
                    prompt_id,
                    approved: granted,
                });
        }
    }
    answer
}

/// Terminal outcome of the retrying request wrapper: the final failure plus
/// how many attempts ran and the best partial across all of them.
#[derive(Debug)]
struct ExhaustedRequest {
    error: ModelRequestError,
    attempts: u32,
    partial: StreamPartial,
}

/// The three renderer-facing credential commands, as far as the refusal rule
/// below needs to tell them apart.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ApiKeyCommand {
    Save,
    Reveal,
    Delete,
}

/// Whether a provider row's credential slot is the user's to manage.
///
/// Two families own their slot for reasons the renderer cannot see. Codex stores
/// the encryption key for its OAuth token there, so writing, reading, or deleting
/// it separately would corrupt or strand the token file. Claude Agent has no
/// credential at all — the CLI uses the user's own login — so a key entered here
/// would silently do nothing while looking like configuration that works.
///
/// The check reads the persisted family, never the renderer's copy of the row.
pub fn refuse_api_key_command(
    family: ProviderFamily,
    command: ApiKeyCommand,
) -> Result<(), String> {
    match (family, command) {
        (ProviderFamily::OpenaiCodex, ApiKeyCommand::Save) => {
            Err("OpenAI Codex 通过 ChatGPT 登录获取凭据，不接受手动填写的 API Key".into())
        }
        (ProviderFamily::OpenaiCodex, ApiKeyCommand::Reveal) => {
            Err("OpenAI Codex 的登录凭据不可查看".into())
        }
        (ProviderFamily::OpenaiCodex, ApiKeyCommand::Delete) => {
            Err("OpenAI Codex 的登录状态请通过「退出登录」清除".into())
        }
        (ProviderFamily::ClaudeAgent, _) => {
            Err("该提供商使用本机 Claude Code 的登录，不使用 API Key".into())
        }
        _ => Ok(()),
    }
}

pub fn save_api_key(provider_id: &str, api_key: &str) -> Result<ApiKeyStatus, String> {
    validate_provider_id(provider_id)?;
    let api_key = api_key.trim();
    if api_key.is_empty() {
        return Err("API Key 不能为空".into());
    }
    if api_key.len() > 16 * 1024 {
        return Err("API Key 超过长度限制".into());
    }
    let _guard = credential_guard();
    let revision = Uuid::new_v4().to_string();
    let identity = credential_identity(provider_id, &revision)?;
    let previous = read_bound_identity(provider_id)?;

    credential_entry(&identity)?
        .set_password(api_key)
        .map_err(|error| credential_store_error("无法将 API Key 保存到操作系统凭据库", error))?;
    if let Err(error) = bind_identity(provider_id, &identity) {
        // The old binding remains authoritative until this write succeeds. A
        // failed save may leave no reachable new secret or revision.
        let _ = delete_identity(&identity);
        return Err(error);
    }
    if let Some(previous) = previous.filter(|previous| previous != &identity) {
        // The new binding is already authoritative. Failure to clean an unreachable old
        // credential must not roll back or accidentally reactivate it.
        let _ = delete_identity(&previous);
    }
    Ok(ApiKeyStatus {
        configured: true,
        key_length: Some(api_key.chars().count()),
    })
}

/// Drops a provider's API key. Also the cleanup path for a provider row that
/// was removed from the document: the binding entry name is a hash, so it can
/// be recomputed from the provider id but never listed, and a provider id that
/// is already gone from the document is unreachable — dropping the row and its
/// credential has to happen in that order, never the reverse.
pub fn delete_api_key(provider_id: &str) -> Result<ApiKeyStatus, String> {
    validate_provider_id(provider_id)?;
    let _guard = credential_guard();
    if let BindingRead::Valid(identity) = read_binding(provider_id)? {
        delete_identity(&identity)?;
    }
    delete_entry(index_entry(provider_id)?, "API Key 绑定信息")?;
    Ok(ApiKeyStatus {
        configured: false,
        key_length: None,
    })
}

pub fn api_key_status(provider_id: &str) -> Result<ApiKeyStatus, String> {
    validate_provider_id(provider_id)?;
    let _guard = credential_guard();
    let key = read_api_key_locked(provider_id)?;
    Ok(ApiKeyStatus {
        configured: key.is_some(),
        key_length: key.as_deref().map(|secret| secret.chars().count()),
    })
}

pub fn reveal_api_key(provider_id: &str) -> Result<String, String> {
    validate_provider_id(provider_id)?;
    let _guard = credential_guard();
    read_api_key_locked(provider_id)?.ok_or_else(|| "API Key 未配置".to_owned())
}

fn credential_entry(identity: &str) -> Result<keyring::Entry, String> {
    if !is_credential_identity(identity) {
        return Err("API Key 凭据身份无效".into());
    }
    keyring::Entry::new(KEYRING_SERVICE, identity).map_err(|_| "无法访问操作系统凭据库".to_owned())
}

fn read_api_key_locked(provider_id: &str) -> Result<Option<String>, String> {
    // The binding is authoritative. Its credential identity may have been minted
    // for an older endpoint; following the binding keeps the secret when Base
    // URL/API format changes while preserving the write-bind-cleanup sequence.
    let Some(identity) = read_bound_identity(provider_id)? else {
        return Ok(None);
    };
    match credential_entry(&identity)?.get_password() {
        Ok(password) if password.trim().is_empty() => Ok(None),
        Ok(password) => Ok(Some(password)),
        Err(keyring::Error::NoEntry) => Ok(None),
        Err(error) => Err(credential_store_error(
            "无法读取操作系统凭据库中的 API Key",
            error,
        )),
    }
}

fn index_entry(provider_id: &str) -> Result<keyring::Entry, String> {
    validate_provider_id(provider_id)?;
    let digest = sha256_hex(provider_id.trim().as_bytes());
    keyring::Entry::new(
        KEYRING_SERVICE,
        &format!("binding:{CREDENTIAL_VERSION}:{digest}"),
    )
    .map_err(|_| "无法访问操作系统凭据库".to_owned())
}

fn credential_identity(provider_id: &str, revision: &str) -> Result<String, String> {
    validate_provider_id(provider_id)?;
    validate_random_credential_revision(revision)?;
    let material = format!("{CREDENTIAL_VERSION}\0{}", provider_id.trim());
    Ok(format!(
        "api-key:{CREDENTIAL_VERSION}:{}:{revision}",
        sha256_hex(material.as_bytes()),
    ))
}

pub(crate) fn sha256_hex(value: &[u8]) -> String {
    Sha256::digest(value)
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

fn is_credential_identity(identity: &str) -> bool {
    let Some(rest) = identity.strip_prefix(&format!("api-key:{CREDENTIAL_VERSION}:")) else {
        return false;
    };
    let Some((digest, revision)) = rest.split_once(':') else {
        return false;
    };
    digest.len() == 64
        && digest.bytes().all(|byte| byte.is_ascii_hexdigit())
        && validate_random_credential_revision(revision).is_ok()
}

fn validate_random_credential_revision(revision: &str) -> Result<(), String> {
    let parsed = Uuid::parse_str(revision).map_err(|_| "API Key 凭据修订标识无效".to_owned())?;
    if parsed.get_version() != Some(Version::Random) || parsed.to_string() != revision {
        return Err("API Key 凭据修订标识无效".into());
    }
    Ok(())
}

#[derive(Debug)]
enum BindingRead {
    Missing,
    Valid(String),
    Malformed,
}

fn read_binding(provider_id: &str) -> Result<BindingRead, String> {
    match index_entry(provider_id)?.get_password() {
        Ok(identity) if is_credential_identity(&identity) => Ok(BindingRead::Valid(identity)),
        Ok(_) => Ok(BindingRead::Malformed),
        Err(keyring::Error::NoEntry) => Ok(BindingRead::Missing),
        Err(error) => Err(credential_store_error(
            "无法读取操作系统凭据库中的 API Key 绑定信息",
            error,
        )),
    }
}

fn read_bound_identity(provider_id: &str) -> Result<Option<String>, String> {
    match read_binding(provider_id)? {
        BindingRead::Valid(identity) => Ok(Some(identity)),
        BindingRead::Malformed => Err("操作系统凭据库中的 API Key 绑定信息无效".into()),
        BindingRead::Missing => Ok(None),
    }
}

fn bind_identity(provider_id: &str, identity: &str) -> Result<(), String> {
    index_entry(provider_id)?
        .set_password(identity)
        .map_err(|error| credential_store_error("无法在操作系统凭据库中绑定 API Key 端点", error))
}

fn delete_identity(identity: &str) -> Result<(), String> {
    delete_entry(credential_entry(identity)?, "API Key")
}

/// Credential critical-section guard.
///
/// The Windows credential store service `com.mework.api` is shared by every
/// Mework identifier (production and browser-dev alike), so the in-process
/// `PROVIDER_CREDENTIAL_LOCK` cannot stop another process from interleaving a
/// "write new secret → rebind → delete old secret" sequence. The guard
/// therefore also holds a cross-process file lock under `~/.mework`. If that
/// lock cannot be established (no home dir, filesystem refusal) the guard
/// degrades to in-process mutual exclusion — the pre-existing behavior —
/// instead of blocking all credential operations.
struct CredentialGuard {
    _process: std::sync::MutexGuard<'static, ()>,
    _cross_process: Option<std::fs::File>,
}

fn acquire_credential_file_lock() -> Option<std::fs::File> {
    // Tests replace the keyring with an in-memory store; a cross-process lock
    // would only write lock files into the developer's real home directory.
    if cfg!(test) {
        return None;
    }
    let directory = dirs::home_dir()?.join(".mework");
    std::fs::create_dir_all(&directory).ok()?;
    let path = directory.join(".keyring.lock");
    match std::fs::symlink_metadata(&path) {
        Ok(metadata) if metadata.file_type().is_symlink() || !metadata.is_file() => return None,
        _ => {}
    }
    let mut options = std::fs::OpenOptions::new();
    options.read(true).write(true).create(true);
    #[cfg(windows)]
    {
        use std::os::windows::fs::OpenOptionsExt;
        use windows_sys::Win32::Storage::FileSystem::{
            FILE_FLAG_OPEN_REPARSE_POINT, FILE_SHARE_READ, FILE_SHARE_WRITE,
        };
        options
            .share_mode(FILE_SHARE_READ | FILE_SHARE_WRITE)
            .custom_flags(FILE_FLAG_OPEN_REPARSE_POINT);
    }
    let file = options.open(&path).ok()?;
    let metadata = file.metadata().ok()?;
    if metadata.file_type().is_symlink() || !metadata.is_file() {
        return None;
    }
    fs2::FileExt::lock_exclusive(&file).ok()?;
    Some(file)
}

fn credential_guard() -> CredentialGuard {
    #[cfg(test)]
    install_test_credential_builder();
    let process = PROVIDER_CREDENTIAL_LOCK
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    // Acquired while already holding the process mutex, so two threads of this
    // process never contend on the file lock against each other.
    let cross_process = acquire_credential_file_lock();
    CredentialGuard {
        _process: process,
        _cross_process: cross_process,
    }
}

#[cfg(test)]
type TestCredentialSecrets = Arc<Mutex<HashMap<(String, String), Vec<u8>>>>;

#[cfg(test)]
#[derive(Debug)]
struct TestCredential {
    service: String,
    user: String,
    secrets: TestCredentialSecrets,
}

#[cfg(test)]
impl keyring::credential::CredentialApi for TestCredential {
    fn set_secret(&self, secret: &[u8]) -> keyring::Result<()> {
        self.secrets
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .insert((self.service.clone(), self.user.clone()), secret.to_vec());
        Ok(())
    }

    fn get_secret(&self) -> keyring::Result<Vec<u8>> {
        self.secrets
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .get(&(self.service.clone(), self.user.clone()))
            .cloned()
            .ok_or(keyring::Error::NoEntry)
    }

    fn delete_credential(&self) -> keyring::Result<()> {
        self.secrets
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .remove(&(self.service.clone(), self.user.clone()))
            .map(|_| ())
            .ok_or(keyring::Error::NoEntry)
    }

    fn as_any(&self) -> &dyn std::any::Any {
        self
    }
}

#[cfg(test)]
#[derive(Debug)]
struct TestCredentialBuilder {
    secrets: TestCredentialSecrets,
}

#[cfg(test)]
impl keyring::credential::CredentialBuilderApi for TestCredentialBuilder {
    fn build(
        &self,
        _target: Option<&str>,
        service: &str,
        user: &str,
    ) -> keyring::Result<Box<keyring::credential::Credential>> {
        Ok(Box::new(TestCredential {
            service: service.into(),
            user: user.into(),
            secrets: Arc::clone(&self.secrets),
        }))
    }

    fn as_any(&self) -> &dyn std::any::Any {
        self
    }

    fn persistence(&self) -> keyring::credential::CredentialPersistence {
        keyring::credential::CredentialPersistence::ProcessOnly
    }
}

#[cfg(test)]
fn install_test_credential_builder() {
    static INIT: std::sync::Once = std::sync::Once::new();
    static SECRETS: OnceLock<TestCredentialSecrets> = OnceLock::new();
    INIT.call_once(|| {
        let secrets = SECRETS
            .get_or_init(|| Arc::new(Mutex::new(HashMap::new())))
            .clone();
        keyring::set_default_credential_builder(Box::new(TestCredentialBuilder { secrets }));
    });
}

fn delete_entry(entry: keyring::Entry, label: &str) -> Result<(), String> {
    match entry.delete_credential() {
        Ok(()) | Err(keyring::Error::NoEntry) => Ok(()),
        Err(error) => Err(credential_store_error(
            &format!("无法从操作系统凭据库删除{label}"),
            error,
        )),
    }
}

/// A credential-store failure as the user reads it. Only `NoStorageAccess`
/// keeps its reason: on macOS that is the keychain dialog being refused, and
/// the reason says how to get it back. Every other variant stays generic —
/// `BadEncoding` in particular carries the stored secret's own bytes.
fn credential_store_error(message: &str, error: keyring::Error) -> String {
    match error {
        keyring::Error::NoStorageAccess(reason) => format!("{message}：{reason}"),
        _ => message.to_owned(),
    }
}

/// Called before an action the user started that cannot work without a
/// credential. On macOS a keychain dialog the user refused earlier in this
/// process is then shown again; reads that only render status never call this,
/// so a refusal is not answered with another dialog.
pub(crate) fn allow_credential_prompt() {
    #[cfg(target_os = "macos")]
    crate::credential_vault::retry_after_refusal();
}

fn validate_provider_id(provider_id: &str) -> Result<(), String> {
    if provider_id.trim().is_empty() {
        return Err("提供商 ID 不能为空".into());
    }
    if provider_id.chars().count() > 256 || provider_id.chars().any(char::is_control) {
        return Err("提供商 ID 无效".into());
    }
    Ok(())
}

pub fn validate_provider(provider: &ApiProvider) -> Result<(), String> {
    validate_provider_id(&provider.id)?;
    if provider.name.trim().is_empty() {
        return Err(format!("提供商 {} 的名称为空", provider.id));
    }
    // The Claude Agent family has no address: `provider_base_url` ignores the
    // field entirely, so validating a leftover string would only brick profiles
    // written before the field was dropped.
    if provider.family == ProviderFamily::ClaudeAgent {
        return Ok(());
    }
    if provider.base_url.trim().is_empty() && provider.family.derives_base_url() {
        // Vertex and Bedrock derive endpoints from identity fields. An empty base
        // URL means use the provider default, while those identity fields remain required.
        return Ok(());
    }
    validate_base_url(&provider.base_url)
}

/// Maximum host-paid continuations when Anthropic search pauses a turn.
/// The sidecar performs continuation; the host supplies `maxSteps` because the
/// cost budget is host policy.
pub(crate) const MAX_ANTHROPIC_PAUSE_CONTINUATIONS: usize = 5;

/// Whether a base URL satisfies host safety rules: HTTPS, no credentials or
/// query string, and HTTP only on loopback. Shared by provider and preset URLs.
pub fn validate_base_url(base_url: &str) -> Result<(), String> {
    normalized_base_url(base_url).map(|_| ())
}

pub(crate) fn provider_key(provider: &ApiProvider, url: &Url) -> Result<Option<String>, String> {
    let key = match provider_api_key(provider) {
        Ok(key) => key,
        // A local-network model server is the normal unauthenticated case: Ollama
        // and LM Studio ship with no key at all, whether they run on this machine
        // or on another one in the house.
        Err(_) if is_local_network_url(url) => None,
        Err(error) => return Err(error),
    };
    if key.is_none() && !is_local_network_url(url) {
        return Err(format!("提供商 {} 尚未配置 API Key", provider.name));
    }
    Ok(key)
}

/// Credential for model discovery. Its absence is valid: unauthenticated local
/// and public catalogs must be allowed to answer the GET without `Authorization`.
pub(crate) fn optional_provider_key(provider: &ApiProvider) -> Option<String> {
    provider_api_key(provider).ok().flatten()
}

/// The provider's API key, or `None` when it has none at all — the caller
/// decides whether that is fatal (remote host) or fine (loopback).
fn provider_api_key(provider: &ApiProvider) -> Result<Option<String>, String> {
    validate_provider_id(&provider.id)?;
    let _guard = credential_guard();
    read_api_key_locked(&provider.id)
}

/// Reads the API key and its opaque revision under one credential-store lock.
///
/// Existing v1/v2/v3 credentials are lazily rebound to a fresh v4 identity
/// before this returns. The revision is random, non-secret, and unrelated to

/// Authentication header for model-discovery GET requests. The model-discovery
/// strategy chooses the header shape per provider family.
pub(crate) fn authenticated_request(
    builder: RequestBuilder,
    family: ProviderFamily,
    key: Option<&str>,
) -> RequestBuilder {
    // Some relays sit behind gateways that content-negotiate on `Accept` and
    // answer an HTML console page to the `*/*` reqwest sends by default.
    let builder = builder.header("accept", "application/json");
    match family {
        // Codex carries an OAuth access token, which the backend reads as a
        // plain Bearer credential; its account header is added by the caller.
        ProviderFamily::OpenaiResponses
        | ProviderFamily::OpenaiCodex
        | ProviderFamily::OpenaiChat
        | ProviderFamily::OpenaiCompatible
        | ProviderFamily::Xai
        | ProviderFamily::Bedrock => match key {
            Some(key) => builder.bearer_auth(key),
            None => builder,
        },
        ProviderFamily::Anthropic => {
            let builder = builder.header("anthropic-version", "2023-06-01");
            match key {
                Some(key) => builder.header("x-api-key", key),
                None => builder,
            }
        }
        // The agent family never issues a host HTTP request: its model list is a
        // built-in registry and its credential lives in the CLI. Keep the Messages
        // shape for the exhaustive match so a future caller gets the right header.
        ProviderFamily::ClaudeAgent => {
            let builder = builder.header("anthropic-version", "2023-06-01");
            match key {
                Some(key) => builder.header("x-api-key", key),
                None => builder,
            }
        }
        // Google uses its own header; a Bearer header produces an unrelated error.
        ProviderFamily::Google | ProviderFamily::Vertex => match key {
            Some(key) => builder.header("x-goog-api-key", key),
            None => builder,
        },
        // Azure OpenAI uses `api-key`, not `Authorization`.
        ProviderFamily::Azure => match key {
            Some(key) => builder.header("api-key", key),
            None => builder,
        },
    }
}

/// Validated provider conversation base URL. `None` means use a provider-derived
/// default, which is permitted only for Vertex and Bedrock. The Codex family has
/// a host-known default instead, so an empty address resolves to it here: the
/// host stays the single authority for where a request goes.
///
/// A Codex address may only be overridden with a loopback or local-network host.
/// The credential attached to these requests is the user's ChatGPT session, which
/// is only meaningful at OpenAI; the sole legitimate reason to point it elsewhere
/// is a test double on this machine. Accepting an arbitrary HTTPS host would let
/// a Base URL edit hand that session to a third party.
///
/// The Claude Agent family has no address of its own: the CLI talks to whatever
/// its own login points at. A string left in the row by an older version is
/// ignored rather than rejected, so those profiles keep working.
pub(crate) fn provider_base_url(provider: &ApiProvider) -> Result<Option<Url>, String> {
    if provider.family == ProviderFamily::ClaudeAgent {
        return Ok(None);
    }
    if provider.family == ProviderFamily::OpenaiCodex {
        if provider.base_url.trim().is_empty() {
            return normalized_base_url(crate::codex_oauth::CODEX_DEFAULT_BASE_URL).map(Some);
        }
        let url = normalized_base_url(&provider.base_url)?;
        if !is_local_network_url(&url) {
            return Err(
                "OpenAI Codex 的 API 地址只能留空（使用 ChatGPT 后端）或指向本机测试桩".into(),
            );
        }
        return Ok(Some(url));
    }
    if provider.base_url.trim().is_empty() && provider.family.derives_base_url() {
        return Ok(None);
    }
    normalized_base_url(&provider.base_url).map(Some)
}

/// Credential resolved once at run start.
///
/// Key-based families read the stored API key (local-network hosts may have
/// none). The Codex family reads its OAuth session instead, which also acts as
/// the "signed in" gate: a run without a session fails here, before any ledger
/// or wire history is touched, with the same shape of error as a missing key.
///
/// The Claude Agent family has no credential of its own: the CLI authenticates
/// with the user's own local login. The credential store is not consulted at
/// all, so a key left behind by an older version cannot leak into a request.
pub(crate) fn initial_provider_key(
    provider: &ApiProvider,
    base_url: &Option<Url>,
) -> Result<Option<String>, String> {
    // A run is the user asking for the credential, so a refused keychain
    // dialog is worth raising again here.
    allow_credential_prompt();
    if provider.family == ProviderFamily::OpenaiCodex {
        let credentials = crate::codex_oauth::host().credentials(&provider.id)?;
        return Ok(Some(credentials.access_token.to_string()));
    }
    if provider.family == ProviderFamily::ClaudeAgent {
        return Ok(None);
    }
    match base_url {
        Some(url) => provider_key(provider, url),
        // Vertex and Bedrock have no loopback-classifiable URL, so treat them as
        // remote and reject missing credentials before dispatch.
        None => Ok(Some(provider_api_key(provider)?.ok_or_else(|| {
            format!("提供商 {} 尚未配置 API Key", provider.name)
        })?)),
    }
}

/// Upstream credential for one sidecar request.
pub(crate) struct StepCredential {
    pub(crate) api_key: Option<String>,
    pub(crate) headers: std::collections::BTreeMap<String, String>,
}

/// Resolve the credential for one request. Key-based families reuse the key
/// from run start. The Codex family re-reads its OAuth session every step: a
/// token that is about to expire is refreshed here rather than failing
/// upstream, and a refresh that landed mid-run reaches the next request.
pub(crate) fn step_credential(
    provider: &ApiProvider,
    key: &Option<String>,
) -> Result<StepCredential, String> {
    if provider.family == ProviderFamily::OpenaiCodex {
        let credentials = crate::codex_oauth::host().credentials(&provider.id)?;
        return Ok(StepCredential {
            api_key: Some(credentials.access_token.to_string()),
            headers: crate::codex_oauth::request_headers(&credentials),
        });
    }
    Ok(StepCredential {
        api_key: key.clone(),
        headers: std::collections::BTreeMap::new(),
    })
}

/// Fetches models using the provider-specific strategy in `model_discovery`.
/// A generic `{base}/models` request is incomplete for several providers.
pub fn fetch_models(provider: &ApiProvider) -> Result<Vec<ModelProfile>, String> {
    allow_credential_prompt();
    crate::model_discovery::fetch_models(provider)
}

pub(crate) fn parse_http_json(response: Response, key: Option<&str>) -> Result<Value, String> {
    let status = response.status();
    let url = response.url().to_string();
    if !status.is_success() {
        let (body, _) = read_body(response, MAX_ERROR_BODY)?;
        let message = api_error_message(status, &body);
        return Err(sanitize_error(
            &format!("{message}{}", status_hint(status, &url)),
            key,
        ));
    }
    let (body, overflowed) = read_body(response, MAX_SUCCESS_BODY)?;
    if overflowed {
        return Err(format!(
            "API 响应超过 {} MiB 限制",
            MAX_SUCCESS_BODY / 1024 / 1024
        ));
    }
    serde_json::from_slice(&body).map_err(|error| {
        // A relay that answers HTML here is almost always a wrong Base URL or a
        // gateway interception page, so name both instead of only the parser error.
        sanitize_error(
            &format!("{url} 返回的不是 JSON（{error}）。请检查 Base URL 是否指向 API 根地址，以及该地址是否被网关拦截。"),
            key,
        )
    })
}

/// Actionable hint for the status codes a misconfigured relay produces. Empty
/// for everything else, so ordinary upstream errors keep their own wording.
fn status_hint(status: StatusCode, url: &str) -> String {
    if status.is_redirection() {
        return format!("。{url} 要求跳转到其他站点，出于安全考虑不会带着 API Key 跨站跳转；请直接填写跳转后的地址。");
    }
    match status {
        StatusCode::UNAUTHORIZED | StatusCode::FORBIDDEN => {
            "。请检查 API Key，以及该中转站要求的鉴权方式。".into()
        }
        StatusCode::NOT_FOUND => {
            format!("。{url} 不存在，Base URL 多半漏了 /v1 之类的前缀或多写了一段路径。")
        }
        _ => String::new(),
    }
}

fn sync_generated_contexts(
    request: &mut RunModelRequest,
    generated: &[ContextItem],
    checkpoint: &mut usize,
) {
    let mut known_ids = request
        .contexts
        .iter()
        .map(|context| context.id().to_owned())
        .collect::<HashSet<_>>();
    for context in &generated[*checkpoint..] {
        if known_ids.insert(context.id().to_owned()) {
            request.contexts.push(context.clone());
        }
    }
    *checkpoint = generated.len();
}

struct ProjectMemoryRunState {
    options: project_memory::ProjectMemoryOptions,
    report: project_memory::ProjectMemoryReport,
    loaded_paths: BTreeSet<PathBuf>,
    diagnostic_checkpoint: usize,
    /// Opaque backend-only revision of the encrypted external-import trust
    /// ledger. Runs without external imports do not need a lease.
    trust_lease: Option<crate::project_import_trust::ProjectImportTrustLease>,
}

impl ProjectMemoryRunState {
    fn discover(
        request: &mut RunModelRequest,
        instructions_loaded: Option<&InstructionsLoadedRunDispatcher>,
    ) -> Result<Option<Self>, String> {
        // Ordinary named subagents get the same project/user instruction
        // hierarchy as the main run (their model-owned auto memory remains
        // separate and is not inherited). The web-search executor is an
        // ordinary subagent for this purpose too: its searching happens inside
        // one upstream request and it never spawns a child of its own.
        let workspace = Path::new(&request.workspace_path);
        if !workspace.is_dir() {
            return Ok(None);
        }
        let mut options = project_memory::ProjectMemoryOptions::new(workspace);
        crate::memory_locations::MemoryLocationRoots::for_host()
            .apply_to_project_memory_options(&mut options);
        let app_data = Path::new(&request.app_data_path);
        if workspace.starts_with(app_data) {
            options.ancestor_floor = Some(workspace.to_path_buf());
        }
        let untrusted_report = project_memory::discover_project_memory(&options);
        let requires_external_trust = untrusted_report.diagnostics.iter().any(|diagnostic| {
            diagnostic.kind == project_memory::ProjectMemoryDiagnosticKind::ImportRequiresTrust
        });
        let (report, trust_lease) = if requires_external_trust {
            let trust_store =
                crate::project_import_trust::EncryptedProjectImportTrustStore::open(app_data);
            let lease = crate::project_import_trust::acquire_project_import_trust_lease(
                &trust_store,
                &request.workspace_id,
                workspace,
            )?;
            options.trusted_import_paths =
                crate::project_import_trust::trusted_paths_for_workspace(
                    &trust_store,
                    &request.workspace_id,
                    workspace,
                )?;
            if !crate::project_import_trust::project_import_trust_lease_is_current(
                &trust_store,
                &lease,
                &request.workspace_id,
                workspace,
            )? {
                return Err(
                    "Project-memory external-import trust changed during the startup snapshot; no model request was made for this turn. Please retry.".into(),
                );
            }
            (
                project_memory::discover_project_memory(&options),
                Some(lease),
            )
        } else {
            (untrusted_report, None)
        };

        // The async native approval preflight is intentionally repeated here:
        // it may have waited for user input while another settings window
        // revoked trust. Rebuild the startup block from the exact report bound
        // to the lease that every provider attempt below will revalidate.
        if let Some(context_id) = request.project_memory_context_id.take() {
            request
                .ephemeral_contexts
                .retain(|context| context.id() != context_id);
        }
        let startup_sources = project_memory::startup_sources(&report);
        let startup_prompt =
            project_memory::render_project_memory_prompt(&startup_sources, &request.prompt_profile);
        if !startup_prompt.is_empty() {
            let context_id = new_context_id("project-memory");
            request.ephemeral_contexts.push(ContextItem::User {
                id: context_id.clone(),
                content: startup_prompt,
                images: Vec::new(),
                files: Vec::new(),
                created_at: Utc::now().to_rfc3339(),
            });
            request.project_memory_context_id = Some(context_id);
        }
        if let Some(instructions_loaded) = instructions_loaded {
            let manifested =
                hooks::instructions_loaded::manifested_instruction_loads(&startup_sources, None)?;
            instructions_loaded.dispatch_manifested(&manifested);
        }
        let loaded_paths = startup_sources
            .into_iter()
            .map(|source| source.path.clone())
            .collect();
        let diagnostic_checkpoint = report.diagnostics.len();
        Ok(Some(Self {
            options,
            report,
            loaded_paths,
            diagnostic_checkpoint,
            trust_lease,
        }))
    }

    fn validate_external_import_trust(&self, request: &RunModelRequest) -> Result<(), String> {
        let Some(lease) = self.trust_lease.as_ref() else {
            return Ok(());
        };
        let workspace = Path::new(&request.workspace_path);
        let trust_store = crate::project_import_trust::EncryptedProjectImportTrustStore::open(
            Path::new(&request.app_data_path),
        );
        if crate::project_import_trust::project_import_trust_lease_is_current(
            &trust_store,
            lease,
            &request.workspace_id,
            workspace,
        )? {
            Ok(())
        } else {
            Err("Project-memory external-import trust changed; the stale run was stopped and cached project memory was not sent.".into())
        }
    }

    fn load_for_read(
        &mut self,
        request: &mut RunModelRequest,
        call: &ToolCall,
        result: &ToolResult,
        opened_file: Option<&tool_executor::VerifiedOpenedFile>,
        instructions_loaded: Option<&InstructionsLoadedRunDispatcher>,
    ) -> Result<(), String> {
        if call.name != "read" || !result.success {
            return Ok(());
        }
        let Some(opened_file) = opened_file else {
            return Ok(());
        };
        self.validate_external_import_trust(request)?;
        let Some(opened_identity) = project_memory::discover_nested_project_memory_for_read(
            &self.options,
            &mut self.report,
            opened_file,
        ) else {
            self.record_new_diagnostics()?;
            return Ok(());
        };
        let sources = project_memory::sources_for_read_path(
            &self.report,
            &opened_identity,
            &self.loaded_paths,
        );
        if sources.is_empty() {
            self.record_new_diagnostics()?;
            return Ok(());
        }
        let prompt =
            project_memory::render_project_memory_prompt(&sources, &request.prompt_profile);
        // A revoke can commit while the bounded, handle-verified files are
        // being read. Discard that local result unless the same lease is still
        // current; the next provider attempt performs a third check.
        self.validate_external_import_trust(request)?;
        for source in &sources {
            self.loaded_paths.insert(source.path.clone());
        }
        if prompt.is_empty() {
            self.record_new_diagnostics()?;
            return Ok(());
        }
        request.ephemeral_contexts.push(ContextItem::User {
            id: new_context_id("project-memory"),
            content: prompt,
            images: Vec::new(),
            files: Vec::new(),
            created_at: Utc::now().to_rfc3339(),
        });
        if let Some(instructions_loaded) = instructions_loaded {
            let manifested = hooks::instructions_loaded::manifested_instruction_loads(
                &sources,
                Some(&opened_identity),
            )?;
            instructions_loaded.dispatch_manifested(&manifested);
        }
        Ok(())
    }

    /// Advance the diagnostic cursor. It must advance even without the retired
    /// persistent ledger, otherwise diagnostics are processed repeatedly.
    fn record_new_diagnostics(&mut self) -> Result<(), String> {
        self.report
            .diagnostics
            .get(self.diagnostic_checkpoint..)
            .ok_or_else(|| {
                "Project-instructions diagnostic cursor is beyond the current report.".to_owned()
            })?;
        self.diagnostic_checkpoint = self.report.diagnostics.len();
        Ok(())
    }
}

fn host_memory_prompt_content(request: &RunModelRequest) -> Result<Option<&str>, String> {
    let Some(expected_id) = request.memory_context_id.as_deref() else {
        return Ok(None);
    };
    let matches = request
        .ephemeral_contexts
        .iter()
        .filter(|context| context.id() == expected_id)
        .collect::<Vec<_>>();
    let [ContextItem::User { content, .. }] = matches.as_slice() else {
        return Err(
            "The host context ID for the persistent-memory prompt is missing, duplicated, or no longer identifies a user context; sending was refused.".into(),
        );
    };
    if content
        .matches(crate::mework_memory::MEMORY_CONTEXT_START)
        .count()
        != 1
        || content
            .matches(crate::mework_memory::MEMORY_CONTEXT_END)
            .count()
            != 1
        || content
            .strip_prefix(crate::mework_memory::MEMORY_CONTEXT_START)
            .and_then(|body| body.strip_suffix(crate::mework_memory::MEMORY_CONTEXT_END))
            .is_none()
    {
        return Err("Persistent-memory prompt block boundaries are missing, duplicated, or unpaired; sending was refused.".into());
    }
    Ok(Some(content))
}

/// Persistence sink for top-level conversation output.
/// The host is the sole writer: each canonical context is persisted on creation,
/// then checked at round boundaries. Child output belongs to its tool transcript,
/// not the parent timeline, and therefore receives `None`.
struct ConversationSink {
    store: std::sync::Arc<crate::conversation_store::ConversationStore>,
    conversation_id: String,
    request_id: String,
}

impl ConversationSink {
    fn for_request(request: &RunModelRequest) -> Option<Self> {
        if request.subagent_depth > 0 || request.app_data_path.is_empty() {
            return None;
        }
        let anchor = Path::new(&request.app_data_path).join("document.v1.json");
        match crate::conversation_store::store_for(&anchor) {
            Ok(store) => Some(Self {
                store,
                conversation_id: request.conversation_id.clone(),
                request_id: request.request_id.clone(),
            }),
            Err(error) => {
                eprintln!("对话库不可用，本次运行的正文无法随产出落盘：{error}");
                None
            }
        }
    }

    /// Whether the write reached the database. Failed writes must remain pending;
    /// recording their fingerprint would suppress all later retries.
    fn upsert(
        &self,
        items: &[ContextItem],
        status: crate::conversation_store::ContextStatus,
    ) -> bool {
        self.upsert_in_sequence(items, status, &[])
    }

    /// Like [`Self::upsert`], but places the rows named by `sequence` in that order; see
    /// [`crate::conversation_store::ConversationStore::upsert_contexts_in_sequence`].
    fn upsert_in_sequence(
        &self,
        items: &[ContextItem],
        status: crate::conversation_store::ContextStatus,
        sequence: &[&str],
    ) -> bool {
        if let Err(error) =
            self.store
                .upsert_contexts_in_sequence(&self.conversation_id, items, status, sequence)
        {
            eprintln!("对话 {} 的上下文落盘失败：{error}", self.conversation_id);
            return false;
        }
        true
    }

    /// Remove a steering message's durable queue row once it enters a round; the
    /// model has seen it and it must not be redelivered after restart.
    fn drop_queued(&self, id: &str) {
        if let Err(error) = self
            .store
            .remove_queued_messages(&self.conversation_id, std::slice::from_ref(&id.to_owned()))
        {
            eprintln!("对话 {} 的排队消息清理失败：{error}", self.conversation_id);
        }
    }

    /// Delete streaming rows that will never become canonical. Rows settlement
    /// has already claimed are left alone.
    fn discard_streaming(&self, ids: &[&str]) {
        if let Err(error) = self
            .store
            .discard_streaming_contexts(&self.conversation_id, ids)
        {
            eprintln!(
                "对话 {} 的未定稿正文丢弃失败：{error}",
                self.conversation_id
            );
        }
    }

    /// Mark streaming rows without an authoritative final context as interrupted.
    /// On normal completion the final context replaces every streaming row in place.
    fn finish(&self) {
        if let Err(error) = self.store.reconcile_streaming_in(&self.conversation_id) {
            eprintln!(
                "对话 {} 的未定稿正文回收失败：{error}",
                self.conversation_id
            );
        }
        // After reconciling, never before: history records the trunk as it settled,
        // and a row still marked streaming here is one this run abandoned.
        if let Err(error) = self.store.record_trunk_change(
            &self.conversation_id,
            crate::conversation_store::TrunkChange::Run,
            Some(&self.request_id),
        ) {
            eprintln!(
                "对话 {} 的时间线历史记录失败：{error}",
                self.conversation_id
            );
        }
    }
}

/// Recovery-only storage for a running child. Canonical child contexts stay
/// nested on the owning tool card; they are never parent timeline rows.
struct SubagentTranscriptSink {
    store: Arc<crate::conversation_store::ConversationStore>,
    conversation_id: String,
    state: AppState,
    shared: Arc<AgentShared>,
    incarnation: crate::agents::TaskIdentity,
    written: Option<(String, u64)>,
}

impl SubagentTranscriptSink {
    fn for_child(
        request: &RunModelRequest,
        state: &AppState,
        shared: Arc<AgentShared>,
        incarnation: crate::agents::TaskIdentity,
    ) -> Option<Self> {
        if request.subagent_depth == 0 || request.app_data_path.is_empty() {
            return None;
        }
        let anchor = Path::new(&request.app_data_path).join("document.v1.json");
        match crate::conversation_store::store_for(&anchor) {
            Ok(store) => Some(Self {
                store,
                conversation_id: request.conversation_id.clone(),
                state: state.clone(),
                shared,
                incarnation,
                written: None,
            }),
            Err(error) => {
                eprintln!("Subagent transcript store is unavailable: {error}");
                None
            }
        }
    }

    fn write(&mut self, live: &[ContextItem]) -> bool {
        use std::hash::{Hash, Hasher};
        let Self {
            store,
            conversation_id,
            state,
            shared,
            incarnation,
            written,
        } = self;
        shared.checkpoint_transcript(*incarnation, live, |owner, record| {
            let encoded = match serde_json::to_string(&record) {
                Ok(encoded) => encoded,
                Err(error) => {
                    eprintln!("Could not encode running subagent transcript: {error}");
                    return false;
                }
            };
            let mut hasher = std::collections::hash_map::DefaultHasher::new();
            encoded.hash(&mut hasher);
            let fingerprint = hasher.finish();
            // Ownership is part of confirmation: the same bytes written to
            // another card have not been written to this one.
            if written.as_ref().is_some_and(|(id, value)| id == owner && *value == fingerprint) {
                return true;
            }
            let persisted = store.update_task_cards_in_place(conversation_id, owner, &shared.name, |card| {
                let current_owner = card.id() == owner;
                let ContextItem::Tool { tool_name, subagent, .. } = card else { return false; };
                if current_owner {
                    if tool_name != "agent_spawn"
                        || subagent.as_ref().is_some_and(|previous| previous.name.as_deref() != Some(shared.name.as_str()))
                    {
                        return false;
                    }
                    *subagent = Some(record.clone());
                } else {
                    *subagent = None;
                }
                re_attest_tool_context(card, conversation_id, state);
                true
            });
            match persisted {
                Ok(true) => {
                    *written = Some((owner.to_owned(), fingerprint));
                    true
                }
                Ok(false) => false,
                Err(error) => {
                    eprintln!("Running subagent transcript checkpoint failed; it remains pending: {error}");
                    false
                }
            }
        }).unwrap_or(false)
    }
}

/// Canonical contexts produced by this run. `push` and `extend` persist each new item, while
/// `checkpoint` rewrites entries changed in place, such as record backfills.
///
/// Rows reach the store in the order the run produced them, not the order the writes happen
/// to arrive: the journal appends a round's streaming prose while the provider is still
/// talking, and the round's reasoning cards are only minted after it stops. Every write
/// therefore hands the store the run's own order, and the store files each new row behind its
/// predecessor in that order rather than at the end.
struct GeneratedContexts {
    journal: Option<Arc<ProseJournal>>,
    items: Vec<ContextItem>,
    sink: Option<ConversationSink>,
    /// The last context already on the timeline when the run began. The run's first
    /// item has no predecessor of its own, and without this it would be appended
    /// behind whatever streaming row the journal wrote first.
    predecessor: Option<String>,
    /// Maps each id to the fingerprint last successfully persisted.
    written: HashMap<String, u64>,
    /// Re-signed historical cards are updates, never new output. Keep failed
    /// writes dirty independently of the in-memory record equality check.
    historical_updates: HashMap<String, ContextItem>,
    transcript: Option<SubagentTranscriptSink>,
}

impl GeneratedContexts {
    fn new(sink: Option<ConversationSink>, predecessor: Option<String>) -> Self {
        Self {
            journal: None,
            items: Vec::new(),
            sink,
            predecessor,
            written: HashMap::new(),
            historical_updates: HashMap::new(),
            transcript: None,
        }
    }

    fn with_transcript(mut self, transcript: Option<SubagentTranscriptSink>) -> Self {
        self.transcript = transcript;
        self
    }

    fn track_card_updates(&mut self, updates: Vec<ContextItem>) {
        for item in updates {
            if !self
                .items
                .iter()
                .any(|generated| generated.id() == item.id())
            {
                self.historical_updates.insert(item.id().to_owned(), item);
            }
        }
    }

    fn push(&mut self, item: ContextItem) {
        self.items.push(item);
        self.write_from(self.items.len() - 1);
    }

    /// Persists a run of items like [`Self::push`] does for one. This shadows `Vec::extend`
    /// on purpose: reached through `DerefMut`, that would file the items without writing them.
    fn extend<I: IntoIterator<Item = ContextItem>>(&mut self, items: I) {
        let start = self.items.len();
        self.items.extend(items);
        if start < self.items.len() {
            self.write_from(start);
        }
    }

    /// Persist every item changed since the previous checkpoint. Returns whether
    /// all writes were confirmed, including the required persistence sink.
    fn checkpoint(&mut self) -> bool {
        let current_confirmed = if let Some(transcript) = self.transcript.as_mut() {
            // Only settled-round checkpoints write child recovery copies. In
            // particular, push/extend do not flush an in-progress model round.
            self.items.is_empty() || transcript.write(&self.items)
        } else {
            self.write_from(0)
        };
        if self.historical_updates.is_empty() {
            return current_confirmed;
        }
        let updates = self
            .historical_updates
            .values()
            .cloned()
            .collect::<Vec<_>>();
        if self.sink.as_ref().is_some_and(|sink| {
            sink.upsert(&updates, crate::conversation_store::ContextStatus::Settled)
        }) {
            self.historical_updates.clear();
            current_confirmed
        } else {
            false
        }
    }

    /// Writes every item from `start` onwards whose fingerprint changed since it was last
    /// persisted. Returns whether all pending writes were confirmed; no sink is unconfirmed,
    /// while no pending item is confirmed.
    fn write_from(&mut self, start: usize) -> bool {
        let journal = self.journal.clone();
        let frozen = journal.as_ref().map(|journal| {
            journal
                .gate
                .lock()
                .unwrap_or_else(|error| error.into_inner())
        });
        if frozen.as_ref().is_some_and(|frozen| **frozen) {
            return false;
        }
        let Some(sink) = self.sink.as_ref() else {
            return false;
        };
        let mut changed = Vec::new();
        let mut prints = Vec::new();
        let mut first_changed = None;
        for (index, item) in self.items.iter().enumerate().skip(start) {
            let print = context_fingerprint(item);
            if self.written.get(item.id()).copied() == Some(print) {
                continue;
            }
            first_changed.get_or_insert(index);
            prints.push((item.id().to_owned(), print));
            changed.push(item.clone());
        }
        let Some(first_changed) = first_changed else {
            return true;
        };
        // The item before the first change anchors where new rows go; everything
        // after it lets the store confirm the rest of the run is still in order.
        let mut sequence = Vec::with_capacity(self.items.len() - first_changed + 2);
        if first_changed == 0 {
            sequence.extend(self.predecessor.as_deref());
        }
        sequence.extend(
            self.items[first_changed.saturating_sub(1)..]
                .iter()
                .map(ContextItem::id),
        );
        // Record a fingerprint only after a successful write so failed batches
        // remain pending for the next checkpoint.
        if sink.upsert_in_sequence(
            &changed,
            crate::conversation_store::ContextStatus::Settled,
            &sequence,
        ) {
            if let Some(journal) = journal.as_ref() {
                journal
                    .state
                    .lock()
                    .unwrap_or_else(|error| error.into_inner())
                    .excluded
                    .extend(changed.iter().map(|item| item.id().to_owned()));
                for pending in journal
                    .pending_rounds
                    .lock()
                    .unwrap_or_else(|error| error.into_inner())
                    .iter_mut()
                {
                    pending
                        .excluded
                        .extend(changed.iter().map(|item| item.id().to_owned()));
                }
            }
            self.written.extend(prints);
            return true;
        }
        false
    }

    /// Whether the store holds this run's latest version of `id`. An id this
    /// run never produced a card for counts as confirmed: there is nothing
    /// pending that could still claim it.
    fn confirmed(&self, id: &str) -> bool {
        match self.items.iter().rev().find(|item| item.id() == id) {
            Some(item) => self.written.get(id).copied() == Some(context_fingerprint(item)),
            None => true,
        }
    }

    fn into_items(mut self) -> Vec<ContextItem> {
        self.checkpoint();
        // Reconciliation belongs to `Drop`, which every exit path reaches.
        std::mem::take(&mut self.items)
    }

    /// Remove the steering message's durable queue row when it joins a round.
    fn queued_delivered(&self, id: &str) {
        if let Some(sink) = self.sink.as_ref() {
            sink.drop_queued(id);
        }
    }
}

/// Reconcile on every exit path rather than only on the one that consumes the
/// ledger. A run that leaves through an error — a dead event sink, a failing
/// hook — returns before `into_items`, and its round's streaming rows would
/// then stay `streaming` until the next run or the next app start. In that
/// window an idle, in-sync `conversations::update` rewrites the whole timeline
/// as settled, turning what was an interrupted fragment into a message that
/// looks complete.
impl Drop for GeneratedContexts {
    fn drop(&mut self) {
        // A last attempt at any write that never confirmed. `into_items` has
        // already emptied `items`, so this costs nothing on the normal path.
        self.checkpoint();
        if let Some(journal) = self.journal.as_ref() {
            let frozen = journal
                .gate
                .lock()
                .unwrap_or_else(|error| error.into_inner());
            if *frozen {
                return;
            }
            if let Err(error) = journal.finish_locked() {
                eprintln!("退出运行时持久化正文失败：{error}");
                return;
            }
        }
        if let Some(sink) = self.sink.as_ref() {
            sink.finish();
        }
    }
}

impl std::ops::Deref for GeneratedContexts {
    type Target = Vec<ContextItem>;

    fn deref(&self) -> &Self::Target {
        &self.items
    }
}

impl std::ops::DerefMut for GeneratedContexts {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.items
    }
}

fn context_fingerprint(item: &ContextItem) -> u64 {
    use std::hash::{Hash, Hasher};
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    serde_json::to_string(item)
        .unwrap_or_default()
        .hash(&mut hasher);
    hasher.finish()
}

/// Persists prose while a round streams. Before canonical context exists, the
/// event sink periodically upserts a `streaming` row. Reconciliation marks a
/// leftover row interrupted; normal settlement replaces it in place with the same id.
///
/// The event stream tells it when an attempt is retried; the round loop tells
/// it when a paused step completes ([`Self::commit`]) and when a round's cards
/// have been minted ([`Self::round_settled`]), at which point any row of that
/// round no card claimed is dropped instead of being left for reconciliation.
/// Serializes streaming, canonical writes, and the application exit snapshot.
/// A failed exit keeps the gate closed: the same snapshots can be retried without
/// accepting newer deltas behind a partially committed exit barrier.
#[derive(Clone, Default)]
pub(crate) struct ProseJournalRegistry {
    gate: Arc<std::sync::Mutex<bool>>,
    journals: Arc<std::sync::Mutex<Vec<Arc<ProseJournal>>>>,
}

impl ProseJournalRegistry {
    fn register(&self, mut journal: ProseJournal) -> Result<Arc<ProseJournal>, String> {
        let frozen = self.gate.lock().unwrap_or_else(|error| error.into_inner());
        if *frozen {
            return Err("应用正在退出，拒绝启动新的流式持久化".into());
        }
        journal.gate = Arc::clone(&self.gate);
        let journal = Arc::new(journal);
        self.journals
            .lock()
            .unwrap_or_else(|error| error.into_inner())
            .push(Arc::clone(&journal));
        Ok(journal)
    }

    fn complete(&self, journal: &Arc<ProseJournal>) {
        let frozen = self.gate.lock().unwrap_or_else(|error| error.into_inner());
        if *frozen {
            return;
        }
        if let Err(error) = journal.finish_locked() {
            eprintln!("运行最终快照落盘失败，保留至退出时重试：{error}");
            return;
        }
        self.journals
            .lock()
            .unwrap_or_else(|error| error.into_inner())
            .retain(|entry| !Arc::ptr_eq(entry, journal));
    }

    pub(crate) fn flush_for_exit(&self) -> Result<(), String> {
        let mut frozen = self.gate.lock().unwrap_or_else(|error| error.into_inner());
        *frozen = true;
        let journals = self
            .journals
            .lock()
            .unwrap_or_else(|error| error.into_inner());
        for journal in journals.iter() {
            journal.finish_locked()?;
        }
        Ok(())
    }
}

struct ProseJournal {
    gate: Arc<std::sync::Mutex<bool>>,
    pending_rounds: std::sync::Mutex<Vec<ProseRound>>,
    sink: ConversationSink,
    /// Run token used with the round to derive the shared streaming and final
    /// context id.
    request_id: String,
    /// Resolved reasoning form for this run. Streaming and final contexts must
    /// use the same form because they are the same timeline entry.
    reasoning_form: ReasoningForm,
    state: std::sync::Mutex<ProseRound>,
}

/// Throttle interval for streaming prose persistence. A host UPSERT writes one
/// row and can run more often than a renderer round trip.
const PROSE_WRITE_INTERVAL: std::time::Duration = std::time::Duration::from_secs(1);

#[derive(Clone)]
struct ProseRound {
    round: usize,
    /// The last received attempt survives retry backoff until a replacement delta.
    retry_snapshot: Option<(String, String)>,
    excluded: std::collections::HashSet<String>,
    finished: bool,
    text: String,
    reasoning: String,
    /// Byte lengths of `text` and `reasoning` that completed provider steps
    /// produced. A `pause_turn` continuation keeps streaming the same round,
    /// and when one of its later steps is retried, only what that step
    /// streamed is discarded; the prefix stays.
    committed: (usize, usize),
    assistant_id: String,
    reasoning_id: String,
    created_at: String,
    last_write: Instant,
}

impl ProseRound {
    fn new(request_id: &str, round: usize) -> Self {
        Self {
            round,
            retry_snapshot: None,
            excluded: std::collections::HashSet::new(),
            finished: false,
            text: String::new(),
            reasoning: String::new(),
            committed: (0, 0),
            assistant_id: round_identity(request_id, round, "assistant")
                .unwrap_or_else(|| new_context_id("assistant")),
            reasoning_id: round_identity(request_id, round, "reasoning")
                .unwrap_or_else(|| new_context_id("reasoning")),
            created_at: Utc::now().to_rfc3339(),
            last_write: Instant::now(),
        }
    }
}

impl ProseJournal {
    fn new(sink: ConversationSink, request_id: &str, reasoning_form: ReasoningForm) -> Self {
        Self {
            gate: Arc::new(std::sync::Mutex::new(false)),
            pending_rounds: std::sync::Mutex::new(Vec::new()),
            sink,
            request_id: request_id.to_owned(),
            reasoning_form,
            state: std::sync::Mutex::new(ProseRound::new(request_id, 0)),
        }
    }

    fn deliver(
        &self,
        event: ModelStreamEvent,
        event_sink: &ModelEventSink<'_>,
    ) -> Result<(), String> {
        if !self.note(&event) {
            return Err("应用退出持久化屏障已关闭事件接收".into());
        }
        event_sink(event)
    }

    fn note(&self, event: &ModelStreamEvent) -> bool {
        let frozen = self.gate.lock().unwrap_or_else(|error| error.into_inner());
        if *frozen {
            return false;
        }
        let (round, text, reasoning) = match event {
            ModelStreamEvent::TextDelta { round, delta } => (*round, Some(delta.as_str()), None),
            // The round ledger merges reasoning by round for crash recovery;
            // segment identity is maintained by streaming and settlement.
            ModelStreamEvent::ReasoningDelta { round, delta, .. } => {
                (*round, None, Some(delta.as_str()))
            }
            ModelStreamEvent::StreamRetryScheduled { round, .. } => {
                self.retry(*round);
                return true;
            }
            _ => return true,
        };
        let mut state = self
            .state
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if state.round != round {
            if !self.snapshot_items(&state).is_empty() {
                self.pending_rounds
                    .lock()
                    .unwrap_or_else(|error| error.into_inner())
                    .push(state.clone());
            }
            *state = ProseRound::new(&self.request_id, round);
        }
        state.retry_snapshot = None;
        if let Some(text) = text {
            state.text.push_str(text);
        }
        if let Some(reasoning) = reasoning {
            state.reasoning.push_str(reasoning);
        }
        if state.last_write.elapsed() < PROSE_WRITE_INTERVAL {
            return true;
        }
        state.last_write = Instant::now();
        self.write(&state);
        true
    }

    /// The attempt that was streaming this round has failed and the step is
    /// about to be requested again. Its prose leaves the buffers, so the
    /// replacement attempt is journaled from the start of the step rather than
    /// appended to a failed attempt's text. Anything a completed step of this
    /// round produced before it is kept (see [`Self::commit`]).
    ///
    /// The rows already on disk are left alone. Until the replacement attempt
    /// overwrites them they are the newest prose this round has, and if the
    /// run is stopped during the backoff they are what reconciliation turns
    /// into the round's interrupted fragment. A row the retried round never
    /// claims is dropped when the round settles ([`Self::round_settled`]).
    ///
    /// Nothing has been journaled for a round the state has not reached, so
    /// only the current round is affected.
    fn retry(&self, round: usize) {
        let mut state = self
            .state
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if state.round != round {
            return;
        }
        if state.retry_snapshot.is_none() {
            state.retry_snapshot = Some((state.text.clone(), state.reasoning.clone()));
        }
        let (text, reasoning) = state.committed;
        state.text.truncate(text);
        state.reasoning.truncate(reasoning);
    }

    /// A step of this round completed and the provider paused the turn for a
    /// continuation. What it streamed is now this round's settled prefix: a
    /// retry of a later step discards only that step's own prose.
    fn commit(&self, round: usize) {
        let mut state = self
            .state
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if state.round != round {
            return;
        }
        state.committed = (state.text.len(), state.reasoning.len());
    }

    /// The round's canonical cards have been minted, whether it completed or
    /// settled as interrupted. Every card claimed its row by id, so a row of
    /// this round still in `streaming` is prose no card stands behind — a
    /// failed attempt's reasoning that the retried attempt never repeated —
    /// and it is dropped here rather than left for reconciliation to turn into
    /// an interrupted card for a round that in fact settled.
    ///
    /// "No card stands behind it" is a claim about the store, not about what
    /// was minted: a card whose own write never confirmed leaves its row in
    /// `streaming` while looking, from here, exactly like an unclaimed one.
    /// Rows in that state are kept, because the row is then the only surviving
    /// copy of that prose. The check is per id so that a pending card cannot
    /// also strand the round's genuinely unclaimed row.
    fn round_settled(&self, round: usize, generated: &GeneratedContexts) {
        let frozen = self.gate.lock().unwrap_or_else(|error| error.into_inner());
        if *frozen {
            return;
        }
        let mut state = self
            .state
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if state.round != round {
            return;
        }
        let unclaimed = [state.assistant_id.as_str(), state.reasoning_id.as_str()]
            .into_iter()
            .filter(|id| generated.confirmed(id))
            .collect::<Vec<_>>();
        self.sink.discard_streaming(&unclaimed);
        let excluded = unclaimed.into_iter().map(str::to_owned).collect::<Vec<_>>();
        state.excluded.extend(excluded);
    }

    /// Caller holds the shared gate. Persist first, reconcile only after a
    /// successful write, and retain the snapshot on any error for a later retry.
    fn finish_locked(&self) -> Result<(), String> {
        let mut state = self.state.lock().unwrap_or_else(|error| error.into_inner());
        if state.finished {
            return Ok(());
        }
        let pending = self
            .pending_rounds
            .lock()
            .unwrap_or_else(|error| error.into_inner());
        let items = pending
            .iter()
            .chain(std::iter::once(&*state))
            .flat_map(|round| self.snapshot_items(round))
            .collect::<Vec<_>>();
        self.sink.store.upsert_contexts(
            &self.sink.conversation_id,
            &items,
            crate::conversation_store::ContextStatus::Streaming,
        )?;
        self.sink
            .store
            .reconcile_streaming_in(&self.sink.conversation_id)?;
        state.finished = true;
        Ok(())
    }

    fn snapshot_items(&self, state: &ProseRound) -> Vec<ContextItem> {
        let mut snapshot = state.clone();
        if let Some((text, reasoning)) = snapshot.retry_snapshot.take() {
            snapshot.text = text;
            snapshot.reasoning = reasoning;
        }
        self.items(&snapshot)
            .into_iter()
            .filter(|item| !state.excluded.contains(item.id()))
            .collect()
    }

    fn write(&self, state: &ProseRound) {
        self.sink.upsert(
            &self.items(state),
            crate::conversation_store::ContextStatus::Streaming,
        );
    }

    fn items(&self, state: &ProseRound) -> Vec<ContextItem> {
        // Streaming and canonical contexts share an id and group, so a recovered
        // interrupted fragment remains in its originating round.
        let model_turn_id = (!self.request_id.is_empty())
            .then(|| round_model_turn_id(&self.request_id, state.round));
        let mut items = Vec::new();
        if !state.reasoning.is_empty() {
            items.push(ContextItem::Reasoning {
                id: state.reasoning_id.clone(),
                content: Some(state.reasoning.clone()),
                form: Some(self.reasoning_form),
                round: Some(state.round),
                model_turn_id: model_turn_id.clone(),
                interrupted: false,
                // Reasoning duration and token usage arrive only in the `done`
                // frame; settlement replaces this row in place to add them.
                duration_ms: None,
                tokens: None,
                replay: None,
                created_at: state.created_at.clone(),
            });
        }
        if !state.text.is_empty() {
            items.push(ContextItem::Assistant {
                id: state.assistant_id.clone(),
                content: state.text.clone(),
                round: Some(state.round),
                model_turn_id,
                interrupted: false,
                sources: Vec::new(),
                created_at: state.created_at.clone(),
            });
        }
        items
    }
}

pub fn run_model(
    request: RunModelRequest,
    state: &AppState,
    event_sink: &ModelEventSink<'_>,
    approve_dangerous_tool: &DangerousToolApproval<'_>,
) -> Result<RunModelResponse, String> {
    run_model_with_transcript(request, state, event_sink, approve_dangerous_tool, None)
}

fn run_model_with_transcript(
    request: RunModelRequest,
    state: &AppState,
    event_sink: &ModelEventSink<'_>,
    approve_dangerous_tool: &DangerousToolApproval<'_>,
    transcript: Option<SubagentTranscriptSink>,
) -> Result<RunModelResponse, String> {
    // Only top-level runs write conversation rows. The ledger is attached to the
    // event sink, which observes every delta without coupling persistence to parsing.
    let journal = ConversationSink::for_request(&request).map(|sink| {
        ProseJournal::new(
            sink,
            &request.request_id,
            request.model.reasoning_content.into(),
        )
    });
    let Some(journal) = journal else {
        if request.subagent_depth == 0 && !request.app_data_path.is_empty() {
            return Err("对话库不可用，拒绝启动无法持久化的顶层运行".into());
        }
        return run_model_inner(
            request,
            state,
            event_sink,
            approve_dangerous_tool,
            None,
            transcript,
        );
    };
    let journal = state.prose_journals.register(journal)?;
    let journaled = |event: ModelStreamEvent| journal.deliver(event, event_sink);
    let result = run_model_inner(
        request,
        state,
        &journaled,
        approve_dangerous_tool,
        Some(&journal),
        transcript,
    );
    state.prose_journals.complete(&journal);
    result
}

fn model_stop_reason_is_stopped(reason: &str) -> bool {
    matches!(
        reason,
        "hook_stopped"
            | "hook_continuation_limit"
            | "subagent_round_limit"
            | "agent_definition_revoked"
            | "cancelled"
            | "canceled"
            | "stopped"
    )
}

fn run_model_inner(
    mut request: RunModelRequest,
    state: &AppState,
    event_sink: &ModelEventSink<'_>,
    approve_dangerous_tool: &DangerousToolApproval<'_>,
    // The journal behind `event_sink`, when this run writes conversation rows.
    // The round loop tells it when a paused step completes and when a round's
    // cards have been minted; neither is visible from the event stream.
    journal: Option<&Arc<ProseJournal>>,
    transcript: Option<SubagentTranscriptSink>,
) -> Result<RunModelResponse, String> {
    // Named-agent definitions are revocable trusted capabilities. Validate
    // before MCP discovery or lifecycle hooks can start a process, run a
    // command, or otherwise observe the stale definition.
    let initial_definition_authority = request
        .agent_definition_binding
        .as_ref()
        .map(|_| {
            state.definition_authority_lock.read().map_err(|_| {
                "Named-agent definition authority lock is poisoned; this turn has not started."
                    .to_owned()
            })
        })
        .transpose()?;
    validate_current_agent_definition(&request, state)?;
    // Reject malformed trusted policy before MCP discovery can start a process
    // or make a network request. Revalidate below after dynamic descriptors are
    // attached so the final provider catalog is checked as one coherent
    // request.
    validate_run_request(&request)?;
    attach_mcp_tools(&mut request, state)?;
    validate_run_request(&request)?;
    // Whether the conversation has handoff notes and has been armed to hand
    // off: the two facts behind the handoff tools every step derives.
    request.handoff = crate::handoff::HandoffRun::resolve(&request);
    // Resolve reasoning form once per run. The model cannot change during a run,
    // and every reasoning card must use the same form.
    let reasoning_form = ReasoningForm::from(request.model.reasoning_content);
    let started = Instant::now();
    // The sidecar receives a base URL and derives endpoints by family. The host
    // remains responsible for HTTPS, loopback exceptions, and suffix stripping.
    let base_url = provider_base_url(&request.provider)?;
    let key = initial_provider_key(&request.provider, &base_url)?;
    let base_url_text = base_url.as_ref().map(Url::to_string).unwrap_or_default();
    // One CLI session per run for the Claude Agent family (`None` otherwise).
    // Holding it here, not inside the round loop, is what makes the CLI's
    // parked tool handlers survive across rounds; dropping it on any exit
    // path sends `release`.
    let agent_lease =
        crate::aisdk::agent::SessionLease::acquire(&request.provider, &request.app_data_path)?;
    // Each parent round and child run owns a gateway ledger handle, ensuring one
    // record per HTTP request without double-counting absorbed child usage.
    let gateway_ledger = crate::token_ledger::GatewayRecorder::new(
        &request.app_data_path,
        if request.subagent_depth > 0 {
            crate::token_ledger::UsageOrigin::Subagent
        } else {
            crate::token_ledger::UsageOrigin::Conversation
        },
        &request.conversation_id,
        &request.workspace_id,
        &request.provider.id,
        &request.provider.name,
        &request.model.id,
    );
    let mut exchanges = Vec::new();
    let mut generated = GeneratedContexts::new(
        ConversationSink::for_request(&request),
        request
            .contexts
            .last()
            .map(|context| context.id().to_owned()),
    )
    .with_transcript(transcript);
    generated.journal = journal.cloned();
    let mut hook_budget = hooks::HookBudget::default();
    let hook_services = HookRunServices {
        event_sink,
        cancellation: request.round_cancellation(),
    };
    let mut usage = ModelUsage::default();
    // `usage` below is cumulative across tool rounds (and eventually child agents).  Keep the
    // final parent-model round separately for the context meter.
    let mut context_tokens = None;
    // The same count, with what has joined the transcript since, for the
    // auto-compact threshold.
    let mut context_measure = ContextMeasure::default();
    let mut response_model = request.model.id.clone();
    let mut stop_reason = None;
    let mut run_error: Option<ModelRunError> = None;
    let turn_id = Uuid::new_v4().to_string();
    let mut stop_hook_active = false;
    let mut stop_continuations = 0usize;
    let mut generated_checkpoint = 0usize;
    let instructions_loaded = instructions_loaded_dispatcher(&request, &hook_services, &turn_id);
    let mut project_memory_state =
        ProjectMemoryRunState::discover(&mut request, instructions_loaded.as_ref())?;

    if state.begin_hook_session(&request.conversation_id) {
        let input = hook_input(
            &request,
            HookEvent::SessionStart,
            &turn_id,
            json!({"source":"startup"}),
        );
        let executions = run_hook_event(
            &request,
            &hook_services,
            HookEvent::SessionStart,
            Some("startup"),
            None,
            &input,
            0,
            &mut hook_budget,
        )?;
        record_hook_outputs(&mut request, &mut generated, &executions);
        if let Some(reason) = hook_block_reason(&executions, &request.prompt_profile) {
            // The run ends here, so a hook's context has no round to ride; it
            // joins the transcript for the next turn instead.
            deliver_host_notices(&mut request, state, 0, &mut [], &mut generated);
            generated.push(assistant_context(
                request
                    .prompt_profile
                    .render(PromptKey::HookSessionStartBlocked, &[("reason", &reason)]),
            ));
            return Ok(run_response(
                &request,
                generated.into_items(),
                usage,
                response_model,
                started,
                None,
                Some("hook_blocked".into()),
                None,
                None,
            ));
        }
    }

    let prompt = latest_user_prompt(&request.contexts);
    let input = hook_input(
        &request,
        HookEvent::UserPromptSubmit,
        &turn_id,
        json!({"prompt":prompt}),
    );
    let executions = run_hook_event(
        &request,
        &hook_services,
        HookEvent::UserPromptSubmit,
        None,
        None,
        &input,
        0,
        &mut hook_budget,
    )?;
    record_hook_outputs(&mut request, &mut generated, &executions);
    if let Some(reason) = hook_block_reason(&executions, &request.prompt_profile) {
        // The run ends here, so a hook's context has no round to ride; it
        // joins the transcript for the next turn instead.
        deliver_host_notices(&mut request, state, 0, &mut [], &mut generated);
        generated.push(assistant_context(
            request
                .prompt_profile
                .render(PromptKey::HookUserPromptBlocked, &[("reason", &reason)]),
        ));
        return Ok(run_response(
            &request,
            generated.into_items(),
            usage,
            response_model,
            started,
            None,
            Some("hook_blocked".into()),
            None,
            None,
        ));
    }
    drop(initial_definition_authority);

    // Advisory, so a document read failure must not fail the turn.
    if should_inject_agent_types(&request) {
        let policy = role_policy(&request, state);
        // A failed read leaves the static schema in place rather than injecting
        // an empty enum: "no roles" and "could not tell" are different claims,
        // and only the first one may remove the selector.
        if let Some(roles) = policy.roles() {
            let roles = roles.to_vec();
            inject_agent_type_schemas(&mut request, &roles, policy.required());
        }
    }
    // The `skill` schema is not injected here, unlike the role schemas above:
    // it names no skill, so it is the same object on every request and adding
    // a skill mid-conversation never redeclares a tool.
    record_added_skill_contexts(&mut request);

    // A subagent loop is cancellation-driven, exactly like the top-level loop.
    //
    // There used to be a hard 40-round ceiling here, on the reasoning that an
    // invisible child loop could otherwise spin forever. The containment answer
    // is visibility rather than a budget: a child whose state is on screen can
    // be stopped, and a round cap only ever truncated legitimate long work while
    // doing nothing about a child nobody was watching. Cancellation and the
    // parent's own lifetime remain the stops.

    // Wire-format history for this turn: reuses the conversation's cached
    // projection prefix (top-level runs only) and projects just the new tail;
    // rounds re-assemble without re-projecting. Subagents still get in-turn
    // reuse but stay out of the cross-turn cache.
    let mut wire_session = wire_history::begin_session_with_replay(
        (request.subagent_depth == 0).then(|| request.conversation_id.clone()),
        WireVariant::for_format(request.provider.family),
        &request.contexts,
        wire_history::ReplayInputs::new(&request.app_data_path, &request.conversation_id),
    );

    // Top-level task runs use the session-lifetime pool and shadow. They survive
    // rounds; loop exits only finalize settled records. Child runs keep a private,
    // round-lifetime pool whose long work cannot outlive its child round.
    let conversation_tasks =
        (request.subagent_depth == 0).then(|| state.conversation_tasks(&request.conversation_id));
    let local_pool;
    let local_shadow;
    // The shadow kernel observes the formal-spec projection without interfering.
    // Divergences are recorded; strict mode panics. Top-level shadows are
    // session-lifetime, while child runs keep private shadows.
    let (pool, kernel_shadow): (&AgentPool, &crate::kernel_shadow::KernelShadow) =
        if let Some(tasks) = &conversation_tasks {
            (tasks.pool.as_ref(), tasks.shadow.as_ref())
        } else {
            local_pool = AgentPool::new();
            local_shadow = crate::kernel_shadow::KernelShadow::new(
                local_pool.live_limit().unwrap_or(agents::MAX_LIVE_AGENTS),
            );
            (&local_pool, &local_shadow)
        };
    kernel_shadow.begin_turn_with_completed(pool.undelivered_result_identities());
    let mut agent_context_ids = HashMap::<String, String>::new();
    // Schema-bound runs only. Declared out here, beside the other turn states,
    // because `run_response` below the scope has to read the validated value.
    let mut structured_output_state = StructuredOutputTurnState::default();
    // Which deferred MCP tools this turn has handed schemas out for. Declared
    // here because widening `enabled_tools` is the round loop's job: the
    // executor only reports what it matched.
    let mut tool_search_state = ToolSearchTurnState::default();
    // The round a notice queued after the last loop head is stamped with.
    let mut last_round = 0usize;
    // The tool set the previous request of this transcript offered, which is
    // what tells a tool that just joined from one already declared. A top-level
    // run continues from the conversation's last request; a child's tool set is
    // its own, so it starts from its first.
    let mut offered_tools = if request.subagent_depth == 0 {
        state.offered_tools.last(&request.conversation_id)
    } else {
        None
    };
    let turn = {
        let loop_outcome = (|| -> Result<(), String> {
            for round in 1usize.. {
                last_round = round;
                // Settle the prior round on return to the loop head; steering
                // intake and fold occur after this prep boundary.
                kernel_shadow.round_boundary();
                // Problems a language server published since the last round.
                // This is the round boundary the source calls attachment
                // generation time: diagnostics are never waited for, they are
                // delivered whenever they have arrived.
                inject_lsp_diagnostics(&mut request, state);
                // Files the model read that changed behind its back since. The
                // same boundary Claude Code scans `readFileState` at: query
                // start and after every tool batch.
                inject_file_change_notices(&mut request, state);
                // Derive group identity from run and round, matching the renderer's
                // streamed grouping so settlement cannot change the group's identity.
                let model_turn_id = if request.request_id.is_empty() {
                    new_context_id("model-turn")
                } else {
                    round_model_turn_id(&request.request_id, round)
                };
                // A user steer is acknowledged only when it actually crosses
                // into the current turn. The frontend keeps the durable queue
                // card until this event, so cancellation and end-of-turn races
                // cannot silently discard the instruction.
                if let Some(mailbox) = request.steer_mailbox.0.clone() {
                    let steer_batch = mailbox.drain();
                    if !steer_batch.is_empty() {
                        // Project one batch as a single enqueue-to-intake transition.
                        kernel_shadow.steer_joined();
                        // The message comes after the round that just settled: move
                        // that round out of the live exchanges into the transcript
                        // first, or the message would be projected ahead of the
                        // tool calls and results it follows (an `ask_user` closed
                        // by this very message included).
                        if !exchanges.is_empty() {
                            sync_generated_contexts(
                                &mut request,
                                &generated,
                                &mut generated_checkpoint,
                            );
                            exchanges.clear();
                        }
                    }
                    for message in steer_batch {
                        let mut images = message.images;
                        let files = message.files;
                        let id = message
                            .id
                            .unwrap_or_else(|| new_context_id("steer-message"));
                        let created_at = message
                            .created_at
                            .unwrap_or_else(|| Utc::now().to_rfc3339());
                        let mut content = message.content;
                        // The renderer numbered these images against the
                        // document it could see; the turn may have minted more
                        // numbers since, so re-check before the event makes the
                        // numbering durable.
                        renumber_user_message_images(
                            &request,
                            &generated,
                            &mut content,
                            &mut images,
                        );
                        event_sink(ModelStreamEvent::UserInputReceived {
                            round,
                            id: id.clone(),
                            content: content.clone(),
                            images: images.clone(),
                            files: files.clone(),
                            created_at: created_at.clone(),
                        })?;
                        let context = ContextItem::User {
                            id,
                            content,
                            images,
                            files,
                            created_at,
                        };
                        // Invalidate the durable queue copy once the model has
                        // seen the message; it now belongs to the timeline.
                        generated.queued_delivered(context.id());
                        request.contexts.push(context.clone());
                        generated.push(context);
                    }
                }
                // Everything from here to `append_new_tools` is the host's own
                // addition to the transcript, announced to the renderer below.
                let host_added_from = generated.len();
                // Terminal results nobody waited for reach the model at the
                // next round boundary — including results a task settled while
                // When the conversation was idle, results from surviving tasks
                // are delivered at the next round boundary. If this run already
                // returns real tool results, notifications follow them in the same request.
                fold_undrained_agent_results(
                    &pool,
                    &kernel_shadow,
                    event_sink,
                    round,
                    &request.conversation_id,
                    state,
                    &request.prompt_profile,
                    &mut exchanges,
                    &mut request.contexts,
                    &mut generated,
                );
                // Deliver recovered interrupted-workflow notifications through
                // the same round-boundary window as fold.
                let restart_notices_delivered = fold_workflow_restart_notices(
                    &request.prompt_profile,
                    round,
                    &request.conversation_id,
                    state,
                    &mut exchanges,
                    &mut request.contexts,
                    &mut generated,
                );
                // Subagents the previous process lost before their results reached the model
                // are reported in the same window.
                let lost_subagents_reported = fold_subagent_restart_notices(
                    &request.prompt_profile,
                    round,
                    &request.conversation_id,
                    &request.app_data_path,
                    state,
                    &mut exchanges,
                    &mut request.contexts,
                    &mut generated,
                );
                // Auto-compact: past the threshold the conversation is armed to
                // hand off, and offered the handoff tools from this request on.
                // Measured ahead of the notices below, which the next request
                // carries too.
                let handoff_instruction =
                    arm_handoff_at_boundary(&mut request, state, &context_measure, &generated);
                // Every notice the host has queued for the model since the
                // last request: hooks, skills, diagnostics, changed files, a
                // Stop hook's continuation, the structured-output reminder.
                deliver_host_notices(&mut request, state, round, &mut exchanges, &mut generated);
                // The instructions follow every notice, as the carriers place
                // them on the wire (`Exchange::system_appends` after the
                // deliveries): first the request to hand off.
                if let Some(instruction) = handoff_instruction {
                    deliver_instruction(
                        &mut request,
                        state,
                        round,
                        offered_tools.as_ref(),
                        &mut exchanges,
                        &mut generated,
                        instruction,
                    );
                }
                // A continuation's first boundary: the notes it inherited, where
                // its system prompt could not take them (`handoff.rs`).
                deliver_handoff_index(
                    &mut request,
                    state,
                    round,
                    offered_tools.as_ref(),
                    &mut exchanges,
                    &mut generated,
                );
                // Plan mode switched on or off since the model was last told:
                // the instruction is added here, after everything above, and
                // the plan tools it introduces join just below.
                reconcile_plan_mode(
                    &mut request,
                    state,
                    round,
                    offered_tools.as_ref(),
                    &mut exchanges,
                    &mut generated,
                );
                // Last, so a tool that joined this boundary (the handoff tools
                // armed just above, an MCP schema `tool_search` handed out, the
                // plan pair) is appended after everything else the model is owed.
                append_new_tools(&mut request, &mut offered_tools, &mut exchanges, &mut generated);
                announce_host_contexts(event_sink, round, &generated[host_added_from..]);
                // Backfill and re-sign settled task records at the round boundary
                // and persist them with the event, rather than waiting for request
                // settlement, so completed transcripts survive a mid-run crash.
                let card_updates = checkpoint_terminal_agent_records(
                    pool,
                    &request.conversation_id,
                    &request.workspace_path,
                    state,
                    event_sink,
                    round,
                    &mut request.contexts,
                    &mut generated,
                    &agent_context_ids,
                );
                generated.track_card_updates(card_updates);
                // Confirm all prior-round output, including folded task results
                // and backfilled records, before this round can lose it.
                let boundary_durable = generated.checkpoint();
                // Clear recovery accounting only after checkpoint confirmation.
                // Failed writes remain eligible for delivery after restart.
                if boundary_durable {
                    for (notice_conversation, notice_run) in &restart_notices_delivered {
                        crate::workflow_store::mark_crash_notice_delivered(
                            std::path::Path::new(&request.app_data_path),
                            notice_conversation,
                            notice_run,
                        );
                    }
                    for name in &lost_subagents_reported {
                        crate::subagent_ledger::settle(
                            std::path::Path::new(&request.app_data_path),
                            &request.conversation_id,
                            name,
                        );
                    }
                    settle_delivered_subagents(pool, &request, state);
                } else if !restart_notices_delivered.is_empty() || !lost_subagents_reported.is_empty() {
                    eprintln!(
                        "重启中断通知未确认入库，暂不销账（{} 条待下次启动补投）",
                        restart_notices_delivered.len() + lost_subagents_reported.len()
                    );
                }
                // `pause_turn` is one logical Anthropic assistant turn even
                // when the server-side tool loop needs several HTTP requests.
                // Keep every provider block in transient `exchanges`, stream
                // all deltas under the same UI round, and persist only the
                // combined format-neutral visible result.
                let had_tool_exchange = !exchanges.is_empty();
                let mut pause_continuations = 0usize;
                let mut output_continuations = 0usize;
                let mut paused_text = String::new();
                let mut paused_reasoning = Vec::new();
                // Signed reasoning parts of every pause step, so the round's cards
                // replay the whole logical turn and not only its last request.
                let mut paused_replay_parts: Vec<Value> = Vec::new();
                let mut paused_sources: Vec<crate::aisdk::protocol::SidecarSource> = Vec::new();
                // Sidecar `reasoning_ms` is cumulative per step. Sum it across
                // steps so settlement retains the full UI-round duration.
                let mut paused_reasoning_ms: Option<u64> = None;
                // `reasoningTokens` is also per step. Sum it alongside duration;
                // keeping only the final step would give incompatible accounting.
                let mut paused_reasoning_tokens: Option<u64> = None;
                // Reasoning item ordinals restart at zero for a continuation step.
                // Offset them by earlier steps to prevent streamed identity collisions.
                let mut paused_reasoning_item_base = 0usize;
                let step_reasoning_items = std::sync::atomic::AtomicUsize::new(0);
                // Prep ledger is clear; dispatch one provider call. Multiple HTTP
                // continuations for `pause_turn` remain one round.
                kernel_shadow.round_started();
                let parsed = loop {
                    wire_session.sync(&request.contexts);
                    // Re-resolved per step so a Codex access token refreshed
                    // mid-run reaches this request; key families are a no-op.
                    let credential = step_credential(&request.provider, &key)?;
                    let key = credential.api_key.clone();
                    let (mut step, audit) = crate::aisdk::step::build_step_request_audited(
                        &request,
                        &exchanges,
                        wire_session.assemble(),
                        &base_url_text,
                        key.clone(),
                        // Ordinary rounds use one sidecar step: tool calls return
                        // to the host, which owns the tool loop.
                        1,
                        |_| {},
                    )?;
                    let wire_recorder = crate::history::RequestRecorder::for_request(
                        &request,
                        crate::history::KIND_MODEL,
                        round,
                        audit,
                    );
                    step.headers = credential.headers;
                    step.agent = agent_lease.session(&request.model);
                    // Revalidate external-import trust before sending: it may have
                    // been revoked after approval but before dispatch.
                    let validate_import_trust = || {
                        if let Some(project_memory) = project_memory_state.as_ref() {
                            project_memory.validate_external_import_trust(&request)?;
                        }
                        Ok(())
                    };
                    let has_external_project_import_trust = project_memory_state
                        .as_ref()
                        .and_then(|project_memory| project_memory.trust_lease.as_ref())
                        .is_some();
                    // A reasoning-done event reports this step's cumulative values.
                    // Offset duration and item ordinals by earlier steps so a pause
                    // continuation does not reset card values or identities.
                    let reasoning_ms_base = paused_reasoning_ms.unwrap_or(0);
                    let reasoning_item_base = paused_reasoning_item_base;
                    step_reasoning_items.store(0, std::sync::atomic::Ordering::Relaxed);
                    let continuation_sink = |event: ModelStreamEvent| -> Result<(), String> {
                        let event = match event {
                            ModelStreamEvent::ReasoningStart { round, item, form } => {
                                step_reasoning_items
                                    .fetch_max(item + 1, std::sync::atomic::Ordering::Relaxed);
                                ModelStreamEvent::ReasoningStart {
                                    round,
                                    item: item + reasoning_item_base,
                                    form,
                                }
                            }
                            ModelStreamEvent::ReasoningDelta { round, item, delta } => {
                                step_reasoning_items
                                    .fetch_max(item + 1, std::sync::atomic::Ordering::Relaxed);
                                ModelStreamEvent::ReasoningDelta {
                                    round,
                                    item: item + reasoning_item_base,
                                    delta,
                                }
                            }
                            ModelStreamEvent::ReasoningDone {
                                round,
                                item,
                                duration_ms,
                            } => {
                                step_reasoning_items
                                    .fetch_max(item + 1, std::sync::atomic::Ordering::Relaxed);
                                ModelStreamEvent::ReasoningDone {
                                    round,
                                    item: item + reasoning_item_base,
                                    duration_ms: if reasoning_ms_base > 0 {
                                        duration_ms.map(|ms| ms.saturating_add(reasoning_ms_base))
                                    } else {
                                        duration_ms
                                    },
                                }
                            }
                            other => {
                                // A transient retry restarts item ordinals. Do not
                                // include its maximum in the continuation offset.
                                if matches!(other, ModelStreamEvent::StreamRetryScheduled { .. }) {
                                    step_reasoning_items
                                        .store(0, std::sync::atomic::Ordering::Relaxed);
                                }
                                other
                            }
                        };
                        event_sink(event)
                    };
                    let mut parsed = match post_model_request_with_validator(
                        &step,
                        key.as_deref(),
                        round,
                        &continuation_sink,
                        request
                            .agent_definition_binding
                            .as_ref()
                            .map(|_| state.definition_authority_lock.as_ref()),
                        &|| validate_current_agent_definition(&request, state),
                        has_external_project_import_trust
                            .then_some(state.project_import_trust_lock.as_ref()),
                        &validate_import_trust,
                        gateway_ledger.as_ref(),
                        wire_recorder.as_ref(),
                    ) {
                        Ok(parsed) => parsed,
                        Err(exhausted) => {
                            if let ModelRequestError::EventSink(error) = exhausted.error {
                                return Err(error);
                            }
                            // A 401 from the Codex backend means the access token
                            // was revoked ahead of its `exp`; drop the cached
                            // expiry so the next run refreshes instead of
                            // replaying the same rejected token.
                            if request.provider.family == ProviderFamily::OpenaiCodex
                                && exhausted.error.message().starts_with("HTTP 401")
                            {
                                crate::codex_oauth::host()
                                    .invalidate_access_token(&request.provider.id);
                            }
                            // The failure itself is a transient notice for the
                            // renderer (structured `error`), never timeline
                            // content. What the logical round already streamed
                            // stays as interrupted canonical contexts.
                            paused_reasoning.extend(exhausted.partial.reasoning);
                            for (segment, reasoning) in paused_reasoning.iter().enumerate() {
                                generated.extend(interrupted_reasoning_context(
                                    reasoning_segment_identity(&request.request_id, round, segment),
                                    reasoning.clone(),
                                    round,
                                    &model_turn_id,
                                    reasoning_form,
                                ));
                            }
                            if !exhausted.partial.text.is_empty() {
                                if !paused_text.is_empty() {
                                    paused_text.push('\n');
                                }
                                paused_text.push_str(&exhausted.partial.text);
                            }
                            if !paused_text.is_empty() {
                                generated.push(interrupted_assistant_context(
                                    round_identity(&request.request_id, round, "assistant"),
                                    paused_text.clone(),
                                    round,
                                    &model_turn_id,
                                    context_sources(&paused_sources),
                                ));
                            }
                            if let Some(journal) = journal {
                                journal.round_settled(round, &generated);
                            }
                            run_error = Some(ModelRunError {
                                message: if pause_continuations > 0 {
                                    format!(
                                        "Anthropic pause_turn automatic continuation request failed: {}",
                                        exhausted.error.message()
                                    )
                                } else if had_tool_exchange {
                                    format!(
                                        "Model continuation request after tool execution failed: {}",
                                        exhausted.error.message()
                                    )
                                } else {
                                    format!(
                                        "Model API request failed: {}",
                                        exhausted.error.message()
                                    )
                                },
                                round,
                                attempts: exhausted.attempts,
                            });
                            stop_reason = Some("error".into());
                            break None;
                        }
                    };

                    context_tokens = usage_context_tokens(&parsed.usage);
                    context_measure.report(context_tokens, &model_turn_id, generated.len());
                    merge_usage(&mut usage, &parsed.usage);
                    if let Some(model) = parsed
                        .model
                        .as_deref()
                        .filter(|model| !model.trim().is_empty())
                    {
                        response_model = model.to_owned();
                    }
                    stop_reason = parsed.stop_reason.clone();

                    // AI SDK normalizes `pause_turn` to `finishReason:"stop"`.
                    // Accept the raw stop reason and normalized value so dialect
                    // passthrough cannot disable continuation.
                    let paused = parsed.raw_stop_reason.as_deref() == Some("pause_turn")
                        || parsed.stop_reason.as_deref() == Some("pause_turn");
                    let output_limited = matches!(
                        request.provider.family,
                        ProviderFamily::Anthropic | ProviderFamily::Bedrock
                    ) && (parsed.raw_stop_reason.as_deref()
                        == Some("max_tokens")
                        || (parsed.raw_stop_reason.is_none()
                            && parsed.stop_reason.as_deref() == Some("length")));
                    // A token-truncated tool input is not an executable invocation.
                    if output_limited {
                        parsed.calls.clear();
                        if let Some(messages) = parsed.continuation.as_array_mut() {
                            for message in messages {
                                if let Some(content) =
                                    message.get_mut("content").and_then(Value::as_array_mut)
                                {
                                    content.retain(|part| part["type"] != "tool-call");
                                }
                            }
                        }
                    }
                    let continue_output = output_limited && output_continuations < 3;
                    if paused || continue_output {
                        if !parsed.text.is_empty() {
                            if !paused_text.is_empty() {
                                paused_text.push('\n');
                            }
                            paused_text.push_str(&parsed.text);
                        }
                        paused_reasoning.append(&mut parsed.reasoning);
                        paused_sources.append(&mut parsed.sources);
                        if let Some(step_ms) = parsed.reasoning_ms {
                            paused_reasoning_ms =
                                Some(paused_reasoning_ms.unwrap_or(0).saturating_add(step_ms));
                        }
                        if let Some(step_tokens) = parsed.usage.reasoning_tokens {
                            paused_reasoning_tokens = Some(
                                paused_reasoning_tokens
                                    .unwrap_or(0)
                                    .saturating_add(step_tokens),
                            );
                        }
                        paused_reasoning_item_base +=
                            step_reasoning_items.swap(0, std::sync::atomic::Ordering::Relaxed);
                        if paused && pause_continuations >= MAX_ANTHROPIC_PAUSE_CONTINUATIONS {
                            for (segment, reasoning) in paused_reasoning.iter().enumerate() {
                                generated.extend(interrupted_reasoning_context(
                                    reasoning_segment_identity(&request.request_id, round, segment),
                                    reasoning.clone(),
                                    round,
                                    &model_turn_id,
                                    reasoning_form,
                                ));
                            }
                            if !paused_text.is_empty() {
                                generated.push(interrupted_assistant_context(
                                    round_identity(&request.request_id, round, "assistant"),
                                    paused_text.clone(),
                                    round,
                                    &model_turn_id,
                                    context_sources(&paused_sources),
                                ));
                            }
                            if let Some(journal) = journal {
                                journal.round_settled(round, &generated);
                            }
                            run_error = Some(ModelRunError {
                                message: format!(
                                    "Anthropic pause_turn automatic continuation reached the safety limit of {MAX_ANTHROPIC_PAUSE_CONTINUATIONS}"
                                ),
                                round,
                                attempts: 1,
                            });
                            stop_reason = Some("error".into());
                            break None;
                        }
                        paused_replay_parts.extend(reasoning_replay_parts(&parsed.continuation));
                        let mut exchange = Exchange::new(parsed.continuation, Vec::new());
                        if continue_output {
                            output_continuations += 1;
                            exchange.host_deliveries.extend(transient_host_delivery(
                                &request,
                                state,
                                round,
                                crate::model::HostNotice {
                                    kind: crate::wire_history::notice_kind::OUTPUT_TRUNCATED,
                                    summary: request
                                        .prompt_profile
                                        .text(PromptKey::HostNoticeOutputTruncatedSummary)
                                        .to_owned(),
                                    body: request
                                        .prompt_profile
                                        .text(PromptKey::HostNoticeOutputTruncated)
                                        .to_owned(),
                                    id: None,
                                },
                            ));
                        } else {
                            pause_continuations += 1;
                        }
                        exchanges.push(exchange);
                        // This step is complete; what it streamed stays through
                        // a retry of the continuation that follows.
                        if let Some(journal) = journal {
                            journal.commit(round);
                        }
                        continue;
                    }

                    if !paused_text.is_empty() {
                        if !parsed.text.is_empty() {
                            paused_text.push('\n');
                            paused_text.push_str(&parsed.text);
                        }
                        parsed.text = paused_text;
                    }
                    if !paused_reasoning.is_empty() {
                        paused_reasoning.append(&mut parsed.reasoning);
                        parsed.reasoning = paused_reasoning;
                    }
                    if !paused_sources.is_empty() {
                        paused_sources.append(&mut parsed.sources);
                        parsed.sources = paused_sources;
                    }
                    // Merge duration and text independently: a step may report
                    // duration without a summary.
                    if let Some(base) = paused_reasoning_ms {
                        parsed.reasoning_ms =
                            Some(base.saturating_add(parsed.reasoning_ms.unwrap_or(0)));
                    }
                    if let Some(base) = paused_reasoning_tokens {
                        parsed.usage.reasoning_tokens =
                            Some(base.saturating_add(parsed.usage.reasoning_tokens.unwrap_or(0)));
                    }
                    break Some(parsed);
                };
                let Some(parsed) = parsed else {
                    break;
                };

                // Derive prose identity from run and round to match the renderer
                // and ledger row. Reasoning segments derive ids from their ordinal.
                // The cards also carry the provider's signed parts so later turns
                // replay them verbatim, as Claude Code and Codex do.
                let mut replay_parts = std::mem::take(&mut paused_replay_parts);
                replay_parts.extend(reasoning_replay_parts(&parsed.continuation));
                generated.extend(round_reasoning_contexts(
                    &parsed.reasoning,
                    ReasoningStats {
                        duration_ms: parsed.reasoning_ms,
                        tokens: parsed.usage.reasoning_tokens,
                    },
                    &request.request_id,
                    round,
                    &model_turn_id,
                    reasoning_form,
                    RoundReasoningReplay {
                        parts: replay_parts,
                        model: &request.model.id,
                    },
                ));

                if parsed.calls.is_empty() {
                    let assistant_text = if parsed.text.trim().is_empty() {
                        request
                            .prompt_profile
                            .text(PromptKey::RunNoTextReply)
                            .to_owned()
                    } else {
                        parsed.text
                    };
                    generated.push(model_assistant_context(
                        round_identity(&request.request_id, round, "assistant"),
                        assistant_text.clone(),
                        round,
                        &model_turn_id,
                        context_sources(&parsed.sources),
                    ));
                    if let Some(journal) = journal {
                        journal.round_settled(round, &generated);
                    }
                    let input = hook_input(
                        &request,
                        HookEvent::Stop,
                        &turn_id,
                        json!({
                            "stop_hook_active": stop_hook_active,
                            "last_assistant_message": assistant_text
                        }),
                    );
                    // The provider-send fence intentionally ends when the
                    // response is received so definition edits are not
                    // blocked by streaming. Reacquire the definition fence
                    // before Stop hooks: those hooks can execute commands,
                    // and a named agent revoked while the provider was
                    // responding must not retain that side-effect authority.
                    let stop_definition_authority = match current_agent_definition_authority(
                        &request,
                        state,
                        "Before running the Stop hook",
                    ) {
                        Ok(authority) => authority,
                        Err(error) => {
                            generated.push(assistant_context(request.prompt_profile.render(
                                PromptKey::HookStopSkippedDefinitionRevoked,
                                &[("error", &error)],
                            )));
                            stop_reason = Some("agent_definition_revoked".into());
                            break;
                        }
                    };
                    let executions = run_hook_event(
                        &request,
                        &hook_services,
                        HookEvent::Stop,
                        None,
                        None,
                        &input,
                        round,
                        &mut hook_budget,
                    )?;
                    // Decide whether the hook halts or requests a continuation
                    // while the exact definition is still read-fenced.
                    let hook_halted = executions.iter().any(|execution| execution.decision.halt);
                    let continuation_reason =
                        hook_continuation_reason(&executions, &request.prompt_profile);
                    drop(stop_definition_authority);
                    record_hook_outputs(&mut request, &mut generated, &executions);
                    if hook_halted {
                        stop_reason = Some("hook_stopped".into());
                        break;
                    }
                    if let Some(reason) = continuation_reason {
                        if stop_continuations >= 3 {
                            generated.push(assistant_context(
                                request
                                    .prompt_profile
                                    .render(PromptKey::HookStopLimitReached, &[("limit", "3")]),
                            ));
                            stop_reason = Some("hook_continuation_limit".into());
                            break;
                        }
                        sync_generated_contexts(
                            &mut request,
                            &generated,
                            &mut generated_checkpoint,
                        );
                        let continuation = ContextItem::User {
                            id: new_context_id("hook-continuation"),
                            content: reason,
                            images: Vec::new(),
                            files: Vec::new(),
                            created_at: Utc::now().to_rfc3339(),
                        };
                        request.contexts.push(continuation.clone());
                        generated.push(continuation.clone());
                        // It joins ahead of the next round, before that
                        // round's steering and host notices.
                        announce_host_contexts(
                            event_sink,
                            round + 1,
                            std::slice::from_ref(&continuation),
                        );
                        exchanges.clear();
                        stop_hook_active = true;
                        stop_continuations += 1;
                        // Account for host-injected boundary content as steering.
                        kernel_shadow.host_injection();
                        continue;
                    }
                    if request
                        .steer_mailbox
                        .0
                        .as_ref()
                        .is_some_and(|mailbox| !mailbox.is_empty())
                    {
                        sync_generated_contexts(
                            &mut request,
                            &generated,
                            &mut generated_checkpoint,
                        );
                        exchanges.clear();
                        continue;
                    }
                    // A schema-bound run that produced only prose gets exactly one
                    // reminder. Shaped like the hook continuation above, including
                    // `exchanges.clear()` — without it the next provider request
                    // carries orphaned tool_use blocks from this round.
                    if structured_output_state.needs_nudge(&request) {
                        sync_generated_contexts(
                            &mut request,
                            &generated,
                            &mut generated_checkpoint,
                        );
                        request.host_notices.push(crate::model::HostNotice {
                            kind: crate::wire_history::notice_kind::STRUCTURED_OUTPUT,
                            summary: request
                                .prompt_profile
                                .text(PromptKey::HostNoticeStructuredOutputSummary)
                                .to_owned(),
                            body: request
                                .prompt_profile
                                .text(PromptKey::SubagentStructuredOutputNudge)
                                .to_owned(),
                            id: None,
                        });
                        exchanges.clear();
                        structured_output_state.nudged = true;
                        // Account for host-injected boundary content as steering.
                        kernel_shadow.host_injection();
                        continue;
                    }
                    // Unfolded terminal task results require another round so the
                    // loop-head fold can deliver them. Every terminal status
                    // counts, a task the user closed included.
                    if pool.has_undrained_foldable_results() {
                        sync_generated_contexts(
                            &mut request,
                            &generated,
                            &mut generated_checkpoint,
                        );
                        exchanges.clear();
                        continue;
                    }
                    // Running tasks neither block settlement nor become interrupted.
                    // Their results are folded at the first boundary of the next
                    // wake-triggered or user-triggered round.
                    break;
                }

                {
                    generated.push(model_assistant_context(
                        round_identity(&request.request_id, round, "assistant"),
                        parsed.text.clone(),
                        round,
                        &model_turn_id,
                        context_sources(&parsed.sources),
                    ));
                    if let Some(journal) = journal {
                        journal.round_settled(round, &generated);
                    }
                }

                // Streaming parsers announce a call as soon as its stable id and tool name
                // arrive. JSON responses have no earlier metadata event, so announce those
                // here. Arguments still cross the IPC boundary only after the provider stream
                // has completed and the parser has produced a bounded, complete call.
                for call in &parsed.calls {
                    if let Some(streamed_name) = parsed.announced_tool_calls.get(&call.id) {
                        if streamed_name != &call.name {
                            return Err(format!(
                                "Tool call {} has different streamed and completed names",
                                call.id
                            ));
                        }
                    } else {
                        event_sink(ModelStreamEvent::ToolCallAnnounced {
                            round,
                            call_id: call.id.clone(),
                            tool_name: call.name.clone(),
                            // Filled in by the run's event sink, which is the
                            // only layer that knows the conversation.
                            context_id: String::new(),
                        })?;
                    }
                    if !call.input.contains_key("_raw") {
                        event_sink(ModelStreamEvent::ToolCallArgumentsReady {
                            round,
                            call_id: call.id.clone(),
                            input: public_tool_input(&call.name, &call.input),
                        })?;
                    }
                }

                let mut executions = Vec::with_capacity(parsed.calls.len());
                // Set when the user closed an `ask_user` card without a message
                // to follow it: the turn ends there, with no further request.
                let mut question_dismissed = false;
                // Set by a `handoff` that opened the continuation: the round
                // settles and the run ends without another request.
                let mut handed_off = false;
                // Async tool calls (`web_search` / `web_fetch`) dispatched this round
                // and collected at its settlement point.
                let mut pending_async: Vec<PendingAsyncTool> = Vec::new();
                let mut calls = parsed.calls.into_iter();
                while let Some(mut call) = calls.next() {
                    let requested_input = call.input.clone();
                    let automatic_rejection = automatic_tool_rejection_reason(&request, &call);
                    if let Some(reason) = automatic_rejection {
                        kernel_shadow.rejected_precheck(&call.id);
                        event_sink(ModelStreamEvent::ToolExecutionStarted {
                            round,
                            call_id: call.id.clone(),
                        })?;
                        let execution = rejected_tool_execution(&request, call, &reason, state);
                        event_sink(ModelStreamEvent::ToolExecutionCompleted {
                            round,
                            call_id: execution.call.id.clone(),
                            result: execution.result.clone(),
                        })?;
                        let context = tool_context_for_turn(
                            &execution,
                            round,
                            &model_turn_id,
                            None,
                            &request.conversation_id,
                            &request.request_id,
                            state,
                        );
                        generated.push(context);
                        crate::history::record_tool_result(&request, round, &execution);
                        executions.push(execution);
                        continue;
                    }
                    // A trusted named-agent definition is capability policy.
                    // Serialize its final validation with the complete hook /
                    // approval / tool / post-hook sequence so a concurrent
                    // renderer save cannot revoke or revise the definition in
                    // the narrow gap immediately before a side effect.
                    let _definition_authority = match current_agent_definition_authority(
                        &request,
                        state,
                        "Before the tool hook/approval/execution sequence",
                    ) {
                        Ok(authority) => authority,
                        Err(reason) => {
                            kernel_shadow.rejected_precheck(&call.id);
                            event_sink(ModelStreamEvent::ToolExecutionStarted {
                                round,
                                call_id: call.id.clone(),
                            })?;
                            let execution = rejected_tool_execution(&request, call, &reason, state);
                            event_sink(ModelStreamEvent::ToolExecutionCompleted {
                                round,
                                call_id: execution.call.id.clone(),
                                result: execution.result.clone(),
                            })?;
                            let context = tool_context_for_turn(
                                &execution,
                                round,
                                &model_turn_id,
                                None,
                                &request.conversation_id,
                                &request.request_id,
                                state,
                            );
                            generated.push(context);
                            crate::history::record_tool_result(&request, round, &execution);
                            executions.push(execution);
                            continue;
                        }
                    };
                    let input = hook_input(
                        &request,
                        HookEvent::PreToolUse,
                        &turn_id,
                        json!({
                            "tool_name": call.name,
                            "tool_use_id": call.id,
                            "tool_input": call.input.clone()
                        }),
                    );
                    let pre_tool = run_hook_event(
                        &request,
                        &hook_services,
                        HookEvent::PreToolUse,
                        Some(&call.name),
                        Some(call.id.as_str()),
                        &input,
                        round,
                        &mut hook_budget,
                    )?;
                    record_hook_outputs(&mut request, &mut generated, &pre_tool);
                    let mut hook_stops_turn =
                        pre_tool.iter().any(|execution| execution.decision.halt);
                    if let Some(updated) = hook_updated_input(&pre_tool) {
                        call.input = updated;
                        event_sink(ModelStreamEvent::ToolCallArgumentsReady {
                            round,
                            call_id: call.id.clone(),
                            input: public_tool_input(&call.name, &call.input),
                        })?;
                    }
                    event_sink(ModelStreamEvent::ToolExecutionStarted {
                        round,
                        call_id: call.id.clone(),
                    })?;
                    crate::helper_model::uses::on_tool_started(state, &request, round, &call.id, &call.name, &call.input);

                    let mut authorization = classify_tool_authorization(&request, &call)?;
                    let mut permission_forces_prompt = hook_permission_asks(&pre_tool);
                    let mut hook_allows_permission = hook_permission_allows(&pre_tool);
                    let mut denied = hook_block_reason(&pre_tool, &request.prompt_profile);
                    // Plan mode refuses before anything asks: no permission
                    // hook and no card is spent on a call it will not run.
                    if denied.is_none() {
                        denied = plan_mode_refusal(&request, &call, &authorization);
                    }
                    if denied.is_none()
                        && (permission_forces_prompt
                            || authorization
                                .requires_permission_hook(request.effective_security_level()))
                    {
                        let input = hook_input(
                            &request,
                            HookEvent::PermissionRequest,
                            &turn_id,
                            json!({
                                "tool_name": call.name,
                                "tool_input": call.input.clone(),
                                // Mework does not yet expose a persistent
                                // "always allow" proposal from this dialog.
                                // Preserve Claude's input shape without
                                // inventing a policy mutation destination.
                                "permission_suggestions": []
                            }),
                        );
                        let permission_hooks = run_hook_event(
                            &request,
                            &hook_services,
                            HookEvent::PermissionRequest,
                            Some(&call.name),
                            Some(call.id.as_str()),
                            &input,
                            round,
                            &mut hook_budget,
                        )?;
                        record_hook_outputs(&mut request, &mut generated, &permission_hooks);
                        denied = hook_block_reason(&permission_hooks, &request.prompt_profile);
                        hook_stops_turn |= hook_permission_interrupts(&permission_hooks)
                            || permission_hooks
                                .iter()
                                .any(|execution| execution.decision.halt);
                        if denied.is_none() {
                            if let Some(updated) = hook_updated_input(&permission_hooks) {
                                call.input = updated;
                                event_sink(ModelStreamEvent::ToolCallArgumentsReady {
                                    round,
                                    call_id: call.id.clone(),
                                    input: public_tool_input(&call.name, &call.input),
                                })?;
                                authorization = classify_tool_authorization(&request, &call)?;
                                denied = plan_mode_refusal(&request, &call, &authorization);
                            }
                        }
                        permission_forces_prompt = hook_permission_asks(&pre_tool)
                            || hook_permission_asks(&permission_hooks);
                        hook_allows_permission = hook_permission_allows(&pre_tool)
                            || hook_permission_allows(&permission_hooks);
                    }
                    if denied.is_none()
                        && permission_forces_prompt
                        && !authorization.intrinsic_mandatory_prompt()
                    {
                        let execution_request = ToolExecutionRequest {
                            conversation_id: request.conversation_id.clone(),
                            workspace_path: request.workspace_path.clone(),
                            tool_name: call.name.clone(),
                            input: call.input.clone(),
                        };
                        let descriptor = request
                            .tools
                            .iter()
                            .find(|tool| tool.name == call.name)
                            .ok_or_else(|| {
                            format!(
                                "Mandatory-confirmation decision references unknown tool {}",
                                call.name
                            )
                        })?;
                        let mut approval_descriptor = descriptor.clone();
                        // Hook-required confirmation must travel with this call's
                        // descriptor. Existing permanent permission cannot answer it
                        // or be offered for persistence.
                        approval_descriptor.force_confirmation = true;
                        if let Some(source) = permission_prompt_source(&pre_tool) {
                            approval_descriptor.label =
                                format!("{}\n确认来源：{source}", approval_descriptor.label);
                        }
                        match approve_dangerous_tool(
                            &execution_request,
                            &approval_descriptor,
                            approval_requester(&request),
                        ) {
                            Ok(true) => hook_allows_permission = true,
                            Ok(false) => {
                                denied = Some(
                                    "The user denied the confirmation required by the hook.".into(),
                                )
                            }
                            Err(error) => {
                                denied = Some(format!(
                                "Could not complete the confirmation required by the hook: {error}"
                            ))
                            }
                        }
                    }
                    if denied.is_none() {
                        if let Err(reason) = validate_current_agent_definition(&request, state) {
                            denied = Some(format!(
                                "The named-agent definition became invalid before tool execution; this side effect was refused: {reason}"
                            ));
                        }
                    }
                    // `structured_output` and `tool_search` have their whole effect
                    // in host-side turn state, so a blocking PostToolUse hook must be
                    // able to take it back. Without this a value written during
                    // dispatch would survive a hook that told the model the call
                    // failed, and ship out on the response.
                    let orchestration_checkpoint = (call.name == STRUCTURED_OUTPUT_TOOL
                        || call.name == crate::capabilities::TOOL_SEARCH_TOOL)
                        .then(|| (structured_output_state.clone(), tool_search_state.clone()));
                    // Final classification follows any Hook parameter rewrite.
                    // The approval predicate includes backend, MCP, and Hook
                    // requirements; attest the approved parameter summary.
                    let shadow_danger = authorization
                        .requires_permission_hook(request.effective_security_level())
                        || authorization.intrinsic_mandatory_prompt()
                        || permission_forces_prompt;
                    kernel_shadow.tool_request(
                        &call.id,
                        shadow_danger,
                        crate::kernel_shadow::call_params_digest(&call.input),
                    );
                    if denied.is_none() {
                        kernel_shadow.tool_dispatched(&call.id);
                    }
                    // The input this call runs with, once every hook has had its
                    // say, on disk before it runs: this — not the model's own
                    // words, which a hook may rightly have rewritten — is what a
                    // later check compares against.
                    crate::history::record_tool_call(
                        &request,
                        round,
                        &call,
                        &requested_input,
                        denied.as_deref(),
                    );
                    // Dangerous-call approval happens inside the executor. Wrap the
                    // callback only for this execution window; child workers retain
                    // the original callback beyond it.
                    let shadowed_approval = |execution_request: &ToolExecutionRequest,
                                             descriptor: &ToolDescriptor,
                                             requester: ApprovalRequester<'_>|
                     -> Result<bool, String> {
                        let outcome =
                            approve_dangerous_tool(execution_request, descriptor, requester);
                        if let Ok(granted) = &outcome {
                            kernel_shadow.record_prompt_outcome(*granted);
                        }
                        outcome
                    };
                    let rejected_before_execution = denied.is_some();
                    let mut file_identities = ToolFileIdentities::default();
                    let mut execution = {
                        // Direct IPC executors still attest their own result.
                        // During a model invocation those receipts are
                        // token-scoped, invisible to persistence, and removed
                        // exactly before PostToolUse decides the final result.
                        let _provisional_receipts = state.begin_provisional_receipts();
                        if let Some(reason) = denied {
                            rejected_tool_execution(&request, call, &reason, state)
                        } else if let Some(reason) = browser_credential_takeover_denial(
                            &request,
                            &call,
                            state,
                            &shadowed_approval,
                        ) {
                            failed_tool_execution(call, reason)
                        } else if tool_executor::ShellKind::of_tool(&call.name).is_some()
                            && tool_executor::shell_run_in_background_requested(&call.input)
                        {
                            // Consume approval before spawning the background shell
                            // process, then run it through the existing task mechanism
                            // for identity, fold, waiting, and cleanup.
                            run_background_shell(
                                pool,
                                kernel_shadow,
                                &request,
                                call,
                                state,
                                event_sink,
                                &shadowed_approval,
                                hook_allows_permission,
                                round,
                            )?
                        } else if agents::runs_async(&call.name) {
                            // `web_search` and `web_fetch` are concurrent async
                            // tools, not tasks. Consume approval before dispatch;
                            // settle local failures immediately and collect successful
                            // calls after the loop with other same-round results.
                            match dispatch_async_tool(
                                &request,
                                call,
                                &shadowed_approval,
                                hook_allows_permission,
                                requested_input.clone(),
                                round,
                            )? {
                                AsyncToolDispatch::Pending(pending) => {
                                    pending_async.push(*pending);
                                    continue;
                                }
                                AsyncToolDispatch::Settled(execution) => execution,
                            }
                        } else if call.name == BOX_TOOL {
                            // `box` exists to be a carrier the host fills, not a
                            // capability. Calling it is legal and does nothing;
                            // saying so is more useful than an error the model
                            // would try to work around.
                            ToolExecution {
                                result: ToolResult {
                                    success: true,
                                    output: request
                                        .prompt_profile
                                        .text(PromptKey::TaskBoxNoOp)
                                        .to_owned(),
                                    images: Vec::new(),
                                    diff: None,
                                    executed_at: Utc::now().to_rfc3339(),
                                    duration_ms: 0,
                                },
                                call,
                                subagent: None,
                            }
                        } else if let Some(kind) = agents::agent_tool_kind(&call.name) {
                            run_agent_tool(
                                kind,
                                pool,
                                kernel_shadow,
                                &request,
                                call,
                                state,
                                event_sink,
                                &shadowed_approval,
                                hook_allows_permission,
                                round,
                            )?
                        } else if call.name == workflow::WORKFLOW_TOOL {
                            // The workflow driver occupies an outer-pool slot and
                            // returns its spawn receipt immediately; steps fan out in
                            // its private pool. Mandatory approval is consumed before
                            // spawn and remains attributed to this call.
                            workflow::run_workflow_tool(
                                pool,
                                kernel_shadow,
                                &request,
                                call,
                                state,
                                event_sink,
                                &shadowed_approval,
                                hook_allows_permission,
                                round,
                            )?
                        } else if call.name == crate::ask_user::ASK_USER_TOOL {
                            crate::ask_user::run_ask_user_tool(&request, call, state)
                        } else if call.name == crate::plan_mode::PLAN_TOOL {
                            crate::plan_mode::run_plan_tool(&request, call, state)
                        } else if call.name == crate::plan_mode::EXIT_PLAN_MODE_TOOL {
                            crate::plan_mode::run_exit_plan_mode_tool(&request, call, state)
                        } else if crate::handoff::is_handoff_tool_name(&call.name) {
                            // A background agent or workflow reports back to
                            // this conversation, so `handoff` waits for it; a
                            // backgrounded shell may never end and does not
                            // hold it up.
                            let running = pool
                                .all()
                                .iter()
                                .filter(|task| {
                                    task.kind != SubagentRunKind::ShellCommand
                                        && task.status() == AgentLiveStatus::Running
                                })
                                .count();
                            crate::handoff::run_tool(&request, call, state, running)
                        } else {
                            // A foreground shell call gets a way out of its own
                            // deadline: rather than killing work the model asked
                            // for, the run is offered to this turn's task pool.
                            // Every other tool passes `None` and keeps the
                            // ordinary "runs until it returns" contract.
                            //
                            // Declared rather than built inline so the closure
                            // borrows the turn's state instead of moving it; it
                            // must not outlive this one call.
                            let shell_kind = tool_executor::ShellKind::of_tool(&call.name);
                            let shell_call_id = call.id.clone();
                            let shell_command =
                                tool_executor::parse_shell_command(&call.input).unwrap_or_default();
                            let shell_timeout = tool_executor::parse_shell_timeout(&call.input);
                            // The closure has to outlive the match that decides
                            // whether to use it, so the kind it captures is
                            // resolved here. The fallback is never reached: the
                            // handoff is handed on only when `shell_kind` is
                            // `Some`, and only a shell tool can invoke it.
                            let handoff_kind = shell_kind.unwrap_or(tool_executor::ShellKind::Bash);
                            let shell_handoff = |run, guard, context| {
                                adopt_timed_out_shell(
                                    pool,
                                    kernel_shadow,
                                    &request,
                                    &shell_call_id,
                                    handoff_kind,
                                    &shell_command,
                                    state,
                                    event_sink,
                                    round,
                                    run,
                                    guard,
                                    context,
                                    shell_timeout,
                                )
                            };
                            let handoff: Option<&tool_executor::ShellHandoff<'_>> =
                                shell_kind.is_some().then_some(&shell_handoff);
                            execute_model_tool_with_turn_states(
                                &request,
                                call,
                                state,
                                &mut structured_output_state,
                                &mut tool_search_state,
                                &shadowed_approval,
                                hook_allows_permission,
                                Some(&mut file_identities),
                                handoff,
                            )
                        }
                    };
                    reject_unusable_tool_images(&request, &mut execution);
                    // A file this call wrote is news for whichever language
                    // server holds it; its answer arrives at a later round
                    // boundary, through `inject_lsp_diagnostics`.
                    note_lsp_file_change(
                        &request,
                        &execution,
                        file_identities.file_touch.as_ref(),
                        state,
                    );
                    // Number surviving images before hooks, receipts, and
                    // events run, so every downstream consumer sees the final
                    // receipt with its `imageId` announcement.
                    assign_tool_image_short_ids(&request, &generated, &mut execution);

                    let mut post_tool_hook_ran = false;
                    if !rejected_before_execution {
                        let input = hook_input(
                            &request,
                            HookEvent::PostToolUse,
                            &turn_id,
                            json!({
                                "tool_name": execution.call.name,
                                "tool_use_id": execution.call.id,
                                "tool_input": execution.call.input.clone(),
                                "tool_response": execution.result.clone()
                            }),
                        );
                        let post_tool = run_hook_event(
                            &request,
                            &hook_services,
                            HookEvent::PostToolUse,
                            Some(&execution.call.name),
                            Some(execution.call.id.as_str()),
                            &input,
                            round,
                            &mut hook_budget,
                        )?;
                        post_tool_hook_ran = !post_tool.is_empty();
                        record_hook_outputs(&mut request, &mut generated, &post_tool);
                        hook_stops_turn |=
                            post_tool.iter().any(|execution| execution.decision.halt);
                        if let Some(reason) = hook_block_reason(&post_tool, &request.prompt_profile)
                        {
                            discard_blocked_tool_images(&mut execution);
                            let rolled_back =
                                if let Some((structured_checkpoint, search_checkpoint)) =
                                    orchestration_checkpoint
                                {
                                    // These tools have no external side effect, so a
                                    // blocking PostToolUse hook removes the attempted
                                    // change from this turn immediately. `tool_search`'s
                                    // whole effect is the schemas in its result, and
                                    // the model is about to be handed the block
                                    // reason instead.
                                    structured_output_state = structured_checkpoint;
                                    tool_search_state = search_checkpoint;
                                    true
                                } else {
                                    false
                                };
                            execution.result.success = false;
                            // PostToolUse runs after execution. For tools without
                            // rollback, report that the call executed and its result
                            // was rejected so the model does not retry a completed effect.
                            execution.result.output = if rolled_back {
                                reason
                            } else {
                                request.prompt_profile.render(
                                    PromptKey::HookPostToolNotRolledBack,
                                    &[("reason", &reason), ("tool", &execution.call.name)],
                                )
                            };
                        }
                    }
                    if let Some(project_memory) = project_memory_state.as_mut() {
                        project_memory.load_for_read(
                            &mut request,
                            &execution.call,
                            &execution.result,
                            file_identities.opened_read_file.as_ref(),
                            instructions_loaded.as_ref(),
                        )?;
                    }
                    // The read record is committed only now, against the final
                    // result: a read a PostToolUse hook blocked never reached the
                    // model, so it must not count as one. A write's record was
                    // taken by the executor, because the bytes are on disk
                    // whatever a hook says about them afterwards — but a hook
                    // that rewrote the file (a formatter) leaves that record
                    // behind the disk, which is what the re-sync repairs.
                    settle_file_guard_touch(
                        &mut request,
                        &execution,
                        file_identities.file_touch.take(),
                        post_tool_hook_ran,
                        state,
                    );
                    // Widen the wire tool set to whatever `tool_search` has
                    // handed out, after the PostToolUse hook has had its say: a
                    // blocked call was rolled back above, so this adds nothing.
                    // The next step re-derives its tools from `enabled_tools`,
                    // which is what makes a fetched schema callable rather than
                    // merely readable.
                    surface_deferred_tools(&mut request, &tool_search_state);
                    // Read after PostToolUse, which may have turned the result
                    // into a refusal.
                    let handed_off_now = execution.result.success
                        && execution.call.name == crate::handoff::HANDOFF_TOOL;
                    if execution.result.success
                        && matches!(
                            execution.call.name.as_str(),
                            crate::handoff::CREATE_NOTE_TOOL | crate::handoff::EDIT_NOTE_TOOL
                        )
                    {
                        request.handoff.note_written();
                    }
                    let dismissed_question = settle_tool_execution(
                        &request,
                        execution,
                        requested_input,
                        rejected_before_execution,
                        hook_allows_permission,
                        round,
                        &model_turn_id,
                        state,
                        pool,
                        kernel_shadow,
                        event_sink,
                        &mut generated,
                        &mut agent_context_ids,
                        &mut executions,
                    )?;
                    if hook_stops_turn {
                        for leftover in calls.by_ref() {
                            kernel_shadow.rejected_precheck(&leftover.id);
                            event_sink(ModelStreamEvent::ToolExecutionStarted {
                                round,
                                call_id: leftover.id.clone(),
                            })?;
                            let rejected = rejected_tool_execution(
                                &request,
                                leftover,
                                request
                                    .prompt_profile
                                    .text(PromptKey::HookInterruptedCallSkipped),
                                state,
                            );
                            event_sink(ModelStreamEvent::ToolExecutionCompleted {
                                round,
                                call_id: rejected.call.id.clone(),
                                result: rejected.result.clone(),
                            })?;
                            let context = tool_context_for_turn(
                                &rejected,
                                round,
                                &model_turn_id,
                                None,
                                &request.conversation_id,
                                &request.request_id,
                                state,
                            );
                            generated.push(context);
                            crate::history::record_tool_result(&request, round, &rejected);
                            executions.push(rejected);
                        }
                        stop_reason = Some("hook_stopped".into());
                        break;
                    }
                    // Nothing after a handoff or a closed question runs: the
                    // continuation is already working, or the user ended the
                    // turn by closing the question card.
                    let skipped = if handed_off_now {
                        handed_off = true;
                        crate::handoff::SKIPPED_AFTER_HANDOFF.to_owned()
                    } else if dismissed_question {
                        question_dismissed = true;
                        crate::ask_user::INTERRUPTED_CALL_SKIPPED.to_owned()
                    } else {
                        continue;
                    };
                    for leftover in calls.by_ref() {
                        kernel_shadow.rejected_precheck(&leftover.id);
                        event_sink(ModelStreamEvent::ToolExecutionStarted {
                            round,
                            call_id: leftover.id.clone(),
                        })?;
                        let rejected = rejected_tool_execution(&request, leftover, &skipped, state);
                        event_sink(ModelStreamEvent::ToolExecutionCompleted {
                            round,
                            call_id: rejected.call.id.clone(),
                            result: rejected.result.clone(),
                        })?;
                        let context = tool_context_for_turn(
                            &rejected,
                            round,
                            &model_turn_id,
                            None,
                            &request.conversation_id,
                            &request.request_id,
                            state,
                        );
                        generated.push(context);
                        crate::history::record_tool_result(&request, round, &rejected);
                        executions.push(rejected);
                    }
                }
                // Collect every search and fetch dispatched this round before the
                // next round. They have already run concurrently; placement outside
                // the loop and before `exchanges.push` prevents early exits from
                // stranding paid network calls.
                let mut collected = std::mem::take(&mut pending_async).into_iter();
                while let Some(pending) = collected.next() {
                    let requested_input = pending.requested_input.clone();
                    let pending_hook_allows_permission = pending.hook_allows_permission;
                    // This definition lock prevents concurrent saves between
                    // validation and side effects. It cannot revoke a request
                    // already sent, so completed results are delivered regardless.
                    let _definition_authority = current_agent_definition_authority(
                        &request,
                        state,
                        "Before collecting asynchronous tools",
                    )
                    .ok()
                    .flatten();
                    let mut execution = match collect_async_tool(pending, event_sink) {
                        Ok(execution) => execution,
                        Err(error) => {
                            // On user cancellation, abandon uncollected calls so
                            // detached workers stop network I/O at their 500ms probe.
                            for stranded in collected.by_ref() {
                                stranded.abandon.store(true, Ordering::Release);
                            }
                            return Err(error);
                        }
                    };
                    // PostToolUse requires actual results and therefore runs here.
                    // It cannot block same-round siblings already dispatched; these
                    // tools produce neither images nor event-sourced task checkpoints.
                    let input = hook_input(
                        &request,
                        HookEvent::PostToolUse,
                        &turn_id,
                        json!({
                            "tool_name": execution.call.name,
                            "tool_use_id": execution.call.id,
                            "tool_input": execution.call.input.clone(),
                            "tool_response": execution.result.clone()
                        }),
                    );
                    let post_tool = run_hook_event(
                        &request,
                        &hook_services,
                        HookEvent::PostToolUse,
                        Some(&execution.call.name),
                        Some(execution.call.id.as_str()),
                        &input,
                        round,
                        &mut hook_budget,
                    )?;
                    record_hook_outputs(&mut request, &mut generated, &post_tool);
                    if post_tool.iter().any(|execution| execution.decision.halt) {
                        stop_reason = Some("hook_stopped".into());
                    }
                    if let Some(reason) = hook_block_reason(&post_tool, &request.prompt_profile) {
                        execution.result.success = false;
                        execution.result.output = reason;
                    }
                    settle_tool_execution(
                        &request,
                        execution,
                        requested_input,
                        false,
                        pending_hook_allows_permission,
                        round,
                        &model_turn_id,
                        state,
                        pool,
                        kernel_shadow,
                        event_sink,
                        &mut generated,
                        &mut agent_context_ids,
                        &mut executions,
                    )?;
                }
                exchanges.push(Exchange::new(parsed.continuation, executions));
                // Verify all signed tool cards before deciding whether to begin the
                // next round; no post-tool early exit may discard them. A `task_wait` in
                // this batch may have carried a subagent's result; once its card is
                // confirmed, that agent no longer needs its ledger entry.
                if generated.checkpoint() {
                    settle_delivered_subagents(pool, &request, state);
                }
                if stop_reason.as_deref() == Some("hook_stopped") {
                    break;
                }
                if handed_off {
                    // The work goes on in the continuation; like a structured
                    // result, the tool receipts of this round are not sent back.
                    stop_reason = Some(crate::handoff::STOP_REASON.into());
                    break;
                }
                if question_dismissed {
                    // The user closed the question card instead of answering it.
                    // The turn ends without another request and without a final
                    // assistant message; Stop hooks stay out of it because the
                    // agent has not finished its turn.
                    stop_reason = Some(crate::ask_user::QUESTION_CLOSED_STOP_REASON.into());
                    break;
                }
                // A structured result ends only the next round. Execute and retain
                // all parallel tool calls from this round, then skip sending their
                // results back to the model.
                //
                // Read `value` directly. Blocking PostToolUse rolls the dispatch
                // value back with its orchestration checkpoint, leaving `None`.
                //
                // Project this as cancellation because tool receipts will not be
                // delivered and `roundDue` remains set. `TurnCancel` discharges that
                // obligation while the run itself remains completed.
                if structured_output_state.value.is_some() {
                    stop_reason = Some(STRUCTURED_OUTPUT_STOP_REASON.into());
                    break;
                }
                // Checked after PostToolUse has had its say, so an attempt a
                // blocking hook rolled back does not count against the cap.
                if structured_output_state.exhausted() {
                    generated.push(assistant_context(request.prompt_profile.render(
                        PromptKey::SubagentStructuredOutputExhausted,
                        &[("max_attempts", &MAX_STRUCTURED_OUTPUT_ATTEMPTS.to_string())],
                    )));
                    stop_reason = Some("structured_output_retry_limit".into());
                    break;
                }
            }
            Ok(())
        })();
        if request.subagent_depth == 0 {
            if let Some(offered) = offered_tools.take() {
                state
                    .offered_tools
                    .record(&request.conversation_id, offered);
            }
        }
        // A notice queued as the turn ended — a Stop hook's context on the last
        // round — never met another loop head. It still joins the transcript,
        // where the next turn's first request carries it.
        if !request.host_notices.is_empty() {
            sync_generated_contexts(&mut request, &generated, &mut generated_checkpoint);
            deliver_host_notices(&mut request, state, last_round, &mut [], &mut generated);
        }
        // Loop exit never interrupts running session tasks. Foldable results are
        // delivered on a normal delivery round; uncollected results after abort
        // remain for the next round. Finalization merges usage and backfills only
        // terminal records.
        //
        // Finalize the shadow kernel. Cancellation, early stop, and stream errors
        // project through the abort path; call `turn_aborting` before finalization
        // to settle executing calls and close the in-flight round.
        // Read cancellation by ownership: top-level rounds use this run's signal,
        // task rounds use the task signal. A conversation-wide lookup can observe
        // an unrelated foreground run and corrupt task settlement.
        let round_cancel = request.round_cancellation();
        let run_cancelled = round_cancel.cancelled();
        let turn_aborted = run_cancelled || loop_outcome.is_err() || stop_reason.is_some();
        if turn_aborted {
            kernel_shadow.turn_aborting();
        } else {
            // Settling loop exit closes the final round; later fold occurs in prep.
            kernel_shadow.round_boundary();
        }
        // A child run's private pool ends with the child round. Its long work is
        // settled as interrupted during finalization; the top-level pool is excluded.
        if conversation_tasks.is_none() && !pool.is_empty() {
            pool.await_quiescence();
        }
        finalize_agent_pool(pool, &mut generated, &mut usage, &agent_context_ids);
        record_generated_subagent_receipts(&request, &mut generated, state);
        // A cancellation raised during finalization also follows abort settlement
        // using the same ownership-derived signal.
        let late_cancelled = round_cancel.cancelled();
        kernel_shadow.turn_finished(turn_aborted || late_cancelled);
        loop_outcome
    };
    // Persist the projection prefix for the next turn regardless of how the
    // loop ended: the projected history mirrors the timeline, not the outcome.
    wire_history::store_session(wire_session, std::mem::take(&mut request.contexts));
    let run_cancelled = request.round_cancellation().cancelled();
    if run_cancelled {
        // The round's own stop flag is the trusted distinction between a user
        // stop and an arbitrary dead event sink — for a top-level round the
        // flag `begin_model_run` minted, for a task round the task's own flag
        // (its sidebar stop). Teardown above has already joined the
        // turn-scoped workers, finalized their records, and minted receipts;
        // return that settlement instead of discarding it through `turn?`. A
        // sink failure without this flag remains an ordinary error.
        stop_reason = Some("cancelled".into());
    } else {
        turn?;
    }

    Ok(run_response(
        &request,
        generated.into_items(),
        usage,
        response_model,
        started,
        context_tokens,
        stop_reason,
        run_error,
        structured_output_state.value,
    ))
}

/// Arms the conversation to hand off once its context crosses the auto-compact
/// threshold (`handoff.rs`), checked at every round boundary, the first one
/// included.
///
/// The measure is the context the next request carries: the latest response's
/// reported input and output, everything that has joined the transcript since
/// (`ContextMeasure`), and what the host has queued to say at this boundary.
/// Before this run has a response, it is the conversation's latest recorded
/// request plus an estimate of what the user added since.
///
/// The boundary is the only place the instruction can go, so the check follows the
/// provider's operations: a response's parallel calls all settle before it,
/// and the steps of one logical turn (`pause_turn`, a truncated output's
/// continuation) never reach it in between.
///
/// Arming is a flag the tool derivation reads, set here, and one instruction
/// asking the model to hand off, returned for the loop head to deliver behind
/// the boundary's notices by the carrier the model has for an instruction
/// (`deliver_instruction`). Nothing is sent or summarized on the model's
/// behalf: it writes its notes and calls `handoff` itself.
fn arm_handoff_at_boundary(
    request: &mut RunModelRequest,
    state: &AppState,
    measure: &ContextMeasure,
    generated: &[ContextItem],
) -> Option<Instruction> {
    if !request.handoff.can_arm() || request.request_id.is_empty() {
        return None;
    }
    // Arming hands the model four tools mid-run; a model whose protocol cannot
    // append them never arms, which is why auto-compact is unavailable for it.
    if !crate::tool_append::appends_tools(&request.provider, &request.model) {
        return None;
    }
    let window = request.model.context_window.filter(|window| *window > 0)?;
    let anchor = Path::new(&request.app_data_path).join("document.v1.json");
    let document = state.document_store.current_snapshot(&anchor).ok()?;
    let settings = document.global_settings.auto_compact.clone();
    drop(document);
    if !settings.enabled {
        return None;
    }
    let threshold = crate::handoff::threshold_tokens(window, settings.threshold_percent);
    let measured = match measure.current(generated) {
        Some(tokens) => tokens,
        None => {
            let recorded = crate::token_ledger::store_for(&anchor)
                .and_then(|ledger| ledger.last_conversation_context(&request.conversation_id))
                .ok()
                .flatten()?;
            // What the user added since that request: the trailing messages
            // no model turn has answered yet.
            request
                .contexts
                .iter()
                .rev()
                .take_while(|context| {
                    matches!(
                        context,
                        ContextItem::User { .. } | ContextItem::System { .. }
                    )
                })
                .map(estimate_context_tokens)
                .fold(recorded, u64::saturating_add)
        }
    };
    // What the host has queued to say at this boundary goes out in the same
    // request, right ahead of this instruction.
    let used = request
        .host_notices
        .iter()
        .map(|notice| {
            estimate_tokens(&notice.summary).saturating_add(estimate_tokens(&notice.body))
        })
        .fold(measured, u64::saturating_add);
    if used < threshold {
        return None;
    }
    request.handoff.arm();
    let notice = crate::handoff::notice(&request.prompt_profile);
    Some(Instruction {
        topic: crate::handoff::ARMED_TOPIC,
        notice_kind: notice.kind,
        summary: notice.summary,
        notice_id: notice.id,
        content: notice.body,
    })
}

/// How large the context a run's next request carries is, as messages join
/// it: the provider's own count at the latest response, plus each message the
/// transcript has gained since.
///
/// A provider counts a request only once it has it, so the results of the
/// calls a response made — and whatever else joins before the next request —
/// are in no count yet. Waiting for the next response to report them leaves a
/// large tool result unmeasured for a whole request. Each one is priced the
/// way the composer's gauge prices it, until the next response's count
/// replaces the estimate.
#[derive(Default)]
struct ContextMeasure {
    /// Input plus output of the latest response, as its provider reported them.
    reported: Option<u64>,
    /// That response's model turn: what it wrote is in its output already.
    model_turn_id: String,
    /// How many items the run had generated when it was reported. The ones
    /// after it are what joined since.
    generated_at: usize,
}

impl ContextMeasure {
    fn report(&mut self, reported: Option<u64>, model_turn_id: &str, generated_at: usize) {
        self.reported = reported;
        self.model_turn_id = model_turn_id.to_owned();
        self.generated_at = generated_at;
    }

    /// `None` until a response of this run has reported both counts.
    fn current(&self, generated: &[ContextItem]) -> Option<u64> {
        let reported = self.reported?;
        Some(
            generated
                .get(self.generated_at..)
                .unwrap_or_default()
                .iter()
                .map(|item| context_growth_tokens(item, &self.model_turn_id))
                .fold(reported, u64::saturating_add),
        )
    }
}

/// What `item` adds beyond the output of the response `model_turn_id` names.
/// That response's prose, reasoning and calls are in its output, so of its
/// calls only the result is new; anything else joins whole.
fn context_growth_tokens(item: &ContextItem, model_turn_id: &str) -> u64 {
    let answered = |turn: &Option<String>| turn.as_deref() == Some(model_turn_id);
    match item {
        ContextItem::Assistant {
            model_turn_id: turn,
            ..
        }
        | ContextItem::Reasoning {
            model_turn_id: turn,
            ..
        } if answered(turn) => 0,
        ContextItem::Tool {
            model_turn_id: turn,
            result,
            ..
        } if answered(turn) => estimate_tokens(&result.output)
            .saturating_add(estimate_images_tokens(&result.images)),
        item => estimate_context_tokens(item),
    }
}

/// One context priced the way the composer's gauge prices it
/// (`contextTokens.ts::estimateContextTokens`). A host-only record adds nothing.
fn estimate_context_tokens(item: &ContextItem) -> u64 {
    match item {
        ContextItem::System {
            local_only: true, ..
        } => 0,
        ContextItem::System { content, .. } | ContextItem::Assistant { content, .. } => {
            estimate_tokens(content)
        }
        ContextItem::User {
            content,
            images,
            files,
            ..
        } => files.iter().map(|file| file.tokens).fold(
            estimate_tokens(content).saturating_add(estimate_images_tokens(images)),
            u64::saturating_add,
        ),
        ContextItem::Reasoning { content, .. } => {
            estimate_tokens(&format!("[Reasoning]\n{}", content.as_deref().unwrap_or_default()))
        }
        ContextItem::Tool {
            tool_name,
            input,
            result,
            ..
        } => estimate_tokens(&format!(
            "{tool_name}\n{}\n{}",
            serde_json::to_string(input).unwrap_or_default(),
            result.output
        ))
        .saturating_add(estimate_images_tokens(&result.images)),
    }
}

/// Images priced as the gauge prices them: 170 tokens a 512-pixel tile plus
/// 85, never under 1,024, and 1,024 for one whose size is unknown.
fn estimate_images_tokens(images: &[crate::model::ImageAttachment]) -> u64 {
    images
        .iter()
        .map(|image| {
            if image.width == 0 || image.height == 0 {
                return 1_024;
            }
            let tiles =
                u64::from(image.width.div_ceil(512)) * u64::from(image.height.div_ceil(512));
            (85 + tiles * 170).max(1_024)
        })
        .fold(0, u64::saturating_add)
}

/// Shared settlement tail for a tool call: receipt fingerprint, timeline card,
/// completion event, shadow `ToolSettle`, and `executions` entry.
/// Synchronous and asynchronous paths must use this single tail to prevent their
/// attestation, receipt, and shadow accounting from drifting.
/// Returns whether this call was an `ask_user` card the user dismissed, which
/// interrupts the turn. Determined after PostToolUse, from the final result.
#[allow(clippy::too_many_arguments)]
fn settle_tool_execution(
    request: &RunModelRequest,
    execution: ToolExecution,
    requested_input: JsonObject,
    rejected_before_execution: bool,
    hook_allows_permission: bool,
    round: usize,
    model_turn_id: &str,
    state: &AppState,
    pool: &AgentPool,
    kernel_shadow: &crate::kernel_shadow::KernelShadow,
    event_sink: &ModelEventSink<'_>,
    generated: &mut GeneratedContexts,
    agent_context_ids: &mut HashMap<String, String>,
    executions: &mut Vec<ToolExecution>,
) -> Result<bool, String> {
    let requested_input = (requested_input != execution.call.input).then_some(requested_input);
    let public_requested_input = requested_input
        .as_ref()
        .map(|input| public_tool_input(&execution.call.name, input));
    let receipt_request = ToolExecutionRequest {
        conversation_id: request.conversation_id.clone(),
        workspace_path: request.workspace_path.clone(),
        tool_name: execution.call.name.clone(),
        input: public_tool_input(&execution.call.name, &execution.call.input),
    };
    let context = tool_context_for_turn(
        &execution,
        round,
        model_turn_id,
        requested_input.as_ref(),
        &request.conversation_id,
        &request.request_id,
        state,
    );
    state.record_context_receipt(
        &receipt_request,
        &execution.result,
        public_requested_input.as_ref(),
    );
    event_sink(ModelStreamEvent::ToolExecutionCompleted {
        round,
        call_id: execution.call.id.clone(),
        result: execution.result.clone(),
    })?;
    if !execution.result.success {
        crate::helper_model::uses::on_tool_failed(
            state,
            request,
            &execution.call.id,
            &execution.call.name,
            &execution.result.output,
            context.id(),
        );
    }
    if tool_execution_owns_subagent_record(&execution) {
        agent_context_ids.insert(execution.call.id.clone(), context.id().to_owned());
        // Return the timeline context id to this task. The request-local call-to-
        // context map expires, while a cross-round task needs it for record backfill.
        if let Some(shared) = pool.find_by_latest_call(&execution.call.id) {
            shared.record_call_context(&execution.call.id, context.id());
        }
    }
    generated.push(context);
    kernel_shadow.tool_finished(
        &execution.call.id,
        rejected_before_execution,
        hook_allows_permission,
        execution.result.success,
        crate::kernel_shadow::call_params_digest(&execution.call.input),
    );
    // A message steered in while the card was up is what closed it; it follows
    // the result into the next round rather than the turn ending here.
    let steer_pending = request
        .steer_mailbox
        .0
        .as_ref()
        .is_some_and(|mailbox| !mailbox.is_empty());
    let dismissed_question = crate::ask_user::ends_turn(&execution, steer_pending);
    crate::history::record_tool_result(request, round, &execution);
    executions.push(execution);
    Ok(dismissed_question)
}

/// Applies a profile's `tools[]` entry to a description the host did not author.
///
/// Built-in tools take their description from the registry, so `schema_notes`
/// reaches them by overriding a `PromptKey`. An MCP tool has no such key: the
/// text came from the remote server. This is where that column is overridden
/// instead — `schema_notes` replaces the server's wording and `usage_guidance`
/// is appended below it, so a profile can annotate a tool without discarding
/// what the server said about it.
fn apply_profile_tool_override(
    profile: &crate::prompt_profile::PromptProfile,
    tool_name: &str,
    base: String,
) -> String {
    let Some(entry) = profile
        .tools
        .iter()
        .find(|entry| entry.tool_name.trim() == tool_name)
    else {
        return base;
    };
    let mut description = if entry.schema_notes.trim().is_empty() {
        base
    } else {
        entry.schema_notes.clone()
    };
    if !entry.usage_guidance.trim().is_empty() {
        if !description.trim().is_empty() {
            description.push_str("\n\n");
        }
        description.push_str(&entry.usage_guidance);
    }
    description
}

fn attach_mcp_tools(request: &mut RunModelRequest, state: &AppState) -> Result<(), String> {
    if request.mcp_servers.is_empty() || !request.mcp_bindings.is_empty() {
        // Nothing to dial, or a child that inherited its parent's bindings —
        // either way the deferral decision still has to be made, if only to
        // strip a `tool_search` this run has nothing to hand out for.
        defer_mcp_tools(request);
        return Ok(());
    }
    // The caller holds definition_authority_lock across validation and discovery.
    // Resolve from the trusted binding, not the already-filtered enabled catalog:
    // empty parent discovery may become nonempty on a fresh or resumed child.
    let role_policy = if let Some(binding) = request.agent_definition_binding.as_ref() {
        validate_current_agent_definition(request, state)?;
        let document = current_agent_document(request, state)?;
        let definition = resolve_agent_definition(
            &document,
            request_agent_definitions(&document, request),
            &request.workspace_id,
            &binding.name,
        )?;
        Some(AgentRunOverrides::from_definition(definition))
    } else {
        None
    };
    let report = state.mcp_sessions.discover_for_conversation(
        &request.conversation_id,
        &request.mcp_servers,
        // Use ownership-derived cancellation: task rounds observe task cancellation
        // and top-level rounds observe this run's cancellation only.
        request.round_cancellation(),
    );
    for failure in &report.failures {
        eprintln!(
            "MCP 工具探测失败，已隔离该服务（server_id={}，server_name={}，kind={:?}）：{}",
            failure.server_id, failure.server_name, failure.kind, failure.message
        );
    }
    let mut names = request
        .tools
        .iter()
        .map(|tool| tool.name.clone())
        .collect::<HashSet<_>>();
    let mut bindings = Vec::new();
    for binding in report.bindings {
        if role_policy
            .as_ref()
            .is_some_and(|policy| !policy.permits_tool(&binding.exposed_name))
        {
            continue;
        }
        if !names.insert(binding.exposed_name.clone()) {
            eprintln!(
                "MCP 工具名称与现有工具冲突，已隔离该工具（server_id={}，tool_name={}）",
                binding.server.server_id, binding.exposed_name
            );
            continue;
        }
        request.enabled_tools.push(binding.exposed_name.clone());
        let mandatory_notice = binding
            .requires_user_interaction
            .then_some(" (remote declaration: every call needs manual confirmation)")
            .unwrap_or_default();
        let description = if binding.confirmation_required() {
            format!(
                "{}{}",
                request
                    .prompt_profile
                    .text(PromptKey::McpMandatoryDescriptionPrefix),
                binding.description
            )
        } else {
            binding.description.clone()
        };
        // MCP tools are discovered per run, so they miss the catalog merge in
        // `lib::tool_catalog_with_descriptions` and have no registry key of their
        // own — their description belongs to the server that declared it. Apply
        // the profile's override here instead, with the same rule the built-ins
        // get: `schemaNotes` replaces, `usageGuidance` is appended.
        let description = apply_profile_tool_override(
            &request.prompt_profile,
            &binding.exposed_name,
            description,
        );
        request.tools.push(ToolDescriptor {
            force_confirmation: false,
            name: binding.exposed_name.clone(),
            label: format!(
                "MCP {} / {}{}",
                binding.server.name, binding.title, mandatory_notice
            ),
            description,
            category: ToolCategory::Mcp,
            dangerous: true,
            parameters: Vec::new(),
            input_schema: Some(binding.input_schema.clone()),
        });
        bindings.push(binding);
    }
    request.enabled_tools.sort();
    request.enabled_tools.dedup();
    request.mcp_bindings = bindings;
    defer_mcp_tools(request);
    Ok(())
}

/// Withholds the MCP tools' schemas from the wire and announces their names.
///
/// This runs after discovery rather than inside it because the names only exist
/// once the servers answer. Three things happen together, and they have to:
///
/// - every MCP name leaves `enabled_tools`, which is what `aisdk::tools::enabled_tools`
///   filters the wire tool set by, so the schemas stop being declared;
/// - the descriptors stay in `request.tools`, because they are what the
///   executor dispatches against and what `tool_search` hands out;
/// - `tool_search` is derived in and the announcement is built, because a name
///   nobody has heard of is a capability that does not exist.
///
/// The announcement is fixed for the run. It sits at the head of every step, so
/// a list that moved as tools were fetched would evict the whole prompt cache
/// once per round; a name that stays listed after its schema arrives costs one
/// line and confuses nothing, since the schema is right there in the tool set.
fn defer_mcp_tools(request: &mut RunModelRequest) {
    request.deferred_tools.clear();
    if !request.mcp_tool_discovery || request.mcp_bindings.is_empty() {
        // Still strip a stale name: `tool_search` is in the catalog, so a
        // conversation that turned discovery off could otherwise carry it.
        crate::capabilities::apply_tool_search_tool(&mut request.enabled_tools, 0);
        return;
    }
    let deferred = request
        .mcp_bindings
        .iter()
        .map(|binding| crate::model::DeferredTool {
            name: binding.exposed_name.clone(),
            server_name: binding.server.name.clone(),
        })
        .collect::<Vec<_>>();
    let withheld = deferred
        .iter()
        .map(|tool| tool.name.as_str())
        .collect::<HashSet<_>>();
    request
        .enabled_tools
        .retain(|name| !withheld.contains(name.as_str()));
    crate::capabilities::apply_tool_search_tool(&mut request.enabled_tools, deferred.len());
    request.enabled_tools.sort();
    request.enabled_tools.dedup();
    let announcement = render_deferred_tool_announcement(&request.prompt_profile, &deferred);
    request.deferred_tools = deferred;
    request.ephemeral_contexts.push(ContextItem::User {
        id: format!("ctx_ephemeral_deferred_tools_{}", Uuid::new_v4().simple()),
        content: announcement,
        images: Vec::new(),
        files: Vec::new(),
        created_at: Utc::now().to_rfc3339(),
    });
}

/// The announcement text: one row per server, each listing that server's
/// withheld tool names in discovery order.
fn render_deferred_tool_announcement(
    profile: &PromptProfile,
    deferred: &[crate::model::DeferredTool],
) -> String {
    // `Vec` of pairs rather than a map: discovery order is the order the user
    // selected the servers in, and a map would sort it into something else.
    let mut grouped: Vec<(&str, Vec<&str>)> = Vec::new();
    for tool in deferred {
        match grouped
            .iter_mut()
            .find(|(server, _)| *server == tool.server_name)
        {
            Some((_, names)) => names.push(&tool.name),
            None => grouped.push((&tool.server_name, vec![&tool.name])),
        }
    }
    let rows = grouped
        .into_iter()
        .map(|(server, names)| {
            profile.render(
                PromptKey::ToolSearchAnnouncementRow,
                &[("server", server), ("names", &names.join(", "))],
            )
        })
        .collect::<Vec<_>>();
    profile.render(
        PromptKey::ToolSearchAnnouncement,
        &[("tools", &rows.join("\n"))],
    )
}

fn discard_blocked_tool_images(execution: &mut ToolExecution) {
    execution.result.images.clear();
}

/// A tool's images reach a model only if it takes images; for one that does
/// not, the images are dropped and the result says why.
fn reject_unusable_tool_images(request: &RunModelRequest, execution: &mut ToolExecution) {
    if execution.result.images.is_empty() || request.model.supports_vision() {
        return;
    }
    execution.result.output = format!(
        "Tool {} ran and returned {} images, but the current model {} does not support image input; the images were not added to context. Switch to a vision-capable model and retry.",
        execution.call.name,
        execution.result.images.len(),
        request.model.id
    );
    execution.result.images.clear();
    execution.result.success = false;
}

/// Parses every well-formed `[Image #N]` placeholder in user-authored text.
/// The scan mirrors `src/lib/imageShortIds.ts`: a placeholder is the literal
/// prefix, 1–9 ASCII digits, and a closing bracket, with no whitespace inside.
fn image_placeholder_ids(text: &str) -> Vec<u32> {
    const PREFIX: &str = "[Image #";
    let mut ids = Vec::new();
    let mut rest = text;
    while let Some(start) = rest.find(PREFIX) {
        rest = &rest[start + PREFIX.len()..];
        let digits = rest.bytes().take_while(u8::is_ascii_digit).count();
        if (1..=9).contains(&digits) && rest.as_bytes().get(digits) == Some(&b']') {
            if let Ok(id) = rest[..digits].parse::<u32>() {
                if id >= 1 {
                    ids.push(id);
                }
            }
        }
    }
    ids
}

/// Collects every image number already spoken for in the given contexts:
/// stored `short_id`s on user and tool images plus literal `[Image #N]`
/// placeholders in user text. Placeholders count even when their image is
/// gone, so a number the model may still be reading about is never reissued.
fn image_short_ids_in_use<'a>(
    contexts: impl Iterator<Item = &'a ContextItem>,
) -> std::collections::HashSet<u32> {
    let mut taken = std::collections::HashSet::new();
    for context in contexts {
        match context {
            ContextItem::User {
                content, images, ..
            } => {
                taken.extend(images.iter().filter_map(|image| image.short_id));
                taken.extend(image_placeholder_ids(content));
            }
            ContextItem::Tool { result, .. } => {
                taken.extend(result.images.iter().filter_map(|image| image.short_id));
            }
            _ => {}
        }
    }
    taken
}

/// Assigns fresh `[Image #N]` numbers to a tool result's images and announces
/// them in the receipt so the model can cite a screenshot in
/// `preview_upload_image`.
fn assign_tool_image_short_ids(
    request: &RunModelRequest,
    generated: &[ContextItem],
    execution: &mut ToolExecution,
) {
    if execution
        .result
        .images
        .iter()
        .all(|image| image.short_id.is_some())
    {
        return;
    }
    let taken = image_short_ids_in_use(
        request
            .ephemeral_contexts
            .iter()
            .chain(request.contexts.iter())
            .chain(generated.iter()),
    );
    let mut next = taken.iter().copied().max().unwrap_or(0).saturating_add(1);
    let mut assigned = Vec::new();
    for image in &mut execution.result.images {
        if image.short_id.is_none() {
            image.short_id = Some(next);
            assigned.push(next);
            next = next.saturating_add(1);
        }
    }
    announce_image_short_ids(&mut execution.result.output, &assigned);
}

/// Adds allocated numbers to a JSON-object receipt as `imageId` (single) or
/// `imageIds` (several); non-JSON output gets literal `[Image #N]` lines
/// appended instead.
fn announce_image_short_ids(output: &mut String, assigned: &[u32]) {
    if assigned.is_empty() {
        return;
    }
    if let Ok(Value::Object(mut object)) = serde_json::from_str::<Value>(output) {
        if let [single] = assigned {
            object.insert("imageId".into(), json!(single));
        } else {
            object.insert("imageIds".into(), json!(assigned));
        }
        if let Ok(serialized) = serde_json::to_string_pretty(&Value::Object(object)) {
            *output = serialized;
            return;
        }
    }
    for id in assigned {
        output.push_str(&format!("\n[Image #{id}]"));
    }
}

/// Renumbers a steered or queued user message whose `[Image #N]` numbers were
/// allocated by the renderer before this turn advanced. Any number that is
/// missing or already taken in the live transcript gets a fresh one, and the
/// literal placeholders in the text are rewritten to match, so the model never
/// sees two images sharing a number.
fn renumber_user_message_images(
    request: &RunModelRequest,
    generated: &[ContextItem],
    content: &mut String,
    images: &mut [crate::model::ImageAttachment],
) {
    if images.is_empty() {
        return;
    }
    let mut taken = image_short_ids_in_use(
        request
            .ephemeral_contexts
            .iter()
            .chain(request.contexts.iter())
            .chain(generated.iter()),
    );
    // Reserve every non-colliding draft number first, so a fresh number can
    // never land on one another image in this message still holds — that
    // would make the later rewrite corrupt the earlier image's placeholder.
    let keeps: Vec<bool> = images
        .iter()
        .map(|image| match image.short_id {
            Some(id) => taken.insert(id),
            None => false,
        })
        .collect();
    let mut next = taken.iter().copied().max().unwrap_or(0).saturating_add(1);
    for (image, keep) in images.iter_mut().zip(keeps) {
        if keep {
            continue;
        }
        while !taken.insert(next) {
            next = next.saturating_add(1);
        }
        if let Some(previous) = image.short_id {
            *content =
                content.replace(&format!("[Image #{previous}]"), &format!("[Image #{next}]"));
        }
        image.short_id = Some(next);
        next = next.saturating_add(1);
    }
}

/// Cheap, deterministic fallback estimator shared with the frontend mirror
/// (`src/lib/contextTokens.ts`); the unit test pins the exact vectors so the
/// two implementations cannot drift apart silently. File attachments record
/// their size with it at upload, so the renderer can show it without the text.
pub fn estimate_tokens(text: &str) -> u64 {
    let (ascii, non_ascii) = text.chars().fold((0_u64, 0_u64), |(ascii, non_ascii), ch| {
        if ch.is_ascii() {
            (ascii + 1, non_ascii)
        } else {
            (ascii, non_ascii + 1)
        }
    });
    ((ascii as f64 / 4.0) + (non_ascii as f64 / 1.6)).ceil() as u64
}

#[allow(clippy::too_many_arguments)]
fn run_response(
    request: &RunModelRequest,
    contexts: Vec<ContextItem>,
    usage: ModelUsage,
    model: String,
    started: Instant,
    context_tokens: Option<u64>,
    stop_reason: Option<String>,
    error: Option<ModelRunError>,
    structured_output: Option<Value>,
) -> RunModelResponse {
    RunModelResponse {
        contexts,
        usage,
        model,
        provider_name: request.provider.name.clone(),
        duration_ms: started.elapsed().as_millis().min(u64::MAX as u128) as u64,
        context_tokens,
        stop_reason,
        error,
        structured_output,
    }
}

fn validate_run_request(request: &RunModelRequest) -> Result<(), String> {
    validate_provider(&request.provider)?;
    if !request.provider.enabled {
        return Err(format!("API 提供商 {} 已停用", request.provider.name));
    }
    if request.model.id.trim().is_empty() {
        return Err("模型 ID 不能为空".into());
    }
    if request.workspace_path.trim().is_empty() {
        return Err("工作区路径不能为空".into());
    }
    if request.app_data_path.trim().is_empty() {
        return Err("模型运行缺少可信的应用数据目录".into());
    }
    let descriptor_names = request
        .tools
        .iter()
        .map(|tool| tool.name.as_str())
        .collect::<HashSet<_>>();
    if request
        .enabled_tools
        .iter()
        .any(|name| !descriptor_names.contains(name.as_str()))
    {
        return Err("启用工具列表包含未知工具".into());
    }
    // Fail before endpoint/credential setup and before any hook can cause
    // network or filesystem activity.
    Ok(())
}

/// Test-only convenience wrapper: the retry/streaming loop with no policy
/// barriers. Production sends always go through
/// `post_model_request_with_validator`.
#[cfg(test)]
fn post_model_request(
    step: &crate::aisdk::protocol::StepRequest,
    key: Option<&str>,
    round: usize,
    event_sink: &ModelEventSink<'_>,
) -> Result<ParsedModelResponse, ExhaustedRequest> {
    post_model_request_with_validator(
        step,
        key,
        round,
        event_sink,
        None,
        &|| Ok(()),
        None,
        &|| Ok(()),
        None,
        None,
    )
}

/// Issues one model request with bounded automatic retries on transient
/// failures. Each retry is announced through the sink (so the renderer can
/// discard the failed attempt's partial round and show a temporary notice),
/// backoff waits stay cancellable via `Ping` probes, and the terminal failure
/// carries the last streamed partial so callers can keep it in the timeline.
/// Host-owned policy barriers run immediately before every HTTP attempt
/// (initial, pause/tool continuation, and retry). The named-agent
/// definition is revalidated while its read fence is held, followed by
/// memory/import trust, so any stale capability fails before debug-body
/// publication and `request.send()`.
///
/// Built-in gateway accounting point. A required `Option` makes every request
/// caller choose an owner, so a new caller cannot silently omit accounting.
///
/// The history takes the same shape for the same reason: `wire` is recorded once
/// per attempt, immediately before the payload goes out, so a send that the
/// transport then loses still leaves an entry, and once per parsed response,
/// before it is returned, so what came back is on disk before anything acts on it.
/// A caller with nothing to record — a bare test state — passes `None` explicitly.
fn post_model_request_with_validator(
    step: &crate::aisdk::protocol::StepRequest,
    key: Option<&str>,
    round: usize,
    event_sink: &ModelEventSink<'_>,
    attempt_definition_authority: Option<&RwLock<()>>,
    validate_definition_before_send: &dyn Fn() -> Result<(), String>,
    attempt_project_import_authority: Option<&RwLock<()>>,
    validate_before_attempt: &dyn Fn() -> Result<(), String>,
    ledger: Option<&crate::token_ledger::GatewayRecorder>,
    wire: Option<&crate::history::RequestRecorder>,
) -> Result<ParsedModelResponse, ExhaustedRequest> {
    let mut kept_partial = StreamPartial::default();
    let mut attempts = 0_u32;
    loop {
        attempts += 1;
        let failure = match post_model_request_once(
            step,
            key,
            round,
            event_sink,
            attempt_definition_authority,
            validate_definition_before_send,
            attempt_project_import_authority,
            validate_before_attempt,
            wire,
        ) {
            Ok(parsed) => {
                // Record one ledger row per successfully parsed response. Failed
                // attempts carry no usage, and guessing is worse than omission.
                // The history's response entry carries the usage for the same
                // reason: the request entry was written before the send, when
                // what it would cost was still unknown, and only the attempt that
                // came back with a parsed response has counters — the ones that
                // failed have no response entry, which is the truth about them.
                if let Some(ledger) = ledger {
                    ledger.record(&parsed.usage);
                }
                if let Some(wire) = wire {
                    // Before returning, so nothing the model said is acted on —
                    // no call dispatched, no reply delivered — without a record
                    // of it, and of what it cost, that outlives this process.
                    wire.record_response(&parsed);
                }
                return Ok(parsed);
            }
            Err(failure) => failure,
        };
        // Keep the newest attempt that actually streamed content — the same
        // content the renderer last displayed for this round.
        if !failure.partial.is_empty() {
            kept_partial = failure.partial;
        }
        let retryable = matches!(failure.error, ModelRequestError::Api(_));
        if !retryable || attempts > MODEL_REQUEST_MAX_RETRIES {
            return Err(ExhaustedRequest {
                error: failure.error,
                attempts,
                partial: kept_partial,
            });
        }
        let delay = retry_delay_with_hint(retry_backoff_delay(attempts), failure.retry_after_ms);
        let announced = event_sink(ModelStreamEvent::StreamRetryScheduled {
            round,
            attempt: attempts,
            max_attempts: MODEL_REQUEST_MAX_RETRIES,
            delay_ms: delay.as_millis().min(u64::MAX as u128) as u64,
            message: failure.error.message().to_owned(),
        })
        .and_then(|()| probe_sleep(delay, event_sink));
        if let Err(sink_error) = announced {
            return Err(ExhaustedRequest {
                error: ModelRequestError::EventSink(sink_error),
                attempts,
                partial: kept_partial,
            });
        }
    }
}

/// Dev-only request-body dumps are opt-in: they cost several full-body
/// serializations plus an IPC round trip per model round.
#[cfg(debug_assertions)]
fn debug_model_body_enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        std::env::var(DEBUG_MODEL_BODY_ENV)
            .or_else(|_| std::env::var(LEGACY_DEBUG_MODEL_BODY_ENV))
            .is_ok_and(|value| !value.is_empty() && value != "0")
    })
}

/// Single request attempt. Failures are classified (`Api` = transient,
/// `Fatal` = permanent) and carry the partial streamed content, with provider
/// keys already scrubbed from every message.
///
/// Dispatch writes a frame to sidecar stdin, not `request.send()`. `submit`
/// returning means the frame has left, so authorization read locks can be released
/// without holding definition edits for the full response.
fn post_model_request_once(
    step: &crate::aisdk::protocol::StepRequest,
    key: Option<&str>,
    round: usize,
    event_sink: &ModelEventSink<'_>,
    attempt_definition_authority: Option<&RwLock<()>>,
    validate_definition_before_send: &dyn Fn() -> Result<(), String>,
    attempt_project_import_authority: Option<&RwLock<()>>,
    validate_before_send: &dyn Fn() -> Result<(), String>,
    wire: Option<&crate::history::RequestRecorder>,
) -> Result<ParsedModelResponse, RequestFailure> {
    // Definition mutations take this gate's write side. Revalidate only after
    // acquiring the read side and retain it through the submit, so a completed
    // revoke cannot race a stale named-agent request onto the wire.
    let definition_authority = attempt_definition_authority
        .map(|lock| {
            lock.read()
                .map_err(|_| "Named-agent definition authority lock is poisoned; the model request was not sent.".to_owned())
        })
        .transpose()
        .map_err(|error| RequestFailure::bare(ModelRequestError::Fatal(error)))?;
    validate_definition_before_send()
        .map_err(|error| RequestFailure::bare(ModelRequestError::Fatal(error)))?;
    // External-import trust can be revoked independently from both memory
    // namespace gates. Hold its read side through the submit as the final
    // authority fence: a completed revoke wins and fails the lease check,
    // while an already-submitted request is the earlier linearized event.
    let project_import_authority = attempt_project_import_authority
        .map(|lock| {
            lock.read()
                .map_err(|_| "Project-memory external-import authority lock is poisoned; the model request was not sent.".to_owned())
        })
        .transpose()
        .map_err(|error| RequestFailure::bare(ModelRequestError::Fatal(error)))?;
    validate_before_send()
        .map_err(|error| RequestFailure::bare(ModelRequestError::Fatal(error)))?;

    // Serializing, cloning, and forwarding full request bodies is O(context), so
    // debug dumps require explicit environment-variable opt-in.
    #[cfg(debug_assertions)]
    if debug_model_body_enabled() {
        let debug_body = redact_debug_images(&serde_json::to_value(step).unwrap_or(Value::Null));
        eprintln!(
            "[dev] 模型 API 请求体（第 {round} 轮）：\n{}",
            serde_json::to_string_pretty(&debug_body).unwrap_or_else(|_| debug_body.to_string())
        );
        event_sink(ModelStreamEvent::DebugRequestBody {
            round,
            body: debug_body,
        })
        .map_err(|error| RequestFailure::bare(ModelRequestError::EventSink(error)))?;
    }

    // Recorded inside the authority fences and immediately before the submit:
    // the entry means "this payload was handed to the transport", so a request
    // that a revoked lease turned away must not leave one, and a request the
    // transport then loses must.
    if let Some(wire) = wire {
        wire.record();
    }

    let submission =
        crate::aisdk::process::submit(step).map_err(|failure| failure.sanitize(key))?;
    drop(project_import_authority);
    drop(definition_authority);

    crate::aisdk::process::drive_submission(&submission, round, event_sink)
        .map(ParsedModelResponse::from)
        .map_err(|failure| failure.sanitize(key))
}

/// A request body as the dev-only dump prints it: image bytes become markers,
/// since they are megabytes of base64 nobody reads in a terminal. Everything
/// else is printed as it was sent.
fn redact_debug_images(value: &Value) -> Value {
    match value {
        Value::Array(values) => Value::Array(values.iter().map(redact_debug_images).collect()),
        Value::Object(object) => {
            let is_image_source = object.get("type").and_then(Value::as_str) == Some("base64")
                && object.contains_key("media_type")
                && object.contains_key("data");
            let mut redacted = object
                .iter()
                .map(|(key, value)| (key.clone(), redact_debug_images(value)))
                .collect::<Map<_, _>>();
            if is_image_source {
                redacted.insert("data".into(), Value::String("<image data redacted>".into()));
            }
            Value::Object(redacted)
        }
        Value::String(value) if value.starts_with("data:image/") => {
            Value::String("<image data URL redacted>".into())
        }
        _ => value.clone(),
    }
}

/// Internal child-to-parent status tool. Keeping it outside `catalog::tool_catalog`
/// prevents the renderer, main agent, manual executor, and approval path from
/// granting it. A trusted child request injects this descriptor explicitly.
fn subagent_update_descriptor(profile: &PromptProfile) -> ToolDescriptor {
    // Leave the usage seed empty. Tool semantics belong in the root description
    // from `builtin_schemas::subagent_update_schema`; labels are UI-only.
    let english_defaults = profile.language == ResolvedLanguage::EnUs;
    let (label, parameter_label, parameter_help) = if english_defaults {
        (
            "Update",
            "Progress",
            "Describe current progress, important findings, or the next step.",
        )
    } else {
        ("更新", "进度", "说明当前进展、重要发现或下一步计划")
    };
    ToolDescriptor {
        force_confirmation: false,
        name: SUBAGENT_UPDATE_TOOL.into(),
        label: label.into(),
        description: String::new(),
        category: ToolCategory::Orchestration,
        dangerous: false,
        parameters: vec![ToolParameter {
            name: "message".into(),
            label: parameter_label.into(),
            parameter_type: ToolParameterType::Multiline,
            required: true,
            placeholder: None,
            help: Some(parameter_help.into()),
            default_value: None,
        }],
        input_schema: Some(crate::builtin_schemas::subagent_update_schema(profile)),
    }
}

/// Internal child-only tool that carries a schema-bound run's typed result back
/// to its parent. Injected — like [`subagent_update_descriptor`] — only into a
/// trusted child request, and only when that run has an `output_schema`.
///
/// It diverges from `subagent_update` in one deliberate way: the argument shape
/// is the CALLER's schema, which `ToolParameterType` cannot express (it has no
/// object or array variant). So the descriptor carries `input_schema` directly —
/// `tool_schema` returns that verbatim when present, which is how one per-spawn
/// schema reaches all three provider wire formats with no new arm anywhere.
///
/// Note what this does NOT buy: bodies are built with `"strict": false`, and
/// Anthropic has no strict flag at all, so no provider enforces the schema.
/// `subagent_schema` validation plus the retry/nudge loop is the whole
/// enforcement mechanism.
fn structured_output_descriptor(
    profile: &PromptProfile,
    schema: &crate::subagent_schema::Schema,
) -> ToolDescriptor {
    // Leave the usage seed empty. Value semantics belong in the wire schema's root
    // description and must not overwrite caller-provided root text. Lifecycle
    // semantics are appended unconditionally because they govern host behavior.
    let label = if profile.language == ResolvedLanguage::EnUs {
        "Structured result"
    } else {
        "结构化结果"
    };
    let mut wire_schema = schema.as_value().clone();
    let root = wire_schema
        .get("description")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|text| !text.is_empty())
        .unwrap_or(profile.text(PromptKey::SubagentStructuredOutputRootSeed))
        .to_owned();
    wire_schema["description"] = json!(format!(
        "{root} {}",
        profile.text(PromptKey::SubagentStructuredOutputLifecycle)
    ));
    ToolDescriptor {
        force_confirmation: false,
        name: STRUCTURED_OUTPUT_TOOL.into(),
        label: label.into(),
        description: String::new(),
        category: ToolCategory::Orchestration,
        dangerous: false,
        parameters: Vec::new(),
        input_schema: Some(wire_schema),
    }
}

/// Binds a resolved `output_schema` to a child request.
///
/// Called from `run_agent_spawn` AFTER `configure_named_agent_template`, never
/// from `agent_child_template`: `AgentRunOverrides::apply` runs last by design
/// and INTERSECTS `enabled_tools` against a named definition's `tools`
/// allowlist, so a tool pushed before it silently disappears for exactly the
/// agents most likely to be given a schema.
pub(crate) fn install_structured_output(
    template: &mut RunModelRequest,
    schema: crate::subagent_schema::Schema,
) -> Result<(), String> {
    template.tools.push(structured_output_descriptor(
        &template.prompt_profile,
        &schema,
    ));
    if !template
        .enabled_tools
        .iter()
        .any(|name| name == STRUCTURED_OUTPUT_TOOL)
    {
        template.enabled_tools.push(STRUCTURED_OUTPUT_TOOL.into());
    }
    template.output_schema = Some(schema);
    Ok(())
}

fn run_mcp_tool(
    request: &RunModelRequest,
    call: &ToolCall,
    execution_request: &ToolExecutionRequest,
    state: &AppState,
    descriptor: &ToolDescriptor,
    approve_dangerous_tool: &DangerousToolApproval<'_>,
    hook_allows_permission: bool,
) -> ToolResult {
    const MAX_MCP_MODEL_OUTPUT: usize = 64 * 1024;
    let started = Instant::now();
    let failure = |message: String| ToolResult {
        success: false,
        output: message,
        images: Vec::new(),
        diff: None,
        executed_at: Utc::now().to_rfc3339(),
        duration_ms: started.elapsed().as_millis().min(u64::MAX as u128) as u64,
    };
    let Some(binding) = request
        .mcp_bindings
        .iter()
        .find(|binding| binding.exposed_name == call.name)
    else {
        let result = failure(
            "The MCP tool binding is no longer valid; disable and re-enable this MCP server".into(),
        );
        state.record_receipt(execution_request, &result);
        return result;
    };

    if mcp_requires_native_approval(
        request.effective_security_level(),
        hook_allows_permission,
        binding.confirmation_required(),
    ) {
        match approve_dangerous_tool(execution_request, descriptor, approval_requester(request)) {
            Ok(true) => {}
            Ok(false) => {
                let result = failure("The user declined this MCP tool call".into());
                state.record_receipt(execution_request, &result);
                return result;
            }
            Err(error) => {
                let result = failure(format!("Could not confirm this MCP tool call: {error}"));
                state.record_receipt(execution_request, &result);
                return result;
            }
        }
    }

    let result = match state.mcp_sessions.call_for_conversation(
        &request.conversation_id,
        binding,
        Value::Object(call.input.clone()),
        // A task MCP call is interrupted only by its own task cancellation signal.
        request.round_cancellation(),
    ) {
        Ok(output) => {
            let serialized = output.model_output();
            if serialized.len() > MAX_MCP_MODEL_OUTPUT {
                failure(format!(
                    "The MCP tool returned more than {} KiB of model output; it was not injected into the context",
                    MAX_MCP_MODEL_OUTPUT / 1024
                ))
            } else {
                ToolResult {
                    success: !output.is_error,
                    output: serialized,
                    images: Vec::new(),
                    diff: None,
                    executed_at: Utc::now().to_rfc3339(),
                    duration_ms: started.elapsed().as_millis().min(u64::MAX as u128) as u64,
                }
            }
        }
        Err(error) => failure(format!("MCP tool call failed: {error}")),
    };
    state.record_receipt(execution_request, &result);
    result
}

fn mcp_requires_native_approval(
    level: crate::model::SecurityLevel,
    hook_allows_permission: bool,
    requires_user_interaction: bool,
) -> bool {
    requires_user_interaction
        || (level != crate::model::SecurityLevel::FullAccess && !hook_allows_permission)
}

#[cfg(test)]
fn execute_model_tool(
    request: &RunModelRequest,
    call: ToolCall,
    state: &AppState,
    approve_dangerous_tool: &DangerousToolApproval<'_>,
    hook_allows_permission: bool,
) -> ToolExecution {
    let mut structured_output_state = StructuredOutputTurnState::default();
    let mut tool_search_state = ToolSearchTurnState::default();
    execute_model_tool_with_turn_states(
        request,
        call,
        state,
        &mut structured_output_state,
        &mut tool_search_state,
        approve_dangerous_tool,
        hook_allows_permission,
        None,
        None,
    )
}

/// What the executor hands back to the run loop besides the result: the
/// verified identity of a `read`, and the file a guarded file tool touched.
#[derive(Default)]
struct ToolFileIdentities {
    opened_read_file: Option<tool_executor::VerifiedOpenedFile>,
    file_touch: Option<tool_executor::FileGuardTouch>,
}

/// The file guard this request executes under, as the executor wants it.
fn file_guard_context<'a>(
    request: &'a RunModelRequest,
    state: &'a AppState,
) -> tool_executor::FileGuardContext<'a> {
    tool_executor::FileGuardContext {
        scope: crate::file_read_state::ScopeRef {
            id: request.file_guard_scope(),
            parent: request.file_guard.parent_scope.as_deref(),
        },
        registry: &state.file_read_state,
    }
}

/// Plan mode's refusal of this call, if it has one
/// (`tool_executor::plan_mode_refusal`), asked under the scope the call was
/// classified with — the scope it would execute under.
fn plan_mode_refusal(
    request: &RunModelRequest,
    call: &ToolCall,
    authorization: &ToolAuthorization,
) -> Option<String> {
    if !request.plan_mode_active() {
        return None;
    }
    let decision = authorization.security.as_ref()?;
    tool_executor::plan_mode_refusal(
        &ToolExecutionRequest {
            conversation_id: request.conversation_id.clone(),
            workspace_path: request.workspace_path.clone(),
            tool_name: call.name.clone(),
            input: call.input.clone(),
        },
        &decision.scope,
        &request.workspaces,
        &request.prompt_profile,
        &request.round_cancellation(),
    )
}

fn execute_model_tool_with_scope(
    request: &RunModelRequest,
    execution_request: ToolExecutionRequest,
    state: &AppState,
    scope: security::ExecutionScope,
    handoff: Option<&tool_executor::ShellHandoff<'_>>,
    call_id: &str,
) -> (ToolResult, ToolFileIdentities) {
    // Browser admission depends on the conversation's level, and the navigation
    // callbacks that enforce it fire later, from the WebView's own thread. Push
    // the level onto the session now, while the request that carries it is still
    // in scope.
    if execution_request.tool_name.starts_with("preview_") {
        if let Ok(session_id) = crate::browser::preview_page_session_id(&request.conversation_id) {
            state
                .browser
                .set_session_security_level(&session_id, request.effective_security_level());
        }
    }
    // `preview_upload_image` names a transcript image, and only the run loop
    // holds the transcript, so the number-to-attachment lookup happens here
    // before the executor takes over.
    if execution_request.tool_name == "preview_upload_image" {
        let result = match resolve_upload_image_reference(request, &execution_request.input) {
            Ok(image) => tool_executor::execute_browser_upload_image(
                &execution_request,
                state,
                Path::new(&request.app_data_path),
                &image,
                &request.prompt_profile,
            ),
            Err(reason) => {
                let result = ToolResult {
                    success: false,
                    output: reason,
                    images: Vec::new(),
                    diff: None,
                    executed_at: Utc::now().to_rfc3339(),
                    duration_ms: 0,
                };
                state.record_receipt(&execution_request, &result);
                result
            }
        };
        return (result, ToolFileIdentities::default());
    }
    let execution = tool_executor::execute_with_scope_and_attachments_guarded(
        execution_request,
        state,
        scope,
        Some(Path::new(&request.app_data_path)),
        // Shell polling and pre-dispatch cancellation follow ownership: task rounds
        // use their task signal and top-level rounds use this run's signal.
        &request.round_cancellation(),
        &request.workspaces,
        handoff,
        &request.prompt_profile,
        Some(file_guard_context(request, state)),
        Some(call_id),
    );
    (
        execution.result,
        ToolFileIdentities {
            opened_read_file: execution.opened_file,
            file_touch: execution.file_touch,
        },
    )
}

enum UploadImageReference {
    Short(u32),
    Digest(String),
}

/// Resolves the `image_id` argument of `preview_upload_image` into a stored
/// attachment. Matches user images and non-memory tool images — exactly the set
/// the provider projection lets the model see.
fn resolve_upload_image_reference(
    request: &RunModelRequest,
    input: &JsonObject,
) -> Result<crate::model::ImageAttachment, String> {
    let reference = parse_upload_image_reference(input.get("image_id"))?;
    let mut found = None;
    for context in request
        .contexts
        .iter()
        .chain(request.ephemeral_contexts.iter())
    {
        let images: &[crate::model::ImageAttachment] = match context {
            ContextItem::User { images, .. } => images,
            ContextItem::Tool { result, .. } => &result.images,
            _ => continue,
        };
        for image in images {
            let matched = match &reference {
                UploadImageReference::Short(short) => image.short_id == Some(*short),
                UploadImageReference::Digest(digest) => image.id == *digest,
            };
            if matched {
                found = Some(image.clone());
            }
        }
    }
    found.ok_or_else(|| match reference {
        UploadImageReference::Short(short) => format!(
            "No image with reference [Image #{short}] was found; available numbers come from [Image #N] placeholders in user messages or imageId values in tool receipts."
        ),
        UploadImageReference::Digest(digest) => format!("No image attachment with digest {digest} was found."),
    })
}

/// Accepts the bare number the transcript shows (`3`), `#3`, `[Image #3]`,
/// or a full 64-hex attachment digest.
fn parse_upload_image_reference(value: Option<&Value>) -> Result<UploadImageReference, String> {
    let Some(value) = value else {
        return Err("Missing parameter image_id".into());
    };
    if let Some(number) = value.as_u64() {
        return u32::try_from(number)
            .ok()
            .filter(|short| *short >= 1)
            .map(UploadImageReference::Short)
            .ok_or_else(|| format!("image_id number is out of range: {number}"));
    }
    let Some(text) = value.as_str() else {
        return Err(
            "Parameter image_id must be an image number, such as 3 or \"[Image #3]\"".into(),
        );
    };
    let text = text.trim();
    if text.len() == 64
        && text
            .bytes()
            .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
    {
        return Ok(UploadImageReference::Digest(text.into()));
    }
    let digits = text
        .strip_prefix("[Image #")
        .and_then(|rest| rest.strip_suffix(']'))
        .or_else(|| text.strip_prefix('#'))
        .unwrap_or(text);
    digits
        .parse::<u32>()
        .ok()
        .filter(|short| *short >= 1)
        .map(UploadImageReference::Short)
        .ok_or_else(|| {
            format!("Unrecognized image_id: {text}; use an image number from the conversation, such as 3 or \"[Image #3]\"")
        })
}

fn execute_model_tool_with_turn_states(
    request: &RunModelRequest,
    call: ToolCall,
    state: &AppState,
    structured_output_state: &mut StructuredOutputTurnState,
    tool_search_state: &mut ToolSearchTurnState,
    approve_dangerous_tool: &DangerousToolApproval<'_>,
    hook_allows_permission: bool,
    mut file_identities: Option<&mut ToolFileIdentities>,
    handoff: Option<&tool_executor::ShellHandoff<'_>>,
) -> ToolExecution {
    let execution_request = ToolExecutionRequest {
        conversation_id: request.conversation_id.clone(),
        workspace_path: request.workspace_path.clone(),
        tool_name: call.name.clone(),
        input: call.input.clone(),
    };
    let descriptor = request.tools.iter().find(|tool| tool.name == call.name);
    let result = if let Some(reason) = automatic_tool_rejection_reason(request, &call) {
        let result = ToolResult {
            success: false,
            output: reason.into(),
            images: Vec::new(),
            diff: None,
            executed_at: Utc::now().to_rfc3339(),
            duration_ms: 0,
        };
        let receipt_request = ToolExecutionRequest {
            input: public_tool_input(&call.name, &call.input),
            ..execution_request.clone()
        };
        state.record_receipt(&receipt_request, &result);
        result
    } else if descriptor.is_some_and(|tool| tool.category == ToolCategory::Memory) {
        let started = Instant::now();
        // The two tiers are independent per-conversation switches. Refuse a
        // tier the user left off before anything else runs — in particular
        // before the global-mutation confirmation below, so a stale enabled
        // name can never make the user answer a native dialog for a write that
        // was never going to happen.
        let tier_denied = crate::mework_memory::tool_tier(&call.name)
            .filter(|tier| !request.memory_tier_access().allows(*tier))
            .map(|tier| {
                format!(
                    "This conversation has not enabled {}; enable it in the conversation settings and try again",
                    tier.label()
                )
            });
        // Writing global memory affects every workspace on this machine, so it
        // always demands a native confirmation. The tier is part of the tool
        // name, so this cannot be talked around with an argument.
        let global_mutation = tier_denied.is_none()
            && matches!(
                call.name.as_str(),
                "create_global_memory" | "edit_global_memory"
            );
        if global_mutation {
            let mut approval_descriptor = descriptor
                .expect("validated memory descriptor must exist")
                .clone();
            approval_descriptor.label = format!("{}（跨项目全局记忆）", approval_descriptor.label);
            match approve_dangerous_tool(
                &execution_request,
                &approval_descriptor,
                approval_requester(request),
            ) {
                Ok(true) => {}
                Ok(false) => {
                    let denied = ToolExecution {
                        call,
                        result: ToolResult {
                            success: false,
                            output: "The user declined to modify cross-project global memory; this memory operation was not executed".into(),
                            images: Vec::new(),
                            diff: None,
                            executed_at: Utc::now().to_rfc3339(),
                            duration_ms: u64::try_from(started.elapsed().as_millis())
                                .unwrap_or(u64::MAX),
                        },
                        subagent: None,
                    };
                    let receipt_request = ToolExecutionRequest {
                        input: public_tool_input(&denied.call.name, &denied.call.input),
                        ..execution_request
                    };
                    state.record_receipt(&receipt_request, &denied.result);
                    return denied;
                }
                Err(error) => {
                    let denied = ToolExecution {
                        call,
                        result: ToolResult {
                            success: false,
                            output: format!(
                                "Could not confirm the cross-project global memory change: {error}"
                            ),
                            images: Vec::new(),
                            diff: None,
                            executed_at: Utc::now().to_rfc3339(),
                            duration_ms: u64::try_from(started.elapsed().as_millis())
                                .unwrap_or(u64::MAX),
                        },
                        subagent: None,
                    };
                    let receipt_request = ToolExecutionRequest {
                        input: public_tool_input(&denied.call.name, &denied.call.input),
                        ..execution_request
                    };
                    state.record_receipt(&receipt_request, &denied.result);
                    return denied;
                }
            }
        }
        let result = (|| {
            // A tier the conversation turned off is refused here rather than
            // silently reading a directory the user opted out of. The roots
            // carry the same access, so this is belt and braces.
            if let Some(error) = tier_denied {
                return Err(error);
            }
            crate::mework_memory::execute_tool(
                &run_memory_roots(request),
                &call.name,
                &call.input,
                &request.prompt_profile,
            )
        })();
        match result {
            Ok(output) => ToolResult {
                success: true,
                output,
                images: Vec::new(),
                diff: None,
                executed_at: Utc::now().to_rfc3339(),
                duration_ms: u64::try_from(started.elapsed().as_millis()).unwrap_or(u64::MAX),
            },
            Err(error) => ToolResult {
                success: false,
                output: error,
                images: Vec::new(),
                diff: None,
                executed_at: Utc::now().to_rfc3339(),
                duration_ms: u64::try_from(started.elapsed().as_millis()).unwrap_or(u64::MAX),
            },
        }
    } else if descriptor.is_some_and(|tool| tool.category == ToolCategory::Mcp) {
        run_mcp_tool(
            request,
            &call,
            &execution_request,
            state,
            descriptor.expect("validated MCP descriptor must exist"),
            approve_dangerous_tool,
            hook_allows_permission,
        )
    } else if descriptor.is_some_and(|tool| tool.category == ToolCategory::Orchestration) {
        // Pure host-side state tools: no filesystem scope or approval.
        // agent_*/workflow/ask_user never reach here — the run loop
        // intercepts them by name before selecting an executor.
        let outcome = match call.name.as_str() {
            SKILL_TOOL => run_skill_tool(request, &call.input),
            crate::capabilities::TOOL_SEARCH_TOOL => {
                run_tool_search_tool(request, &call.input).map(|(output, matched)| {
                    // Surfacing is recorded whether or not the search matched:
                    // an empty match list leaves the state untouched, so the
                    // wire tool set only widens when a schema actually went out.
                    tool_search_state.surface(matched);
                    output
                })
            }
            // Returns as soon as the request is raised (or, under full access,
            // performed); the decision never comes back to this run.
            crate::fork_requests::FORK_TOOL => {
                crate::fork_requests::run_fork_tool(request, state, &call.input)
            }
            SUBAGENT_UPDATE_TOOL if request.subagent_depth > 0 => {
                orchestration::run_subagent_update(&call.input, &request.prompt_profile)
            }
            SUBAGENT_UPDATE_TOOL => Err(
                "The update tool is only for a subagent reporting status to the main agent".into(),
            ),
            STRUCTURED_OUTPUT_TOOL if request.subagent_depth > 0 => {
                match request.output_schema.as_ref() {
                    Some(schema) => {
                        match orchestration::parse_structured_output(&call.input, schema) {
                            Ok(value) => {
                                structured_output_state.value = Some(value);
                                Ok(request
                                    .prompt_profile
                                    .text(PromptKey::SubagentStructuredOutputSettled)
                                    .to_owned())
                            }
                            Err(error) => {
                                // Counted here, not in the caller: only this arm can
                                // tell a rejected value from a call that never ran.
                                structured_output_state.attempts += 1;
                                Err(request.prompt_profile.render(
                                    PromptKey::SubagentStructuredOutputRejected,
                                    &[
                                        ("error", &error),
                                        ("attempt", &structured_output_state.attempts.to_string()),
                                        (
                                            "max_attempts",
                                            &MAX_STRUCTURED_OUTPUT_ATTEMPTS.to_string(),
                                        ),
                                    ],
                                ))
                            }
                        }
                    }
                    None => Err(
                        "This run has no output_schema, so no structured result is expected".into(),
                    ),
                }
            }
            STRUCTURED_OUTPUT_TOOL => Err(
                "The structured-result tool is only for a subagent returning this run's result"
                    .into(),
            ),
            other => Err(format!(
                "Orchestration tool {other} can only be dispatched by the model run loop"
            )),
        };
        let (success, output) = match outcome {
            Ok(output) => (true, output),
            Err(error) => (false, error),
        };
        let result = ToolResult {
            success,
            output,
            images: Vec::new(),
            diff: None,
            executed_at: Utc::now().to_rfc3339(),
            duration_ms: 0,
        };
        state.record_receipt(&execution_request, &result);
        result
    } else {
        let decision = security::classify_model_call_in_workspaces(
            request.effective_security_level(),
            &request.workspaces,
            Path::new(&request.workspace_path),
            Path::new(&request.app_data_path),
            &request.additional_directories,
            &execution_request,
        );
        match decision {
            Err(error) => {
                let result = ToolResult {
                    success: false,
                    output: format!(
                        "Security classification failed; the tool was not executed: {error}"
                    ),
                    images: Vec::new(),
                    diff: None,
                    executed_at: Utc::now().to_rfc3339(),
                    duration_ms: 0,
                };
                state.record_receipt(&execution_request, &result);
                result
            }
            Ok(decision)
                if decision.requires_approval
                    && (!hook_allows_permission || decision.mandatory_prompt) =>
            {
                let approval = approve_dangerous_tool(
                    &execution_request,
                    descriptor.expect("validated descriptor must exist"),
                    approval_requester(request),
                );
                match approval {
                    Ok(true) => {
                        let (result, identities) = execute_model_tool_with_scope(
                            request,
                            execution_request.clone(),
                            state,
                            decision.scope,
                            handoff,
                            &call.id,
                        );
                        if let Some(slot) = &mut file_identities {
                            **slot = identities;
                        }
                        result
                    }
                    Ok(false) => {
                        let result = ToolResult {
                            success: false,
                            output: "The user declined this tool call".into(),
                            images: Vec::new(),
                            diff: None,
                            executed_at: Utc::now().to_rfc3339(),
                            duration_ms: 0,
                        };
                        state.record_receipt(&execution_request, &result);
                        result
                    }
                    Err(error) => {
                        let result = ToolResult {
                            success: false,
                            output: format!("Could not confirm this tool call: {error}"),
                            images: Vec::new(),
                            diff: None,
                            executed_at: Utc::now().to_rfc3339(),
                            duration_ms: 0,
                        };
                        state.record_receipt(&execution_request, &result);
                        result
                    }
                }
            }
            Ok(decision) => {
                let (result, identities) = execute_model_tool_with_scope(
                    request,
                    execution_request.clone(),
                    state,
                    decision.scope,
                    handoff,
                    &call.id,
                );
                if let Some(slot) = &mut file_identities {
                    **slot = identities;
                }
                result
            }
        }
    };
    ToolExecution {
        call,
        result,
        subagent: None,
    }
}

fn automatic_tool_rejection_reason(
    request: &RunModelRequest,
    call: &ToolCall,
) -> Option<String> {
    if !request.tools.iter().any(|tool| tool.name == call.name) {
        return Some("The model requested an unknown tool".to_owned());
    }
    // Child requests strip their hard-disabled names from enabled_tools, so
    // this is also the structural guard against nested agents/ask_user calls.
    //
    // The plan tools are never in `enabled_tools`: they are derived from the
    // plan-mode setting, so the same derivation that decided which schemas this
    // step advertised decides whether the call is allowed. The handoff tools
    // likewise, from the run's handoff state.
    if !request.enabled_tools.iter().any(|name| name == &call.name)
        && !crate::plan_mode::derived_tools(request.plan_tools, request.subagent_depth)
            .contains(&call.name.as_str())
        && !crate::handoff::derived_tools(request).contains(&call.name.as_str())
    {
        // A deferred MCP tool is not disabled, it is unfetched, and the model
        // can fix that itself. Saying so is the difference between a dead end
        // and a repairable one — the model announced the name to itself, so it
        // has every reason to believe the tool is there.
        if request
            .deferred_tools
            .iter()
            .any(|tool| tool.name == call.name)
        {
            return Some(
                request
                    .prompt_profile
                    .render(PromptKey::ToolSearchNotLoaded, &[("name", &call.name)]),
            );
        }
        return Some("The model requested a tool that is not enabled".to_owned());
    }
    if let Some(raw) = call.input.get("_raw") {
        // What arrived, so the model can see what went wrong — usually JSON cut
        // off or left unbalanced — instead of being told an argument is missing.
        let text = raw.as_str().map(str::to_owned).unwrap_or_else(|| raw.to_string());
        let shown = text.chars().take(200).collect::<String>();
        let more = if text.chars().count() > 200 { "…" } else { "" };
        return Some(format!(
            "The tool arguments were not a valid JSON object, so the call did not run. Received: {shown}{more}"
        ));
    }
    None
}

fn rejected_tool_execution(
    request: &RunModelRequest,
    call: ToolCall,
    reason: &str,
    state: &AppState,
) -> ToolExecution {
    let execution_request = ToolExecutionRequest {
        conversation_id: request.conversation_id.clone(),
        workspace_path: request.workspace_path.clone(),
        tool_name: call.name.clone(),
        input: public_tool_input(&call.name, &call.input),
    };
    let result = ToolResult {
        success: false,
        output: reason.to_owned(),
        images: Vec::new(),
        diff: None,
        executed_at: Utc::now().to_rfc3339(),
        duration_ms: 0,
    };
    state.record_receipt(&execution_request, &result);
    ToolExecution {
        call,
        result,
        subagent: None,
    }
}

pub(crate) fn failed_tool_execution(call: ToolCall, reason: String) -> ToolExecution {
    ToolExecution {
        call,
        result: ToolResult {
            success: false,
            output: reason,
            images: Vec::new(),
            diff: None,
            executed_at: Utc::now().to_rfc3339(),
            duration_ms: 0,
        },
        subagent: None,
    }
}

fn browser_credential_takeover_denial(
    request: &RunModelRequest,
    call: &ToolCall,
    state: &AppState,
    approve_dangerous_tool: &DangerousToolApproval<'_>,
) -> Option<String> {
    let tool = crate::browser::PreviewTool::from_tool_name(&call.name)?;
    let session_id = crate::browser::preview_page_session_id(&request.conversation_id).ok()?;
    let origin = match state.browser.pending_credential_takeover(&session_id) {
        Ok(None) => return None,
        Ok(Some(origin)) => origin,
        // Never read a failed check as "no credentials here".
        Err(error) => {
            return Some(format!(
                "Could not confirm whether this tab carries login credentials; takeover was refused: {error}"
            ))
        }
    };
    let Some(descriptor) = request.tools.iter().find(|tool| tool.name == call.name) else {
        return Some(format!(
            "Browser tool {} has no trusted descriptor",
            call.name
        ));
    };
    let mut descriptor = descriptor.clone();
    // The prompt names the tool. Without it every takeover request would read the same whether
    // the Agent wants to read the page or type into a signed-in form.
    descriptor.label = format!(
        "{} · {tool}\nAuthorization to take over: Agent requests control of the browser tab you opened, {}. This page is currently signed in to {origin}. If you allow it, the Agent can act as you on this page until it leaves this origin.",
        descriptor.label,
        crate::browser::browser_tab_label(&session_id),
    );
    let execution_request = ToolExecutionRequest {
        conversation_id: request.conversation_id.clone(),
        workspace_path: request.workspace_path.clone(),
        tool_name: call.name.clone(),
        input: call.input.clone(),
    };
    // A hook cannot pre-approve this one. Every other prompt in this loop protects the workspace or
    // the machine, where a project-owned hook is a reasonable delegate. This protects the user's own
    // signed-in session, and the user asked to be the one who answers.
    match approve_dangerous_tool(&execution_request, &descriptor, approval_requester(request)) {
        Ok(true) => {}
        Ok(false) => {
            return Some(format!(
                "The user declined to let the Agent take over this signed-in tab ({origin})"
            ))
        }
        Err(error) => {
            return Some(format!(
                "Could not confirm authorization to take over this tab: {error}"
            ))
        }
    }
    state
        .browser
        .grant_credential_takeover(&session_id, &origin)
        .err()
}

fn web_search_task_context(task: String) -> ContextItem {
    ContextItem::User {
        id: new_context_id("web-search-task"),
        content: task,
        images: Vec::new(),
        files: Vec::new(),
        created_at: Utc::now().to_rfc3339(),
    }
}

/// The isolated executor's system prompt, from the profile
/// (`web.executor_system_prompt` with one of the two budget lines).
fn web_search_system_prompt(profile: &PromptProfile, max_searches: u32) -> String {
    let budget_line = if max_searches == 0 {
        profile
            .text(PromptKey::WebExecutorBudgetUnlimited)
            .to_owned()
    } else {
        profile.render(
            PromptKey::WebExecutorBudgetLimited,
            &[("max_searches", &max_searches.to_string())],
        )
    };
    profile.render(
        PromptKey::WebExecutorSystemPrompt,
        &[("budget_line", &budget_line)],
    )
}

/// Builds the one isolated request the `Native` search backend dispatches. The
/// base is deliberately narrow: no memory, no project instructions, no MCP, no
/// parent tool catalogue, and a fresh context holding only the query.
///
/// It holds **no client tools at all**. Its one capability is the
/// provider-native `web_search` server tool, which `build_*_body` adds to the
/// wire request because `native_search_call` is set. That is why there is
/// nothing here for the host to execute and no second permission boundary.
fn web_search_request_template(
    parent: &RunModelRequest,
    provider: ApiProvider,
    model: ModelProfile,
    task: String,
) -> RunModelRequest {
    RunModelRequest {
        provider,
        web_search: parent.web_search.clone(),
        native_search_call: true,
        native_fetch_call: None,
        // The delegated request carries the server-side search tool directly; it
        // does not re-derive the host's own web tools, so the switch that grants
        // those is irrelevant here and stays off.
        web_search_enabled: false,
        // Search proxy calls do not enable shell tools, so a run environment has no effect.
        run_environment: Default::default(),
        workspaces: Default::default(),
        prompt_profile: parent.prompt_profile.clone(),
        // An isolated search request has no reason to read or write the
        // user's memory, and must not be able to exfiltrate it to a page.
        global_memory_enabled: false,
        project_memory_enabled: false,
        // Nor any skill: this request runs one host-minted search, not the
        // user's task, so the conversation's instructions are not its business.
        skills: Vec::new(),
            added_skills: Vec::new(),
            mcp_tool_discovery: false,
            file_guard: Default::default(),
            deferred_tools: Vec::new(),
        // A search call reports as prose, not through `structured_output`.
        output_schema: None,
        model,
        reasoning_effort: parent.reasoning_effort,
        conversation_id: parent.conversation_id.clone(),
        workspace_id: parent.workspace_id.clone(),
        memory_context_id: None,
        project_memory_context_id: None,
        agent_definition_binding: None,
        inherits_parent_model_memory: false,
        fork_model_binding: None,
        subagent_execution_mode_receipt: None,
        subagent_reserved_names: Vec::new(),
        memory_run_id: None,
        context_load_actor_name: Some("web-search-call".into()),
        workspace_path: parent.workspace_path.clone(),
        additional_directories: parent.additional_directories.clone(),
        assembled_system_prompt: web_search_system_prompt(
            &parent.prompt_profile,
            parent.web_search.max_searches_per_call,
        ),
        enabled_tools: Vec::new(),
        contexts: vec![web_search_task_context(task)],
        ephemeral_contexts: Vec::new(),
        host_notices: Vec::new(),
        tools: Vec::new(),
        // No client tools means no tool call can happen inside this request at
        // all, so these hooks have nothing left to intercept. They are kept only
        // so the filter's intent stays visible if a client tool is ever added back.
        active_hooks: parent
            .active_hooks
            .iter()
            .filter(|hook| {
                matches!(
                    hook.event,
                    HookEvent::PreToolUse | HookEvent::PermissionRequest | HookEvent::PostToolUse
                )
            })
            .cloned()
            .collect(),
        // A scoped grant, not unrestricted access: the capability set is the
        // host-minted tool list above and nothing else. No live cell either, so
        // a mid-turn switch cannot narrow a grant this request already relies on.
        security_level: crate::model::SecurityLevel::FullAccess,
        live_security_level: None,
        plan_tools: false,
        live_plan_mode: None,
        app_data_path: parent.app_data_path.clone(),
        mcp_servers: Vec::new(),
        mcp_bindings: Vec::new(),
        subagent_depth: parent.subagent_depth + 1,
        handoff: Default::default(),
        request_id: String::new(),
        subagent_name: None,
        subagent_call_id: None,
        history_owner: None,
        steer_mailbox: AgentMailboxHandle::default(),
        // This template sends one HTTP request with no client tools or hooks.
        // Its dispatching worker observes cancellation at the HTTP layer.
        task_cancel: CancelSignal::default(),
        run_cancel: CancelSignal::default(),
    }
}

/// Builds the one isolated request the `Native` fetch backend dispatches.
///
/// Same shape and same reasoning as [`web_search_request_template`] — no memory,
/// no skills, no client tools, no parent catalogue — with two differences: the
/// only capability attached is the upstream's own server-side `web_fetch`, and
/// the executor's prose is thrown away. The host reads the retrieved pages out
/// of `web_documents`, so nothing here depends on the model summarizing well.
///
/// The URLs go into the request's own user context because Anthropic will only
/// fetch an address that already appeared in the conversation; putting them in
/// the task body is what makes them eligible.
fn web_fetch_request_template(parent: &RunModelRequest, urls: &[String]) -> RunModelRequest {
    let (provider, model) = resolve_native_search_endpoint(parent);
    let task = parent.prompt_profile.render(
        PromptKey::WebFetchExecutorTask,
        &[("urls", &urls.join("\n"))],
    );
    RunModelRequest {
        native_search_call: false,
        // One fetch per URL, and no budget to wander: the executor cannot
        // retrieve a page the model did not name.
        native_fetch_call: Some(urls.len().min(u32::MAX as usize) as u32),
        assembled_system_prompt: parent
            .prompt_profile
            .text(PromptKey::WebFetchExecutorSystemPrompt)
            .to_owned(),
        contexts: vec![web_search_task_context(task)],
        context_load_actor_name: Some("web-fetch-call".into()),
        ..web_search_request_template(parent, provider, model, String::new())
    }
}

fn sanitize_instruction_shaped_text(
    profile: &PromptProfile,
    value: &str,
    max_chars: usize,
) -> String {
    let mut output = String::new();
    for (index, line) in value.lines().enumerate() {
        if index > 0 {
            output.push('\n');
        }
        let line = line
            .chars()
            .filter(|character| {
                !character.is_control()
                    && !matches!(
                        *character,
                        '\u{061c}'
                            | '\u{200b}'
                            | '\u{200e}'
                            | '\u{200f}'
                            | '\u{202a}'..='\u{202e}'
                            | '\u{2066}'..='\u{2069}'
                            | '\u{feff}'
                            | '\u{e0000}'..='\u{e007f}'
                    )
            })
            .collect::<String>();
        let probe = line.trim_start().to_ascii_lowercase();
        if [
            "system:",
            "developer:",
            "human:",
            "assistant:",
            "tool:",
            "<system-reminder",
            // Background task notifications are bare `<task-notification>` wire
            // elements. Fetched page text must never resemble one, or it could forge
            // a host completion event.
            "<task-notification",
            "[system]",
            "ignore previous",
            "ignore all previous",
        ]
        .iter()
        .any(|prefix| probe.starts_with(prefix))
        {
            output.push_str(profile.text(PromptKey::WebUntrustedMarker));
        }
        output.push_str(&line);
        if output.chars().count() >= max_chars {
            break;
        }
    }
    if output.chars().count() <= max_chars {
        return output;
    }
    output.chars().take(max_chars).collect()
}

fn web_tool_failure(call: ToolCall, message: impl Into<String>, started: Instant) -> ToolExecution {
    ToolExecution {
        call,
        result: ToolResult {
            success: false,
            output: message.into(),
            images: Vec::new(),
            diff: None,
            executed_at: Utc::now().to_rfc3339(),
            duration_ms: started.elapsed().as_millis().min(u64::MAX as u128) as u64,
        },
        subagent: None,
    }
}

/// Input for `web_search`: one self-contained query. Any other key means
/// nothing to a search and is ignored; a typo'd `query` still fails, because
/// the query itself is then missing.
fn parse_web_search_query(input: &JsonObject) -> Result<String, String> {
    let query = input
        .get("query")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|query| !query.is_empty())
        .ok_or_else(|| {
            "web_search.query must be a non-empty string: use one self-contained query without pronouns that refer to earlier context".to_owned()
        })?;
    let length = query.chars().count();
    if length < WEB_SEARCH_MIN_QUERY {
        return Err(format!(
            "web_search.query must be at least {WEB_SEARCH_MIN_QUERY} characters"
        ));
    }
    if length > WEB_SEARCH_MAX_QUERY {
        return Err(format!(
            "web_search.query exceeds the {WEB_SEARCH_MAX_QUERY}-character limit; split a long question into multiple searches"
        ));
    }
    Ok(query.to_owned())
}

/// Input for `web_fetch`: a batch of absolute HTTP(S) URLs. Other keys are
/// ignored, as for `web_search`.
fn parse_web_fetch_urls(input: &JsonObject) -> Result<Vec<String>, String> {
    let urls = input
        .get("urls")
        .and_then(Value::as_array)
        .ok_or_else(|| "web_fetch.urls must be an array of strings".to_owned())?;
    let mut collected = Vec::with_capacity(urls.len());
    for entry in urls {
        let url = entry
            .as_str()
            .ok_or_else(|| "Each web_fetch.urls entry must be a string".to_owned())?;
        collected.push(url.to_owned());
    }
    crate::web_search::pipeline::normalize_urls(&collected)
}

/// The task body handed to the `Native` backend. There is deliberately no
/// mandated return shape: nothing downstream parses the findings — the host
/// sanitizes them as text and hands them back as the tool result.
fn web_search_native_task(profile: &PromptProfile, query: &str) -> String {
    profile.render(PromptKey::WebExecutorTask, &[("query", query)])
}

/// Resolves the conversation's own provider/model for the `Native` backend.
///
/// The `Native` backend uses the conversation's own provider/model. Catalog
/// entries are search APIs the host calls itself, so they never produce a
/// `(provider, model)` pair.
fn resolve_native_search_endpoint(parent: &RunModelRequest) -> (ApiProvider, ModelProfile) {
    let mut model = parent.model.clone();
    // OpenAI reasoning models require at least 8192 output tokens; otherwise
    // reasoning exhausts the budget and returns incomplete with no prose. Raise,
    // but never lower, the conversation's configured limit.
    model.max_output_tokens = Some(
        model
            .max_output_tokens
            .unwrap_or(0)
            .max(crate::web_search::SEARCH_CALL_MAX_OUTPUT_TOKENS),
    );
    // Exclude search-result images because extraction and citations are text-only.
    model.set_capability(ModelCapability::ImageRecognition, false);
    (parent.provider.clone(), model)
}

/// What one native search produced: the executor's report, and the sites it
/// consulted.
///
/// The two travel together because they answer different questions and only the
/// pair is honest. `findings` is prose a model wrote and could be wrong about;
/// `sources` is the list of pages the provider actually retrieved, which is the
/// only part of a server-side search the host can verify. The timeline draws its
/// per-site chips from `sources`, so flattening them into the prose would make
/// the card have to parse its own text back apart.
struct NativeSearchOutcome {
    findings: String,
    sources: Vec<crate::model::ContextSource>,
}

/// Sends the one isolated search request and returns its findings and sources.
///
/// Deliberately built out of the same primitives as an ordinary model round —
/// `build_request_body_with_history` + `post_model_request_with_validator` — so
/// this path inherits the bounded retries, the single-exchange ceiling and,
/// most importantly, the **cancellation probes**: a stop must not have to wait
/// out a minute-long upstream search.
///
/// The nested stream is not renderer-visible: every event it produces is
/// translated into a rate-limited `Ping` on the parent sink. A `Ping` is exactly
/// the sink's cancellation check, so the turn stays interruptible mid-stream
/// while none of the search's own text leaks into the parent turn as if the
/// conversation's model had said it.
fn perform_web_search_request(
    request: &RunModelRequest,
    event_sink: &ModelEventSink<'_>,
    round: usize,
) -> Result<NativeSearchOutcome, ModelRequestError> {
    let base_url = provider_base_url(&request.provider).map_err(ModelRequestError::Fatal)?;
    let key =
        initial_provider_key(&request.provider, &base_url).map_err(ModelRequestError::Fatal)?;
    let base_url_text = base_url.as_ref().map(Url::to_string).unwrap_or_default();
    let probe = Mutex::new(Instant::now());
    let quiet = |event: ModelStreamEvent| -> Result<(), String> {
        if matches!(event, ModelStreamEvent::Ping) {
            return event_sink(ModelStreamEvent::Ping);
        }
        let mut last = probe
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if last.elapsed() < CANCELLATION_PROBE_INTERVAL {
            return Ok(());
        }
        *last = Instant::now();
        event_sink(ModelStreamEvent::Ping)
    };
    let quiet_sink: &ModelEventSink<'_> = &quiet;
    // Native search is a host-minted model request that consumes tokens. Route it
    // through the gateway and record one `web_search` ledger row.
    let gateway_ledger = crate::token_ledger::GatewayRecorder::new(
        &request.app_data_path,
        crate::token_ledger::UsageOrigin::WebSearch,
        &request.conversation_id,
        &request.workspace_id,
        &request.provider.id,
        &request.provider.name,
        &request.model.id,
    );

    // `None` conversation id: this request is one-shot, so it owns no
    // cross-turn prompt-cache session.
    let wire_session = wire_history::begin_session_with_replay(
        None,
        crate::aisdk::protocol::Family::for_format(request.provider.family),
        &request.contexts,
        wire_history::ReplayInputs::new(&request.app_data_path, &request.conversation_id),
    );
    // `pause_turn` continuation has two layers. Anthropic requires replaying the
    // assistant message verbatim, including every `encrypted_content`, before the
    // next step. The sidecar continues pending provider tools via `streamText` and
    // `maxSteps`; this loop handles a pause whose call and result are both complete,
    // which SDK otherwise normalizes to `finishReason:"stop"`.
    let mut exchanges: Vec<Exchange> = Vec::new();
    let mut pause_continuations = 0usize;
    let mut collected_text = String::new();
    let mut search_failures: Vec<String> = Vec::new();
    let mut cited: Vec<crate::aisdk::protocol::SidecarSource> = Vec::new();
    let search_limit = request.web_search.max_searches_per_call;
    let mut search_uses = 0u32;
    let mut search_call_ids = BTreeSet::new();
    let mut budget_exhausted = false;
    loop {
        // Continuations receive only the remaining step budget. Provider `max_uses`
        // is per request, but this bounds total SDK steps rather than multiplying it.
        let remaining_steps = (MAX_ANTHROPIC_PAUSE_CONTINUATIONS as u32)
            .saturating_add(1)
            .saturating_sub(pause_continuations as u32)
            .max(1);
        let credential =
            step_credential(&request.provider, &key).map_err(ModelRequestError::Fatal)?;
        let key = credential.api_key.clone();
        let (mut step, audit) = crate::aisdk::step::build_step_request_audited(
            request,
            &exchanges,
            wire_session.assemble(),
            &base_url_text,
            key.clone(),
            remaining_steps,
            |step| {
                if let Some(native) = step.native_search.as_mut() {
                    // SDK response.messages may contain only its last internal step.
                    // Carry accounted IDs independently of opaque replay to deduplicate
                    // calls from earlier SDK steps on a subsequent host continuation.
                    native.previous_call_ids = search_call_ids.iter().cloned().collect();
                    if search_limit > 0 {
                        // Exhaustion exits below; remaining zero must never mean unlimited.
                        native.max_uses = search_limit.saturating_sub(search_uses);
                    }
                }
            },
        )
        .map_err(ModelRequestError::Fatal)?;
        let wire_recorder = crate::history::RequestRecorder::for_request(
            request,
            crate::history::KIND_SEARCH,
            round,
            audit,
        );
        step.headers = credential.headers;
        let mut parsed = post_model_request_with_validator(
            &step,
            key.as_deref(),
            round,
            quiet_sink,
            None,
            &|| Ok(()),
            None,
            &|| Ok(()),
            gateway_ledger.as_ref(),
            wire_recorder.as_ref(),
        )
        .map_err(|exhausted| exhausted.error)?;
        // A reported server-tool failure is not completed search. Exhaustion,
        // rejection, and upstream failure can otherwise resemble normal prose.
        search_failures.extend(parsed.provider_tool_errors.iter().map(|failure| {
            if failure.tool_name.is_empty() {
                failure.message.clone()
            } else {
                format!("{}: {}", failure.tool_name, failure.message)
            }
        }));
        cited.append(&mut parsed.sources);
        if !parsed.text.trim().is_empty() {
            if !collected_text.is_empty() {
                collected_text.push('\n');
            }
            collected_text.push_str(parsed.text.trim());
        }
        let step_uses = parsed.native_search_uses.ok_or_else(|| {
            ModelRequestError::Fatal("Native-search step omitted its search consumption".into())
        })?;
        let before = search_call_ids.len();
        search_call_ids.extend(parsed.native_search_call_ids.iter().cloned());
        if search_call_ids.len().saturating_sub(before) != step_uses as usize {
            return Err(ModelRequestError::Fatal(
                "Native-search consumption IDs disagree with its count".into(),
            ));
        }
        search_uses = search_uses.saturating_add(step_uses);
        if search_limit > 0 && search_uses >= search_limit {
            budget_exhausted = true;
            break;
        }
        // Match the main loop: either raw or normalized `pause_turn` continues,
        // so dialect passthrough cannot disable this path.
        if parsed.raw_stop_reason.as_deref() == Some("pause_turn")
            || parsed.stop_reason.as_deref() == Some("pause_turn")
        {
            if pause_continuations >= MAX_ANTHROPIC_PAUSE_CONTINUATIONS {
                return Err(ModelRequestError::Fatal(format!(
                    "Native-search pause_turn automatic continuation reached the safety limit of {MAX_ANTHROPIC_PAUSE_CONTINUATIONS}"
                )));
            }
            exchanges.push(Exchange::new(parsed.continuation, Vec::new()));
            pause_continuations += 1;
            continue;
        }
        break;
    }
    let text = collected_text.trim();
    if text.is_empty() && budget_exhausted {
        return Err(ModelRequestError::Fatal(
            "Native-search budget exhausted without an answer".into(),
        ));
    }
    if text.is_empty() {
        if let Some(first) = search_failures.first() {
            return Err(ModelRequestError::Fatal(format!(
                "Upstream server-side search failed: {first}"
            )));
        }
        return Err(ModelRequestError::Fatal(
            "The upstream completed this web search but returned no text".into(),
        ));
    }
    // Up to 32 citations reach the envelope. URLs are the only traceable part of
    // a server-side search — the page text is sealed in the provider's own
    // encrypted payload — so they are the whole audit trail, and the timeline
    // builds its per-site chips out of them.
    let sources = context_sources(&cited);
    let mut tail = String::new();
    if budget_exhausted {
        tail.push_str("\n\nNative-search budget exhausted; no further searches were requested.");
    }
    let profile = &request.prompt_profile;
    if !search_failures.is_empty() {
        // Preserve failure warnings alongside text so incomplete search is not
        // represented as a clean result.
        tail.push_str("\n\n");
        tail.push_str(&profile.render(
            PromptKey::WebSearchWarnings,
            &[("warnings", &profile.join_list(&search_failures))],
        ));
    }
    // `web_search_output` truncates the full envelope at 32K from the front.
    // Reserve tail space for warnings; truncate content, not facts. Sources are
    // no longer part of this budget: they became a field of the envelope rather
    // than a rendered list at the end of the prose, so they cannot be cut off by
    // a long report and the renderer does not have to parse them back out.
    let budget = WEB_RESEARCH_MAX_FINDING_REPORT
        .saturating_sub(tail.len())
        .saturating_sub(1024);
    let mut findings = if text.len() > budget {
        let mut cut = budget;
        while cut > 0 && !text.is_char_boundary(cut) {
            cut -= 1;
        }
        format!("{}…", &text[..cut])
    } else {
        text.to_owned()
    };
    findings.push_str(&tail);
    Ok(NativeSearchOutcome { findings, sources })
}

/// Sends the one isolated fetch request and returns the pages it retrieved.
///
/// Built out of the same primitives as [`perform_web_search_request`], for the
/// same reasons: bounded retries, a single-exchange ceiling, and cancellation
/// probes, so stopping a run does not have to wait out a slow page.
///
/// What differs is the deliverable. The executor's prose is discarded; the
/// result is `web_documents`, the pages the upstream already converted to text.
/// That is the whole point of taking this path instead of the catalog pipeline —
/// no second model reads the pages and writes them up, so nothing is lost or
/// invented between the page and the tool result.
fn perform_web_fetch_request(
    request: &RunModelRequest,
    event_sink: &ModelEventSink<'_>,
    round: usize,
) -> Result<Vec<crate::web_search::SearchResultItem>, ModelRequestError> {
    let base_url = provider_base_url(&request.provider).map_err(ModelRequestError::Fatal)?;
    let key =
        initial_provider_key(&request.provider, &base_url).map_err(ModelRequestError::Fatal)?;
    let base_url_text = base_url.as_ref().map(Url::to_string).unwrap_or_default();
    let probe = Mutex::new(Instant::now());
    let quiet = |event: ModelStreamEvent| -> Result<(), String> {
        if matches!(event, ModelStreamEvent::Ping) {
            return event_sink(ModelStreamEvent::Ping);
        }
        let mut last = probe
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if last.elapsed() < CANCELLATION_PROBE_INTERVAL {
            return Ok(());
        }
        *last = Instant::now();
        event_sink(ModelStreamEvent::Ping)
    };
    let quiet_sink: &ModelEventSink<'_> = &quiet;
    let gateway_ledger = crate::token_ledger::GatewayRecorder::new(
        &request.app_data_path,
        crate::token_ledger::UsageOrigin::WebSearch,
        &request.conversation_id,
        &request.workspace_id,
        &request.provider.id,
        &request.provider.name,
        &request.model.id,
    );
    let wire_session = wire_history::begin_session_with_replay(
        None,
        crate::aisdk::protocol::Family::for_format(request.provider.family),
        &request.contexts,
        wire_history::ReplayInputs::new(&request.app_data_path, &request.conversation_id),
    );
    let mut exchanges: Vec<Exchange> = Vec::new();
    let mut pause_continuations = 0usize;
    let mut documents: Vec<crate::aisdk::protocol::SidecarWebDocument> = Vec::new();
    let mut failures: Vec<String> = Vec::new();
    loop {
        let remaining_steps = (MAX_ANTHROPIC_PAUSE_CONTINUATIONS as u32)
            .saturating_add(1)
            .saturating_sub(pause_continuations as u32)
            .max(1);
        let credential =
            step_credential(&request.provider, &key).map_err(ModelRequestError::Fatal)?;
        let key = credential.api_key.clone();
        let (mut step, audit) = crate::aisdk::step::build_step_request_audited(
            request,
            &exchanges,
            wire_session.assemble(),
            &base_url_text,
            key.clone(),
            remaining_steps,
            |_| {},
        )
        .map_err(ModelRequestError::Fatal)?;
        let wire_recorder = crate::history::RequestRecorder::for_request(
            request,
            crate::history::KIND_FETCH,
            round,
            audit,
        );
        step.headers = credential.headers;
        let parsed = post_model_request_with_validator(
            &step,
            key.as_deref(),
            round,
            quiet_sink,
            None,
            &|| Ok(()),
            None,
            &|| Ok(()),
            gateway_ledger.as_ref(),
            wire_recorder.as_ref(),
        )
        .map_err(|exhausted| exhausted.error)?;
        failures.extend(parsed.provider_tool_errors.iter().map(|failure| {
            if failure.tool_name.is_empty() {
                failure.message.clone()
            } else {
                format!("{}: {}", failure.tool_name, failure.message)
            }
        }));
        documents.extend(parsed.web_documents.iter().cloned());
        if parsed.raw_stop_reason.as_deref() == Some("pause_turn")
            || parsed.stop_reason.as_deref() == Some("pause_turn")
        {
            if pause_continuations >= MAX_ANTHROPIC_PAUSE_CONTINUATIONS {
                return Err(ModelRequestError::Fatal(format!(
                    "Native-fetch pause_turn automatic continuation reached the safety limit of {MAX_ANTHROPIC_PAUSE_CONTINUATIONS}"
                )));
            }
            exchanges.push(Exchange::new(parsed.continuation, Vec::new()));
            pause_continuations += 1;
            continue;
        }
        break;
    }
    if documents.is_empty() {
        // A fetch that retrieved nothing is a failure with a cause, not an empty
        // success: reporting "no content" would read as "the page is blank".
        return Err(ModelRequestError::Fatal(match failures.first() {
            Some(first) => format!("Upstream server-side fetch failed: {first}"),
            None => "The upstream completed this fetch but returned no page content".to_owned(),
        }));
    }
    let profile = &request.prompt_profile;
    Ok(documents
        .into_iter()
        .map(|document| crate::web_search::SearchResultItem {
            title: sanitize_instruction_shaped_text(
                profile,
                document.title.as_deref().unwrap_or_default(),
                512,
            ),
            content: sanitize_instruction_shaped_text(
                profile,
                &document.text,
                WEB_RESEARCH_MAX_FINDING_REPORT,
            ),
            source_input: document.url.clone(),
            url: document.url,
        })
        .collect())
}

/// Shared approval preflight for web tools.
/// `Ok(None)` may continue; `Ok(Some(execution))` is a completed denial or
/// permission failure; `Err` is a host failure. Child calls use the same
/// classification and approval path as top-level calls, with the requester named.
fn authorize_web_tool(
    parent: &RunModelRequest,
    call: &ToolCall,
    shadowed_approval: &DangerousToolApproval<'_>,
    hook_allows_permission: bool,
    started: Instant,
) -> Result<Option<ToolExecution>, String> {
    let execution_request = ToolExecutionRequest {
        conversation_id: parent.conversation_id.clone(),
        workspace_path: parent.workspace_path.clone(),
        tool_name: call.name.clone(),
        input: call.input.clone(),
    };
    let descriptor = parent
        .tools
        .iter()
        .find(|tool| tool.name == call.name)
        .ok_or_else(|| format!("Web tool {} has no trusted description", call.name))?;
    let decision = security::classify_model_call(
        parent.effective_security_level(),
        Path::new(&parent.workspace_path),
        Path::new(&parent.app_data_path),
        &parent.additional_directories,
        &execution_request,
    )?;
    // One approval covers this whole call. Every request it makes is a
    // consequence of this decision, which is why the prompt text says so
    // explicitly rather than describing a single fetch.
    if decision.requires_approval && (!hook_allows_permission || decision.mandatory_prompt) {
        // Pass the requester so a subagent-initiated web approval names the
        // requesting subagent rather than appearing to come from the main agent.
        match shadowed_approval(&execution_request, descriptor, approval_requester(parent)) {
            Ok(true) => {}
            Ok(false) => {
                return Ok(Some(web_tool_failure(
                    call.clone(),
                    "The user declined this web request",
                    started,
                )))
            }
            Err(error) => {
                return Ok(Some(web_tool_failure(
                    call.clone(),
                    format!("Could not confirm authorization for this web request: {error}"),
                    started,
                )))
            }
        }
    }
    Ok(None)
}

fn web_tool_success(call: ToolCall, output: String, started: Instant) -> ToolExecution {
    ToolExecution {
        call,
        result: ToolResult {
            success: true,
            output,
            images: Vec::new(),
            diff: None,
            executed_at: Utc::now().to_rfc3339(),
            duration_ms: started.elapsed().as_millis().min(u64::MAX as u128) as u64,
        },
        subagent: None,
    }
}

/// The catalog-facing `web_search` backends, prepared before spawn.
///
/// Web search always runs in a background worker. Resolve an owned worker payload
/// before spawn; reject locally detectable configuration errors synchronously so a
/// repairable error points to settings without creating an immediately failed task.
enum PreparedWebSearchBackend {
    Native {
        template: RunModelRequest,
    },
    Provider {
        resolved: crate::model::ResolvedSearchProvider,
        execution: crate::model::SearchExecutionConfig,
        query: String,
    },
}

const WEB_SEARCH_REPAIR_HINT: &str =
    "Select Native or an enabled provider in the conversation's Search provider setting";

fn prepare_web_search_backend(
    parent: &RunModelRequest,
    query: String,
) -> Result<PreparedWebSearchBackend, String> {
    match parent.web_search.backend.clone() {
        None => Err(format!(
            "No usable search backend is configured; {WEB_SEARCH_REPAIR_HINT}"
        )),
        Some(SearchBackend::Native) => {
            let (provider, model) = resolve_native_search_endpoint(parent);
            // Chat Completions has no provider-executed tools, and generic OpenAI-
            // compatible providers silently discard them. Reject before spawning so
            // a successful request cannot silently omit search.
            if !crate::web_search::family_supports_native_search(
                crate::aisdk::protocol::Family::for_format(provider.family),
            ) {
                return Err(format!(
                    "Provider {} belongs to the {} family, which has no native web-search tool; {WEB_SEARCH_REPAIR_HINT}",
                    provider.name,
                    serde_json::to_value(provider.family)
                        .ok()
                        .and_then(|value| value.as_str().map(str::to_owned))
                        .unwrap_or_else(|| "unknown".into()),
                ));
            }
            let template = web_search_request_template(
                parent,
                provider,
                model,
                web_search_native_task(&parent.prompt_profile, &query),
            );
            Ok(PreparedWebSearchBackend::Native { template })
        }
        Some(SearchBackend::Provider(resolved)) => Ok(PreparedWebSearchBackend::Provider {
            resolved,
            execution: parent.web_search.execution.clone(),
            query,
        }),
    }
}

/// Worker outcome. Cancellation propagates because the whole run is stopping;
/// failures become model-readable, repairable tool results.
#[derive(Debug)]
enum AsyncToolError {
    Cancelled,
    Failed(String),
}

/// The retrieval core an async `web_search` worker runs — the two backends,
/// unchanged:
///
/// - `Native` sends **one** stateless model request whose only capability is
///   the upstream's own server-side search tool, and returns that request's
///   text.
/// - A catalog provider runs the Cherry-Studio pipeline **in this process**
///   and returns normalized results.
///
/// `event_sink` is the worker-owned probe, not a model-run sink: it reports an
/// error exactly when the owning run was cancelled.
fn perform_prepared_web_search(
    prepared: &PreparedWebSearchBackend,
    profile: &PromptProfile,
    event_sink: &ModelEventSink<'_>,
    round: usize,
) -> Result<String, AsyncToolError> {
    match prepared {
        PreparedWebSearchBackend::Native { template } => {
            match perform_web_search_request(template, event_sink, round) {
                Ok(outcome) => Ok(web_search_output(profile, &outcome)),
                Err(ModelRequestError::EventSink(_)) => Err(AsyncToolError::Cancelled),
                Err(error) => Err(AsyncToolError::Failed(format!(
                    "Web search failed: {}",
                    error.message()
                ))),
            }
        }
        PreparedWebSearchBackend::Provider {
            resolved,
            execution,
            query,
        } => {
            let outcome = crate::web_search::pipeline::run_capability(
                SearchCapability::SearchKeywords,
                resolved,
                execution,
                crate::web_search::stored_secret(
                    resolved.kind,
                    crate::web_search::CredentialSlot::ApiKey,
                ),
                crate::web_search::stored_secret(
                    resolved.kind,
                    crate::web_search::CredentialSlot::BasicAuthPassword,
                ),
                vec![query.clone()],
                // Keyword search never names a target itself; whatever the engine
                // returns stays outward-only.
                false,
                event_sink,
            );
            match outcome {
                Ok(items) => Ok(web_results_output(profile, &items)),
                Err(crate::web_search::SearchError::Cancelled(_)) => Err(AsyncToolError::Cancelled),
                Err(crate::web_search::SearchError::Config(message)) => Err(
                    AsyncToolError::Failed(format!("{message}; {WEB_SEARCH_REPAIR_HINT}")),
                ),
                Err(crate::web_search::SearchError::Transient(message)) => {
                    Err(AsyncToolError::Failed(message))
                }
            }
        }
    }
}

/// Fetch uses a global backend, not a per-conversation choice. Neither wire
/// protocol exposes page fetching as a server tool, so `web_fetch` always calls
/// a catalog provider that declares Cherry `fetchUrls` capability.
const WEB_FETCH_REPAIR_HINT: &str =
    "Choose a fetch provider in this conversation's web-search settings, or switch to a search backend that fetches pages itself";

/// `Native` output contract: sanitize findings, cap them at 32K, list the sites
/// the provider consulted, and mark the whole thing untrusted because upstream
/// web-derived text is data, never instructions.
///
/// `sources` is a field rather than a rendered list at the end of the prose. The
/// model reads the same JSON either way, but a field cannot be truncated off by
/// a long report, and the timeline can build per-site chips from it without
/// parsing prose back apart.
///
/// `notice` carries the profile's wording for the untrusted marking; the key is
/// empty by default and an empty notice is left out of the envelope rather than
/// sent as `""`.
fn web_search_output(profile: &PromptProfile, outcome: &NativeSearchOutcome) -> String {
    let mut envelope = json!({
        "findings": sanitize_instruction_shaped_text(
            profile,
            &outcome.findings,
            WEB_RESEARCH_MAX_FINDING_REPORT,
        ),
        "sources": outcome
            .sources
            .iter()
            .map(|source| {
                let mut entry = serde_json::Map::new();
                if let Some(url) = source.url.as_deref().map(str::trim).filter(|url| !url.is_empty())
                {
                    entry.insert(
                        "url".to_owned(),
                        Value::String(url.chars().take(512).collect::<String>()),
                    );
                }
                if let Some(title) = source
                    .title
                    .as_deref()
                    .map(str::trim)
                    .filter(|title| !title.is_empty())
                {
                    entry.insert(
                        "title".to_owned(),
                        Value::String(sanitize_instruction_shaped_text(profile, title, 160)),
                    );
                }
                Value::Object(entry)
            })
            .filter(|entry| !entry.as_object().is_some_and(serde_json::Map::is_empty))
            .collect::<Vec<_>>(),
        "untrustedWebContent": true,
    });
    insert_web_notice(&mut envelope, profile, PromptKey::WebFindingsNotice);
    serde_json::to_string_pretty(&envelope).unwrap_or_else(|_| "{\"findings\":\"\"}".into())
}

/// Adds the profile's untrusted-content `notice` to a web envelope, unless the
/// profile leaves that key empty — the default, since a user-configured search
/// backend is a trusted one.
fn insert_web_notice(envelope: &mut Value, profile: &PromptProfile, key: PromptKey) {
    let notice = profile.text(key);
    if notice.is_empty() {
        return;
    }
    if let Some(object) = envelope.as_object_mut() {
        object.insert("notice".to_owned(), Value::String(notice.to_owned()));
    }
}

/// Output contract for catalog providers and `web_fetch`.
/// Wrap the result array in one untrusted envelope and sanitize every field so
/// webpage text that resembles `System:` reaches context as data, not instructions.
fn web_results_output(
    profile: &PromptProfile,
    items: &[crate::web_search::SearchResultItem],
) -> String {
    let sanitized: Vec<crate::web_search::SearchResultItem> = items
        .iter()
        .map(|item| crate::web_search::SearchResultItem {
            title: sanitize_instruction_shaped_text(profile, &item.title, WEB_RESULT_MAX_TITLE),
            content: sanitize_instruction_shaped_text(
                profile,
                &item.content,
                WEB_RESULT_MAX_CONTENT,
            ),
            url: sanitize_instruction_shaped_text(profile, &item.url, WEB_RESULT_MAX_TITLE),
            source_input: item.source_input.clone(),
        })
        .collect();
    let mut envelope = json!({
        "results": crate::web_search::tool_output(&sanitized),
        "untrustedWebContent": true,
    });
    insert_web_notice(&mut envelope, profile, PromptKey::WebResultsNotice);
    serde_json::to_string_pretty(&envelope).unwrap_or_else(|_| "{\"results\":[]}".into())
}

fn model_stop_reason_is_round_limit(reason: &str) -> bool {
    matches!(reason, "subagent_round_limit" | "hook_continuation_limit")
}

/// Classifies the terminal state a child reached. Every distinction here was
/// previously collapsed to `Interrupted`, which left the parent unable to tell a
/// retryable provider error from a deliberate stop from a truncated-but-valid
/// result.
fn subagent_run_status(stop_reason: Option<&str>) -> SubagentRunStatus {
    match stop_reason {
        Some("error") | Some("structured_output_retry_limit") => SubagentRunStatus::Failed,
        // Ordered before the generic stop test: the round-limit reasons are a
        // subset of `model_stop_reason_is_stopped`.
        Some(reason) if model_stop_reason_is_round_limit(reason) => SubagentRunStatus::RoundLimit,
        Some(reason) if model_stop_reason_is_stopped(reason) => SubagentRunStatus::Stopped,
        _ => SubagentRunStatus::Completed,
    }
}

fn agent_definition_precedence(source: AgentDefinitionSource) -> u8 {
    match source {
        AgentDefinitionSource::Managed => 4,
        AgentDefinitionSource::Project => 3,
        AgentDefinitionSource::User => 2,
        AgentDefinitionSource::Plugin => 1,
    }
}

fn agent_definition_is_applicable(definition: &AgentDefinition, workspace_id: &str) -> bool {
    match definition.source {
        AgentDefinitionSource::Project => definition.source_key == workspace_id,
        AgentDefinitionSource::User
        | AgentDefinitionSource::Plugin
        | AgentDefinitionSource::Managed => true,
    }
}

/// The roles one conversation offers, read fresh from the document.
///
/// Roles belong to a conversation through its preset, so "which roles exist"
/// is a question that only has an answer relative to a conversation. They are
/// deliberately re-read from disk on every resolution rather than carried on the
/// request: the identity ledger check exists precisely to notice a definition
/// that changed mid-run, and a cached copy could not.
///
/// An unknown conversation resolves to no roles rather than to an error. That
/// is the same outcome the model sees for a conversation with none configured,
/// which is the point — a run whose conversation row has gone must not be able
/// to distinguish itself from an ordinary empty one.
fn conversation_agent_definitions<'a>(
    document: &'a crate::model::AppDocument,
    workspace_id: &str,
    conversation_id: &str,
) -> &'a [AgentDefinition] {
    document
        .workspaces
        .iter()
        .find(|workspace| workspace.id == workspace_id)
        .and_then(|workspace| {
            workspace
                .conversations
                .iter()
                .find(|conversation| conversation.id == conversation_id)
        })
        .map(|conversation| conversation.settings.agent_definitions.as_slice())
        .unwrap_or_default()
}

/// The roles visible to one run. Split from the lookup above so every caller
/// spells the same `(workspace, conversation)` pair rather than half of it.
fn request_agent_definitions<'a>(
    document: &'a crate::model::AppDocument,
    request: &RunModelRequest,
) -> &'a [AgentDefinition] {
    conversation_agent_definitions(document, &request.workspace_id, &request.conversation_id)
}

/// Separators are cosmetic in an agent slug, so `code_reviewer` and
/// `code-reviewer` address the same definition. The slug rule already forces
/// lowercase, so folding case here would be redundant.
/// The form two names are compared in once an exact match has already failed.
///
/// A role name is free text, so what the model emits for it will not always be
/// byte-identical to what is stored: it lower-cases a name it read in a listing,
/// it writes a space where the role has a hyphen, it wraps the name in the
/// quotes it was quoting it with, it keeps the newline it split a line on. None
/// of those is a different role, and spending a round telling the model so is
/// spending a round on punctuation.
///
/// So this folds away exactly the things that carry no meaning in a name: outer
/// whitespace and quoting, letter case, and the separators — space, `-`, `_` —
/// that spell one word three ways. It folds NOTHING else: two roles that differ
/// by a real character still normalise apart, and a fold that lands on more than
/// one role is reported as ambiguous rather than guessed at. Used only after the
/// exact pass has found nothing, so a loose reading can never shadow a role that
/// really is called that.
fn normalized_agent_type(agent_type: &str) -> String {
    agent_type
        .trim()
        .trim_matches(|character| {
            matches!(
                character,
                '"' | '\'' | '`' | '“' | '”' | '‘' | '’' | '「' | '」' | '《' | '》'
            )
        })
        .to_lowercase()
        .chars()
        .filter(|character| !character.is_whitespace() && *character != '-' && *character != '_')
        .collect()
}

/// Whether this definition's model binding resolves right now.
///
/// A role names a MODEL the user chose, and `Explicit` records the exact
/// `(provider_id, model_id)` pair rather than a bare model ID because two
/// providers may both offer `gpt-4o` and they are not the same model. When that
/// pair no longer resolves — provider deleted, provider disabled, chat turned
/// off, model removed, model disabled — the role cannot run at all, so it must
/// not be offered: advertising a name whose only possible outcome is a spawn
/// failure trains the model to retry something that can never work.
///
/// `Inherit` always resolves; it rides the parent's provider and model, which
/// exist by construction because the parent is mid-run.
fn agent_definition_model_is_available(
    document: &crate::model::AppDocument,
    definition: &AgentDefinition,
) -> bool {
    match &definition.model_selection {
        AgentModelSelection::Inherit => true,
        // Already the recorded outcome of this very check; re-running it against
        // the providers would be asking a question the value has answered.
        AgentModelSelection::Unavailable => false,
        AgentModelSelection::Explicit {
            provider_id,
            model_id,
        } => enabled_provider_model(document, provider_id, model_id).is_ok(),
    }
}

/// Every agent type that would resolve successfully right now, sorted, together
/// with what the user says each one is for. Used both for the model-facing
/// schemas and to make a resolution failure actionable instead of a dead end.
///
/// The description is read off the definition `resolve_applicable_agent_definition`
/// actually returns, never off a second lookup by name. A managed `reviewer`
/// shadows a user `reviewer`, and advertising the user's prose while the spawn
/// derives the managed one would misroute the model with text describing a role
/// that will not run.
fn available_agent_types(
    document: &crate::model::AppDocument,
    definitions: &[AgentDefinition],
    workspace_id: &str,
) -> Vec<crate::builtin_schemas::AgentRoleSummary> {
    let mut names = definitions
        .iter()
        .filter(|definition| agent_definition_is_applicable(definition, workspace_id))
        .map(|definition| definition.name.as_str())
        .collect::<Vec<_>>();
    names.sort_unstable();
    names.dedup();
    names
        .into_iter()
        // Resolving each name rather than re-deriving the predicate keeps the
        // shadow-revoke rule in exactly one place. The model-binding check rides
        // the same resolution so a role whose model went away disappears from
        // the listing instead of failing only once the model has committed to
        // spawning it.
        .filter_map(|name| {
            let definition =
                resolve_applicable_agent_definition(definitions, workspace_id, name).ok()?;
            agent_definition_model_is_available(document, definition).then(|| {
                crate::builtin_schemas::AgentRoleSummary {
                    name: definition.name.clone(),
                    description: definition.description.clone(),
                }
            })
        })
        .collect()
}

/// The name half of [`available_agent_types`]. Kept as its own function because
/// the resolution-failure messages want the legal names and nothing else.
fn available_agent_type_names(
    document: &crate::model::AppDocument,
    definitions: &[AgentDefinition],
    workspace_id: &str,
) -> Vec<String> {
    available_agent_types(document, definitions, workspace_id)
        .into_iter()
        .map(|role| role.name)
        .collect()
}

/// Role policy for this run: legal roles and whether a child must name one.
/// Compute both together in this order: `required` is valid only when legal roles
/// exist, since requiring a field with no legal value makes every call fail.
pub(crate) struct RolePolicy {
    /// Available roles for this run. `None` means the document was unreadable:
    /// do not require or validate names, matching schema injection's static fallback.
    roles: Option<Vec<crate::builtin_schemas::AgentRoleSummary>>,
    required: bool,
}

impl RolePolicy {
    /// Most permissive policy when the document cannot be read.
    fn unknown() -> Self {
        Self {
            roles: None,
            required: false,
        }
    }

    /// Whether this run requires a named role.
    pub(crate) fn required(&self) -> bool {
        self.required
    }

    /// Legal role names; `None` disables name validation for this run.
    pub(crate) fn known_names(&self) -> Option<Vec<String>> {
        self.roles
            .as_ref()
            .map(|roles| roles.iter().map(|role| role.name.clone()).collect())
    }

    /// Available roles and their descriptions; `None` has the same meaning.
    fn roles(&self) -> Option<&[crate::builtin_schemas::AgentRoleSummary]> {
        self.roles.as_deref()
    }
}

/// Read from disk on every check so the identity ledger can detect definitions
/// changed during a run; a request-cached copy cannot do that.
pub(crate) fn role_policy(request: &RunModelRequest, state: &AppState) -> RolePolicy {
    let Ok(document) = current_agent_document(request, state) else {
        return RolePolicy::unknown();
    };
    let definitions = request_agent_definitions(&document, request);
    let roles = available_agent_types(&document, definitions, &request.workspace_id);
    let allow_roleless = conversation_allows_roleless_subagents(
        &document,
        &request.workspace_id,
        &request.conversation_id,
    );
    RolePolicy {
        required: !allow_roleless && !roles.is_empty(),
        roles: Some(roles),
    }
}

/// Conversation setting permitting children without named roles.
/// An unknown conversation is permissive, matching unknown definitions: missing
/// data must not itself reject a call.
fn conversation_allows_roleless_subagents(
    document: &crate::model::AppDocument,
    workspace_id: &str,
    conversation_id: &str,
) -> bool {
    document
        .workspaces
        .iter()
        .find(|workspace| workspace.id == workspace_id)
        .and_then(|workspace| {
            workspace
                .conversations
                .iter()
                .find(|conversation| conversation.id == conversation_id)
        })
        .map(|conversation| conversation.settings.allow_roleless_subagents)
        .unwrap_or(true)
}

/// Which enabled tools carry a role selector in this run.
///
/// `agent_spawn` names one through `agent_type`; a workflow step names one
/// through `agentType`. Both land on the same definition through
/// [`apply_named_role_to_fresh_template`], so a run that holds either tool can
/// act on the role set — but a tool that is disabled is left out, because
/// advertising it would name a capability `automatic_tool_rejection_reason`
/// then refuses.
///
/// The returned names are also the injection targets: these are exactly the
/// descriptors whose schema has to carry this conversation's role names.
fn agent_type_selector_tools(enabled_tools: &[String]) -> Vec<&'static str> {
    let mut selectors = Vec::new();
    if enabled_tools.iter().any(|tool| tool == "agent_spawn") {
        selectors.push("agent_spawn");
    }
    if enabled_tools
        .iter()
        .any(|tool| tool == workflow::WORKFLOW_TOOL)
    {
        selectors.push(workflow::WORKFLOW_TOOL);
    }
    selectors
}

/// Top level only, and only when the model can actually act on it.
///
/// A child already received its identity through the named template and holds
/// neither selector, so specialising its schemas would be a no-op on a tool it
/// cannot call.
fn should_inject_agent_types(request: &RunModelRequest) -> bool {
    request.subagent_depth == 0 && !agent_type_selector_tools(&request.enabled_tools).is_empty()
}

/// Which single tool carries the human-readable role block this run.
///
/// Both selectors take the same `agentType` values, so both would carry the same
/// paragraph — and sending one request with the identical text twice buys the
/// model nothing. `workflow` wins because a workflow script is the surface that
/// picks roles in bulk; `agent_spawn` gets the block only when it is the only
/// one on.
///
/// This is deliberately NOT [`agent_type_selector_tools`]. That function decides
/// where the machine-readable `enum` / `$defs` goes, and it must keep going to
/// EVERY selector: a run holding both tools where `agent_spawn` lost its
/// `agent_type` enum would still be able to call `agent_spawn`, now against a
/// static schema that names no legal value.
fn role_description_carrier(enabled_tools: &[String]) -> Option<&'static str> {
    let selectors = agent_type_selector_tools(enabled_tools);
    selectors
        .contains(&workflow::WORKFLOW_TOOL)
        .then_some(workflow::WORKFLOW_TOOL)
        .or_else(|| selectors.first().copied())
}

/// Bakes this conversation's available roles into the schemas of the tools that
/// can name a role.
///
/// Two things go in, and they are different kinds of claim. The NAMES are a
/// constraint, so they go in machine-readable — an `enum` on
/// `agent_spawn.agent_type`, a root `$defs.agentType` for the `agentType` written
/// inside a workflow script — and they go to every selector the run holds. What
/// each role is FOR is prose, and prose can only be prose: it is appended to the
/// tool's own description, on exactly one carrier
/// ([`role_description_carrier`]).
///
/// The empty set is injected too, and that is the point: with no role
/// configured, `agent_spawn.agent_type` disappears from the schema entirely
/// rather than advertising a field whose every value would be refused.
///
/// `input_schema` is the first rung of `protocol_adapter::chat::tools::
/// tool_schema`'s four-level ladder, and all three wire protocols wrap that one
/// value — so writing it here reaches Responses, Chat and Anthropic alike. It is
/// also where a built-in tool's own description actually lives: every catalog
/// descriptor's `description` is the empty string and belongs to the user's
/// tool-description override (`lib::tool_catalog_with_descriptions`), which this
/// must not touch.
fn inject_agent_type_schemas(
    request: &mut RunModelRequest,
    roles: &[crate::builtin_schemas::AgentRoleSummary],
    role_required: bool,
) {
    let names = roles
        .iter()
        .map(|role| role.name.clone())
        .collect::<Vec<_>>();
    let carrier = role_description_carrier(&request.enabled_tools);
    for tool in agent_type_selector_tools(&request.enabled_tools) {
        let mut schema = if tool == "agent_spawn" {
            crate::builtin_schemas::agent_spawn_schema_for_roles(
                &names,
                role_required,
                &request.prompt_profile,
            )
        } else {
            crate::builtin_schemas::workflow_schema_for_roles(
                &names,
                role_required,
                &request.prompt_profile,
            )
        };
        if carrier == Some(tool) {
            crate::builtin_schemas::append_role_descriptions(
                &mut schema,
                roles,
                &request.prompt_profile,
            );
        }
        if let Some(descriptor) = request.tools.iter_mut().find(|entry| entry.name == tool) {
            descriptor.input_schema = Some(schema);
        }
    }
}

/// Stable card id for a skill delivered as a host notice.
///
/// Derived from the skill's catalog id, which is the whole of the
/// de-duplication: the next round finds the card already in the transcript and
/// delivers nothing. It carries the delivery prefix, because the card is a
/// `box` delivery like every other host notice.
pub(crate) fn added_skill_context_id(resource_id: &str) -> String {
    format!("{AGENT_RESULT_CONTEXT_ID_PREFIX}skill_{resource_id}")
}

/// The id conversations recorded before skills arrived as host notices gave
/// the same delivery: a system card. Still counted, so an old conversation is
/// not handed the skill a second time.
fn legacy_added_skill_context_id(resource_id: &str) -> String {
    format!("ctx_skill_{resource_id}")
}

/// Puts each skill selected after this conversation opened in front of the
/// model as a host notice.
///
/// A skill chosen before the first run is part of the system prompt, and that
/// prompt is what every earlier round was answered against — a later one cannot
/// join it without rewriting what those rounds were replying to, and on the
/// dialects that pin their tool set it could not join the `skill` tool's schema
/// either. So it arrives here instead: once, at the round it was added, at the
/// end of the transcript, and carried by the history from then on.
fn record_added_skill_contexts(request: &mut RunModelRequest) {
    if request.added_skills.is_empty() {
        return;
    }
    let present = request
        .contexts
        .iter()
        .map(|context| context.id().to_owned())
        .collect::<HashSet<_>>();
    for skill in std::mem::take(&mut request.added_skills) {
        let id = added_skill_context_id(&skill.resource_id);
        if present.contains(&id)
            || present.contains(&legacy_added_skill_context_id(&skill.resource_id))
        {
            continue;
        }
        let summary = request
            .prompt_profile
            .render(PromptKey::HostNoticeSkillAddedSummary, &[("name", &skill.name)]);
        request.host_notices.push(crate::model::HostNotice {
            kind: crate::wire_history::notice_kind::SKILL_ADDED,
            summary,
            body: skill.content,
            id: Some(id),
        });
    }
}

/// Executes one `skill` call against the bodies the trusted request carries.
///
/// There is no filesystem access here on purpose. The bodies were read once, by
/// the request builder, from the descriptor's own no-follow path under the
/// app-data skill root — so a model naming a skill can never reach a file the
/// conversation did not select, and there is nothing here for a path argument
/// to point at.
///
/// The base directory leads: a skill's instructions routinely reference
/// `scripts/…` or `references/…` relative to their own directory, and those
/// references are unresolvable without it.
fn run_skill_tool(request: &RunModelRequest, input: &JsonObject) -> Result<String, String> {
    let name = input
        .get("name")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|name| !name.is_empty())
        .ok_or_else(|| "Missing parameter name".to_owned())?;
    let skill = request
        .skills
        .iter()
        .find(|skill| skill.name == name)
        .ok_or_else(|| {
            let available = request
                .skills
                .iter()
                .map(|skill| skill.name.as_str())
                .collect::<Vec<_>>()
                .join(", ");
            if available.is_empty() {
                format!("Skill {name} is not among this conversation's available skills")
            } else {
                format!("Skill {name} is not among this conversation's available skills; available: {available}")
            }
        })?;
    Ok(request.prompt_profile.render(
        PromptKey::SkillResult,
        &[("directory", &skill.directory), ("body", &skill.body)],
    ))
}

/// The tokens a deferred tool's name contributes to a keyword match.
///
/// An MCP name is `mcp__<server>__<tool>`, so the server and the tool are split
/// apart and each is also kept whole: a query naming the server should reach
/// every tool it declared, and a query naming the tool should reach it whatever
/// server it came from. A non-MCP name is split on case changes and
/// underscores, so `create_issue` answers to "create" and to "issue".
struct ToolNameParts {
    /// Individual words, lowercased.
    parts: Vec<String>,
    /// The whole server and tool segments, lowercased, unsplit.
    coarse: Vec<String>,
    /// Whether the name came from an MCP server, which scores higher: the model
    /// is searching a list that is entirely MCP, so a name hit there is the
    /// signal rather than the noise.
    is_mcp: bool,
}

fn tool_name_parts(name: &str) -> ToolNameParts {
    if let Some(rest) = name.strip_prefix("mcp__") {
        let (server, tool) = match rest.split_once("__") {
            Some((server, tool)) => (server, tool),
            None => (rest, ""),
        };
        let coarse = [server, tool]
            .into_iter()
            .filter(|segment| !segment.is_empty())
            .map(str::to_lowercase)
            .collect::<Vec<_>>();
        let parts = coarse
            .iter()
            .flat_map(|segment| {
                segment
                    .split(|character: char| character == '_' || character == '.' || character == '-' || character.is_whitespace())
                    .filter(|word| !word.is_empty())
                    .map(str::to_owned)
                    .collect::<Vec<_>>()
            })
            .collect();
        return ToolNameParts {
            parts,
            coarse,
            is_mcp: true,
        };
    }
    let mut spaced = String::new();
    let mut previous_lower = false;
    for character in name.chars() {
        if character.is_uppercase() && previous_lower {
            spaced.push(' ');
        }
        previous_lower = character.is_lowercase();
        spaced.push(if character == '_' { ' ' } else { character });
    }
    ToolNameParts {
        parts: spaced
            .to_lowercase()
            .split_whitespace()
            .map(str::to_owned)
            .collect(),
        coarse: vec![name.to_lowercase()],
        is_mcp: false,
    }
}

/// Whether `haystack` contains `needle` as a whole word.
///
/// Substring matching on a description is too generous — "get" would hit
/// "widget" — so the description half of the score asks for a word boundary,
/// while the name half deliberately keeps substring matching: names are
/// compounds, and "issue" should reach `create_issue`.
fn contains_word(haystack: &str, needle: &str) -> bool {
    let bytes = haystack.as_bytes();
    let boundary = |index: usize| match bytes.get(index) {
        None => true,
        Some(byte) => !byte.is_ascii_alphanumeric() && *byte != b'_',
    };
    let mut from = 0;
    while let Some(offset) = haystack[from..].find(needle) {
        let start = from + offset;
        let end = start + needle.len();
        let before_ok = start == 0 || boundary(start - 1);
        if before_ok && boundary(end) {
            return true;
        }
        from = start + 1;
    }
    false
}

/// Ranks this run's deferred tools against a keyword query.
///
/// Ported from Claude Code's `ToolSearchTool` keyword search, including its
/// weights: an exact word in the name outranks a substring of one, a hit in the
/// name outranks a hit in the description, and a term prefixed with `+` is a
/// filter rather than a ranking signal — every candidate must satisfy it, and
/// the remaining terms decide the order.
fn rank_deferred_tools(
    request: &RunModelRequest,
    query: &str,
    max_results: usize,
) -> Vec<String> {
    let lowered = query.to_lowercase();
    let mut required = Vec::new();
    let mut optional = Vec::new();
    for term in lowered.split_whitespace() {
        match term.strip_prefix('+') {
            Some(rest) if !rest.is_empty() => required.push(rest.to_owned()),
            _ => optional.push(term.to_owned()),
        }
    }
    // With a `+` term present the required words still take part in the
    // ranking; without one every word does, which is the same list.
    let terms = if required.is_empty() {
        optional.clone()
    } else {
        required.iter().chain(optional.iter()).cloned().collect()
    };
    if terms.is_empty() {
        return Vec::new();
    }

    let mut scored = Vec::new();
    for deferred in &request.deferred_tools {
        let Some(descriptor) = request
            .tools
            .iter()
            .find(|tool| tool.name == deferred.name)
        else {
            continue;
        };
        let parts = tool_name_parts(&deferred.name);
        let description = descriptor.description.to_lowercase();
        let server = deferred.server_name.to_lowercase();
        let matches_term = |term: &String| {
            parts.parts.iter().any(|part| part.contains(term.as_str()))
                || parts.coarse.iter().any(|part| part.contains(term.as_str()))
                || contains_word(&server, term)
                || contains_word(&description, term)
        };
        if !required.iter().all(matches_term) {
            continue;
        }
        let mut score = 0u32;
        for term in &terms {
            if parts.parts.iter().any(|part| part == term) {
                score += if parts.is_mcp { 12 } else { 10 };
            } else if parts.parts.iter().any(|part| part.contains(term.as_str())) {
                score += if parts.is_mcp { 6 } else { 5 };
            }
            if parts.coarse.iter().any(|part| part == term) {
                score += if parts.is_mcp { 12 } else { 10 };
            } else if parts.coarse.iter().any(|part| part.contains(term.as_str())) {
                score += if parts.is_mcp { 4 } else { 3 };
            }
            if contains_word(&server, term) {
                score += 4;
            }
            if contains_word(&description, term) {
                score += 2;
            }
        }
        if score > 0 {
            scored.push((score, deferred.name.clone()));
        }
    }
    // Descending score, then by name, so two tools that tie do not swap places
    // between one call and the next.
    scored.sort_by(|left, right| right.0.cmp(&left.0).then_with(|| left.1.cmp(&right.1)));
    scored
        .into_iter()
        .take(max_results)
        .map(|(_, name)| name)
        .collect()
}

/// Renders the matched tools as a `<functions>` block.
///
/// The encoding is the one the tool's own description promises: one
/// `<function>{…}</function>` line per tool, carrying exactly the JSON the wire
/// tool set would have carried. Anything else would teach the model a second
/// shape for the same thing.
fn render_tool_functions_block(request: &RunModelRequest, names: &[String]) -> String {
    let mut lines = vec!["<functions>".to_owned()];
    for name in names {
        let Some(descriptor) = request.tools.iter().find(|tool| &tool.name == name) else {
            continue;
        };
        let entry = json!({
            "description": descriptor.description,
            "name": descriptor.name,
            "parameters": crate::aisdk::tools::tool_schema(
                descriptor,
                &request.prompt_profile,
                &request.workspaces,
            ),
        });
        lines.push(format!("<function>{entry}</function>"));
    }
    lines.push("</functions>".to_owned());
    lines.join("\n")
}

/// Executes one `tool_search` call against the tools this run withheld.
///
/// Two query forms, both from Claude Code: `select:<name>[,<name>…]` fetches
/// exact names, anything else is a keyword search. There is no filesystem or
/// network access here and nothing is dialed — every schema this can return was
/// discovered by `attach_mcp_tools` before the first step, so the call is a
/// lookup in the request the run is already holding.
///
/// Surfacing is the caller's half: this returns the names it matched, and the
/// round loop is what adds them to `enabled_tools` so the next step declares
/// them for real.
fn run_tool_search_tool(
    request: &RunModelRequest,
    input: &JsonObject,
) -> Result<(String, Vec<String>), String> {
    let query = input
        .get("query")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|query| !query.is_empty())
        .ok_or_else(|| "Missing parameter query".to_owned())?;
    let max_results = input
        .get("max_results")
        .and_then(Value::as_u64)
        .map(|value| value.clamp(1, 50) as usize)
        .unwrap_or(5);

    let matches = match query
        .split_once(':')
        .filter(|(head, _)| head.eq_ignore_ascii_case("select"))
    {
        Some((_, names)) => {
            let mut resolved = Vec::new();
            let mut missing = Vec::new();
            for wanted in names.split(',').map(str::trim).filter(|name| !name.is_empty()) {
                match request
                    .deferred_tools
                    .iter()
                    .find(|tool| tool.name.eq_ignore_ascii_case(wanted))
                {
                    // A tool named twice in one query is fetched once: the
                    // result is a set of definitions, not a transcript of the
                    // query.
                    Some(tool) if !resolved.contains(&tool.name) => resolved.push(tool.name.clone()),
                    Some(_) => {}
                    None => missing.push(wanted.to_owned()),
                }
            }
            // A partial select still returns what it found; the miss is
            // reported by the no-match text only when nothing resolved at all,
            // because a model that asked for three tools and got two can see
            // which one is absent from the block.
            if resolved.is_empty() && !missing.is_empty() {
                Vec::new()
            } else {
                resolved
            }
        }
        None => rank_deferred_tools(request, query, max_results),
    };

    if matches.is_empty() {
        return Ok((
            request.prompt_profile.render(
                PromptKey::ToolSearchNoMatch,
                &[
                    ("query", query),
                    ("total", &request.deferred_tools.len().to_string()),
                ],
            ),
            Vec::new(),
        ));
    }
    let functions = render_tool_functions_block(request, &matches);
    Ok((
        request
            .prompt_profile
            .render(PromptKey::ToolSearchResult, &[("functions", &functions)]),
        matches,
    ))
}

/// Adds every tool `tool_search` has handed a schema out for to the run's
/// enabled set, so the next step declares it like any other tool.
///
/// Idempotent, and called on every settled tool rather than only on
/// `tool_search` ones: the state is the whole truth, and re-deriving from it is
/// cheaper than tracking which call last changed it.
fn surface_deferred_tools(request: &mut RunModelRequest, state: &ToolSearchTurnState) {
    if state.surfaced.is_empty() {
        return;
    }
    let mut widened = false;
    for name in &state.surfaced {
        if !request.enabled_tools.iter().any(|entry| entry == name) {
            request.enabled_tools.push(name.clone());
            widened = true;
        }
    }
    if widened {
        request.enabled_tools.sort();
        request.enabled_tools.dedup();
    }
}

/// Resolution without the available-set suffix. Split out so
/// [`available_agent_type_names`] can call it without recursing through the
/// error path that calls *it*.
fn resolve_applicable_agent_definition<'a>(
    definitions: &'a [AgentDefinition],
    workspace_id: &str,
    agent_type: &str,
) -> Result<&'a AgentDefinition, String> {
    let mut candidates = definitions
        .iter()
        .filter(|definition| {
            definition.name == agent_type
                && agent_definition_is_applicable(definition, workspace_id)
        })
        .collect::<Vec<_>>();
    let Some(highest) = candidates
        .iter()
        .map(|definition| agent_definition_precedence(definition.source))
        .max()
    else {
        return Err(format!(
            "Trusted named-agent definition {agent_type} does not exist or does not apply to the current workspace"
        ));
    };
    candidates.retain(|definition| agent_definition_precedence(definition.source) == highest);
    if candidates.len() != 1 {
        return Err(format!(
            "Trusted named-agent definition {agent_type} is ambiguous at the same precedence; selection was refused"
        ));
    }
    let definition = candidates[0];
    if definition.deleted {
        return Err(format!(
            "Trusted named-agent definition {agent_type} was deleted"
        ));
    }
    if !definition.enabled {
        return Err(format!(
            "Trusted named-agent definition {agent_type} is disabled"
        ));
    }
    Ok(definition)
}

/// Resolves a public `agent_type` against host-owned definitions. A disabled
/// higher-precedence definition shadows lower-precedence definitions instead
/// of silently falling through, so managed/project policy can revoke a name.
///
/// An exact match wins outright. Only when no definition carries that exact
/// name does the loose second pass run — case, outer quoting and separators
/// folded away, see `normalized_agent_type` — so a slip in how the model
/// re-typed a free-text name is recoverable without ever letting the loose form
/// override a role that really is called that. A loose reading is accepted only
/// when it lands on exactly one role; landing on several is reported as
/// ambiguous rather than guessed at. Failures name the available set — the
/// model cannot otherwise discover what it may retry with.
/// The "no such agent type" error, with the available set appended.
///
/// Shared so the unknown-name path and the model-is-unavailable path produce
/// BYTE-IDENTICAL text. Two hand-written copies would drift, and the moment
/// they differ the model can distinguish a role that does not exist from a role
/// whose model the user disabled — a distinction it cannot act on and should
/// not be able to probe for.
fn unknown_agent_type_error(
    document: &crate::model::AppDocument,
    definitions: &[AgentDefinition],
    workspace_id: &str,
    agent_type: &str,
) -> String {
    let available = available_agent_type_names(document, definitions, workspace_id);
    let available_suffix = if available.is_empty() {
        "; no named agents are currently available".to_owned()
    } else {
        format!("; available: {}", available.join(", "))
    };
    format!("Trusted named-agent definition {agent_type} does not exist or does not apply to the current workspace{available_suffix}")
}

fn resolve_agent_definition<'a>(
    document: &'a crate::model::AppDocument,
    definitions: &'a [AgentDefinition],
    workspace_id: &str,
    agent_type: &str,
) -> Result<&'a AgentDefinition, String> {
    crate::model::validate_agent_type_name(agent_type)?;

    let exists_exactly = definitions.iter().any(|definition| {
        definition.name == agent_type && agent_definition_is_applicable(definition, workspace_id)
    });
    if exists_exactly {
        return resolvable_or_hidden(document, definitions, workspace_id, agent_type, agent_type);
    }

    let wanted = normalized_agent_type(agent_type);
    // A name that folds away to nothing carries no evidence of which role was
    // meant, so it matches none rather than whichever role also folds to empty.
    let mut matches = if wanted.is_empty() {
        Vec::new()
    } else {
        definitions
            .iter()
            .filter(|definition| {
                agent_definition_is_applicable(definition, workspace_id)
                    && normalized_agent_type(&definition.name) == wanted
            })
            .map(|definition| definition.name.as_str())
            .collect::<Vec<_>>()
    };
    matches.sort_unstable();
    matches.dedup();

    match matches.as_slice() {
        [single] => resolvable_or_hidden(document, definitions, workspace_id, single, agent_type),
        [] => Err(unknown_agent_type_error(
            document,
            definitions,
            workspace_id,
            agent_type,
        )),
        several => {
            let available = available_agent_type_names(document, definitions, workspace_id);
            let available_suffix = if available.is_empty() {
                "; no named agents are currently available".to_owned()
            } else {
                format!("; available: {}", available.join(", "))
            };
            Err(format!(
                "agent_type {agent_type} matches multiple definitions once case and separators are ignored: {}; provide the complete name{available_suffix}",
                several.join(", ")
            ))
        }
    }
}

/// Resolves `name`, then refuses a role whose model binding is gone.
///
/// Both success branches of [`resolve_agent_definition`] route through here so
/// the rule cannot hold on one spelling of a name and not the other: without
/// it, a refused role would still resolve when reached through the
/// separator-folded pass.
///
/// # Two different refusals
///
/// A role the user CONFIGURED and whose model then went away reports exactly
/// that. It is a distinct fact from "no such role" and the only one that is
/// actionable — the user has a role to repair, and telling them it does not
/// exist would send them to create a duplicate. Nothing is leaked by saying so:
/// a name that was never configured still gets the unknown-name text, so the
/// model cannot probe for roles it was never told about.
///
/// An `Explicit` binding that merely fails to resolve right now keeps the
/// unknown-name wording. That state is transient — a provider toggled off — and
/// the renderer rewrites it to `Unavailable` on the next load anyway.
///
/// `requested` is what the caller typed and is what the error names, so the
/// message stays byte-identical to the unknown-name error for that same input.
fn resolvable_or_hidden<'a>(
    document: &crate::model::AppDocument,
    definitions: &'a [AgentDefinition],
    workspace_id: &str,
    name: &str,
    requested: &str,
) -> Result<&'a AgentDefinition, String> {
    let definition = resolve_applicable_agent_definition(definitions, workspace_id, name)?;
    if definition.model_selection == AgentModelSelection::Unavailable {
        return Err(format!(
            "The model bound to named-agent definition {requested} is unavailable; choose a model again in the conversation preset's agent roles."
        ));
    }
    if !agent_definition_model_is_available(document, definition) {
        return Err(unknown_agent_type_error(
            document,
            definitions,
            workspace_id,
            requested,
        ));
    }
    Ok(definition)
}

fn enabled_provider_model(
    document: &crate::model::AppDocument,
    provider_id: &str,
    model_id: &str,
) -> Result<(ApiProvider, ModelProfile), String> {
    let provider = document
        .assets
        .api_providers
        .iter()
        .find(|provider| provider.id == provider_id)
        .cloned()
        .ok_or_else(|| {
            format!("The provider {provider_id} bound to the named agent no longer exists")
        })?;
    if !provider.enabled {
        return Err(format!(
            "The provider {provider_id} bound to the named agent is disabled"
        ));
    }
    let model = provider
        .models
        .iter()
        .find(|model| model.id == model_id)
        .cloned()
        .ok_or_else(|| {
            format!("The original model ID {model_id} bound to the named agent no longer exists in provider {provider_id}")
        })?;
    Ok((provider, model))
}

/// Scope key for user/project memory. Project and local scope by workspace;
/// user and none share the global key.
fn agent_memory_scope_key(memory: AgentDefinitionMemory, workspace_id: &str) -> String {
    match memory {
        AgentDefinitionMemory::None | AgentDefinitionMemory::User => String::new(),
        AgentDefinitionMemory::Project | AgentDefinitionMemory::Local => workspace_id.to_owned(),
    }
}

fn initial_agent_definition_binding(
    parent: &RunModelRequest,
    document: &crate::model::AppDocument,
    definition: &AgentDefinition,
) -> Result<(AgentDefinitionBinding, ApiProvider, ModelProfile), String> {
    if definition.deleted || !definition.enabled || definition.memory_epoch == 0 {
        return Err("A deleted or disabled named-agent definition, or one missing its host memory epoch, cannot spawn a child.".into());
    }
    let (provider, model) = match &definition.model_selection {
        AgentModelSelection::Inherit => (parent.provider.clone(), parent.model.clone()),
        // Defence in depth: `resolve_agent_definition` already refuses this role
        // before a binding is attempted, so reaching here means a new call path
        // skipped that gate. Fail rather than silently borrowing the parent's
        // model — that would run the role on a model the user never chose.
        AgentModelSelection::Unavailable => {
            return Err(format!(
                "The model bound to named-agent definition {} is unavailable",
                definition.name
            ))
        }
        AgentModelSelection::Explicit {
            provider_id,
            model_id,
        } => enabled_provider_model(document, provider_id, model_id)?,
    };
    let binding = AgentDefinitionBinding {
        source: definition.source,
        source_key: definition.source_key.clone(),
        name: definition.name.clone(),
        revision: definition.revision,
        memory_epoch: definition.memory_epoch,
        provider_id: provider.id.clone(),
        model_id: model.id.clone(),
        memory: definition.memory,
        scope_key: agent_memory_scope_key(definition.memory, &parent.workspace_id),
        configuration_receipt: String::new(),
        // Stamped from the constant at issuance and never re-assigned. The
        // version is projected into `AgentDefinitionBindingV1` and from there
        // into the execution-mode payload bytes, so the version a record
        // claims and the version its bytes were derived from stay one value
        // by construction.
        receipt_version: CURRENT_DEFINITION_RECEIPT_VERSION,
    };
    // Configuration receipts are absent; field-by-field validation detects a
    // replaced or revised definition without a signature.
    Ok((binding, provider, model))
}

/// The definition-receipt version stamped on newly issued bindings.
///
/// The stamped value is projected into `AgentDefinitionBindingV1` and then into
/// execution-mode payload bytes, so a record's claimed version and the version
/// used to derive its bytes stay aligned.
///
/// Persisted reservation rows participate in the spawn dedupe gate. This keeps
/// name selection safe across every source of execution-mode payload volatility:
/// provider/model bindings, memory configuration, definition revisions, and
/// prompt versions cannot reopen a reserved name.
pub(crate) const CURRENT_DEFINITION_RECEIPT_VERSION: u8 = 2;

/// The request's tool catalogue was minted in English. This is the one
/// host-owned language signal a child can trust: descriptor labels come from
/// `catalog::tool_catalog_for_language`, never from model input. Previously
/// open-coded three times; keep every language decision routed through here so
/// the memory prompt, the injected update tool and the subagent addendum can
/// never disagree about the same conversation.
fn request_uses_english_defaults(request: &RunModelRequest) -> bool {
    request
        .tools
        .iter()
        .any(|tool| tool.name == "ls" && tool.label == "List files")
}

fn current_agent_document(
    request: &RunModelRequest,
    state: &AppState,
) -> Result<Arc<crate::model::AppDocument>, String> {
    state
        .document_store
        .current_snapshot(&Path::new(&request.app_data_path).join("document.v1.json"))
        .map_err(|error| format!("Could not validate the current named-agent definition: {error}"))
}

fn validate_current_agent_definition(
    request: &RunModelRequest,
    state: &AppState,
) -> Result<(), String> {
    let Some(binding) = request.agent_definition_binding.as_ref() else {
        return Ok(());
    };
    if request.subagent_depth == 0 {
        return Err(
            "A top-level model request must not carry a named-agent definition binding.".into(),
        );
    }
    if request.inherits_parent_model_memory {
        return Err("A named agent cannot also inherit parent model memory.".into());
    }
    let document = current_agent_document(request, state)?;
    let definitions = request_agent_definitions(&document, request);
    let definition =
        resolve_agent_definition(&document, definitions, &request.workspace_id, &binding.name)?;
    if definition.source != binding.source
        || definition.source_key != binding.source_key
        || definition.revision != binding.revision
        || definition.memory_epoch != binding.memory_epoch
        || definition.memory != binding.memory
    {
        return Err(format!(
            "Named-agent definition {} was replaced, revised, or had its memory scope changed; the stale run was refused from continuing.",
            binding.name
        ));
    }
    let expected_scope_key = agent_memory_scope_key(binding.memory, &request.workspace_id);
    if binding.scope_key != expected_scope_key {
        return Err("The named agent's user/project/local scope binding has expired.".into());
    }
    if let AgentModelSelection::Explicit {
        provider_id,
        model_id,
    } = &definition.model_selection
    {
        if provider_id != &binding.provider_id || model_id != &binding.model_id {
            return Err(format!(
                "The explicit model binding of named-agent definition {} changed; the stale run was refused from continuing.",
                binding.name
            ));
        }
    }
    let _ = enabled_provider_model(&document, &binding.provider_id, &binding.model_id)?;
    if request.provider.id != binding.provider_id || request.model.id != binding.model_id {
        return Err("The named agent's current request does not match its exact provider/model binding at spawn time.".into());
    }
    Ok(())
}

/// Acquires and validates the exact current named-agent definition as one
/// side-effect fence. Writers cannot revoke or replace the definition between
/// the final validation and the caller's protected operation.
fn current_agent_definition_authority<'a>(
    request: &RunModelRequest,
    state: &'a AppState,
    phase: &str,
) -> Result<Option<RwLockReadGuard<'a, ()>>, String> {
    let authority = request
        .agent_definition_binding
        .as_ref()
        .map(|_| {
            state.definition_authority_lock.read().map_err(|_| {
                format!(
                    "Named-agent definition authority lock is poisoned; {phase} has not started"
                )
            })
        })
        .transpose()?;
    validate_current_agent_definition(request, state)?;
    Ok(authority)
}

/// Whether the child being configured is starting fresh or being restored.
///
/// The only thing this changes is the zero-tool refusal: refusing a RESUME would
/// turn a definition edit into "your existing agent can no longer be continued",
/// and the agent's record is already persisted by then, so failing closed
/// protects nothing that is not already on disk.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum AgentRunStart {
    Fresh,
    Resume,
}

/// Host-resolved execution overrides for one child run.
///
/// Reachable from a resolved [`AgentDefinition`] or constructed directly by host
/// code — the Workflow runtime builds one per step — and NEVER from model JSON:
/// `orchestration::parse_agent_spawn` rejects all four keys in both spellings,
/// and `catalog::tests` asserts the `agent_spawn` descriptor never advertises
/// them, so the model is not shown a parameter that is parsed and then refused.
///
/// # Turn-local when it comes from host code
///
/// These values reach no receipt payload and no `SubagentRunRecord`. For a NAMED
/// agent that is fine and deliberate: `build_rehydrated_agent_template` re-runs
/// `configure_named_agent_template` against the current definition, so the
/// overrides are re-derived — and re-attested — on every resumed turn. A
/// workflow step is fine for the opposite reason: its record is `name: None`
/// view-only history that is never rehydrated at all.
///
/// What is NOT supported is a host-imposed restriction on an ordinary child or a
/// conversation fork that must outlive the turn. Nothing would carry it, and
/// rehydration would silently restore the unrestricted template — capability
/// widening by omission. If a future milestone needs that, it has to decide
/// where the value is persisted and attested BEFORE relying on it.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub(crate) struct AgentRunOverrides {
    pub(crate) effort: Option<ReasoningEffort>,
    pub(crate) tools: Option<Vec<String>>,
    pub(crate) disallowed_tools: Vec<String>,
}

/// An allowlist entry that names every tool the child may keep.
const AGENT_TOOL_WILDCARD: &str = "*";

impl AgentRunOverrides {
    /// Whether these overrides leave `name` callable. Used for context
    /// filtering, where there is no `enabled_tools` list to intersect against.
    fn permits_tool(&self, name: &str) -> bool {
        if let Some(allowed) = self.tools.as_deref() {
            if !allowed
                .iter()
                .any(|entry| entry == AGENT_TOOL_WILDCARD || entry == name)
            {
                return false;
            }
        }
        !self.disallowed_tools.iter().any(|entry| entry == name)
    }

    fn from_definition(definition: &AgentDefinition) -> Self {
        Self {
            effort: definition.effort,
            tools: definition.tools.clone(),
            disallowed_tools: definition.disallowed_tools.clone(),
        }
    }

    /// Applies the overrides to an already-configured child template.
    ///
    /// Must run LAST, after every host adjustment to `enabled_tools` — in
    /// particular after `configure_named_agent_template`'s memory-tool surgery —
    /// or an allowlist would be computed against a set the host then widened.
    ///
    /// # The allowlist SELECTS from the child catalogue; it does not intersect
    ///
    /// The allowlist resolves against the child's own descriptor vector, so a
    /// role can grant a catalogue tool its caller does not hold. A role's tool
    /// selection must define its own usable capabilities; otherwise the editor
    /// could save and advertise a selected tool that silently disappears here.
    ///
    /// Two floors survive, and they are the reason this is a filtered selection
    /// rather than a plain lookup:
    ///
    /// - `subagent_tool_is_disabled` is re-applied to the DESCRIPTOR side, so a
    ///   name on that list can never be selected no matter what the document
    ///   says. It is deliberately NOT re-applied to `template.enabled_tools`:
    ///   anything the host already put there after the inheritance filter is a
    ///   deliberate grant, and re-filtering would revoke it.
    /// - `host_derived_child_tool` names are exempt from the allowlist in both
    ///   directions: an allowlist neither grants nor revokes them, because the
    ///   host derives them from switches and producers rather than from lists.
    ///   That is also why the zero-tool refusal counts what the allowlist
    ///   GRANTED rather than what the vector ended up holding — a leftover
    ///   `skill` must not disguise a definition that resolved to nothing.
    ///
    /// Dynamic MCP discovery re-resolves named-role policy from the trusted
    /// definition binding before admitting any newly discovered tool.
    fn apply(&self, template: &mut RunModelRequest, start: AgentRunStart) -> Result<(), String> {
        if let Some(effort) = self.effort {
            template.reasoning_effort = effort;
        }

        if let Some(allowed) = self.tools.as_deref() {
            let has_wildcard = allowed.iter().any(|name| name == AGENT_TOOL_WILDCARD);
            if !has_wildcard {
                let inherited = std::mem::take(&mut template.enabled_tools);
                let base_was_empty = inherited.is_empty();
                let allowed_set = allowed.iter().map(String::as_str).collect::<HashSet<_>>();

                // Two buckets, because they answer to different authorities.
                //
                // `kept` walks the INHERITED vector first so a narrowing role —
                // the overwhelmingly common case — leaves the order it found
                // alone. Host-derived names ride along untouched: the allowlist
                // has no opinion about them in either direction.
                let mut kept = Vec::new();
                let mut granted = 0usize;
                let mut already = HashSet::new();
                for name in &inherited {
                    if host_derived_child_tool(name) {
                        if already.insert(name.clone()) {
                            kept.push(name.clone());
                        }
                    } else if allowed_set.contains(name.as_str()) && already.insert(name.clone()) {
                        granted += 1;
                        kept.push(name.clone());
                    }
                }
                // Then the additions: catalogue entries this role asked for that
                // its caller had switched off. Appended in catalogue order, so
                // the result is deterministic.
                //
                // `already` is threaded through both loops rather than snapshotted
                // between them: two MCP servers may advertise the same tool name,
                // and a duplicate here would reach the model as two identical
                // function declarations in one request.
                for tool in &template.tools {
                    if subagent_tool_is_disabled(&tool.name)
                        || host_derived_child_tool(&tool.name)
                        || !allowed_set.contains(tool.name.as_str())
                        || !already.insert(tool.name.clone())
                    {
                        continue;
                    }
                    granted += 1;
                    kept.push(tool.name.clone());
                }
                template.enabled_tools = kept;

                // The five-part guard. An empty resolved set is refused only
                // when every part holds: the resolver ran (an allowlist exists),
                // it was not a wildcard, the base pool was non-empty, this is a
                // fresh spawn, and a non-empty diagnostic can say WHY. An
                // explicit `tools: []` produces no diagnostic and is therefore
                // ALLOWED — that is a deliberate "no tools" configuration, not a
                // typo, and refusing it would make it unexpressible.
                //
                // The count is of names the ALLOWLIST granted, not of the
                // resulting vector. Those differ now that host-derived names
                // survive an allowlist that never mentions them: reading the
                // vector would let a leftover `skill` disguise a definition that
                // resolved to nothing.
                if granted == 0 && !base_was_empty && start == AgentRunStart::Fresh {
                    let known = template
                        .tools
                        .iter()
                        .map(|tool| tool.name.as_str())
                        .collect::<HashSet<_>>();
                    let mut unrecognized = Vec::new();
                    let mut unavailable = Vec::new();
                    for name in allowed {
                        if known.contains(name.as_str()) {
                            // Present in the catalogue but withheld from every
                            // child. "The conversation did not enable it" is no
                            // longer a reason to land here — that case now
                            // resolves.
                            unavailable.push(name.as_str());
                        } else {
                            unrecognized.push(name.as_str());
                        }
                    }
                    if !unrecognized.is_empty() || !unavailable.is_empty() {
                        let mut reasons = Vec::new();
                        if !unrecognized.is_empty() {
                            reasons.push(format!("Unrecognized: {}", unrecognized.join(", ")));
                        }
                        if !unavailable.is_empty() {
                            reasons.push(format!(
                                "Unavailable to subagents: {}",
                                unavailable.join(", ")
                            ));
                        }
                        return Err(format!(
                            "The named agent's tools allowlist resolved to no usable tools ({}); correct the definition or use \"*\".",
                            reasons.join("; ")
                        ));
                    }
                }
            }
        }

        if !self.disallowed_tools.is_empty() {
            let denied = self
                .disallowed_tools
                .iter()
                .map(String::as_str)
                .collect::<HashSet<_>>();
            template
                .enabled_tools
                .retain(|name| !denied.contains(name.as_str()));
        }
        // Task runtime tools follow their producers, not an allowlist. Re-derive
        // after selection/removal because a producer may have changed.
        crate::agents::apply_task_runtime_tools(&mut template.enabled_tools);
        Ok(())
    }
}

/// Resolves a role name and applies it to a FRESH child template.
///
/// The one entry point both callers use — `agent_spawn`'s `agent_type` and a
/// workflow step's `agentType`. It exists so those two cannot drift: the model
/// selects a role by name in both places, and "select a role" has to mean the
/// same four steps (resolve, verify the identity ledger, bind an exact
/// provider/model, configure the template) wherever it is written.
///
/// `resolve_agent_definition` already reports a role whose bound model is gone
/// with wording byte-identical to an unknown name, so there is deliberately no
/// second model-availability check here.
pub(crate) fn apply_named_role_to_fresh_template(
    parent: &RunModelRequest,
    state: &AppState,
    template: &mut RunModelRequest,
    agent_type: &str,
) -> Result<Option<String>, String> {
    let document = current_agent_document(parent, state)?;
    let definitions = request_agent_definitions(&document, parent);
    let definition =
        resolve_agent_definition(&document, definitions, &parent.workspace_id, agent_type)?.clone();
    let (binding, provider, model) =
        initial_agent_definition_binding(parent, &document, &definition)?;
    let template_id = definition.template_id.clone();
    configure_named_agent_template(
        parent,
        template,
        &definition,
        binding,
        provider,
        model,
        &document.assets.web_search,
        AgentRunStart::Fresh,
    )?;
    // Returned rather than applied here: this configures the child's REQUEST,
    // and a template is its opening HISTORY, which the caller owns and builds
    // separately. Handing back the id keeps both readings of the role in one
    // resolution instead of making the caller look the definition up again.
    Ok(template_id)
}

#[allow(clippy::too_many_arguments)]
fn configure_named_agent_template(
    parent: &RunModelRequest,
    template: &mut RunModelRequest,
    definition: &AgentDefinition,
    binding: AgentDefinitionBinding,
    provider: ApiProvider,
    model: ModelProfile,
    web_search_assets: &crate::model::WebSearchAssets,
    start: AgentRunStart,
) -> Result<(), String> {
    template.provider = provider;
    template.model = model;
    // A role carries no prompt of its own: a named child renders the PARENT's
    // host-assembled prompt through the same addendum an ordinary child gets, so
    // the two kinds of child cannot drift apart in what they were told about the
    // task. The addendum's wording follows the parent's prompt profile.
    template.assembled_system_prompt = subagent_prompt::render(
        PromptVersion::current(),
        &parent.assembled_system_prompt,
        &parent.prompt_profile,
    );
    template.agent_definition_binding = Some(binding.clone());
    template.inherits_parent_model_memory = false;
    template.fork_model_binding = None;
    template.subagent_execution_mode_receipt = None;
    template.memory_context_id = None;
    template.project_memory_context_id = None;
    template.ephemeral_contexts.clear();
    template
        .enabled_tools
        .retain(|name| !is_memory_tool_name(name));
    template
        .tools
        .retain(|tool| tool.category != ToolCategory::Memory);
    // Memory is two directories, not a per-agent namespace. A named agent whose
    // definition asks for memory reads and writes the very same tiers as its
    // parent — the binding only chooses WHICH tier, and the parent's own
    // switches are the ceiling, so a role can never open a tier the
    // conversation left off. `memory: none` withholds both.
    let requested = match binding.memory {
        AgentDefinitionMemory::None => crate::mework_memory::MemoryTierAccess {
            global: false,
            project: false,
        },
        AgentDefinitionMemory::User => crate::mework_memory::MemoryTierAccess {
            global: true,
            project: false,
        },
        AgentDefinitionMemory::Project | AgentDefinitionMemory::Local => {
            crate::mework_memory::MemoryTierAccess {
                global: false,
                project: true,
            }
        }
    };
    template.global_memory_enabled = parent.global_memory_enabled && requested.global;
    template.project_memory_enabled = parent.project_memory_enabled && requested.project;
    for tier in [
        crate::mework_memory::MemoryTier::Global,
        crate::mework_memory::MemoryTier::Project,
    ] {
        if !template.memory_tier_access().allows(tier) {
            continue;
        }
        let names = crate::mework_memory::tool_names_for_tier(tier);
        let descriptors = parent
            .tools
            .iter()
            .filter(|tool| {
                tool.category == ToolCategory::Memory && names.contains(&tool.name.as_str())
            })
            .cloned()
            .collect::<Vec<_>>();
        if descriptors.len() != names.len() {
            return Err(format!(
                "Trusted tool catalog lacks the complete {} tools",
                tier.label()
            ));
        }
        template
            .enabled_tools
            .extend(descriptors.iter().map(|tool| tool.name.clone()));
        template.tools.extend(descriptors);
    }
    // Apply only a role's backend override after provider/model binding. `Native`
    // resolves against the executing provider/model and must fail closed when that
    // family lacks provider-executed search. Preserve all other effective parent
    // settings, which were resolved at the parent request boundary.
    if definition.search_provider.is_some() || definition.fetch_provider.is_some() {
        // Whether this child's own provider can fetch as a server tool of its
        // own. `template.web_search.fetch` was resolved at the parent boundary
        // against the PARENT's model, and a role may be bound to another one, so
        // the question is re-asked against the family the child actually runs on.
        // `template.provider` is this child's own, assigned at the top of this
        // function. The question has to be asked against the family the CHILD
        // runs on: `template.web_search.fetch` was resolved at the parent
        // boundary against the parent's model, and a role may be bound to
        // another one whose provider answers differently.
        let native_fetch = crate::web_search::family_supports_native_fetch(
            crate::aisdk::protocol::Family::for_format(template.provider.family),
        );
        // One throwaway view resolves both legs. A leg the role did not name is
        // filled with `Disabled` and its result discarded below, so the value
        // put here can never reach the child — the parent's own resolved answer
        // is already on `template` and simply stays there.
        let resolved = crate::model::WebSearchSettings::effective(
            &crate::model::ConversationWebSearchSettings {
                max_searches_per_call: parent.web_search.max_searches_per_call,
                provider: definition
                    .search_provider
                    .clone()
                    .unwrap_or(crate::model::SearchProviderSelection::Disabled),
                fetch_provider: definition
                    .fetch_provider
                    .clone()
                    .unwrap_or(crate::model::FetchProviderSelection::Disabled),
                // The Messages tool versions belong to the conversation, not to
                // the role: a role picks which backend searches or fetches,
                // never which wire spelling that backend's own provider uses.
                native_search_tool: parent.web_search.native_search_tool,
                native_fetch_tool: parent.web_search.native_fetch_tool,
                // Shaping is applied below and unconditionally, so whatever this
                // throwaway view computes for it is discarded with the rest.
                ..Default::default()
            },
            web_search_assets,
            native_fetch,
        );
        if definition.search_provider.is_some() {
            template.web_search.backend = resolved.backend;
            // A role that names no search backend withholds `web_search` from
            // its own child, exactly as the same choice does on a conversation.
            // It travels with the backend because it IS the backend answer.
            template.web_search.search_withheld = resolved.search_withheld;
        }
        // The fetch leg has no separate "withheld" flag: `None` already means
        // the model is handed no `web_fetch` at all.
        if definition.fetch_provider.is_some() {
            template.web_search.fetch = resolved.fetch;
        }
    }
    // Domain filtering, applied whole or not at all: a role that names a mode
    // filters by its own two lists, and one that names none keeps the caller's
    // mode and lists exactly as the parent boundary resolved them.
    if let Some(mode) = definition.domain_filter {
        template.web_search.execution.domain_filter = mode;
        template.web_search.execution.include_domains = definition.include_domains.clone();
        template.web_search.execution.exclude_domains = definition.exclude_domains.clone();
    }
    // Result shaping, unlike the backend, is not an override with a "follow the
    // conversation" setting: 0 already means "no cap", leaving no value over to
    // spell inheritance with, so every role carries its own answer and applies
    // it whether or not it also redirected the backend.
    template.web_search.execution.max_results = definition
        .max_results
        .min(crate::model::MAX_SEARCH_MAX_RESULTS);
    template.web_search.execution.compression_cutoff = definition
        .compression_cutoff
        .min(crate::model::MAX_SEARCH_CUTOFF_LIMIT);
    // LAST, after the memory-tool surgery above: an allowlist computed before it
    // would be applied to a set this function then widens.
    AgentRunOverrides::from_definition(definition).apply(template, start)
}

fn refresh_named_agent_memory(
    request: &mut RunModelRequest,
    state: &AppState,
) -> Result<(), String> {
    if request.agent_definition_binding.is_none() {
        return Ok(());
    };
    let binding = request.agent_definition_binding.clone();
    validate_current_agent_definition(request, state)?;
    if let Some(memory_context_id) = request.memory_context_id.take() {
        request.ephemeral_contexts.retain(
            |context| !matches!(context, ContextItem::User { id, .. } if id == &memory_context_id),
        );
    }
    if !request.memory_enabled() {
        request
            .enabled_tools
            .retain(|name| !is_memory_tool_name(name));
        return Ok(());
    }
    let already = request
        .enabled_tools
        .iter()
        .cloned()
        .collect::<HashSet<_>>();
    // Only the tiers this child was granted. The descriptor set was already
    // narrowed to those tiers by `apply_agent_definition`, but re-deriving
    // membership from the switches keeps a widened descriptor list from
    // silently widening the enabled list too.
    let granted = request.memory_tier_access();
    request.enabled_tools.extend(
        request
            .tools
            .iter()
            .filter(|tool| tool.category == ToolCategory::Memory)
            .filter(|tool| {
                crate::mework_memory::tool_tier(&tool.name).is_some_and(|tier| granted.allows(tier))
            })
            .map(|tool| tool.name.clone())
            .filter(|name| !already.contains(name)),
    );
    // The named agent reads the same tiers as the main session, so the block is
    // rebuilt from disk rather than from a per-agent namespace — and only for
    // the tiers this child actually holds.
    if let Some(prompt) = run_memory_roots(request).render_context(&request.prompt_profile) {
        let context_id = new_context_id("agent-memory");
        request.ephemeral_contexts.push(ContextItem::User {
            id: context_id.clone(),
            content: prompt,
            images: Vec::new(),
            files: Vec::new(),
            created_at: Utc::now().to_rfc3339(),
        });
    }
    // The binding clone prevents a future refactor from accidentally using a
    // model-provided identity while refreshing this request.
    if request.agent_definition_binding != binding {
        return Err(
            "The named-agent definition binding changed while memory was refreshing.".into(),
        );
    }
    Ok(())
}

/// Prototype request for one child turn: parent provider, workspace, security
/// level and tool-level hooks, with a small explicit capability deny-list and
/// one injected child-only update tool. Contexts are filled by the agent worker.
pub(crate) fn agent_child_template(parent: &RunModelRequest) -> RunModelRequest {
    // `workflow` is dropped as a DESCRIPTOR, not merely withheld from
    // `enabled_tools`. A child must not be able to see that the tool exists:
    // with the descriptor present, a stray call is refused as "not enabled",
    // which reads as a permission the user could grant. Removing the descriptor
    // makes the same call fail as an unknown tool — the truthful answer, since
    // no child can ever hold it.
    let mut child_tools = parent
        .tools
        .iter()
        .filter(|tool| tool.name != "workflow")
        .cloned()
        .collect::<Vec<_>>();
    // `parent` may already be a child request whose descriptor vector contains
    // `subagent_update`; preserve idempotence.
    if !child_tools
        .iter()
        .any(|tool| tool.name == SUBAGENT_UPDATE_TOOL)
    {
        child_tools.push(subagent_update_descriptor(&parent.prompt_profile));
    }
    let mut child_enabled_tools = parent
        .enabled_tools
        .iter()
        .filter(|name| !subagent_tool_is_disabled(name))
        .cloned()
        .collect::<Vec<_>>();
    // This function also creates accounting templates for background shell and
    // search work, where `parent` may already contain `subagent_update`. Keep the
    // insertion idempotent after inherited-tool filtering.
    if !child_enabled_tools
        .iter()
        .any(|name| name == SUBAGENT_UPDATE_TOOL)
    {
        child_enabled_tools.push(SUBAGENT_UPDATE_TOOL.into());
    }
    // `task_wait` / `task_list` are on that deny-list, so the filter above just
    // stripped them — which is right, because a child must not inherit its
    // parent's view of the task board. It must still be able to collect its OWN
    // tasks: `web_search` always dispatches through a background leg, so a child
    // holding it would otherwise receive a dispatch receipt it could never
    // redeem. Same derivation as the top-level request (`trusted_run_request`),
    // against the child's own producer set, resolving against the child's own
    // pool.
    //
    // LAST, after the `subagent_update` push, so that composing this function
    // directly with `AgentRunOverrides::apply` for a role that overrides nothing
    // yields a byte-identical vector — that composition is what
    // `a_role_allowlist_selects_from_the_catalogue_but_never_past_the_child_floor`
    // asserts. It is NOT byte-identical on the named-agent path: in between,
    // `configure_named_agent_template` strips and re-adds the memory tools, and
    // `apply`'s own closing derivation then moves the task pair behind them.
    // That difference is fine — order carries no meaning downstream
    // (`aisdk::tools::enabled_tools` reads the vector as a set) — but do not
    // promote the equality to an invariant it does not have.
    crate::agents::apply_task_runtime_tools(&mut child_enabled_tools);
    // The web pair follows the conversation's switch for the same reason the
    // memory tools follow its tiers: a child works inside the same boundary, so
    // it reaches the network exactly when the conversation may.
    crate::web_search::apply_web_tools(
        &mut child_enabled_tools,
        parent.web_search_enabled,
        &parent.web_search,
    );
    RunModelRequest {
        provider: parent.provider.clone(),
        web_search: parent.web_search.clone(),
        native_search_call: false,
        native_fetch_call: None,
        web_search_enabled: parent.web_search_enabled,
        // Children share the conversation-level run environment; synchronous shell
        // execution location does not vary by derivation depth.
        run_environment: parent.run_environment.clone(),
        // Children address the same numbered workspaces as their parent. A child
        // that could reach a directory or a machine its parent could not would
        // make derivation depth a way to widen the boundary.
        workspaces: parent.workspaces.clone(),
        prompt_profile: parent.prompt_profile.clone(),
        // An ordinary subagent works inside the same conversation's boundary,
        // so it follows that conversation's two memory switches.
        global_memory_enabled: parent.global_memory_enabled,
        project_memory_enabled: parent.project_memory_enabled,
        // Inherited for the same reason `skill` stays out of
        // `SUBAGENT_DISABLED_TOOL_NAMES`: the bodies were resolved from the
        // parent conversation's own selection, so a child loading one reaches
        // nothing the parent had not already chosen.
        skills: parent.skills.clone(),
        // Deliberately empty: these are messages for the parent's transcript,
        // and a child starts from an empty history. A child therefore reads the
        // skill listing its inherited system prompt carries — the ones the
        // conversation opened with — while a skill selected later is still
        // loadable by name, just not advertised to it. The parent's task text
        // is where a child is told to use one.
        added_skills: Vec::new(),
        // Inherited, because the servers are: a child dials the same MCP
        // transports through the parent's bindings, so it has to hold their
        // schemas back the same way. What it does NOT inherit is which of them
        // the parent already fetched — the child starts from an empty history
        // and never read those results, so `attach_mcp_tools` re-withholds
        // every one of them and the child searches for its own.
        mcp_tool_discovery: parent.mcp_tool_discovery,
        // The guards are inherited; the read record is not shared. A child gets
        // a scope of its own, seeded from the parent's on first use — the
        // parent's reads are what the child may edit, but what the child then
        // reads and writes stays the child's: the parent never saw it.
        file_guard: crate::model::FileGuard {
            scope: crate::file_read_state::child_scope_id(&parent.conversation_id),
            parent_scope: Some(parent.file_guard_scope().to_owned()),
        },
        deferred_tools: Vec::new(),
        // Deliberately NOT inherited and deliberately NOT set here. The schema
        // belongs to one `agent_spawn` call, not to the parent run, and the
        // matching tool injection has to happen AFTER `AgentRunOverrides::apply`
        // intersects `enabled_tools` — see `install_structured_output`.
        output_schema: None,
        model: parent.model.clone(),
        reasoning_effort: parent.reasoning_effort,
        conversation_id: parent.conversation_id.clone(),
        workspace_id: parent.workspace_id.clone(),
        memory_context_id: None,
        project_memory_context_id: None,
        agent_definition_binding: None,
        inherits_parent_model_memory: false,
        fork_model_binding: None,
        subagent_execution_mode_receipt: None,
        subagent_reserved_names: parent.subagent_reserved_names.clone(),
        memory_run_id: parent.memory_run_id.clone(),
        context_load_actor_name: None,
        workspace_path: parent.workspace_path.clone(),
        additional_directories: parent.additional_directories.clone(),
        assembled_system_prompt: subagent_prompt::render(
            PromptVersion::current(),
            &parent.assembled_system_prompt,
            &parent.prompt_profile,
        ),
        enabled_tools: child_enabled_tools,
        contexts: Vec::new(),
        ephemeral_contexts: Vec::new(),
        host_notices: Vec::new(),
        tools: child_tools,
        // Tool-level hooks keep guarding subagent calls. InstructionsLoaded is
        // also inherited because named/ordinary children receive their own
        // actual project/user instruction context; it remains asynchronous
        // observation-only. Session, prompt, and stop hooks belong to the
        // visible conversation turn.
        active_hooks: parent
            .active_hooks
            .iter()
            .filter(|hook| {
                matches!(
                    hook.event,
                    HookEvent::InstructionsLoaded
                        | HookEvent::PreToolUse
                        | HookEvent::PermissionRequest
                        | HookEvent::PostToolUse
                )
            })
            .cloned()
            .collect(),
        // Snapshot the level in force now, and share the parent's cell so a
        // switch during the parent's turn reaches descendants too.
        security_level: parent.effective_security_level(),
        live_security_level: parent.live_security_level.clone(),
        plan_tools: false,
        live_plan_mode: None,
        app_data_path: parent.app_data_path.clone(),
        mcp_servers: parent.mcp_servers.clone(),
        mcp_bindings: parent.mcp_bindings.clone(),
        subagent_depth: parent.subagent_depth + 1,
        handoff: Default::default(),
        request_id: String::new(),
        subagent_name: None,
        subagent_call_id: None,
        history_owner: None,
        steer_mailbox: AgentMailboxHandle::default(),
        // A template belongs to no run. Workers attach their own task signal to
        // each round clone; inheriting the parent's signal would stop grandchildren
        // for parent cancellation.
        task_cancel: CancelSignal::default(),
        // Child rounds do not inherit `run_cancel`; it is minted only for a
        // registered top-level `run_model` invocation.
        run_cancel: CancelSignal::default(),
    }
}

/// The fork-binding receipt version stamped on newly issued fork bindings.
///
/// The value is reflected in newly issued fork records. Execution-mode payload
/// volatility is classified on `model::canonical_subagent_execution_mode_payload`; read
/// that before changing this constant.
pub(crate) const CURRENT_FORK_BINDING_RECEIPT_VERSION: u8 = 1;

/// Bind an addressable child-agent name to this execution mode.
/// A name must map to one immutable mode within a conversation; otherwise messages
/// could silently change recipient. The in-process registry enforces this invariant.
pub(crate) fn reserve_subagent_execution_mode(
    request: &RunModelRequest,
    state: &AppState,
    name: &str,
    kind: SubagentRunKind,
) -> Result<(), String> {
    let payload = canonical_subagent_execution_mode_payload(
        &request.conversation_id,
        name,
        kind,
        request.inherits_parent_model_memory,
        request.fork_model_binding.as_ref(),
        request.agent_definition_binding.as_ref(),
    )?;
    state.reserve_subagent_execution_mode(&request.conversation_id, name, &payload)
}

/// When restoring a child, verify its name remains bound to the same execution
/// mode. Re-reserving the recorded payload is idempotent for equal digests and
/// rejects a changed mode.
fn verify_subagent_execution_mode(
    parent: &RunModelRequest,
    state: &AppState,
    name: &str,
    record: &SubagentRunRecord,
) -> Result<(), String> {
    if record.name.as_deref() != Some(name) || record.kind != SubagentRunKind::General {
        return Err(format!(
            "Persisted record for subagent {name} lacks an exact, ordinary, addressable identity; restoration was refused."
        ));
    }
    let payload = canonical_subagent_execution_mode_payload(
        &parent.conversation_id,
        name,
        record.kind,
        record.inherits_model_memory,
        record.fork_model_binding.as_ref(),
        record.agent_definition.as_ref(),
    )?;
    state.reserve_subagent_execution_mode(&parent.conversation_id, name, &payload)
}

/// Byte bound on a fork's persisted `system_prompt_snapshot`.
///
/// Creation and restore MUST read this same constant. Two independent literals
/// can drift, and drifting in the direction "creation permits more than restore
/// accepts" produces forks that are permanently unrestorable rather than merely
/// rejected up front.
///
/// `agents::validate_child_memory_mode` and
/// `storage::validate_subagent_fork_binding` still spell the same bound as
/// inline `1024 * 1024` literals; folding those into this constant is a
/// follow-up in files this change does not own.
pub(crate) const MAX_FORK_SYSTEM_PROMPT_SNAPSHOT_BYTES: usize = 1024 * 1024;

fn validate_fork_system_prompt_snapshot(snapshot: &str) -> Result<(), String> {
    if snapshot.is_empty() || snapshot.len() > MAX_FORK_SYSTEM_PROMPT_SNAPSHOT_BYTES {
        return Err(format!(
            "The conversation fork's persisted system-prompt snapshot is empty or exceeds {} MiB",
            MAX_FORK_SYSTEM_PROMPT_SNAPSHOT_BYTES / (1024 * 1024)
        ));
    }
    Ok(())
}

/// Establish exact provider/model and system-prompt snapshot binding for a
/// conversation fork. Field-by-field restore validation detects replaced or
/// revised records; memory is read fresh from disk and has no signed snapshot.
fn inherit_parent_model_memory_for_fork(
    parent: &RunModelRequest,
    child: &mut RunModelRequest,
    _state: &AppState,
) -> Result<(), String> {
    child.inherits_parent_model_memory = true;
    child.agent_definition_binding = None;
    child.fork_model_binding = None;
    child.memory_context_id = None;
    // A fork inherits parent memory switches, not a snapshot; both Markdown tiers
    // are read fresh.
    if host_memory_prompt_content(parent)?.is_some() {
        let expected_id = parent
            .memory_context_id
            .as_deref()
            .expect("validated host memory context has an id");
        child.ephemeral_contexts = parent
            .ephemeral_contexts
            .iter()
            .filter(|context| context.id() == expected_id)
            .cloned()
            .collect();
        child.memory_context_id = parent.memory_context_id.clone();
    }
    let memory_tool_names = enabled_memory_tool_names(parent);
    validate_fork_memory_tool_names(&memory_tool_names)?;
    child
        .enabled_tools
        .retain(|name| !is_memory_tool_name(name));
    child
        .enabled_tools
        .extend(memory_tool_names.iter().cloned());
    let system_prompt_snapshot = child.assembled_system_prompt.clone();
    // Apply the restore bound at creation. A child prompt may exceed the snapshot
    // limit even when its parent request does not; otherwise it creates a fork that
    // can run but can never be restored.
    validate_fork_system_prompt_snapshot(&system_prompt_snapshot)?;
    child.fork_model_binding = Some(ForkModelBinding {
        provider_id: child.provider.id.clone(),
        model_id: child.model.id.clone(),
        memory_language: if request_uses_english_defaults(parent) {
            ResolvedLanguage::EnUs
        } else {
            ResolvedLanguage::ZhCn
        },
        memory_tool_names,
        system_prompt_receipt: String::new(),
        system_prompt_snapshot,
        memory_snapshot_receipt: None,
        binding_receipt: String::new(),
        receipt_version: CURRENT_FORK_BINDING_RECEIPT_VERSION,
    });
    Ok(())
}

/// The memory tool names a restored fork may actually hold.
///
/// The persisted set is a snapshot of what the fork held when it was created;
/// the two tier switches are live conversation policy. Restoring a tier the
/// conversation has since turned off would re-expose it, so the snapshot is
/// intersected with what is enabled now. Restore and the per-turn fence share
/// this one function deliberately: comparing the fence against the raw snapshot
/// instead would make a fork whose tier was turned off restore cleanly and then
/// fail its own validation on the very next round.
fn fork_memory_tool_names_for(
    request: &RunModelRequest,
    binding: &ForkModelBinding,
) -> Vec<String> {
    let granted = request.memory_tier_access();
    binding
        .memory_tool_names
        .iter()
        .filter(|name| {
            crate::mework_memory::tool_tier(name).is_some_and(|tier| granted.allows(tier))
        })
        .cloned()
        .collect()
}

fn restore_conversation_fork_binding(
    child: &mut RunModelRequest,
    binding: &ForkModelBinding,
) -> Result<(), String> {
    validate_fork_memory_tool_names(&binding.memory_tool_names)?;
    validate_fork_system_prompt_snapshot(&binding.system_prompt_snapshot)?;
    // Receipt signatures are absent. Field-by-field comparison is the substantive
    // check that this is still the original fork.
    if binding.provider_id != child.provider.id || binding.model_id != child.model.id {
        return Err(
            "The conversation fork's persisted provider/model does not match the current restoration request; restoration was refused.".into(),
        );
    }

    child.inherits_parent_model_memory = true;
    child.fork_model_binding = Some(binding.clone());
    child.subagent_execution_mode_receipt = None;
    child.agent_definition_binding = None;
    child.assembled_system_prompt = binding.system_prompt_snapshot.clone();
    child.ephemeral_contexts.clear();
    child.memory_context_id = None;
    child.project_memory_context_id = None;
    child
        .enabled_tools
        .retain(|name| !is_memory_tool_name(name));
    // Only the tiers this conversation still has on — see
    // `fork_memory_tool_names_for`.
    let memory_tool_names = fork_memory_tool_names_for(child, binding);
    if !memory_tool_names.is_empty() {
        let memory_descriptors = child
            .tools
            .iter()
            .filter(|tool| tool.category == ToolCategory::Memory)
            .map(|tool| tool.name.clone())
            .collect::<HashSet<_>>();
        if memory_tool_names
            .iter()
            .any(|name| !memory_descriptors.contains(name))
        {
            return Err("Trusted tool catalog lacks the memory tools enabled when the conversation fork was created.".into());
        }
        child.enabled_tools.extend(memory_tool_names);
    }

    // A fork no longer replays a signed memory snapshot. Memory lives on disk
    // and is read fresh, so the fork simply inherits the parent conversation's
    // switches and reads whatever the enabled tiers hold now. There is nothing
    // to verify against a receipt: the previous design signed a database
    // snapshot precisely because the store could change underneath a restored
    // fork, and a plain file has no such hidden state to smuggle in.
    if child.memory_enabled() {
        if let Some(prompt) = run_memory_roots(child).render_context(&child.prompt_profile) {
            let context_id = new_context_id("fork-memory");
            child.ephemeral_contexts.push(ContextItem::User {
                id: context_id.clone(),
                content: prompt,
                images: Vec::new(),
                files: Vec::new(),
                created_at: Utc::now().to_rfc3339(),
            });
        }
    }
    Ok(())
}

fn validate_current_fork_binding(request: &RunModelRequest) -> Result<(), String> {
    let Some(binding) = request.fork_model_binding.as_ref() else {
        if request.inherits_parent_model_memory {
            return Err(
                "A conversation fork is missing its persisted exact model/snapshot binding.".into(),
            );
        }
        return Ok(());
    };
    if !request.inherits_parent_model_memory || request.agent_definition_binding.is_some() {
        return Err(
            "The memory modes of the conversation fork, ordinary agent, and named agent conflict."
                .into(),
        );
    }
    if request.provider.id != binding.provider_id || request.model.id != binding.model_id {
        return Err("The conversation fork's current request has drifted from the exact provider/model at spawn time.".into());
    }
    validate_fork_memory_tool_names(&binding.memory_tool_names)?;
    // Receipt signatures are absent; field comparison still detects a modified
    // snapshot without a separate signature proof.
    if request.assembled_system_prompt != binding.system_prompt_snapshot {
        return Err("The conversation fork's system-prompt snapshot changed.".into());
    }
    if enabled_memory_tool_names(request) != fork_memory_tool_names_for(request, binding) {
        return Err(
            "The conversation fork's exact memory-tool set differs from its creation snapshot."
                .into(),
        );
    }
    // A fork's memory block is read fresh from disk, so there is no signed
    // snapshot to compare against. What still has to hold is that the fork
    // only carries a memory block when its conversation actually enables
    // memory — a fork must not become a way to widen the switch.
    let prompt = host_memory_prompt_content(request)?;
    if prompt.is_some() && !request.memory_enabled() {
        return Err(
            "A conversation fork with long-term memory disabled must not carry a memory prompt."
                .into(),
        );
    }
    Ok(())
}

/// A sanitized copy of the conversation for `agent_spawn` with
/// `context: "conversation"` — the Codex `fork_turns` analogue. Host-loop tool
/// calls, reasoning and system contexts stay behind, and nested run records
/// are stripped so forked children never re-persist them.
///
/// `overrides` additionally drops transcripts of tools the child will not be
/// able to call, so a restricted child does not inherit worked examples of
/// capabilities it no longer has. Today's only caller passes the default —
/// `parse_agent_spawn` refuses `agent_type` together with
/// `context: "conversation"`, so a model-driven fork never carries overrides —
/// which makes this reachable only for a host caller that constructs both.
///
/// Note what this filter does NOT consult: the parent's current
/// `enabled_tools`. A conversation that ran `bash` and later switched it off
/// still hands the fork that transcript, and always has. The two gates here are
/// the permanent floor (`subagent_tool_is_disabled`, plus the child-only tools)
/// and the role's own overrides — "a capability this child can never hold" and
/// "a capability this role refused", not "a switch the user happens to have
/// flipped since". History is history; the child simply cannot call it, because
/// `enabled_tools` is a separate gate. `web_search` and `web_fetch` are
/// ordinary child capabilities subject to the same transcript and capability
/// gates as every other tool.
fn forked_conversation_contexts(
    parent: &RunModelRequest,
    overrides: &AgentRunOverrides,
) -> Vec<ContextItem> {
    sanitize_child_history(&parent.contexts, overrides)
}

/// The shared body of that filter, over any history a child is about to be
/// seeded with — a forked conversation, or a role's saved template. A template
/// is captured from a real conversation, so it can hold every one of the things
/// this drops.
fn sanitize_child_history(
    contexts: &[ContextItem],
    overrides: &AgentRunOverrides,
) -> Vec<ContextItem> {
    contexts
        .iter()
        .filter_map(|context| match context {
            ContextItem::Assistant {
                interrupted: true, ..
            } => None,
            // A folded agent-result notification is child-authored text. Forks
            // strip every subagent transcript by design; letting the same output
            // back in through its delivery would re-open the boundary sideways.
            // Both carriers the delivery has ever used are named here: the `box`
            // tool card, and the user context older conversations recorded.
            ContextItem::User { id, .. } | ContextItem::Tool { id, .. }
                if id.starts_with(AGENT_RESULT_CONTEXT_ID_PREFIX) =>
            {
                None
            }
            ContextItem::User { .. } => Some(context.clone()),
            ContextItem::Assistant { .. } => {
                let mut context = context.clone();
                if let ContextItem::Assistant { round, .. } = &mut context {
                    *round = None;
                }
                Some(context)
            }
            ContextItem::Tool { tool_name, .. }
                if agents::agent_tool_kind(tool_name).is_none()
                    && !subagent_tool_is_disabled(tool_name)
                    && tool_name != SUBAGENT_UPDATE_TOOL
                    // Both child-only tools are filtered for the same reason:
                    // a fork replaying its parent's transcript must not inherit
                    // calls to tools that only exist inside a child run, and a
                    // parent's structured result is not this fork's to claim.
                    && tool_name != STRUCTURED_OUTPUT_TOOL
                    && overrides.permits_tool(tool_name) =>
            {
                let mut context = context.clone();
                if let ContextItem::Tool { subagent, .. } = &mut context {
                    *subagent = None;
                }
                Some(context)
            }
            ContextItem::System { .. }
            | ContextItem::Reasoning { .. }
            | ContextItem::Tool { .. } => None,
        })
        .collect()
}

/// A role's bound template, sanitized into the child's opening history.
///
/// The body comes from the host's own template store; the role holds only an id.
/// A deleted template leaves that id dangling and reads as an empty history, so
/// a role whose template is gone still runs on the task alone.
///
/// `AgentRunOverrides::default()` matches what `context: "conversation"` passes:
/// the permanent floor (`subagent_tool_is_disabled` and the child-only tools)
/// applies, while the role's own allowlist does not narrow the transcript. The
/// role's allowlist still governs what the child can actually call — that is a
/// separate gate on the request, not on the history.
pub(crate) fn role_template_contexts(
    parent: &RunModelRequest,
    template_id: &str,
) -> Result<Vec<ContextItem>, String> {
    let anchor = Path::new(&parent.app_data_path).join("document.v1.json");
    let contexts = crate::conversations::store(&anchor)
        .and_then(|store| store.template_contexts(template_id))
        .map_err(|error| format!("角色的对话模板读取失败：{error}"))?;
    Ok(sanitize_child_history(
        &contexts,
        &AgentRunOverrides::default(),
    ))
}

/// The latest persisted run record per agent name across the conversation
/// timeline; this is what keeps agents addressable across turns and restarts.
pub(crate) fn historical_agent_records(
    contexts: &[ContextItem],
) -> BTreeMap<String, &SubagentRunRecord> {
    fn visit<'a>(
        contexts: &'a [ContextItem],
        records: &mut BTreeMap<String, &'a SubagentRunRecord>,
    ) {
        for context in contexts {
            if let ContextItem::Tool {
                subagent: Some(record),
                ..
            } = context
            {
                if let Some(name) = &record.name {
                    records.insert(name.clone(), record);
                }
            }
        }
    }

    let mut records = BTreeMap::new();
    visit(contexts, &mut records);
    records
}

pub(crate) fn subagent_names_in_contexts(contexts: &[ContextItem]) -> HashSet<String> {
    historical_agent_records(contexts).into_keys().collect()
}

fn build_rehydrated_agent_template(
    parent: &RunModelRequest,
    state: &AppState,
    name: &str,
    record: &SubagentRunRecord,
) -> Result<RunModelRequest, String> {
    verify_subagent_execution_mode(parent, state, name, record)?;
    if record.inherits_model_memory != record.fork_model_binding.is_some() {
        return Err(format!(
            "Persisted record for subagent {name} lacks or forges the conversation fork's exact binding; restoration was refused."
        ));
    }
    if record.agent_definition.is_some()
        && (record.inherits_model_memory || record.fork_model_binding.is_some())
    {
        return Err(format!(
            "Persisted record for subagent {name} declares both a fork and a named definition; restoration was refused."
        ));
    }
    let mut template = agent_child_template(parent);
    if let Some(binding) = record.agent_definition.as_ref() {
        let document = current_agent_document(parent, state)?;
        let definitions = request_agent_definitions(&document, parent);
        let definition =
            resolve_agent_definition(&document, definitions, &parent.workspace_id, &binding.name)?
                .clone();
        let (provider, model) =
            enabled_provider_model(&document, &binding.provider_id, &binding.model_id)?;
        configure_named_agent_template(
            parent,
            &mut template,
            &definition,
            binding.clone(),
            provider,
            model,
            &document.assets.web_search,
            // A persisted agent must stay continuable even if the definition was
            // later edited into an allowlist that resolves to nothing.
            AgentRunStart::Resume,
        )?;
        validate_current_agent_definition(&template, state)?;
    } else if let Some(binding) = record.fork_model_binding.as_ref() {
        let document = current_agent_document(parent, state)?;
        let (provider, model) =
            enabled_provider_model(&document, &binding.provider_id, &binding.model_id)?;
        template.provider = provider;
        template.model = model;
        restore_conversation_fork_binding(&mut template, binding)?;
        validate_current_fork_binding(&template)?;
    }
    // Restored AFTER `configure_named_agent_template`, exactly like the spawn
    // path: that call ends in `AgentRunOverrides::apply`, which intersects
    // `enabled_tools` against a named definition's allowlist, and an earlier
    // push would strip the one tool this run is required to call. The persisted
    // document is renderer-writable, so the schema goes back through the same
    // byte / node / depth / keyword precheck as a fresh spawn — a forged or
    // corrupted value refuses the continuation (fail closed) rather than
    // silently continuing without the constraint the parent contracted for.
    if let Some(document) = record.output_schema.as_ref() {
        let schema = orchestration::compile_output_schema(document).map_err(|error| {
            format!("Persisted output_schema for subagent {name} failed preflight; restoration was refused: {error}")
        })?;
        install_structured_output(&mut template, schema)?;
    }
    template.context_load_actor_name = Some(name.to_owned());
    Ok(template)
}

/// Re-registers an agent from its persisted record so `task_wait` can address
/// it in a later turn.
fn rehydrate_agent(
    pool: &AgentPool,
    parent: &RunModelRequest,
    state: &AppState,
    name: &str,
) -> Result<Option<Arc<AgentShared>>, String> {
    let history = historical_agent_records(&parent.contexts);
    let Some(record) = history.get(name) else {
        return Ok(None);
    };
    let template = build_rehydrated_agent_template(parent, state, name, record)?;
    let status = match record.status {
        SubagentRunStatus::Completed => AgentLiveStatus::Idle,
        SubagentRunStatus::Interrupted => AgentLiveStatus::Interrupted,
        SubagentRunStatus::Failed => AgentLiveStatus::Failed,
        SubagentRunStatus::Stopped => AgentLiveStatus::Stopped,
        SubagentRunStatus::RoundLimit => AgentLiveStatus::RoundLimit,
    };
    let shared = pool
        .register(
            name.to_owned(),
            name.to_owned(),
            record.task.clone(),
            template,
            // `verify_subagent_execution_mode` already rejected every record
            // whose kind is not `General`, so rehydration only ever restores
            // ordinary addressable agents. A search group is turn-local.
            SubagentRunKind::General,
            state,
            record.contexts.clone(),
            record.updates.clone(),
            status,
            // No live call: nothing runs it again, so finalize has no record
            // to backfill.
            String::new(),
            record.structured_output.clone(),
        )
        .map_err(|error| format!("Could not restore subagent {name}: {error}"))?;
    shared.restore_lifetime_usage(record.usage.clone());
    Ok(Some(shared))
}

fn find_or_rehydrate_agent(
    pool: &AgentPool,
    parent: &RunModelRequest,
    state: &AppState,
    name: &str,
) -> Result<Option<Arc<AgentShared>>, String> {
    if let Some(shared) = pool.find(name) {
        validate_current_agent_definition(&shared.template, state)?;
        validate_current_fork_binding(&shared.template)?;
        return Ok(Some(shared));
    }
    rehydrate_agent(pool, parent, state, name)
}

/// Wraps one normalized child event for the parent stream without flattening
/// its round or tool structure. `subagent_update` is additionally captured as
/// a parent-inbox envelope.
fn forward_child_event(
    shared: &AgentShared,
    incarnation: crate::agents::TaskIdentity,
    event_sink: &ModelEventSink<'_>,
    round: usize,
    call_id: &str,
    child_tool_calls: &Mutex<HashMap<String, (String, Option<JsonObject>)>>,
    event: ModelStreamEvent,
) -> Result<(), String> {
    let forward_delta = |channel: SubagentChannel, delta: String| {
        event_sink(ModelStreamEvent::SubagentDelta {
            round,
            call_id: call_id.to_owned(),
            channel,
            delta,
        })
    };
    let mut update = None;
    match &event {
        ModelStreamEvent::ToolCallAnnounced {
            call_id: child_call,
            tool_name,
            ..
        } => {
            child_tool_calls
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
                .insert(child_call.clone(), (tool_name.clone(), None));
        }
        ModelStreamEvent::ToolCallArgumentsReady {
            call_id: child_call,
            input,
            ..
        } => {
            if let Some((_, stored_input)) = child_tool_calls
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
                .get_mut(child_call)
            {
                *stored_input = Some(input.clone());
            }
        }
        ModelStreamEvent::ToolExecutionCompleted {
            call_id: child_call,
            result,
            ..
        } => {
            let (tool_name, input) = child_tool_calls
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
                .remove(child_call)
                .unwrap_or_else(|| ("tool".into(), None));
            if tool_name == SUBAGENT_UPDATE_TOOL && result.success {
                let message = input
                    .as_ref()
                    .and_then(|input| orchestration::parse_subagent_update(input).ok())
                    .unwrap_or_else(|| result.output.clone());
                update = Some((message, result.executed_at.clone()));
            }
        }
        _ => {}
    }

    // A child's cancellation probe must still reach the parent sink (so parent
    // cancellation interrupts child retry backoffs), but carries no content
    // worth wrapping into the child stream.
    if matches!(&event, ModelStreamEvent::Ping) {
        return event_sink(ModelStreamEvent::Ping);
    }

    // Keep the complete nested event envelope: flattening or dropping an
    // already nested event would hide a live child timeline until final
    // settlement. Debug request bodies remain process-local diagnostics.
    #[cfg(debug_assertions)]
    if !matches!(&event, ModelStreamEvent::DebugRequestBody { .. }) {
        event_sink(ModelStreamEvent::SubagentEvent {
            round,
            call_id: call_id.to_owned(),
            event: Box::new(event),
        })?;
    }
    #[cfg(not(debug_assertions))]
    event_sink(ModelStreamEvent::SubagentEvent {
        round,
        call_id: call_id.to_owned(),
        event: Box::new(event),
    })?;

    if let Some((message, created_at)) = update {
        shared.push_update(incarnation, message.clone(), created_at);
        forward_delta(SubagentChannel::Update, message)?;
    }
    Ok(())
}

/// Two failure paths before a child turn obtains `RunModelResponse`. Preserve
/// error text through settlement so preflight and run setup failures become
/// `Failed`; task-level cancellation settles as `Ok(stop_reason = "cancelled")`.
enum ChildRunError {
    /// Named-agent memory preflight failed (`refresh_named_agent_memory`).
    Preflight(String),
    /// `run_model` setup or pre-run failure.
    Run(String),
}

/// Runs an agent's one child turn from the transcript it was registered with.
///
/// Detached worker for a session-lifetime task. It communicates through the
/// session task surface; disconnected sinks may discard events but must not fail
/// the task. Task-level cancellation is the only termination cause.
fn agent_worker_loop(shared: &Arc<AgentShared>, state: &AppState, round: usize) {
    let call_id = shared.latest_call_id();
    // This child turn's incarnation identity gates all result, progress, and
    // cleanup writes, rejecting stale-worker writes at the core boundary.
    let incarnation = shared.identity();
    let guard = RunningTurnGuard::new(Arc::clone(shared));
    let mut child_request = shared.template.clone();
    child_request.contexts = shared.transcript();
    // The template is built before registration, so the worker is the first
    // place that knows which agent this request runs as. The dangerous-tool
    // dialog needs it: several children can be asking at once.
    child_request.subagent_name = Some(shared.name.clone());
    // Machine-readable coordinates derived from the name let approval cards
    // navigate the renderer to the requester page.
    child_request.subagent_call_id = Some(call_id.clone());
    // This round belongs to this task. Its task signal lets running shell and
    // hook commands observe the sidebar stop action promptly.
    child_request.task_cancel = CancelSignal::from_flag(shared.cancel_flag());
    let memory_preflight = refresh_named_agent_memory(&mut child_request, state);

    // Reacquire the surface for each child round to use the latest registered
    // security/workspace configuration. Without a surface, use a discard sink
    // but still call `forward_child_event`, whose capture side effects persist
    // progress for task waiting and records.
    let surface = state.task_surface(&shared.template.conversation_id);
    let idle_sink = |_: ModelStreamEvent| -> Result<(), String> { Ok(()) };
    let child_tool_calls: Mutex<HashMap<String, (String, Option<JsonObject>)>> =
        Mutex::new(HashMap::new());
    let child_sink = |event: ModelStreamEvent| -> Result<(), String> {
        if shared.cancel.load(std::sync::atomic::Ordering::Acquire) {
            return Err("The subagent was stopped.".into());
        }
        let sink: &ModelEventSink<'_> = match surface.as_ref() {
            Some(surface) => &*surface.sink,
            None => &idle_sink,
        };
        forward_child_event(
            shared,
            incarnation,
            sink,
            round,
            &call_id,
            &child_tool_calls,
            event,
        )
    };
    // No surface means no human approval channel, not a user refusal. Report
    // that host failure accurately in the tool result.
    let no_channel = |_: &ToolExecutionRequest,
                      _: &ToolDescriptor,
                      _: ApprovalRequester<'_>|
     -> Result<bool, String> {
        Err("This conversation does not yet have an available approval channel, so this tool call cannot be confirmed.".into())
    };
    // Bind this task's cancellation signal into approvals so the sidebar stop
    // action releases a pending approval.
    let bound_approval;
    let approval: &DangerousToolApproval<'_> = match surface.as_ref() {
        Some(surface) => {
            let approve = Arc::clone(&surface.approve);
            let flag_owner = Arc::clone(shared);
            bound_approval = move |request: &ToolExecutionRequest,
                                   descriptor: &ToolDescriptor,
                                   requester: ApprovalRequester<'_>|
                  -> Result<bool, String> {
                approve(request, descriptor, requester, Some(&flag_owner.cancel))
            };
            &bound_approval
        }
        None => &no_channel,
    };

    // Wall-clock of this child turn, reported to the parent so it can see
    // what a delegation cost.
    let turn_started = Instant::now();
    let child_run = match memory_preflight {
        Ok(()) => {
            let transcript = SubagentTranscriptSink::for_child(
                &child_request,
                state,
                Arc::clone(shared),
                incarnation,
            );
            run_model_with_transcript(child_request, state, &child_sink, approval, transcript)
                .map_err(ChildRunError::Run)
        }
        Err(error) => Err(ChildRunError::Preflight(error)),
    };
    let turn_duration_ms = turn_started.elapsed().as_millis() as u64;
    let status = match child_run {
        Ok(response) => {
            // Read before `response.contexts` is moved below.
            let structured_output = response.structured_output.clone();
            let final_text = response
                .contexts
                .iter()
                .rev()
                .find_map(|context| match context {
                    ContextItem::Assistant { content, .. } => Some(content.as_str()),
                    _ => None,
                })
                .unwrap_or_default();
            let reported = if shared.cancel.load(std::sync::atomic::Ordering::Acquire) {
                SubagentRunStatus::Interrupted
            } else {
                subagent_run_status(response.stop_reason.as_deref())
            };
            // Terminal request failures retain their cause only in
            // `response.error`. Propagate it so rate limits and empty responses
            // remain distinguishable and actionable.
            let output = match response.error.as_ref() {
                Some(error) if reported == SubagentRunStatus::Failed => {
                    orchestration::subagent_failure_output(
                        final_text,
                        &error.message,
                        &shared.template.prompt_profile,
                    )
                }
                _ => orchestration::subagent_result_output(
                    final_text,
                    &shared.template.prompt_profile,
                ),
            };
            let status = match reported {
                SubagentRunStatus::Completed => AgentLiveStatus::Idle,
                SubagentRunStatus::Failed => AgentLiveStatus::Failed,
                SubagentRunStatus::Stopped => AgentLiveStatus::Stopped,
                SubagentRunStatus::RoundLimit => AgentLiveStatus::RoundLimit,
                SubagentRunStatus::Interrupted => AgentLiveStatus::Interrupted,
            };
            // A run that was given a schema and finished with prose instead
            // handed back exactly what `output_schema` exists to prevent: a
            // result the parent has to re-parse. Reporting it as completed
            // would make the parent trust that text as the answer.
            let owes_structured_output = shared.template.output_schema.is_some()
                && structured_output.is_none()
                && status == AgentLiveStatus::Idle;
            let (status, output) = if owes_structured_output {
                (
                    AgentLiveStatus::Failed,
                    orchestration::missing_structured_output_output(
                        &output,
                        &shared.template.prompt_profile,
                    ),
                )
            } else {
                (status, output)
            };
            // The sidebar close is the one terminal cause the model cannot
            // infer from the partial text, so say it in the result itself.
            let output = if shared.stopped_by_user() {
                orchestration::append_user_close_note(&output, &shared.template.prompt_profile)
            } else {
                output
            };
            shared.complete_turn(
                incarnation,
                response.contexts,
                output,
                status,
                &response.usage,
                turn_duration_ms,
                structured_output,
            );
            status
        }
        Err(error) => {
            // Errors here are real preflight/setup failures, not task stops,
            // which settle as `Ok(stop_reason = "cancelled")`. Record them as
            // `Failed` with error text unless the task signal is already set.
            let (status, text) = if shared.cancel.load(std::sync::atomic::Ordering::Acquire) {
                (
                    AgentLiveStatus::Interrupted,
                    if shared.stopped_by_user() {
                        shared
                            .template
                            .prompt_profile
                            .text(PromptKey::TaskStoppedByUser)
                            .to_owned()
                    } else {
                        "(Subagent run interrupted)".into()
                    },
                )
            } else {
                match error {
                    ChildRunError::Preflight(error) => (
                        AgentLiveStatus::Failed,
                        format!("(Named-agent preflight failed: {error})"),
                    ),
                    ChildRunError::Run(error) => (
                        AgentLiveStatus::Failed,
                        format!("(Subagent run failed: {error})"),
                    ),
                }
            };
            shared.complete_turn(
                incarnation,
                Vec::new(),
                text,
                status,
                &ModelUsage::default(),
                turn_duration_ms,
                None,
            );
            status
        }
    };
    guard.defuse();
    // Incumbent guards may discard this write. Renderer receipts and self-claim
    // checks must use the recorded state rather than a locally predicted state.
    let applied_status = shared.status();
    let _ = status;
    // Best-effort lifecycle signal for the renderer; delivery is optional
    // The terminal state is already recorded. An idle surface sink may discard
    // live events; a wake run later completes the UI through fold and records.
    if let Some(surface) = surface.as_ref() {
        let _ = (surface.sink)(ModelStreamEvent::SubagentDelta {
            round,
            call_id: call_id.clone(),
            channel: SubagentChannel::Status,
            delta: applied_status.wire().into(),
        });
    }
}

/// Spawn a detached worker that captures only owned data, allowing its task to
/// survive across rounds.
fn spawn_agent_worker(shared: Arc<AgentShared>, state: &AppState, round: usize) {
    let state = state.clone();
    std::thread::spawn(move || {
        // Thread-level panic guard covers the gap between rounds. Per-round guards
        // settle their own panics as `Failed`; defuse after normal return.
        let guard = RunningTurnGuard::new(Arc::clone(&shared));
        agent_worker_loop(&shared, &state, round);
        guard.defuse();
    });
}

/// Scoped worker for workflow steps. Steps are internal to the driver, use
/// its wrapped sink and approval callback, and do not use the session task surface.
fn agent_worker_loop_scoped(
    shared: &Arc<AgentShared>,
    state: &AppState,
    event_sink: &ModelEventSink<'_>,
    approve_dangerous_tool: &TaskApproval<'_>,
    round: usize,
) {
    // Bind the step's task signal into approvals. Skipping a step or stopping the
    // workflow must release a pending card rather than holding the 30-minute budget.
    let flag_owner = Arc::clone(shared);
    let bound_approval = move |request: &ToolExecutionRequest,
                               descriptor: &ToolDescriptor,
                               requester: ApprovalRequester<'_>|
          -> Result<bool, String> {
        approve_dangerous_tool(request, descriptor, requester, Some(&flag_owner.cancel))
    };
    let approve_dangerous_tool: &DangerousToolApproval<'_> = &bound_approval;
    let call_id = shared.latest_call_id();
    let incarnation = shared.identity();
    let guard = RunningTurnGuard::new(Arc::clone(shared));
    let mut child_request = shared.template.clone();
    child_request.contexts = shared.transcript();
    child_request.subagent_name = Some(shared.name.clone());
    // Machine-readable coordinates derived from the name let approval cards
    // navigate the renderer to the requester page.
    child_request.subagent_call_id = Some(call_id.clone());
    // Skipping a step or cancelling race losers must reach commands and hooks
    // currently running for this step.
    child_request.task_cancel = CancelSignal::from_flag(shared.cancel_flag());
    let memory_preflight = refresh_named_agent_memory(&mut child_request, state);

    let child_tool_calls: Mutex<HashMap<String, (String, Option<JsonObject>)>> =
        Mutex::new(HashMap::new());
    let child_sink = |event: ModelStreamEvent| -> Result<(), String> {
        if shared.cancel.load(std::sync::atomic::Ordering::Acquire) {
            return Err("The subagent was stopped.".into());
        }
        forward_child_event(
            shared,
            incarnation,
            event_sink,
            round,
            &call_id,
            &child_tool_calls,
            event,
        )
    };

    let turn_started = Instant::now();
    let child_run = match memory_preflight {
        Ok(()) => run_model(child_request, state, &child_sink, approve_dangerous_tool)
            .map_err(ChildRunError::Run),
        Err(error) => Err(ChildRunError::Preflight(error)),
    };
    let turn_duration_ms = turn_started.elapsed().as_millis() as u64;
    let status = match child_run {
        Ok(response) => {
            let structured_output = response.structured_output.clone();
            let final_text = response
                .contexts
                .iter()
                .rev()
                .find_map(|context| match context {
                    ContextItem::Assistant { content, .. } => Some(content.as_str()),
                    _ => None,
                })
                .unwrap_or_default();
            let reported = if shared.cancel.load(std::sync::atomic::Ordering::Acquire) {
                SubagentRunStatus::Interrupted
            } else {
                subagent_run_status(response.stop_reason.as_deref())
            };
            // Terminal request failures retain their cause only in
            // `response.error`. Propagate it so rate limits and empty responses
            // remain distinguishable and actionable.
            let output = match response.error.as_ref() {
                Some(error) if reported == SubagentRunStatus::Failed => {
                    orchestration::subagent_failure_output(
                        final_text,
                        &error.message,
                        &shared.template.prompt_profile,
                    )
                }
                _ => orchestration::subagent_result_output(
                    final_text,
                    &shared.template.prompt_profile,
                ),
            };
            let status = match reported {
                SubagentRunStatus::Completed => AgentLiveStatus::Idle,
                SubagentRunStatus::Failed => AgentLiveStatus::Failed,
                SubagentRunStatus::Stopped => AgentLiveStatus::Stopped,
                SubagentRunStatus::RoundLimit => AgentLiveStatus::RoundLimit,
                SubagentRunStatus::Interrupted => AgentLiveStatus::Interrupted,
            };
            let owes_structured_output = shared.template.output_schema.is_some()
                && structured_output.is_none()
                && status == AgentLiveStatus::Idle;
            let (status, output) = if owes_structured_output {
                (
                    AgentLiveStatus::Failed,
                    orchestration::missing_structured_output_output(
                        &output,
                        &shared.template.prompt_profile,
                    ),
                )
            } else {
                (status, output)
            };
            shared.complete_turn(
                incarnation,
                response.contexts,
                output,
                status,
                &response.usage,
                turn_duration_ms,
                structured_output,
            );
            status
        }
        Err(error) => {
            // As in `agent_worker_loop`, `Err` means a real failure because
            // stopping settles as `Ok + cancelled`; retain its text as `Failed`
            // unless the cancellation signal is set.
            let (status, text) = if shared.cancel.load(std::sync::atomic::Ordering::Acquire) {
                (
                    AgentLiveStatus::Interrupted,
                    "(Subagent run interrupted)".into(),
                )
            } else {
                match error {
                    ChildRunError::Preflight(error) => (
                        AgentLiveStatus::Failed,
                        format!("(Named-agent preflight failed: {error})"),
                    ),
                    ChildRunError::Run(error) => (
                        AgentLiveStatus::Failed,
                        format!("(Subagent run failed: {error})"),
                    ),
                }
            };
            shared.complete_turn(
                incarnation,
                Vec::new(),
                text,
                status,
                &ModelUsage::default(),
                turn_duration_ms,
                None,
            );
            status
        }
    };
    guard.defuse();
    let applied_status = shared.status();
    let _ = status;
    let _ = event_sink(ModelStreamEvent::SubagentDelta {
        round,
        call_id: call_id.clone(),
        channel: SubagentChannel::Status,
        delta: applied_status.wire().into(),
    });
}

/// Scoped workflow-step spawn. It follows registered-worker lifetime rules but
/// runs in the driver's nested scope with borrowed sink and approval callback.
#[allow(clippy::too_many_arguments)]
pub(crate) fn start_registered_step_worker<'scope, 'env>(
    scope: &'scope std::thread::Scope<'scope, 'env>,
    shared: Arc<AgentShared>,
    state: &'env AppState,
    event_sink: &'env ModelEventSink<'env>,
    approve_dangerous_tool: &'env TaskApproval<'env>,
    round: usize,
    call_id: &str,
) -> Result<(), String> {
    let guard = RunningTurnGuard::new(Arc::clone(&shared));
    event_sink(ModelStreamEvent::SubagentDelta {
        round,
        call_id: call_id.to_owned(),
        channel: SubagentChannel::Status,
        delta: AgentLiveStatus::Running.wire().into(),
    })?;
    let worker_state = state.clone();
    scope.spawn(move || {
        agent_worker_loop_scoped(
            &shared,
            &worker_state,
            event_sink,
            approve_dangerous_tool,
            round,
        );
    });
    guard.defuse();
    Ok(())
}

/// Publishes the initial lifecycle state before a registered agent can produce
/// any child events, then starts its worker. If the parent stream has already
/// closed, the guard makes the registration terminal instead of leaving a
/// `Running` pool entry that has no worker.
pub(crate) fn start_registered_agent_worker(
    shared: Arc<AgentShared>,
    state: &AppState,
    event_sink: &ModelEventSink<'_>,
    round: usize,
    call_id: &str,
) -> Result<(), String> {
    let guard = RunningTurnGuard::new(Arc::clone(&shared));
    event_sink(ModelStreamEvent::SubagentDelta {
        round,
        call_id: call_id.to_owned(),
        channel: SubagentChannel::Status,
        delta: AgentLiveStatus::Running.wire().into(),
    })?;
    spawn_agent_worker(shared, state, round);
    guard.defuse();
    Ok(())
}

/// Custom worker variant of `start_registered_agent_worker` for workflow drivers.
/// Register a running delta before detached spawn; the worker completes its turn
/// and emits a terminal delta itself.
pub(crate) fn start_registered_worker_with<F>(
    shared: Arc<AgentShared>,
    event_sink: &ModelEventSink<'_>,
    round: usize,
    call_id: &str,
    worker: F,
) -> Result<(), String>
where
    F: FnOnce() + Send + 'static,
{
    let guard = RunningTurnGuard::new(Arc::clone(&shared));
    event_sink(ModelStreamEvent::SubagentDelta {
        round,
        call_id: call_id.to_owned(),
        channel: SubagentChannel::Status,
        delta: AgentLiveStatus::Running.wire().into(),
    })?;
    let worker_shared = Arc::clone(&shared);
    std::thread::spawn(move || {
        // A panic guard settles custom-worker panics as `Failed`; otherwise a
        // running pool entry would be permanent and cannot be stopped or checkpointed.
        let worker_guard = RunningTurnGuard::new(Arc::clone(&worker_shared));
        worker();
        worker_guard.defuse();
    });
    guard.defuse();
    Ok(())
}

/// Dispatches one `agent` tool call inside the run loop. Like the orchestration
/// tools, only event-sink failures propagate as `Err`; every semantic problem
/// becomes a failed tool result the model can react to.
#[allow(clippy::too_many_arguments)]
fn run_agent_tool(
    kind: agents::AgentToolKind,
    pool: &AgentPool,
    shadow: &crate::kernel_shadow::KernelShadow,
    parent: &RunModelRequest,
    call: ToolCall,
    state: &AppState,
    event_sink: &ModelEventSink<'_>,
    approve_dangerous_tool: &DangerousToolApproval<'_>,
    hook_allows_permission: bool,
    round: usize,
) -> Result<ToolExecution, String> {
    match kind {
        agents::AgentToolKind::Spawn => run_agent_spawn(
            pool,
            shadow,
            parent,
            call,
            state,
            event_sink,
            approve_dangerous_tool,
            hook_allows_permission,
            round,
        ),
        agents::AgentToolKind::Wait => {
            run_task_wait(pool, shadow, parent, call, state, event_sink, round)
        }
        agents::AgentToolKind::List => Ok(run_task_list(pool, parent, call, state)),
    }
}

#[allow(clippy::too_many_arguments)]
fn run_agent_spawn(
    pool: &AgentPool,
    shadow: &crate::kernel_shadow::KernelShadow,
    parent: &RunModelRequest,
    call: ToolCall,
    state: &AppState,
    event_sink: &ModelEventSink<'_>,
    approve_dangerous_tool: &DangerousToolApproval<'_>,
    hook_allows_permission: bool,
    round: usize,
) -> Result<ToolExecution, String> {
    if parent.subagent_depth >= 1 {
        // enabled_tools filtering already rejects nested calls before execution;
        // this is the defense-in-depth stop for any future call path.
        return Ok(failed_tool_execution(
            call,
            "Subagents cannot spawn further subagents.".into(),
        ));
    }
    let spec = match orchestration::parse_agent_spawn(
        &call.input,
        role_policy(parent, state).required(),
    ) {
        Ok(spec) => spec,
        Err(error) => return Ok(failed_tool_execution(call, error)),
    };
    let history = historical_agent_records(&parent.contexts);
    // The fourth source, and the only one that can see a name whose run never
    // persisted. `sign_subagent_execution_mode` writes its reservation row
    // before `pool.register` and before this turn's tool result reaches the
    // timeline, so a turn that dies in between leaves the name held by a row the
    // other three sources cannot see — while `auto_name` deterministically
    // returns to `a1`. Without this read, that name either re-reserves to
    // byte-identical bytes (silent no-op) or hard-errors FOREVER, and because
    // auto-naming would keep choosing it, the conversation loses `agent_spawn`
    // entirely rather than losing one name.
    //
    // A name reserved at registration may be missing from persisted records after
    // a mid-round crash. Check this source too or automatic naming can reuse a
    // permanently failing name.
    let orphan_reserved = state.reserved_subagent_names(&parent.conversation_id);
    let mut reserved_names = parent
        .subagent_reserved_names
        .iter()
        .map(String::as_str)
        .collect::<HashSet<_>>();
    reserved_names.extend(orphan_reserved.iter().map(String::as_str));
    let name = spec.name.clone();
    if history.contains_key(&name)
        || reserved_names.contains(name.as_str())
        || pool.find(&name).is_some()
    {
        return Ok(failed_tool_execution(
            call,
            format!(
                "The subagent name {name} is permanently reserved throughout this conversation branch tree; choose another name."
            ),
        ));
    }
    let label = spec
        .label
        .clone()
        .or_else(|| spec.agent_type.clone())
        .unwrap_or_else(|| name.clone());
    let mut initial_contexts = match spec.context {
        orchestration::SpawnContextMode::None => Vec::new(),
        orchestration::SpawnContextMode::Conversation => {
            forked_conversation_contexts(parent, &AgentRunOverrides::default())
        }
    };
    let mut template = agent_child_template(parent);
    let mut role_template_id = None;
    if spec.context == orchestration::SpawnContextMode::Conversation {
        if let Err(error) = inherit_parent_model_memory_for_fork(parent, &mut template, state) {
            return Ok(failed_tool_execution(call, error));
        }
    } else if let Some(agent_type) = spec.agent_type.as_deref() {
        match apply_named_role_to_fresh_template(parent, state, &mut template, agent_type) {
            Ok(template_id) => role_template_id = template_id,
            Err(error) => return Ok(failed_tool_execution(call, error)),
        }
    }
    // The role's template is the child's opening history. It cannot collide with
    // the forked branch above: `parse_agent_spawn` refuses `agent_type` together
    // with `context: "conversation"`, so at most one of the two ever seeds.
    if let Some(template_id) = role_template_id.as_deref() {
        match role_template_contexts(parent, template_id) {
            Ok(seeded) => initial_contexts.extend(seeded),
            Err(error) => return Ok(failed_tool_execution(call, error)),
        }
    }
    let initial_contexts = crate::conversation_template::seed_with_task(
        initial_contexts,
        &spec.task,
        new_context_id,
        Utc::now().to_rfc3339(),
    );
    template.context_load_actor_name = Some(name.clone());
    // After `configure_named_agent_template` on purpose. That path ends in
    // `AgentRunOverrides::apply`, which intersects `enabled_tools` against a
    // named definition's allowlist — injecting earlier would silently strip the
    // one tool this run is required to call, and only for named agents.
    if let Some(schema) = spec.output_schema {
        if let Err(error) = install_structured_output(&mut template, schema) {
            return Ok(failed_tool_execution(call, error));
        }
    }
    if let Err(error) = pool.preflight_registration(&name, &template, AgentLiveStatus::Running) {
        return Ok(failed_tool_execution(call, error));
    }
    // Delegation itself is a dangerous call under RequestApproval. Consume
    // its real approval before any durable name reservation or worker exists;
    // the caller's wrapper attributes only this decision to the parent shadow.
    let execution_request = ToolExecutionRequest {
        conversation_id: parent.conversation_id.clone(),
        workspace_path: parent.workspace_path.clone(),
        tool_name: call.name.clone(),
        input: call.input.clone(),
    };
    let decision = match security::classify_model_call(
        parent.effective_security_level(),
        Path::new(&parent.workspace_path),
        Path::new(&parent.app_data_path),
        &parent.additional_directories,
        &execution_request,
    ) {
        Ok(decision) => decision,
        Err(error) => {
            return Ok(failed_tool_execution(
                call,
                format!("Safety classification failed; the tool was not executed: {error}"),
            ))
        }
    };
    if decision.requires_approval && (!hook_allows_permission || decision.mandatory_prompt) {
        let Some(descriptor) = parent.tools.iter().find(|tool| tool.name == call.name) else {
            return Ok(failed_tool_execution(
                call,
                "Tool description is missing, so confirmation cannot be requested.".into(),
            ));
        };
        match approve_dangerous_tool(&execution_request, descriptor, approval_requester(parent)) {
            Ok(true) => {}
            Ok(false) => {
                return Ok(failed_tool_execution(
                    call,
                    "The user denied this tool call.".into(),
                ))
            }
            Err(error) => {
                return Ok(failed_tool_execution(
                    call,
                    format!("Could not confirm this tool call: {error}"),
                ))
            }
        }
    }
    if let Err(error) =
        reserve_subagent_execution_mode(&template, state, &name, SubagentRunKind::General)
    {
        return Ok(failed_tool_execution(call, error));
    }
    let shared = match pool.register(
        name.clone(),
        label,
        spec.task,
        template,
        SubagentRunKind::General,
        state,
        initial_contexts,
        Vec::new(),
        AgentLiveStatus::Running,
        call.id.clone(),
        // A fresh spawn has no earlier structured result to carry forward.
        None,
    ) {
        Ok(shared) => shared,
        Err(error) => return Ok(failed_tool_execution(call, error)),
    };
    // Give the shadow the host-minted first-generation incarnation identity so it
    // can validate identity-to-request binding from the spawn observation point.
    shadow.agent_spawned(&name, shared.identity());
    // Taken before the worker can move the record on: what the ledger keeps is the record as the
    // spawn made it — receipt, bindings, schema — for a startup that has to write one from nothing.
    let spawn_record = (!parent.app_data_path.is_empty()).then(|| shared.record());
    start_registered_agent_worker(shared, state, event_sink, round, &call.id)?;
    // From here the child owes the model a result that only this process can deliver. The ledger
    // outlives the process, so a startup after an exit that lost it can still say so.
    if let Some(spawn_record) = spawn_record {
        crate::subagent_ledger::record_spawned(
            Path::new(&parent.app_data_path),
            &parent.conversation_id,
            &name,
            &call.id,
            &spawn_record,
        );
        state.note_ledgered_subagent(&parent.conversation_id, &name);
    }
    Ok(ToolExecution {
        call,
        result: ToolResult {
            success: true,
            output: orchestration::agent_spawn_output(&name),
            images: Vec::new(),
            diff: None,
            executed_at: Utc::now().to_rfc3339(),
            duration_ms: 0,
        },
        subagent: None,
    })
}

/// Dispatches a backgrounded `bash`/`powershell` call. Consume approval before
/// spawn, then run the process as a `ShellCommand` pool worker for task identity,
/// fold/task_wait delivery, and round cleanup. The model sees `shell:<id>`, not
/// the internal pool name.
#[allow(clippy::too_many_arguments)]
fn run_background_shell(
    pool: &AgentPool,
    shadow: &crate::kernel_shadow::KernelShadow,
    parent: &RunModelRequest,
    call: ToolCall,
    state: &AppState,
    event_sink: &ModelEventSink<'_>,
    approve_dangerous_tool: &DangerousToolApproval<'_>,
    hook_allows_permission: bool,
    round: usize,
) -> Result<ToolExecution, String> {
    let kind = tool_executor::ShellKind::of_tool(&call.name)
        .expect("dispatch guarantees a shell tool name");
    if parent.subagent_depth >= 1 {
        // Children cannot use `task_wait`; fold is their only delivery path, and
        // their pool/shadow ownership intersects the parent round. Keep background
        // shell execution top-level only.
        return Ok(failed_tool_execution(
            call,
            "A subagent cannot run shell commands in the background; remove run_in_background to execute it synchronously.".into(),
        ));
    }
    let command = match tool_executor::parse_shell_command(&call.input) {
        Ok(command) => command,
        Err(error) => return Ok(failed_tool_execution(call, error)),
    };
    let execution_request = ToolExecutionRequest {
        conversation_id: parent.conversation_id.clone(),
        workspace_path: parent.workspace_path.clone(),
        tool_name: call.name.clone(),
        input: call.input.clone(),
    };
    // Use the synchronous approval discipline: classify first, then request approval
    // when the hook did not allow it or the classifier requires confirmation.
    let decision = match security::classify_model_call(
        parent.effective_security_level(),
        Path::new(&parent.workspace_path),
        Path::new(&parent.app_data_path),
        &parent.additional_directories,
        &execution_request,
    ) {
        Ok(decision) => decision,
        Err(error) => {
            return Ok(failed_tool_execution(
                call,
                format!("Safety classification failed; the tool was not executed: {error}"),
            ))
        }
    };
    if decision.requires_approval && (!hook_allows_permission || decision.mandatory_prompt) {
        let Some(descriptor) = parent.tools.iter().find(|tool| tool.name == call.name) else {
            return Ok(failed_tool_execution(
                call,
                "Tool description is missing, so confirmation cannot be requested.".into(),
            ));
        };
        match approve_dangerous_tool(&execution_request, descriptor, approval_requester(parent)) {
            Ok(true) => {}
            Ok(false) => {
                return Ok(failed_tool_execution(
                    call,
                    "The user denied this tool call.".into(),
                ))
            }
            Err(error) => {
                return Ok(failed_tool_execution(
                    call,
                    format!("Could not confirm this tool call: {error}"),
                ))
            }
        }
    }
    // Preflight capacity and name before process creation so a registration-race
    // loser never needs to terminate a newly started process.
    let history = historical_agent_records(&parent.contexts);
    let orphan_reserved = state.reserved_subagent_names(&parent.conversation_id);
    let mut reserved_names = parent
        .subagent_reserved_names
        .iter()
        .map(String::as_str)
        .collect::<HashSet<_>>();
    reserved_names.extend(orphan_reserved.iter().map(String::as_str));
    let name = pool.auto_name(&|candidate| {
        history.contains_key(candidate) || reserved_names.contains(candidate)
    });
    // This template never runs a model. Its worker polls a process; fields exist
    // only for execution-mode payloads and pool accounting.
    let template = agent_child_template(parent);
    if let Err(error) = pool.preflight_registration(&name, &template, AgentLiveStatus::Running) {
        return Ok(failed_tool_execution(call, error));
    }
    if let Err(error) =
        reserve_subagent_execution_mode(&template, state, &name, SubagentRunKind::ShellCommand)
    {
        return Ok(failed_tool_execution(call, error));
    }
    // A backgrounded command starts where the conversation's shell currently is,
    // but it does not move it: Claude Code reads the reported directory back only
    // for foreground calls, because a background `cd` finishing at an arbitrary
    // later moment would silently relocate whatever the model ran next. The
    // context is still built so the snapshot is sourced and the argv matches.
    //
    // The workspace the call named decides the machine, exactly as it does for a
    // synchronous shell: backgrounding changes when a command is waited for, not
    // where it runs.
    let workspaces = if parent.workspaces.is_empty() {
        crate::workspace_set::WorkspaceSet::local_root(&parent.workspace_path)
    } else {
        parent.workspaces.clone()
    };
    let selected = match tool_executor::workspace_argument(&call.input)
        .and_then(|index| workspaces.select(index).cloned())
    {
        Ok(selected) => selected,
        Err(error) => return Ok(failed_tool_execution(call, error)),
    };
    let program = match tool_executor::shell_program(&selected, kind) {
        Ok(program) => program,
        Err(error) => return Ok(failed_tool_execution(call, error)),
    };
    let shell_context = tool_executor::shell_call_context(
        kind,
        &selected.runner,
        &parent.conversation_id,
        Some(Path::new(&parent.app_data_path)),
        state,
        selected.sandbox.is_some(),
    );
    let local_anchor = if selected.is_local() {
        PathBuf::from(&selected.root)
    } else {
        PathBuf::from(&parent.workspace_path)
    };
    let start_dir = if selected.is_local() {
        state
            .shell_cwd(&parent.conversation_id)
            .unwrap_or_else(|| local_anchor.clone())
    } else {
        local_anchor.clone()
    };
    // The durable task address must exist before launching an independent process.
    let mut guard = match state.shell_tasks.try_register(
        &parent.conversation_id,
        kind.tool_name(),
        &command,
        true,
        crate::shell_tasks::ShellTaskOrigin {
            workspace_root: Some(&selected.root),
            // A remote command starts at its workspace root; `start_dir` is only this host's
            // anchor for it.
            cwd: if selected.is_local() {
                start_dir.to_str()
            } else {
                Some(&selected.root)
            },
            call_id: Some(&call.id),
        },
    ) {
        Ok(guard) => guard,
        Err(error) => return Ok(failed_tool_execution(call, error)),
    };
    let spawned = match tool_executor::spawn_shell_process(
        &local_anchor,
        &selected.root,
        &start_dir,
        kind,
        program.as_deref(),
        &command,
        &selected.runner,
        shell_context.session(),
        &parent.prompt_profile,
        selected.sandbox.as_ref(),
    ) {
        Ok(spawned) => spawned,
        Err(error) => {
            guard.finish(crate::shell_tasks::ShellTaskOutcome::Failed, None);
            return Ok(failed_tool_execution(call, error));
        }
    };
    let shell_ref = orchestration::TaskRef::Shell(guard.shell_task_id().to_owned()).wire();
    let shared = match pool.register(
        name.clone(),
        // `label` is the model-visible task address; `task_wait` resolves
        // `shell:<id>` to this pool entry and displays the same label.
        shell_ref.clone(),
        command.clone(),
        template,
        SubagentRunKind::ShellCommand,
        state,
        Vec::new(),
        Vec::new(),
        AgentLiveStatus::Running,
        call.id.clone(),
        None,
    ) {
        Ok(shared) => shared,
        Err(error) => {
            // The process is already running. On registration failure, terminate
            // its process tree so no unaddressable, uncleared command leaks.
            state
                .shell_tasks
                .request_stop(&parent.conversation_id, guard.shell_task_id());
            let _ = tool_executor::collect_shell_process(
                spawned,
                &mut guard,
                &|| true,
                &parent.prompt_profile,
            );
            return Ok(failed_tool_execution(call, error));
        }
    };
    // Treat this like ordinary tasks: validate identity-to-request binding from
    // the spawn observation point.
    shadow.agent_spawned(&name, shared.identity());
    let worker_shared = Arc::clone(&shared);
    let worker_state = state.clone();
    let tool_name = kind.tool_name();
    let worker_ref = shell_ref.clone();
    let worker_call_id = call.id.clone();
    // Draining starts before the worker thread does: a command that fills a pipe
    // buffer with nobody reading it blocks, and the gap between registering and
    // scheduling the worker is real.
    let run = match tool_executor::ShellRun::start(spawned, &guard, None) {
        Ok(run) => run,
        Err(error) => return Ok(failed_tool_execution(call, error)),
    };
    let spawn_output = orchestration::shell_background_spawn_output(tool_name, &shell_ref);
    start_registered_worker_with(
        Arc::clone(&shared),
        event_sink,
        round,
        &call.id,
        move || {
            drive_background_shell(
                worker_shared,
                worker_state,
                run,
                shell_context,
                guard,
                tool_name,
                worker_ref,
                round,
                worker_call_id,
            );
        },
    )?;
    Ok(ToolExecution {
        call,
        result: ToolResult {
            success: true,
            output: spawn_output,
            images: Vec::new(),
            diff: None,
            executed_at: Utc::now().to_rfc3339(),
            duration_ms: 0,
        },
        subagent: None,
    })
}

/// Adopts a foreground shell command whose deadline expired into the turn's task
/// pool, so it keeps running instead of being killed.
///
/// This is the host half of the kernel's `ToolBackground`: the call slot stays
/// executing and still owes its receipt, while a task slot takes over the
/// process under a fresh identity. Every refusal path gives the run back intact
/// so the caller can stop it — the one thing that must never happen is losing
/// track of a live process tree.
///
/// The order matters. Everything that can fail happens before ownership moves,
/// including the status event, because `start_registered_worker_with` would drop
/// the closure — and with it the child, the job object, and the reader threads —
/// if its event sink refused. That is why the worker thread is spawned directly
/// here rather than through that helper.
#[allow(clippy::too_many_arguments)]
fn adopt_timed_out_shell(
    pool: &AgentPool,
    shadow: &crate::kernel_shadow::KernelShadow,
    parent: &RunModelRequest,
    call_id: &str,
    kind: tool_executor::ShellKind,
    command: &str,
    state: &AppState,
    event_sink: &ModelEventSink<'_>,
    round: usize,
    run: tool_executor::ShellRun,
    guard: crate::shell_tasks::ShellTaskGuard,
    context: tool_executor::ShellCallContext,
    timeout: std::time::Duration,
) -> tool_executor::ShellHandoffOutcome {
    use tool_executor::ShellHandoffOutcome as Outcome;
    // Children cannot use `task_wait`; fold is their only delivery path, and
    // their pool/shadow ownership intersects the parent round. Background shell
    // execution stays top-level only, however the command got here.
    if parent.subagent_depth >= 1 {
        return Outcome::Refused(run, guard, context);
    }
    let history = historical_agent_records(&parent.contexts);
    let orphan_reserved = state.reserved_subagent_names(&parent.conversation_id);
    let mut reserved_names = parent
        .subagent_reserved_names
        .iter()
        .map(String::as_str)
        .collect::<HashSet<_>>();
    reserved_names.extend(orphan_reserved.iter().map(String::as_str));
    let name = pool.auto_name(&|candidate| {
        history.contains_key(candidate) || reserved_names.contains(candidate)
    });
    let template = agent_child_template(parent);
    if pool
        .preflight_registration(&name, &template, AgentLiveStatus::Running)
        .is_err()
    {
        // Every task slot is busy. Claude Code stops the command in exactly this
        // case, and so does the caller once this comes back.
        return Outcome::Refused(run, guard, context);
    }
    if reserve_subagent_execution_mode(&template, state, &name, SubagentRunKind::ShellCommand)
        .is_err()
    {
        return Outcome::Refused(run, guard, context);
    }
    // The row changes hands too: it was registered as a foreground command, so
    // this turn's cancellation would otherwise kill a command the model has just
    // been told is still running.
    if !state
        .shell_tasks
        .mark_background(&parent.conversation_id, guard.shell_task_id())
    {
        return Outcome::Refused(run, guard, context);
    }
    let shell_ref = orchestration::TaskRef::Shell(guard.shell_task_id().to_owned()).wire();
    let Ok(shared) = pool.register(
        name.clone(),
        shell_ref.clone(),
        command.to_owned(),
        template,
        SubagentRunKind::ShellCommand,
        state,
        Vec::new(),
        Vec::new(),
        AgentLiveStatus::Running,
        call_id.to_owned(),
        None,
    ) else {
        return Outcome::Refused(run, guard, context);
    };
    // The last fallible step before ownership moves.
    if event_sink(ModelStreamEvent::SubagentDelta {
        round,
        call_id: call_id.to_owned(),
        channel: SubagentChannel::Status,
        delta: AgentLiveStatus::Running.wire().into(),
    })
    .is_err()
    {
        return Outcome::Refused(run, guard, context);
    }
    shadow.tool_backgrounded(call_id, &name, shared.identity());

    let worker_shared = Arc::clone(&shared);
    let worker_state = state.clone();
    let tool_name = kind.tool_name();
    let worker_ref = shell_ref.clone();
    let worker_call_id = call_id.to_owned();
    std::thread::spawn(move || {
        // The same panic guard `start_registered_worker_with` installs: without
        // it a running pool entry would be permanent and could not be stopped.
        let worker_guard = RunningTurnGuard::new(Arc::clone(&worker_shared));
        drive_background_shell(
            worker_shared,
            worker_state,
            run,
            context,
            guard,
            tool_name,
            worker_ref,
            round,
            worker_call_id,
        );
        worker_guard.defuse();
    });
    Outcome::Adopted(orchestration::shell_timeout_backgrounded_output(
        tool_name,
        &shell_ref,
        timeout,
        &parent.prompt_profile,
    ))
}

/// Pool worker for background shell. Poll the OS process to completion, then
/// settle a normal task envelope and terminal delta. Its pool cancellation signal
/// is set only by task-level stop, never by round settlement.
///
/// Takes an already-draining [`tool_executor::ShellRun`] rather than a fresh
/// spawn, because the two ways a command gets here are not symmetric: an
/// explicit `run_in_background` starts one, while a foreground call that hit its
/// deadline hands over one that has been running and streaming for minutes. The
/// worker cannot tell the difference, and should not.
///
/// `context` is the call scaffolding, held only so its `Drop` removes the cwd
/// file once the command is really finished.
#[allow(clippy::too_many_arguments)]
fn drive_background_shell(
    shared: Arc<AgentShared>,
    state: AppState,
    run: tool_executor::ShellRun,
    context: tool_executor::ShellCallContext,
    mut guard: crate::shell_tasks::ShellTaskGuard,
    tool_name: &'static str,
    shell_ref: String,
    round: usize,
    call_id: String,
) {
    let _context = context;
    let incarnation = shared.identity();
    let started = Instant::now();
    let cancel_shared = Arc::clone(&shared);
    let cancel_probe = move || {
        cancel_shared
            .cancel
            .load(std::sync::atomic::Ordering::Acquire)
    };
    let profile = &shared.template.prompt_profile;
    // An output too long to deliver is saved beside the conversation's other
    // spilled output and delivered as its path and start, as in the
    // foreground.
    let spill_stem = format!("{tool_name}-{}", guard.shell_task_id());
    let spill = crate::tool_output::Spill::new(
        Some(Path::new(&shared.template.app_data_path)),
        &shared.template.conversation_id,
        &spill_stem,
    );
    let fit = |output: String| {
        crate::tool_output::fit(output, crate::tool_output::SHELL_INLINE_CHARS, spill, profile)
    };
    // No deadline on this leg: reaching one is what makes a command *become* a
    // background task, so a command that is already one has none left.
    let result = run.settle_in_background(&mut guard, &cancel_probe, profile);
    // The machine that ran the command timed it, when it could: this worker started a round
    // trip after it, and heard of its end only once its last output had arrived.
    let runtime = result.as_ref().ok().and_then(|result| result.runtime);
    let (status, text) = match result {
        Ok(result) => match result.end {
            tool_executor::ShellProcessEnd::Exited => {
                let text = orchestration::shell_background_result_text(
                    tool_name,
                    &shell_ref,
                    result.exit_code,
                    &fit(result.output),
                    profile,
                );
                if result.success {
                    (AgentLiveStatus::Idle, text)
                } else {
                    (AgentLiveStatus::Failed, text)
                }
            }
            // A user-stopped command still reports what it printed before the
            // kill; the body carries `tool.shell_user_aborted` at its end, so no
            // separate task-level close sentence is appended here.
            //
            // `TimedOut` cannot reach here: a deadline belongs to the
            // synchronous leg, and reaching one is what makes a command
            // *become* a background task rather than something that happens to
            // one. It is folded in with the stop cases so a future change that
            // does give background commands a deadline still reports the output
            // rather than dropping it.
            tool_executor::ShellProcessEnd::StoppedByUser
            | tool_executor::ShellProcessEnd::Cancelled
            | tool_executor::ShellProcessEnd::TimedOut => (
                AgentLiveStatus::Stopped,
                orchestration::shell_background_stopped_text(
                    tool_name,
                    &shell_ref,
                    &fit(result.output),
                    profile,
                ),
            ),
        },
        Err(error) => (
            AgentLiveStatus::Failed,
            profile.render(
                PromptKey::TaskShellFailedToRun,
                &[("shell_ref", &shell_ref), ("error", &error)],
            ),
        ),
    };
    let duration_ms = runtime
        .unwrap_or_else(|| started.elapsed())
        .as_millis()
        .min(u64::MAX as u128) as u64;
    shared.complete_turn(
        incarnation,
        Vec::new(),
        text,
        status,
        &ModelUsage::default(),
        duration_ms,
        None,
    );
    // This lifecycle signal is best-effort; recorded state is authoritative because
    // cancellation settlement may already have terminalized this incarnation.
    if let Some(surface) = state.task_surface(&shared.template.conversation_id) {
        let _ = (surface.sink)(ModelStreamEvent::SubagentDelta {
            round,
            call_id,
            channel: SubagentChannel::Status,
            delta: shared.status().wire().into(),
        });
    }
}

/// The prepared `web_fetch` backends, resolved before spawn.
///
/// The two are not variations on one request: `Native` asks the conversation's
/// own upstream to retrieve the page with its server-side fetch tool, which
/// hands back the page already converted to plain text, while `Provider` runs
/// the host's own HTTP pipeline against a catalog provider. Only families in
/// [`crate::web_search::family_supports_native_fetch`] can take the first path.
enum PreparedWebFetchBackend {
    Native {
        template: RunModelRequest,
    },
    Provider {
        resolved: crate::model::ResolvedSearchProvider,
        execution: crate::model::SearchExecutionConfig,
    },
}

/// Everything prepared for an asynchronous tool call at its call site. Its worker
/// needs only network work and never touches `AppState`, request state, or credentials.
enum PreparedAsyncTool {
    Search(PreparedWebSearchBackend),
    Fetch {
        backend: PreparedWebFetchBackend,
        urls: Vec<String>,
        /// Full access lets a directly named fetch target resolve to this
        /// machine or this network — usually the user's own development server.
        /// Redirects and search results stay outward-only at every level.
        allow_local_targets: bool,
    },
}

/// Worker body for an async tool. Both branches share a probe-sink contract:
/// an error means the user stopped this run.
fn perform_prepared_async_tool(
    prepared: &PreparedAsyncTool,
    profile: &PromptProfile,
    event_sink: &ModelEventSink<'_>,
    round: usize,
) -> Result<String, AsyncToolError> {
    match prepared {
        PreparedAsyncTool::Search(backend) => {
            perform_prepared_web_search(backend, profile, event_sink, round)
        }
        PreparedAsyncTool::Fetch {
            backend: PreparedWebFetchBackend::Native { template },
            ..
        } => match perform_web_fetch_request(template, event_sink, round) {
            Ok(items) => Ok(web_results_output(profile, &items)),
            Err(ModelRequestError::EventSink(_)) => Err(AsyncToolError::Cancelled),
            Err(error) => Err(AsyncToolError::Failed(format!(
                "Web fetch failed: {}",
                error.message()
            ))),
        },
        PreparedAsyncTool::Fetch {
            backend:
                PreparedWebFetchBackend::Provider {
                    resolved,
                    execution,
                },
            urls,
            allow_local_targets,
        } => {
            let outcome = crate::web_search::pipeline::run_capability(
                SearchCapability::FetchUrls,
                resolved,
                execution,
                crate::web_search::stored_secret(
                    resolved.kind,
                    crate::web_search::CredentialSlot::ApiKey,
                ),
                None,
                urls.clone(),
                *allow_local_targets,
                event_sink,
            );
            match outcome {
                Ok(items) => Ok(web_results_output(profile, &items)),
                Err(crate::web_search::SearchError::Cancelled(_)) => Err(AsyncToolError::Cancelled),
                Err(crate::web_search::SearchError::Config(message)) => Err(
                    AsyncToolError::Failed(format!("{message}; {WEB_FETCH_REPAIR_HINT}")),
                ),
                Err(crate::web_search::SearchError::Transient(message)) => {
                    Err(AsyncToolError::Failed(message))
                }
            }
        }
    }
}

/// An asynchronous tool call dispatched for round settlement. It carries all data
/// needed to reuse the shared settlement tail, so async and synchronous paths cannot
/// drift in PostToolUse, receipts, contexts, or shadow accounting.
struct PendingAsyncTool {
    call: ToolCall,
    /// Model-request parameters before hook rewriting, used to calculate the
    /// `requested_input` difference at settlement.
    requested_input: JsonObject,
    hook_allows_permission: bool,
    started: Instant,
    outcome: std::sync::mpsc::Receiver<Result<String, AsyncToolError>>,
    /// Set when settlement abandons this call. The worker probes every 500ms and
    /// stops network I/O when it is set.
    abandon: Arc<AtomicBool>,
}

/// Dispatch outcome. Locally decidable failures do not spawn a thread, so a
/// repairable denial does not add a round-end join.
enum AsyncToolDispatch {
    Pending(Box<PendingAsyncTool>),
    /// A locally settled parameter, authorization, or backend failure. It follows
    /// the normal synchronous settlement tail.
    Settled(ToolExecution),
}

/// Dispatches one concurrent `web_search` or `web_fetch` call. Consume approval
/// before dispatch and settle local failures synchronously, but do not mint task
/// identity or register a pool entry; the call's receipt carries its result at
/// round settlement.
#[allow(clippy::too_many_arguments)]
fn dispatch_async_tool(
    parent: &RunModelRequest,
    call: ToolCall,
    shadowed_approval: &DangerousToolApproval<'_>,
    hook_allows_permission: bool,
    requested_input: JsonObject,
    round: usize,
) -> Result<AsyncToolDispatch, String> {
    let started = Instant::now();
    // Parse both branches and consume approval before starting a thread: parse
    // parameters first, then approve all network effects of this call.
    let prepared = if call.name == WEB_SEARCH_TOOL {
        // Keep this explicit two-branch list aligned with `agents::runs_async`.
        // Unknown names must fail here, never be silently parsed as `web_fetch`.
        let query = match parse_web_search_query(&call.input) {
            Ok(query) => query,
            Err(error) => {
                return Ok(AsyncToolDispatch::Settled(web_tool_failure(
                    call, error, started,
                )))
            }
        };
        if let Some(refusal) = authorize_web_tool(
            parent,
            &call,
            shadowed_approval,
            hook_allows_permission,
            started,
        )? {
            return Ok(AsyncToolDispatch::Settled(refusal));
        }
        match prepare_web_search_backend(parent, query) {
            Ok(backend) => PreparedAsyncTool::Search(backend),
            Err(message) => {
                return Ok(AsyncToolDispatch::Settled(web_tool_failure(
                    call, message, started,
                )))
            }
        }
    } else if call.name == WEB_FETCH_TOOL {
        let urls = match parse_web_fetch_urls(&call.input) {
            Ok(urls) => urls,
            Err(error) => {
                return Ok(AsyncToolDispatch::Settled(web_tool_failure(
                    call, error, started,
                )))
            }
        };
        if let Some(refusal) = authorize_web_tool(
            parent,
            &call,
            shadowed_approval,
            hook_allows_permission,
            started,
        )? {
            return Ok(AsyncToolDispatch::Settled(refusal));
        }
        let backend = match parent.web_search.fetch.clone() {
            None => {
                return Ok(AsyncToolDispatch::Settled(web_tool_failure(
                    call,
                    format!("No usable web-fetch backend is configured; {WEB_FETCH_REPAIR_HINT}"),
                    started,
                )))
            }
            Some(crate::model::SearchFetchBackend::Provider(resolved)) => {
                PreparedWebFetchBackend::Provider {
                    resolved,
                    execution: parent.web_search.execution.clone(),
                }
            }
            Some(crate::model::SearchFetchBackend::Native) => PreparedWebFetchBackend::Native {
                template: web_fetch_request_template(parent, &urls),
            },
        };
        PreparedAsyncTool::Fetch {
            backend,
            urls,
            allow_local_targets: parent.effective_security_level()
                == crate::model::SecurityLevel::FullAccess,
        }
    } else {
        return Err(format!("{} is not an asynchronous tool", call.name));
    };
    // Probe cancellation by ownership: top-level rounds use this run's signal and
    // task rounds use their task signal. A conversation-wide lookup can interrupt
    // unrelated background search. Without a signal, still probe `abandon`.
    let owner_cancelled = parent.round_cancellation();
    let abandon = Arc::new(AtomicBool::new(false));
    let (sender, receiver) = std::sync::mpsc::channel();
    let worker_abandon = Arc::clone(&abandon);
    let tool_name = call.name.clone();
    let worker_profile = Arc::clone(&parent.prompt_profile);
    std::thread::spawn(move || {
        let probe = move |_event: ModelStreamEvent| -> Result<(), String> {
            if worker_abandon.load(Ordering::Acquire) || owner_cancelled.cancelled() {
                return Err(format!("{tool_name} was stopped with the run"));
            }
            Ok(())
        };
        let probe_sink: &ModelEventSink<'_> = &probe;
        // Probe before starting so a stop arriving between dispatch and scheduling
        // sends no network request.
        let outcome = match probe_sink(ModelStreamEvent::Ping) {
            Ok(()) => {
                // A worker panic must still yield a settlement outcome. Map a
                // disconnected channel to a readable failure rather than a hang.
                std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    perform_prepared_async_tool(&prepared, &worker_profile, probe_sink, round)
                }))
                .unwrap_or_else(|_| {
                    Err(AsyncToolError::Failed(
                        "Internal network-tool error (panic)".into(),
                    ))
                })
            }
            Err(_) => Err(AsyncToolError::Cancelled),
        };
        // If settlement abandoned the call, its receiver is gone and `send` failure
        // is normal.
        let _ = sender.send(outcome);
    });
    Ok(AsyncToolDispatch::Pending(Box::new(PendingAsyncTool {
        call,
        requested_input,
        hook_allows_permission,
        started,
        outcome: receiver,
        abandon,
    })))
}

/// Settle a dispatched asynchronous tool call.
/// Wait cancellably by pinging the parent sink every 500ms; a bare `recv()` would
/// make the stop action ineffective during a long upstream request. Propagate
/// cancellation rather than turning it into a tool failure.
fn collect_async_tool(
    pending: PendingAsyncTool,
    event_sink: &ModelEventSink<'_>,
) -> Result<ToolExecution, String> {
    let PendingAsyncTool {
        call,
        started,
        outcome,
        abandon,
        ..
    } = pending;
    loop {
        match outcome.recv_timeout(CANCELLATION_PROBE_INTERVAL) {
            Ok(Ok(text)) => return Ok(web_tool_success(call, text, started)),
            Ok(Err(AsyncToolError::Failed(message))) => {
                return Ok(web_tool_failure(call, message, started))
            }
            Ok(Err(AsyncToolError::Cancelled)) => {
                return Err(format!("{} was stopped with the run", call.name))
            }
            // A sender that vanished before sending is not cancellation; report a
            // readable failure.
            Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => {
                return Ok(web_tool_failure(
                    call,
                    "The network tool returned no result.",
                    started,
                ))
            }
            Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {
                if let Err(error) = event_sink(ModelStreamEvent::Ping) {
                    // User stop: tell the worker not to send requests, then propagate.
                    abandon.store(true, Ordering::Release);
                    return Err(error);
                }
            }
        }
    }
}

/// The dev servers this conversation may address, exactly as `preview_list`
/// lists them: in every one of its workspaces, its own plus the ones no
/// conversation owns, each carrying the workspace number that completes its
/// address when there are several.
///
/// The registry only ever holds servers that are starting or running — one that
/// exits is removed by its supervisor thread — so an id that is absent here has
/// either never existed or is already gone, and both answer the same way.
fn conversation_preview_servers(
    parent: &RunModelRequest,
    state: &AppState,
) -> Vec<tool_executor::AddressableServer> {
    let fallback;
    let workspaces = if parent.workspaces.is_empty() {
        fallback = crate::workspace_set::WorkspaceSet::local_root(&parent.workspace_path);
        &fallback
    } else {
        &parent.workspaces
    };
    tool_executor::addressable_preview_servers(state, workspaces, &parent.conversation_id)
}

/// The task address a dev server answers to — the form `task_list` prints.
fn preview_task_ref(server: &tool_executor::AddressableServer) -> orchestration::TaskRef {
    orchestration::TaskRef::Preview {
        server_id: server.server.server_id.clone(),
        workspace: server.workspace,
    }
}

/// What a `preview:` address names among `servers`. A workspace number in a
/// conversation with one workspace narrows nothing, so it is dropped rather than
/// made to miss.
fn address_preview_task<'a>(
    servers: &'a [tool_executor::AddressableServer],
    parent: &RunModelRequest,
    server_id: &str,
    workspace: Option<u32>,
) -> tool_executor::PreviewServerAddress<'a> {
    let workspace = workspace.filter(|_| parent.workspaces.len() > 1);
    tool_executor::address_preview_server(servers, server_id, workspace)
}

/// The dev server a `preview:` address names right now, if exactly one does.
fn preview_task_server(
    parent: &RunModelRequest,
    state: &AppState,
    server_id: &str,
    workspace: Option<u32>,
) -> Option<crate::preview_servers::PreviewServerSnapshot> {
    let servers = conversation_preview_servers(parent, state);
    match address_preview_task(&servers, parent, server_id, workspace) {
        tool_executor::PreviewServerAddress::Found(found) => Some(found.server.clone()),
        _ => None,
    }
}

/// Where a dev server answers, as a task row and an observation say it: its port,
/// and the machine when that `localhost` is not this computer's.
fn preview_task_detail(server: &crate::preview_servers::PreviewServerSnapshot) -> String {
    match &server.machine {
        Some(machine) => format!("localhost:{} · {machine}", server.port),
        None => format!("localhost:{}", server.port),
    }
}

/// The status word a dev-server row and observation share.
///
/// `None` is a server the registry no longer holds. The registry drops a server
/// the moment its process exits, whoever ended it, so "stopped" covers both a
/// `preview_stop` and a crash — and an id that never existed cannot reach here,
/// because resolution refuses it first.
fn preview_status_key(
    status: Option<crate::preview_servers::PreviewServerStatus>,
) -> PromptKey {
    match status {
        Some(crate::preview_servers::PreviewServerStatus::Starting) => PromptKey::TaskPreviewStarting,
        Some(crate::preview_servers::PreviewServerStatus::Running) => PromptKey::TaskPreviewRunning,
        _ => PromptKey::TaskPreviewStopped,
    }
}

/// Resolves the agent half of a wait spec. Non-agent addresses are validated
/// here too — waiting on a terminal that does not exist must fail loudly rather
/// than silently watching nothing.
fn resolve_wait_targets(
    pool: &AgentPool,
    parent: &RunModelRequest,
    state: &AppState,
    spec: &orchestration::TaskWaitSpec,
) -> Result<(Vec<Arc<AgentShared>>, Vec<orchestration::TaskRef>), String> {
    if spec.tasks.is_empty() {
        // A bare wait watches subagents only. Including terminals here would
        // let `task_wait` block on a shell the user is typing into.
        return Ok((pool.all(), Vec::new()));
    }
    let mut agents = Vec::new();
    let mut others = Vec::new();
    for task in &spec.tasks {
        match task {
            orchestration::TaskRef::Agent(name) => {
                match find_or_rehydrate_agent(pool, parent, state, name)? {
                    Some(shared) => agents.push(shared),
                    None => {
                        return Err(format!("There is no subagent named {name}; use task_list to see the existing tasks"))
                    }
                }
            }
            orchestration::TaskRef::Terminal(terminal_id) => {
                if state
                    .terminals
                    .task_snapshot(&parent.conversation_id, terminal_id)
                    .is_none()
                {
                    return Err(format!(
                        "There is no terminal terminal:{terminal_id}; use task_list to see the existing tasks"
                    ));
                }
                others.push(task.clone());
            }
            orchestration::TaskRef::Preview {
                server_id,
                workspace,
            } => {
                let servers = conversation_preview_servers(parent, state);
                match address_preview_task(&servers, parent, server_id, *workspace) {
                    // Watched under the address `task_list` prints, workspace included, so a
                    // bare id cannot turn ambiguous halfway through the wait when another
                    // workspace starts a server of the same name.
                    tool_executor::PreviewServerAddress::Found(found) => {
                        let canonical = preview_task_ref(found);
                        if !others.contains(&canonical) {
                            others.push(canonical);
                        }
                    }
                    tool_executor::PreviewServerAddress::Ambiguous(numbers) => {
                        let addresses = numbers
                            .iter()
                            .map(|number| format!("preview:{server_id}@{number}"))
                            .collect::<Vec<_>>()
                            .join(", ");
                        return Err(format!(
                            "preview:{server_id} names dev servers in more than one workspace; wait on one of {addresses}"
                        ));
                    }
                    tool_executor::PreviewServerAddress::Elsewhere(_)
                    | tool_executor::PreviewServerAddress::Missing => {
                        return Err(format!(
                            "There is no dev server {}; use task_list to see the existing tasks",
                            task.wire()
                        ));
                    }
                }
            }
            orchestration::TaskRef::Shell(shell_task_id) => {
                // Resolve background shell tasks through pool entries first. Their
                // envelopes contain command output and use the task-wait delivery path;
                // historical synchronous-shell rows still use snapshot observation.
                let wire = task.wire();
                if let Some(shared) = pool.all().into_iter().find(|agent| {
                    agent.kind == SubagentRunKind::ShellCommand && agent.label == wire
                }) {
                    agents.push(shared);
                    continue;
                }
                if state
                    .shell_tasks
                    .task_snapshot(&parent.conversation_id, shell_task_id)
                    .is_none()
                {
                    return Err(format!(
                        "There is no command shell:{shell_task_id}; it may have already finished. Use task_list to see the existing tasks."
                    ));
                }
                others.push(task.clone());
            }
            orchestration::TaskRef::Workflow(run_id) => {
                // A workflow driver is a pool entry whose label is its task address.
                // Terminal agents remain collectable in the same round; old cross-
                // round runs are already folded or in the timeline and cannot be waited.
                let wire = task.wire();
                if let Some(shared) = pool.all().into_iter().find(|agent| {
                    agent.kind == SubagentRunKind::WorkflowStep && agent.label == wire
                }) {
                    agents.push(shared);
                    continue;
                }
                return Err(format!(
                    "There is no running workflow workflow:{run_id}; it may have already finished (its result is in the timeline). Use task_list to see the existing tasks."
                ));
            }
        }
    }
    Ok((agents, others))
}

/// Where a non-agent task stands right now. Terminals and dev servers stream
/// nothing into the agent outbox, so the wait reports a snapshot of each one
/// taken when it returned rather than an envelope.
fn observe_task(
    task: &orchestration::TaskRef,
    parent: &RunModelRequest,
    state: &AppState,
) -> orchestration::TaskObservation {
    let profile = &parent.prompt_profile;
    // Share one predicate between the wait loop and timeout text so they cannot
    // disagree about whether an address has been delivered or is still running.
    let settled = non_agent_task_is_settled(task, parent, state);
    match task {
        orchestration::TaskRef::Agent(name) => orchestration::TaskObservation {
            task: name.clone(),
            label: name.clone(),
            status_label: "unknown".into(),
            detail: None,
            settled,
        },
        // Workflow refs always resolve to pool entries (or fail resolution), so
        // like agents they never reach the snapshot-observation path.
        orchestration::TaskRef::Workflow(run_id) => orchestration::TaskObservation {
            task: task.wire(),
            label: run_id.clone(),
            status_label: "unknown".into(),
            detail: None,
            settled,
        },
        orchestration::TaskRef::Terminal(terminal_id) => {
            let snapshot = state
                .terminals
                .task_snapshot(&parent.conversation_id, terminal_id);
            orchestration::TaskObservation {
                task: task.wire(),
                label: terminal_id.clone(),
                status_label: profile
                    .text(match &snapshot {
                        Some(snapshot) if snapshot.busy => PromptKey::TaskTerminalRunning,
                        Some(snapshot) if snapshot.alive => PromptKey::TaskTerminalIdle,
                        Some(_) => PromptKey::TaskTerminalExited,
                        None => PromptKey::TaskTerminalClosed,
                    })
                    .to_owned(),
                detail: snapshot.map(|snapshot| snapshot.cwd),
                settled,
            }
        }
        orchestration::TaskRef::Preview {
            server_id,
            workspace,
        } => {
            let server = preview_task_server(parent, state, server_id, *workspace);
            orchestration::TaskObservation {
                task: task.wire(),
                label: server
                    .as_ref()
                    .map(|server| server.name.clone())
                    .unwrap_or_else(|| server_id.clone()),
                status_label: profile
                    .text(preview_status_key(server.as_ref().map(|server| server.status)))
                    .to_owned(),
                detail: server.as_ref().map(preview_task_detail),
                settled,
            }
        }
        orchestration::TaskRef::Shell(shell_task_id) => {
            let snapshot = state
                .shell_tasks
                .task_snapshot(&parent.conversation_id, shell_task_id);
            orchestration::TaskObservation {
                task: task.wire(),
                label: snapshot
                    .as_ref()
                    .map(|snapshot| snapshot.tool_name.clone())
                    .unwrap_or_else(|| shell_task_id.clone()),
                status_label: profile
                    .text(match snapshot.as_ref().map(|snapshot| snapshot.outcome) {
                        Some(Some(ShellTaskOutcome::Succeeded)) => PromptKey::TaskStatusCompleted,
                        Some(Some(ShellTaskOutcome::Failed)) => PromptKey::TaskStatusFailed,
                        Some(Some(ShellTaskOutcome::Stopped)) => PromptKey::TaskShellAborted,
                        // Still running. `stopping` is the window between the stop request and the
                        // process tree actually dying, which on a large tree is worth naming.
                        Some(None) if snapshot.as_ref().is_some_and(|snap| snap.stopping) => {
                            PromptKey::TaskShellAborting
                        }
                        Some(None) => PromptKey::TaskShellRunning,
                        // Evicted by the retention cap, or never existed.
                        None => PromptKey::TaskShellFinished,
                    })
                    .to_owned(),
                detail: snapshot.map(|snapshot| snapshot.command),
                settled,
            }
        }
    }
}

/// Whether one watched non-agent task has settled. A terminal settles when no
/// command is running; a dev server settles once it is no longer coming up,
/// which includes having gone away entirely — a process that exited answers the
/// wait rather than burning the whole timeout.
fn non_agent_task_is_settled(
    task: &orchestration::TaskRef,
    parent: &RunModelRequest,
    state: &AppState,
) -> bool {
    match task {
        orchestration::TaskRef::Agent(_) => true,
        orchestration::TaskRef::Workflow(_) => true,
        orchestration::TaskRef::Terminal(terminal_id) => state
            .terminals
            .task_snapshot(&parent.conversation_id, terminal_id)
            .is_none_or(|snapshot| !snapshot.busy),
        orchestration::TaskRef::Preview {
            server_id,
            workspace,
        } => preview_task_server(parent, state, server_id, *workspace).is_none_or(|server| {
            server.status != crate::preview_servers::PreviewServerStatus::Starting
        }),
        // Asked of the registry rather than inferred from the row's absence: a finished command
        // keeps its row now, so presence no longer means "still running".
        orchestration::TaskRef::Shell(shell_task_id) => !state
            .shell_tasks
            .is_running(&parent.conversation_id, shell_task_id),
    }
}

/// Whether every watched non-agent task has settled.
fn non_agent_tasks_are_settled(
    tasks: &[orchestration::TaskRef],
    parent: &RunModelRequest,
    state: &AppState,
) -> bool {
    tasks
        .iter()
        .all(|task| non_agent_task_is_settled(task, parent, state))
}

fn run_task_wait(
    pool: &AgentPool,
    shadow: &crate::kernel_shadow::KernelShadow,
    parent: &RunModelRequest,
    call: ToolCall,
    state: &AppState,
    event_sink: &ModelEventSink<'_>,
    round: usize,
) -> Result<ToolExecution, String> {
    let spec = match orchestration::parse_task_wait(&call.input) {
        Ok(spec) => spec,
        Err(error) => return Ok(failed_tool_execution(call, error)),
    };
    let started = Instant::now();
    let (watched, others) = match resolve_wait_targets(pool, parent, state, &spec) {
        Ok(targets) => targets,
        Err(error) => return Ok(failed_tool_execution(call, error)),
    };
    // Start the shadow task-wait window for each observed task. Delivered terminal
    // results settle the wait; all others time out on return. Turn cancellation
    // invalidates waits, and current incarnation identity is recorded.
    for agent in &watched {
        shadow.task_wait_started(&agent.name, agent.identity());
    }
    let deadline = started + Duration::from_secs(spec.timeout_seconds);
    // The heartbeat keeps cancellation observable while this blocks: the
    // renderer ignores empty status deltas, but a dead sink errors here
    // and aborts the wait immediately.
    let heartbeat = || {
        event_sink(ModelStreamEvent::SubagentDelta {
            round,
            call_id: call.id.clone(),
            channel: SubagentChannel::Status,
            delta: String::new(),
        })
    };
    let outcome = if watched.is_empty() {
        agents::WaitOutcome {
            envelopes: Vec::new(),
            timed_out: false,
        }
    } else {
        // Block until every observed task has a terminal result. Progress updates
        // and an early sibling result do not end the wait; buffer results for one
        // final return.
        pool.wait_results_until(&watched, deadline, &heartbeat)?
    };
    // Non-pooled tasks must also be truly awaited. Use the same absolute deadline
    // with pooled work so mixed waits cannot return after only one result.
    let mut outcome = outcome;
    if !others.is_empty() {
        loop {
            if non_agent_tasks_are_settled(&others, parent, state) {
                break;
            }
            if Instant::now() >= deadline {
                outcome.timed_out = true;
                break;
            }
            heartbeat()?;
            std::thread::sleep(agents::WAIT_POLL_INTERVAL);
        }
    }
    // Project each retrieved terminal envelope as settlement then wait delivery.
    // Undelivered waits time out only on deadline or when the task becomes terminal
    // without an envelope; progress and sibling delivery do not end them.
    for envelope in &outcome.envelopes {
        if let agents::EnvelopeKind::Result(_) = envelope.kind {
            // Validate delivery against the envelope's actual incarnation identity;
            // stale cross-generation envelopes are rejected by the shadow.
            shadow.task_wait_claimed(&envelope.agent, envelope.identity);
        }
    }
    for agent in &watched {
        let delivered = outcome.envelopes.iter().any(|envelope| {
            matches!(envelope.kind, agents::EnvelopeKind::Result(_)) && envelope.agent == agent.name
        });
        if !delivered {
            shadow.task_wait_timed_out(&agent.name, agent.identity());
        }
    }
    // Pool names are internal; the model knows `shell:<id>` and `workflow:<runId>`
    // task addresses, which are the corresponding entry labels. Use them for display
    // after shadow accounting completes under the internal name.
    for envelope in &mut outcome.envelopes {
        if let Some(agent) = watched.iter().find(|agent| {
            agent.name == envelope.agent
                && matches!(
                    agent.kind,
                    SubagentRunKind::ShellCommand | SubagentRunKind::WorkflowStep
                )
        }) {
            envelope.agent = agent.label.clone();
        }
    }
    let statuses = watched
        .iter()
        .map(|agent| {
            let display = if matches!(
                agent.kind,
                SubagentRunKind::ShellCommand | SubagentRunKind::WorkflowStep
            ) {
                agent.label.clone()
            } else {
                agent.name.clone()
            };
            (display, agent.status())
        })
        .collect::<Vec<_>>();
    let observations = others
        .iter()
        .map(|task| observe_task(task, parent, state))
        .collect::<Vec<_>>();
    let output = orchestration::format_wait_output(
        &outcome.envelopes,
        &statuses,
        &observations,
        outcome.timed_out,
        spec.timeout_seconds,
        &parent.prompt_profile,
    );
    Ok(ToolExecution {
        call,
        result: ToolResult {
            success: true,
            output,
            images: Vec::new(),
            diff: None,
            executed_at: Utc::now().to_rfc3339(),
            duration_ms: started.elapsed().as_millis().min(u64::MAX as u128) as u64,
        },
        subagent: None,
    })
}

fn run_task_list(
    pool: &AgentPool,
    parent: &RunModelRequest,
    call: ToolCall,
    state: &AppState,
) -> ToolExecution {
    let profile = &parent.prompt_profile;
    let mut agent_rows = Vec::new();
    let mut workflow_rows = Vec::new();
    let live = pool.all();
    for agent in &live {
        if agent.kind == SubagentRunKind::ShellCommand {
            // A shell pool entry is internal; the model-visible form is the
            // `shell:<id>` row in the Shell Commands group.
            continue;
        }
        let status = agent.status();
        if agent.kind == SubagentRunKind::WorkflowStep {
            // Keep workflow drivers out of the subagent group: their internal pool
            // names are not model-visible. Display `workflow:<runId>` in the
            // Workflows group instead.
            workflow_rows.push(orchestration::TaskListRow {
                task: agent.label.clone(),
                label: agent.label.clone(),
                status_label: profile.text(status.prompt_key()).to_owned(),
                detail: agent.task.clone(),
                latest_update: agent.latest_update(),
            });
            continue;
        }
        agent_rows.push(orchestration::TaskListRow {
            task: agent.name.clone(),
            label: agent.label.clone(),
            status_label: profile.text(status.prompt_key()).to_owned(),
            detail: agent.task.clone(),
            latest_update: agent.latest_update(),
        });
    }
    for (name, record) in historical_agent_records(&parent.contexts) {
        if live.iter().any(|agent| agent.name == name) {
            continue;
        }
        let persisted_status = profile.text(orchestration::persisted_status_key(record.status));
        if record.kind == SubagentRunKind::WorkflowStep {
            // Historical workflow runs use their recorded `workflow:<runId>` label.
            // An old record without a label has no address, so report only status.
            let address = record.label.clone().unwrap_or_else(|| "workflow".into());
            workflow_rows.push(orchestration::TaskListRow {
                task: address.clone(),
                label: address,
                status_label: format!(
                    "{persisted_status}{}",
                    profile.text(PromptKey::TaskListResultInTimeline)
                ),
                detail: record.task.clone(),
                latest_update: record.updates.last().map(|update| update.content.clone()),
            });
            continue;
        }
        agent_rows.push(orchestration::TaskListRow {
            task: name.clone(),
            label: name,
            status_label: format!(
                "{persisted_status}{}",
                profile.text(PromptKey::TaskListResultInTimeline)
            ),
            detail: record.task.clone(),
            latest_update: record.updates.last().map(|update| update.content.clone()),
        });
    }
    let terminal_rows = state
        .terminals
        .task_snapshots(&parent.conversation_id)
        .into_iter()
        .map(|snapshot| orchestration::TaskListRow {
            task: orchestration::TaskRef::Terminal(snapshot.terminal_id.clone()).wire(),
            label: snapshot.terminal_id,
            status_label: profile
                .text(if snapshot.busy {
                    PromptKey::TaskTerminalRunning
                } else if snapshot.alive {
                    PromptKey::TaskTerminalIdle
                } else {
                    PromptKey::TaskTerminalExited
                })
                .to_owned(),
            detail: format!("{} · {}", snapshot.shell, snapshot.cwd),
            latest_update: None,
        })
        .collect::<Vec<_>>();
    // The dev servers this conversation started, plus any nobody owns, in every
    // workspace. The page each one is showing is not a row: it is a view of the
    // process, it cannot be waited on, and closing the server closes it.
    let preview_rows = conversation_preview_servers(parent, state)
        .iter()
        .map(|addressable| orchestration::TaskListRow {
            task: preview_task_ref(addressable).wire(),
            label: addressable.server.name.clone(),
            status_label: profile
                .text(preview_status_key(Some(addressable.server.status)))
                .to_owned(),
            detail: preview_task_detail(&addressable.server),
            latest_update: None,
        })
        .collect::<Vec<_>>();
    // A conversation's own shell command can only be one another tool call started,
    // so a *running* row here is normally one a sibling agent sharing the conversation
    // started. Finished rows are the conversation's own command history, which is what
    // makes this list answer "did that build pass" instead of only "what is running".
    let shell_rows = state
        .shell_tasks
        .task_snapshots(&parent.conversation_id)
        .into_iter()
        .map(|snapshot| orchestration::TaskListRow {
            task: orchestration::TaskRef::Shell(snapshot.shell_task_id.clone()).wire(),
            label: snapshot.tool_name,
            status_label: match snapshot.outcome {
                Some(ShellTaskOutcome::Succeeded) => match snapshot.exit_code {
                    Some(code) => profile.render(
                        PromptKey::TaskShellCompleted,
                        &[("code", &code.to_string())],
                    ),
                    None => profile.text(PromptKey::TaskStatusCompleted).to_owned(),
                },
                Some(ShellTaskOutcome::Failed) => match snapshot.exit_code {
                    Some(code) => {
                        profile.render(PromptKey::TaskShellFailed, &[("code", &code.to_string())])
                    }
                    None => profile.text(PromptKey::TaskStatusFailed).to_owned(),
                },
                Some(ShellTaskOutcome::Stopped) => {
                    profile.text(PromptKey::TaskShellAborted).to_owned()
                }
                None if snapshot.stopping => profile.text(PromptKey::TaskShellAborting).to_owned(),
                None => profile.text(PromptKey::TaskShellRunning).to_owned(),
            },
            detail: snapshot.command,
            latest_update: None,
        })
        .collect::<Vec<_>>();
    let groups = vec![
        orchestration::TaskListGroup {
            title: profile.text(PromptKey::TaskGroupSubagents).to_owned(),
            rows: agent_rows,
        },
        orchestration::TaskListGroup {
            title: profile.text(PromptKey::TaskGroupWorkflows).to_owned(),
            rows: workflow_rows,
        },
        orchestration::TaskListGroup {
            title: profile.text(PromptKey::TaskGroupTerminals).to_owned(),
            rows: terminal_rows,
        },
        orchestration::TaskListGroup {
            title: profile.text(PromptKey::TaskGroupPreviewServers).to_owned(),
            rows: preview_rows,
        },
        orchestration::TaskListGroup {
            title: profile.text(PromptKey::TaskGroupShellCommands).to_owned(),
            rows: shell_rows,
        },
    ];
    ToolExecution {
        call,
        result: ToolResult {
            success: true,
            output: orchestration::format_task_list(&groups, profile),
            images: Vec::new(),
            diff: None,
            executed_at: Utc::now().to_rfc3339(),
            duration_ms: 0,
        },
        subagent: None,
    }
}

fn tool_execution_owns_subagent_record(execution: &ToolExecution) -> bool {
    // Pool-managed workflow tasks backfill cumulative records into their own tool
    // contexts. `web_search` creates no task and therefore has no subagent record.
    agents::agent_tool_kind(&execution.call.name).is_some()
        || execution.call.name == workflow::WORKFLOW_TOOL
}

/// The text the UserPromptSubmit hook receives as the turn's prompt: the last
/// REAL user context. An S9 agent-result notification can sit at the very end
/// of a turn's timeline, and feeding child-authored output to user-configured
/// hook commands as "the user's prompt" would hand a subagent transcript an
/// authority it never had.
pub(crate) fn latest_user_prompt(contexts: &[ContextItem]) -> String {
    contexts
        .iter()
        .rev()
        .find_map(|context| match context {
            ContextItem::User { id, content, .. }
                if !id.starts_with(AGENT_RESULT_CONTEXT_ID_PREFIX) =>
            {
                Some(content.clone())
            }
            _ => None,
        })
        .unwrap_or_default()
}

/// Full id prefix of the contexts minted by `fold_undrained_agent_results`
/// (i.e. `new_context_id("agent-result")`). It is the timeline identity of a
/// host-delivered background result — the one thing that tells a folded
/// delivery card apart from a `task_wait` the model actually called.
///
/// Fold uses a host-synthesized `task_wait` tool context, projected on the wire as
/// a system notification with a bare `<task-notification>`. Remaining host consumers
/// filter historical pre-migration User contexts; new tool contexts need no such filter.
const AGENT_RESULT_CONTEXT_ID_PREFIX: &str = crate::wire_history::HOST_TASK_DELIVERY_CONTEXT_PREFIX;

/// Queues the problems language servers reported since the last round as one
/// host notice.
///
/// Gated on the editing tools, as the source is: diagnostics exist to tell the
/// model what its own edits broke, and a conversation that cannot edit can do
/// nothing with them. Everything else — what counts as new, how much is too
/// much — is decided by the ledger in [`crate::lsp_servers`], which only ever
/// hands back problems this conversation has not already been shown. A notice
/// is a card in the transcript, so each block is sent once, where it arrived,
/// and never again.
fn inject_lsp_diagnostics(request: &mut RunModelRequest, state: &AppState) {
    if !request
        .enabled_tools
        .iter()
        .any(|name| name == "write" || name == "edit")
    {
        return;
    }
    let files = state
        .lsp_servers
        .take_new_diagnostics(&request.conversation_id);
    if files.is_empty() {
        return;
    }
    request.host_notices.push(crate::model::HostNotice {
        kind: crate::wire_history::notice_kind::DIAGNOSTICS,
        summary: request
            .prompt_profile
            .text(PromptKey::HostNoticeDiagnosticsSummary)
            .to_owned(),
        body: crate::lsp_servers::render_diagnostics(&files),
        id: None,
    });
}

/// Claude Code's `PXe`: characters of changed-region snippet per file.
const FILE_CHANGE_SNIPPET_CHARS: usize = 8_192;
/// Claude Code's `bRs`: characters of snippet per scan, after which a changed
/// file is still announced but its diff is omitted.
const FILE_CHANGE_SNIPPET_BUDGET: usize = 16_384;
/// Claude Code's `H7` context radius for those snippets.
const FILE_CHANGE_DIFF_CONTEXT: usize = 8;
/// The most text the scan re-reads for one file, the `read` tool's own limit.
const FILE_CHANGE_MAX_TEXT_BYTES: u64 = 2 * 1024 * 1024;

/// Queues one file-change notice block: an external change to a file the
/// model read, or a hook's rewrite of a file it just wrote. The record was
/// refreshed when the notice was made, so the next scan is silent about the
/// same change.
fn push_file_change_block(request: &mut RunModelRequest, content: String) {
    request.host_notices.push(crate::model::HostNotice {
        kind: crate::wire_history::notice_kind::FILE_CHANGES,
        summary: request
            .prompt_profile
            .text(PromptKey::HostNoticeFileChangesSummary)
            .to_owned(),
        body: content,
        id: None,
    });
}

/// Claude Code's `changed_files` scan: every full record whose file changed on
/// disk since is re-read, its record refreshed, and the model told what moved.
/// A file that disappeared is forgotten without a word, as the source does.
fn inject_file_change_notices(request: &mut RunModelRequest, state: &AppState) {
    let notices = {
        let guard = file_guard_context(request, state);
        scan_changed_files(
            &guard,
            Path::new(&request.workspace_path),
            &request.prompt_profile,
        )
    };
    if notices.is_empty() {
        return;
    }
    push_file_change_block(request, notices.join("\n\n"));
}

fn scan_changed_files(
    guard: &tool_executor::FileGuardContext<'_>,
    workspace: &Path,
    profile: &PromptProfile,
) -> Vec<String> {
    let mut budget = FILE_CHANGE_SNIPPET_BUDGET;
    let mut notices = Vec::new();
    for (path, record) in guard.registry.full_records(guard.scope) {
        // A file on another machine cannot be stat'ed from here, and a failed
        // stat must not read as "deleted": the record is what lets the next
        // remote edit go through, and only that machine can say whether the
        // file moved on.
        if crate::file_read_state::is_remote_key(&path) {
            continue;
        }
        let Some(disk_ms) = crate::file_read_state::modified_ms(&path) else {
            guard.registry.forget(guard.scope, &path);
            continue;
        };
        if disk_ms <= record.modified_ms {
            continue;
        }
        // Unreadable now — binary, gone between the two stats, over the limit —
        // is skipped the way the source skips a file its `read` refuses.
        let Some(text) = read_text_bounded(&path) else {
            continue;
        };
        let normalized = crate::file_read_state::normalize_text(&text);
        if record.matches(&normalized) {
            // Touched but not changed: only the time moves.
            guard.registry.record(
                guard.scope,
                path,
                crate::file_read_state::FileReadRecord {
                    modified_ms: disk_ms,
                    ..record
                },
            );
            continue;
        }
        let snippet = record
            .content
            .as_deref()
            .map(|before| changed_region_snippet(before, &normalized))
            .unwrap_or_default();
        guard.registry.record(
            guard.scope,
            path.clone(),
            crate::file_read_state::FileReadRecord::full_read(disk_ms, normalized),
        );
        let display = tool_executor::display_recorded_path(workspace, &path);
        if snippet.is_empty() || snippet.len() > budget {
            notices.push(profile.render(PromptKey::ToolFileChangedOmitted, &[("path", &display)]));
            continue;
        }
        budget -= snippet.len();
        notices.push(profile.render(
            PromptKey::ToolFileChangedNotice,
            &[("path", &display), ("snippet", &snippet)],
        ));
    }
    notices
}

fn read_text_bounded(path: &Path) -> Option<String> {
    let metadata = std::fs::metadata(path).ok()?;
    if !metadata.is_file() || metadata.len() > FILE_CHANGE_MAX_TEXT_BYTES {
        return None;
    }
    String::from_utf8(std::fs::read(path).ok()?).ok()
}

/// The changed regions between two texts, each line numbered the way `cat -n`
/// would show it — the source's `wZt`: context around every hunk, hunks
/// separated by `...`, cut at the per-file cap with a note of what was left out.
fn changed_region_snippet(before: &str, after: &str) -> String {
    let diff = similar::TextDiff::from_lines(before, after);
    let mut lines = Vec::new();
    for (index, group) in diff.grouped_ops(FILE_CHANGE_DIFF_CONTEXT).iter().enumerate() {
        if index > 0 {
            lines.push("...".to_owned());
        }
        for op in group {
            for change in diff.iter_changes(op) {
                let (sign, number) = match change.tag() {
                    similar::ChangeTag::Equal => (' ', change.new_index()),
                    similar::ChangeTag::Insert => ('+', change.new_index()),
                    similar::ChangeTag::Delete => ('-', change.old_index()),
                };
                let number = number.map_or(0, |index| index + 1);
                let text = change.value();
                lines.push(format!(
                    "{sign}{number:>6}\t{}",
                    text.strip_suffix('\n').unwrap_or(text)
                ));
            }
        }
    }
    let mut rendered = String::new();
    let mut shown = 0usize;
    for line in &lines {
        if rendered.len() + line.len() + 1 > FILE_CHANGE_SNIPPET_CHARS {
            break;
        }
        if !rendered.is_empty() {
            rendered.push('\n');
        }
        rendered.push_str(line);
        shown += 1;
    }
    if shown < lines.len() {
        rendered.push_str(&format!(
            "\n... [{} lines truncated] ...",
            lines.len() - shown
        ));
    }
    rendered
}

/// Commits what a guarded file tool reported once the call's result is final.
///
/// A `read` is recorded only when it succeeded: a result a PostToolUse hook
/// replaced never reached the model. A `write`/`edit` recorded itself in the
/// executor, so here it is only re-checked against the disk when a hook ran —
/// the source's `vln` re-sync, which is what keeps a formatter hook from
/// turning the model's next edit into a stale-file error.
fn settle_file_guard_touch(
    request: &mut RunModelRequest,
    execution: &ToolExecution,
    touch: Option<tool_executor::FileGuardTouch>,
    post_tool_hook_ran: bool,
    state: &AppState,
) {
    let Some(touch) = touch else {
        return;
    };
    if !execution.result.success {
        return;
    }
    let notice = {
        let guard = file_guard_context(request, state);
        match touch.read {
            Some(record) => {
                guard.registry.record(guard.scope, touch.path, record);
                None
            }
            None if post_tool_hook_ran => {
                resync_written_file(
                    &guard,
                    &touch.path,
                    Path::new(&request.workspace_path),
                    &request.prompt_profile,
                )
            }
            None => None,
        }
    };
    if let Some(notice) = notice {
        push_file_change_block(request, notice);
    }
}

/// Re-reads a just-written file whose time moved after the PostToolUse hooks
/// ran. Returns the notice for the model when the text actually changed; a
/// hook that only touched the time refreshes the record silently.
fn resync_written_file(
    guard: &tool_executor::FileGuardContext<'_>,
    path: &Path,
    workspace: &Path,
    profile: &PromptProfile,
) -> Option<String> {
    let record = guard.registry.get(guard.scope, path)?;
    let disk_ms = crate::file_read_state::modified_ms(path)?;
    if disk_ms <= record.modified_ms {
        return None;
    }
    let text = read_text_bounded(path)?;
    let normalized = crate::file_read_state::normalize_text(&text);
    if record.matches(&normalized) {
        guard.registry.record(
            guard.scope,
            path.to_path_buf(),
            crate::file_read_state::FileReadRecord {
                modified_ms: disk_ms,
                ..record
            },
        );
        return None;
    }
    // The disk is known again, but the model's copy is the pre-hook text.
    guard.registry.record(
        guard.scope,
        path.to_path_buf(),
        crate::file_read_state::FileReadRecord::written(disk_ms, normalized, false),
    );
    Some(profile.render(
        PromptKey::ToolHookFileResynced,
        &[("path", &tool_executor::display_recorded_path(workspace, path))],
    ))
}

/// Tells the language server holding a file that the model just changed it.
///
/// Only when a server is already running: an edit is not a reason to pay a cold
/// `rust-analyzer` start, and reading two configuration files off disk for
/// every `write` would be a cost every conversation pays whether or not it uses
/// code navigation at all.
///
/// A file on another machine is recognized by the record the remote leg took
/// for it — its key carries the machine and the canonical path there — and the
/// registry is asked whether a live server on that machine holds it before
/// anything crosses the transport again.
fn note_lsp_file_change(
    request: &RunModelRequest,
    execution: &ToolExecution,
    touch: Option<&tool_executor::FileGuardTouch>,
    state: &AppState,
) {
    if !execution.result.success
        || !matches!(execution.call.name.as_str(), "write" | "edit")
        || !state.lsp_servers.has_running_servers()
    {
        return;
    }
    if let Some((machine_key, canonical)) =
        touch.and_then(|touch| crate::file_read_state::remote_key_parts(&touch.path))
    {
        // The workspace the call named is the machine whose shell can read the
        // file back; the record's machine key is checked against it so a stale
        // touch can never send one machine's path to another's shell.
        let workspace = tool_executor::workspace_argument(&execution.call.input)
            .ok()
            .and_then(|index| request.workspaces.select(index).ok())
            .filter(|workspace| {
                crate::run_environment::env_key(workspace.machine.as_ref()) == machine_key
            });
        let Some(workspace) = workspace else {
            return;
        };
        let runner = workspace.runner.clone();
        let canonical = canonical.to_owned();
        state.lsp_servers.notify_remote_file_changed(
            machine_key,
            Path::new(&canonical),
            &request.conversation_id,
            &|| crate::remote_lsp::read_text(&runner, &canonical),
        );
        return;
    }
    let Some(path) = execution.call.input.get("path").and_then(Value::as_str) else {
        return;
    };
    // The workspace the call named, when it is a second local checkout: the
    // file was resolved in it, and its `.mework/lsp.json` is the one that
    // names the server holding the file.
    let selected = tool_executor::workspace_argument(&execution.call.input)
        .ok()
        .and_then(|index| request.workspaces.select(index).ok())
        .filter(|workspace| workspace.is_local())
        .map(|workspace| workspace.root.clone())
        .unwrap_or_else(|| request.workspace_path.clone());
    let workspace = Path::new(&selected);
    let configs =
        crate::lsp_config::servers_for_workspace(workspace, request.prompt_profile.language);
    let resolved = crate::lsp::resolved_workspace_path(workspace, path);
    state.lsp_servers.notify_file_changed(
        &configs,
        workspace,
        &resolved,
        &request.conversation_id,
    );
}

/// Routes one host-minted delivery card to the carriers that owe it.
///
/// The card rides the pending tool results when there are any, and otherwise
/// enters the canonical contexts at its timeline spot. Never both: a branch
/// that discards the live exchanges syncs `generated` in the same step, which
/// would deliver it twice.
fn deliver_host_card(
    context: ContextItem,
    exchanges: &mut [Exchange],
    request_contexts: &mut Vec<ContextItem>,
    generated: &mut Vec<ContextItem>,
) {
    let mut rode_along = false;
    if let Some(delivery) = crate::wire_history::host_task_delivery(&context) {
        if let Some(exchange) = exchanges
            .iter_mut()
            .rev()
            .find(|exchange| !exchange.executions.is_empty())
        {
            exchange.host_deliveries.push(delivery);
            rode_along = true;
        }
    }
    if !rode_along {
        request_contexts.push(context.clone());
    }
    generated.push(context);
}

/// Shows the renderer what the host just added to the transcript ahead of
/// `round`, in transcript order.
///
/// These cards have no stream of their own: without this the live turn only
/// learns of them when it settles, so a notice the model is already acting on
/// — auto-compact arming, a background result — stays off screen for the
/// whole turn. They are persisted already, so a dead sink costs only the live
/// view; the settled turn still carries them.
fn announce_host_contexts(event_sink: &ModelEventSink<'_>, round: usize, contexts: &[ContextItem]) {
    for context in contexts {
        let _ = event_sink(ModelStreamEvent::HostContextAdded {
            round,
            context: Box::new(context.clone()),
        });
    }
}

/// Mints one host `box` delivery card.
///
/// The card is exactly the exchange the model reads: the call carries the one
/// empty argument `box` takes (`wire_history::box_call_input`) and the result
/// is the whole message, `<task-notification>` and all. The timeline shows that
/// text, an edit changes that text, and replay sends that text — nothing is
/// rebuilt from bookkeeping on the way out. `notice` names a host notice for
/// the renderer and the host; it never reaches the wire.
fn box_delivery_card(
    state: &AppState,
    conversation_id: &str,
    id: String,
    round: usize,
    notice: Option<&str>,
    message: String,
) -> ContextItem {
    debug_assert!(id.starts_with(AGENT_RESULT_CONTEXT_ID_PREFIX));
    let input = crate::wire_history::box_call_input();
    // Collection succeeds even when a child ended failed or at round limit,
    // just as `task_wait` returns a failed result with `success: true`.
    let result = ToolResult {
        success: true,
        output: message,
        images: Vec::new(),
        diff: None,
        executed_at: Utc::now().to_rfc3339(),
        duration_ms: 0,
    };
    // This host-issued card is renderer-validated on save; an empty token would
    // be isolated as a renderer forgery.
    let attestation = state.attest_tool_context(&crate::tool_attestation::AttestationSubject {
        conversation_id,
        context_id: &id,
        tool_name: BOX_TOOL,
        input: &input,
        requested_input: None,
        result: &result,
        subagent: None,
    });
    ContextItem::Tool {
        id,
        tool_name: BOX_TOOL.to_owned(),
        // No `model_turn_id`: host collection belongs to no model round. The
        // renderer and wire projection recognize the host-collected card by id.
        round: Some(round),
        model_turn_id: None,
        // The host issued this call, so there is no provider id to keep; both
        // legs mint the same digest from the card's own id.
        provider_call_id: None,
        requested_input: None,
        input,
        result,
        subagent: None,
        notice: notice.map(str::to_owned),
        attestation,
        created_at: Utc::now().to_rfc3339(),
    }
}

/// Mints one host notice as a signed `box` delivery card: the same carrier,
/// the same `<task-notification>` and the same identity a background result
/// has, so everything the host says between rounds reaches the model in one
/// form and at the end of the transcript.
fn host_notice_card(
    request: &RunModelRequest,
    state: &AppState,
    round: usize,
    notice: crate::model::HostNotice,
) -> ContextItem {
    let id = notice
        .id
        .unwrap_or_else(|| new_context_id("agent-result"));
    box_delivery_card(
        state,
        &request.conversation_id,
        id,
        round,
        Some(notice.kind),
        crate::wire_history::host_notice_notification(&notice.summary, &notice.body),
    )
}

/// Hands every queued host notice over as a `box` card.
///
/// Runs at the loop head, where the previous round's exchange is complete: a
/// notice queued in the middle of a tool batch (a hook, a rewritten file)
/// therefore rides behind that batch's results rather than splitting the
/// model's turn, and one queued before the first round takes its own timeline
/// spot. A notice with a fixed id that the conversation already holds is
/// dropped — that id is the promise to deliver it once.
fn deliver_host_notices(
    request: &mut RunModelRequest,
    state: &AppState,
    round: usize,
    exchanges: &mut [Exchange],
    generated: &mut Vec<ContextItem>,
) {
    for notice in std::mem::take(&mut request.host_notices) {
        if let Some(id) = notice.id.as_deref() {
            if request.contexts.iter().any(|context| context.id() == id) {
                continue;
            }
        }
        let card = host_notice_card(request, state, round, notice);
        // A message, not a result: it owes the kernel nothing, so no shadow
        // event goes with it.
        deliver_host_card(card, exchanges, &mut request.contexts, generated);
    }
}

/// Appends the tools this request offers that the previous one did not.
///
/// They are not written into the declared tool list, which heads the prompt
/// and would take the whole prompt cache with it; a marker records that they
/// joined here instead, and the protocol's own append interface hands them to
/// the model at this point (`tool_append.rs`). The marker rides the pending
/// tool results when there are any, like a delivery card, so the live request
/// and every replay of the timeline put it in the same place.
fn append_new_tools(
    request: &mut RunModelRequest,
    offered: &mut Option<BTreeSet<String>>,
    exchanges: &mut [Exchange],
    generated: &mut Vec<ContextItem>,
) {
    let names = crate::aisdk::tools::enabled_tools(request)
        .into_iter()
        .map(|tool| tool.name.clone())
        .collect::<Vec<_>>();
    let appended = crate::tool_append::appended(request.contexts.iter().chain(generated.iter()));
    let added = crate::tool_append::newly_offered(&names, offered.as_ref(), &appended);
    *offered = Some(names.into_iter().collect());
    if added.is_empty() {
        return;
    }
    let marker = crate::tool_append::marker(
        new_context_id(crate::tool_append::CONTEXT_KIND),
        added.clone(),
        Utc::now().to_rfc3339(),
    );
    match exchanges
        .iter_mut()
        .rev()
        .find(|exchange| !exchange.executions.is_empty())
    {
        Some(exchange) => exchange.tool_additions.push(added),
        None => request.contexts.push(marker.clone()),
    }
    generated.push(marker);
}

/// Brings what the model was last told about plan mode in line with the switch
/// (`plan_mode.rs`).
///
/// The transcript is the record of what the model was told: the latest
/// plan-mode instruction, or an approved plan. Switched on since, the
/// guidance is added here; switched off by hand, the note that plan mode
/// ended. Each enabling adds the guidance again, but the plan tools join
/// only once — `plan_tools` stays set, so `append_new_tools` right after this
/// finds the pair new exactly the first time.
fn reconcile_plan_mode(
    request: &mut RunModelRequest,
    state: &AppState,
    round: usize,
    previously_offered: Option<&BTreeSet<String>>,
    exchanges: &mut [Exchange],
    generated: &mut Vec<ContextItem>,
) {
    if request.subagent_depth > 0 {
        return;
    }
    let active = request.plan_mode_active();
    if active {
        request.plan_tools = true;
    }
    let told = crate::plan_mode::transcript_in_plan_mode(
        request.contexts.iter().chain(generated.iter()),
    );
    let instruction = match (active, told) {
        (true, false) => Instruction {
            topic: crate::plan_mode::ENTER_TOPIC,
            notice_kind: crate::plan_mode::ENTER_NOTICE_KIND,
            summary: request.prompt_profile.text(PromptKey::HostNoticePlanModeSummary).to_owned(),
            notice_id: None,
            content: request.prompt_profile.text(PromptKey::SystemPlanMode).trim().to_owned(),
        },
        (false, true) => Instruction {
            topic: crate::plan_mode::EXIT_TOPIC,
            notice_kind: crate::plan_mode::EXIT_NOTICE_KIND,
            summary: request
                .prompt_profile
                .text(PromptKey::HostNoticePlanModeExitSummary)
                .to_owned(),
            notice_id: None,
            content: request.prompt_profile.text(PromptKey::SystemPlanModeExit).trim().to_owned(),
        },
        _ => return,
    };
    if instruction.content.is_empty() {
        return;
    }
    deliver_instruction(request, state, round, previously_offered, exchanges, generated, instruction);
}

/// Hands a continuation the notebook index it inherited (`handoff.rs`), once,
/// at its first round boundary, behind the opening message and whatever the
/// host delivered there. Only where the index is not already in the system
/// prompt: on a model that reads its system prompt ahead of its tools, the
/// handoff left it out of the timeline so it could go in here instead.
fn deliver_handoff_index(
    request: &mut RunModelRequest,
    state: &AppState,
    round: usize,
    previously_offered: Option<&BTreeSet<String>>,
    exchanges: &mut [Exchange],
    generated: &mut Vec<ContextItem>,
) {
    let Some(index) = crate::handoff::owed_index(request, generated.iter()) else {
        return;
    };
    let instruction = Instruction {
        topic: crate::handoff::INDEX_TOPIC,
        notice_kind: crate::handoff::INDEX_NOTICE_KIND,
        summary: request.prompt_profile.text(PromptKey::HandoffIndexSummary).to_owned(),
        notice_id: Some(crate::handoff::INDEX_NOTICE_ID.to_owned()),
        content: index,
    };
    deliver_instruction(request, state, round, previously_offered, exchanges, generated, instruction);
}

/// An instruction the host adds partway through a conversation, in both the
/// forms it can take (`host_append.rs`).
struct Instruction {
    /// Its topic as an appended system prompt (`system_append::card`).
    topic: &'static str,
    /// Its `kind` and `<summary>` as a host notice in `box`.
    notice_kind: &'static str,
    summary: String,
    /// The card id an instruction given at most once takes in `box`; `None`
    /// mints a fresh one.
    notice_id: Option<String>,
    content: String,
}

/// Adds `instruction` by the carrier this request has for one: an appended
/// system prompt where the model and endpoint take a system message here, a
/// `box` notice where they do not. Either rides the pending tool results when
/// there are any, so the live request and every replay put it in the same
/// place.
fn deliver_instruction(
    request: &mut RunModelRequest,
    state: &AppState,
    round: usize,
    previously_offered: Option<&BTreeSet<String>>,
    exchanges: &mut [Exchange],
    generated: &mut Vec<ContextItem>,
    instruction: Instruction,
) {
    match crate::host_append::instruction_carrier(request, previously_offered) {
        crate::host_append::InstructionCarrier::Box => {
            let notice = crate::model::HostNotice {
                kind: instruction.notice_kind,
                summary: instruction.summary,
                body: instruction.content,
                id: instruction.notice_id,
            };
            let card = host_notice_card(request, state, round, notice);
            deliver_host_card(card, exchanges, &mut request.contexts, generated);
        }
        // The last resort lands here too: the sidecar lifts the card into the
        // system prompt, the one place left.
        crate::host_append::InstructionCarrier::SystemAppend
        | crate::host_append::InstructionCarrier::SystemPrompt => {
            let content = instruction.content;
            let card =
                crate::system_append::card(instruction.topic, content.clone(), Utc::now().to_rfc3339());
            match exchanges
                .iter_mut()
                .rev()
                .find(|exchange| !exchange.executions.is_empty())
            {
                Some(exchange) => exchange.system_appends.push(content),
                None => request.contexts.push(card.clone()),
            }
            generated.push(card);
        }
    }
}

/// A notice that is transient by design: the continue-after-truncation nudge
/// lives only in the live exchange it follows, because the round's fragments
/// settle as one assistant card and the nudge between them has no timeline
/// spot to keep. It still travels as a `box` exchange, the form every other
/// host message has.
fn transient_host_delivery(
    request: &RunModelRequest,
    state: &AppState,
    round: usize,
    notice: crate::model::HostNotice,
) -> Option<crate::wire_history::HostDelivery> {
    crate::wire_history::host_task_delivery(&host_notice_card(request, state, round, notice))
}

/// S9: folds terminal results no `task_wait` drained into the parent's
/// timeline, pushed into BOTH sinks — the model sees them at its next round,
/// and they persist at their true chronological position, deletable and
/// replayable like any other context. One-shot per envelope:
/// `take_undelivered_results` removes under the core mutex, so a concurrent or
/// later `task_wait` can never deliver the same result twice, and a replayed
/// timeline carries the delivery as plain persisted history rather than
/// re-running the fold.
///
/// A task result is a host-synthesized `box` tool context, not user input. On
/// the wire it is a fabricated `box` exchange appended after real same-round
/// tool results when possible, otherwise projected at its canonical timeline
/// position. Both paths use `wire_history::host_task_delivery` to keep protocol
/// bytes equal.
///
/// The card itself reaches the live turn through the loop head's
/// `announce_host_contexts`, with everything else delivered at the boundary.
/// An adopted task from an earlier idle round needs a best-effort terminal status
/// delta because its spawn card is outside this run's generated contexts and record
/// backfill cannot reach it.
#[allow(clippy::too_many_arguments)]
fn fold_undrained_agent_results(
    pool: &AgentPool,
    shadow: &crate::kernel_shadow::KernelShadow,
    event_sink: &ModelEventSink<'_>,
    round: usize,
    conversation_id: &str,
    state: &AppState,
    profile: &PromptProfile,
    exchanges: &mut [Exchange],
    request_contexts: &mut Vec<ContextItem>,
    generated: &mut Vec<ContextItem>,
) {
    for mut envelope in pool.take_undelivered_results() {
        // Every terminal result is delivered, whatever ended the task. A task
        // the user closed from the sidebar reports what it produced through the
        // same host-synthesized `box` card as one that finished on its own.
        shadow.agent_folded(&envelope.agent, envelope.identity);
        // Address the status delta by stable spawn call id. Sink failure is benign:
        // persistence is authoritative and reload restores the renderer state.
        if let Some(shared) = pool.find(&envelope.agent) {
            let call_id = shared.latest_call_id();
            if !call_id.is_empty() {
                let _ = event_sink(ModelStreamEvent::SubagentDelta {
                    round,
                    call_id,
                    channel: SubagentChannel::Status,
                    delta: shared.status().wire().into(),
                });
            }
        }
        // Display task addresses rather than internal pool names so shell and
        // workflow results remain recognizable to the model.
        let managed = pool.find(&envelope.agent).and_then(|shared| {
            matches!(
                shared.kind,
                SubagentRunKind::ShellCommand | SubagentRunKind::WorkflowStep
            )
            .then(|| shared.label.clone())
        });
        if let Some(label) = managed {
            envelope.agent = label;
        }
        let crate::agents::EnvelopeKind::Result(status) = envelope.kind else {
            unreachable!("the fold claims terminal Result envelopes only");
        };
        let output = orchestration::format_undrained_result_notification(&envelope, profile);
        let message = crate::wire_history::task_notification(
            &envelope.agent,
            orchestration::task_status_wire(status),
            &orchestration::task_notification_summary(&envelope.agent, status, profile),
            &output,
            orchestration::task_notification_usage(envelope.metrics.as_ref()),
        );
        let context = box_delivery_card(
            state,
            conversation_id,
            new_context_id("agent-result"),
            round,
            None,
            message,
        );
        deliver_host_card(context, exchanges, request_contexts, generated);
    }
}

/// Deliver startup-recovered interrupted-workflow notifications at a round boundary
/// as host-synthesized `task_wait` cards. They use the same wire notification path
/// as fold but emit no shadow event because the task belongs to a prior process.
/// Report them as `failed`, not user-stop interruption, and clear manifest accounting
/// only after `generated.checkpoint()` confirms delivery.
fn fold_workflow_restart_notices(
    profile: &PromptProfile,
    round: usize,
    conversation_id: &str,
    state: &AppState,
    exchanges: &mut [Exchange],
    request_contexts: &mut Vec<ContextItem>,
    generated: &mut Vec<ContextItem>,
) -> Vec<(String, String)> {
    let mut delivered = Vec::new();
    for notice in state.take_workflow_restart_notices(conversation_id) {
        let label = format!("workflow:{}", notice.run_id);
        let summary = profile.render(PromptKey::WorkflowRestartSummary, &[("task", &label)]);
        let output = profile.render(
            PromptKey::WorkflowRestartNotice,
            &[
                ("task", &label),
                ("script", &notice.script_name),
                ("reusable_steps", &notice.reusable_steps.to_string()),
                ("run_id", &notice.run_id),
            ],
        );
        let message = crate::wire_history::task_notification(
            &label,
            orchestration::task_status_wire(crate::model::SubagentRunStatus::Failed),
            &summary,
            &output,
            None,
        );
        let context = box_delivery_card(
            state,
            conversation_id,
            new_context_id("agent-result"),
            round,
            None,
            message,
        );
        deliver_host_card(context, exchanges, request_contexts, generated);
        delivered.push((notice.conversation_id.clone(), notice.run_id.clone()));
    }
    delivered
}

/// Delivers the startup-claimed subagents the previous process lost before their results reached
/// the model, through the same round-boundary window as fold. Returns the agent names whose ledger
/// entries may be settled once `generated.checkpoint()` confirms this boundary.
///
/// Each entry ends one of three ways, and none of them reads the timeline, which is the user's to
/// edit:
///
/// - The history shows a request carrying the agent's result to the model. The entry outlived a
///   delivery whose confirmation the crash cut off, and it is settled without a word.
/// - Startup found the agent's final reply in the history ([`LostSubagent::recovered`]).
///   The agent finished; it is delivered as the `completed` result a fold would have carried. Its
///   card already holds the reply ([`reattach_recovered_subagent`]), and nothing woke the model
///   for it: it rides whatever run comes next.
/// - Otherwise the agent died mid-work, and the model gets a `failed` notice, which wakes like any
///   other failure, carrying the last text the agent wrote as the history received it.
///
/// [`LostSubagent::recovered`]: crate::subagent_ledger::LostSubagent::recovered
#[allow(clippy::too_many_arguments)]
fn fold_subagent_restart_notices(
    profile: &PromptProfile,
    round: usize,
    conversation_id: &str,
    app_data_path: &str,
    state: &AppState,
    exchanges: &mut [Exchange],
    request_contexts: &mut Vec<ContextItem>,
    generated: &mut Vec<ContextItem>,
) -> Vec<String> {
    let lost = state.take_subagent_restart_notices(conversation_id);
    if lost.is_empty() {
        return Vec::new();
    }
    // Without the history there is nothing to rule a delivery in, so every entry is reported:
    // a duplicate notice beats a silent loss.
    let history = crate::history::history_store(app_data_path).ok();
    let mut settled = Vec::new();
    for lost in lost {
        let name = lost.name;
        if history
            .as_deref()
            .is_some_and(|store| agent_result_reached_model(store, conversation_id, &name, profile))
        {
            settled.push(name);
            continue;
        }
        let (status, summary, output) = match lost.recovered {
            Some(reply) => {
                let content = orchestration::subagent_result_output(&reply.text, profile);
                (
                    crate::model::SubagentRunStatus::Completed,
                    orchestration::task_notification_summary(
                        &name,
                        crate::model::SubagentRunStatus::Completed,
                        profile,
                    ),
                    orchestration::format_recovered_result_notification(
                        &name,
                        &content,
                        reply.structured_output.as_ref(),
                        profile,
                    ),
                )
            }
            None => {
                let last_output = history
                    .as_deref()
                    .and_then(|store| {
                        crate::subagent_ledger::last_received_text(store, conversation_id, &name)
                    })
                    .map_or_else(
                        || profile.text(PromptKey::TaskRestartNoOutput).to_owned(),
                        |text| profile.render(PromptKey::TaskRestartLastOutput, &[("text", &text)]),
                    );
                (
                    crate::model::SubagentRunStatus::Failed,
                    profile.render(PromptKey::TaskRestartSummary, &[("task", &name)]),
                    orchestration::truncate_agent_output(
                        &profile.render(
                            PromptKey::TaskRestartNotice,
                            &[("task", &name), ("last_output", &last_output)],
                        ),
                        profile,
                    ),
                )
            }
        };
        let message = crate::wire_history::task_notification(
            &name,
            orchestration::task_status_wire(status),
            &summary,
            &output,
            None,
        );
        let context = box_delivery_card(
            state,
            conversation_id,
            new_context_id("agent-result"),
            round,
            None,
            message,
        );
        deliver_host_card(context, exchanges, request_contexts, generated);
        settled.push(name);
    }
    settled
}

/// Whether the history shows the model receiving a result for agent `name`: a request carrying a host
/// delivery addressed to it (a fold, or an earlier restart notice), or a `task_wait` whose output
/// holds its result section — `[name · <status>]`, as opposed to a `[name · <progress label>]`
/// update. A failed read counts as no delivery.
///
/// Only a request can answer this: what the model received is what went out, and a result the host
/// produced reaches the model when a request carries it, not before.
fn agent_result_reached_model(
    store: &crate::conversation_store::ConversationStore,
    conversation_id: &str,
    name: &str,
    profile: &PromptProfile,
) -> bool {
    use crate::history::RecordedToolPart;
    let Ok(bodies) = store.history_message_bodies(conversation_id, None, Some("tool"), name) else {
        return false;
    };
    let delivery = format!("<task-id>{name}</task-id>");
    let section = format!("[{name} · ");
    let update = format!(
        "[{name} · {}]",
        profile.text(PromptKey::TaskProgressUpdateLabel)
    );
    bodies.iter().any(|body| {
        crate::history::recorded_tool_parts(body)
            .into_iter()
            .any(|part| match part {
                RecordedToolPart::Result {
                    name: tool, text, ..
                } if tool == BOX_TOOL => text.contains(&delivery),
                RecordedToolPart::Result {
                    name: tool, text, ..
                } if tool == "task_wait" => text
                    .lines()
                    .any(|line| line.starts_with(&section) && !line.starts_with(&update)),
                _ => false,
            })
    })
}

/// Puts a recovered final reply back on the agent's card at startup, before anything reads the
/// conversation: the record's status becomes `completed`, it gains the schema-bound value, and
/// the reply joins its transcript under the id the child's own round would have given it — so a
/// record that already holds it (the parent backfilled it before the crash) is left as it is.
///
/// A child's transcript is only checkpointed at its round boundaries, and its final round has no
/// boundary after it: until the parent backfills the record, the reply exists nowhere but the
/// history. A child that settled in its first round never had a record written at all; the
/// one its spawn left in the ledger entry is written onto the spawn card instead.
///
/// Returns whether the card now holds the reply. It is re-signed like every record the host
/// writes, and superseded holders of the name lose theirs, as the running checkpoint does.
pub(crate) fn reattach_recovered_subagent(
    store: &crate::conversation_store::ConversationStore,
    state: &AppState,
    lost: &crate::subagent_ledger::LostSubagent,
) -> bool {
    let Some(reply) = lost.recovered.as_ref() else {
        return false;
    };
    let owner = match store.task_card_owner(
        &lost.conversation_id,
        &lost.name,
        lost.spawn_call_id.as_deref(),
    ) {
        Ok(Some(owner)) => owner,
        Ok(None) => return false,
        Err(error) => {
            eprintln!("找不到子代理 {} 的卡片，最终回复未接回：{error}", lost.name);
            return false;
        }
    };
    let reply_id = round_identity(&reply.request_id, reply.round, "assistant");
    let revised =
        store.update_task_cards_in_place(&lost.conversation_id, &owner, &lost.name, |card| {
            let is_owner = card.id() == owner;
            let ContextItem::Tool { subagent, .. } = card else {
                return false;
            };
            if !is_owner {
                *subagent = None;
                re_attest_tool_context(card, &lost.conversation_id, state);
                return true;
            }
            let Some(mut record) = subagent.clone().or_else(|| lost.record.clone()) else {
                return false;
            };
            if record.name.as_deref() != Some(lost.name.as_str()) {
                return false;
            }
            record.status = crate::model::SubagentRunStatus::Completed;
            if reply.structured_output.is_some() {
                record.structured_output = reply.structured_output.clone();
            }
            let present = reply_id
                .as_deref()
                .is_some_and(|id| record.contexts.iter().any(|context| context.id() == id));
            if !present && !reply.text.trim().is_empty() {
                record.contexts.push(ContextItem::Assistant {
                    id: reply_id
                        .clone()
                        .unwrap_or_else(|| new_context_id("assistant")),
                    content: reply.text.clone(),
                    round: Some(reply.round),
                    model_turn_id: None,
                    interrupted: false,
                    sources: Vec::new(),
                    created_at: Utc::now().to_rfc3339(),
                });
            }
            *subagent = Some(record);
            re_attest_tool_context(card, &lost.conversation_id, state);
            true
        });
    match revised {
        Ok(revised) => revised,
        Err(error) => {
            eprintln!("子代理 {} 的最终回复未能接回卡片：{error}", lost.name);
            false
        }
    }
}

/// Settles the ledger entries of top-level agents whose results the model now holds durably. Call
/// only after a confirmed `generated.checkpoint()` on this run's thread: an agent that is no longer
/// running and has no result left in its outbox handed that result to a fold or a `task_wait` on
/// this same thread, and the confirmed checkpoint wrote the card that carried it.
fn settle_delivered_subagents(pool: &AgentPool, request: &RunModelRequest, state: &AppState) {
    if request.subagent_depth > 0 || request.app_data_path.is_empty() {
        return;
    }
    let delivered = state.take_ledgered_subagents(&request.conversation_id, |name| {
        pool.find(name).map_or(true, |agent| {
            agent.status() != AgentLiveStatus::Running && !agent.has_undrained_foldable_results()
        })
    });
    for name in delivered {
        crate::subagent_ledger::settle(
            Path::new(&request.app_data_path),
            &request.conversation_id,
            &name,
        );
    }
}

fn finalize_agent_pool(
    pool: &AgentPool,
    generated: &mut Vec<ContextItem>,
    usage: &mut ModelUsage,
    agent_context_ids: &HashMap<String, String>,
) {
    if pool.is_empty() {
        return;
    }
    for shared in pool.all() {
        // Order-independent by construction: `take_usage` empties the counter
        // that rolls into the parent total, while `record()` reads the parallel
        // never-taken `lifetime_usage`. Neither reads the other's value.
        merge_usage(usage, &shared.take_usage());
        // Running tasks survive rounds and receive no terminal record yet; mapping
        // them through `persisted()` would falsely mark live work interrupted.
        if shared.status() == crate::agents::AgentLiveStatus::Running {
            continue;
        }
        let latest_call_id = shared.latest_call_id();
        if latest_call_id.is_empty() {
            // Rehydrated this turn but never continued: the historical record
            // in the timeline is still authoritative.
            continue;
        }
        let Some(context_id) = agent_context_ids.get(&latest_call_id) else {
            continue;
        };
        let mut record = Some(shared.record());
        for context in generated.iter_mut().rev() {
            if let ContextItem::Tool {
                id,
                tool_name,
                subagent,
                ..
            } = context
            {
                if id == context_id
                    && matches!(
                        tool_name.as_str(),
                        // `web_search` does not backfill a subagent record. Its
                        // durable surface is the registry row and folded notification.
                        "agent_spawn" | "workflow"
                    )
                {
                    *subagent = record.take();
                    break;
                }
            }
        }
    }
}

/// Recomputes the durable attestation token of a tool card after the host
/// mutated its payload (today: attaching a terminal child record). The token
/// must always cover the exact projected payload the renderer stores and hands
/// back; leaving the mint-time token in place made every record-bearing card
/// depend on the bounded process-local receipt book until its bytes stopped
/// changing.
fn re_attest_tool_context(context: &mut ContextItem, conversation_id: &str, state: &AppState) {
    if let ContextItem::Tool {
        id,
        tool_name,
        requested_input,
        input,
        result,
        subagent,
        attestation,
        ..
    } = context
    {
        *attestation = state.attest_tool_context(&crate::tool_attestation::AttestationSubject {
            conversation_id,
            context_id: id,
            tool_name,
            input,
            requested_input: requested_input.as_ref(),
            result,
            subagent: subagent.as_ref(),
        });
    }
}

/// Mints the process-local fallback receipt for a record-bearing card, so a
/// save issued before the re-attested card reaches the renderer still passes.
fn record_tool_context_subagent_receipt(
    conversation_id: &str,
    workspace_path: &str,
    context: &ContextItem,
    state: &AppState,
) {
    let ContextItem::Tool {
        tool_name,
        requested_input,
        input,
        result,
        subagent: Some(subagent),
        ..
    } = context
    else {
        return;
    };
    state.record_context_subagent_receipt(
        &ToolExecutionRequest {
            conversation_id: conversation_id.to_owned(),
            workspace_path: workspace_path.to_owned(),
            tool_name: tool_name.clone(),
            input: input.clone(),
        },
        result,
        requested_input.as_ref(),
        subagent,
    );
}

fn find_tool_context_mut<'a>(
    contexts: &'a mut [ContextItem],
    context_id: &str,
) -> Option<&'a mut ContextItem> {
    contexts
        .iter_mut()
        .rev()
        .find(|context| matches!(context, ContextItem::Tool { id, .. } if id == context_id))
}

/// Re-sign a card whose `subagent` record changed, backfill its receipt, and send
/// the complete card to the renderer.
fn publish_settled_card(
    card: &mut ContextItem,
    conversation_id: &str,
    workspace_path: &str,
    state: &AppState,
    event_sink: &ModelEventSink<'_>,
    round: usize,
) {
    re_attest_tool_context(card, conversation_id, state);
    record_tool_context_subagent_receipt(conversation_id, workspace_path, card, state);
    let _ = event_sink(ModelStreamEvent::ToolContextSettled {
        round,
        context: Box::new(card.clone()),
    });
}

/// Round-boundary record checkpoint. Backfill terminal task records into current
/// or historical agent/workflow cards, re-sign, and emit `ToolContextSettled` so
/// persistence occurs at the first boundary after task completion. Move each record
/// to only its latest call card to preserve the single-holder invariant and avoid
/// O(n²) transcript growth.
fn checkpoint_terminal_agent_records(
    pool: &AgentPool,
    conversation_id: &str,
    workspace_path: &str,
    state: &AppState,
    event_sink: &ModelEventSink<'_>,
    round: usize,
    request_contexts: &mut [ContextItem],
    generated: &mut [ContextItem],
    agent_context_ids: &HashMap<String, String>,
) -> Vec<ContextItem> {
    let mut updates = Vec::new();
    if pool.is_empty() {
        return updates;
    }
    for shared in pool.all() {
        // Shell pool entries are internal and do not backfill subagent records.
        if shared.kind == SubagentRunKind::ShellCommand {
            continue;
        }
        // Do not backfill live cross-round tasks: `persisted()` would incorrectly
        // map `Running` to `Interrupted`.
        if shared.status() == crate::agents::AgentLiveStatus::Running {
            continue;
        }
        let latest_call_id = shared.latest_call_id();
        if latest_call_id.is_empty() {
            continue;
        }
        let Some(context_id) = agent_context_ids
            .get(&latest_call_id)
            .cloned()
            .or_else(|| shared.latest_context_id())
        else {
            continue;
        };
        let Some(card) = find_tool_context_mut(generated, &context_id)
            .or_else(|| find_tool_context_mut(request_contexts, &context_id))
        else {
            continue;
        };
        let owns_record = matches!(
            &*card,
            ContextItem::Tool { tool_name, .. } if matches!(
                tool_name.as_str(),
                "agent_spawn" | "workflow"
            )
        );
        if !owns_record {
            continue;
        }
        let record = shared.record();
        let unchanged = matches!(
            &*card,
            ContextItem::Tool { subagent: Some(existing), .. } if *existing == record
        );
        if unchanged {
            continue;
        }
        let agent_name = record.name.clone();
        if let ContextItem::Tool { subagent, .. } = &mut *card {
            *subagent = Some(record);
        }
        publish_settled_card(
            card,
            conversation_id,
            workspace_path,
            state,
            event_sink,
            round,
        );
        updates.push(card.clone());
        let Some(agent_name) = agent_name else {
            continue;
        };
        let superseded = generated
            .iter()
            .chain(request_contexts.iter())
            .filter_map(|context| match context {
                ContextItem::Tool {
                    id,
                    subagent: Some(existing),
                    ..
                } if id != &context_id && existing.name.as_deref() == Some(agent_name.as_str()) => {
                    Some(id.clone())
                }
                _ => None,
            })
            .collect::<Vec<_>>();
        for stale_id in superseded {
            let Some(stale) = find_tool_context_mut(generated, &stale_id)
                .or_else(|| find_tool_context_mut(request_contexts, &stale_id))
            else {
                continue;
            };
            if let ContextItem::Tool { subagent, .. } = &mut *stale {
                *subagent = None;
            }
            publish_settled_card(
                stale,
                conversation_id,
                workspace_path,
                state,
                event_sink,
                round,
            );
            updates.push(stale.clone());
        }
    }
    updates
}

/// Attests the exact child-agent audit record only after the turn-scoped pool
/// has backfilled its final transcript and status. The ordinary per-execution
/// receipt is intentionally insufficient: otherwise the renderer could attach
/// or rewrite a child task, kind, transcript, update, or queued message before
/// saving the document.
///
/// The cards are also re-attested here: `finalize_agent_pool` mutated their
/// payload after the mint-time token was issued, and the durable token — not
/// the bounded process-local receipt book — is what lets the settled card
/// survive a restart-then-edit round trip.
fn record_generated_subagent_receipts(
    request: &RunModelRequest,
    generated: &mut [ContextItem],
    state: &AppState,
) {
    for context in generated.iter_mut() {
        let ContextItem::Tool {
            subagent: Some(_), ..
        } = context
        else {
            continue;
        };
        re_attest_tool_context(context, &request.conversation_id, state);
        record_tool_context_subagent_receipt(
            &request.conversation_id,
            &request.workspace_path,
            context,
            state,
        );
    }
}

fn hook_context_id(request_id: &str, execution_id: &str, purpose: &str, index: usize) -> String {
    format!("ctx_hook_{request_id}_{execution_id}_{purpose}_{index}")
}

fn hook_context(request_id: &str, execution: &HookExecution) -> ContextItem {
    let status = if execution.decision.blocked || execution.decision.halt {
        "blocked"
    } else if execution.result.success {
        "succeeded"
    } else {
        "failed"
    };
    let mut details = execution.result.output.clone();
    if let Some(message) = &execution.decision.system_message {
        details.push_str(&format!("\n\n[systemMessage]\n{message}"));
    }
    if let Some(reason) = &execution.decision.reason {
        details.push_str(&format!("\n\n[decision]\n{reason}"));
    }
    ContextItem::System {
        id: hook_context_id(request_id, &execution.execution_id, "display", 0),
        content: format!(
            "[生命周期钩子 · {} · {}]\nID：{}\n名称：{}\n耗时：{} ms\n\n{}",
            hooks::event_label(execution.event),
            status,
            execution.id,
            execution.name,
            execution.result.duration_ms,
            details
        ),
        local_only: true,
        hook_execution: Some(HookContextMetadata {
            execution_id: execution.execution_id.clone(),
            hook_id: execution.id.clone(),
            hook_name: execution.name.clone(),
            event: hooks::event_label(execution.event).into(),
            status: status.into(),
            context_injected: false,
        }),
        tools_added: Vec::new(),
        created_at: execution.result.executed_at.clone(),
    }
}

fn hook_input(request: &RunModelRequest, event: HookEvent, turn_id: &str, fields: Value) -> Value {
    // Plan mode is a tool switch, not a permission mode: hooks see the level.
    let permission_mode = match request.effective_security_level() {
        crate::model::SecurityLevel::RequestApproval => "default",
        crate::model::SecurityLevel::AllowEdits => "acceptEdits",
        crate::model::SecurityLevel::FullAccess => "bypassPermissions",
    };
    let mut input = serde_json::Map::from_iter([
        ("session_id".into(), json!(request.conversation_id)),
        ("transcript_path".into(), Value::Null),
        ("cwd".into(), json!(request.workspace_path.as_str())),
        ("hook_event_name".into(), json!(hooks::event_label(event))),
        ("model".into(), json!(request.model.id)),
        ("permission_mode".into(), json!(permission_mode)),
        ("turn_id".into(), json!(turn_id)),
    ]);
    if let Some(fields) = fields.as_object() {
        input.extend(fields.clone());
    }
    Value::Object(input)
}

fn instructions_loaded_dispatcher(
    request: &RunModelRequest,
    services: &HookRunServices<'_>,
    turn_id: &str,
) -> Option<InstructionsLoadedRunDispatcher> {
    if !request
        .active_hooks
        .iter()
        .any(|hook| hook.enabled && hook.event == HookEvent::InstructionsLoaded)
    {
        return None;
    }
    let workspace = Path::new(&request.workspace_path);
    let runner = hook_command_runner(request, services.cancellation.clone()).ok()?;
    let cwd = std::fs::canonicalize(workspace).ok()?;
    let paths = InstructionsLoadedPathMode::host();
    let permission_mode = match request.effective_security_level() {
        crate::model::SecurityLevel::RequestApproval => InstructionsLoadedPermissionMode::Default,
        crate::model::SecurityLevel::AllowEdits => InstructionsLoadedPermissionMode::AcceptEdits,
        crate::model::SecurityLevel::FullAccess => {
            InstructionsLoadedPermissionMode::BypassPermissions
        }
    };
    let host = InstructionsLoadedHostContext::new(
        request.conversation_id.clone(),
        None,
        &cwd,
        request.model.id.clone(),
        permission_mode,
        turn_id.to_owned(),
    )
    .ok()?;
    InstructionsLoadedRunDispatcher::new(&request.active_hooks, host, paths, runner)
}

fn hook_command_runner(
    request: &RunModelRequest,
    cancellation: CancelSignal,
) -> Result<HookCommandRunner, String> {
    Ok(hooks::command_runner_with_environment(
        Path::new(&request.workspace_path),
        &[],
        cancellation,
    ))
}

fn run_hook_event(
    request: &RunModelRequest,
    services: &HookRunServices<'_>,
    event: HookEvent,
    matcher: Option<&str>,
    call_id: Option<&str>,
    input: &Value,
    round: usize,
    budget: &mut hooks::HookBudget,
) -> Result<Vec<HookExecution>, String> {
    let observer = |update| match update {
        HookRunUpdate::Started { execution_id, hook } => {
            (services.event_sink)(ModelStreamEvent::HookExecutionStarted {
                round,
                execution_id,
                hook_id: hook.id,
                hook_name: hook.name,
                event: hooks::event_label(hook.event).into(),
                status_message: hook.status_message,
            })
        }
        HookRunUpdate::Completed(execution) => {
            (services.event_sink)(ModelStreamEvent::HookExecutionCompleted {
                round,
                execution_id: execution.execution_id,
                hook_id: execution.id,
                hook_name: execution.name,
                event: hooks::event_label(execution.event).into(),
                result: execution.result,
                blocked: execution.decision.blocked || execution.decision.halt,
                reason: execution.decision.reason,
                context_injected: execution.decision.additional_context.is_some(),
            })
        }
    };
    let executions = hooks::execute_event_with_runner(
        &request.active_hooks,
        event,
        matcher,
        input,
        budget,
        hook_command_runner(request, services.cancellation.clone())?,
        &observer,
    )?;
    // On disk before the caller honours any of it: a rewritten input, a block, a
    // `Stop` hook sending the model back to work are all intended, and the record
    // is what lets a later check tell them from a change nobody made.
    crate::history::record_hooks(request, round, call_id, matcher, &executions);
    Ok(executions)
}

fn record_hook_outputs(
    request: &mut RunModelRequest,
    generated: &mut Vec<ContextItem>,
    executions: &[HookExecution],
) {
    for execution in executions {
        generated.push(hook_context(&request.request_id, execution));
        if let Some(context) = execution
            .decision
            .additional_context
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            // Queued, not placed: a PreToolUse or PostToolUse hook runs in the
            // middle of the model's tool batch, and a card there would split
            // its turn. The loop head delivers it behind the batch's results.
            let summary = request.prompt_profile.render(
                PromptKey::HostNoticeHookContextSummary,
                &[
                    ("name", &execution.name),
                    ("event", crate::hooks::event_label(execution.event)),
                ],
            );
            request.host_notices.push(crate::model::HostNotice {
                kind: crate::wire_history::notice_kind::HOOK_CONTEXT,
                summary,
                body: context.to_owned(),
                id: None,
            });
        }
    }
}

fn hook_block_reason(executions: &[HookExecution], profile: &PromptProfile) -> Option<String> {
    executions.iter().find_map(|execution| {
        (execution.decision.blocked
            || execution.decision.halt
            || execution.decision.permission_decision == Some(HookPermissionDecision::Deny))
        .then(|| {
            execution.decision.reason.clone().unwrap_or_else(|| {
                profile.render(PromptKey::HookBlockedBy, &[("name", &execution.name)])
            })
        })
    })
}

fn hook_continuation_reason(
    executions: &[HookExecution],
    profile: &PromptProfile,
) -> Option<String> {
    executions.iter().find_map(|execution| {
        (execution.decision.blocked && !execution.decision.halt).then(|| {
            execution
                .decision
                .reason
                .clone()
                .unwrap_or_else(|| profile.text(PromptKey::HookContinueFallback).to_owned())
        })
    })
}

fn hook_permission_allows(executions: &[HookExecution]) -> bool {
    executions.iter().any(|execution| {
        execution.decision.permission_decision == Some(HookPermissionDecision::Allow)
    }) && !executions.iter().any(|execution| {
        execution.decision.permission_decision == Some(HookPermissionDecision::Deny)
    }) && !hook_permission_inputs_conflict(executions)
}

fn hook_permission_asks(executions: &[HookExecution]) -> bool {
    executions.iter().any(|execution| {
        execution.decision.permission_decision == Some(HookPermissionDecision::Ask)
    })
}

fn hook_permission_interrupts(executions: &[HookExecution]) -> bool {
    executions.iter().any(|execution| {
        execution.decision.permission_decision == Some(HookPermissionDecision::Deny)
            && execution.decision.interrupt
    })
}

fn permission_prompt_source(pre_tool_hooks: &[HookExecution]) -> Option<String> {
    const MAX_SOURCE_CHARS: usize = 800;
    let mut sources = Vec::new();
    sources.extend(pre_tool_hooks.iter().filter_map(|execution| {
        (execution.decision.permission_decision == Some(HookPermissionDecision::Ask)).then(|| {
            let reason = execution
                .decision
                .reason
                .as_deref()
                .unwrap_or("要求本次调用先由用户确认");
            format!(
                "Hook {}：{}",
                sanitize_permission_prompt_source(&execution.name),
                sanitize_permission_prompt_source(reason)
            )
        })
    }));
    if sources.is_empty() {
        return None;
    }
    Some(sources.join("；").chars().take(MAX_SOURCE_CHARS).collect())
}

fn sanitize_permission_prompt_source(value: &str) -> String {
    value
        .chars()
        .map(|character| {
            if character.is_control() {
                ' '
            } else {
                character
            }
        })
        .collect::<String>()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}

fn hook_updated_input(executions: &[HookExecution]) -> Option<JsonObject> {
    if hook_permission_inputs_conflict(executions) {
        return None;
    }
    executions.iter().rev().find_map(|execution| {
        if !matches!(
            execution.decision.permission_decision,
            Some(HookPermissionDecision::Allow | HookPermissionDecision::Ask)
        ) {
            return None;
        }
        execution
            .decision
            .updated_input
            .as_ref()
            .and_then(Value::as_object)
            .cloned()
    })
}

fn hook_permission_inputs_conflict(executions: &[HookExecution]) -> bool {
    let mut initialized = false;
    let mut first = None;
    for execution in executions {
        if !matches!(
            execution.decision.permission_decision,
            Some(HookPermissionDecision::Allow | HookPermissionDecision::Ask)
        ) {
            continue;
        }
        let current = execution.decision.updated_input.as_ref();
        if !initialized {
            initialized = true;
            first = current;
        } else if first != current {
            return true;
        }
    }
    false
}

/// The fixed backend classifier plus the conversation's security level are the
/// only authorization inputs. Hooks may still ask for or grant one call, but
/// there is no user-defined rule layer that can widen or narrow this verdict.
#[derive(Clone, Debug)]
struct ToolAuthorization {
    security: Option<security::SecurityDecision>,
    mcp_tool: bool,
    mcp_requires_user_interaction: bool,
}

impl ToolAuthorization {
    fn intrinsic_mandatory_prompt(&self) -> bool {
        self.mcp_requires_user_interaction
            || self
                .security
                .as_ref()
                .is_some_and(|decision| decision.mandatory_prompt)
    }

    fn requires_permission_hook(&self, level: crate::model::SecurityLevel) -> bool {
        self.mcp_requires_user_interaction
            || self.security.as_ref().map_or(
                self.mcp_tool && level != crate::model::SecurityLevel::FullAccess,
                |decision| decision.requires_approval,
            )
    }
}

fn authorization_tool_input(request: &RunModelRequest, call: &ToolCall) -> JsonObject {
    let mut input = call.input.clone();
    if matches!(call.name.as_str(), "memory_upsert" | "memory_delete") {
        if let Some(binding) = request.agent_definition_binding.as_ref() {
            let scope = match binding.memory {
                // Agent `user` memory is cross-project for the exact raw model
                // owner and therefore uses the existing mandatory global
                // mutation policy internally. The model-facing schema still
                // has no scope selector.
                AgentDefinitionMemory::User => Some("global"),
                AgentDefinitionMemory::Project | AgentDefinitionMemory::Local => Some("project"),
                AgentDefinitionMemory::None => None,
            };
            if let Some(scope) = scope {
                input.insert("scope".into(), json!(scope));
            }
        }
    }
    input
}

fn classify_tool_authorization(
    request: &RunModelRequest,
    call: &ToolCall,
) -> Result<ToolAuthorization, String> {
    let binding = request
        .mcp_bindings
        .iter()
        .find(|binding| binding.exposed_name == call.name);
    let authorization_input = authorization_tool_input(request, call);

    let security = if binding.is_some() {
        None
    } else {
        let execution_request = ToolExecutionRequest {
            conversation_id: request.conversation_id.clone(),
            workspace_path: request.workspace_path.clone(),
            tool_name: call.name.clone(),
            input: authorization_input,
        };
        Some(security::classify_model_call_in_workspaces(
            request.effective_security_level(),
            &request.workspaces,
            Path::new(&request.workspace_path),
            Path::new(&request.app_data_path),
            &request.additional_directories,
            &execution_request,
        )?)
    };
    Ok(ToolAuthorization {
        security,
        mcp_tool: binding.is_some(),
        mcp_requires_user_interaction: binding
            .is_some_and(|binding| binding.confirmation_required()),
    })
}

#[cfg(test)]
fn tool_requires_approval(request: &RunModelRequest, call: &ToolCall) -> Result<bool, String> {
    Ok(classify_tool_authorization(request, call)?
        .requires_permission_hook(request.effective_security_level()))
}

#[cfg(test)]
fn tool_context(execution: &ToolExecution, round: usize) -> ContextItem {
    tool_context_for_turn(
        execution,
        round,
        &new_context_id("model-turn"),
        None,
        "test-conversation",
        "test-run",
        &AppState::default(),
    )
}

fn tool_context_for_turn(
    execution: &ToolExecution,
    round: usize,
    model_turn_id: &str,
    requested_input: Option<&JsonObject>,
    conversation_id: &str,
    run_scope: &str,
    state: &AppState,
) -> ContextItem {
    let input = public_tool_input(&execution.call.name, &execution.call.input);
    let requested_input =
        requested_input.map(|input| public_tool_input(&execution.call.name, input));
    let result = execution.result.clone();
    let id = tool_context_id(conversation_id, run_scope, round, &execution.call.id);
    // Attest the exact projected payload this card carries — not the raw
    // execution — because the projection is what the renderer sees, stores and
    // hands back, and therefore what has to be checkable at save time.
    let attestation = state.attest_tool_context(&crate::tool_attestation::AttestationSubject {
        conversation_id,
        context_id: &id,
        tool_name: &execution.call.name,
        input: &input,
        requested_input: requested_input.as_ref(),
        result: &result,
        subagent: execution.subagent.as_ref(),
    });
    ContextItem::Tool {
        id,
        tool_name: execution.call.name.clone(),
        round: Some(round),
        model_turn_id: Some(model_turn_id.to_owned()),
        // Kept alongside the derived local id, not recoverable from it: the
        // digest is one-way, and replay that cannot read this back has to mint a
        // new id, which rewrites every tool call in the turn the moment the next
        // turn replays it.
        provider_call_id: Some(execution.call.id.clone()),
        requested_input,
        input,
        result,
        subagent: execution.subagent.clone(),
        notice: None,
        attestation,
        created_at: Utc::now().to_rfc3339(),
    }
}

/// Fills in the timeline id on an announcement, which the stream parsers emit
/// empty because they do not know the conversation.
///
/// Every other event passes through untouched. Nested subagent announcements
/// are stamped too: a child's cards live in the parent's conversation and are
/// committed by the parent card's fingerprint, so their ids must agree just as
/// exactly. A child run has no `request_id`, so its own cards derive from an
/// empty run scope; the recursion therefore drops the parent's scope rather
/// than stamping the child with a value the child itself will never use.
pub(crate) fn stamp_announced_context_id(
    event: ModelStreamEvent,
    conversation_id: &str,
    run_scope: &str,
) -> ModelStreamEvent {
    match event {
        ModelStreamEvent::ToolCallAnnounced {
            round,
            call_id,
            tool_name,
            ..
        } => {
            let context_id = tool_context_id(conversation_id, run_scope, round, &call_id);
            ModelStreamEvent::ToolCallAnnounced {
                round,
                call_id,
                tool_name,
                context_id,
            }
        }
        ModelStreamEvent::SubagentEvent {
            round,
            call_id,
            event,
        } => ModelStreamEvent::SubagentEvent {
            round,
            call_id,
            event: Box::new(stamp_announced_context_id(*event, conversation_id, "")),
        },
        other => other,
    }
}

/// The timeline id for one tool call, derived rather than minted.
///
/// The renderer sees a call announced long before the host builds its card,
/// and has to give the streaming row an id right then so later deltas can find
/// it. When both sides invented their own random id, the renderer's won at
/// save time — and any attestation the host had bound to *its* id could never
/// match again, which is exactly how a tool card became unsaveable.
///
/// Deriving the id from what both sides already hold when the call is
/// announced — the conversation, the run, the round, and the provider's call
/// id — makes them agree without a new event or an extra round trip.
/// Persistence requires context ids to be unique across the whole document, not
/// just one conversation, so the conversation is part of the digest: without it
/// two conversations whose providers both start at `call_1` would collide on
/// their first round. Hashing rather than concatenating keeps a hostile provider
/// id from shaping the local id.
///
/// `run_scope` is the run's `request_id`. The round counter restarts at 1 for
/// every run, so without it a second run in the same conversation whose first
/// round carries the same provider call id derives the same id as the first
/// run's — and the store, keyed on `(conversation_id, id)`, updates that row
/// instead of inserting, silently replacing the earlier card. Providers that
/// omit call ids make this concrete rather than theoretical: the sidecar
/// synthesizes stream-local ids, so two runs can both open with `synth_call_0`.
/// Child runs have no registered turn and therefore no `request_id`; they pass
/// an empty scope, which is what their announcements are stamped with too.
pub(crate) fn tool_context_id(
    conversation_id: &str,
    run_scope: &str,
    round: usize,
    provider_call_id: &str,
) -> String {
    let mut hasher = Sha256::new();
    for part in [
        conversation_id.as_bytes(),
        run_scope.as_bytes(),
        round.to_string().as_bytes(),
        provider_call_id.as_bytes(),
    ] {
        hasher.update(part);
        hasher.update([0]);
    }
    format!("ctx_tool_{:x}", hasher.finalize())
}

/// The timeline id for one round's prose, derived rather than minted — the same
/// lesson as [`tool_context_id`], applied to the branch that never learned it.
///
/// The renderer has to give the streaming assistant/reasoning row an id the
/// moment the first delta arrives, long before this round produces a canonical
/// context. When both sides invent their own, they disagree the instant the
/// round settles: `conversations::update` compares the renderer's id sequence
/// with the store's and, on any mismatch, **silently** keeps the host's body
/// and returns `Ok`. Every renderer write in that window is dropped without a
/// word — which is how an answered question, a queued message promotion or an
/// ordinary edit went missing.
///
/// A round's prose has no provider call id to key on, but both sides already
/// hold this run's identity and its round number: the renderer mints
/// `request_id` and passes it as the turn token, and the host validated and
/// registered that token before the run started. Deriving from those two makes
/// the ids agree without a new event or an extra round trip.
///
/// Concatenation is enough here, unlike the tool branch: both components are
/// locally produced, so there is no hostile provider string to keep from
/// shaping the id. `round` is decimal digits and `request_id` is one opaque
/// token, so no two `(request_id, round)` pairs can render the same string.
pub(crate) fn round_prose_context_id(request_id: &str, round: usize, kind: &str) -> String {
    format!("ctx_{kind}_{request_id}_{round}")
}

/// The grouping id shared by every context a single round produced.
///
/// Derived from the same two components, and in the renderer's existing shape,
/// so the cards the renderer grouped while streaming stay in one group after
/// the authoritative contexts replace them.
pub(crate) fn round_model_turn_id(request_id: &str, round: usize) -> String {
    format!("model-turn-{request_id}-{round}")
}

/// Child runs have no registered turn of their own, so they have no
/// `request_id` to derive from; their prose keeps a minted id. Their contexts
/// live inside a tool card's subagent transcript rather than on the parent
/// timeline, so no renderer streaming row is ever reconciled against them.
fn round_identity(request_id: &str, round: usize, kind: &str) -> Option<String> {
    (!request_id.is_empty()).then(|| round_prose_context_id(request_id, round, kind))
}

fn is_memory_tool_name(tool_name: &str) -> bool {
    crate::mework_memory::is_memory_tool(tool_name)
}

/// Resolves this run's two memory tiers from host-trusted paths only.
///
/// The global root comes from the platform home directory and the project root
/// from the run's own workspace path. Neither renderer IPC nor a model tool
/// argument contributes a path, so a tool call can only ever name a document
/// inside one of these two directories. The run's own tier switches ride along,
/// so a tier the conversation turned off is refused by the roots themselves.
fn run_memory_roots(request: &RunModelRequest) -> crate::mework_memory::MemoryRoots {
    let workspace = request.workspace_path.trim();
    crate::mework_memory::MemoryRoots::resolve_enabled(
        dirs::home_dir().as_deref(),
        (!workspace.is_empty()).then(|| Path::new(workspace)),
        request.memory_tier_access(),
    )
}

fn enabled_memory_tool_names(request: &RunModelRequest) -> Vec<String> {
    let enabled = request
        .enabled_tools
        .iter()
        .map(String::as_str)
        .collect::<HashSet<_>>();
    request
        .tools
        .iter()
        .filter(|tool| {
            tool.category == ToolCategory::Memory
                && is_memory_tool_name(&tool.name)
                && enabled.contains(tool.name.as_str())
        })
        .map(|tool| tool.name.clone())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect()
}

fn validate_fork_memory_tool_names(names: &[String]) -> Result<(), String> {
    if names.len() > crate::mework_memory::MEMORY_TOOL_NAMES.len()
        || names
            .windows(2)
            .any(|window| window[0].as_str() >= window[1].as_str())
        || names.iter().any(|name| !is_memory_tool_name(name))
    {
        return Err("The conversation fork's persisted memory-tool set is not a sorted, deduplicated trusted subset.".into());
    }
    Ok(())
}

pub fn public_tool_input(tool_name: &str, input: &JsonObject) -> JsonObject {
    let mut projected = project_tool_input(tool_name, input);
    // Every projected payload is compared against the copy that came back
    // through the renderer, so it must already be in the form that survives
    // that trip. Doing this once here covers the timeline card and its
    // attestation together, because both are built from this function.
    crate::model::canonicalize_object_numbers(&mut projected);
    projected
}

fn project_tool_input(tool_name: &str, input: &JsonObject) -> JsonObject {
    if tool_name == workflow::WORKFLOW_TOOL {
        // Scripts may reach 512 KiB. Public receipts and timeline retain only name
        // and fingerprint; `script.js` holds the body and step contexts hold output.
        let mut sanitized = JsonObject::new();
        // The model-provided short slug is the task row title. Project it into this
        // public input because the driver record is not persisted until first settlement.
        if let Some(name) = input.get("name").and_then(Value::as_str) {
            sanitized.insert("name".into(), Value::String(name.to_owned()));
        }
        if let Some(script) = input.get("script").and_then(Value::as_str) {
            if let Some(name) = workflow_script::script_display_name(script) {
                sanitized.insert("scriptName".into(), Value::String(name));
            }
            sanitized.insert("scriptBytes".into(), json!(script.len()));
            let mut hasher = Sha256::new();
            hasher.update(script.as_bytes());
            sanitized.insert(
                "scriptSha256".into(),
                Value::String(format!("{:x}", hasher.finalize())),
            );
        }
        if let Some(args) = input.get("args") {
            let body = serde_json::to_vec(args).unwrap_or_default();
            sanitized.insert("argsBytes".into(), json!(body.len()));
            // The anchor a resume that omits args checks `args.json` against. `args.json` holds
            // these same bytes, so the digests agree exactly when the file is untouched.
            if !args.is_null() {
                sanitized.insert(
                    "argsSha256".into(),
                    Value::String(crate::workflow_store::hex_digest(&body)),
                );
            }
        }
        if let Some(resume) = input.get("resume_run_id").and_then(Value::as_str) {
            sanitized.insert("resumeRunId".into(), Value::String(resume.to_owned()));
        }
        return sanitized;
    }
    input.clone()
}

fn assistant_context(content: String) -> ContextItem {
    ContextItem::Assistant {
        id: new_context_id("assistant"),
        content,
        round: None,
        model_turn_id: None,
        interrupted: false,
        sources: Vec::new(),
        created_at: Utc::now().to_rfc3339(),
    }
}

/// Converts sidecar citations into assistant-card entries. Deduplicate by `id`
/// because a `pause_turn` round may receive one citation in multiple steps, and
/// enforce host-side count and field bounds independently of the sidecar.
fn context_sources(
    sources: &[crate::aisdk::protocol::SidecarSource],
) -> Vec<crate::model::ContextSource> {
    fn clip(value: &str, max: usize) -> String {
        value.chars().take(max).collect()
    }
    let mut seen = std::collections::HashSet::new();
    sources
        .iter()
        .filter(|source| seen.insert(source.id.clone()))
        .take(32)
        .map(|source| crate::model::ContextSource {
            id: clip(&source.id, 256),
            url: source.url.as_deref().map(|url| clip(url, 2048)),
            title: source.title.as_deref().map(|title| clip(title, 512)),
        })
        .collect()
}

/// Like [`model_assistant_context`], but reuses the ledger-derived id so final
/// prose replaces its streaming row in place.
fn model_assistant_context(
    id: Option<String>,
    content: String,
    round: usize,
    model_turn_id: &str,
    sources: Vec<crate::model::ContextSource>,
) -> ContextItem {
    ContextItem::Assistant {
        id: id.unwrap_or_else(|| new_context_id("assistant")),
        content,
        round: Some(round),
        model_turn_id: Some(model_turn_id.to_owned()),
        interrupted: false,
        sources,
        created_at: Utc::now().to_rfc3339(),
    }
}

/// Like [`reasoning_context`], but reuses the ledger-derived id. Only the first
/// reasoning segment reuses it; later segments receive distinct ids.
/// `stats` belongs only on the first segment because duration and tokens are
/// step-level totals and must not be duplicated across cards.
fn reasoning_context(
    id: Option<String>,
    content: Option<String>,
    round: Option<usize>,
    model_turn_id: Option<&str>,
    form: ReasoningForm,
    stats: ReasoningStats,
) -> ContextItem {
    ContextItem::Reasoning {
        id: id.unwrap_or_else(|| new_context_id("reasoning")),
        content,
        form: Some(form),
        round,
        model_turn_id: model_turn_id.map(str::to_owned),
        interrupted: false,
        duration_ms: stats.duration_ms,
        tokens: stats.tokens,
        replay: None,
        created_at: Utc::now().to_rfc3339(),
    }
}

/// Reasoning parts the provider handed back in a step's continuation, in
/// provider order, as `{ "text", "providerOptions" }` values.
///
/// Only parts carrying `providerOptions` are collected: that is where the AI
/// SDK keeps an Anthropic `signature`/`redactedData` or a Responses
/// `itemId`/`reasoningEncryptedContent`. A Chat-family reasoning part has none
/// and keeps projecting as plain text through the card's content.
pub(crate) fn reasoning_replay_parts(continuation: &Value) -> Vec<Value> {
    let Some(messages) = continuation.as_array() else {
        return Vec::new();
    };
    let mut parts = Vec::new();
    for message in messages {
        if message.get("role").and_then(Value::as_str) != Some("assistant") {
            continue;
        }
        let Some(content) = message.get("content").and_then(Value::as_array) else {
            continue;
        };
        for part in content {
            if part.get("type").and_then(Value::as_str) != Some("reasoning") {
                continue;
            }
            let Some(options) = part.get("providerOptions").and_then(Value::as_object) else {
                continue;
            };
            if options.is_empty() {
                continue;
            }
            let text = part.get("text").and_then(Value::as_str).unwrap_or_default();
            parts.push(json!({ "text": text, "providerOptions": options }));
        }
    }
    parts
}

/// Attaches a step's replay parts to the cards minted for it.
///
/// A part whose text equals a card's summary belongs to that card (Responses
/// summary parts and plaintext thinking). Every other part — encrypted-only
/// items carry no text — goes to the metadata-only card when there is one,
/// otherwise to the first card, so it is still replayed. Parts that find no card
/// at all are dropped: the sidecar's evidence gate already judged them to be
/// empty provider scaffolding.
fn attach_reasoning_replay(cards: &mut [ContextItem], parts: Vec<Value>, model: &str) {
    if parts.is_empty() || cards.is_empty() {
        return;
    }
    let card_content = |card: &ContextItem| match card {
        ContextItem::Reasoning { content, .. } => content.clone(),
        _ => None,
    };
    let mut assigned: Vec<Vec<Value>> = vec![Vec::new(); cards.len()];
    let mut leftovers = Vec::new();
    for part in parts {
        let text = part.get("text").and_then(Value::as_str).unwrap_or_default();
        let slot = cards.iter().enumerate().position(|(index, card)| {
            assigned[index].is_empty() && card_content(card).as_deref().unwrap_or_default() == text
        });
        match slot {
            Some(index) => assigned[index].push(part),
            None => leftovers.push(part),
        }
    }
    if !leftovers.is_empty() {
        let index = cards
            .iter()
            .position(|card| card_content(card).is_none())
            .unwrap_or(0);
        assigned[index].extend(leftovers);
    }
    for (card, parts) in cards.iter_mut().zip(assigned) {
        if parts.is_empty() {
            continue;
        }
        if let ContextItem::Reasoning { replay, form, .. } = card {
            if parts.iter().any(|part| {
                part.pointer("/providerOptions/anthropic/redactedData")
                    .and_then(Value::as_str)
                    .is_some_and(|data| !data.is_empty())
            }) {
                *form = Some(ReasoningForm::Encrypted);
            }
            *replay = Some(crate::model::ReasoningReplay {
                model: model.to_owned(),
                parts,
            });
        }
    }
}

/// Reasoning metadata for a round: sidecar wall-clock duration and provider
/// reasoning tokens. If both are absent there is no visible reasoning trace; if
/// text is absent but metadata exists, render a metadata-only card.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(crate) struct ReasoningStats {
    pub(crate) duration_ms: Option<u64>,
    pub(crate) tokens: Option<u64>,
}

impl ReasoningStats {
    /// Whether this round performed reasoning.
    ///
    /// Use `tokens > 0`, not `is_some()`: OpenAI Responses reports zero rather
    /// than omitting the field for non-reasoning responses.
    fn is_present(self) -> bool {
        self.duration_ms.is_some() || self.tokens.is_some_and(|tokens| tokens > 0)
    }

    /// Context form: omit zero tokens to avoid displaying a meaningless zero.
    fn normalized(self) -> Self {
        Self {
            duration_ms: self.duration_ms,
            tokens: self.tokens.filter(|tokens| *tokens > 0),
        }
    }
}

/// Derived identity for reasoning segment `segment` in this round. The first
/// segment shares the streamed `ctx_reasoning_<request_id>_<round>` id; later
/// segments append their ordinal, matching renderer streaming ids.
fn reasoning_segment_identity(request_id: &str, round: usize, segment: usize) -> Option<String> {
    let base = round_identity(request_id, round, "reasoning")?;
    Some(if segment == 0 {
        base
    } else {
        format!("{base}_{segment}")
    })
}

/// Builds reasoning cards for a round. Attach step-level metadata only to the
/// first segment, render metadata-only cards for encrypted reasoning with no summary,
/// and choose card form from the producing model's configured reasoning form.
fn round_reasoning_contexts(
    reasoning: &[String],
    stats: ReasoningStats,
    request_id: &str,
    round: usize,
    model_turn_id: &str,
    form: ReasoningForm,
    replay: RoundReasoningReplay<'_>,
) -> Vec<ContextItem> {
    let mut stats = stats.normalized();
    let mut cards = if reasoning.is_empty() {
        if !stats.is_present() {
            return Vec::new();
        }
        vec![reasoning_context(
            reasoning_segment_identity(request_id, round, 0),
            None,
            Some(round),
            Some(model_turn_id),
            form,
            stats,
        )]
    } else {
        reasoning
            .iter()
            .enumerate()
            .map(|(segment, content)| {
                reasoning_context(
                    reasoning_segment_identity(request_id, round, segment),
                    Some(content.clone()),
                    Some(round),
                    Some(model_turn_id),
                    form,
                    std::mem::take(&mut stats),
                )
            })
            .collect()
    };
    attach_reasoning_replay(&mut cards, replay.parts, replay.model);
    cards
}

/// The provider payload a round's reasoning cards must carry forward: the
/// continuation's reasoning parts and the model that produced them.
#[derive(Debug, Default)]
pub(crate) struct RoundReasoningReplay<'a> {
    pub(crate) parts: Vec<Value>,
    pub(crate) model: &'a str,
}

/// Partial assistant text recovered from a request that died mid-stream after
/// every retry failed. Marked interrupted so the renderer labels it truthfully;
/// no OpenAI Chat continuation envelope exists for an unfinished round.
///
/// It carries this round's derived id like any other canonical prose: the
/// streaming row the journal already wrote is the *same* text, so a minted id
/// here would leave the fragment on disk twice — once as the reconciled
/// streaming leftover and once as this context.
fn interrupted_assistant_context(
    id: Option<String>,
    content: String,
    round: usize,
    model_turn_id: &str,
    sources: Vec<crate::model::ContextSource>,
) -> ContextItem {
    ContextItem::Assistant {
        id: id.unwrap_or_else(|| new_context_id("assistant")),
        content,
        round: Some(round),
        model_turn_id: Some(model_turn_id.to_owned()),
        interrupted: true,
        // Citations from completed intermediate pause steps remain factual even if a
        // later step fails or reaches its limit.
        sources,
        created_at: Utc::now().to_rfc3339(),
    }
}

/// Reasoning recovered from a round that died before finishing it.
///
/// The fragment is kept in either form. For plaintext reasoning it *is* the
/// reasoning. For encrypted reasoning it is the summary the provider streamed
/// alongside the ciphertext — and a round that never reached its `done` frame
/// has no ciphertext, so the card carries no replay payload and the summary is
/// all there is to show. What such a card must never do is reach the provider:
/// an incomplete encrypted trace cannot be sent back, and the wire projection
/// drops every interrupted reasoning card when the next turn is built (see
/// `wire_history`). Nothing to show means no card: a round with neither
/// summary text nor a finished trace leaves only the notice of its failure.
fn interrupted_reasoning_context(
    id: Option<String>,
    content: String,
    round: usize,
    model_turn_id: &str,
    form: ReasoningForm,
) -> Option<ContextItem> {
    if content.is_empty() {
        return None;
    }
    Some(ContextItem::Reasoning {
        id: id.unwrap_or_else(|| new_context_id("reasoning")),
        content: Some(content),
        form: Some(form),
        round: Some(round),
        model_turn_id: Some(model_turn_id.to_owned()),
        interrupted: true,
        // Interrupted reasoning has no duration or tokens because it never reached
        // a `done` frame; omit rather than guess.
        duration_ms: None,
        tokens: None,
        replay: None,
        created_at: Utc::now().to_rfc3339(),
    })
}

pub(crate) fn new_context_id(kind: &str) -> String {
    format!("ctx_{kind}_{}", Uuid::new_v4().simple())
}

pub(crate) fn merge_usage(total: &mut ModelUsage, current: &ModelUsage) {
    total.input_tokens = add_optional(total.input_tokens, current.input_tokens);
    total.cached_input_tokens =
        add_optional(total.cached_input_tokens, current.cached_input_tokens);
    total.output_tokens = add_optional(total.output_tokens, current.output_tokens);
    total.total_tokens = add_optional(total.total_tokens, current.total_tokens);
}

fn usage_context_tokens(usage: &ModelUsage) -> Option<u64> {
    match (usage.input_tokens, usage.output_tokens) {
        (Some(input), Some(output)) => Some(input.saturating_add(output)),
        _ => None,
    }
}

fn add_optional(left: Option<u64>, right: Option<u64>) -> Option<u64> {
    match (left, right) {
        (Some(left), Some(right)) => Some(left.saturating_add(right)),
        (Some(value), None) | (None, Some(value)) => Some(value),
        (None, None) => None,
    }
}

