    /// What the loose second pass folds away, and what it must not.
    ///
    /// The fold is the whole of the tolerance a free-text role name gets: two
    /// spellings that normalise together are offered to the model as one role,
    /// and two that do not are two roles it has to name apart. Widening this
    /// silently would start merging roles the user wrote as distinct.
    #[test]
    fn the_loose_pass_folds_away_only_what_carries_no_meaning_in_a_name() {
        // Case, the three separators, outer whitespace and outer quoting: all
        // ways of writing one name, none of them a different role.
        for spelling in [
            "code-reviewer",
            "Code Reviewer",
            "CODE_REVIEWER",
            "codereviewer",
            "  code reviewer  ",
            "\"code-reviewer\"",
            "`code-reviewer`",
            "「code-reviewer」",
        ] {
            assert_eq!(
                normalized_agent_type(spelling),
                normalized_agent_type("code-reviewer"),
                "{spelling:?}"
            );
        }

        // Non-ASCII names fold by the same rule and keep their own identity.
        assert_eq!(normalized_agent_type(" 对抗式审查 "), "对抗式审查");
        assert_ne!(
            normalized_agent_type("对抗式审查"),
            normalized_agent_type("代码检查")
        );

        // A real character is never folded: these stay three roles.
        assert_ne!(
            normalized_agent_type("reviewer"),
            normalized_agent_type("reviewer2")
        );
        assert_ne!(
            normalized_agent_type("reviewer"),
            normalized_agent_type("re.viewer")
        );

        // And a name that folds to nothing matches nothing, rather than every
        // other name that also folds to nothing.
        assert!(normalized_agent_type(" -_- ").is_empty());
    }

