    #[test]
    fn provider_errors_redact_keys_data_urls_and_large_bare_encoded_payloads() {
        let key = "sk-secret";
        let bare = "A".repeat(512);
        let message =
            format!("request with {key} rejected: data:image/png;base64,iVBORw0KGgo= and {bare}");
        let provider_body = json!({"error":{"message":message}}).to_string();
        let provider_error = api_error_message(StatusCode::BAD_REQUEST, provider_body.as_bytes());

        let sanitized = sanitize_error(&provider_error, Some(key));

        assert!(sanitized.contains("HTTP 400"));
        assert!(sanitized.contains("[REDACTED]"));
        assert!(sanitized.contains("<image data URL redacted>"));
        assert!(sanitized.contains("<large encoded data redacted>"));
        assert!(!sanitized.contains(key));
        assert!(!sanitized.contains("iVBORw0KGgo="));
        assert!(!sanitized.contains(&bare));
    }

    #[test]
    fn provider_error_redaction_consumes_folded_data_url_payloads() {
        let folded_payload = "iVBORw0K\r\n\t GgoAAA\n BBBCCC==";
        let message =
            format!("provider rejected data:image/png;base64,{folded_payload}; safe detail");
        let provider_body = json!({"error":{"message":message}}).to_string();
        let provider_error = api_error_message(StatusCode::BAD_REQUEST, provider_body.as_bytes());

        let sanitized = sanitize_error(&provider_error, None);

        assert!(sanitized.contains("<image data URL redacted>; safe detail"));
        assert!(!sanitized.contains("iVBORw0K"));
        assert!(!sanitized.contains("GgoAAA"));
        assert!(!sanitized.contains("BBBCCC=="));

        let whitespace_only = "data:image/png;base64,\r\n\t ; intact";
        assert_eq!(
            crate::http_util::redact_inline_encoded_data(whitespace_only),
            whitespace_only,
            "a data URL marker without any encoded byte must not be treated as an image payload"
        );
    }

