    fn step_request_with(
        request: &RunModelRequest,
        exchanges: &[Exchange],
        base_url: &str,
    ) -> crate::aisdk::protocol::StepRequest {
        try_step_request_with(request, exchanges, base_url).expect("测试请求应当能组装")
    }

    /// Same, but returns assembly-time rejections for callers to assert.
    fn try_step_request_with(
        request: &RunModelRequest,
        exchanges: &[Exchange],
        base_url: &str,
    ) -> Result<crate::aisdk::protocol::StepRequest, String> {
        let family = crate::aisdk::protocol::Family::for_format(request.provider.family);
        crate::aisdk::step::build_step_request(
            request,
            exchanges,
            wire_history::project_full(family, &request.contexts),
            base_url,
            None,
            1,
        )
    }

