    /// Answers the first plan card the run raises and hands the card back, so a
    /// test can assert on what the user was actually shown.
    /// Answers the plan cards the run raises, in order, one answer per card.
    fn answer_plan_cards(
        state: &AppState,
        answers: Vec<(crate::tool_prompt::ToolPromptDecision, Option<&str>)>,
    ) -> thread::JoinHandle<Vec<crate::tool_prompt::PendingToolPrompt>> {
        let answering = state.clone();
        let answers = answers
            .into_iter()
            .map(|(decision, feedback)| (decision, feedback.map(str::to_owned)))
            .collect::<Vec<_>>();
        thread::spawn(move || {
            let mut cards = Vec::new();
            for (decision, feedback) in answers {
                let deadline = Instant::now() + Duration::from_secs(30);
                loop {
                    assert!(Instant::now() < deadline, "plan card {} was never announced", cards.len() + 1);
                    if let Some((_, card)) = answering
                        .tool_prompts()
                        .all_pending_cards()
                        .into_iter()
                        .next()
                    {
                        if answering
                            .tool_prompts()
                            .resolve(&card.prompt_id, decision, feedback.clone())
                            .is_ok()
                        {
                            cards.push(card);
                            break;
                        }
                    }
                    thread::sleep(Duration::from_millis(5));
                }
            }
            cards
        })
    }

    fn function_call_response(call_id: &str, name: &str, arguments: Value) -> Value {
        json!({
            "model": "model-test",
            "status": "completed",
            "output": [{
                "type":"function_call",
                "status":"completed",
                "call_id": call_id,
                "name": name,
                "arguments": serde_json::to_string(&arguments).unwrap()
            }],
            "usage":{"input_tokens":1,"output_tokens":1,"total_tokens":2}
        })
    }

    fn tool_output<'a>(response: &'a RunModelResponse, tool: &str) -> &'a ToolResult {
        response
            .contexts
            .iter()
            .find_map(|context| match context {
                ContextItem::Tool {
                    tool_name, result, ..
                } if tool_name == tool => Some(result),
                _ => None,
            })
            .unwrap_or_else(|| panic!("{tool} never produced a result"))
    }

    /// The whole plan-mode round trip through the run loop: the two tools the
    /// setting derives are admitted without being enabled, the card carries the
    /// plan's own title, feedback sends the model back to revise and ask again,
    /// and approval returns the plan without touching the security level.
    #[test]
    fn a_plan_goes_round_on_feedback_until_approved_and_leaves_the_level_alone() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = serve_json_sequence(
            listener,
            vec![
                function_call_response(
                    "call-plan-write",
                    "plan",
                    json!({"action":"write","content":"# Ship the parser\n\nRewrite the tokenizer."}),
                ),
                function_call_response("call-exit", "exit_plan_mode", json!({})),
                function_call_response(
                    "call-plan-revise",
                    "plan",
                    json!({"action":"write","content":"# Ship the parser\n\nRewrite the tokenizer and migrate the data."}),
                ),
                function_call_response("call-exit-again", "exit_plan_mode", json!({})),
                responses_text_output("done"),
            ],
        );

        let directory = tempfile::tempdir().unwrap();
        let (state, request, cell, store) = plan_mode_loop_fixture(address, &directory);
        let conversation_id = request.conversation_id.clone();
        let answering = answer_plan_cards(
            &state,
            vec![
                (
                    crate::tool_prompt::ToolPromptDecision::Deny,
                    Some("cover the migration too"),
                ),
                (crate::tool_prompt::ToolPromptDecision::AllowOnce, None),
            ],
        );

        let response = run_model(request, &state, &discard_event, &|_, _, _| {
            panic!("a plan tool must not go through the ordinary approval gate")
        })
        .unwrap();
        let bodies = server.join().unwrap();
        let cards = answering.join().unwrap();

        assert_eq!(cards.len(), 2);
        assert_eq!(cards[0].kind, crate::tool_prompt::PromptKind::PlanExit);
        assert_eq!(cards[0].tool_name, "exit_plan_mode");
        assert_eq!(cards[0].summary, "Ship the parser");
        assert!(!cards[0].allow_always_offered);
        assert!(cards[0].mandatory);

        let exits = response
            .contexts
            .iter()
            .filter_map(|context| match context {
                ContextItem::Tool {
                    tool_name, result, ..
                } if tool_name == "exit_plan_mode" => Some(result),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(exits.len(), 2);
        assert!(exits[0].success, "{}", exits[0].output);
        assert!(exits[0].output.contains("cover the migration too"));
        assert!(exits[0].output.contains("call exit_plan_mode again"));
        assert!(exits[1].success, "{}", exits[1].output);
        assert!(exits[1].output.contains("User has approved your plan"));
        assert!(exits[1]
            .output
            .contains("## Approved Plan:\n# Ship the parser\n\nRewrite the tokenizer and migrate the data."));
        assert!(!exits[1].output.contains("Permission mode"));

        // The guidance was appended where plan mode began, as a system item in
        // the model's input rather than in its instructions.
        let guidance = crate::prompt_profile::PromptProfile::builtin_english()
            .text(crate::prompt_profile::PromptKey::SystemPlanMode)
            .lines()
            .nth(2)
            .unwrap()
            .to_owned();
        assert!(response.contexts.iter().any(|context| {
            crate::system_append::topic(context) == Some(crate::plan_mode::ENTER_TOPIC)
        }));
        assert_eq!(bodies[0].matches(guidance.as_str()).count(), 1, "{}", bodies[0]);
        assert!(!bodies[0].contains("systemAppend"), "the marker never leaves the host");

        // Approval ended plan mode, at once and on disk, so the reply after it
        // ended the turn without putting anything to the user again.
        assert!(!state.live_plan_mode(&conversation_id).unwrap().get());
        assert!(!store.conversation(&conversation_id).unwrap().unwrap().settings.plan_mode_enabled);
        assert_eq!(bodies.len(), 5);

        // Approval is not a level change: the level stays the user's.
        assert_eq!(cell.get(), SecurityLevel::RequestApproval);
        assert_eq!(
            store
                .conversation(&conversation_id)
                .unwrap()
                .unwrap()
                .settings
                .security_level,
            SecurityLevel::RequestApproval
        );
        let plan = store.conversation_plan(&conversation_id).unwrap().unwrap();
        assert_eq!(plan.status, crate::model::PlanStatus::Approved);
        assert!(plan.markdown.contains("migrate the data"));
    }

    /// Plan mode refuses a `write` to a tracked file before the call reaches
    /// its approval card: the user is never asked, and the file is untouched.
    #[test]
    fn plan_mode_refuses_a_repository_write_before_its_approval_card() {
        let directory = tempfile::tempdir().unwrap();
        let git = |args: &[&str]| {
            std::process::Command::new("git")
                .current_dir(directory.path())
                .args(args)
                .output()
                .is_ok_and(|output| output.status.success())
        };
        if !git(&["init", "-q"]) {
            return;
        }
        std::fs::write(directory.path().join("tracked.txt"), "keep\n").unwrap();
        assert!(git(&["add", "tracked.txt"]));
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = serve_json_sequence(
            listener,
            vec![
                function_call_response(
                    "call-write",
                    "write",
                    json!({"path":"tracked.txt","content":"changed\n"}),
                ),
                responses_text_output("understood"),
            ],
        );
        let (state, request, _, _) = plan_mode_loop_fixture(address, &directory);
        // The fixture's level asks before a write, so a card would show here.
        let probe = ToolCall {
            id: "probe".into(),
            name: "write".into(),
            input: serde_json::from_value(json!({"path":"tracked.txt","content":"changed\n"}))
                .unwrap(),
        };
        assert!(tool_requires_approval(&request, &probe).unwrap());
        let prompts = std::sync::atomic::AtomicUsize::new(0);

        let response = run_model(request, &state, &discard_event, &|_, _, _| {
            prompts.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            Ok(true)
        })
        .unwrap();
        server.join().unwrap();

        assert_eq!(prompts.load(std::sync::atomic::Ordering::SeqCst), 0);
        let write = tool_output(&response, "write");
        assert!(!write.success);
        assert!(write.output.starts_with("Plan mode is on:"), "{}", write.output);
        assert_eq!(
            std::fs::read_to_string(directory.path().join("tracked.txt")).unwrap(),
            "keep\n"
        );
    }

    #[test]
    fn agent_spawn_approval_precedes_reservation_and_observation() {
        for (level, hook_allow, answer, prompts, success) in [
            (SecurityLevel::RequestApproval, false, Ok(false), 1, false),
            (
                SecurityLevel::RequestApproval,
                false,
                Err("approval channel closed".to_owned()),
                1,
                false,
            ),
            (SecurityLevel::RequestApproval, false, Ok(true), 1, true),
            (SecurityLevel::RequestApproval, true, Ok(false), 0, true),
            (SecurityLevel::FullAccess, false, Ok(false), 0, true),
        ] {
            let (directory, state, mut parent, _) =
                named_agent_fixture(AgentDefinitionMemory::None);
            parent.security_level = level;
            let pool = AgentPool::new();
            let shadow = test_kernel_shadow();
            shadow.begin_turn();
            shadow.round_started();
            let call = ToolCall {
                id: "approval-spawn".into(),
                name: "agent_spawn".into(),
                input: serde_json::from_value(
                    json!({"name":"approval-probe", "prompt":"review", "agent_type":"reviewer"}),
                )
                .unwrap(),
            };
            let digest = crate::kernel_shadow::call_params_digest(&call.input);
            shadow.tool_request(
                &call.id,
                level == SecurityLevel::RequestApproval,
                digest,
            );
            shadow.tool_dispatched(&call.id);
            let observed = std::sync::atomic::AtomicUsize::new(0);
            let approval =
                |_: &ToolExecutionRequest, _: &ToolDescriptor, _: ApprovalRequester<'_>| {
                    assert!(pool.is_empty(), "approval must precede registration");
                    assert!(
                        state
                            .reserved_subagent_names(&parent.conversation_id)
                            .is_empty(),
                        "denial must not leave a permanent name reservation"
                    );
                    observed.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                    if let Ok(granted) = &answer {
                        shadow.record_prompt_outcome(*granted);
                    }
                    answer.clone()
                };
            let started = std::sync::atomic::AtomicBool::new(false);
            let sink = |event: ModelStreamEvent| -> Result<(), String> {
                if matches!(
                    event,
                    ModelStreamEvent::SubagentDelta {
                        channel: SubagentChannel::Status,
                        ..
                    }
                ) {
                    assert_eq!(
                        observed.load(std::sync::atomic::Ordering::SeqCst),
                        prompts,
                        "approval must precede worker startup"
                    );
                    started.store(true, std::sync::atomic::Ordering::SeqCst);
                    // Cancel at the startup boundary so this dispatch test cannot
                    // contact any real provider, while still using the real worker path.
                    pool.find("approval-probe")
                        .unwrap()
                        .request_stop(agents::StopOrigin::Host);
                }
                Ok(())
            };
            let execution = run_agent_tool(
                agents::AgentToolKind::Spawn,
                &pool,
                &shadow,
                &parent,
                call,
                &state,
                &sink,
                &approval,
                hook_allow,
                1,
            )
            .unwrap();
            shadow.tool_finished(
                &execution.call.id,
                false,
                hook_allow,
                execution.result.success,
                digest,
            );
            assert_eq!(observed.load(std::sync::atomic::Ordering::SeqCst), prompts);
            assert_eq!(
                execution.result.success, success,
                "{}",
                execution.result.output
            );
            assert_eq!(started.load(std::sync::atomic::Ordering::SeqCst), success);
            if success {
                pool.wait_settled_for_tests(Duration::from_secs(5));
            } else {
                assert!(pool.is_empty());
                assert!(state
                    .reserved_subagent_names(&parent.conversation_id)
                    .is_empty());
            }
            assert!(
                shadow.divergences().is_empty(),
                "{:?}",
                shadow.divergences()
            );
            state.document_store.flush(Duration::from_secs(10)).unwrap();
            drop(directory);
        }
    }

    #[test]
    fn run_model_agent_spawn_denial_reaches_the_next_model_round_without_a_task() {
        let (directory, state, mut request, _) = named_agent_fixture(AgentDefinitionMemory::None);
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        request.provider.base_url = format!("http://{}/v1", listener.local_addr().unwrap());
        request.security_level = SecurityLevel::RequestApproval;
        let mut document = (*current_agent_document(&request, &state).unwrap()).clone();
        document.assets.api_providers = vec![request.provider.clone()];
        state
            .document_store
            .commit(&directory.path().join("document.v1.json"), document)
            .unwrap();
        let server = serve_json_sequence(
            listener,
            vec![
                json!({
                    "model":"model-test", "status":"completed",
                    "usage":{"input_tokens":1,"output_tokens":1,"total_tokens":2}, "output":[{
                        "type":"function_call", "id":"fc_spawn", "call_id":"call_spawn",
                        "name":"agent_spawn", "arguments":json!({"name":"denied-worker", "prompt":"review", "agent_type":"reviewer"}).to_string(),
                        "status":"completed"
                    }]
                }),
                responses_text_output("The delegation was denied."),
            ],
        );
        let approvals = std::sync::atomic::AtomicUsize::new(0);
        let approval =
            |execution: &ToolExecutionRequest, _: &ToolDescriptor, _: ApprovalRequester<'_>| {
                assert_eq!(execution.tool_name, "agent_spawn");
                assert!(state
                    .reserved_subagent_names(&request.conversation_id)
                    .is_empty());
                approvals.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                Ok(false)
            };
        let response = run_model(request.clone(), &state, &discard_event, &approval).unwrap();
        assert_eq!(
            approvals.load(std::sync::atomic::Ordering::SeqCst),
            1,
            "{response:?}"
        );
        let bodies = server.join().unwrap();
        assert_eq!(bodies.len(), 2);
        assert!(
            bodies[1].contains("The user denied this tool call."),
            "{}",
            bodies[1]
        );
        assert!(state
            .reserved_subagent_names(&request.conversation_id)
            .is_empty());
        assert!(response.contexts.iter().any(|context| matches!(context,
            ContextItem::Tool { tool_name, result, .. } if tool_name == "agent_spawn" && !result.success)));
        state.document_store.flush(Duration::from_secs(10)).unwrap();
    }

    #[test]
    fn running_child_round_checkpoint_survives_reopen_before_complete_turn() {
        let directory = tempfile::tempdir().unwrap();
        std::fs::write(
            directory.path().join("checkpoint.txt"),
            "ROUND_ONE_TOOL_BODY",
        )
        .unwrap();
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        listener.set_nonblocking(true).unwrap();
        let mut parent = loop_request_for(listener.local_addr().unwrap(), directory.path());
        parent.request_id = "child-round-checkpoint".into();
        let state = AppState::default();
        let pool = Arc::new(AgentPool::new());
        let spawn = ToolExecution {
            call: ToolCall {
                id: "spawn-checkpoint".into(),
                name: "agent_spawn".into(),
                input: serde_json::from_value(
                    json!({"name":"checkpoint-worker", "prompt":"read checkpoint.txt"}),
                )
                .unwrap(),
            },
            result: ToolResult {
                success: true,
                output: "ok".into(),
                images: Vec::new(),
                diff: None,
                executed_at: "2026-09-05T00:00:00Z".into(),
                duration_ms: 0,
            },
            subagent: None,
        };
        let card = tool_context(&spawn, 1);
        let card_id = card.id().to_owned();
        parent.contexts.push(card);
        let store = persisted_conversation_for(&parent);
        let initial = vec![ContextItem::User {
            id: "child-task".into(),
            content: "read checkpoint.txt".into(),
            images: Vec::new(),
            files: Vec::new(),
            created_at: "2026-09-05T00:00:00Z".into(),
        }];
        let shared = pool
            .register(
                "checkpoint-worker".into(),
                "checkpoint-worker".into(),
                "read checkpoint.txt".into(),
                agent_child_template(&parent),
                SubagentRunKind::General,
                &state,
                initial.clone(),
                Vec::new(),
                AgentLiveStatus::Running,
                spawn.call.id.clone(),
                None,
            )
            .unwrap();
        shared.record_call_context(&spawn.call.id, &card_id);
        let notices = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let notice_counter = Arc::clone(&notices);
        pool.set_settle_observer(Arc::new(move |_, _| {
            notice_counter.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        }));
        let (at_second_tx, at_second_rx) = std::sync::mpsc::channel();
        let (release_tx, release_rx) = std::sync::mpsc::channel();
        let server = thread::spawn(move || {
            let deadline = Instant::now() + Duration::from_secs(30);
            let accept = || loop {
                match listener.accept() {
                    Ok((stream, _)) => {
                        stream.set_nonblocking(false).unwrap();
                        stream
                            .set_read_timeout(Some(Duration::from_secs(10)))
                            .unwrap();
                        break stream;
                    }
                    Err(error)
                        if error.kind() == std::io::ErrorKind::WouldBlock
                            && Instant::now() < deadline =>
                    {
                        thread::yield_now()
                    }
                    Err(error) => panic!("checkpoint fixture accept failed: {error}"),
                }
            };
            let mut first = accept();
            read_http_request_with_body(&mut first);
            write_sse_response(
                &mut first,
                &responses_sse(&json!({
                    "model":"model-test", "status":"completed",
                    "usage":{"input_tokens":1,"output_tokens":1,"total_tokens":2},
                    "output":[
                        {"type":"message","id":"msg_first","status":"completed","role":"assistant",
                         "content":[{"type":"output_text","text":"ROUND_ONE_DURABLE"}]},
                        {"type":"function_call","id":"fc_read","call_id":"read_checkpoint","name":"read",
                         "arguments":json!({"path":"checkpoint.txt"}).to_string(),"status":"completed"}
                    ]
                })),
            );
            drop(first);
            let mut second = accept();
            let second_body = read_http_request_with_body(&mut second);
            at_second_tx.send(()).unwrap();
            release_rx.recv_timeout(Duration::from_secs(30)).unwrap();
            write_sse_response(
                &mut second,
                &responses_sse(&responses_text_output("FINAL_ROUND_DONE")),
            );
            second_body
        });
        let worker_shared = Arc::clone(&shared);
        let worker_state = state.clone();
        // No task surface: persistence must not depend on a live parent renderer.
        let worker = thread::spawn(move || agent_worker_loop(&worker_shared, &worker_state, 1));
        at_second_rx.recv_timeout(Duration::from_secs(20)).unwrap();
        let status_at_checkpoint = shared.status();
        let transcript_at_checkpoint = shared.transcript();
        let notices_at_checkpoint = notices.load(std::sync::atomic::Ordering::SeqCst);
        let results_at_checkpoint = pool.take_undelivered_results();
        let reopened = crate::conversation_store::ConversationStore::open(
            &directory
                .path()
                .join(crate::conversation_store::DATABASE_FILE_NAME),
        )
        .unwrap();
        let recovery = reopened
            .conversation(&parent.conversation_id)
            .unwrap()
            .unwrap();
        release_tx.send(()).unwrap();
        worker.join().unwrap();
        let second_body = server.join().unwrap();
        assert!(
            second_body.contains("ROUND_ONE_TOOL_BODY"),
            "the first tool round really completed"
        );
        assert_eq!(status_at_checkpoint, AgentLiveStatus::Running);
        assert_eq!(
            transcript_at_checkpoint, initial,
            "complete_turn has not appended any round yet"
        );
        assert_eq!(notices_at_checkpoint, 0);
        assert!(results_at_checkpoint.is_empty());
        assert_eq!(
            recovery.contexts.len(),
            parent.contexts.len(),
            "child output must not pollute the parent timeline"
        );
        let record = match recovery
            .contexts
            .iter()
            .find(|item| item.id() == card_id)
            .unwrap()
        {
            ContextItem::Tool {
                subagent: Some(record),
                attestation,
                ..
            } if !attestation.is_empty() => record,
            _ => panic!("the live child's settled round must already be durable and signed"),
        };
        assert_eq!(record.status, SubagentRunStatus::Interrupted);
        let contents = serde_json::to_string(&record.contexts).unwrap();
        assert!(contents.contains("ROUND_ONE_DURABLE"));
        assert!(contents.contains("ROUND_ONE_TOOL_BODY"));
        assert!(!contents.contains("FINAL_ROUND_DONE"));
        // Normal terminal backfill replaces the recovery copy, not appends to it.
        let mut history = parent.contexts.clone();
        let mut generated = GeneratedContexts::new(
            Some(ConversationSink {
                store: Arc::clone(&store),
                conversation_id: parent.conversation_id.clone(),
                request_id: parent.request_id.clone(),
            }),
            None,
        );
        let updates = checkpoint_terminal_agent_records(
            &pool,
            &parent.conversation_id,
            &parent.workspace_path,
            &state,
            &discard_event,
            2,
            &mut history,
            &mut generated,
            &HashMap::new(),
        );
        generated.track_card_updates(updates);
        assert!(generated.checkpoint());
        let terminal = reopened
            .conversation(&parent.conversation_id)
            .unwrap()
            .unwrap();
        let ContextItem::Tool {
            subagent: Some(record),
            ..
        } = terminal
            .contexts
            .iter()
            .find(|item| item.id() == card_id)
            .unwrap()
        else {
            panic!("terminal record")
        };
        assert_eq!(record.status, SubagentRunStatus::Completed);
        assert_eq!(
            record.contexts.len(),
            record
                .contexts
                .iter()
                .map(ContextItem::id)
                .collect::<HashSet<_>>()
                .len()
        );
        assert!(serde_json::to_string(&record.contexts)
            .unwrap()
            .contains("FINAL_ROUND_DONE"));
    }

    #[test]
    fn running_child_checkpoint_retries_and_is_refused_once_the_turn_settles() {
        let directory = tempfile::tempdir().unwrap();
        let parent = loop_request_for("127.0.0.1:9".parse().unwrap(), directory.path());
        let state = AppState::default();
        let pool = AgentPool::new();
        let template = agent_child_template(&parent);
        let shared = pool
            .register(
                "draft-worker".into(),
                "draft-worker".into(),
                "draft task".into(),
                template.clone(),
                SubagentRunKind::General,
                &state,
                Vec::new(),
                Vec::new(),
                AgentLiveStatus::Running,
                "owner-1-call".into(),
                None,
            )
            .unwrap();
        let store = persisted_conversation_for(&parent);
        let spawn = ToolExecution {
            call: ToolCall {
                id: "owner-1-call".into(),
                name: "agent_spawn".into(),
                input: serde_json::from_value(
                    json!({"name":"draft-worker", "prompt":"draft task"}),
                )
                .unwrap(),
            },
            result: ToolResult {
                success: true,
                output: "ok".into(),
                images: Vec::new(),
                diff: None,
                executed_at: "2026-09-05T00:00:00Z".into(),
                duration_ms: 0,
            },
            subagent: None,
        };
        let card = tool_context(&spawn, 1);
        let first_id = card.id().to_owned();
        shared.record_call_context("owner-1-call", &first_id);
        let new_sink = || {
            SubagentTranscriptSink::for_child(
                &template,
                &state,
                Arc::clone(&shared),
                shared.identity(),
            )
        };
        let mut generated = GeneratedContexts::new(None, None).with_transcript(new_sink());
        let prose = |id: &str, content: &str| ContextItem::Assistant {
            id: id.into(),
            content: content.into(),
            round: Some(1),
            model_turn_id: None,
            interrupted: false,
            sources: Vec::new(),
            created_at: "2026-09-05T00:00:00Z".into(),
        };
        generated.push(prose("round-1", "FIRST_CHECKPOINT"));
        assert!(
            !generated.checkpoint(),
            "the parent's owner row is not on disk yet"
        );
        store
            .upsert_contexts(
                &parent.conversation_id,
                &[card.clone()],
                crate::conversation_store::ContextStatus::Settled,
            )
            .unwrap();
        let read_card = |id: &str| {
            store
                .conversation(&parent.conversation_id)
                .unwrap()
                .unwrap()
                .contexts
                .into_iter()
                .find(|item| item.id() == id)
                .unwrap()
        };
        assert!(matches!(
            read_card(&first_id),
            ContextItem::Tool { subagent: None, .. }
        ));
        let fault = rusqlite::Connection::open(
            directory
                .path()
                .join(crate::conversation_store::DATABASE_FILE_NAME),
        )
        .unwrap();
        let coordinates = || {
            fault.query_row(
            "SELECT order_key, status, branch_id FROM context WHERE conversation_id = ?1 AND id = ?2",
            rusqlite::params![parent.conversation_id, first_id],
            |row| Ok((row.get::<_, f64>(0)?, row.get::<_, String>(1)?, row.get::<_, Option<String>>(2)?)),
        ).unwrap()
        };
        let original_coordinates = coordinates();
        fault
            .execute_batch(
                "CREATE TRIGGER fail_child_checkpoint BEFORE UPDATE ON context
            BEGIN SELECT RAISE(ABORT, 'child checkpoint failure'); END;",
            )
            .unwrap();
        assert!(!generated.checkpoint());
        assert!(generated.transcript.as_ref().unwrap().written.is_none());
        fault
            .execute_batch("DROP TRIGGER fail_child_checkpoint;")
            .unwrap();
        assert!(
            generated.checkpoint(),
            "failed writes must be retried without new child output"
        );
        assert_eq!(coordinates(), original_coordinates);
        assert!(
            matches!(read_card(&first_id), ContextItem::Tool { subagent: Some(record), .. }
            if record.status == SubagentRunStatus::Interrupted && record.contexts.len() == 1)
        );
        assert_eq!(shared.status(), AgentLiveStatus::Running);
        assert!(
            shared.transcript().is_empty(),
            "a recovery copy must not change complete_turn's append base"
        );
        assert!(pool.take_undelivered_results().is_empty());
        let old = shared.identity();
        shared.complete_turn(
            old,
            generated.items.clone(),
            "done".into(),
            AgentLiveStatus::Idle,
            &ModelUsage::default(),
            1,
            None,
        );
        shared.take_undelivered_results();
        let before = read_card(&first_id);
        generated.push(prose("late-old", "STALE_CHECKPOINT"));
        assert!(
            !generated.checkpoint(),
            "a settled incarnation's late checkpoint must be refused"
        );
        assert_eq!(read_card(&first_id), before);
        assert!(pool.take_undelivered_results().is_empty());
    }

