    #[test]
    fn discovered_mcp_role_policy_matrix() {
        for (tools, disallowed, expected) in [
            (None, vec![], true),
            (Some(vec![]), vec![], false),
            (Some(vec!["*".into()]), vec![], true),
            (Some(vec!["*".into()]), vec!["mcp_tool".into()], false),
            (Some(vec!["mcp_tool".into()]), vec![], true),
            (Some(vec!["read".into()]), vec![], false),
        ] {
            let policy = AgentRunOverrides {
                tools,
                disallowed_tools: disallowed,
                ..Default::default()
            };
            assert_eq!(policy.permits_tool("mcp_tool"), expected);
        }
    }

    #[test]
    fn named_agent_mcp_rediscovery_respects_current_role() {
        let (directory, state, mut parent, mut definition) =
            named_agent_fixture(AgentDefinitionMemory::None);
        definition.tools = Some(vec!["read".into()]);
        let mut document = (*current_agent_document(&parent, &state).unwrap()).clone();
        set_conversation_agent_definitions(&mut document, vec![definition]);
        state
            .document_store
            .commit(&directory.path().join("document.v1.json"), document)
            .unwrap();
        parent.mcp_servers = vec![crate::mcp::RuntimeMcpServer {
            artifact_id: "test:role".into(),
            server_id: "test:role:echo".into(),
            name: "Role discovery".into(),
            description: String::new(),
            disabled_tools: Vec::new(),
            confirm_every_call_tools: Vec::new(),
            request_timeout: None,
            transport: crate::mcp::RuntimeMcpTransport::Stdio {
                command: "node".into(),
                args: vec![Path::new(env!("CARGO_MANIFEST_DIR"))
                    .join("tests/fixtures/mock_mcp_server.js")
                    .to_string_lossy()
                    .into_owned()],
                env: [("MCP_MOCK_EMPTY_FIRST_LIST".into(), "1".into())]
                    .into_iter()
                    .collect(),
                cwd: None,
                env_passthrough: Vec::new(),
            },
        }];
        attach_mcp_tools(&mut parent, &state).unwrap();
        assert!(
            parent.mcp_bindings.is_empty(),
            "the parent must actually discover zero tools"
        );
        let mut child = agent_child_template(&parent);
        apply_named_role_to_fresh_template(&parent, &state, &mut child, "reviewer").unwrap();
        attach_mcp_tools(&mut child, &state).unwrap();
        // A roleless sibling proves the same live server now really returns tools.
        let mut control = agent_child_template(&parent);
        attach_mcp_tools(&mut control, &state).unwrap();
        assert_eq!(control.mcp_bindings.len(), 2);
        for binding in &control.mcp_bindings {
            assert!(!child.enabled_tools.contains(&binding.exposed_name));
            assert!(!child
                .tools
                .iter()
                .any(|tool| tool.name == binding.exposed_name));
            assert!(!crate::aisdk::tools::enabled_tools(&child)
                .iter()
                .any(|tool| tool.name == binding.exposed_name));
        }
        assert!(child.mcp_bindings.is_empty());
        // Restored named requests retain the same trusted binding; rediscovery
        // must not widen their policy either.
        let mut resumed = child.clone();
        attach_mcp_tools(&mut resumed, &state).unwrap();
        assert!(resumed.mcp_bindings.is_empty());
        state.document_store.flush(Duration::from_secs(10)).unwrap();
    }

    /// Mutable access to the role list a run will actually resolve against.
    /// Tests that edit one field of a committed role (revision, tombstone) go
    /// through here rather than reaching for a global list that no longer exists.
    fn conversation_agent_definitions_mut(
        document: &mut crate::model::AppDocument,
    ) -> &mut Vec<AgentDefinition> {
        &mut document.workspaces[0].conversations[0]
            .settings
            .agent_definitions
    }

    /// Roles live in a conversation, so a test that wants a spawnable role has
    /// to put it where the run will look: the conversation its `RunModelRequest`
    /// names. Seeds every conversation in the document so a fixture does not have
    /// to know which one the request picked.
    fn set_conversation_agent_definitions(
        document: &mut crate::model::AppDocument,
        definitions: Vec<AgentDefinition>,
    ) {
        for workspace in &mut document.workspaces {
            for conversation in &mut workspace.conversations {
                conversation.settings.agent_definitions = definitions.clone();
            }
        }
    }

    fn set_conversation_allows_roleless(document: &mut crate::model::AppDocument, allow: bool) {
        for workspace in &mut document.workspaces {
            for conversation in &mut workspace.conversations {
                conversation.settings.allow_roleless_subagents = allow;
            }
        }
    }

