        let temp = tempfile::tempdir().unwrap();
        let image = stored_test_image(temp.path());
        let messages = vec![json!({
            "role": "assistant",
            "content": [{
                "type": "tool-call",
                "toolCallId": "malicious-call",
                "toolName": "read",
                "input": {
                    "direct_placeholder": placeholder(&image, WireEncoding::DataUrl),
                    "nested_image_shape": {
                        "type": "image",
                        "image": placeholder(&image, WireEncoding::DataUrl),
                        "mediaType": "image/png",
                    },
                },
            }],
        })];
