    #[test]
    fn one_canonical_turn_projects_to_all_api_formats_with_transient_wire_ids() {
        let mut request = run_request(ProviderFamily::OpenaiChat);
        request.contexts = vec![
            ContextItem::User {
                id: "ctx_user".into(),
                content: "读取 a.txt".into(),
                images: Vec::new(),
                files: Vec::new(),
                created_at: "2026-07-21T00:00:00Z".into(),
            },
            ContextItem::Reasoning {
                id: "ctx_reasoning".into(),
                content: Some("先读取文件".into()),
                form: None,
                round: Some(1),
                model_turn_id: Some("turn-1".into()),
                interrupted: false,
                duration_ms: None,
                tokens: None,
                replay: None,
                created_at: "2026-07-21T00:00:01Z".into(),
            },
            ContextItem::Assistant {
                id: "ctx_assistant".into(),
                content: "正在读取".into(),
                round: Some(1),
                model_turn_id: Some("turn-1".into()),
                interrupted: false,
                sources: Vec::new(),
                created_at: "2026-07-21T00:00:01Z".into(),
            },
            ContextItem::Tool {
                id: "ctx_local_tool".into(),
                tool_name: "read".into(),
                round: Some(1),
                model_turn_id: Some("turn-1".into()),
                provider_call_id: None,
                requested_input: None,
                input: serde_json::from_value(json!({"path":"a.txt"})).unwrap(),
                result: ToolResult {
                    success: true,
                    output: "file contents".into(),
                    images: Vec::new(),
                    diff: None,
                    executed_at: "2026-07-21T00:00:02Z".into(),
                    duration_ms: 1,
                },
                subagent: None,
                notice: None,
                attestation: String::new(),
                created_at: "2026-07-21T00:00:02Z".into(),
            },
            ContextItem::User {
                id: "ctx_followup".into(),
                content: "继续".into(),
                images: Vec::new(),
                files: Vec::new(),
                created_at: "2026-07-21T00:00:03Z".into(),
            },
        ];

        let mut projected_ids = Vec::new();
        for (format, expected_family, expected_prefix) in [
            (ProviderFamily::OpenaiChat, "openai-chat", "call_"),
            (ProviderFamily::OpenaiResponses, "openai-responses", "call_"),
            (ProviderFamily::Anthropic, "anthropic", "toolu_"),
        ] {
            request.provider.family = format;
            let payload = step_json(&request);
            assert_eq!(payload["family"], expected_family);
            let messages = payload["messages"].as_array().expect("ModelMessage[]");
            assert_eq!(messages.len(), 4);
            assert_eq!(messages[0]["role"], "user");
            assert_eq!(messages[0]["content"], "读取 a.txt");

            let assistant = messages[1]["content"]
                .as_array()
                .expect("assistant content parts");
            // A reasoning card without a provider payload replays as text only
            // where the protocol accepts plain reasoning text; Anthropic and
            // Responses need a signature or ciphertext and omit it, as Claude
            // Code and Codex omit blocks they never stored.
            let assistant = if format == ProviderFamily::OpenaiChat {
                assert_eq!(
                    assistant[0],
                    json!({"type":"reasoning","text":"先读取文件"})
                );
                &assistant[1..]
            } else {
                assert!(
                    assistant.iter().all(|part| part["type"] != "reasoning"),
                    "{format:?} must not replay unsigned reasoning: {assistant:?}"
                );
                &assistant[..]
            };
            assert_eq!(assistant[0], json!({"type":"text","text":"正在读取"}));
            assert_eq!(assistant[1]["type"], "tool-call");
            assert_eq!(assistant[1]["toolName"], "read");
            assert_eq!(assistant[1]["input"], json!({"path":"a.txt"}));
            let call_id = assistant[1]["toolCallId"].as_str().unwrap();
            assert!(call_id.starts_with(expected_prefix));
            assert_ne!(call_id, "ctx_local_tool");

            assert_eq!(messages[2]["role"], "tool");
            assert_eq!(messages[2]["content"][0]["toolCallId"], call_id);
            assert_eq!(messages[2]["content"][0]["toolName"], "read");
            assert_eq!(messages[2]["content"][0]["output"]["type"], "text");
            assert_eq!(
                messages[2]["content"][0]["output"]["value"],
                "file contents"
            );
            assert_eq!(messages[3], json!({"role":"user","content":"继续"}));
            assert!(!payload.to_string().contains("[Reasoning]"));
            projected_ids.push(call_id.to_owned());
        }

        let persisted = serde_json::to_string(&request.contexts).unwrap();
        for provider_field in [
            "openAiChat",
            "callId",
            "toolCallId",
            "encryptedPayload",
            "providerOptions",
            "apiFormat",
        ] {
            assert!(
                !persisted.contains(provider_field),
                "canonical timeline leaked provider field {provider_field}: {persisted}"
            );
        }
        for projected_id in projected_ids {
            assert!(
                !persisted.contains(&projected_id),
                "canonical timeline persisted transient tool id {projected_id}: {persisted}"
            );
        }
    }

    #[test]
    fn projected_history_projects_reasoning_and_skips_interrupted_fragments_before_a_new_user_turn()
    {
        let mut request = run_request(ProviderFamily::OpenaiChat);
        request.contexts = vec![
            ContextItem::Reasoning {
                id: "legacy_reasoning".into(),
                content: Some("legacy thought".into()),
                form: None,
                round: None,
                model_turn_id: None,
                interrupted: false,
                duration_ms: None,
                tokens: None,
                replay: None,
                created_at: "2026-07-21T00:00:00Z".into(),
            },
            ContextItem::Assistant {
                id: "legacy_answer".into(),
                content: "legacy answer".into(),
                round: None,
                model_turn_id: None,
                interrupted: false,
                sources: Vec::new(),
                created_at: "2026-07-21T00:00:01Z".into(),
            },
            ContextItem::Reasoning {
                id: "partial_reasoning".into(),
                content: Some("DO_NOT_REPLAY_REASONING".into()),
                form: None,
                round: Some(2),
                model_turn_id: Some("partial-turn".into()),
                interrupted: true,
                duration_ms: None,
                tokens: None,
                replay: None,
                created_at: "2026-07-21T00:00:02Z".into(),
            },
            ContextItem::Assistant {
                id: "partial_answer".into(),
                content: "DO_NOT_REPLAY_ANSWER".into(),
                round: Some(2),
                model_turn_id: Some("partial-turn".into()),
                interrupted: true,
                sources: Vec::new(),
                created_at: "2026-07-21T00:00:02Z".into(),
            },
            ContextItem::User {
                id: "later_user".into(),
                content: "new request".into(),
                images: Vec::new(),
                files: Vec::new(),
                created_at: "2026-07-21T00:00:03Z".into(),
            },
        ];

        let messages = step_request(&request).messages;
        assert_eq!(messages.len(), 2);
        let assistant = messages[0]["content"]
            .as_array()
            .expect("assistant content parts");
        assert_eq!(
            assistant[0],
            json!({"type":"reasoning","text":"legacy thought"})
        );
        assert_eq!(assistant[1], json!({"type":"text","text":"legacy answer"}));
        assert_eq!(messages[1], json!({"role":"user","content":"new request"}));

        let serialized = serde_json::to_string(&messages).unwrap();
        assert!(!serialized.contains("[Reasoning]"));
        assert!(!serialized.contains("DO_NOT_REPLAY"));
    }

    #[test]
    fn edited_context_topology_is_source_neutral_in_all_api_formats() {
        fn tool(
            id: &str,
            name: &str,
            round: Option<usize>,
            model_turn_id: Option<&str>,
        ) -> ContextItem {
            ContextItem::Tool {
                id: id.into(),
                tool_name: name.into(),
                round,
                model_turn_id: model_turn_id.map(str::to_owned),
                provider_call_id: None,
                requested_input: None,
                input: serde_json::from_value(json!({"path": format!("{id}.txt")})).unwrap(),
                result: ToolResult {
                    success: true,
                    output: format!("result:{id}"),
                    images: Vec::new(),
                    diff: None,
                    executed_at: "2026-07-22T00:00:00Z".into(),
                    duration_ms: 1,
                },
                subagent: None,
                notice: None,
                attestation: String::new(),
                created_at: "2026-07-22T00:00:00Z".into(),
            }
        }

        // Provenance surviving an edit keeps every item of one model turn on
        // that turn's id. Distinct ids are the deliberate signal that two tool
        // rounds ran sequentially (see `wire_history`), so stale metadata must
        // not otherwise change the provider-neutral projection.
        fn topology(with_stale_metadata: bool) -> Vec<ContextItem> {
            let turn = |id: &str, round: usize| -> (Option<usize>, Option<String>) {
                if with_stale_metadata {
                    (Some(round), Some(id.to_owned()))
                } else {
                    (None, None)
                }
            };
            let (first_round, first_turn) = turn("stale-first", 90);
            let (second_round, second_turn) = turn("stale-second", 91);
            let (interrupted_round, interrupted_turn) = turn("stale-interrupted", 92);
            vec![
                ContextItem::User {
                    id: "edited-user".into(),
                    content: "开始".into(),
                    images: Vec::new(),
                    files: Vec::new(),
                    created_at: "2026-07-22T00:00:00Z".into(),
                },
                ContextItem::Assistant {
                    id: "edited-assistant".into(),
                    content: "手工说明".into(),
                    round: first_round,
                    model_turn_id: first_turn.clone(),
                    interrupted: false,
                    sources: Vec::new(),
                    created_at: "2026-07-22T00:00:01Z".into(),
                },
                tool("edited-tool-a", "read", first_round, first_turn.as_deref()),
                ContextItem::Assistant {
                    id: "edited-empty-assistant".into(),
                    content: String::new(),
                    round: first_round,
                    model_turn_id: first_turn.clone(),
                    interrupted: false,
                    sources: Vec::new(),
                    created_at: "2026-07-22T00:00:02Z".into(),
                },
                ContextItem::Reasoning {
                    id: "edited-empty-reasoning".into(),
                    content: Some(String::new()),
                    form: None,
                    round: first_round,
                    model_turn_id: first_turn.clone(),
                    interrupted: false,
                    duration_ms: None,
                    tokens: None,
                    replay: None,
                    created_at: "2026-07-22T00:00:03Z".into(),
                },
                tool("edited-tool-b", "find", first_round, first_turn.as_deref()),
                ContextItem::Reasoning {
                    id: "edited-reasoning".into(),
                    content: Some("手工思考".into()),
                    form: None,
                    round: second_round,
                    model_turn_id: second_turn.clone(),
                    interrupted: false,
                    duration_ms: None,
                    tokens: None,
                    replay: None,
                    created_at: "2026-07-22T00:00:04Z".into(),
                },
                ContextItem::Assistant {
                    id: "edited-continuation".into(),
                    content: "继续说明".into(),
                    round: second_round,
                    model_turn_id: second_turn.clone(),
                    interrupted: false,
                    sources: Vec::new(),
                    created_at: "2026-07-22T00:00:05Z".into(),
                },
                tool(
                    "edited-tool-c",
                    "read",
                    second_round,
                    second_turn.as_deref(),
                ),
                ContextItem::Assistant {
                    id: "edited-interrupted".into(),
                    content: "DO_NOT_REPLAY_INTERRUPTED".into(),
                    round: interrupted_round,
                    model_turn_id: interrupted_turn,
                    interrupted: true,
                    sources: Vec::new(),
                    created_at: "2026-07-22T00:00:06Z".into(),
                },
                ContextItem::System {
                    id: "edited-system".into(),
                    content: "手工系统约束".into(),
                    local_only: false,
                    hook_execution: None,
                    tools_added: Vec::new(),
                    created_at: "2026-07-22T00:00:07Z".into(),
                },
                ContextItem::User {
                    id: "edited-followup".into(),
                    content: "继续".into(),
                    images: Vec::new(),
                    files: Vec::new(),
                    created_at: "2026-07-22T00:00:08Z".into(),
                },
            ]
        }

        for format in [
            ProviderFamily::OpenaiChat,
            ProviderFamily::OpenaiResponses,
            ProviderFamily::Anthropic,
        ] {
            let mut clean = run_request(format);
            clean.contexts = topology(false);
            let mut stale = clean.clone();
            stale.contexts = topology(true);
            assert_eq!(
                step_json(&clean),
                step_json(&stale),
                "{format:?} changed when only provenance metadata changed"
            );
        }

        let mut request = run_request(ProviderFamily::OpenaiChat);
        request.contexts = topology(true);
        let messages = step_request(&request).messages;
        assert_eq!(messages.len(), 6);
        assert_eq!(messages[0], json!({"role":"user","content":"开始"}));

        let first_turn = messages[1]["content"]
            .as_array()
            .expect("first assistant turn");
        assert_eq!(first_turn[0], json!({"type":"text","text":"手工说明"}));
        assert_eq!(
            first_turn
                .iter()
                .filter(|part| part["type"] == "tool-call")
                .count(),
            2
        );
        assert_eq!(messages[2]["role"], "tool");
        assert_eq!(messages[2]["content"].as_array().unwrap().len(), 2);

        let second_turn = messages[3]["content"]
            .as_array()
            .expect("second assistant turn");
        assert_eq!(
            second_turn[0],
            json!({"type":"reasoning","text":"手工思考"})
        );
        assert_eq!(second_turn[1], json!({"type":"text","text":"继续说明"}));
        assert_eq!(
            second_turn
                .iter()
                .filter(|part| part["type"] == "tool-call")
                .count(),
            1
        );
        assert_eq!(messages[4]["role"], "tool");
        assert_eq!(messages[4]["content"].as_array().unwrap().len(), 1);
        assert_eq!(messages[5], json!({"role":"user","content":"继续"}));
        assert!(!serde_json::to_string(&messages)
            .unwrap()
            .contains("DO_NOT_REPLAY_INTERRUPTED"));
    }

    #[test]
    fn command_tail_generation_cleanup_contract_handles_step_frame_rejection() {
        let state = AppState::default();
        let request_id = "run-step-frame-budget";
        let conversation_id = "conversation-step-frame-budget";
        let (cancellation, _) = state.begin_model_run(request_id, conversation_id).unwrap();

        let mut request = run_request(ProviderFamily::Anthropic);
        request.contexts = vec![ContextItem::User {
            id: "oversized-user".into(),
            content: "x".repeat(crate::aisdk::protocol::MAX_LINE_BYTES / 2 + 1),
            images: Vec::new(),
            files: Vec::new(),
            created_at: "2026-01-01T00:00:00Z".into(),
        }];
        let error = try_step_request_with(&request, &[], "https://api.test.invalid/v1")
            .expect_err("an over-budget message frame must be rejected before dispatch");
        assert!(error.contains("单帧"), "{error}");

        // The non-test Tauri command calls this same generation-bound cleanup
        // after every worker outcome. This unit covers the cleanup contract
        // without pretending to execute that cfg(not(test)) command wrapper.
        state
            .finish_model_run_checked(request_id, &cancellation)
            .unwrap();
        assert!(!state.conversation_model_run_active(conversation_id));
    }

    #[test]
    fn memory_execution_uses_only_host_resolved_roots() {
        // The retired system bound memory to an exact model ID and proved a
        // model could not forge one. There is no identity to forge now, so the
        // surviving property is narrower and stronger: the only thing a tool
        // call contributes is a document NAME, and the directory comes from the
        // host's own workspace path.
        let root = tempfile::tempdir().unwrap();
        let workspace = root.path().join("workspace");
        std::fs::create_dir_all(&workspace).unwrap();

        let mut request = run_request(ProviderFamily::OpenaiResponses);
        request.global_memory_enabled = true;
        request.project_memory_enabled = true;
        request.workspace_path = workspace.to_string_lossy().into_owned();
        request.tools = catalog::tool_catalog()
            .into_iter()
            .filter(|tool| tool.category == ToolCategory::Memory)
            .collect();
        request.enabled_tools = crate::mework_memory::MEMORY_TOOL_NAMES
            .iter()
            .map(|name| (*name).to_string())
            .collect();
        let state = AppState::default();

        let execution = execute_model_tool(
            &request,
            ToolCall {
                id: "call-memory".into(),
                name: "create_project_memory".into(),
                input: serde_json::from_value(json!({
                    "name": "testing",
                    "content": "Prefer deterministic integration tests.",
                    "description": "测试约定",
                }))
                .unwrap(),
            },
            &state,
            &|_, _, _| panic!("memory tools never request filesystem approval"),
            false,
        );
        assert!(execution.result.success, "{}", execution.result.output);

        // It landed in this run's own workspace, under the fixed layout.
        let written = workspace.join(".mework/memory/testing.md");
        assert_eq!(
            std::fs::read_to_string(&written).unwrap(),
            "Prefer deterministic integration tests."
        );
        assert!(
            std::fs::read_to_string(workspace.join(".mework/memory/MEMORY.md"))
                .unwrap()
                .contains("测试约定")
        );

        // The persisted timeline keeps the name but not the body.
        let persisted = tool_context(&execution, 1);
        let ContextItem::Tool { result, .. } = persisted else {
            panic!("expected a tool context");
        };
        assert!(!result.output.contains("deterministic integration tests"));

        // A name that tries to climb out of the memory directory is rejected
        // outright rather than sanitized into some other file.
        for escape in ["../../escape", r"..\escape", "sub/dir", "C:/absolute"] {
            let forged = execute_model_tool(
                &request,
                ToolCall {
                    id: "call-memory-escape".into(),
                    name: "create_project_memory".into(),
                    input: serde_json::from_value(json!({
                        "name": escape,
                        "content": "attempted escape",
                        "description": "d",
                    }))
                    .unwrap(),
                },
                &state,
                &|_, _, _| panic!("memory tools never request filesystem approval"),
                false,
            );
            assert!(!forged.result.success, "{escape} must be rejected");
        }

        // A conversation with memory off cannot call a memory tool at all,
        // even by naming one directly.
        let mut disabled = request.clone();
        disabled.global_memory_enabled = false;
        disabled.project_memory_enabled = false;
        let refused = execute_model_tool(
            &disabled,
            ToolCall {
                id: "call-memory-disabled".into(),
                name: "read_project_memory".into(),
                input: serde_json::from_value(json!({ "name": "testing" })).unwrap(),
            },
            &state,
            &|_, _, _| panic!("memory tools never request filesystem approval"),
            false,
        );
        assert!(!refused.result.success);
        assert!(refused
            .result
            .output
            .contains("This conversation has not enabled project memory"));
    }
    #[test]
    fn disabling_memory_stops_reads_writes_and_context_immediately() {
        // The retired system revoked a namespace lease mid-run. The switch is
        // now per-conversation, and the surviving property is the same one that
        // mattered: once memory is off, the run cannot read it, cannot write
        // it, and carries none of it in context.
        let root = tempfile::tempdir().unwrap();
        let workspace = root.path().join("workspace");
        std::fs::create_dir_all(workspace.join(".mework/memory")).unwrap();
        std::fs::write(workspace.join(".mework/MEWORK.md"), "PROJECT INSTRUCTIONS").unwrap();

        let mut request = run_request(ProviderFamily::OpenaiResponses);
        request.global_memory_enabled = true;
        request.project_memory_enabled = true;
        request.workspace_path = workspace.to_string_lossy().into_owned();
        request.tools = catalog::tool_catalog()
            .into_iter()
            .filter(|tool| tool.category == ToolCategory::Memory)
            .collect();
        request.enabled_tools = crate::mework_memory::MEMORY_TOOL_NAMES
            .iter()
            .map(|name| (*name).to_string())
            .collect();
        let state = AppState::default();

        let write = |request: &RunModelRequest, id: &str, name: &str| {
            execute_model_tool(
                request,
                ToolCall {
                    id: id.into(),
                    name: "create_project_memory".into(),
                    input: serde_json::from_value(json!({
                        "name": name,
                        "content": "PRIVATE BODY",
                        "description": "描述",
                    }))
                    .unwrap(),
                },
                &state,
                &|_, _, _| panic!("project memory never requests approval"),
                false,
            )
        };

        // Enabled: the write lands and the tier contributes context.
        assert!(write(&request, "call-enabled", "first").result.success);
        let enabled_context = run_memory_roots(&request)
            .render_context(&request.prompt_profile)
            .unwrap();
        assert!(enabled_context.contains("PROJECT INSTRUCTIONS"));
        assert!(enabled_context.contains("first.md"));

        // Disabled: reads and writes are both refused, and nothing new lands.
        let mut disabled = request.clone();
        disabled.global_memory_enabled = false;
        disabled.project_memory_enabled = false;
        let refused_write = write(&disabled, "call-disabled", "second");
        assert!(!refused_write.result.success);
        assert!(refused_write
            .result
            .output
            .contains("This conversation has not enabled project memory"));
        assert!(!workspace.join(".mework/memory/second.md").exists());

        let refused_read = execute_model_tool(
            &disabled,
            ToolCall {
                id: "call-disabled-read".into(),
                name: "read_project_memory".into(),
                input: serde_json::from_value(json!({ "name": "first" })).unwrap(),
            },
            &state,
            &|_, _, _| panic!("project memory never requests approval"),
            false,
        );
        assert!(!refused_read.result.success);
        assert!(!refused_read.result.output.contains("PRIVATE BODY"));

        // Re-enabling restores the same directory rather than a fresh one.
        assert!(write(&request, "call-reenabled", "third").result.success);
        assert!(workspace.join(".mework/memory/first.md").exists());
        assert!(workspace.join(".mework/memory/third.md").exists());

        // The two tiers are independent, not one switch with two names: with
        // global on and project off, the project write is refused while the
        // global read still reaches its own directory, and the refusal names
        // the tier the user actually turned off.
        let mut global_only = request.clone();
        global_only.project_memory_enabled = false;
        let refused_project = write(&global_only, "call-global-only", "fourth");
        assert!(!refused_project.result.success);
        assert!(
            refused_project
                .result
                .output
                .contains("This conversation has not enabled project memory"),
            "{}",
            refused_project.result.output
        );
        assert!(!workspace.join(".mework/memory/fourth.md").exists());
        let global_read = execute_model_tool(
            &global_only,
            ToolCall {
                id: "call-global-only-read".into(),
                name: "read_global_memory".into(),
                input: serde_json::from_value(json!({ "name": "absent" })).unwrap(),
            },
            &state,
            &|_, _, _| panic!("global reads never request approval"),
            false,
        );
        // It failed on a missing document, not on a disabled tier: the enabled
        // tier really did reach its own directory.
        assert!(!global_read.result.success);
        assert!(global_read
            .result
            .output
            .contains("No memory document named"));
        assert!(!global_read.result.output.contains("未启用"));

        // And the project tier alone still sees its own context, without one
        // byte of the global tier.
        let mut project_only = request.clone();
        project_only.global_memory_enabled = false;
        let context = run_memory_roots(&project_only)
            .render_context(&project_only.prompt_profile)
            .unwrap();
        assert!(context.contains("PROJECT INSTRUCTIONS"));
        assert!(!context.contains("全局记忆 · "));
    }

    #[test]
    fn model_global_memory_mutations_always_require_native_user_confirmation() {
        let root = tempfile::tempdir().unwrap();
        let workspace = root.path().join("workspace");
        std::fs::create_dir_all(&workspace).unwrap();

        let base = |level: SecurityLevel| {
            let mut request = run_request(ProviderFamily::OpenaiResponses);
            request.global_memory_enabled = true;
            request.project_memory_enabled = true;
            request.workspace_path = workspace.to_string_lossy().into_owned();
            request.security_level = level;
            request.tools = catalog::tool_catalog()
                .into_iter()
                .filter(|tool| tool.category == ToolCategory::Memory)
                .collect();
            request.enabled_tools = crate::mework_memory::MEMORY_TOOL_NAMES
                .iter()
                .map(|name| (*name).to_string())
                .collect();
            request
        };

        // Writing global memory affects every workspace, so it demands a native
        // confirmation in every security level — `full_access` included — and a
        // permission hook must not be able to suppress that circuit breaker.
        for level in [
            SecurityLevel::RequestApproval,
            SecurityLevel::AllowEdits,
            SecurityLevel::FullAccess,
        ] {
            for tool in ["create_global_memory", "edit_global_memory"] {
                let request = base(level);
                let approvals = std::sync::atomic::AtomicUsize::new(0);
                let execution = execute_model_tool(
                    &request,
                    ToolCall {
                        id: format!("call-global-{level:?}-{tool}"),
                        name: tool.into(),
                        input: serde_json::from_value(json!({
                            "name": "cross-project",
                            "content": "Attempted cross-project persistence.",
                            "old_text": "a",
                            "new_text": "b",
                            "description": "d",
                        }))
                        .unwrap(),
                    },
                    &AppState::default(),
                    &|_, _, _| {
                        approvals.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                        Ok(false)
                    },
                    true,
                );

                assert!(!execution.result.success, "{level:?} {tool}");
                assert!(
                    execution
                        .result
                        .output
                        .contains("The user declined to modify cross-project global memory"),
                    "{level:?} {tool}: {}",
                    execution.result.output
                );
                assert_eq!(
                    approvals.load(std::sync::atomic::Ordering::SeqCst),
                    1,
                    "{level:?} {tool}"
                );
            }
        }

        // A denied global write left nothing on disk.
        assert!(!root.path().join(".mework").exists());

        // Project writes stay inside one workspace, so they never enter the
        // global circuit breaker.
        let request = base(SecurityLevel::FullAccess);
        let project = execute_model_tool(
            &request,
            ToolCall {
                id: "call-project".into(),
                name: "create_project_memory".into(),
                input: serde_json::from_value(json!({
                    "name": "project-only",
                    "content": "Project-only persistence.",
                    "description": "仅本项目",
                }))
                .unwrap(),
            },
            &AppState::default(),
            &|_, _, _| panic!("project memory must not enter the global circuit breaker"),
            true,
        );
        assert!(project.result.success, "{}", project.result.output);
        assert!(workspace.join(".mework/memory/project-only.md").exists());
    }

    #[test]
    fn a_named_agent_shares_the_two_tiers_and_never_gets_its_own_partition() {
        // The retired system gave each named agent a private memory partition
        // keyed by definition identity, and this test proved the scope came
        // from the host rather than a model argument. Partitions are gone:
        // a named agent now reads and writes the SAME two tiers as its parent,
        // and its definition only decides whether it gets the tools at all.
        let root = tempfile::tempdir().unwrap();
        let workspace = root.path().join("workspace");
        std::fs::create_dir_all(&workspace).unwrap();

        let mut parent = run_request(ProviderFamily::OpenaiResponses);
        parent.global_memory_enabled = true;
        parent.project_memory_enabled = true;
        parent.workspace_path = workspace.to_string_lossy().into_owned();
        parent.tools = catalog::tool_catalog();
        parent.enabled_tools = crate::mework_memory::MEMORY_TOOL_NAMES
            .iter()
            .map(|name| (*name).to_string())
            .collect();

        // The parent writes one project memory.
        let state = AppState::default();
        assert!(
            execute_model_tool(
                &parent,
                ToolCall {
                    id: "call-parent".into(),
                    name: "create_project_memory".into(),
                    input: serde_json::from_value(json!({
                        "name": "shared",
                        "content": "SHARED BODY",
                        "description": "共享",
                    }))
                    .unwrap(),
                },
                &state,
                &|_, _, _| panic!("project memory never requests approval"),
                false,
            )
            .result
            .success
        );

        // An ordinary child inherits the switch and sees the same document —
        // not an empty private partition.
        let child = agent_child_template(&parent);
        assert!(child.memory_enabled());
        let read = execute_model_tool(
            &child,
            ToolCall {
                id: "call-child".into(),
                name: "read_project_memory".into(),
                input: serde_json::from_value(json!({ "name": "shared" })).unwrap(),
            },
            &state,
            &|_, _, _| panic!("project memory never requests approval"),
            false,
        );
        assert!(read.result.success, "{}", read.result.output);
        assert_eq!(read.result.output, "SHARED BODY");

        // A parent with memory off cannot hand memory to a child.
        let mut disabled_parent = parent.clone();
        disabled_parent.global_memory_enabled = false;
        disabled_parent.project_memory_enabled = false;
        assert!(!agent_child_template(&disabled_parent).memory_enabled());
    }

    /// The renderer needs a timeline id the moment a call is announced, and the
    /// host builds its card much later. Both derive that id from the same four
    /// facts, so the streaming row and the persisted card are one entry. When
    /// each side minted its own instead, the renderer's id reached disk while
    /// the host's receipt stayed bound to its own — and since that receipt keys
    /// on the context id, the card could never be saved again.
    #[test]
    fn the_announced_and_persisted_ids_of_one_call_agree() {
        let request = run_request(ProviderFamily::Anthropic);
        let execution = ToolExecution {
            call: ToolCall {
                id: "provider-call-1".into(),
                name: "read".into(),
                input: serde_json::from_value(json!({"path": "README.md"})).unwrap(),
            },
            result: ToolResult {
                success: true,
                output: "ok".into(),
                images: Vec::new(),
                diff: None,
                executed_at: "2026-08-09T00:00:00Z".into(),
                duration_ms: 1,
            },
            subagent: None,
        };
        let announced = stamp_announced_context_id(
            ModelStreamEvent::ToolCallAnnounced {
                round: 2,
                call_id: execution.call.id.clone(),
                tool_name: execution.call.name.clone(),
                context_id: String::new(),
            },
            &request.conversation_id,
            &request.request_id,
        );
        let ModelStreamEvent::ToolCallAnnounced { context_id, .. } = &announced else {
            panic!("stamping must preserve the announcement");
        };
        let context = tool_context_for_turn(
            &execution,
            2,
            "model-turn",
            None,
            &request.conversation_id,
            &request.request_id,
            &AppState::default(),
        );

        assert_eq!(context.id(), context_id);
        assert!(!context_id.is_empty());
        // The provider's own call id is transient and untrusted, so it must not
        // survive into the local id it seeds.
        assert!(!context_id.contains("provider-call-1"));

        // Two conversations that both start at the provider's first call id
        // must not collide: persistence requires ids to be unique across the
        // whole document, not just within one conversation.
        assert_ne!(
            tool_context_id(&request.conversation_id, "run-a", 2, &execution.call.id),
            tool_context_id("another-conversation", "run-a", 2, &execution.call.id)
        );
        assert_ne!(
            tool_context_id(&request.conversation_id, "run-a", 2, &execution.call.id),
            tool_context_id(&request.conversation_id, "run-a", 3, &execution.call.id)
        );
        // The round counter restarts at 1 for every run, so the run itself has
        // to separate them. Without this, a second run whose first round reuses
        // the provider's call id — which providers that omit ids make routine,
        // since the sidecar then synthesizes stream-local ones — addresses the
        // first run's row and the store updates it instead of inserting.
        assert_ne!(
            tool_context_id(&request.conversation_id, "run-a", 1, &execution.call.id),
            tool_context_id(&request.conversation_id, "run-b", 1, &execution.call.id)
        );
    }

    /// A child's cards live in the parent's conversation and are committed by
    /// the parent card's fingerprint, so their ids have to agree just as
    /// exactly — a nested mismatch invalidates the whole parent card. A child
    /// run has no `request_id`, so the parent's run scope must not reach the
    /// child's announcement: the child builds its own card from an empty scope.
    #[test]
    fn a_nested_announcement_is_stamped_like_a_top_level_one() {
        let nested = stamp_announced_context_id(
            ModelStreamEvent::SubagentEvent {
                round: 1,
                call_id: "parent-call".into(),
                event: Box::new(ModelStreamEvent::ToolCallAnnounced {
                    round: 1,
                    call_id: "child-call".into(),
                    tool_name: "read".into(),
                    context_id: String::new(),
                }),
            },
            "conversation-1",
            "parent-run",
        );
        let ModelStreamEvent::SubagentEvent { event, .. } = nested else {
            panic!("stamping must preserve the envelope");
        };
        let ModelStreamEvent::ToolCallAnnounced { context_id, .. } = *event else {
            panic!("stamping must preserve the nested announcement");
        };
        assert_eq!(
            context_id,
            tool_context_id("conversation-1", "", 1, "child-call")
        );
    }

    /// Cross-language contract: renderer and host derive the same ids. Any shape
    /// change must fail tests on both sides, preventing silent host-body rejection
    /// by `conversations::update` when context ids diverge.
    #[test]
    fn the_derived_hook_identity_matches_the_renderer() {
        assert_eq!(
            hook_context_id("run_cancelled", "exec_1", "display", 0),
            "ctx_hook_run_cancelled_exec_1_display_0"
        );
        assert_eq!(
            hook_context_id("run_cancelled", "exec_1", "injection", 0),
            "ctx_hook_run_cancelled_exec_1_injection_0"
        );
        let base = hook_context_id("run_cancelled", "exec_1", "display", 0);
        for (request, execution, purpose, index) in [
            ("run_other", "exec_1", "display", 0),
            ("run_cancelled", "exec_2", "display", 0),
            ("run_cancelled", "exec_1", "injection", 0),
            ("run_cancelled", "exec_1", "display", 1),
        ] {
            assert_ne!(base, hook_context_id(request, execution, purpose, index));
        }
    }

    #[test]
    fn the_derived_prose_identity_matches_the_renderer() {
        assert_eq!(
            round_prose_context_id("run_1", 1, "assistant"),
            "ctx_assistant_run_1_1"
        );
        assert_eq!(
            round_prose_context_id("run_1", 2, "reasoning"),
            "ctx_reasoning_run_1_2"
        );
        assert_eq!(round_model_turn_id("run_1", 3), "model-turn-run_1-3");

        // Context ids must be document-unique across different rounds and runs.
        assert_ne!(
            round_prose_context_id("run_1", 1, "assistant"),
            round_prose_context_id("run_1", 2, "assistant")
        );
        assert_ne!(
            round_prose_context_id("run_1", 1, "assistant"),
            round_prose_context_id("run_2", 1, "assistant")
        );
        assert_ne!(
            round_prose_context_id("run_1", 1, "assistant"),
            round_prose_context_id("run_1", 1, "reasoning")
        );
    }

    /// The ledger's streaming row and final canonical context share an id, so final
    /// prose replaces rather than duplicates the row.
    #[test]
    fn a_rounds_streaming_row_and_its_canonical_context_share_one_id() {
        let streaming = ProseRound::new("run_9", 4);
        assert_eq!(
            streaming.assistant_id,
            round_identity("run_9", 4, "assistant").unwrap()
        );
        assert_eq!(
            streaming.reasoning_id,
            round_identity("run_9", 4, "reasoning").unwrap()
        );

        // Child runs have no round token and do not write the parent timeline, so
        // they have no derivable identity and use minted ids.
        assert!(round_identity("", 1, "assistant").is_none());
        let childless = ProseRound::new("", 1);
        assert!(childless.assistant_id.starts_with("ctx_assistant_"));
        assert_ne!(childless.assistant_id, ProseRound::new("", 1).assistant_id);
    }

    /// A run's output as the journal and the settlement write it, against a real
    /// store. The journal has appended the round's streaming prose (its throttle
    /// fired mid-text; the reasoning was too short to reach a write) before the
    /// stream ends. Settlement then mints the reasoning cards, replaces the prose
    /// in place, and appends the tool card — and the rows must read in the run's
    /// order, with the reasoning persisted the moment it is minted rather than at
    /// the round-end checkpoint, after every tool has run.
    #[test]
    fn settled_reasoning_is_persisted_at_once_and_files_ahead_of_streamed_prose() {
        let directory = tempfile::tempdir().unwrap();
        let store = Arc::new(
            crate::conversation_store::ConversationStore::open(
                &directory
                    .path()
                    .join(crate::conversation_store::DATABASE_FILE_NAME),
            )
            .unwrap(),
        );
        let user = ContextItem::User {
            id: "user-1".into(),
            content: "Read the file.".into(),
            images: Vec::new(),
            files: Vec::new(),
            created_at: "2026-09-05T00:00:00Z".into(),
        };
        store
            .put_conversation(
                "ws",
                &crate::model::Conversation {
                    id: "conv_order".into(),
                    title: "order".into(),
                    created_at: "2026-09-05T00:00:00.000Z".into(),
                    updated_at: "2026-09-05T00:00:00.000Z".into(),
                    settings: serde_json::from_value(json!({
                        "enabledTools": [],
                    }))
                    .unwrap(),
                    contexts: vec![user],
                    queued_messages: Vec::new(),
                    branches: Vec::new(),
                    user_aborted_tasks: Vec::new(),
                    worktrees: Vec::new(),
                    run_target: None,
                    additional_directories: Vec::new(),
                    parent_conversation_id: None,
                    fork_of: None,
                    handoff_of: None,
                    preset_id: String::new(),
                    template_id: String::new(),
                    attached_workspaces: Vec::new(),
                },
            )
            .unwrap();
        let sink = || ConversationSink {
            store: Arc::clone(&store),
            conversation_id: "conv_order".into(),
            request_id: "run_9".into(),
        };
        let ids = || {
            store
                .conversation("conv_order")
                .unwrap()
                .unwrap()
                .contexts
                .iter()
                .map(|context| context.id().to_owned())
                .collect::<Vec<_>>()
        };
        let model_turn_id = round_model_turn_id("run_9", 1);

        // The journal's throttled write lands while the prose is still streaming.
        let journal = ProseJournal::new(sink(), "run_9", ReasoningForm::Plaintext);
        let mut streamed = ProseRound::new("run_9", 1);
        streamed.text = "Let me read".into();
        journal.write(&streamed);
        assert_eq!(ids(), vec!["user-1", "ctx_assistant_run_9_1"]);

        let mut generated = GeneratedContexts::new(Some(sink()), Some("user-1".into()));
        generated.extend(round_reasoning_contexts(
            &["Which file?".into(), "README, surely.".into()],
            ReasoningStats {
                duration_ms: Some(400),
                tokens: Some(12),
            },
            "run_9",
            1,
            &model_turn_id,
            ReasoningForm::Plaintext,
            RoundReasoningReplay::default(),
        ));
        // Minted cards reach disk before any checkpoint, filed behind the run's
        // anchor and therefore ahead of the streamed prose.
        assert_eq!(
            ids(),
            vec![
                "user-1",
                "ctx_reasoning_run_9_1",
                "ctx_reasoning_run_9_1_1",
                "ctx_assistant_run_9_1"
            ]
        );
        generated.push(model_assistant_context(
            round_identity("run_9", 1, "assistant"),
            "Let me read the file.".into(),
            1,
            &model_turn_id,
            Vec::new(),
        ));
        let tool_id = tool_context_id("conv_order", "run_9", 1, "call-1");
        generated.push(ContextItem::Tool {
            id: tool_id.clone(),
            tool_name: "read".into(),
            round: Some(1),
            model_turn_id: Some(model_turn_id.clone()),
            provider_call_id: None,
            requested_input: None,
            input: serde_json::from_value(json!({"path": "README.md"})).unwrap(),
            result: ToolResult {
                success: true,
                output: "# Mework".into(),
                images: Vec::new(),
                diff: None,
                executed_at: "2026-09-05T00:00:03Z".into(),
                duration_ms: 1,
            },
            subagent: None,
            notice: None,
            attestation: "sig".into(),
            created_at: "2026-09-05T00:00:03Z".into(),
        });

        // Round 2: the journal again gets its prose row down first. This card's
        // predecessor is round 1's tool card, not the run anchor, and the card must
        // be filed between the two.
        let second_turn_id = round_model_turn_id("run_9", 2);
        let mut streamed = ProseRound::new("run_9", 2);
        streamed.text = "It says".into();
        journal.write(&streamed);
        generated.extend(round_reasoning_contexts(
            &["Summarise it.".into()],
            ReasoningStats::default(),
            "run_9",
            2,
            &second_turn_id,
            ReasoningForm::Plaintext,
            RoundReasoningReplay::default(),
        ));
        assert_eq!(
            ids(),
            vec![
                "user-1".to_owned(),
                "ctx_reasoning_run_9_1".to_owned(),
                "ctx_reasoning_run_9_1_1".to_owned(),
                "ctx_assistant_run_9_1".to_owned(),
                tool_id,
                "ctx_reasoning_run_9_2".to_owned(),
                "ctx_assistant_run_9_2".to_owned(),
            ]
        );
        generated.push(model_assistant_context(
            round_identity("run_9", 2, "assistant"),
            "It says Mework.".into(),
            2,
            &second_turn_id,
            Vec::new(),
        ));
        let items = generated.into_items();

        let persisted = store.conversation("conv_order").unwrap().unwrap().contexts;
        let mut expected = vec!["user-1".to_owned()];
        expected.extend(items.iter().map(|item| item.id().to_owned()));
        assert_eq!(
            persisted
                .iter()
                .map(|item| item.id().to_owned())
                .collect::<Vec<_>>(),
            expected
        );
        assert!(matches!(
            &persisted[3],
            ContextItem::Assistant { content, interrupted: false, .. } if content == "Let me read the file."
        ));
        assert!(matches!(
            &persisted[6],
            ContextItem::Assistant { content, interrupted: false, .. } if content == "It says Mework."
        ));
        assert_eq!(store.reconcile_streaming_in("conv_order").unwrap(), 0);
    }

    /// A store holding one conversation with a single user context, plus a sink
    /// factory and an id reader for it.
