    fn persisted_ids(
        store: &crate::conversation_store::ConversationStore,
        conversation_id: &str,
    ) -> Vec<String> {
        store
            .conversation(conversation_id)
            .unwrap()
            .unwrap()
            .contexts
            .iter()
            .map(|context| context.id().to_owned())
            .collect()
    }

    #[test]
    fn a_missing_persistence_sink_cannot_bypass_the_exit_journal_registry() {
        let directory = tempfile::tempdir().unwrap();
        let blocker = directory.path().join("not-a-directory");
        std::fs::write(&blocker, "block store creation").unwrap();
        let mut request = run_request(ProviderFamily::OpenaiResponses);
        request.app_data_path = blocker.to_string_lossy().into_owned();
        let delivered = std::sync::atomic::AtomicUsize::new(0);
        let result = run_model(
            request,
            &AppState::default(),
            &|_| {
                delivered.fetch_add(1, Ordering::Relaxed);
                Ok(())
            },
            &|_, _, _| Ok(true),
        );
        assert!(result.unwrap_err().contains("拒绝启动无法持久化的顶层运行"));
        assert_eq!(delivered.load(Ordering::Relaxed), 0);
    }

    #[test]
    fn every_displayable_delta_survives_an_immediate_host_restart() {
        let (store, directory) = journal_fixture("conv_exit_delta");
        let registry = ProseJournalRegistry::default();
        let journal = registry
            .register(ProseJournal::new(
                ConversationSink {
                    store: Arc::clone(&store),
                    conversation_id: "conv_exit_delta".into(),
                    request_id: "run_exit_delta".into(),
                },
                "run_exit_delta",
                ReasoningForm::Plaintext,
            ))
            .unwrap();
        let first = ModelStreamEvent::TextDelta {
            round: 1,
            delta: "first".into(),
        };
        let displayed = std::sync::Mutex::new(Vec::new());
        journal
            .deliver(first, &|event| {
                displayed.lock().unwrap().push(event);
                Ok(())
            })
            .unwrap();
        assert_eq!(displayed.lock().unwrap().len(), 1);
        assert_eq!(persisted_ids(&store, "conv_exit_delta").len(), 1);
        assert!(journal.note(&ModelStreamEvent::TextDelta {
            round: 1,
            delta: " and last".into()
        }));
        assert!(journal.note(&ModelStreamEvent::ReasoningDelta {
            round: 1,
            item: 0,
            delta: "reasoning tail".into(),
        }));
        registry.flush_for_exit().unwrap();
        assert!(!journal.note(&ModelStreamEvent::TextDelta {
            round: 1,
            delta: "too late".into()
        }));
        drop(journal);
        drop(registry);
        drop(store);
        let reopened = crate::conversation_store::ConversationStore::open(
            &directory
                .path()
                .join(crate::conversation_store::DATABASE_FILE_NAME),
        )
        .unwrap();
        assert_eq!(reopened.reconcile_streaming().unwrap(), 0);
        let contexts = reopened
            .conversation("conv_exit_delta")
            .unwrap()
            .unwrap()
            .contexts;
        assert!(contexts.iter().any(|item| matches!(item,
            ContextItem::Assistant { content, interrupted: true, .. } if content == "first and last"
        )));
        assert!(contexts.iter().any(|item| matches!(item,
            ContextItem::Reasoning { content: Some(content), interrupted: true, .. } if content == "reasoning tail"
        )));
    }

    #[test]
    fn registered_ledger_drop_flushes_unclaimed_tails_but_preserves_canonical_cards() {
        for canonical in [false, true] {
            let (store, _directory) = journal_fixture("conv_exit_drop");
            let registry = ProseJournalRegistry::default();
            let journal = registry
                .register(ProseJournal::new(
                    ConversationSink {
                        store: Arc::clone(&store),
                        conversation_id: "conv_exit_drop".into(),
                        request_id: "run_exit_drop".into(),
                    },
                    "run_exit_drop",
                    ReasoningForm::Plaintext,
                ))
                .unwrap();
            let mut generated = GeneratedContexts::new(
                Some(ConversationSink {
                    store: Arc::clone(&store),
                    conversation_id: "conv_exit_drop".into(),
                    request_id: "run_exit_drop".into(),
                }),
                Some("user-1".into()),
            );
            generated.journal = Some(Arc::clone(&journal));
            journal.note(&ModelStreamEvent::TextDelta {
                round: 1,
                delta: "unsettled tail".into(),
            });
            if canonical {
                generated.push(model_assistant_context(
                    round_identity("run_exit_drop", 1, "assistant"),
                    "canonical answer".into(),
                    1,
                    &round_model_turn_id("run_exit_drop", 1),
                    Vec::new(),
                ));
            }
            drop(generated);
            registry.complete(&journal);
            assert!(registry.journals.lock().unwrap().is_empty());
            registry.flush_for_exit().unwrap();
            let contexts = store
                .conversation("conv_exit_drop")
                .unwrap()
                .unwrap()
                .contexts;
            let expected = if canonical {
                "canonical answer"
            } else {
                "unsettled tail"
            };
            assert!(contexts.iter().any(|item| matches!(item,
                ContextItem::Assistant { content, interrupted, .. } if content == expected && *interrupted != canonical
            )));
            assert_eq!(store.reconcile_streaming().unwrap(), 0);
        }
    }

    #[test]
    fn exit_snapshot_keeps_previous_rounds_until_their_canonical_writes_confirm() {
        for retry_canonical in [false, true] {
            let (store, directory) = journal_fixture("conv_exit_rounds");
            let registry = ProseJournalRegistry::default();
            let journal = registry
                .register(ProseJournal::new(
                    ConversationSink {
                        store: Arc::clone(&store),
                        conversation_id: "conv_exit_rounds".into(),
                        request_id: "run_exit_rounds".into(),
                    },
                    "run_exit_rounds",
                    ReasoningForm::Plaintext,
                ))
                .unwrap();
            let mut generated = GeneratedContexts::new(
                Some(ConversationSink {
                    store: Arc::clone(&store),
                    conversation_id: "conv_exit_rounds".into(),
                    request_id: "run_exit_rounds".into(),
                }),
                Some("user-1".into()),
            );
            generated.journal = Some(Arc::clone(&journal));
            journal.note(&ModelStreamEvent::TextDelta {
                round: 1,
                delta: "first streamed".into(),
            });
            let connection = rusqlite::Connection::open(
                directory
                    .path()
                    .join(crate::conversation_store::DATABASE_FILE_NAME),
            )
            .unwrap();
            connection.execute_batch(
                "CREATE TRIGGER block_round_insert BEFORE INSERT ON context BEGIN SELECT RAISE(FAIL, 'round write failure'); END;
                 CREATE TRIGGER block_round_update BEFORE UPDATE ON context BEGIN SELECT RAISE(FAIL, 'round write failure'); END;"
            ).unwrap();
            generated.push(model_assistant_context(
                round_identity("run_exit_rounds", 1, "assistant"),
                "first canonical".into(),
                1,
                &round_model_turn_id("run_exit_rounds", 1),
                Vec::new(),
            ));
            assert!(!generated.checkpoint());
            journal.round_settled(1, &generated);
            journal.note(&ModelStreamEvent::TextDelta {
                round: 2,
                delta: "second streamed".into(),
            });
            connection
                .execute_batch("DROP TRIGGER block_round_insert; DROP TRIGGER block_round_update;")
                .unwrap();
            if retry_canonical {
                assert!(generated.checkpoint());
            }
            registry.flush_for_exit().unwrap();
            drop(generated);
            let contexts = store
                .conversation("conv_exit_rounds")
                .unwrap()
                .unwrap()
                .contexts;
            let first = if retry_canonical {
                "first canonical"
            } else {
                "first streamed"
            };
            assert!(contexts.iter().any(|item| matches!(item,
                ContextItem::Assistant { content, interrupted, .. } if content == first && *interrupted != retry_canonical
            )));
            assert!(contexts.iter().any(|item| matches!(item,
                ContextItem::Assistant { content, interrupted: true, .. } if content == "second streamed"
            )));
            assert_eq!(store.reconcile_streaming().unwrap(), 0);
        }
    }

    #[test]
    fn exit_snapshot_preserves_the_last_attempt_during_retry_backoff() {
        let (store, _directory) = journal_fixture("conv_exit_retry");
        let registry = ProseJournalRegistry::default();
        let journal = registry
            .register(ProseJournal::new(
                ConversationSink {
                    store: Arc::clone(&store),
                    conversation_id: "conv_exit_retry".into(),
                    request_id: "run_exit_retry".into(),
                },
                "run_exit_retry",
                ReasoningForm::Plaintext,
            ))
            .unwrap();
        journal.note(&ModelStreamEvent::TextDelta {
            round: 1,
            delta: "prefix".into(),
        });
        flush_journal(&journal);
        journal.commit(1);
        journal.note(&ModelStreamEvent::TextDelta {
            round: 1,
            delta: " unsaved attempt".into(),
        });
        journal.note(&ModelStreamEvent::ReasoningDelta {
            round: 1,
            item: 0,
            delta: "unsaved thought".into(),
        });
        journal.note(&ModelStreamEvent::StreamRetryScheduled {
            round: 1,
            attempt: 1,
            max_attempts: 3,
            delay_ms: 0,
            message: "retry".into(),
        });
        assert_eq!(journal.state.lock().unwrap().text, "prefix");
        registry.flush_for_exit().unwrap();
        registry.flush_for_exit().unwrap();
        let contexts = store
            .conversation("conv_exit_retry")
            .unwrap()
            .unwrap()
            .contexts;
        assert!(contexts.iter().any(|item| matches!(item,
            ContextItem::Assistant { content, interrupted: true, .. } if content == "prefix unsaved attempt"
        )));
        assert!(contexts.iter().any(|item| matches!(item,
            ContextItem::Reasoning { content: Some(content), interrupted: true, .. } if content == "unsaved thought"
        )));
    }

    #[test]
    fn exit_snapshot_write_failure_keeps_the_barrier_closed_and_retries_the_same_tail() {
        let (store, directory) = journal_fixture("conv_exit_failure");
        let registry = ProseJournalRegistry::default();
        let journal = registry
            .register(ProseJournal::new(
                ConversationSink {
                    store: Arc::clone(&store),
                    conversation_id: "conv_exit_failure".into(),
                    request_id: "run_exit_failure".into(),
                },
                "run_exit_failure",
                ReasoningForm::Plaintext,
            ))
            .unwrap();
        journal.note(&ModelStreamEvent::TextDelta {
            round: 1,
            delta: "prefix".into(),
        });
        flush_journal(&journal);
        journal.note(&ModelStreamEvent::TextDelta {
            round: 1,
            delta: " tail".into(),
        });
        journal.note(&ModelStreamEvent::ReasoningDelta {
            round: 1,
            item: 0,
            delta: "thought".into(),
        });
        let connection = rusqlite::Connection::open(
            directory
                .path()
                .join(crate::conversation_store::DATABASE_FILE_NAME),
        )
        .unwrap();
        connection.execute_batch(
            "CREATE TRIGGER block_exit_insert BEFORE INSERT ON context BEGIN SELECT RAISE(FAIL, 'exit disk failure'); END;
             CREATE TRIGGER block_exit_update BEFORE UPDATE ON context BEGIN SELECT RAISE(FAIL, 'exit disk failure'); END;"
        ).unwrap();
        assert!(registry
            .flush_for_exit()
            .unwrap_err()
            .contains("exit disk failure"));
        assert!(!journal.state.lock().unwrap().finished);
        assert!(!journal.note(&ModelStreamEvent::TextDelta {
            round: 1,
            delta: "forbidden".into()
        }));
        assert!(registry
            .register(ProseJournal::new(
                ConversationSink {
                    store: Arc::clone(&store),
                    conversation_id: "conv_exit_failure".into(),
                    request_id: "late".into()
                },
                "late",
                ReasoningForm::Plaintext,
            ))
            .is_err());
        connection
            .execute_batch("DROP TRIGGER block_exit_insert; DROP TRIGGER block_exit_update;")
            .unwrap();
        registry.flush_for_exit().unwrap();
        let contexts = store
            .conversation("conv_exit_failure")
            .unwrap()
            .unwrap()
            .contexts;
        assert!(contexts.iter().any(|item| matches!(item,
            ContextItem::Assistant { content, interrupted: true, .. } if content == "prefix tail"
        )));
        assert_eq!(store.reconcile_streaming().unwrap(), 0);
    }

    #[test]
    fn exit_snapshot_linearizes_with_a_concurrent_delta_without_reopening_streaming() {
        for iteration in 0..8 {
            let (store, _directory) = journal_fixture("conv_exit_race");
            let registry = Arc::new(ProseJournalRegistry::default());
            let journal = registry
                .register(ProseJournal::new(
                    ConversationSink {
                        store: Arc::clone(&store),
                        conversation_id: "conv_exit_race".into(),
                        request_id: format!("race_{iteration}"),
                    },
                    &format!("race_{iteration}"),
                    ReasoningForm::Plaintext,
                ))
                .unwrap();
            journal.note(&ModelStreamEvent::TextDelta {
                round: 1,
                delta: "prefix".into(),
            });
            let start = Arc::new(std::sync::Barrier::new(2));
            let worker = {
                let start = Arc::clone(&start);
                let journal = Arc::clone(&journal);
                std::thread::spawn(move || {
                    start.wait();
                    journal.note(&ModelStreamEvent::TextDelta {
                        round: 1,
                        delta: " accepted".into(),
                    })
                })
            };
            start.wait();
            registry.flush_for_exit().unwrap();
            let accepted = worker.join().unwrap();
            let expected = if accepted {
                "prefix accepted"
            } else {
                "prefix"
            };
            let contexts = store
                .conversation("conv_exit_race")
                .unwrap()
                .unwrap()
                .contexts;
            assert!(contexts.iter().any(|item| matches!(item,
                ContextItem::Assistant { content, interrupted: true, .. } if content == expected
            )));
            assert_eq!(store.reconcile_streaming().unwrap(), 0);
        }
    }

    /// Forces the journal's throttled write for whatever it has buffered.
    fn flush_journal(journal: &ProseJournal) {
        let state = journal
            .state
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        journal.write(&state);
    }

    /// The journal has put round 1's streaming reasoning and text on disk for an
    /// attempt that then fails. The retry announcement empties the buffers but
    /// leaves the rows: the replacement attempt is journaled from the start of
    /// the step, so what lands is that attempt's text alone rather than both
    /// attempts run together, and until it lands the failed attempt's rows are
    /// still the newest prose the round has. When the round then settles
    /// without any reasoning — the retried attempt answered straight away —
    /// the reasoning row no card claimed is dropped at settlement, so nothing
    /// is left for reconciliation to turn into an interrupted card for a round
    /// that in fact completed.
    #[test]
    fn a_retry_restarts_the_journal_and_settlement_drops_the_row_no_card_claims() {
        let (store, _directory) = journal_fixture("conv_retry");
        let sink = || ConversationSink {
            store: Arc::clone(&store),
            conversation_id: "conv_retry".into(),
            request_id: "run_retry".into(),
        };
        let journal = ProseJournal::new(sink(), "run_retry", ReasoningForm::Encrypted);
        journal.note(&ModelStreamEvent::ReasoningDelta {
            round: 1,
            item: 0,
            delta: "先想想".into(),
        });
        journal.note(&ModelStreamEvent::TextDelta {
            round: 1,
            delta: "第一次尝试".into(),
        });
        flush_journal(&journal);
        assert_eq!(
            persisted_ids(&store, "conv_retry"),
            vec![
                "user-1",
                "ctx_reasoning_run_retry_1",
                "ctx_assistant_run_retry_1"
            ]
        );

        journal.note(&ModelStreamEvent::StreamRetryScheduled {
            round: 1,
            attempt: 1,
            max_attempts: 3,
            delay_ms: 0,
            message: "socket closed".into(),
        });
        // The rows stay; the buffers restart.
        assert_eq!(
            persisted_ids(&store, "conv_retry"),
            vec![
                "user-1",
                "ctx_reasoning_run_retry_1",
                "ctx_assistant_run_retry_1"
            ]
        );
        {
            let state = journal.state.lock().unwrap();
            assert_eq!(state.round, 1);
            assert!(state.text.is_empty() && state.reasoning.is_empty());
        }

        // The retried attempt answers without reasoning.
        journal.note(&ModelStreamEvent::TextDelta {
            round: 1,
            delta: "第二次尝试".into(),
        });
        flush_journal(&journal);
        let streamed = store.conversation("conv_retry").unwrap().unwrap().contexts;
        assert_eq!(streamed.len(), 3, "{streamed:?}");
        assert!(matches!(
            &streamed[1],
            ContextItem::Reasoning { content, .. } if content.as_deref() == Some("先想想")
        ));
        assert!(matches!(
            &streamed[2],
            ContextItem::Assistant { id, content, .. }
                if id == "ctx_assistant_run_retry_1" && content == "第二次尝试"
        ));

        let model_turn_id = round_model_turn_id("run_retry", 1);
        let mut generated = GeneratedContexts::new(Some(sink()), Some("user-1".into()));
        generated.extend(round_reasoning_contexts(
            &[],
            ReasoningStats::default(),
            "run_retry",
            1,
            &model_turn_id,
            ReasoningForm::Encrypted,
            RoundReasoningReplay::default(),
        ));
        generated.push(model_assistant_context(
            round_identity("run_retry", 1, "assistant"),
            "第二次尝试。".into(),
            1,
            &model_turn_id,
            Vec::new(),
        ));
        journal.round_settled(1, &generated);
        generated.into_items();

        let persisted = store.conversation("conv_retry").unwrap().unwrap().contexts;
        assert_eq!(persisted.len(), 2, "{persisted:?}");
        assert!(matches!(
            &persisted[1],
            ContextItem::Assistant { content, interrupted: false, .. } if content == "第二次尝试。"
        ));
        assert!(
            !persisted
                .iter()
                .any(|context| matches!(context, ContextItem::Reasoning { .. })),
            "the failed attempt's reasoning must not survive as a card: {persisted:?}"
        );
        assert_eq!(store.reconcile_streaming_in("conv_retry").unwrap(), 0);
    }

    /// The run is stopped while the retry is still backing off. No card is
    /// minted for the round, so the failed attempt's rows — the newest prose
    /// the round has — are what reconciliation turns into its interrupted
    /// fragment, exactly as for a stop with no retry involved.
    #[test]
    fn a_stop_during_retry_backoff_keeps_the_failed_attempts_prose_for_reconciliation() {
        let (store, _directory) = journal_fixture("conv_retry_stop");
        let sink = || ConversationSink {
            store: Arc::clone(&store),
            conversation_id: "conv_retry_stop".into(),
            request_id: "run_stop".into(),
        };
        let journal = ProseJournal::new(sink(), "run_stop", ReasoningForm::Plaintext);
        journal.note(&ModelStreamEvent::ReasoningDelta {
            round: 1,
            item: 0,
            delta: "先想想".into(),
        });
        journal.note(&ModelStreamEvent::TextDelta {
            round: 1,
            delta: "第一次尝试".into(),
        });
        flush_journal(&journal);
        journal.note(&ModelStreamEvent::StreamRetryScheduled {
            round: 1,
            attempt: 1,
            max_attempts: 3,
            delay_ms: 0,
            message: "socket closed".into(),
        });

        GeneratedContexts::new(Some(sink()), Some("user-1".into())).into_items();

        let persisted = store
            .conversation("conv_retry_stop")
            .unwrap()
            .unwrap()
            .contexts;
        assert_eq!(persisted.len(), 3, "{persisted:?}");
        assert!(matches!(
            &persisted[1],
            ContextItem::Reasoning { content, interrupted: true, .. }
                if content.as_deref() == Some("先想想")
        ));
        assert!(matches!(
            &persisted[2],
            ContextItem::Assistant { content, interrupted: true, .. } if content == "第一次尝试"
        ));
        assert_eq!(store.reconcile_streaming_in("conv_retry_stop").unwrap(), 0);
    }

    /// A `pause_turn` continuation keeps streaming the same round. Once a step
    /// has completed, its prose is the round's prefix: a retry of the step
    /// after it discards only that step's own prose, and the next write puts
    /// the prefix plus the replacement attempt's text on disk.
    #[test]
    fn a_completed_pause_step_survives_the_retry_of_the_step_after_it() {
        let (store, _directory) = journal_fixture("conv_pause");
        let journal = ProseJournal::new(
            ConversationSink {
                store: Arc::clone(&store),
                conversation_id: "conv_pause".into(),
                request_id: "run_pause".into(),
            },
            "run_pause",
            ReasoningForm::Plaintext,
        );
        journal.note(&ModelStreamEvent::ReasoningDelta {
            round: 1,
            item: 0,
            delta: "先搜索".into(),
        });
        journal.note(&ModelStreamEvent::TextDelta {
            round: 1,
            delta: "搜索结果显示".into(),
        });
        journal.commit(1);
        journal.note(&ModelStreamEvent::TextDelta {
            round: 1,
            delta: "，失败的续写".into(),
        });
        flush_journal(&journal);
        journal.note(&ModelStreamEvent::StreamRetryScheduled {
            round: 1,
            attempt: 1,
            max_attempts: 3,
            delay_ms: 0,
            message: "socket closed".into(),
        });
        {
            let state = journal.state.lock().unwrap();
            assert_eq!(state.text, "搜索结果显示");
            assert_eq!(state.reasoning, "先搜索");
        }
        journal.note(&ModelStreamEvent::TextDelta {
            round: 1,
            delta: "，重试的续写".into(),
        });
        flush_journal(&journal);

        let persisted = store.conversation("conv_pause").unwrap().unwrap().contexts;
        assert!(
            matches!(
                &persisted[2],
                ContextItem::Assistant { content, .. } if content == "搜索结果显示，重试的续写"
            ),
            "{persisted:?}"
        );
        assert!(matches!(
            &persisted[1],
            ContextItem::Reasoning { content, .. } if content.as_deref() == Some("先搜索")
        ));

        // A commit or a retry for another round leaves this round's prefix alone.
        journal.commit(2);
        journal.note(&ModelStreamEvent::StreamRetryScheduled {
            round: 2,
            attempt: 1,
            max_attempts: 3,
            delay_ms: 0,
            message: "socket closed".into(),
        });
        let state = journal.state.lock().unwrap();
        assert_eq!(state.text, "搜索结果显示，重试的续写");
        assert_eq!(state.committed, ("搜索结果显示".len(), "先搜索".len()));
    }

    /// A retry is announced for the round being requested. If the journal has
    /// not seen a delta for that round, nothing of it is on disk, and whatever
    /// an earlier round left behind is not this retry's to discard.
    #[test]
    fn a_retry_for_a_round_the_journal_has_not_reached_touches_nothing() {
        let (store, _directory) = journal_fixture("conv_retry_later");
        let journal = ProseJournal::new(
            ConversationSink {
                store: Arc::clone(&store),
                conversation_id: "conv_retry_later".into(),
                request_id: "run_later".into(),
            },
            "run_later",
            ReasoningForm::Plaintext,
        );
        journal.note(&ModelStreamEvent::TextDelta {
            round: 1,
            delta: "第一轮".into(),
        });
        flush_journal(&journal);
        let before = persisted_ids(&store, "conv_retry_later");
        assert_eq!(before, vec!["user-1", "ctx_assistant_run_later_1"]);

        journal.note(&ModelStreamEvent::StreamRetryScheduled {
            round: 2,
            attempt: 1,
            max_attempts: 3,
            delay_ms: 0,
            message: "socket closed".into(),
        });

        assert_eq!(persisted_ids(&store, "conv_retry_later"), before);
        let state = journal.state.lock().unwrap();
        assert_eq!(state.round, 1);
        assert_eq!(state.text, "第一轮");
    }

    /// An encrypted round dies with its summary on disk as a streaming row. The
    /// interrupted card settlement mints for it carries that summary under the
    /// same id, so it replaces the row in place: one card, marked interrupted,
    /// with nothing to replay — never a second copy, and never a row left for
    /// reconciliation to mark on its own.
    #[test]
    fn an_interrupted_encrypted_summary_settles_the_journal_row_in_place() {
        let (store, _directory) = journal_fixture("conv_encrypted");
        let sink = || ConversationSink {
            store: Arc::clone(&store),
            conversation_id: "conv_encrypted".into(),
            request_id: "run_enc".into(),
        };
        let journal = ProseJournal::new(sink(), "run_enc", ReasoningForm::Encrypted);
        journal.note(&ModelStreamEvent::ReasoningDelta {
            round: 1,
            item: 0,
            delta: "先读文件".into(),
        });
        flush_journal(&journal);
        assert_eq!(
            persisted_ids(&store, "conv_encrypted"),
            vec!["user-1", "ctx_reasoning_run_enc_1"]
        );

        let model_turn_id = round_model_turn_id("run_enc", 1);
        let mut generated = GeneratedContexts::new(Some(sink()), Some("user-1".into()));
        generated.extend(interrupted_reasoning_context(
            reasoning_segment_identity("run_enc", 1, 0),
            "先读文件".into(),
            1,
            &model_turn_id,
            ReasoningForm::Encrypted,
        ));
        journal.round_settled(1, &generated);
        // The card is the run's own output, not something reconciliation had to
        // recover after the fact: it goes back in the response as well as on disk.
        let items = generated.into_items();
        assert_eq!(items.len(), 1, "{items:?}");
        assert!(matches!(
            &items[0],
            ContextItem::Reasoning {
                interrupted: true,
                ..
            }
        ));

        let persisted = store
            .conversation("conv_encrypted")
            .unwrap()
            .unwrap()
            .contexts;
        assert_eq!(persisted.len(), 2, "{persisted:?}");
        assert!(matches!(
            &persisted[1],
            ContextItem::Reasoning { id, content, form, interrupted: true, replay: None, .. }
                if id == "ctx_reasoning_run_enc_1"
                    && content.as_deref() == Some("先读文件")
                    && *form == Some(ReasoningForm::Encrypted)
        ));
        assert_eq!(store.reconcile_streaming_in("conv_encrypted").unwrap(), 0);
    }

    /// A run that leaves through an error rather than through `into_items` —
    /// `turn?` at the end of `run_model_inner`, reached by a dead event sink or a
    /// failing hook — must still reconcile. Otherwise the round's prose stays
    /// `streaming` until the next run or app start, and an idle, in-sync
    /// `conversations::update` rewrites it as a settled message that no longer
    /// says it was interrupted.
    #[test]
    fn dropping_the_ledger_without_consuming_it_still_reconciles_the_rounds_prose() {
        let (store, _directory) = journal_fixture("conv_error_exit");
        let sink = || ConversationSink {
            store: Arc::clone(&store),
            conversation_id: "conv_error_exit".into(),
            request_id: "run_err".into(),
        };
        let journal = ProseJournal::new(sink(), "run_err", ReasoningForm::Plaintext);
        journal.note(&ModelStreamEvent::TextDelta {
            round: 1,
            delta: "说到一半".into(),
        });
        flush_journal(&journal);

        // The error exit: the ledger goes out of scope having never been consumed.
        drop(GeneratedContexts::new(Some(sink()), Some("user-1".into())));

        let persisted = store
            .conversation("conv_error_exit")
            .unwrap()
            .unwrap()
            .contexts;
        assert_eq!(persisted.len(), 2, "{persisted:?}");
        assert!(
            matches!(
                &persisted[1],
                ContextItem::Assistant { content, interrupted: true, .. } if content == "说到一半"
            ),
            "the abandoned round's prose must settle as an interrupted fragment: {persisted:?}"
        );
        assert_eq!(
            store.reconcile_streaming_in("conv_error_exit").unwrap(),
            0,
            "nothing may be left for the next run or app start to reconcile"
        );
    }

    /// Settlement deletes a still-`streaming` row on the reasoning that no card
    /// claimed it. That reasoning collapses when the claiming card's own write
    /// failed: the row is then the round's only copy of its prose, and deleting
    /// it loses the prose outright. The write failure is injected with a SQLite
    /// trigger, which blocks the settled write while leaving reads — and the
    /// DELETE this test must prove did not happen — working.
    #[test]
    fn settlement_spares_the_streaming_row_when_the_claiming_cards_write_failed() {
        let (store, directory) = journal_fixture("conv_write_fail");
        let database = directory
            .path()
            .join(crate::conversation_store::DATABASE_FILE_NAME);
        let sink = || ConversationSink {
            store: Arc::clone(&store),
            conversation_id: "conv_write_fail".into(),
            request_id: "run_fail".into(),
        };
        let journal = ProseJournal::new(sink(), "run_fail", ReasoningForm::Plaintext);
        journal.note(&ModelStreamEvent::TextDelta {
            round: 1,
            delta: "唯一的一份正文".into(),
        });
        flush_journal(&journal);
        assert_eq!(
            persisted_ids(&store, "conv_write_fail"),
            vec!["user-1", "ctx_assistant_run_fail_1"]
        );

        // A settled write is an UPDATE when it supersedes the streaming row and an
        // INSERT otherwise, so both have to be blocked. Streaming writes and the
        // settlement DELETE stay open.
        let blocker = rusqlite::Connection::open(&database).unwrap();
        blocker
            .execute_batch(
                "CREATE TRIGGER block_settled_update BEFORE UPDATE ON context
                 WHEN NEW.status = 'settled'
                 BEGIN SELECT RAISE(ABORT, 'injected write failure'); END;
                 CREATE TRIGGER block_settled_insert BEFORE INSERT ON context
                 WHEN NEW.status = 'settled'
                 BEGIN SELECT RAISE(ABORT, 'injected write failure'); END;",
            )
            .unwrap();

        let model_turn_id = round_model_turn_id("run_fail", 1);
        let mut generated = GeneratedContexts::new(Some(sink()), Some("user-1".into()));
        generated.push(model_assistant_context(
            round_identity("run_fail", 1, "assistant"),
            // Deliberately not the streamed text: the two are the only way to
            // tell a spared row from a card that quietly landed anyway.
            "唯一的一份正文。".into(),
            1,
            &model_turn_id,
            Vec::new(),
        ));
        assert!(
            !generated.checkpoint(),
            "the injected failure is this test's premise; without it nothing below discriminates"
        );
        journal.round_settled(1, &generated);
        let spared = store
            .conversation("conv_write_fail")
            .unwrap()
            .unwrap()
            .contexts;
        assert!(
            matches!(
                &spared[1],
                ContextItem::Assistant { id, content, .. }
                    if id == "ctx_assistant_run_fail_1" && content == "唯一的一份正文"
            ),
            "prose the failed card write never claimed must survive settlement: {spared:?}"
        );

        blocker
            .execute_batch("DROP TRIGGER block_settled_update; DROP TRIGGER block_settled_insert;")
            .unwrap();
        drop(blocker);

        // The failed write stayed pending rather than being marked written, so the
        // ledger's own teardown still lands it once the store accepts writes again
        // — and the row it claims is no longer reconciled into a fragment.
        drop(generated);
        let persisted = store
            .conversation("conv_write_fail")
            .unwrap()
            .unwrap()
            .contexts;
        assert!(
            matches!(
                &persisted[1],
                ContextItem::Assistant { content, interrupted: false, .. }
                    if content == "唯一的一份正文。"
            ),
            "the retried write must land the card, not reconcile the row it claims: {persisted:?}"
        );
        assert_eq!(store.reconcile_streaming_in("conv_write_fail").unwrap(), 0);
    }

    /// The write check settlement makes is about the round's own two rows, not
    /// about the ledger as a whole. An unrelated item still pending — a hook
    /// message, a tool card whose write failed an earlier round — says nothing
    /// about whether this round's cards claimed their rows, and must not stop
    /// the round from dropping prose that genuinely no card stands behind.
    /// Otherwise a failed attempt's abandoned reasoning comes back as an
    /// interrupted card on a round that completed.
    #[test]
    fn an_unrelated_pending_write_does_not_strand_the_rounds_unclaimed_prose() {
        let (store, directory) = journal_fixture("conv_scope");
        let database = directory
            .path()
            .join(crate::conversation_store::DATABASE_FILE_NAME);
        let sink = || ConversationSink {
            store: Arc::clone(&store),
            conversation_id: "conv_scope".into(),
            request_id: "run_scope".into(),
        };
        let journal = ProseJournal::new(sink(), "run_scope", ReasoningForm::Plaintext);
        journal.note(&ModelStreamEvent::ReasoningDelta {
            round: 1,
            item: 0,
            delta: "先想想".into(),
        });
        journal.note(&ModelStreamEvent::TextDelta {
            round: 1,
            delta: "第一次尝试".into(),
        });
        flush_journal(&journal);
        // The attempt fails and the replacement answers without reasoning, so
        // nothing will ever claim the reasoning row.
        journal.note(&ModelStreamEvent::StreamRetryScheduled {
            round: 1,
            attempt: 1,
            max_attempts: 3,
            delay_ms: 0,
            message: "socket closed".into(),
        });

        let mut generated = GeneratedContexts::new(Some(sink()), Some("user-1".into()));
        let blocker = rusqlite::Connection::open(&database).unwrap();
        blocker
            .execute_batch(
                "CREATE TRIGGER block_settled_insert BEFORE INSERT ON context
                 WHEN NEW.status = 'settled'
                 BEGIN SELECT RAISE(ABORT, 'injected write failure'); END;",
            )
            .unwrap();
        generated.push(assistant_context("钩子留下的消息".to_owned()));
        assert!(
            !generated.confirmed(generated[0].id()),
            "the unrelated item must be left pending for this test to mean anything"
        );
        blocker
            .execute_batch("DROP TRIGGER block_settled_insert;")
            .unwrap();
        drop(blocker);

        let model_turn_id = round_model_turn_id("run_scope", 1);
        generated.push(model_assistant_context(
            round_identity("run_scope", 1, "assistant"),
            "第二次尝试。".into(),
            1,
            &model_turn_id,
            Vec::new(),
        ));
        journal.round_settled(1, &generated);

        let persisted = store.conversation("conv_scope").unwrap().unwrap().contexts;
        assert!(
            !persisted
                .iter()
                .any(|context| matches!(context, ContextItem::Reasoning { .. })),
            "the failed attempt's reasoning is claimed by no card and must still be dropped: {persisted:?}"
        );
        assert_eq!(store.reconcile_streaming_in("conv_scope").unwrap(), 0);
    }

    /// Gateway wiring discriminator: one `run_model` creates one ledger row per
    /// provider request. Zero means no wiring; one for multiple requests undercounts.
    /// The probe uses one tool round trip, which produces two provider requests under
    /// current sidecar continuation behavior, and compares row totals with run usage.
    #[test]
    fn the_gateway_records_one_ledger_row_per_provider_request() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = serve_json_sequence(
            listener,
            vec![
                // First request invokes a host-only task tool and forces a second round.
                json!({
                    "model": "model-test",
                    "status": "completed",
                    "output": [{
                        "type":"function_call","status":"completed",
                        "call_id":"ledger-task-list","name":"task_list",
                        "arguments":json!({}).to_string()
                    }],
                    "usage": {"input_tokens":11,"output_tokens":7,"total_tokens":18}
                }),
                // Second request completes the model turn.
                json!({
                    "model": "model-test",
                    "status": "completed",
                    "output": [{
                        "type":"message","id":"msg_ledger","status":"completed","role":"assistant",
                        "content":[{"type":"output_text","text":"记完了"}]
                    }],
                    "usage": {"input_tokens":13,"output_tokens":7,"total_tokens":20}
                }),
            ],
        );

        let workspace = tempfile::tempdir().unwrap();
        let request = loop_request_for(address, workspace.path());
        let provider_id = request.provider.id.clone();
        let model_id = request.model.id.clone();

        let anchor = workspace.path().join("document.v1.json");
        let ledger = crate::token_ledger::store_for(&anchor).unwrap();
        assert!(ledger.buckets().unwrap().is_empty());

        let response =
            run_model(request, &AppState::default(), &discard_event, &approve_tool).unwrap();
        let captured = server.join().unwrap();
        assert_eq!(captured.len(), 2, "工具往返必须真的发出两次 provider 请求");

        let buckets = ledger.buckets().unwrap();
        // Same hour, model, and origin use one bucket, while `requests` still counts
        // both requests.
        assert_eq!(buckets.len(), 1);
        assert_eq!(buckets[0].requests, 2);
        assert_eq!(buckets[0].provider_id, provider_id);
        assert_eq!(buckets[0].model_id, model_id);
        assert_eq!(
            buckets[0].origin,
            crate::token_ledger::UsageOrigin::Conversation
        );
        assert_eq!(
            buckets[0].input_tokens,
            response.usage.input_tokens.unwrap()
        );
        assert_eq!(
            buckets[0].output_tokens,
            response.usage.output_tokens.unwrap()
        );
        assert_eq!(
            buckets[0].total_tokens,
            response.usage.total_tokens.unwrap()
        );

        crate::token_ledger::close_store_for(&anchor);
    }

    /// A child template inherits the parent's pinned effort and nothing that
    /// would let it re-derive top-level policy authority.
    #[test]
    fn a_child_template_inherits_effort_at_depth_one() {
        let mut parent = run_request(ProviderFamily::OpenaiResponses);
        parent.reasoning_effort = ReasoningEffort::Max;

        let child = agent_child_template(&parent);
        assert_eq!(child.reasoning_effort, ReasoningEffort::Max);
        assert_eq!(child.subagent_depth, 1);
    }

    /// Live DeepSeek native-search stream permits a failed
    /// `web_search_call` item and a status-less `reasoning` item without interrupting
    /// the stream. Host-consumed `function_call` and `message` remain strict.
    /// Server-item terminal states are only completed or failed, and snapshots
    /// cannot change a server item into a host-consumed type.
    #[test]
    fn every_level_reaches_the_sidecar_as_a_neutral_name_without_vendor_dials() {
        for (effort, wire) in [
            (ReasoningEffort::Low, "low"),
            (ReasoningEffort::Medium, "medium"),
            (ReasoningEffort::High, "high"),
            (ReasoningEffort::Extra, "xhigh"),
            (ReasoningEffort::Max, "max"),
        ] {
            for format in [
                ProviderFamily::OpenaiResponses,
                ProviderFamily::OpenaiChat,
                ProviderFamily::Anthropic,
            ] {
                let mut request = run_request(format);
                request.reasoning_effort = effort;

                let step = step_json(&request);

                assert_eq!(step["reasoning"], wire, "{format:?}");
                assert!(step.get("reasoning_effort").is_none());
                assert!(step.get("reasoningEffort").is_none());
                assert!(step.get("thinking").is_none());
                assert!(step.get("output_config").is_none());
                assert!(step.get("outputConfig").is_none());
                // The per-family dials are the sidecar's to choose
                // (`reasoning.ts`): the host's `providerOptions` carries none.
                // Responses always has `{store,include}` for context ownership
                // and a null summary, neither of them a level.
                let options = step.get("providerOptions").cloned().unwrap_or(Value::Null);
                for vendor in options.as_object().into_iter().flat_map(|map| map.values()) {
                    for dial in ["reasoningEffort", "reasoning", "thinking", "effort"] {
                        assert!(
                            vendor.get(dial).is_none(),
                            "{format:?} 的 providerOptions 不该带 {dial}"
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn local_only_system_context_never_enters_any_api_payload() {
        for format in [
            ProviderFamily::OpenaiResponses,
            ProviderFamily::OpenaiChat,
            ProviderFamily::Anthropic,
        ] {
            let mut request = run_request(format);
            request.contexts.push(ContextItem::System {
                id: "local-hook".into(),
                content: "LOCAL_HOOK_SECRET_MUST_NOT_LEAVE".into(),
                local_only: true,
                hook_execution: None,
                tools_added: Vec::new(),
                created_at: "2026-01-01T00:00:00Z".into(),
            });

            let payload = step_json(&request);
            assert_eq!(payload["system"], "Be useful.");
            assert!(!payload
                .to_string()
                .contains("LOCAL_HOOK_SECRET_MUST_NOT_LEAVE"));
        }
    }

    #[test]
    fn ephemeral_memory_context_is_low_priority_user_input_before_durable_history() {
        const SENTINEL: &str = "PRIVATE_EPHEMERAL_MEMORY_SENTINEL";
        for format in [
            ProviderFamily::OpenaiResponses,
            ProviderFamily::OpenaiChat,
            ProviderFamily::Anthropic,
        ] {
            let mut request = run_request(format);
            request.ephemeral_contexts.push(ContextItem::User {
                id: "ephemeral-memory".into(),
                content: SENTINEL.into(),
                images: Vec::new(),
                files: Vec::new(),
                created_at: "2026-07-24T00:00:00Z".into(),
            });

            let family = crate::aisdk::protocol::Family::for_format(format);
            let durable_projection =
                serde_json::to_string(&wire_history::project_full(family, &request.contexts))
                    .expect("serialize durable history");
            assert!(!durable_projection.contains(SENTINEL));

            let payload = step_json(&request);
            assert!(!payload["system"].to_string().contains(SENTINEL));
            let messages = payload["messages"].as_array().expect("ModelMessage[]");
            assert_eq!(messages.len(), 2);
            assert_eq!(messages[0], json!({"role":"user","content":SENTINEL}));
            assert_eq!(
                messages[1],
                json!({"role":"user","content":"Read the file."})
            );
        }
    }

