    #[test]
    fn automatic_tool_round_is_serialized_but_never_enters_api_history() {
        let execution = ToolExecution {
            call: ToolCall {
                id: "call-round".into(),
                name: "read".into(),
                input: serde_json::from_value(json!({"path":"README.md"})).unwrap(),
            },
            result: ToolResult {
                success: true,
                output: "contents".into(),
                images: Vec::new(),
                diff: None,
                executed_at: "2026-01-01T00:00:00Z".into(),
                duration_ms: 1,
            },
            subagent: None,
        };
        let with_round = tool_context(&execution, 3);
        assert_eq!(serde_json::to_value(&with_round).unwrap()["round"], 3);
        assert!(matches!(
            &with_round,
            ContextItem::Tool { round: Some(3), .. }
        ));

        let mut without_round = with_round.clone();
        let ContextItem::Tool { round, .. } = &mut without_round else {
            unreachable!();
        };
        *round = None;

        for format in [
            ProviderFamily::OpenaiResponses,
            ProviderFamily::OpenaiChat,
            ProviderFamily::Anthropic,
        ] {
            let mut request_with_round = run_request(format);
            request_with_round.contexts.push(with_round.clone());
            let mut request_without_round = request_with_round.clone();
            *request_without_round.contexts.last_mut().unwrap() = without_round.clone();

            assert_eq!(
                step_json(&request_with_round),
                step_json(&request_without_round),
                "tool round metadata must not alter {format:?} history"
            );
        }
    }

    #[test]
    fn dangerous_and_orchestration_calls_pass_while_unknown_and_disabled_are_rejected() {
        let mut request = run_request(ProviderFamily::OpenaiResponses);
        request.tools = catalog::tool_catalog();
        request.enabled_tools = request
            .tools
            .iter()
            .map(|tool| tool.name.clone())
            .filter(|name| name != "task_list")
            .collect();
        let dangerous = ToolCall {
            id: "dangerous".into(),
            name: "powershell".into(),
            input: serde_json::from_value(json!({"command":"echo nope"})).unwrap(),
        };
        let unknown = ToolCall {
            id: "unknown".into(),
            name: "not_a_tool".into(),
            input: Map::new(),
        };
        let orchestration = ToolCall {
            id: "orchestration".into(),
            name: "agent_spawn".into(),
            input: serde_json::from_value(json!({"prompt":"do work"})).unwrap(),
        };
        let disabled = ToolCall {
            id: "disabled".into(),
            name: "task_list".into(),
            input: Map::new(),
        };

        assert_eq!(automatic_tool_rejection_reason(&request, &dangerous), None);
        assert_eq!(
            automatic_tool_rejection_reason(&request, &orchestration),
            None
        );
        assert_eq!(
            automatic_tool_rejection_reason(&request, &unknown),
            Some("The model requested an unknown tool".to_owned())
        );
        assert_eq!(
            automatic_tool_rejection_reason(&request, &disabled),
            Some("The model requested a tool that is not enabled".to_owned())
        );
    }

    #[test]
    fn ask_user_validation_follows_claude_code() {
        let parse = |input: Value| orchestration::parse_question(input.as_object().unwrap());
        let option = |label: &str| json!({"label": label, "description": "d"});
        // multiSelect defaults to false, as Claude Code's schema does.
        let spec = parse(json!({"questions":[{"question":"Q?","header":"H","options":[option("A"), option("B")]}]}))
            .unwrap();
        assert!(!spec.questions[0].multi_select);
        let one_option = parse(json!({"questions":[{"question":"Q?","header":"H","options":[option("A")]}]}))
            .unwrap_err();
        assert!(one_option.starts_with("This call included a question with fewer than 2 options"));
        assert_eq!(
            parse(json!({"questions":[
                {"question":"Q?","header":"H","options":[option("A"), option("A")]}
            ]}))
            .unwrap_err(),
            "Question texts must be unique, option labels must be unique within each question"
        );
        assert!(parse(json!({"questions":[
            {"question":"Q?","header":"H","options":[option("A"), option("B")]},
            {"question":"Q?","header":"H2","options":[option("A"), option("B")]}
        ]}))
        .is_err());

        let descriptor = catalog::tool_catalog()
            .into_iter()
            .find(|tool| tool.name == "ask_user")
            .unwrap();
        let schema = tool_schema(
            &descriptor,
            &crate::prompt_profile::PromptProfile::builtin_english(),
            &crate::workspace_set::WorkspaceSet::default(),
        );
        assert_eq!(schema["properties"]["questions"]["minItems"], 1);
        assert_eq!(schema["properties"]["questions"]["maxItems"], 4);
        assert_eq!(
            schema["properties"]["questions"]["items"]["required"],
            json!(["question", "header", "options", "multiSelect"])
        );
    }

    #[test]
    fn memory_tools_publish_strict_host_identity_free_schemas() {
        let catalog = catalog::tool_catalog();
        for name in crate::mework_memory::MEMORY_TOOL_NAMES {
            let descriptor = catalog.iter().find(|tool| tool.name == name).unwrap();
            let schema = tool_schema(
                descriptor,
                &crate::prompt_profile::PromptProfile::builtin_english(),
                &crate::workspace_set::WorkspaceSet::default(),
            );
            let properties = schema["properties"].as_object().unwrap();
            assert_eq!(schema["additionalProperties"], false, "{name}");
            // Memory belongs to a location. The tier is encoded in the tool
            // name, so there is no identity field, no namespace selector, and
            // no path for a model to aim somewhere else.
            for forbidden in [
                "modelId",
                "model_id",
                "providerId",
                "provider_id",
                "presetId",
                "preset_id",
                "workspaceId",
                "workspace_id",
                "path",
                "scope",
                "tier",
                "expected_version",
                "version",
            ] {
                assert!(
                    !properties.contains_key(forbidden),
                    "{name} must not expose trusted identity field {forbidden}"
                );
            }
        }

        let required = |name: &str| {
            catalog
                .iter()
                .find(|tool| tool.name == name)
                .map(|tool| {
                    tool_schema(
                        tool,
                        &crate::prompt_profile::PromptProfile::builtin_english(),
                        &crate::workspace_set::WorkspaceSet::default(),
                    )
                })
                .unwrap()["required"]
                .clone()
        };
        for name in ["read_global_memory", "read_project_memory"] {
            assert_eq!(required(name), json!(["name"]), "{name}");
        }
        for name in ["create_global_memory", "create_project_memory"] {
            // The index description is required, so a write can never leave a
            // document the index does not describe.
            assert_eq!(
                required(name),
                json!(["name", "content", "description"]),
                "{name}"
            );
        }
        for name in ["edit_global_memory", "edit_project_memory"] {
            assert_eq!(
                required(name),
                json!(["name", "old_text", "new_text", "description"]),
                "{name}"
            );
        }
    }

    /// Serves `responses` on sequential connections and returns each captured
    /// request body, so multi-round loop tests can assert what the model saw.
    /// Convert one non-streaming Responses fixture into the AI SDK SSE sequence.
    /// Fixtures are complete JSON responses but `streamText` only consumes streams;
    /// emit installed `@ai-sdk/openai` event names so the mock cannot hang at accept.
    fn responses_sse(value: &Value) -> String {
        let mut out = String::new();
        let mut push = |data: Value| {
            out.push_str("data: ");
            out.push_str(&data.to_string());
            out.push_str("\n\n");
        };
        let model = value.get("model").cloned().unwrap_or(json!("model-test"));
        let empty = Vec::new();
        let items = value
            .get("output")
            .and_then(Value::as_array)
            .unwrap_or(&empty);

        let head = json!({
            "id": "resp_fixture",
            "object": "response",
            "created_at": 1,
            "model": model,
            "status": "in_progress",
            "output": [],
        });
        push(json!({ "type": "response.created", "response": head }));

        for (index, item) in items.iter().enumerate() {
            // Every item needs an id: `call_id` is externally visible while stream
            // deltas correlate by `item_id`.
            let mut item = item.clone();
            if item.get("id").is_none() {
                item["id"] = json!(format!("item_{index}"));
            }
            let item_id = item["id"].clone();
            push(json!({
                "type": "response.output_item.added",
                "output_index": index,
                "item": item,
            }));
            match item.get("type").and_then(Value::as_str) {
                Some("message") => {
                    let text = item
                        .get("content")
                        .and_then(Value::as_array)
                        .and_then(|parts| parts.first())
                        .and_then(|part| part.get("text"))
                        .and_then(Value::as_str)
                        .unwrap_or_default()
                        .to_owned();
                    push(json!({
                        "type": "response.output_text.delta",
                        "item_id": item_id,
                        "output_index": index,
                        "content_index": 0,
                        "delta": text,
                    }));
                }
                Some("function_call") => {
                    let arguments = item
                        .get("arguments")
                        .and_then(Value::as_str)
                        .unwrap_or("{}")
                        .to_owned();
                    push(json!({
                        "type": "response.function_call_arguments.delta",
                        "item_id": item_id,
                        "output_index": index,
                        "delta": arguments,
                    }));
                }
                Some("reasoning") => {
                    // `output_item.added` already opened summary part 0; later parts
                    // open with `summary_part.added`, and each streams its text.
                    let summaries = item
                        .get("summary")
                        .and_then(Value::as_array)
                        .cloned()
                        .unwrap_or_default();
                    for (summary_index, part) in summaries.iter().enumerate() {
                        if summary_index > 0 {
                            push(json!({
                                "type": "response.reasoning_summary_part.added",
                                "item_id": item_id,
                                "output_index": index,
                                "summary_index": summary_index,
                                "part": {"type": "summary_text", "text": ""},
                            }));
                        }
                        let text = part.get("text").and_then(Value::as_str).unwrap_or_default();
                        if !text.is_empty() {
                            push(json!({
                                "type": "response.reasoning_summary_text.delta",
                                "item_id": item_id,
                                "output_index": index,
                                "summary_index": summary_index,
                                "delta": text,
                            }));
                        }
                    }
                }
                _ => {}
            }
            push(json!({
                "type": "response.output_item.done",
                "output_index": index,
                "item": item,
            }));
        }

        let mut tail = json!({
            "id": "resp_fixture",
            "object": "response",
            "created_at": 1,
            "model": model,
            "status": value.get("status").cloned().unwrap_or(json!("completed")),
            "output": items,
        });
        if let Some(usage) = value.get("usage") {
            tail["usage"] = usage.clone();
        }
        push(json!({ "type": "response.completed", "response": tail }));
        out
    }

    /// How long a stub server waits for a request the run under test is expected to make.
    ///
    /// Generous enough for a slow debug build, and finite on purpose: a fixture parked in a
    /// blocking `accept` can never finish, so `server.join()` at the end of the test never
    /// returns either. That turns "the run stopped making requests" — the failure the test was
    /// written to catch — into a test binary that hangs after its summary was already printed.
    const FIXTURE_ACCEPT_BUDGET: Duration = Duration::from_secs(30);

    fn serve_json_sequence(
        listener: TcpListener,
        responses: Vec<Value>,
    ) -> thread::JoinHandle<Vec<String>> {
        serve_json_sequence_within(listener, responses, FIXTURE_ACCEPT_BUDGET)
    }

    fn serve_json_sequence_within(
        listener: TcpListener,
        responses: Vec<Value>,
        budget: Duration,
    ) -> thread::JoinHandle<Vec<String>> {
        thread::spawn(move || {
            let expected = responses.len();
            let mut captured = Vec::with_capacity(expected);
            for (index, response) in responses.into_iter().enumerate() {
                let Some(mut stream) = accept_within(&listener, budget) else {
                    panic!(
                        "等待第 {} 个请求（共 {expected} 个）超时：本次运行没有再发起连接",
                        index + 1
                    );
                };
                captured.push(read_http_request_with_body(&mut stream));
                write_sse_response(&mut stream, &responses_sse(&response));
            }
            captured
        })
    }

    fn responses_text_output(text: &str) -> Value {
        json!({
            "model": "model-test",
            "status": "completed",
            "output": [{
                "type":"message","id":"msg_test","status":"completed","role":"assistant",
                "content":[{"type":"output_text","text":text}]
            }],
            "usage": {"input_tokens":1,"output_tokens":1,"total_tokens":2}
        })
    }

    /// Serves responses on sequential connections while ROUTING each request by
    /// body content: child-turn requests carry the subagent system-prompt
    /// addendum, parent requests do not. Background agents make the arrival
    /// order of parent and child connections nondeterministic; routing keeps
    /// each queue deterministic regardless of interleaving. Returns
    /// `(parent_bodies, child_bodies)` in per-queue arrival order.
    fn serve_routed_json(
        listener: TcpListener,
        parent_responses: Vec<Value>,
        child_responses: Vec<Value>,
    ) -> thread::JoinHandle<(Vec<String>, Vec<String>)> {
        thread::spawn(move || {
            let total = parent_responses.len() + child_responses.len();
            let mut parent_queue = parent_responses.into_iter();
            let mut child_queue = child_responses.into_iter();
            let mut parent_bodies = Vec::new();
            let mut child_bodies = Vec::new();
            for index in 0..total {
                let Some(mut stream) = accept_within(&listener, FIXTURE_ACCEPT_BUDGET) else {
                    panic!(
                        "等待第 {} 个请求（共 {total} 个）超时：本次运行没有再发起连接",
                        index + 1
                    );
                };
                let body = read_http_request_with_body(&mut stream);
                let response = if body.contains("You are a child agent spawned by the main agent")
                    || body.contains("你是主代理派生的子代理")
                {
                    child_bodies.push(body);
                    child_queue.next().expect("unexpected extra child request")
                } else {
                    parent_bodies.push(body);
                    parent_queue
                        .next()
                        .expect("unexpected extra parent request")
                };
                write_json_response(&mut stream, "200 OK", &response);
            }
            (parent_bodies, child_bodies)
        })
    }

    fn loop_request_for(address: std::net::SocketAddr, workspace: &Path) -> RunModelRequest {
        let mut request = run_request(ProviderFamily::OpenaiResponses);
        request.provider.base_url = format!("http://{address}/v1");
        request.workspace_path = workspace.to_string_lossy().into_owned();
        request.app_data_path = workspace.to_string_lossy().into_owned();
        request.tools = catalog::tool_catalog();
        request.enabled_tools = request.tools.iter().map(|tool| tool.name.clone()).collect();
        request
    }

    /// Opens the workspace's conversation store and registers the request's
    /// conversation in it, so the run's `ConversationSink` has a row to write to.
    fn persisted_conversation_for(
        request: &RunModelRequest,
    ) -> Arc<crate::conversation_store::ConversationStore> {
        let anchor = Path::new(&request.app_data_path).join("document.v1.json");
        let store = crate::conversation_store::store_for(&anchor).unwrap();
        store
            .put_conversation(
                &request.workspace_id,
                &crate::model::Conversation {
                    id: request.conversation_id.clone(),
                    title: "order".into(),
                    created_at: "2026-09-05T00:00:00.000Z".into(),
                    updated_at: "2026-09-05T00:00:00.000Z".into(),
                    settings: serde_json::from_value(json!({
                        "enabledTools": [],
                    }))
                    .unwrap(),
                    contexts: request.contexts.clone(),
                    queued_messages: Vec::new(),
                    branches: Vec::new(),
                    user_aborted_tasks: Vec::new(),
                    worktrees: Vec::new(),
                    run_target: None,
                    additional_directories: Vec::new(),
                    parent_conversation_id: None,
                    fork_of: None,
                    handoff_of: None,
                    preset_id: String::new(),
                    template_id: String::new(),
                    attached_workspaces: Vec::new(),
                },
            )
            .unwrap();
        store
    }

    /// The upstream stream opens with the reasoning item, then the prose, then the
    /// tool call — but the host mints the round's reasoning card only after the
    /// stream has ended, once the prose and tool cards may already be on disk. The
    /// persisted round must still read reasoning, prose, tool, and the response
    /// contexts must agree with the rows.
    #[test]
    fn a_rounds_reasoning_card_is_persisted_ahead_of_its_prose_and_tool_cards() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = serve_json_sequence(
            listener,
            vec![
                json!({
                    "model": "model-test",
                    "status": "completed",
                    "output": [
                        {
                            "type":"reasoning","id":"rs_order",
                            "summary":[{"type":"summary_text","text":"先列一下任务"}]
                        },
                        {
                            "type":"message","id":"msg_order","status":"completed","role":"assistant",
                            "content":[{"type":"output_text","text":"我先看看任务列表。"}]
                        },
                        {
                            "type":"function_call","status":"completed",
                            "call_id":"order-task-list","name":"task_list",
                            "arguments":json!({}).to_string()
                        }
                    ],
                    "usage": {
                        "input_tokens":11,"output_tokens":7,"total_tokens":18,
                        "output_tokens_details":{"reasoning_tokens":3}
                    }
                }),
                responses_text_output("列表是空的。"),
            ],
        );

        let workspace = tempfile::tempdir().unwrap();
        let mut request = loop_request_for(address, workspace.path());
        request.request_id = "run_order".into();
        let store = persisted_conversation_for(&request);
        let conversation_id = request.conversation_id.clone();

        let response =
            run_model(request, &AppState::default(), &discard_event, &approve_tool).unwrap();
        server.join().unwrap();

        let persisted = store
            .conversation(&conversation_id)
            .unwrap()
            .expect("the conversation row was registered before the run");
        let kinds = persisted
            .contexts
            .iter()
            .map(|context| match context {
                ContextItem::User { .. } => "user",
                ContextItem::Reasoning { .. } => "reasoning",
                ContextItem::Assistant { .. } => "assistant",
                ContextItem::Tool { .. } => "tool",
                ContextItem::System { .. } => "system",
            })
            .collect::<Vec<_>>();
        assert_eq!(
            kinds,
            vec!["user", "reasoning", "assistant", "tool", "assistant"],
            "persisted rows: {:?}",
            persisted
                .contexts
                .iter()
                .map(ContextItem::id)
                .collect::<Vec<_>>()
        );
        // The response and the rows are the same sequence, so the renderer's
        // authoritative refresh cannot reorder what the run just showed.
        let mut expected = vec!["user-1".to_owned()];
        expected.extend(
            response
                .contexts
                .iter()
                .map(|context| context.id().to_owned()),
        );
        assert_eq!(
            persisted
                .contexts
                .iter()
                .map(|context| context.id().to_owned())
                .collect::<Vec<_>>(),
            expected
        );
        assert!(
            matches!(&persisted.contexts[1], ContextItem::Reasoning { content: Some(text), interrupted: false, .. } if text == "先列一下任务"),
            "the reasoning row must be the settled card, not a streaming leftover: {:?}",
            persisted.contexts[1]
        );
        assert_eq!(store.reconcile_streaming_in(&conversation_id).unwrap(), 0);
        crate::conversation_store::close_store_for(&workspace.path().join("document.v1.json"));
    }

    /// Everything the run did is in the history, in the order it happened, by the time the run
    /// returns: each request, the response to it — as the host parsed it, naming the request it
    /// answers, with the usage the provider reported — the call the host ran and what it
    /// returned. The last response is there although no request ever carried it back.
    #[test]
    fn every_exchange_reaches_the_history_in_order_before_the_host_acts_on_it() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = serve_json_sequence(
            listener,
            vec![
                json!({
                    "model": "model-test",
                    "status": "completed",
                    "output": [
                        {
                            "type":"reasoning","id":"rs_in",
                            "summary":[{"type":"summary_text","text":"先列一下任务"}]
                        },
                        {
                            "type":"message","id":"msg_in","status":"completed","role":"assistant",
                            "content":[{"type":"output_text","text":"我先看看任务列表。"}]
                        },
                        {
                            "type":"function_call","status":"completed",
                            "call_id":"inbound-task-list","name":"task_list",
                            "arguments":json!({}).to_string()
                        }
                    ],
                    "usage": {"input_tokens":11,"output_tokens":7,"total_tokens":18}
                }),
                responses_text_output("列表是空的。"),
            ],
        );
        let workspace = tempfile::tempdir().unwrap();
        let request = loop_request_for(address, workspace.path());
        let store = persisted_conversation_for(&request);
        let conversation_id = request.conversation_id.clone();

        run_model(request, &AppState::default(), &discard_event, &approve_tool).unwrap();
        server.join().unwrap();

        use crate::conversation_store::HistoryFilter;
        let entries = store.history_entries(&conversation_id, None).unwrap();
        assert_eq!(
            entries
                .iter()
                .filter(|entry| !matches!(entry.kind.as_str(), "edit" | "run"))
                .map(|entry| entry.kind.as_str())
                .collect::<Vec<_>>(),
            ["request", "response", "tool", "result", "request", "response"],
            "请求、回复、调用与结果按发生的顺序排在同一条序列里"
        );
        let requests = entries
            .iter()
            .filter(|entry| entry.kind == "request")
            .collect::<Vec<_>>();
        let responses = store
            .history_records(
                &conversation_id,
                HistoryFilter {
                    kinds: &["response"],
                    ..HistoryFilter::default()
                },
            )
            .unwrap();
        assert_eq!(responses.len(), 2);
        assert_eq!(
            responses
                .iter()
                .map(|response| response.answers)
                .collect::<Vec<_>>(),
            requests
                .iter()
                .map(|request| Some(request.seq))
                .collect::<Vec<_>>(),
            "每条回复记着它回答的那条请求"
        );
        let usage = requests[0].usage.expect("第一次请求的回复报了用量");
        assert_eq!(
            (usage.input_tokens, usage.output_tokens),
            (Some(11), Some(7)),
            "用量随回复记下，并落在它回答的那次请求上"
        );
        let ran = store
            .history_records(
                &conversation_id,
                HistoryFilter {
                    call_id: Some("inbound-task-list"),
                    ..HistoryFilter::default()
                },
            )
            .unwrap();
        assert_eq!(
            ran.iter().map(|record| record.kind.as_str()).collect::<Vec<_>>(),
            ["tool", "result"]
        );
        assert_eq!(ran[0].detail_str("name"), Some("task_list"));
        assert!(!ran[0].detail_flag("rewritten"), "没有钩子，执行的就是模型发来的输入");
        assert_eq!(
            crate::history::recorded_tool_input(ran[0].body.as_deref().unwrap()),
            Some(json!({}))
        );
        assert!(ran[1].detail_flag("success"));
        assert_eq!(
            serde_json::from_str::<Value>(responses[0].body.as_deref().unwrap()).unwrap(),
            json!({"role": "assistant", "content": [
                {"type": "reasoning", "text": "先列一下任务"},
                {"type": "text", "text": "我先看看任务列表。"},
                {"type": "tool-call", "toolCallId": "inbound-task-list", "toolName": "task_list", "input": {}}
            ]})
        );
        assert_eq!(
            crate::history::recorded_message_text(responses[1].body.as_deref().unwrap()),
            "列表是空的。"
        );
        assert_eq!(responses[1].detail_str("finishReason"), Some("stop"));
        crate::conversation_store::close_store_for(&workspace.path().join("document.v1.json"));
    }

    /// Answers the first question card a run raises with `response`, after
    /// `before` runs (a test uses it to steer a message in first), and hands the
    /// card back so a test can assert on what the user was shown.
    fn answer_question_card(
        state: &AppState,
        response: crate::tool_prompt::QuestionResponse,
        before: impl FnOnce() + Send + 'static,
    ) -> thread::JoinHandle<crate::tool_prompt::PendingToolPrompt> {
        let answering = state.clone();
        thread::spawn(move || {
            let deadline = Instant::now() + Duration::from_secs(30);
            let card = loop {
                assert!(Instant::now() < deadline, "the question card was never announced");
                if let Some((_, card)) = answering.tool_prompts().all_pending_cards().into_iter().next() {
                    break card;
                }
                thread::sleep(Duration::from_millis(5));
            };
            before();
            answering
                .tool_prompts()
                .resolve_question(&card.prompt_id, response)
                .unwrap();
            card
        })
    }

    fn ask_user_call_response(extra_call: Option<Value>) -> Value {
        let mut output = vec![
            json!({"type":"message","status":"completed","role":"assistant","content":[{"type":"output_text","text":"我需要先确认方向"}]}),
            json!({"type":"function_call","status":"completed","call_id":"call-ask","name":"ask_user",
             "arguments": json!({"questions":[
                 {"question":"选哪个数据库？","header":"数据库","options":[
                     {"label":"Postgres","description":"服务端"},
                     {"label":"SQLite","description":"嵌入式"}
                 ],"multiSelect":false},
                 {"question":"部署到哪？","header":"部署","options":[
                     {"label":"Fly","description":"简单"},
                     {"label":"AWS","description":"全面"}
                 ],"multiSelect":false}
             ]}).to_string()}),
        ];
        output.extend(extra_call);
        json!({
            "model": "model-test",
            "status": "completed",
            "output": output,
            "usage": {"input_tokens":1,"output_tokens":1,"total_tokens":2}
        })
    }

    fn question_response(
        action: crate::tool_prompt::QuestionAction,
        answers: &[Option<&str>],
    ) -> crate::tool_prompt::QuestionResponse {
        crate::tool_prompt::QuestionResponse {
            action,
            answers: answers.iter().map(|answer| answer.map(str::to_owned)).collect(),
            previews: Vec::new(),
            notes: Vec::new(),
        }
    }

    fn ask_user_context(response: &RunModelResponse) -> (&JsonObject, Option<&JsonObject>, &ToolResult) {
        response
            .contexts
            .iter()
            .find_map(|context| match context {
                ContextItem::Tool {
                    tool_name,
                    input,
                    requested_input,
                    result,
                    ..
                } if tool_name == "ask_user" => Some((input, requested_input.as_ref(), result)),
                _ => None,
            })
            .expect("ask_user settled")
    }

    /// The call blocks on the card and the answers come back as its own result,
    /// in the same turn: the model is asked again with the tool result, and the
    /// executed input carries the answers while the model's own input is kept
    /// for replay.
    #[test]
    fn ask_user_blocks_on_the_card_and_answers_in_its_tool_result() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = serve_json_sequence(
            listener,
            vec![ask_user_call_response(None), responses_text_output("好的，用 Postgres")],
        );
        let workspace = tempfile::tempdir().unwrap();
        let state = AppState::default();
        let answering = answer_question_card(
            &state,
            question_response(crate::tool_prompt::QuestionAction::Submit, &[Some("Postgres"), None]),
            || {},
        );
        let response = run_model(
            loop_request_for(address, workspace.path()),
            &state,
            &discard_event,
            &approve_tool,
        )
        .unwrap();
        let card = answering.join().unwrap();
        let captured = server.join().unwrap();

        assert_eq!(card.kind, crate::tool_prompt::PromptKind::Question);
        assert_eq!(card.questions.as_ref().and_then(Value::as_array).map(Vec::len), Some(2));
        let (input, requested_input, result) = ask_user_context(&response);
        assert!(result.success);
        assert_eq!(
            result.output,
            "Your questions have been answered: \"选哪个数据库？\"=\"Postgres\". You can now continue with these answers in mind."
        );
        assert_eq!(input["answers"], json!({"选哪个数据库？": "Postgres"}));
        assert!(requested_input.is_some_and(|requested| !requested.contains_key("answers")));
        assert_eq!(captured.len(), 2);
        assert!(captured[1].contains("Your questions have been answered"));
        assert_ne!(response.stop_reason.as_deref(), Some(crate::ask_user::QUESTION_CLOSED_STOP_REASON));
    }

    /// Closing the card is the whole answer: the result says so, the rest of
    /// the round is skipped, and no further request goes out.
    #[test]
    fn closing_the_question_card_ends_the_turn_without_another_request() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = thread::spawn(move || {
            let (mut stream, _) = listener.accept().unwrap();
            let _request = read_http_request_with_body(&mut stream);
            write_json_response(
                &mut stream,
                "200 OK",
                &ask_user_call_response(Some(json!({
                    "type":"function_call","status":"completed","call_id":"call-read","name":"read",
                    "arguments": json!({"path":"probe.txt"}).to_string()
                }))),
            );
            drop(stream);
            listener.set_nonblocking(true).unwrap();
            thread::sleep(Duration::from_millis(50));
            listener.accept().is_ok()
        });
        let workspace = tempfile::tempdir().unwrap();
        let state = AppState::default();
        let answering = answer_question_card(
            &state,
            question_response(crate::tool_prompt::QuestionAction::Close, &[]),
            || {},
        );
        let response = run_model(
            loop_request_for(address, workspace.path()),
            &state,
            &discard_event,
            &approve_tool,
        )
        .unwrap();
        answering.join().unwrap();
        let made_second_request = server.join().unwrap();

        assert!(!made_second_request, "closing the card must not ask the model again");
        assert_eq!(
            response.stop_reason.as_deref(),
            Some(crate::ask_user::QUESTION_CLOSED_STOP_REASON)
        );
        let (input, _, result) = ask_user_context(&response);
        assert_eq!(result.output, crate::ask_user::QUESTION_CLOSED);
        assert!(!input.contains_key("answers"));
        let read = tool_output(&response, "read");
        assert!(!read.success);
        assert_eq!(read.output, crate::ask_user::INTERRUPTED_CALL_SKIPPED);
    }

    /// A composer message sent while the card is up is steered in before the
    /// card closes, so the closed result is followed by that message and the
    /// model is asked again with both.
    #[test]
    fn a_message_sent_while_the_card_is_up_follows_its_result() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = serve_json_sequence(
            listener,
            vec![ask_user_call_response(None), responses_text_output("收到")],
        );
        let workspace = tempfile::tempdir().unwrap();
        let mut request = loop_request_for(address, workspace.path());
        let mailbox = Arc::new(crate::agents::AgentMailbox::default());
        request.steer_mailbox = AgentMailboxHandle(Some(Arc::clone(&mailbox)));
        let state = AppState::default();
        let steering = Arc::clone(&mailbox);
        let answering = answer_question_card(
            &state,
            question_response(crate::tool_prompt::QuestionAction::Close, &[]),
            move || {
                steering.push_message(crate::agents::MailboxMessage {
                    id: Some("queued-while-asked".into()),
                    content: "先别管数据库，看看日志".into(),
                    images: Vec::new(),
                    files: Vec::new(),
                    created_at: Some("2026-09-30T00:00:00Z".into()),
                });
            },
        );
        let response = run_model(request, &state, &discard_event, &approve_tool).unwrap();
        answering.join().unwrap();
        let captured = server.join().unwrap();

        assert_eq!(captured.len(), 2);
        let (_, _, result) = ask_user_context(&response);
        assert_eq!(result.output, crate::ask_user::QUESTION_CLOSED);
        let closed_at = captured[1].find(crate::ask_user::QUESTION_CLOSED).unwrap();
        let message_at = captured[1].find("先别管数据库，看看日志").unwrap();
        assert!(closed_at < message_at, "the message follows the tool result");
        assert_ne!(
            response.stop_reason.as_deref(),
            Some(crate::ask_user::QUESTION_CLOSED_STOP_REASON)
        );
    }

    /// Accepts one connection within `budget`, or gives up. A missing request is
    /// the failure mode these cutoff tests are looking for, and a blocking
    /// `accept` would report it as a hung test binary instead of a red one.
    fn accept_within(listener: &TcpListener, budget: Duration) -> Option<TcpStream> {
        listener.set_nonblocking(true).unwrap();
        let deadline = std::time::Instant::now() + budget;
        let accepted = loop {
            match listener.accept() {
                Ok((stream, _)) => break Some(stream),
                Err(ref error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                    if std::time::Instant::now() >= deadline {
                        break None;
                    }
                    thread::sleep(Duration::from_millis(10));
                }
                Err(error) => panic!("接受连接失败：{error}"),
            }
        };
        listener.set_nonblocking(false).unwrap();
        if let Some(stream) = accepted.as_ref() {
            stream.set_nonblocking(false).unwrap();
        }
        accepted
    }

    /// A stub server promised more requests than the run actually makes used to park in a
    /// blocking `accept` forever. The test's own `server.join()` then never returned, so the
    /// binary hung — with libtest's summary already on screen — instead of going red, and the
    /// leftover process kept holding its own image open.
    ///
    /// The wait is bounded now, and the panic names the request that never arrived.
    #[test]
    fn a_stub_server_missing_a_request_fails_with_its_phase_instead_of_hanging() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let budget = Duration::from_millis(300);
        // Two responses queued; exactly one request will ever be made.
        let server = serve_json_sequence_within(
            listener,
            vec![responses_text_output("一"), responses_text_output("二")],
            budget,
        );

        let mut stream = TcpStream::connect(address).unwrap();
        stream
            .write_all(b"POST /v1/responses HTTP/1.1\r\nHost: x\r\nContent-Length: 2\r\n\r\n{}")
            .unwrap();
        let mut sink = Vec::new();
        stream.read_to_end(&mut sink).unwrap();
        drop(stream);
        // Proves the first leg really ran, so the failure below is the missing second request
        // and not a fixture that never started.
        assert!(
            String::from_utf8_lossy(&sink).contains("response.completed"),
            "第一个请求应当已被正常应答：{}",
            String::from_utf8_lossy(&sink)
        );

        let deadline = std::time::Instant::now() + budget * 20;
        while !server.is_finished() && std::time::Instant::now() < deadline {
            thread::sleep(Duration::from_millis(10));
        }
        assert!(
            server.is_finished(),
            "夹具仍卡在 accept 里：join() 永远不会返回，测试二进制会挂死而不是变红"
        );

        let panic = server.join().expect_err("缺席的请求必须让夹具失败");
        let message = panic
            .downcast_ref::<String>()
            .cloned()
            .or_else(|| panic.downcast_ref::<&str>().map(|text| (*text).to_owned()))
            .unwrap_or_default();
        assert!(
            message.contains("等待第 2 个请求（共 2 个）超时"),
            "失败信息要说清缺的是哪一个请求：{message}"
        );
    }

    /// A structured result is the run's deliverable. Complete all same-round
    /// parallel siblings, then do not send that round back to the model; a second
    /// connection would prove the cutoff failed.
    #[test]
    fn anthropic_output_limit_continues_at_most_three_times_in_one_round() {
        for (reasons, expected) in [
            (vec!["max_tokens", "end_turn"], 2usize),
            (vec!["max_tokens"; 4], 4),
            (vec!["end_turn"], 1),
            (vec!["model_context_window_exceeded"], 1),
        ] {
            let listener = TcpListener::bind("127.0.0.1:0").unwrap();
            let address = listener.local_addr().unwrap();
            let server_reasons = reasons.clone();
            let server = thread::spawn(move || {
                let mut requests = Vec::new();
                for reason in server_reasons {
                    let Some(mut stream) = accept_within(&listener, Duration::from_secs(3)) else {
                        break;
                    };
                    requests.push(read_http_request_with_body(&mut stream));
                    let events = [
                        json!({"type":"message_start","message":{"id":"limit-message","type":"message","role":"assistant","model":"model-test","content":[],"stop_reason":null,"stop_sequence":null,"usage":{"input_tokens":10,"output_tokens":0}}}),
                        json!({"type":"content_block_start","index":0,"content_block":{"type":"text","text":""}}),
                        json!({"type":"content_block_delta","index":0,"delta":{"type":"text_delta","text":"chunk"}}),
                        json!({"type":"content_block_stop","index":0}),
                        json!({"type":"message_delta","delta":{"stop_reason":reason,"stop_sequence":null},"usage":{"output_tokens":5}}),
                        json!({"type":"message_stop"}),
                    ];
                    let body = events
                        .iter()
                        .map(|event| {
                            format!(
                                "event: {}\ndata: {}\n\n",
                                event["type"].as_str().unwrap(),
                                event
                            )
                        })
                        .collect::<String>();
                    write_sse_response(&mut stream, &body);
                }
                assert!(
                    accept_within(&listener, Duration::from_millis(250)).is_none(),
                    "unexpected extra continuation"
                );
                requests
            });
            let workspace = tempfile::tempdir().unwrap();
            let mut request = loop_request_for(address, workspace.path());
            request.provider.family = ProviderFamily::Anthropic;
            let response =
                run_model(request, &AppState::default(), &discard_event, &approve_tool).unwrap();
            let requests = server.join().unwrap();
            assert_eq!(requests.len(), expected, "{reasons:?}: {response:?}");
            assert!(response.error.is_none(), "{response:?}");
            assert_eq!(response.usage.output_tokens, Some(5 * expected as u64));
            assert_eq!(response.usage.input_tokens, Some(10 * expected as u64));
            let prose = response
                .contexts
                .iter()
                .filter_map(|context| match context {
                    ContextItem::Assistant { content, round, .. } => {
                        assert_eq!(*round, Some(1));
                        Some(content.as_str())
                    }
                    _ => None,
                })
                .collect::<Vec<_>>();
            assert_eq!(prose, vec![vec!["chunk"; expected].join("\n")]);
            for body in requests.iter().skip(1) {
                assert!(
                    body.contains("chunk")
                        && body.contains("Please continue from where you left off")
                );
            }
            assert_eq!(
                response.stop_reason.as_deref(),
                Some(if reasons.last() == Some(&"end_turn") {
                    "stop"
                } else {
                    "length"
                })
            );
        }
    }

    /// A model carries no tool capability any more, so the schema installs on
    /// every model. It must land exactly once even when the descriptor list is
    /// already carrying it.
    #[test]
    fn structured_output_installs_on_any_model_exactly_once() {
        let workspace = tempfile::tempdir().unwrap();
        let mut request = loop_request_for("127.0.0.1:9".parse().unwrap(), workspace.path());
        request.model.capabilities.clear();
        install_structured_output(&mut request, structured_output_schema()).unwrap();
        assert!(request.output_schema.is_some());
        let installed = request
            .enabled_tools
            .iter()
            .filter(|name| *name == STRUCTURED_OUTPUT_TOOL)
            .count();
        assert_eq!(installed, 1);

        install_structured_output(&mut request, structured_output_schema()).unwrap();
        assert_eq!(
            request
                .enabled_tools
                .iter()
                .filter(|name| *name == STRUCTURED_OUTPUT_TOOL)
                .count(),
            1,
            "重复安装不该让 enabled_tools 里出现第二份"
        );
    }

    #[test]
    fn a_settled_structured_output_finishes_the_turn_but_opens_no_next_one() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = thread::spawn(move || {
            let (mut stream, _) = listener.accept().unwrap();
            let _request = read_http_request_with_body(&mut stream);
            write_sse_response(
                &mut stream,
                &responses_sse(&json!({
                    "model": "model-test",
                    "status": "completed",
                    "output": [
                        {"type":"message","status":"completed","role":"assistant",
                         "content":[{"type":"output_text","text":"结论如下"}]},
                        {"type":"function_call","status":"completed","call_id":"call-structured",
                         "name":STRUCTURED_OUTPUT_TOOL,
                         "arguments": json!({"verdict":"ok","score":7}).to_string()},
                        {"type":"function_call","status":"completed","call_id":"call-write","name":"write",
                         "arguments": json!({"path":"after.txt","content":"同轮兄弟照常执行"}).to_string()}
                    ],
                    "usage": {"input_tokens":1,"output_tokens":1,"total_tokens":2}
                })),
            );
            drop(stream);
            accept_within(&listener, Duration::from_millis(250)).is_some()
        });

        let workspace = tempfile::tempdir().unwrap();
        let mut request = loop_request_for(address, workspace.path());
        request.subagent_depth = 1;
        install_structured_output(&mut request, structured_output_schema()).unwrap();
        let response =
            run_model(request, &AppState::default(), &discard_event, &approve_tool).unwrap();
        let made_second_request = server.join().unwrap();

        assert!(
            !made_second_request,
            "a validated structured result must end the run without another API request"
        );
        assert_eq!(
            response.structured_output,
            Some(json!({"verdict":"ok","score":7})),
            "the run still hands back the validated value"
        );
        assert_eq!(
            response.stop_reason.as_deref(),
            Some(STRUCTURED_OUTPUT_STOP_REASON)
        );
        // Settlement reasons must not classify a successful run as failed or
        // stopped; only `Completed` harvests structured output.
        assert_eq!(
            subagent_run_status(response.stop_reason.as_deref()),
            SubagentRunStatus::Completed
        );
        assert!(response.error.is_none());

        let tools = response
            .contexts
            .iter()
            .filter_map(|context| match context {
                ContextItem::Tool {
                    tool_name, result, ..
                } => Some((tool_name.as_str(), result)),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(tools.len(), 2, "每个报过名的调用都要留下一张卡");
        assert_eq!(tools[0].0, STRUCTURED_OUTPUT_TOOL);
        assert!(tools[0].1.success);
        // The round is atomic: same-round siblings execute even if ordered later.
        assert_eq!(tools[1].0, "write");
        assert!(
            tools[1].1.success,
            "同轮的并行兄弟调用必须照常执行：{}",
            tools[1].1.output
        );
        assert!(
            workspace.path().join("after.txt").exists(),
            "同轮兄弟的副作用必须真的发生"
        );
    }

    /// Cut off only after the host accepts the value, not when the model calls the
    /// tool. A blocking PostToolUse rollback means no delivery and requires retry.
    #[test]
    fn a_hook_blocked_structured_output_call_does_not_end_the_run() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = thread::spawn(move || {
            let mut rounds = 0usize;
            for value in [
                json!({"verdict":"blocked-by-hook"}),
                json!({"verdict":"ok","score":7}),
            ] {
                let Some(mut stream) = accept_within(&listener, Duration::from_secs(20)) else {
                    return (rounds, false);
                };
                let _request = read_http_request_with_body(&mut stream);
                write_sse_response(
                    &mut stream,
                    &responses_sse(&json!({
                        "model": "model-test",
                        "status": "completed",
                        "output": [
                            {"type":"function_call","status":"completed",
                             "call_id":format!("call-structured-{rounds}"),
                             "name":STRUCTURED_OUTPUT_TOOL,
                             "arguments": value.to_string()}
                        ],
                        "usage": {"input_tokens":1,"output_tokens":1,"total_tokens":2}
                    })),
                );
                drop(stream);
                rounds += 1;
            }
            let extra = accept_within(&listener, Duration::from_millis(250)).is_some();
            (rounds, extra)
        });

        let workspace = tempfile::tempdir().unwrap();
        let mut request = loop_request_for(address, workspace.path());
        request.subagent_depth = 1;
        install_structured_output(&mut request, structured_output_schema()).unwrap();
        #[cfg(windows)]
        let command = "$body = [Console]::In.ReadToEnd(); if ($body -match 'blocked-by-hook') { [Console]::Error.Write('blocked structured result'); exit 2 }";
        #[cfg(not(windows))]
        let command = "body=$(cat); case \"$body\" in *blocked-by-hook*) printf 'blocked structured result' >&2; exit 2;; esac";
        request.active_hooks = vec![HookDefinition {
            id: "block-structured-output".into(),
            name: "Block the first structured result".into(),
            event: HookEvent::PostToolUse,
            matcher: Some(format!("^{STRUCTURED_OUTPUT_TOOL}$")),
            command: command.into(),
            command_windows: None,
            status_message: None,
            enabled: true,
            timeout_ms: 5_000,
        }];

        let response =
            run_model(request, &AppState::default(), &discard_event, &approve_tool).unwrap();
        let (rounds, made_extra_request) = server.join().unwrap();

        assert_eq!(rounds, 2, "回滚掉的那一轮不算交付，运行必须继续");
        assert!(
            !made_extra_request,
            "第二次交付通过后才轮到掐断，此后不得再请求"
        );
        assert_eq!(
            response.structured_output,
            Some(json!({"verdict":"ok","score":7})),
            "交回的必须是被放行的那个值"
        );
        assert_eq!(
            response.stop_reason.as_deref(),
            Some(STRUCTURED_OUTPUT_STOP_REASON)
        );

        let tools = response
            .contexts
            .iter()
            .filter_map(|context| match context {
                ContextItem::Tool {
                    tool_name, result, ..
                } => Some((tool_name.as_str(), result)),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(tools.len(), 2);
        assert!(tools.iter().all(|tool| tool.0 == STRUCTURED_OUTPUT_TOOL));
        assert!(!tools[0].1.success, "被 Hook 阻断的那次是失败回执");
        assert!(tools[1].1.success);
    }

    #[test]
    fn agent_spawn_runs_a_background_child_and_task_wait_returns_its_result() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let task = "检查工作区里的 probe.txt 并总结内容";
        // `task_wait` returns accumulated progress with the terminal result.
        // The parent must not resume after the first update.
        // queues deterministic however the parent and child connections
        // interleave.
        let server = serve_routed_json(
            listener,
            vec![
                // Parent round 1: spawn the agent, then wait for it.
                json!({
                    "model": "model-test",
                    "status": "completed",
                    "output": [
                        {"type":"function_call","status":"completed","call_id":"call-spawn","name":"agent_spawn",
                            "arguments": json!({"prompt": task, "name": "probe", "label": "检查"}).to_string()},
                        {"type":"function_call","status":"completed","call_id":"call-wait-1","name":"task_wait",
                            "arguments": json!({"timeout_seconds": 120}).to_string()}
                    ],
                    "usage": {"input_tokens":1,"output_tokens":1,"total_tokens":2}
                }),
                // Parent round 2: summarize using the agent result.
                responses_text_output("主代理总结完成"),
            ],
            vec![
                // Child round 1: report progress, then read a workspace file.
                json!({
                    "model": "model-test",
                    "status": "completed",
                    "output": [
                        {"type":"function_call","status":"completed","call_id":"call-child-update","name":"subagent_update",
                            "arguments": json!({"message":"已定位 probe.txt，准备读取"}).to_string()},
                        {"type":"function_call","status":"completed","call_id":"call-child-read","name":"read",
                            "arguments": json!({"path":"probe.txt"}).to_string()}
                    ],
                    "usage": {"input_tokens":1,"output_tokens":1,"total_tokens":2}
                }),
                // Child round 2: final answer.
                responses_text_output("子代理结论：probe 内容正常"),
            ],
        );

        let workspace = tempfile::tempdir().unwrap();
        std::fs::write(workspace.path().join("probe.txt"), "probe-content").unwrap();
        let request = loop_request_for(address, workspace.path());
        let conversation_id = request.conversation_id.clone();
        let events = Arc::new(Mutex::new(Vec::new()));
        let event_capture = Arc::clone(&events);
        let state = AppState::default();
        // Child lifecycle and progress updates use the conversation surface; run events
        // still use the run sink. Both feed this collector.
        install_collecting_surface(&state, &request.conversation_id, Arc::clone(&events));
        let response = run_model(
            request,
            &state,
            &move |event| {
                event_capture
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .push(event);
                Ok(())
            },
            &approve_tool,
        )
        .unwrap();
        let (parent_bodies, child_bodies) = server.join().unwrap();

        // The wait handed the child's result to the model and the batch that carried it was
        // confirmed, so its ledger entry is settled: a restart now has nothing to report lost.
        let ledger = workspace.path().join("subagents").join(&conversation_id);
        assert!(
            !ledger.join("agent-probe.json").exists(),
            "已交付的子代理不得留在存活账目里"
        );
        assert!(
            state.take_ledgered_subagents(&conversation_id, |_| true).is_empty(),
            "进程内账目同样已销"
        );

        // The spawn result returns immediately; the persisted run record is
        // backfilled onto the same tool context at turn end.
        let (spawn_result, spawn_record) = response
            .contexts
            .iter()
            .find_map(|context| match context {
                ContextItem::Tool {
                    tool_name,
                    result,
                    subagent,
                    ..
                } if tool_name == "agent_spawn" => Some((result, subagent.as_ref())),
                _ => None,
            })
            .expect("agent_spawn tool context");
        assert!(spawn_result.success, "{}", spawn_result.output);
        assert_eq!(spawn_result.output, "ok");
        let record = spawn_record.expect("backfilled agent run record");
        assert_eq!(record.name.as_deref(), Some("probe"));
        assert_eq!(record.task, task);
        assert_eq!(record.status, SubagentRunStatus::Completed);
        assert_eq!(record.updates.len(), 1);
        assert_eq!(record.updates[0].content, "已定位 probe.txt，准备读取");
        assert!(matches!(
            record.contexts.first(),
            Some(ContextItem::User {
                id,
                content,
                images,
                files,
                created_at,
            }) if id.starts_with("ctx_subagent-task_")
                && content == task
                && images.is_empty()
                && files.is_empty()
                && !created_at.is_empty()
        ));
        assert!(record.contexts.iter().any(|context| matches!(
            context,
            ContextItem::Tool {
                tool_name,
                ..
            } if tool_name == SUBAGENT_UPDATE_TOOL
        )));
        assert!(record.contexts.iter().any(|context| matches!(
            context,
            ContextItem::Tool {
                tool_name,
                ..
            } if tool_name == "read"
        )));
        assert!(record.contexts.iter().any(|context| matches!(
            context,
            ContextItem::Assistant { content, .. } if content == "子代理结论：probe 内容正常"
        )));

        // A blocking wait returns child progress and its terminal result in its own tool receipt.
        let wait_outputs = response
            .contexts
            .iter()
            .filter_map(|context| match context {
                ContextItem::Tool {
                    id,
                    tool_name,
                    result,
                    ..
                } if tool_name == "task_wait"
                    // Host deliveries wear the same tool role; the id prefix is
                    // what tells a model-issued wait from a host-minted one.
                    && !id.starts_with(AGENT_RESULT_CONTEXT_ID_PREFIX) =>
                {
                    assert!(result.success, "{}", result.output);
                    Some(result.output.clone())
                }
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            wait_outputs.len(),
            1,
            "one blocking wait collects everything"
        );
        let wait = &wait_outputs[0];
        assert!(
            wait.contains(&format!(
                "[probe · {}]",
                PromptKey::TaskProgressUpdateLabel.builtin_en()
            )),
            "{wait}"
        );
        assert!(wait.contains("已定位 probe.txt，准备读取"), "{wait}");
        assert!(
            wait.contains(&format!(
                "[probe · {}]",
                PromptKey::TaskStatusCompleted.builtin_en()
            )),
            "{wait}"
        );
        assert!(wait.contains("子代理结论：probe 内容正常"), "{wait}");
        // A completed wait returns through the tool receipt, not a folded user context.
        assert!(
            !response.contexts.iter().any(|context| matches!(
                context,
                ContextItem::Tool { id, .. } if id.starts_with(AGENT_RESULT_CONTEXT_ID_PREFIX)
            )),
            "a wait that collected the result must leave nothing for the fold"
        );

        assert!(response.contexts.iter().any(|context| matches!(
            context,
            ContextItem::Assistant { content, .. } if content == "主代理总结完成"
        )));
        // Parent usage includes the child's rounds (4 mocked responses × 2 tokens).
        assert_eq!(response.usage.total_tokens, Some(8));

        // The child request is isolated: subagent addendum + task only, and no
        // host-loop tools are advertised to it. The one internal update
        // capability is injected only into this child request.
        let child_round_one: Value =
            serde_json::from_str(child_bodies[0].split("\r\n\r\n").nth(1).unwrap()).unwrap();
        // AI SDK sends system prompts as input items rather than top-level instructions.
        // This verifies that the child instruction reaches the model, not its field location.
        assert!(
            child_bodies[0].contains(
                PromptKey::SubagentAddendum
                    .builtin_en()
                    .lines()
                    .next()
                    .unwrap()
            ),
            "子代理系统提示词必须抵达模型：{}",
            child_bodies[0]
        );
        let child_input = child_round_one["input"].as_array().unwrap();
        assert!(has_message(child_input, "user", &task));
        assert!(
            !child_bodies[0].contains("Read the file."),
            "child must not see parent history"
        );
        let child_tools = child_round_one["tools"].as_array().unwrap();
        assert!(child_tools.iter().any(|tool| tool["name"] == "read"));
        assert!(child_tools
            .iter()
            .any(|tool| tool["name"] == SUBAGENT_UPDATE_TOOL));
        for name in [
            "agent_spawn",
            "agent_send",
            "send_message",
            "followup_task",
            "ask_user",
        ] {
            assert!(
                !child_tools.iter().any(|tool| tool["name"] == name),
                "{name} must not be advertised to the child"
            );
        }
        // `task_wait` / `task_list` are the exception, and they are not
        // inherited: the parent's pair is stripped with the rest of the
        // orchestration group, then re-derived because this child holds task
        // PRODUCERS of its own (`bash`, `web_search`, …). A child that could
        // start a background task and not collect it would be holding a receipt
        // it can never redeem.
        for name in ["task_wait", "task_list"] {
            assert!(
                child_tools.iter().any(|tool| tool["name"] == name),
                "{name} must be re-derived for a child holding a task producer"
            );
        }

        // Exchanges accumulate within the turn, so the parent's final round
        // request carries the drained wait output with the child's answer.
        assert!(parent_bodies.last().unwrap().contains("子代理结论"));

        // The child's normalized stream keeps its tool structure while
        // lifecycle and explicit progress remain parent-facing deltas.
        let captured_events = events
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let deltas = captured_events
            .iter()
            .filter_map(|event| match event {
                ModelStreamEvent::SubagentDelta {
                    call_id,
                    channel,
                    delta,
                    ..
                } if call_id == "call-spawn" => Some((*channel, delta.clone())),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(deltas
            .iter()
            .any(|(channel, delta)| *channel == SubagentChannel::Status && delta == "running"));
        assert!(deltas
            .iter()
            .any(|(channel, delta)| *channel == SubagentChannel::Status && delta == "idle"));
        assert!(deltas
            .iter()
            .any(|(channel, delta)| *channel == SubagentChannel::Update
                && delta == "已定位 probe.txt，准备读取"));
        let nested = captured_events
            .iter()
            .filter_map(|event| match event {
                ModelStreamEvent::SubagentEvent { call_id, event, .. }
                    if call_id == "call-spawn" =>
                {
                    Some(event.as_ref())
                }
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(nested.iter().any(|event| matches!(
            event,
            ModelStreamEvent::ToolCallAnnounced {
                call_id,
                tool_name,
                ..
            } if call_id == "call-child-read" && tool_name == "read"
        )));
        assert!(nested.iter().any(|event| matches!(
            event,
            ModelStreamEvent::ToolExecutionCompleted {
                call_id,
                result,
                ..
            } if call_id == "call-child-read" && result.success
        )));
    }

    #[test]
    fn child_event_forwarding_preserves_an_already_nested_agent_stream() {
        let pool = AgentPool::new();
        let template = agent_child_template(&run_request(ProviderFamily::OpenaiResponses));
        let shared = pool
            .register(
                "executor".into(),
                "executor".into(),
                "research task".into(),
                template,
                SubagentRunKind::General,
                &AppState::default(),
                Vec::new(),
                Vec::new(),
                AgentLiveStatus::Running,
                "dispatch-call".into(),
                None,
            )
            .unwrap();
        let captured = Mutex::new(Vec::new());
        let sink = |event| {
            captured
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
                .push(event);
            Ok(())
        };
        let child_tool_calls = Mutex::new(HashMap::new());

        forward_child_event(
            &shared,
            shared.identity(),
            &sink,
            2,
            "dispatch-call",
            &child_tool_calls,
            ModelStreamEvent::SubagentDelta {
                round: 1,
                call_id: "fetch-call".into(),
                channel: SubagentChannel::Status,
                delta: "running".into(),
            },
        )
        .unwrap();

        let events = captured.into_inner().unwrap();
        assert!(matches!(
            events.as_slice(),
            [ModelStreamEvent::SubagentEvent {
                round: 2,
                call_id,
                event,
            }] if call_id == "dispatch-call"
                && matches!(
                    event.as_ref(),
                    ModelStreamEvent::SubagentDelta {
                        round: 1,
                        call_id,
                        channel: SubagentChannel::Status,
                        delta,
                    } if call_id == "fetch-call" && delta == "running"
                )
        ));
    }

    #[test]
    fn two_same_round_agent_spawns_reach_the_model_backend_concurrently() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = thread::spawn(move || {
            let (mut parent, _) = listener.accept().unwrap();
            let _parent_body = read_http_request_with_body(&mut parent);
            write_json_response(
                &mut parent,
                "200 OK",
                &json!({
                    "model":"model-test",
                    "status":"completed",
                    "output":[
                        {"type":"function_call","status":"completed","call_id":"spawn-alpha","name":"agent_spawn",
                            "arguments":json!({"prompt":"Alpha task","name":"alpha"}).to_string()},
                        {"type":"function_call","status":"completed","call_id":"spawn-beta","name":"agent_spawn",
                            "arguments":json!({"prompt":"Beta task","name":"beta"}).to_string()},
                        {"type":"function_call","status":"completed","call_id":"wait-both","name":"task_wait",
                            "arguments":json!({"agents":["alpha","beta"],"timeout_seconds":120}).to_string()}
                    ],
                    "usage":{"input_tokens":1,"output_tokens":1,"total_tokens":2}
                }),
            );
            // Close the parent connection so the process-shared HTTP client
            // cannot keep-alive it into the pool; every following request must
            // arrive as a fresh accept for the concurrency barrier to observe.
            drop(parent);

            // Do not answer the first child until the second child has also
            // connected. A serial scheduler cannot pass this barrier.
            let (mut first_child, _) = listener.accept().unwrap();
            let first_body = read_http_request_with_body(&mut first_child);
            listener.set_nonblocking(true).unwrap();
            let deadline = Instant::now() + Duration::from_secs(2);
            let mut second_child = loop {
                match listener.accept() {
                    Ok((stream, _)) => break stream,
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                        assert!(
                            Instant::now() < deadline,
                            "second child never ran concurrently"
                        );
                        thread::sleep(Duration::from_millis(5));
                    }
                    Err(error) => panic!("accepting second child failed: {error}"),
                }
            };
            // On Windows a socket accepted from a nonblocking listener inherits
            // nonblocking mode; restore blocking reads before waiting for the
            // request body, otherwise this read races the client's write.
            second_child.set_nonblocking(false).unwrap();
            let second_body = read_http_request_with_body(&mut second_child);
            listener.set_nonblocking(false).unwrap();
            let first_answer = if first_body.contains("Alpha task") {
                "Alpha done"
            } else {
                "Beta done"
            };
            let second_answer = if second_body.contains("Alpha task") {
                "Alpha done"
            } else {
                "Beta done"
            };
            write_json_response(
                &mut first_child,
                "200 OK",
                &responses_text_output(first_answer),
            );
            write_json_response(
                &mut second_child,
                "200 OK",
                &responses_text_output(second_answer),
            );
            // Same keep-alive hygiene as the parent connection above.
            drop(first_child);
            drop(second_child);

            let (mut parent_final, _) = listener.accept().unwrap();
            let _parent_final_body = read_http_request_with_body(&mut parent_final);
            write_json_response(
                &mut parent_final,
                "200 OK",
                &responses_text_output("Both children finished"),
            );
            vec![first_body, second_body]
        });

        let workspace = tempfile::tempdir().unwrap();
        let response = run_model(
            loop_request_for(address, workspace.path()),
            &AppState::default(),
            &discard_event,
            &approve_tool,
        )
        .unwrap();
        let child_bodies = server.join().unwrap();

        assert_eq!(child_bodies.len(), 2);
        assert!(child_bodies.iter().any(|body| body.contains("Alpha task")));
        assert!(child_bodies.iter().any(|body| body.contains("Beta task")));
        assert!(response.contexts.iter().any(|context| matches!(
            context,
            ContextItem::Assistant { content, .. } if content == "Both children finished"
        )));
    }

    /// A parent starts its next model request while an unwaited child task is running.
    /// The server holds the child request until the parent's second request arrives,
    /// proving derivation does not block round completion.
    #[test]
    fn a_parent_keeps_rounding_while_its_spawned_child_is_still_running() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = thread::spawn(move || {
            let (mut parent, _) = listener.accept().unwrap();
            let _ = read_http_request_with_body(&mut parent);
            write_json_response(
                &mut parent,
                "200 OK",
                &json!({
                    "model":"model-test",
                    "status":"completed",
                    "output":[
                        {"type":"function_call","status":"completed","call_id":"spawn-slow","name":"agent_spawn",
                            "arguments":json!({"prompt":"Slow task","name":"slowpoke"}).to_string()}
                    ],
                    "usage":{"input_tokens":1,"output_tokens":1,"total_tokens":2}
                }),
            );
            // Keep-alive hygiene: every later request must arrive as a fresh
            // accept for the barrier to observe.
            drop(parent);

            // Child and parent requests can arrive in either order. Hold the child until
            // the parent's second request proves the child did not block it.
            listener.set_nonblocking(true).unwrap();
            let deadline = Instant::now() + Duration::from_secs(5);
            let mut child: Option<(std::net::TcpStream, String)> = None;
            let mut parent_round2: Option<std::net::TcpStream> = None;
            while parent_round2.is_none() || child.is_none() {
                match listener.accept() {
                    Ok((mut stream, _)) => {
                        stream.set_nonblocking(false).unwrap();
                        let body = read_http_request_with_body(&mut stream);
                        // The parent's second request carries the agent_spawn receipt;
                        // child-round requests do not. Route by context, not receipt wording.
                        if body.contains("function_call_output") {
                            parent_round2 = Some(stream);
                        } else {
                            child = Some((stream, body));
                        }
                    }
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                        assert!(
                            Instant::now() < deadline,
                            "父模型在子任务运行期间没有推进下一轮（parent_round2 到达={} child 到达={}）",
                            parent_round2.is_some(),
                            child.is_some()
                        );
                        thread::sleep(Duration::from_millis(5));
                    }
                    Err(error) => panic!("accepting a connection failed: {error}"),
                }
            }
            listener.set_nonblocking(false).unwrap();
            let (mut child_stream, child_body) = child.unwrap();
            let mut parent2_stream = parent_round2.unwrap();
            assert!(child_body.contains("Slow task"), "被扣住的连接不是子请求");
            write_json_response(
                &mut parent2_stream,
                "200 OK",
                &json!({
                    "model":"model-test",
                    "status":"completed",
                    "output":[
                        {"type":"function_call","status":"completed","call_id":"wait-slow","name":"task_wait",
                            "arguments":json!({"agents":["slowpoke"],"timeout_seconds":120}).to_string()}
                    ],
                    "usage":{"input_tokens":1,"output_tokens":1,"total_tokens":2}
                }),
            );
            drop(parent2_stream);
            write_json_response(
                &mut child_stream,
                "200 OK",
                &responses_text_output("Slow child done"),
            );
            drop(child_stream);

            let (mut parent_final, _) = listener.accept().unwrap();
            let final_body = read_http_request_with_body(&mut parent_final);
            write_json_response(
                &mut parent_final,
                "200 OK",
                &responses_text_output("parent saw the result"),
            );
            final_body
        });

        let workspace = tempfile::tempdir().unwrap();
        let response = run_model(
            loop_request_for(address, workspace.path()),
            &AppState::default(),
            &discard_event,
            &approve_tool,
        )
        .unwrap();
        let final_body = server.join().unwrap();
        assert!(
            final_body.contains("Slow child done"),
            "task_wait 交付的信封没有把子结果送回模型"
        );
        assert!(response.contexts.iter().any(|context| matches!(
            context,
            ContextItem::Assistant { content, .. } if content == "parent saw the result"
        )));
    }

    /// `web_search` returns its findings envelope directly, without task records or
    /// client tools in the native request.
    ///
    /// The worker request must finish before the parent sends its next request with findings.
    #[test]
    fn web_search_returns_its_findings_as_the_call_result() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = serve_json_sequence(
            listener,
            vec![
                json!({
                    "model":"model-test",
                    "status":"completed",
                    "output":[
                        {"type":"function_call","status":"completed","call_id":"ws-bg","name":"web_search",
                            "arguments":json!({
                                "query":"Mework 的当前状态与已知问题"
                            }).to_string()}
                    ],
                    "usage":{"input_tokens":1,"output_tokens":1,"total_tokens":2}
                }),
                responses_text_output("FINDINGS: X 状态良好（来源 example.com）"),
                responses_text_output("search consumed"),
            ],
        );

        let workspace = tempfile::tempdir().unwrap();
        let mut request = loop_request_for(address, workspace.path());
        if !request
            .enabled_tools
            .iter()
            .any(|name| name == WEB_SEARCH_TOOL)
        {
            request.tools = catalog::tool_catalog();
            request.enabled_tools = request.tools.iter().map(|tool| tool.name.clone()).collect();
        }
        request.web_search = crate::model::WebSearchSettings {
            max_searches_per_call: 0,
            backend: Some(SearchBackend::Native),
            ..Default::default()
        };
        let state = AppState::default();
        let response = run_model(request, &state, &discard_event, &approve_tool).unwrap();
        let bodies = server.join().unwrap();
        let search_body = &bodies[1];
        let round2 = &bodies[2];
        assert!(
            search_body.contains("\"type\":\"web_search\""),
            "代发请求必须挂上原生服务端搜索工具：{search_body}"
        );
        assert!(
            !search_body.contains("\"type\":\"function\""),
            "代发请求不得携带任何客户端工具：{search_body}"
        );
        assert!(
            round2.contains("FINDINGS"),
            "findings 必须就地作为工具结果回来：{round2}"
        );
        assert!(
            round2.contains("untrustedWebContent"),
            "结果必须保留不可信标注：{round2}"
        );
        assert!(
            !round2.contains("web_search:search-"),
            "检索不再是任务，不得再铸任务地址：{round2}"
        );
        // Route by context, not request definitions: derived `task_wait` is included
        // whenever task-producing tools are enabled.
        assert!(
            !response.contexts.iter().any(|context| matches!(
                context,
                ContextItem::Tool { tool_name, .. } if tool_name == "task_wait"
            )),
            "检索不再经 task_wait 交付"
        );
        assert!(response.contexts.iter().any(|context| matches!(
            context,
            ContextItem::Assistant { content, .. } if content == "search consumed"
        )));
        let (result, subagent) = response
            .contexts
            .iter()
            .find_map(|context| match context {
                ContextItem::Tool {
                    tool_name,
                    result,
                    subagent,
                    ..
                } if tool_name == "web_search" => Some((result, subagent)),
                _ => None,
            })
            .expect("web_search 应留下一条普通工具上下文");
        assert!(result.success, "{}", result.output);
        assert!(
            result.output.contains("FINDINGS"),
            "工具结果就是 findings 本身：{}",
            result.output
        );
        assert!(subagent.is_none(), "联网搜索不是子代理，不回填记录");
    }

    /// Multiple searches in one round run concurrently.
    /// All results merge into the same next request.
    ///
    /// The server blocks the first response until the second search connects. This
    /// connection barrier, rather than a sleep, proves concurrent dispatch.
    #[test]
    fn same_round_web_searches_run_concurrently_and_land_in_one_request() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let barrier = Arc::new(std::sync::Barrier::new(2));
        let server = std::thread::spawn(move || {
            let mut bodies = Vec::new();
            let (mut stream, _) = listener.accept().unwrap();
            bodies.push(read_http_request_with_body(&mut stream));
            write_sse_response(
                &mut stream,
                &responses_sse(&json!({
                    "model":"model-test",
                    "status":"completed",
                    "output":[
                        {"type":"function_call","status":"completed","call_id":"ws-1","name":"web_search",
                            "arguments":json!({"query":"第一个检索主题"}).to_string()},
                        {"type":"function_call","status":"completed","call_id":"ws-2","name":"web_search",
                            "arguments":json!({"query":"第二个检索主题"}).to_string()}
                    ],
                    "usage":{"input_tokens":1,"output_tokens":1,"total_tokens":2}
                })),
            );
            // Each search runs in its own thread and waits at the barrier before replying.
            let mut search_threads = Vec::new();
            for index in 0..2 {
                let (mut stream, _) = listener.accept().unwrap();
                let barrier = Arc::clone(&barrier);
                search_threads.push(std::thread::spawn(move || {
                    let body = read_http_request_with_body(&mut stream);
                    barrier.wait();
                    write_sse_response(
                        &mut stream,
                        &responses_sse(&responses_text_output(&format!("FINDINGS-{index}"))),
                    );
                    body
                }));
            }
            for handle in search_threads {
                bodies.push(handle.join().unwrap());
            }
            let (mut stream, _) = listener.accept().unwrap();
            bodies.push(read_http_request_with_body(&mut stream));
            write_sse_response(
                &mut stream,
                &responses_sse(&responses_text_output("both searches consumed")),
            );
            bodies
        });

        let workspace = tempfile::tempdir().unwrap();
        let mut request = loop_request_for(address, workspace.path());
        request.tools = catalog::tool_catalog();
        request.enabled_tools = request.tools.iter().map(|tool| tool.name.clone()).collect();
        request.web_search = crate::model::WebSearchSettings {
            max_searches_per_call: 0,
            backend: Some(SearchBackend::Native),
            ..Default::default()
        };
        let response =
            run_model(request, &AppState::default(), &discard_event, &approve_tool).unwrap();
        let bodies = server.join().unwrap();
        let round2 = bodies.last().unwrap();
        assert!(
            round2.contains("FINDINGS-0") && round2.contains("FINDINGS-1"),
            "两份 findings 必须并入同一次下一轮请求：{round2}"
        );
        assert!(response.contexts.iter().any(|context| matches!(
            context,
            ContextItem::Assistant { content, .. } if content == "both searches consumed"
        )));
    }

    /// Background shell dispatch returns immediately with a `shell:<id>` task address.
    /// A same-round `task_wait` returns command output through its envelope.
    #[test]
    fn a_background_shell_persistence_failure_returns_a_failed_receipt_without_a_task_address() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = serve_json_sequence(
            listener,
            vec![
                json!({
                    "model":"model-test", "status":"completed",
                    "output":[{"type":"function_call","status":"completed","call_id":"bg-disk-failure","name":"bash",
                        "arguments":json!({"command":"printf forbidden > should-not-exist.txt","run_in_background":true}).to_string()}],
                    "usage":{"input_tokens":1,"output_tokens":1,"total_tokens":2}
                }),
                responses_text_output("storage failure reported"),
            ],
        );
        let workspace = tempfile::tempdir().unwrap();
        let history = tempfile::tempdir().unwrap();
        let state = AppState::default();
        state.shell_tasks.install_store(history.path()).unwrap();
        let connection = rusqlite::Connection::open(
            history
                .path()
                .join(crate::shell_task_store::DATABASE_FILE_NAME),
        )
        .unwrap();
        connection.execute_batch("CREATE TRIGGER fail_background BEFORE INSERT ON shell_task BEGIN SELECT RAISE(FAIL, 'background durable registration denied'); END;").unwrap();
        let response = run_model(
            loop_request_for(address, workspace.path()),
            &state,
            &discard_event,
            &approve_tool,
        )
        .unwrap();
        let bodies = server.join().unwrap();
        assert!(bodies[1].contains("background durable registration denied"));
        // Scoped to the receipt: every request body also carries the tool descriptions, which
        // spell out the `shell:<id>` address form.
        assert!(
            !bodies[1].contains("\"output\":\"shell:"),
            "失败的派发不得回执任务地址：{}",
            bodies[1]
        );
        assert!(response.contexts.iter().any(|context| matches!(context,
            ContextItem::Tool { tool_name, result, .. } if tool_name == "bash" && !result.success
                && result.output.contains("background durable registration denied")
        )));
        assert!(state.shell_tasks.task_snapshots("conv_test").is_empty());
        assert!(!workspace.path().join("should-not-exist.txt").exists());
    }

    #[test]
    fn a_background_shell_returns_at_once_and_task_wait_delivers_its_output() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = serve_json_sequence(
            listener,
            vec![
                json!({
                    "model":"model-test",
                    "status":"completed",
                    "output":[
                        {"type":"function_call","status":"completed","call_id":"bg-shell","name":"bash",
                            "arguments":json!({"command":"printf BG_WAIT_MARKER","run_in_background":true}).to_string()},
                        {"type":"function_call","status":"completed","call_id":"bg-wait","name":"task_wait",
                            "arguments":json!({"timeout_seconds":30}).to_string()}
                    ],
                    "usage":{"input_tokens":1,"output_tokens":1,"total_tokens":2}
                }),
                responses_text_output("bg done"),
            ],
        );
        let workspace = tempfile::tempdir().unwrap();
        let request = loop_request_for(address, workspace.path());
        let state = AppState::default();
        let response = run_model(request, &state, &discard_event, &approve_tool).unwrap();
        let bodies = server.join().unwrap();
        let round2 = &bodies[1];
        assert!(
            round2.contains("shell:1"),
            "派发回执就是任务地址本身，交付也带着它：{round2}"
        );
        assert!(
            round2.contains("BG_WAIT_MARKER"),
            "task_wait 必须交付命令输出：{round2}"
        );
        assert!(
            round2.contains(
                &PromptProfile::builtin_english()
                    .render(PromptKey::TaskShellExitCode, &[("code", "0")],)
            ),
            "交付文本要报真实退出码：{round2}"
        );
        assert!(
            !round2.contains("[a1"),
            "池内部名不得出现在模型可见文本里：{round2}"
        );
        let (result, subagent) = response
            .contexts
            .iter()
            .find_map(|context| match context {
                ContextItem::Tool {
                    tool_name,
                    result,
                    subagent,
                    ..
                } if tool_name == "bash" => Some((result, subagent)),
                _ => None,
            })
            .expect("后台 bash 应留下一条普通工具上下文");
        assert!(result.success);
        assert!(
            subagent.is_none(),
            "后台 shell 的池条目是管道内部件，不回填子代理记录"
        );
        let rows = state.shell_tasks.task_snapshots("conv_test");
        assert_eq!(rows.len(), 1);
        assert_eq!(
            rows[0].outcome,
            Some(crate::shell_tasks::ShellTaskOutcome::Succeeded)
        );
    }

    /// An unwaited background command is folded at the round boundary and forces a
    /// delivery round. Its output is visible in that round's model request.
    #[test]
    fn an_unwaited_background_shell_folds_into_a_delivery_round() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let workspace = tempfile::tempdir().unwrap();
        let marker = workspace.path().join("bg_fold_marker.txt");
        let server = thread::spawn(move || {
            let (mut first, _) = listener.accept().unwrap();
            let _ = read_http_request_with_body(&mut first);
            write_json_response(
                &mut first,
                "200 OK",
                &json!({
                    "model":"model-test","status":"completed",
                    "output":[
                        {"type":"function_call","status":"completed","call_id":"bg-fold","name":"bash",
                            "arguments":json!({
                                "command":"sleep 1.5; printf done > bg_fold_marker.txt",
                                "run_in_background":true
                            }).to_string()}
                    ],
                    "usage":{"input_tokens":1,"output_tokens":1,"total_tokens":2}
                }),
            );
            // Do not allow the response until the command result is persisted,
            // ensuring the normal boundary observes an unclaimed completed result.
            let (mut second, _) = listener.accept().unwrap();
            let second_body = read_http_request_with_body(&mut second);
            let deadline = Instant::now() + Duration::from_secs(15);
            while !marker.exists() {
                assert!(Instant::now() < deadline, "后台命令没有在期限内落盘");
                thread::sleep(Duration::from_millis(20));
            }
            thread::sleep(Duration::from_millis(500));
            write_json_response(&mut second, "200 OK", &responses_text_output("silent"));
            let (mut third, _) = listener.accept().unwrap();
            let third_body = read_http_request_with_body(&mut third);
            write_json_response(&mut third, "200 OK", &responses_text_output("after fold"));
            (second_body, third_body)
        });
        let request = loop_request_for(address, workspace.path());
        let state = AppState::default();
        let response = run_model(request, &state, &discard_event, &approve_tool).unwrap();
        let (second_body, third_body) = server.join().unwrap();
        assert!(
            !second_body.contains(", exit code "),
            "回执轮不得抢跑 fold 通知：{second_body}"
        );
        assert!(
            third_body.contains("[shell:1"),
            "交付轮必须携带 fold 通知：{third_body}"
        );
        assert!(
            third_body.contains(", exit code "),
            "fold 通知必须保留后台命令的结果正文：{third_body}"
        );
        assert!(
            third_body.contains("task-notification"),
            "交付必须以通知信封的形态到达：{third_body}"
        );
        assert!(
            third_body.contains("\"box\""),
            "交付必须走伪造的 box 调用，而不是 user 文本：{third_body}"
        );
        assert!(
            !third_body.contains("SYSTEM NOTIFICATION"),
            "工具结果不会被误认成用户发言，不该再有免责抬头：{third_body}"
        );
        assert!(
            !third_body.contains("system-reminder"),
            "上游不包 reminder，出站字节里也不该有：{third_body}"
        );
        let notification = response
            .contexts
            .iter()
            .find_map(|context| match context {
                ContextItem::Tool {
                    id,
                    tool_name,
                    result,
                    ..
                } if id.starts_with(AGENT_RESULT_CONTEXT_ID_PREFIX) && tool_name == BOX_TOOL => {
                    Some(&result.output)
                }
                _ => None,
            })
            .expect("fold 应作为宿主合成的 box 工具上下文入账");
        assert!(notification.contains("Background command shell:1"));
    }

    /// A user-stopped background command triggers a delivery round and folds, carrying
    /// whatever the command printed before it was killed.
    #[test]
    fn a_stopped_background_shell_folds_and_retriggers_a_round() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let state = AppState::default();
        let stopper_registry = state.shell_tasks.clone();
        let server_registry = state.shell_tasks.clone();
        let server = thread::spawn(move || {
            let (mut first, _) = listener.accept().unwrap();
            let _ = read_http_request_with_body(&mut first);
            write_json_response(
                &mut first,
                "200 OK",
                &json!({
                    "model":"model-test","status":"completed",
                    "output":[
                        {"type":"function_call","status":"completed","call_id":"bg-stop","name":"bash",
                            "arguments":json!({"command":"echo stop-marker-7; sleep 30","run_in_background":true}).to_string()}
                    ],
                    "usage":{"input_tokens":1,"output_tokens":1,"total_tokens":2}
                }),
            );
            // Wait for the stopped envelope before allowing the terminal response.
            let (mut second, _) = listener.accept().unwrap();
            let second_body = read_http_request_with_body(&mut second);
            let deadline = Instant::now() + Duration::from_secs(15);
            loop {
                let rows = server_registry.task_snapshots("conv_test");
                if rows
                    .iter()
                    .any(|row| row.outcome == Some(crate::shell_tasks::ShellTaskOutcome::Stopped))
                {
                    break;
                }
                assert!(Instant::now() < deadline, "后台命令没有被停止");
                thread::sleep(Duration::from_millis(20));
            }
            thread::sleep(Duration::from_millis(500));
            write_json_response(&mut second, "200 OK", &responses_text_output("quiet"));
            // The stopped result is deliverable, so the loop opens one more round to
            // fold it. Without this third response the run would block on the socket.
            let (mut third, _) = listener.accept().unwrap();
            let _ = read_http_request_with_body(&mut third);
            write_json_response(&mut third, "200 OK", &responses_text_output("acknowledged"));
            second_body
        });
        let stopper = thread::spawn(move || {
            let deadline = Instant::now() + Duration::from_secs(15);
            loop {
                let rows = stopper_registry.task_snapshots("conv_test");
                if let Some(row) = rows.iter().find(|row| row.outcome.is_none()) {
                    assert!(stopper_registry.request_stop("conv_test", &row.shell_task_id));
                    return;
                }
                assert!(Instant::now() < deadline, "后台命令行没有出现");
                thread::sleep(Duration::from_millis(20));
            }
        });
        let workspace = tempfile::tempdir().unwrap();
        let request = loop_request_for(address, workspace.path());
        let response = run_model(request, &state, &discard_event, &approve_tool).unwrap();
        server.join().unwrap();
        stopper.join().unwrap();
        let notification = response
            .contexts
            .iter()
            .find_map(|context| match context {
                ContextItem::Tool { id, result, .. }
                    if id.starts_with(AGENT_RESULT_CONTEXT_ID_PREFIX) =>
                {
                    Some(result.output.clone())
                }
                _ => None,
            })
            .expect("被停止的后台命令必须 fold 成宿主合成的 task_wait 卡");
        assert!(
            notification.contains("was stopped by the user"),
            "{notification}"
        );
        assert!(
            notification.contains("shell:1"),
            "卡上必须是 shell:<id> 地址而不是池名：{notification}"
        );
        assert!(
            notification.contains("stop-marker-7"),
            "被杀死前真正打印出来的输出必须交给模型，而不是只留一句「已被用户停止」：{notification}"
        );
        let rows = state.shell_tasks.task_snapshots("conv_test");
        assert_eq!(rows.len(), 1);
        assert_eq!(
            rows[0].outcome,
            Some(crate::shell_tasks::ShellTaskOutcome::Stopped)
        );
    }

    /// A `shell:<id>` address resolves to its background-pool entry. `task_list`
    /// hides internal pool items and exposes shell rows instead.
    #[test]
    fn a_background_shell_pool_entry_carries_its_shell_address() {
        let state = AppState::default();
        let pool = AgentPool::new();
        let parent = run_request(ProviderFamily::OpenaiResponses);
        let _shared = pool
            .register(
                "a1".into(),
                "shell:9".into(),
                "printf hi".into(),
                agent_child_template(&parent),
                SubagentRunKind::ShellCommand,
                &state,
                Vec::new(),
                Vec::new(),
                AgentLiveStatus::Running,
                "call-bg".into(),
                None,
            )
            .unwrap();
        let input: JsonObject = serde_json::from_value(json!({"tasks": ["shell:9"]})).unwrap();
        let spec = orchestration::parse_task_wait(&input).unwrap();
        let (watched, others) = resolve_wait_targets(&pool, &parent, &state, &spec).unwrap();
        assert_eq!(watched.len(), 1);
        assert_eq!(watched[0].name, "a1");
        assert!(others.is_empty(), "池条目不落快照观察");
        let listing = run_task_list(
            &pool,
            &parent,
            ToolCall {
                id: "list".into(),
                name: "task_list".into(),
                input: JsonObject::new(),
            },
            &state,
        );
        assert!(
            !listing.result.output.contains("a1"),
            "池内部名不得出现在 task_list：{}",
            listing.result.output
        );
    }

    /// A `workflow:<runId>` address resolves to the pool entry, while `task_list`
    /// groups it as a workflow and never exposes the driver's internal pool name.
    #[test]
    fn a_workflow_pool_entry_carries_its_workflow_address() {
        let state = AppState::default();
        let pool = AgentPool::new();
        let parent = run_request(ProviderFamily::OpenaiResponses);
        let _shared = pool
            .register(
                "a1".into(),
                "workflow:runxyz".into(),
                "审计仓库".into(),
                agent_child_template(&parent),
                SubagentRunKind::WorkflowStep,
                &state,
                Vec::new(),
                Vec::new(),
                AgentLiveStatus::Running,
                "call-wf".into(),
                None,
            )
            .unwrap();
        let input: JsonObject =
            serde_json::from_value(json!({"tasks": ["workflow:runxyz"]})).unwrap();
        let spec = orchestration::parse_task_wait(&input).unwrap();
        let (watched, others) = resolve_wait_targets(&pool, &parent, &state, &spec).unwrap();
        assert_eq!(watched.len(), 1);
        assert_eq!(watched[0].name, "a1");
        assert!(others.is_empty(), "池条目不落快照观察");
        let missing: JsonObject =
            serde_json::from_value(json!({"tasks": ["workflow:runmissing"]})).unwrap();
        let error = resolve_wait_targets(
            &pool,
            &parent,
            &state,
            &orchestration::parse_task_wait(&missing).unwrap(),
        )
        .unwrap_err();
        assert!(error.contains("workflow:runmissing"), "{error}");

        let listing = run_task_list(
            &pool,
            &parent,
            ToolCall {
                id: "list".into(),
                name: "task_list".into(),
                input: JsonObject::new(),
            },
            &state,
        );
        let output = &listing.result.output;
        assert!(
            output.contains(PromptKey::TaskGroupWorkflows.builtin_en()),
            "{output}"
        );
        assert!(
            output.contains("workflow:runxyz"),
            "工作流行按任务地址列出：{output}"
        );
        assert!(
            !output.contains("a1"),
            "池内部名不得出现在 task_list：{output}"
        );
    }

    /// Parallel workflow steps dispatch concurrently, return a correctly shaped
    /// synthetic record, and do not enter resumable history.
    #[test]
    fn a_parallel_workflow_fans_its_steps_out_concurrently_and_synthesizes_the_record() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let script = "export const meta = { name: \"fan\", description: \"六步并发扇出\" }\nconst results = await parallel([1, 2, 3, 4, 5, 6].map(i => () => agent(`step-${i}`)))\nreturn { results }";
        let server = thread::spawn(move || {
            let (mut parent, _) = listener.accept().unwrap();
            let _ = read_http_request_with_body(&mut parent);
            write_json_response(
                &mut parent,
                "200 OK",
                &json!({
                    "model":"model-test",
                    "status":"completed",
                    "output":[
                        {"type":"function_call","status":"completed","call_id":"wf-call","name":"workflow",
                            "arguments":json!({"script": script, "name": "fan"}).to_string()},
                        // The wait must allow the driver to finish before the next round.
                        //
                        // `task_wait` addresses the name provided in `workflow.name`.
                        {"type":"function_call","status":"completed","call_id":"wf-wait","name":"task_wait",
                            "arguments":json!({"tasks": ["fan"], "timeout_seconds": 30}).to_string()}
                    ],
                    "usage":{"input_tokens":1,"output_tokens":1,"total_tokens":2}
                }),
            );
            drop(parent);

            // Hold the first step until the second connects to prove concurrent scheduling.
            let (mut first, _) = listener.accept().unwrap();
            let first_body = read_http_request_with_body(&mut first);
            listener.set_nonblocking(true).unwrap();
            let deadline = Instant::now() + Duration::from_secs(5);
            let mut second = loop {
                match listener.accept() {
                    Ok((stream, _)) => break stream,
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                        assert!(
                            Instant::now() < deadline,
                            "second step never ran concurrently"
                        );
                        thread::sleep(Duration::from_millis(5));
                    }
                    Err(error) => panic!("accepting second step failed: {error}"),
                }
            };
            second.set_nonblocking(false).unwrap();
            let second_body = read_http_request_with_body(&mut second);
            listener.set_nonblocking(false).unwrap();
            write_json_response(&mut first, "200 OK", &responses_text_output("done"));
            write_json_response(&mut second, "200 OK", &responses_text_output("done"));
            drop(first);
            drop(second);
            let mut step_bodies = vec![first_body, second_body];
            for _ in 0..4 {
                let (mut step, _) = listener.accept().unwrap();
                step_bodies.push(read_http_request_with_body(&mut step));
                write_json_response(&mut step, "200 OK", &responses_text_output("done"));
                drop(step);
            }

            let (mut parent_final, _) = listener.accept().unwrap();
            let final_body = read_http_request_with_body(&mut parent_final);
            write_json_response(
                &mut parent_final,
                "200 OK",
                &responses_text_output("workflow finished"),
            );
            (step_bodies, final_body)
        });

        let workspace = tempfile::tempdir().unwrap();
        let response = run_model(
            loop_request_for(address, workspace.path()),
            &AppState::default(),
            &discard_event,
            &approve_tool,
        )
        .unwrap();
        let (step_bodies, final_body) = server.join().unwrap();

        assert_eq!(step_bodies.len(), 6);
        for index in 1..=6 {
            assert!(
                step_bodies
                    .iter()
                    .any(|body| body.contains(&format!("step-{index}"))),
                "step-{index} 未到达模型后端"
            );
        }
        assert!(final_body.contains("\\\"results\\\"") || final_body.contains("results"));

        let record = response
            .contexts
            .iter()
            .find_map(|context| match context {
                ContextItem::Tool {
                    tool_name,
                    subagent,
                    ..
                } if tool_name == "workflow" => subagent.as_ref(),
                _ => None,
            })
            .expect("workflow 工具上下文携带合成记录");
        assert_eq!(record.kind, SubagentRunKind::WorkflowStep);
        assert_eq!(record.name.as_deref(), Some("fan"), "{:?}", record.name);
        assert_eq!(record.status, SubagentRunStatus::Completed);
        assert_eq!(record.contexts.len(), 6);
        for (index, context) in record.contexts.iter().enumerate() {
            let ContextItem::Tool {
                id,
                tool_name,
                input,
                subagent,
                ..
            } = context
            else {
                panic!("步骤上下文必须是 Tool 条目");
            };
            assert_eq!(tool_name, "workflow_step");
            assert_eq!(id, &format!("wf-call-ws{}", index + 1));
            // Step bodies are externalized; input metadata contains terminal state and retrieval coordinates.
            assert!(subagent.is_none(), "外移后的步骤不该再内嵌子记录");
            assert_eq!(
                input.get("status").and_then(Value::as_str),
                Some("completed")
            );
            assert_eq!(
                input.get("stepIndex").and_then(Value::as_u64),
                Some(index as u64)
            );
            assert!(input.get("runId").is_some(), "取回正文需要运行 id 坐标");
        }
        // WorkflowStep records cannot be resumed; `resume_run_id` is the only recovery path.
        let historical = historical_agent_records(&response.contexts);
        assert_eq!(historical.len(), 1, "{historical:?}");
        assert_eq!(
            historical.values().next().unwrap().kind,
            SubagentRunKind::WorkflowStep
        );
    }

    /// The driver occupies one outer-pool slot while all 12 workflow steps (more
    /// than the outer `MAX_LIVE_AGENTS` of 8) run in its private pool. After
    /// completion exactly one outer `WorkflowStep` driver record remains and no
    /// per-step records; once the driver is Idle its Running capacity is
    /// released, so a subsequent `agent_spawn` must succeed. The runner is
    /// invoked directly because going through HTTP would race on the unordered
    /// `listener.accept()`.
    #[test]
    fn a_workflow_leaves_the_outer_agent_budget_untouched() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let script = "export const meta = { name: \"bulk\", description: \"十二步扇出\" }\nconst results = await parallel(Array.from({ length: 12 }, (unused, i) => () => agent(`bulk-${i + 1}`)))\nreturn { results }";
        let server = thread::spawn(move || {
            let mut bodies = Vec::new();
            for _ in 0..12 {
                let (mut step, _) = listener.accept().unwrap();
                bodies.push(read_http_request_with_body(&mut step));
                write_json_response(&mut step, "200 OK", &responses_text_output("bulk done"));
                drop(step);
            }
            bodies
        });

        let workspace = tempfile::tempdir().unwrap();
        let request = loop_request_for(address, workspace.path());
        let call = ToolCall {
            id: "wf-call".into(),
            name: "workflow".into(),
            input: json!({"script": script, "name": "bulk-run"})
                .as_object()
                .unwrap()
                .clone(),
        };
        let state = AppState::default();
        let pool = AgentPool::new();
        let shadow = test_kernel_shadow();
        let execution = workflow::run_workflow_tool(
            &pool,
            &shadow,
            &request,
            call,
            &state,
            &discard_event,
            &approve_tool,
            false,
            1,
        )
        .unwrap();
        let bodies = server.join().unwrap();
        // The separated worker requires an explicit wait for pool quiescence.
        pool.wait_settled_for_tests(std::time::Duration::from_secs(120));
        assert!(execution.result.success, "{}", execution.result.output);
        for index in 1..=12 {
            assert!(
                bodies
                    .iter()
                    .any(|body| body.contains(&format!("bulk-{index}"))),
                "bulk-{index} 未到达模型后端"
            );
        }

        let live = pool.all();
        assert_eq!(
            live.len(),
            1,
            "外层池只该看到驱动器：{:?}",
            live.iter().map(|agent| &agent.name).collect::<Vec<_>>()
        );
        let driver = &live[0];
        assert_eq!(driver.kind, SubagentRunKind::WorkflowStep);
        let record = driver.record();
        assert_eq!(record.status, SubagentRunStatus::Completed);
        assert_eq!(record.contexts.len(), 12);
        assert!(record.contexts.iter().all(|context| matches!(
            context,
            ContextItem::Tool { input, subagent: None, .. }
                if input.get("status").and_then(Value::as_str) == Some("completed")
        )));

        assert_eq!(driver.status(), AgentLiveStatus::Idle);
        let spawn_execution = run_agent_spawn(
            &pool,
            &shadow,
            &request,
            ToolCall {
                id: "spawn-after".into(),
                name: "agent_spawn".into(),
                input: serde_json::from_value(json!({"prompt": "After task", "name": "after"}))
                    .unwrap(),
            },
            &state,
            &discard_event,
            &approve_tool,
            false,
            1,
        )
        .unwrap();
        assert!(
            spawn_execution.result.success,
            "驱动器已终态之后，agent_spawn 不该被外层预算拒绝：{}",
            spawn_execution.result.output
        );
        assert!(pool.find("after").is_some());
    }

    /// Child templates do not contain `workflow`; an attempted call must be reported
    /// as an unknown tool, with the runtime depth guard as defense in depth.
    #[test]
    fn a_child_can_neither_hold_nor_invoke_the_workflow_tool() {
        let workspace = tempfile::tempdir().unwrap();
        let parent = loop_request_for("127.0.0.1:9".parse().unwrap(), workspace.path());
        assert!(
            parent.tools.iter().any(|tool| tool.name == "workflow"),
            "父代理必须持有 workflow，否则这个测试什么都没证明"
        );
        let template = agent_child_template(&parent);
        assert!(
            !template.enabled_tools.iter().any(|name| name == "workflow"),
            "子代理模板不得启用 workflow"
        );
        assert!(
            !template.tools.iter().any(|tool| tool.name == "workflow"),
            "子代理模板不得携带 workflow 描述符"
        );
        assert_eq!(
            automatic_tool_rejection_reason(
                &template,
                &ToolCall {
                    id: "wf-unknown".into(),
                    name: "workflow".into(),
                    input: serde_json::Map::new(),
                }
            ),
            Some("The model requested an unknown tool".to_owned())
        );

        let mut nested = parent;
        nested.subagent_depth = 1;
        let call = ToolCall {
            id: "wf-nested".into(),
            name: "workflow".into(),
            input: json!({"script": "export const meta = { name: \"x\", description: \"d\" }\nreturn await agent(\"s\")", "name": "nested-run"})
                .as_object()
                .unwrap()
                .clone(),
        };
        let state = AppState::default();
        let pool = AgentPool::new();
        let shadow = test_kernel_shadow();
        let execution = workflow::run_workflow_tool(
            &pool,
            &shadow,
            &nested,
            call,
            &state,
            &discard_event,
            &approve_tool,
            false,
            1,
        )
        .unwrap();
        assert!(!execution.result.success, "{}", execution.result.output);
        assert!(execution
            .result
            .output
            .contains("Subagents cannot start workflow; return orchestration to the main agent"));
    }

    /// Child agents inherit web tools; `workflow` remains unavailable at child depth.
    ///
    /// Approval is per invocation, and moving research to a parent does not reduce
    /// search work. Child agents must be able to perform their assigned research.
    ///
    /// Inheritance runs through the conversation's web-access switch and resolved
    /// backend, not through names in the parent's list: a child works inside the
    /// same boundary, so it reaches the network exactly when the conversation may.
    #[test]
    fn a_child_inherits_the_web_tools_but_never_the_orchestration_floor() {
        let workspace = tempfile::tempdir().unwrap();
        let mut parent = loop_request_for("127.0.0.1:9".parse().unwrap(), workspace.path());
        parent.web_search_enabled = true;
        parent.web_search.backend = Some(crate::model::SearchBackend::Native);
        parent.web_search.fetch = Some(crate::model::SearchFetchBackend::Native);
        crate::web_search::apply_web_tools(
            &mut parent.enabled_tools,
            parent.web_search_enabled,
            &parent.web_search,
        );
        let template = agent_child_template(&parent);
        for name in [WEB_SEARCH_TOOL, WEB_FETCH_TOOL] {
            assert!(
                template.enabled_tools.iter().any(|entry| entry == name),
                "子代理模板应当继承 {name}"
            );
        }
        // Removing web tools from the allowlist must not disable the remaining checks.
        for name in ["agent_spawn", "workflow", "ask_user"] {
            assert!(
                !template.enabled_tools.iter().any(|entry| entry == name),
                "{name} 仍然不得被子代理继承"
            );
        }
        // Search tools are not producers, so they must not derive task-runtime tools.
        let mut web_only = parent.clone();
        web_only.enabled_tools = vec![WEB_SEARCH_TOOL.to_string(), WEB_FETCH_TOOL.to_string()];
        let web_only_template = agent_child_template(&web_only);
        for name in ["task_wait", "task_list"] {
            assert!(
                !web_only_template
                    .enabled_tools
                    .iter()
                    .any(|entry| entry == name),
                "只持有联网工具的子代理不产生任务，不该拿到 {name}"
            );
        }

        // Depth-one calls follow the same classification and approval path as top-level calls.
        let mut nested = parent;
        nested.subagent_depth = 1;
        nested.subagent_name = Some("researcher".into());
        // Use complete input so validation cannot mask a missing depth guard.
        let fetch_call = ToolCall {
            id: "wf-nested".into(),
            name: WEB_FETCH_TOOL.into(),
            input: json!({ "urls": ["https://example.com/a"] })
                .as_object()
                .unwrap()
                .clone(),
        };
        let dispatch = dispatch_async_tool(
            &nested,
            fetch_call,
            &approve_tool,
            false,
            JsonObject::new(),
            1,
        )
        .unwrap();
        let output = match dispatch {
            AsyncToolDispatch::Settled(execution) => execution.result.output,
            AsyncToolDispatch::Pending(pending) => {
                pending.abandon.store(true, Ordering::Release);
                String::new()
            }
        };
        assert!(!output.contains("子代理不能发起联网请求"), "{output}");
    }

    /// Cancellation belongs to its owner: task rounds use the task flag and top-level
    /// rounds use the request's run flag.
    /// Both cancellation flags travel with the request rather than being looked up by conversation.
    ///
    /// A task flag must take precedence over an unrelated live run flag.
    #[test]
    fn a_round_cancellation_signal_watches_its_owner_only() {
        let state = AppState::default();
        let mut request = run_request(ProviderFamily::OpenaiResponses);

        assert!(!request.round_cancellation().cancelled());

        let (cancellation, _inbox) = state
            .begin_model_run("request-signal", &request.conversation_id)
            .unwrap();
        request.run_cancel = CancelSignal::from_flag(Arc::clone(&cancellation));
        let top_level = request.round_cancellation();
        assert!(!top_level.cancelled());

        // A task round uses only its task flag even when a run flag is present.
        let flag = Arc::new(AtomicBool::new(false));
        request.task_cancel = CancelSignal::from_flag(Arc::clone(&flag));
        let task_round = request.round_cancellation();
        assert!(!task_round.cancelled());

        assert!(state.cancel_model_run("request-signal").unwrap());
        assert!(
            !task_round.cancelled(),
            "无关前台运行的停止不得进入任务回合的信号"
        );
        assert!(top_level.cancelled(), "停止运行必须出现在顶层回合的信号里");

        flag.store(true, Ordering::Release);
        assert!(task_round.cancelled(), "任务级停止必须到达任务回合的同步腿");
    }

    /// Settlement must read `request.round_cancellation()` rather than looking up a
    /// conversation's current run, which can be unrelated to the task round.
    #[test]
    fn a_task_rounds_settlement_ignores_an_unrelated_foreground_runs_cancellation() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = serve_json_sequence(listener, vec![responses_text_output("任务照常完成")]);
        let workspace = tempfile::tempdir().unwrap();
        let mut request = loop_request_for(address, workspace.path());
        let task_flag = Arc::new(AtomicBool::new(false));
        request.task_cancel = CancelSignal::from_flag(Arc::clone(&task_flag));
        request.subagent_depth = 1;

        let state = AppState::default();
        let (unrelated, _) = state
            .begin_model_run("run-unrelated-foreground", &request.conversation_id)
            .unwrap();
        unrelated.store(true, std::sync::atomic::Ordering::Release);

        let response = run_model(request, &state, &discard_event, &approve_tool)
            .expect("任务回合必须以自己的结局收束，而不是借来的取消");
        assert_ne!(
            response.stop_reason.as_deref(),
            Some("cancelled"),
            "无关前台运行的取消不得进入任务回合的结算"
        );
        server.join().unwrap();
    }

    /// A task's own cancellation flag must settle the round successfully with
