    /// Approval is consumed in the runner; a rejection must spawn no steps.
    #[test]
    fn a_refused_approval_prevents_any_workflow_step_from_spawning() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let workspace = tempfile::tempdir().unwrap();
        let request = loop_request_for(address, workspace.path());
        let call = ToolCall {
            id: "wf-refused".into(),
            name: "workflow".into(),
            input: json!({"script": "export const meta = { name: \"refused\", description: \"d\" }\nreturn await agent(\"never-runs\")", "name": "refused-workflow"})
            .as_object()
            .unwrap()
            .clone(),
        };
        let refuse: &DangerousToolApproval<'_> = &|_, _, _| Ok(false);
        let state = AppState::default();
        let pool = AgentPool::new();
        let shadow = test_kernel_shadow();
        let execution = std::thread::scope(|_scope| {
            workflow::run_workflow_tool_with_deadline(
                &pool,
                &shadow,
                &request,
                call,
                &state,
                &discard_event,
                refuse,
                false,
                1,
                4,
                Instant::now() + Duration::from_secs(5),
            )
        })
        .unwrap();
        assert!(!execution.result.success, "{}", execution.result.output);
        assert!(
            execution
                .result
                .output
                .contains("The user declined this workflow run; no steps were created"),
            "{}",
            execution.result.output
        );
        assert!(execution.subagent.is_none(), "拒绝路径不产生合成记录");
        // Approval precedes registration, so a rejected run leaves no pool entry.
        assert!(
            pool.all().is_empty(),
            "拒绝之后外层池不该有任何条目：{:?}",
            pool.all()
                .iter()
                .map(|agent| &agent.name)
                .collect::<Vec<_>>()
        );
        // A rejected approval must not connect any step to the model backend.
        listener.set_nonblocking(true).unwrap();
        thread::sleep(Duration::from_millis(200));
        assert!(
            matches!(listener.accept(), Err(error) if error.kind() == std::io::ErrorKind::WouldBlock),
            "拒绝之后仍有步骤连接了模型后端"
        );
    }

    /// Full access means workflow operations do not request approval.
    #[test]
    fn full_access_runs_a_workflow_without_ever_asking_for_approval() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = thread::spawn(move || {
            let (mut step, _) = listener.accept().unwrap();
            let _ = read_http_request_with_body(&mut step);
            write_json_response(&mut step, "200 OK", &responses_text_output("step done"));
        });

        let workspace = tempfile::tempdir().unwrap();
        let mut request = loop_request_for(address, workspace.path());
        request.security_level = SecurityLevel::FullAccess;
        let call = ToolCall {
            id: "wf-full-access".into(),
            name: "workflow".into(),
            input: json!({"script": "export const meta = { name: \"unattended\", description: \"d\" }\nreturn await agent(\"runs unattended\")", "name": "unattended-workflow"})
            .as_object()
            .unwrap()
            .clone(),
        };
        let asked = AtomicBool::new(false);
        let refuse: &DangerousToolApproval<'_> = &|_, _, _| {
            asked.store(true, Ordering::SeqCst);
            Ok(false)
        };
        let state = AppState::default();
        let pool = AgentPool::new();
        let shadow = test_kernel_shadow();
        let execution = std::thread::scope(|_scope| {
            workflow::run_workflow_tool_with_deadline(
                &pool,
                &shadow,
                &request,
                call,
                &state,
                &discard_event,
                refuse,
                false,
                1,
                4,
                Instant::now() + Duration::from_secs(60),
            )
        })
        .unwrap();

        assert!(
            !asked.load(Ordering::SeqCst),
            "完全访问下 workflow 仍然向用户要了确认"
        );
        assert!(execution.result.success, "{}", execution.result.output);
        server.join().unwrap();
    }

    /// Re-signing a stable private-pool slot in a later workflow run is idempotent;
    /// driver names remain unique within the conversation tree.
    #[test]
    fn two_workflow_runs_in_one_conversation_re_sign_their_step_slots_idempotently() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = thread::spawn(move || {
            for _ in 0..2 {
                let (mut step, _) = listener.accept().unwrap();
                let _ = read_http_request_with_body(&mut step);
                write_json_response(&mut step, "200 OK", &responses_text_output("run done"));
                drop(step);
            }
        });

        let workspace = tempfile::tempdir().unwrap();
        let request = loop_request_for(address, workspace.path());
        let state = AppState::default();
        let pool = AgentPool::new();
        let shadow = test_kernel_shadow();
        for run in 1..=2 {
            let call = ToolCall {
                id: format!("wf-run-{run}"),
                name: "workflow".into(),
                // Driver names persist across the conversation tree, so each run
                // needs a distinct name. Private-pool `ws1` exercises slot idempotence.
                input: json!({
                    "script": format!(
                        "export const meta = {{ name: \"run-{run}\", description: \"d\" }}\nreturn await agent(\"body-{run}\")"
                    ),
                    "name": format!("run-{run}"),
                })
                .as_object()
                .unwrap()
                .clone(),
            };
            // Each call has its own scope, so the driver and step have reached a
            // terminal state before the next run starts.
            let execution = std::thread::scope(|_scope| {
                workflow::run_workflow_tool_with_deadline(
                    &pool,
                    &shadow,
                    &request,
                    call,
                    &state,
                    &discard_event,
                    &approve_tool,
                    false,
                    1,
                    4,
                    Instant::now() + Duration::from_secs(60),
                )
            })
            .unwrap();
            assert!(
                execution.result.success,
                "第 {run} 次运行失败：{}",
                execution.result.output
            );
        }
        server.join().unwrap();
    }

    #[test]
    fn resuming_a_record_whose_execution_mode_was_stripped_or_swapped_is_refused() {
        let directory = tempfile::tempdir().unwrap();
        let state = AppState::default();
        let mut parent = run_request(ProviderFamily::OpenaiResponses);
        parent.app_data_path = directory.path().to_string_lossy().into_owned();

        let ordinary = sign_test_subagent_record(
            &parent,
            &state,
            SubagentRunRecord {
                kind: SubagentRunKind::General,
                name: Some("ordinary-a1".into()),
                label: None,
                inherits_model_memory: false,
                fork_model_binding: None,
                agent_definition: None,
                execution_mode_receipt: String::new(),
                task: "ordinary".into(),
                status: SubagentRunStatus::Completed,
                contexts: Vec::new(),
                updates: Vec::new(),
                structured_output: None,
                output_schema: None,
                usage: ModelUsage::default(),
            },
        );
        verify_subagent_execution_mode(&parent, &state, "ordinary-a1", &ordinary).unwrap();
        let fork_binding = ForkModelBinding {
            provider_id: "provider".into(),
            model_id: "kimi-k3".into(),
            memory_language: ResolvedLanguage::ZhCn,
            memory_tool_names: Vec::new(),
            system_prompt_snapshot: "trusted fork prompt".into(),
            system_prompt_receipt: "receipt".into(),
            memory_snapshot_receipt: None,
            binding_receipt: "binding-receipt".into(),
            receipt_version: 1,
        };
        let mut stripped_fork = sign_test_subagent_record(
            &parent,
            &state,
            SubagentRunRecord {
                kind: SubagentRunKind::General,
                name: Some("fork-a1".into()),
                label: None,
                inherits_model_memory: true,
                fork_model_binding: Some(fork_binding),
                agent_definition: None,
                execution_mode_receipt: String::new(),
                task: "fork".into(),
                status: SubagentRunStatus::Completed,
                contexts: Vec::new(),
                updates: Vec::new(),
                structured_output: None,
                output_schema: None,
                usage: ModelUsage::default(),
            },
        );
        stripped_fork.inherits_model_memory = false;
        stripped_fork.fork_model_binding = None;
        let error = match verify_subagent_execution_mode(&parent, &state, "fork-a1", &stripped_fork)
        {
            Err(error) => error,
            Ok(_) => panic!("a stripped fork execution mode must fail verification"),
        };
        assert!(error.contains("已绑定到另一种执行模式"), "{error}");

        let named_binding = AgentDefinitionBinding {
            source: AgentDefinitionSource::User,
            source_key: String::new(),
            name: "reviewer".into(),
            revision: 1,
            memory_epoch: 1,
            provider_id: "provider".into(),
            model_id: "kimi-k3".into(),
            memory: AgentDefinitionMemory::User,
            scope_key: String::new(),
            configuration_receipt: "configuration-receipt".into(),
            receipt_version: 1,
        };
        let mut stripped_named = sign_test_subagent_record(
            &parent,
            &state,
            SubagentRunRecord {
                kind: SubagentRunKind::General,
                name: Some("named-a1".into()),
                label: None,
                inherits_model_memory: false,
                fork_model_binding: None,
                agent_definition: Some(named_binding),
                execution_mode_receipt: String::new(),
                task: "named".into(),
                status: SubagentRunStatus::Completed,
                contexts: Vec::new(),
                updates: Vec::new(),
                structured_output: None,
                output_schema: None,
                usage: ModelUsage::default(),
            },
        );
        stripped_named.agent_definition = None;
        let error =
            match verify_subagent_execution_mode(&parent, &state, "named-a1", &stripped_named) {
                Err(error) => error,
                Ok(_) => panic!("a stripped named-agent mode must fail verification"),
            };
        assert!(error.contains("已绑定到另一种执行模式"), "{error}");

        let mut conflicting = ordinary.clone();
        conflicting.name = Some("ordinary-a1".into());
        conflicting.inherits_model_memory = true;
        conflicting.fork_model_binding = Some(ForkModelBinding {
            provider_id: "provider".into(),
            model_id: "kimi-k3".into(),
            memory_language: ResolvedLanguage::ZhCn,
            memory_tool_names: Vec::new(),
            system_prompt_snapshot: "trusted fork prompt".into(),
            system_prompt_receipt: "receipt".into(),
            memory_snapshot_receipt: None,
            binding_receipt: "binding-receipt".into(),
            receipt_version: 1,
        });
        let error =
            match verify_subagent_execution_mode(&parent, &state, "ordinary-a1", &conflicting) {
                Err(error) => error,
                Ok(_) => panic!("a record claiming a different mode for a bound name must fail"),
            };
        assert!(error.contains("已绑定到另一种执行模式"), "{error}");

        let mut legacy = ordinary.clone();
        legacy.name = Some("legacy-a1".into());
        legacy.task = "legacy".into();

        for (index, record) in [ordinary, legacy].into_iter().enumerate() {
            parent.contexts.push(ContextItem::Tool {
                id: format!("persisted-agent-{index}"),
                tool_name: "agent_spawn".into(),
                round: Some(1),
                model_turn_id: Some("persisted-agent-turn".into()),
                provider_call_id: None,
                requested_input: None,
                input: JsonObject::new(),
                result: ToolResult {
                    success: true,
                    output: "spawned".into(),
                    images: Vec::new(),
                    diff: None,
                    executed_at: "2026-07-24T00:00:00Z".into(),
                    duration_ms: 1,
                },
                subagent: Some(record),
                notice: None,
                attestation: String::new(),
                created_at: "2026-07-24T00:00:00Z".into(),
            });
        }
        let listed = run_task_list(
            &AgentPool::new(),
            &parent,
            ToolCall {
                id: "list-persisted-agents".into(),
                name: "task_list".into(),
                input: JsonObject::new(),
            },
            &state,
        );
        let valid_line = listed
            .result
            .output
            .lines()
            .find(|line| line.contains("ordinary-a1"))
            .unwrap();
        assert!(
            valid_line.contains(PromptKey::TaskListResultInTimeline.builtin_en()),
            "{valid_line}"
        );
        let legacy_line = listed
            .result
            .output
            .lines()
            .find(|line| line.contains("legacy-a1"))
            .unwrap();
        assert!(
            legacy_line.contains(PromptKey::TaskListResultInTimeline.builtin_en()),
            "{legacy_line}"
        );
        find_or_rehydrate_agent(&AgentPool::new(), &parent, &state, "legacy-a1").unwrap();

        parent.subagent_reserved_names = vec!["branch-a1".into()];
        let agent_pool = AgentPool::new();
        std::thread::scope(|_scope| {
            let execution = run_agent_spawn(
                &agent_pool,
                &test_kernel_shadow(),
                &parent,
                ToolCall {
                    id: "cross-branch-reuse".into(),
                    name: "agent_spawn".into(),
                    input: serde_json::from_value(json!({
                        "prompt": "attempt a different execution mode",
                        "name": "branch-a1",
                        "context": "conversation"
                    }))
                    .unwrap(),
                },
                &state,
                &discard_event,
                &approve_tool,
                false,
                1,
            )
            .unwrap();
            assert!(!execution.result.success, "{}", execution.result.output);
            assert!(
                execution
                    .result
                    .output
                    .contains("permanently reserved throughout this conversation branch tree"),
                "{}",
                execution.result.output
            );
        });
    }

    /// S7 (a), (c) and (e) at the layer that resolves them.
    ///
    /// A role allowlist selects from the trusted catalogue rather than the
    /// caller's enabled set, so it can grant a tool its conversation switched
    /// off. It still cannot reach past `SUBAGENT_DISABLED_TOOL_NAMES`.
    #[test]
    fn a_role_allowlist_selects_from_the_catalogue_but_never_past_the_child_floor() {
        let mut parent = run_request(ProviderFamily::OpenaiResponses);
        parent.tools = catalog::tool_catalog();
        parent.enabled_tools = parent.tools.iter().map(|tool| tool.name.clone()).collect();
        parent.reasoning_effort = ReasoningEffort::High;
        let base = agent_child_template(&parent);
        assert!(!base.enabled_tools.is_empty());
        assert!(
            !base.enabled_tools.iter().any(|name| name == "agent_spawn"),
            "the child template already strips the disabled names"
        );
        assert!(
            base.tools.iter().any(|tool| tool.name == "agent_spawn"),
            "but it still KNOWS them, which is what separates unavailable from unrecognized"
        );

        // Unset inherits, set overrides. Nothing here is defaulted to a value
        // the definition did not ask for.
        let mut inherited = base.clone();
        AgentRunOverrides::default()
            .apply(&mut inherited, AgentRunStart::Fresh)
            .unwrap();
        assert_eq!(inherited.reasoning_effort, ReasoningEffort::High);
        assert_eq!(inherited.enabled_tools, base.enabled_tools);

        let mut overridden = base.clone();
        AgentRunOverrides {
            effort: Some(ReasoningEffort::Low),
            tools: None,
            disallowed_tools: Vec::new(),
        }
        .apply(&mut overridden, AgentRunStart::Fresh)
        .unwrap();
        assert_eq!(overridden.reasoning_effort, ReasoningEffort::Low);

        // (a) An allowlist naming a child-disabled tool still cannot re-add it:
        // that floor is re-applied to the catalogue side.
        let survivor = base
            .enabled_tools
            .iter()
            .find(|name| !host_derived_child_tool(name))
            .cloned()
            .unwrap();
        let mut allowlisted = base.clone();
        AgentRunOverrides {
            tools: Some(vec![survivor.clone(), "agent_spawn".into()]),
            ..AgentRunOverrides::default()
        }
        .apply(&mut allowlisted, AgentRunStart::Fresh)
        .unwrap();
        assert!(!allowlisted.enabled_tools.iter().any(|n| n == "agent_spawn"));
        assert!(allowlisted.enabled_tools.contains(&survivor));
        // Host-derived names ride along: an allowlist that never mentions
        // `subagent_update` is not asking to have the child's only progress
        // channel taken away.
        assert!(
            allowlisted
                .enabled_tools
                .iter()
                .any(|name| name == SUBAGENT_UPDATE_TOOL),
            "{:?}",
            allowlisted.enabled_tools
        );
        assert!(
            allowlisted
                .enabled_tools
                .iter()
                .all(|name| name == &survivor || host_derived_child_tool(name)),
            "{:?}",
            allowlisted.enabled_tools
        );

        // (a') A catalogue tool the CALLER disabled is granted by a role that
        // names it.
        let mut narrow_parent = parent.clone();
        narrow_parent.enabled_tools = vec!["read".into()];
        let narrow_base = agent_child_template(&narrow_parent);
        assert!(!narrow_base.enabled_tools.iter().any(|n| n == "grep"));
        let mut widened = narrow_base.clone();
        AgentRunOverrides {
            tools: Some(vec!["read".into(), "grep".into()]),
            ..AgentRunOverrides::default()
        }
        .apply(&mut widened, AgentRunStart::Fresh)
        .unwrap();
        assert!(
            widened.enabled_tools.iter().any(|name| name == "grep"),
            "{:?}",
            widened.enabled_tools
        );

        // (a'') …but NOT a web tool. Those follow the conversation's web-access
        // switch, so naming one in a role's allowlist must not put a conversation
        // the user left offline onto the network. A role that wants a child kept
        // off the network says so in `disallowed_tools` instead, and what a role
        // can still change is which backend runs the search.
        let mut web_widened = narrow_base.clone();
        AgentRunOverrides {
            tools: Some(vec!["read".into(), "web_fetch".into(), "web_search".into()]),
            ..AgentRunOverrides::default()
        }
        .apply(&mut web_widened, AgentRunStart::Fresh)
        .unwrap();
        assert!(
            !web_widened
                .enabled_tools
                .iter()
                .any(|name| crate::web_search::is_web_tool_name(name)),
            "{:?}",
            web_widened.enabled_tools
        );

        // (c) A wildcard resolves to the whole set and skips the refusal.
        let mut wildcard = base.clone();
        AgentRunOverrides {
            tools: Some(vec![AGENT_TOOL_WILDCARD.into(), "nonexistent_tool".into()]),
            ..AgentRunOverrides::default()
        }
        .apply(&mut wildcard, AgentRunStart::Fresh)
        .unwrap();
        assert_eq!(wildcard.enabled_tools, base.enabled_tools);

        // The deny list runs after the allowlist and subtracts from it.
        let mut denied = base.clone();
        AgentRunOverrides {
            disallowed_tools: vec![survivor.clone()],
            ..AgentRunOverrides::default()
        }
        .apply(&mut denied, AgentRunStart::Fresh)
        .unwrap();
        assert!(!denied.enabled_tools.contains(&survivor));
        assert_eq!(denied.enabled_tools.len(), base.enabled_tools.len() - 1);
    }

    /// Task-runtime tools derive from task producers, not from the allowlist itself.
    /// `task_wait` is a `host_derived_child_tool`, so an allowlist cannot remove it
    /// directly: derivation must be recomputed after producer filtering
    /// (`apply_task_runtime_tools`). Otherwise removing `bash` would leave an
    /// unredeemable wait tool, and adding a producer would leave receipts the role
    /// cannot collect. `web_search` is not a producer: its results return at the
    /// call site rather than through the task face.
    #[test]
    fn the_task_runtime_pair_follows_the_producer_the_allowlist_resolved_to() {
        let mut parent = run_request(ProviderFamily::OpenaiResponses);
        parent.tools = catalog::tool_catalog();

        parent.enabled_tools = vec!["read".into(), "bash".into()];
        let mut narrowed = agent_child_template(&parent);
        assert!(
            narrowed
                .enabled_tools
                .iter()
                .any(|name| name == "task_wait"),
            "前提自证：父持有 producer 时子模板应当已经派生出 task_wait"
        );
        AgentRunOverrides {
            tools: Some(vec!["read".into()]),
            ..AgentRunOverrides::default()
        }
        .apply(&mut narrowed, AgentRunStart::Fresh)
        .unwrap();
        for name in ["task_wait", "task_list"] {
            assert!(
                !narrowed.enabled_tools.iter().any(|entry| entry == name),
                "{name} 应随最后一个 producer 一起消失：{:?}",
                narrowed.enabled_tools
            );
        }

        parent.enabled_tools = vec!["read".into()];
        let mut widened = agent_child_template(&parent);
        assert!(
            !widened.enabled_tools.iter().any(|name| name == "task_wait"),
            "前提自证：父没有 producer 时子模板不该有 task_wait"
        );
        AgentRunOverrides {
            tools: Some(vec!["read".into(), "bash".into()]),
            ..AgentRunOverrides::default()
        }
        .apply(&mut widened, AgentRunStart::Fresh)
        .unwrap();
        assert!(widened.enabled_tools.iter().any(|name| name == "bash"));
        for name in ["task_wait", "task_list"] {
            assert!(
                widened.enabled_tools.iter().any(|entry| entry == name),
                "{name} 必须随新选进的 producer 一起派生：{:?}",
                widened.enabled_tools
            );
        }

        let mut only_runtime = agent_child_template(&parent);
        let error = AgentRunOverrides {
            tools: Some(vec!["task_wait".into(), "task_list".into()]),
            ..AgentRunOverrides::default()
        }
        .apply(&mut only_runtime, AgentRunStart::Fresh)
        .unwrap_err();
        assert!(error.contains("Unavailable to subagents:"), "{error}");
    }

    /// A role's explicit search backend is resolved from trusted assets; `None`
    /// follows the conversation's already-resolved backend without changing other snapshots.
    #[test]
    fn a_role_resolves_its_own_search_backend_from_trusted_assets() {
        use crate::model::{
            SearchBackend, SearchProviderConfig, SearchProviderKind, SearchProviderSelection,
            WebSearchAssets,
        };

        let (_directory, state, mut parent, definition) =
            named_agent_fixture(AgentDefinitionMemory::None);
        parent.web_search.backend = Some(SearchBackend::Provider(
            crate::model::ResolvedSearchProvider {
                kind: SearchProviderKind::Exa,
                api_host: "https://api.exa.ai".into(),
                engines: Vec::new(),
                basic_auth_username: String::new(),
            },
        ));
        parent.web_search.max_searches_per_call = 7;
        parent.web_search.execution.max_results = 33;
        // The caller's own filtering, for the two role answers below to be read
        // against: a role that names a mode replaces it whole, and one that
        // names none keeps it.
        parent.web_search.execution.domain_filter = crate::model::SearchDomainFilterMode::Exclude;
        parent.web_search.execution.exclude_domains = vec!["parent.invalid".into()];
        parent.web_search.fetch = Some(crate::model::SearchFetchBackend::Provider(
            crate::model::ResolvedSearchProvider {
                kind: SearchProviderKind::Jina,
                api_host: "https://r.jina.ai".into(),
                engines: Vec::new(),
                basic_auth_username: String::new(),
            },
        ));
        let document = current_agent_document(&parent, &state).unwrap();

        let assets_with = |enabled: bool| WebSearchAssets {
            providers: vec![SearchProviderConfig {
                enabled,
                ..SearchProviderConfig::new(SearchProviderKind::Tavily)
            }],
            ..WebSearchAssets::default()
        };

        let configure = |search_provider: Option<SearchProviderSelection>,
                         assets: &WebSearchAssets| {
            let mut role = definition.clone();
            role.search_provider = search_provider;
            let (binding, provider, model) =
                initial_agent_definition_binding(&parent, &document, &role).unwrap();
            let mut child = agent_child_template(&parent);
            configure_named_agent_template(
                &parent,
                &mut child,
                &role,
                binding,
                provider,
                model,
                assets,
                AgentRunStart::Fresh,
            )
            .unwrap();
            child.web_search
        };

        let inherited = configure(None, &assets_with(true));
        assert!(matches!(
            inherited.backend,
            Some(SearchBackend::Provider(ref resolved)) if resolved.kind == SearchProviderKind::Exa
        ));

        let explicit = configure(
            Some(SearchProviderSelection::Explicit {
                provider_kind: SearchProviderKind::Tavily,
            }),
            &assets_with(true),
        );
        assert!(matches!(
            explicit.backend,
            Some(SearchBackend::Provider(ref resolved))
                if resolved.kind == SearchProviderKind::Tavily
        ));
        assert_eq!(explicit.max_searches_per_call, 7);
        // The role carries its own result shaping, so the parent's number does
        // not reach the child: 0 already means "no cap" on these two, leaving
        // no value over to spell "follow the conversation" with.
        assert_eq!(
            explicit.execution.max_results,
            crate::model::DEFAULT_SEARCH_MAX_RESULTS
        );
        assert!(
            matches!(
                explicit.fetch,
                Some(crate::model::SearchFetchBackend::Provider(ref resolved))
                    if resolved.kind == SearchProviderKind::Jina
            ),
            "只改搜索腿的角色，抓取腿留在调用方对话选的那一家"
        );

        // The other leg answers for itself, and answers independently: a role
        // may redirect fetching while still searching the way its caller does.
        let fetch_only = {
            let mut role = definition.clone();
            role.fetch_provider = Some(crate::model::FetchProviderSelection::Disabled);
            let (binding, provider, model) =
                initial_agent_definition_binding(&parent, &document, &role).unwrap();
            let mut child = agent_child_template(&parent);
            configure_named_agent_template(
                &parent,
                &mut child,
                &role,
                binding,
                provider,
                model,
                &assets_with(true),
                AgentRunStart::Fresh,
            )
            .unwrap();
            child.web_search
        };
        assert!(fetch_only.fetch.is_none(), "{:?}", fetch_only.fetch);
        assert!(
            matches!(
                fetch_only.backend,
                Some(SearchBackend::Provider(ref resolved))
                    if resolved.kind == SearchProviderKind::Exa
            ),
            "只改抓取腿的角色，搜索腿留在调用方对话解析出来的后端"
        );

        // Domain filtering is applied whole or not at all: naming a mode takes
        // over the two lists as well, and naming none keeps the caller's.
        let filtered = {
            let mut role = definition.clone();
            role.domain_filter = Some(crate::model::SearchDomainFilterMode::Include);
            role.include_domains = vec!["role.invalid".into()];
            let (binding, provider, model) =
                initial_agent_definition_binding(&parent, &document, &role).unwrap();
            let mut child = agent_child_template(&parent);
            configure_named_agent_template(
                &parent,
                &mut child,
                &role,
                binding,
                provider,
                model,
                &assets_with(true),
                AgentRunStart::Fresh,
            )
            .unwrap();
            child.web_search.execution
        };
        assert_eq!(
            filtered.domain_filter,
            crate::model::SearchDomainFilterMode::Include
        );
        assert_eq!(filtered.include_domains, vec!["role.invalid".to_string()]);
        assert!(
            filtered.exclude_domains.is_empty(),
            "角色自己选了模式，就不再叠加调用方的名单：{:?}",
            filtered.exclude_domains
        );
        let unfiltered = configure(None, &assets_with(true));
        assert_eq!(
            unfiltered.execution.domain_filter,
            crate::model::SearchDomainFilterMode::Exclude
        );
        assert_eq!(
            unfiltered.execution.exclude_domains,
            vec!["parent.invalid".to_string()]
        );

        // A role that shapes its results differently applies that shaping
        // whether or not it also redirected the backend.
        let mut shaping_role = definition.clone();
        shaping_role.max_results = 0;
        shaping_role.compression_cutoff = 9_000;
        let (binding, provider, model) =
            initial_agent_definition_binding(&parent, &document, &shaping_role).unwrap();
        let mut shaped_child = agent_child_template(&parent);
        configure_named_agent_template(
            &parent,
            &mut shaped_child,
            &shaping_role,
            binding,
            provider,
            model,
            &assets_with(true),
            AgentRunStart::Fresh,
        )
        .unwrap();
        assert_eq!(shaped_child.web_search.execution.max_results, 0);
        assert_eq!(shaped_child.web_search.execution.compression_cutoff, 9_000);

        // An unavailable explicit backend stays absent rather than falling back to the parent.
        let disabled = configure(
            Some(SearchProviderSelection::Explicit {
                provider_kind: SearchProviderKind::Tavily,
            }),
            &assets_with(false),
        );
        assert!(disabled.backend.is_none(), "{:?}", disabled.backend);

        // `Native` uses the role's own model and ignores asset-level configuration.
        let native = configure(Some(SearchProviderSelection::Native), &assets_with(false));
        assert!(matches!(native.backend, Some(SearchBackend::Native)));
    }

    /// S7 (b) and (c): the five-part guard, one part at a time. An unconditional
    /// zero-tool refusal would reject spawns that are legitimate, which is why
    /// each of these cases is ALLOWED rather than merely untested.
    #[test]
    fn the_zero_tool_refusal_fires_only_under_all_five_guards() {
        let mut parent = run_request(ProviderFamily::OpenaiResponses);
        parent.tools = catalog::tool_catalog();
        parent.enabled_tools = parent.tools.iter().map(|tool| tool.name.clone()).collect();
        let base = agent_child_template(&parent);

        // Fires: fresh spawn, resolver ran, no wildcard, non-empty base, and a
        // diagnostic that separates the two reasons.
        let mut refused = base.clone();
        let error = AgentRunOverrides {
            tools: Some(vec!["nonexistent_tool".into(), "agent_spawn".into()]),
            ..AgentRunOverrides::default()
        }
        .apply(&mut refused, AgentRunStart::Fresh)
        .unwrap_err();
        assert!(error.contains("Unrecognized: nonexistent_tool"), "{error}");
        assert!(
            error.contains("Unavailable to subagents: agent_spawn"),
            "{error}"
        );

        // (e) The same definition on a RESUME is allowed: the agent's record is
        // already persisted, so failing closed protects nothing and would only
        // make an existing agent uncontinuable after a definition edit.
        let mut resumed = base.clone();
        AgentRunOverrides {
            tools: Some(vec!["nonexistent_tool".into()]),
            ..AgentRunOverrides::default()
        }
        .apply(&mut resumed, AgentRunStart::Resume)
        .unwrap();
        assert!(
            resumed
                .enabled_tools
                .iter()
                .all(|name| host_derived_child_tool(name)),
            "{:?}",
            resumed.enabled_tools
        );

        // (a) An explicit empty allowlist produces no diagnostic, so it is a
        // deliberate "no tools" configuration rather than a typo — allowed, or
        // it would be unexpressible. Host-derived names are not what it is
        // switching off: no picker offers them and the conversation's own
        // switches already decide them.
        let mut emptied = base.clone();
        AgentRunOverrides {
            tools: Some(Vec::new()),
            ..AgentRunOverrides::default()
        }
        .apply(&mut emptied, AgentRunStart::Fresh)
        .unwrap();
        assert!(
            emptied
                .enabled_tools
                .iter()
                .all(|name| host_derived_child_tool(name)),
            "{:?}",
            emptied.enabled_tools
        );

        // (d) A child that had no tools to begin with — a model without tool
        // support, or a parent whose whole enabled set is child-disabled — is
        // not the allowlist's doing. It keeps only `box`, which every run
        // declares so the host can hand it notices.
        let mut toolless = base.clone();
        toolless.enabled_tools.clear();
        AgentRunOverrides {
            tools: Some(vec!["nonexistent_tool".into()]),
            ..AgentRunOverrides::default()
        }
        .apply(&mut toolless, AgentRunStart::Fresh)
        .unwrap();
        assert_eq!(toolless.enabled_tools, vec![BOX_TOOL.to_owned()]);

        // A deny list that empties the set is an explicit instruction, not an
        // unresolvable allowlist, so it never refuses. `box` is re-derived after
        // it like the task pair: it is the host's carrier, not a capability a
        // role grants or takes away.
        let mut denied_to_nothing = base.clone();
        AgentRunOverrides {
            disallowed_tools: base.enabled_tools.clone(),
            ..AgentRunOverrides::default()
        }
        .apply(&mut denied_to_nothing, AgentRunStart::Fresh)
        .unwrap();
        assert_eq!(denied_to_nothing.enabled_tools, vec![BOX_TOOL.to_owned()]);
    }

    /// The 40-round subagent ceiling was removed: a child loop is stopped by
    /// cancellation and by its parent's lifetime, not by a round budget. This
    /// runs a child well past the old limit and asserts every round reached the
    /// provider — a reintroduced cap would truncate the sequence and leave
    /// `serve_json_sequence` holding unanswered requests.
    #[test]
    fn a_subagent_loop_runs_past_the_retired_forty_round_ceiling() {
        const ROUNDS: usize = 45;
        let workspace = tempfile::tempdir().unwrap();
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let mut responses = (0..ROUNDS - 1)
            .map(|round| {
                json!({
                    "model": "model-test",
                    "status": "completed",
                    "output": [{
                        "type":"function_call","status":"completed",
                        "call_id":format!("list-{round}"),"name":"task_list",
                        "arguments":json!({}).to_string()
                    }],
                    "usage": {"input_tokens":1,"output_tokens":1,"total_tokens":2}
                })
            })
            .collect::<Vec<_>>();
        // The loop is cancellation-driven, so the child has to end the turn
        // itself; a tool call on every round would never return.
        responses.push(json!({
            "model": "model-test",
            "status": "completed",
            "output": [{
                "type":"message","status":"completed","role":"assistant",
                "content":[{"type":"output_text","text":"完成"}]
            }],
            "usage": {"input_tokens":1,"output_tokens":1,"total_tokens":2}
        }));
        let server = serve_json_sequence(listener, responses);

        let mut request = loop_request_for(address, workspace.path());
        request.subagent_depth = 1;
        let response =
            run_model(request, &AppState::default(), &discard_event, &approve_tool).unwrap();
        let captured = server.join().unwrap();
        assert_eq!(
            captured.len(),
            ROUNDS,
            "a subagent must not be stopped by a round budget"
        );
        // AI SDK normalizes provider-specific terminal reasons into its own
        // vocabulary (`stop`, `length`, `tool-calls`, …), so this asserts `stop`
        // rather than the Responses-native `completed`; host-side
        // `subagent_run_status` separately maps ordinary completion to Completed.
        assert_eq!(response.stop_reason.as_deref(), Some("stop"));
        assert!(
            !response.contexts.iter().any(|context| matches!(
                context,
                ContextItem::Assistant { content, .. } if content.contains("轮上限")
            )),
            "no round-limit notice may be produced"
        );
    }

    /// S7 (b), end to end: the refusal has to land BEFORE the receipt is signed,
    /// or a definition edit would leave an orphan reservation row behind on
    /// every rejected spawn — manufacturing exactly the state
    /// `orphan_reservation_rows_are_visible_to_the_spawn_dedupe_gate` exists to
    /// survive.
    #[test]
    fn an_unresolvable_allowlist_refuses_the_spawn_without_reserving_the_name() {
        let (directory, state, parent, definition) =
            named_agent_fixture(AgentDefinitionMemory::None);
        let reserved_before = state.reserved_subagent_names(&parent.conversation_id);

        let publish = |overrides: AgentRunOverrides, revision: u64| {
            let document = current_agent_document(&parent, &state).unwrap();
            let mut changed = (*document).clone();
            let mut edited = definition.clone();
            edited.revision = revision;
            edited.tools = overrides.tools;
            edited.effort = overrides.effort;
            edited.disallowed_tools = overrides.disallowed_tools;
            let definitions = vec![edited];
            set_conversation_agent_definitions(&mut changed, definitions);
            state
                .document_store
                .commit(&directory.path().join("document.v1.json"), changed)
                .unwrap();
        };
        let spawn = |pool: &AgentPool, id: &str| {
            std::thread::scope(|_scope| {
                run_agent_spawn(
                    pool,
                    &test_kernel_shadow(),
                    &parent,
                    ToolCall {
                        id: id.into(),
                        name: "agent_spawn".into(),
                        input: serde_json::from_value(json!({
                            "prompt": "审查改动",
                            // Both paths use this name: successful registration after
                            // refusal proves refusal precedes reservation.
                            "name": "allowlist-probe",
                            "agent_type": "reviewer"
                        }))
                        .unwrap(),
                    },
                    &state,
                    &discard_event,
                    &approve_tool,
                    false,
                    1,
                )
                .unwrap()
            })
        };

        publish(
            AgentRunOverrides {
                tools: Some(vec!["nonexistent_tool".into()]),
                ..AgentRunOverrides::default()
            },
            definition.revision + 1,
        );
        let refused = spawn(&AgentPool::new(), "unresolvable-allowlist");
        assert!(!refused.result.success);
        assert!(
            refused
                .result
                .output
                .contains("tools allowlist resolved to no usable tools"),
            "{}",
            refused.result.output
        );
        assert_eq!(
            state.reserved_subagent_names(&parent.conversation_id),
            reserved_before,
            "被拒绝的派生不能留下名字预留"
        );

        // The same definition with a wildcard is admitted, proving the refusal
        // is about an unresolvable list and not about carrying overrides at all.
        // S7 (e) rides along here: the resolved definition's effort and round
        // ceiling have to reach the registered child, which is the only thing
        // that proves `configure_named_agent_template` applies the overrides on
        // the real spawn path rather than only in the unit test.
        assert_ne!(parent.reasoning_effort, ReasoningEffort::Low);
        publish(
            AgentRunOverrides {
                tools: Some(vec![AGENT_TOOL_WILDCARD.into()]),
                effort: Some(ReasoningEffort::Low),
                disallowed_tools: vec!["read_file".into()],
            },
            definition.revision + 2,
        );
        let pool = AgentPool::new();
        let accepted = spawn(&pool, "wildcard-allowlist");
        assert!(accepted.result.success, "{}", accepted.result.output);
        let child = pool
            .find("allowlist-probe")
            .expect("wildcard spawn registers");
        assert!(!child.template.enabled_tools.is_empty());
        assert_eq!(child.template.reasoning_effort, ReasoningEffort::Low);
        assert!(!child
            .template
            .enabled_tools
            .iter()
            .any(|name| name == "read_file"));

        state.document_store.flush(Duration::from_secs(10)).unwrap();
    }

    /// The reservation dedupe guard protects names reserved before registration
    /// and before this turn's tool result is persisted.
    ///
    /// `sign_subagent_execution_mode` writes its row before `pool.register` and
    /// before this turn's tool result is persisted, so a turn that dies between
    /// them leaves a name held by a row that persisted records, the branch-wide
    /// `subagent_reserved_names`, and the live pool cannot see. The dedupe gate
    /// reads those persisted rows, so a later spawn receives the ordinary
    /// name-conflict refusal rather than a receipt-layer failure.
    ///
    /// Model-supplied names must be explicitly requested: an unreserved name is
    /// accepted and a name held by an orphan is rejected.
    #[test]
    fn orphan_reservation_rows_are_visible_to_the_spawn_dedupe_gate() {
        let (directory, state, parent, _) = named_agent_fixture(AgentDefinitionMemory::None);
        // Disable role requirements so name-reservation behavior is tested without
        // role validation rejecting either spawn.
        {
            let document = current_agent_document(&parent, &state).unwrap();
            let mut changed = (*document).clone();
            set_conversation_allows_roleless(&mut changed, true);
            state
                .document_store
                .commit(&directory.path().join("document.v1.json"), changed)
                .unwrap();
        }

        // Reserve `a1` exactly the way an interrupted spawn would, and persist
        // nothing: no record, no context, no live pool entry.
        let orphan_template = agent_child_template(&parent);
        reserve_subagent_execution_mode(&orphan_template, &state, "a1", SubagentRunKind::General)
            .unwrap();
        assert!(historical_agent_records(&parent.contexts).is_empty());
        assert!(parent.subagent_reserved_names.is_empty());

        let pool = AgentPool::new();
        std::thread::scope(|_scope| {
            // Request an unreserved name first, then the orphaned `a1`, to prove
            // that an orphan reserves only its own name.
            let execution = run_agent_spawn(
                &pool,
                &test_kernel_shadow(),
                &parent,
                ToolCall {
                    id: "past-orphan".into(),
                    name: "agent_spawn".into(),
                    input: serde_json::from_value(json!({ "prompt": "分析日志", "name": "a2" }))
                        .unwrap(),
                },
                &state,
                &discard_event,
                &approve_tool,
                false,
                1,
            )
            .unwrap();
            assert!(execution.result.success, "{}", execution.result.output);
            // The pool entry proves that this spawn used the requested name.
            assert_eq!(execution.result.output, "ok");
            assert!(pool.find("a2").is_some());
            assert!(pool.find("a1").is_none());
        });

        // Asking for the orphan by name gets the ordinary rename advice, not the
        // raw `subagent name is permanently reserved to another execution mode`
        // from four frames down inside the receipt layer.
        let pool = AgentPool::new();
        std::thread::scope(|_scope| {
            let execution = run_agent_spawn(
                &pool,
                &test_kernel_shadow(),
                &parent,
                ToolCall {
                    id: "explicit-orphan".into(),
                    name: "agent_spawn".into(),
                    input: serde_json::from_value(json!({ "prompt": "分析日志", "name": "a1" }))
                        .unwrap(),
                },
                &state,
                &discard_event,
                &approve_tool,
                false,
                1,
            )
            .unwrap();
            assert!(!execution.result.success, "{}", execution.result.output);
            assert!(
                execution
                    .result
                    .output
                    .contains("permanently reserved throughout this conversation branch tree"),
                "{}",
                execution.result.output
            );
            assert!(
                !execution
                    .result
                    .output
                    .contains("reserved to another execution mode"),
                "the internal reservation wording must not reach the model: {}",
                execution.result.output
            );
        });

        state.document_store.flush(Duration::from_secs(10)).unwrap();
        drop(directory);
    }

