    #[test]
    fn task_wait_handles_missing_agents_and_non_agent_tasks_without_a_network() {
        let request = run_request(ProviderFamily::OpenaiResponses);
        let state = AppState::default();
        let pool = AgentPool::new();

        // Waiting with no tasks at all returns an immediate hint.
        let wait = run_task_wait(
            &pool,
            &test_kernel_shadow(),
            &request,
            ToolCall {
                id: "call-wait".into(),
                name: "task_wait".into(),
                input: Map::new(),
            },
            &state,
            &discard_event,
            1,
        )
        .unwrap();
        assert!(wait.result.success);
        assert!(wait
            .result
            .output
            .contains(PromptKey::TaskWaitIdle.builtin_en()));

        // Waiting on an unknown name fails with guidance.
        let unknown = run_task_wait(
            &pool,
            &test_kernel_shadow(),
            &request,
            ToolCall {
                id: "call-wait-unknown".into(),
                name: "task_wait".into(),
                input: serde_json::from_value(json!({"tasks":["ghost"]})).unwrap(),
            },
            &state,
            &discard_event,
            1,
        )
        .unwrap();
        assert!(!unknown.result.success);
        assert!(
            unknown
                .result
                .output
                .contains("There is no subagent named ghost"),
            "{}",
            unknown.result.output
        );

        // A terminal or dev-server address that names nothing fails the same way rather than
        // silently watching an empty set until the timeout. The retired browser-page address
        // gets its own sentence, because an old transcript still holds `browser:` calls.
        for (address, expected) in [
            ("terminal:ghost", "There is no terminal terminal:ghost"),
            ("preview:ghost", "There is no dev server preview:ghost"),
            ("browser:main", "a browser page is no longer a task"),
        ] {
            let missing = run_task_wait(
                &pool,
                &test_kernel_shadow(),
                &request,
                ToolCall {
                    id: format!("call-wait-{address}"),
                    name: "task_wait".into(),
                    input: serde_json::from_value(json!({"tasks":[address]})).unwrap(),
                },
                &state,
                &discard_event,
                1,
            )
            .unwrap();
            assert!(!missing.result.success, "{}", missing.result.output);
            assert!(
                missing.result.output.contains(expected),
                "{}",
                missing.result.output
            );
        }
    }

    /// Mixed waits must also wait for non-pooled tasks, even if the named pooled
    /// task has already settled.
    #[test]
    fn a_mixed_wait_also_waits_for_its_non_pool_tasks() {
        let request = run_request(ProviderFamily::OpenaiResponses);
        let state = AppState::default();
        let pool = AgentPool::new();
        // A terminal agent with no requested result cannot delay this wait.
        pool.register(
            "a1".into(),
            "a1".into(),
            "早就跑完了".into(),
            agent_child_template(&request),
            SubagentRunKind::General,
            &state,
            Vec::new(),
            Vec::new(),
            AgentLiveStatus::Idle,
            "call-a1".into(),
            None,
        )
        .unwrap();
        // A synchronous task has no pool entry and must be observed by snapshot polling.
        let _guard =
            state
                .shell_tasks
                .register(&request.conversation_id, "bash", "sleep 600", false);
        let shell_ref = format!("shell:{}", _guard.shell_task_id());

        let started = Instant::now();
        let wait = run_task_wait(
            &pool,
            &test_kernel_shadow(),
            &request,
            ToolCall {
                id: "call-mixed".into(),
                name: "task_wait".into(),
                input: serde_json::from_value(
                    json!({"tasks":["a1",shell_ref],"timeout_seconds":5}),
                )
                .unwrap(),
            },
            &state,
            &discard_event,
            1,
        )
        .unwrap();
        assert!(wait.result.success, "{}", wait.result.output);
        assert!(
            started.elapsed() >= Duration::from_secs(5),
            "命令还在跑，混合等待必须真的等到期限，而不是在 a1 那边一了结就返回"
        );
        assert!(
            wait.result.output.contains(&shell_ref),
            "超时文案要点名还在跑的那条命令：{}",
            wait.result.output
        );
    }

    /// `task_list` groups every kind of task. With an empty conversation the
    /// groups are all empty, and the empty-state text must say so once rather
    /// than printing three bare headers.
    #[test]
    fn task_list_includes_recovered_shell_history_without_creating_pool_tasks() {
        let directory = tempfile::tempdir().unwrap();
        let request = run_request(ProviderFamily::OpenaiResponses);
        let first = AppState::default();
        first.shell_tasks.install_store(directory.path()).unwrap();
        let mut guard = first
            .shell_tasks
            .try_register(
                &request.conversation_id,
                "bash",
                "historical build",
                true,
                crate::shell_tasks::ShellTaskOrigin::default(),
            )
            .unwrap();
        let address = format!("shell:{}", guard.shell_task_id());
        guard.finish(ShellTaskOutcome::Failed, Some(2));
        drop(guard);
        drop(first);
        let restored = AppState::default();
        restored
            .shell_tasks
            .install_store(directory.path())
            .unwrap();
        let pool = AgentPool::new();
        let listed = run_task_list(
            &pool,
            &request,
            ToolCall {
                id: "restored-list".into(),
                name: "task_list".into(),
                input: Map::new(),
            },
            &restored,
        );
        assert!(listed.result.success);
        assert!(
            listed.result.output.contains(&address),
            "{}",
            listed.result.output
        );
        assert!(listed
            .result
            .output
            .contains(PromptKey::TaskGroupShellCommands.builtin_en()));
        assert!(listed.result.output.contains("historical build"));
        assert!(pool.all().is_empty());
    }

    /// Two workspaces that each run a `dev`: `task_list` prints each under an address carrying its
    /// workspace, `task_wait` takes that address back, and a bare id is refused as ambiguous
    /// rather than watching whichever server happened to come first — until only one is left.
    #[cfg(unix)]
    #[test]
    fn dev_servers_in_every_workspace_are_tasks_with_unambiguous_addresses() {
        let first = tempfile::tempdir().unwrap();
        let second = tempfile::tempdir().unwrap();
        for root in [first.path(), second.path()] {
            let directory = root.join(".mework");
            std::fs::create_dir_all(&directory).unwrap();
            std::fs::write(
                directory.join("launch.json"),
                r#"{"configurations":[{"name":"dev","runtimeExecutable":"/bin/sh","runtimeArgs":["-c","sleep 30"],"port":0,"autoPort":true}]}"#,
            )
            .unwrap();
        }
        let attached = |root: &Path| crate::model::AttachedWorkspace {
            machine: None,
            path: root.to_string_lossy().into_owned(),
        };
        let mut request = run_request(ProviderFamily::OpenaiResponses);
        request.workspace_path = first.path().to_string_lossy().into_owned();
        request.workspaces = crate::workspace_set::WorkspaceSet::resolve(
            &Default::default(),
            &attached(first.path()),
            &[attached(second.path())],
        )
        .unwrap();
        let state = AppState::default();
        let mut handles = Vec::new();
        for root in [first.path(), second.path()] {
            let crate::preview::PreviewStartOutcome::Server { server, .. } = crate::preview::start(
                &state.preview_servers,
                root,
                Some("dev"),
                Some(&request.conversation_id),
            )
            .unwrap() else {
                panic!("the entry runs a command");
            };
            handles.push(server.handle);
        }
        let pool = AgentPool::new();

        let listed = run_task_list(
            &pool,
            &request,
            ToolCall {
                id: "call-list".into(),
                name: "task_list".into(),
                input: Map::new(),
            },
            &state,
        );
        for address in ["preview:dev@1", "preview:dev@2"] {
            assert!(
                listed.result.output.contains(address),
                "{}",
                listed.result.output
            );
        }

        let resolve = |raw: &str| {
            resolve_wait_targets(
                &pool,
                &request,
                &state,
                &orchestration::TaskWaitSpec {
                    tasks: vec![orchestration::TaskRef::parse(raw).unwrap()],
                    timeout_seconds: 5,
                },
            )
            .map(|(_, others)| others)
        };
        let second_dev = orchestration::TaskRef::Preview {
            server_id: "dev".into(),
            workspace: Some(2),
        };
        assert_eq!(
            resolve("preview:dev").unwrap_err(),
            "preview:dev names dev servers in more than one workspace; wait on one of preview:dev@1, preview:dev@2"
        );
        assert_eq!(resolve("preview:DEV@2").unwrap(), vec![second_dev.clone()]);
        assert!(resolve("preview:dev@3")
            .unwrap_err()
            .starts_with("There is no dev server preview:dev@3;"));
        let observed = observe_task(&second_dev, &request, &state);
        assert_eq!(observed.task, "preview:dev@2");
        assert!(observed
            .detail
            .as_deref()
            .is_some_and(|detail| detail.starts_with("localhost:")));

        // With workspace 1's server gone the bare id is unambiguous again, and it is watched
        // under the full address.
        assert!(state.preview_servers.stop(&handles[0]));
        assert_eq!(resolve("preview:dev").unwrap(), vec![second_dev]);
        state.preview_servers.stop_all();
    }

