    #[test]
    fn agent_type_injection_is_gated_to_a_top_level_run_that_can_name_a_role() {
        let mut request = run_request(ProviderFamily::OpenaiResponses);
        request.enabled_tools = vec!["agent_spawn".into(), "ls".into()];
        request.subagent_depth = 0;
        assert!(should_inject_agent_types(&request));

        request.subagent_depth = 1;
        assert!(
            !should_inject_agent_types(&request),
            "a child never holds a role selector, so specialising its schema is a no-op"
        );

        request.subagent_depth = 0;
        request.enabled_tools = vec!["ls".into()];
        assert!(
            !should_inject_agent_types(&request),
            "advertising a disabled tool names a capability the host then refuses"
        );

        // A workflow step names a role through `agentType`, so a run holding
        // only `workflow` needs the role set just as much. Without this the
        // legal values of `agentType` would be unguessable in exactly the runs
        // that need them.
        request.enabled_tools = vec![workflow::WORKFLOW_TOOL.into()];
        assert!(should_inject_agent_types(&request));
        assert_eq!(
            agent_type_selector_tools(&request.enabled_tools),
            vec![workflow::WORKFLOW_TOOL]
        );

        // Only the tools that are actually callable are touched — an
        // `agent_spawn`-less run must not have that descriptor rewritten.
        request.enabled_tools = vec!["agent_spawn".into(), workflow::WORKFLOW_TOOL.into()];
        assert_eq!(
            agent_type_selector_tools(&request.enabled_tools),
            vec!["agent_spawn", workflow::WORKFLOW_TOOL]
        );
        assert!(agent_type_selector_tools(&["ls".to_owned()]).is_empty());
    }

    /// Roles are required only when the final resolved set contains at least one
    /// available role; a nonempty but unusable definition list must not lock tools.
    #[test]
    fn a_role_is_required_only_when_the_switch_is_off_and_a_usable_role_exists() {
        let (directory, state, parent, user) = named_agent_fixture(AgentDefinitionMemory::None);
        let anchor = directory.path().join("document.v1.json");
        let commit = |definitions: Vec<AgentDefinition>, allow_roleless: bool| {
            let document = current_agent_document(&parent, &state).unwrap();
            let mut changed = (*document).clone();
            set_conversation_agent_definitions(&mut changed, definitions);
            set_conversation_allows_roleless(&mut changed, allow_roleless);
            state.document_store.commit(&anchor, changed).unwrap();
            role_policy(&parent, &state)
        };

        let usable = vec![AgentDefinition {
            name: "reviewer".into(),
            ..user.clone()
        }];

        let policy = commit(usable.clone(), false);
        assert!(policy.required());
        assert_eq!(policy.known_names(), Some(vec!["reviewer".to_owned()]));

        let policy = commit(usable.clone(), true);
        assert!(!policy.required());
        assert_eq!(policy.known_names(), Some(vec!["reviewer".to_owned()]));

        let policy = commit(Vec::new(), false);
        assert!(!policy.required());
        assert_eq!(policy.known_names(), Some(Vec::new()));

        // A nonempty list with no usable roles must behave like an empty list.
        let policy = commit(
            vec![AgentDefinition {
                enabled: false,
                name: "shadowed".into(),
                ..user.clone()
            }],
            false,
        );
        assert!(!policy.required(), "停用的角色不能撑起必填");
        assert_eq!(policy.known_names(), Some(Vec::new()));

        state.document_store.flush(Duration::from_secs(10)).unwrap();
    }

    /// The wire schema must stay the same object whatever this conversation has
    /// selected: selecting another skill is not allowed to redeclare a tool.
    #[test]
    fn resolved_skills_reach_the_wire_schema_as_neither_an_enum_nor_a_listing() {
        let mut request = run_request(ProviderFamily::Anthropic);
        request.tools = crate::catalog::tool_catalog();
        request.enabled_tools = vec![SKILL_TOOL.into()];
        request.skills = vec![
            crate::model::ResolvedSkill {
                name: "Commit Helper".into(),
                trigger: "Use when writing a commit".into(),
                body: "BODY-A".into(),
                directory: "C:/skills/commit".into(),
            },
            crate::model::ResolvedSkill {
                name: "PDF Tools".into(),
                trigger: String::new(),
                body: "BODY-B".into(),
                directory: "C:/skills/pdf".into(),
            },
        ];

        let step = step_request(&request);
        let skill = step
            .tools
            .iter()
            .find(|tool| tool.name == SKILL_TOOL)
            .expect("skill tool in step");
        let wire = &skill.input_schema;

        assert!(wire["properties"]["name"].get("enum").is_none(), "{wire}");
        let description = wire["description"].as_str().expect("skill description");
        assert!(!description.contains("Commit Helper"), "{description}");
        // Skill bodies must never enter the schema.
        assert!(!wire.to_string().contains("BODY-A"), "{wire}");
    }

    /// A skill selected mid-conversation becomes one host notice, and only one:
    /// the card id is derived from the skill, so the next round finds it there.
    #[test]
    fn a_later_skill_becomes_one_box_notice_and_is_not_repeated() {
        let state = AppState::default();
        let mut request = run_request(ProviderFamily::Anthropic);
        request.contexts = vec![ContextItem::User {
            id: "ctx_u".into(),
            content: "hi".into(),
            images: Vec::new(),
            files: Vec::new(),
            created_at: "2026-09-16T00:00:00.000Z".into(),
        }];
        let added = || {
            vec![crate::model::AddedSkill {
                resource_id: "skill_probe".into(),
                name: "probe".into(),
                content: "## Skill added: probe\n\nBODY".into(),
            }]
        };
        request.added_skills = added();
        let mut generated = GeneratedContexts::new(None, None);

        record_added_skill_contexts(&mut request);
        deliver_host_notices(&mut request, &state, 1, &mut [], &mut generated);

        assert_eq!(request.contexts.len(), 2);
        let ContextItem::Tool {
            id,
            tool_name,
            result,
            ..
        } = &request.contexts[1]
        else {
            panic!("the added skill is a box card");
        };
        assert_eq!(id, "ctx_agent-result_skill_skill_probe");
        assert_eq!(tool_name, BOX_TOOL);
        assert_eq!(
            crate::wire_history::host_notice_kind(&request.contexts[1]),
            Some(crate::wire_history::notice_kind::SKILL_ADDED)
        );
        assert!(result.output.contains("BODY"));
        // It projects as a delivery, at the end of the transcript rather than
        // in the system prompt.
        let notice = crate::wire_history::host_task_notification(&request.contexts[1])
            .expect("a host delivery");
        assert!(notice.contains("<summary>The skill probe was added to this conversation</summary>"), "{notice}");
        assert_eq!(crate::aisdk::step::system_prompt_parts(&request).1, None);
        // The card is the run's own output, so it is persisted and returned
        // like any other host-authored context.
        assert_eq!(generated.items.len(), 1);

        // A second round over the same transcript delivers nothing more.
        request.added_skills = added();
        record_added_skill_contexts(&mut request);
        deliver_host_notices(&mut request, &state, 2, &mut [], &mut generated);
        assert_eq!(request.contexts.len(), 2);
        assert_eq!(generated.items.len(), 1);
    }

