    /// A run holding withheld MCP tools, built without dialing anything: the
    /// descriptors and bindings are what discovery would have produced.
    fn deferred_mcp_request(tools: &[(&str, &str, &str)]) -> RunModelRequest {
        let mut request = run_request(ProviderFamily::Anthropic);
        request.mcp_tool_discovery = true;
        let server = |name: &str| crate::mcp::RuntimeMcpServer {
            artifact_id: format!("test:{name}"),
            server_id: format!("test:{name}:s"),
            name: name.to_owned(),
            description: String::new(),
            disabled_tools: Vec::new(),
            confirm_every_call_tools: Vec::new(),
            request_timeout: None,
            transport: crate::mcp::RuntimeMcpTransport::Stdio {
                command: "node".into(),
                args: Vec::new(),
                env: Default::default(),
                cwd: None,
                env_passthrough: Vec::new(),
            },
        };
        for (server_name, tool_name, description) in tools {
            let exposed = format!("mcp__{server_name}__{tool_name}");
            request.tools.push(ToolDescriptor {
                force_confirmation: false,
                name: exposed.clone(),
                label: format!("MCP {server_name} / {tool_name}"),
                description: (*description).to_owned(),
                category: ToolCategory::Mcp,
                dangerous: true,
                parameters: Vec::new(),
                input_schema: Some(json!({
                    "type": "object",
                    "properties": {"body": {"type": "string"}},
                    "required": ["body"]
                })),
            });
            request.enabled_tools.push(exposed.clone());
            request.mcp_bindings.push(crate::mcp::McpToolBinding {
                exposed_name: exposed,
                remote_name: (*tool_name).to_owned(),
                title: (*tool_name).to_owned(),
                description: (*description).to_owned(),
                input_schema: json!({"type": "object", "properties": {}}),
                output_schema: None,
                annotations: None,
                requires_user_interaction: false,
                user_requires_confirmation: false,
                negotiated_protocol_version: "2025-06-18".into(),
                server: server(server_name),
            });
        }
        defer_mcp_tools(&mut request);
        request
    }

    /// Withholding is what saves the tokens, so it has to reach the wire: the
    /// names leave the enabled set, `tool_search` takes their place, and the
    /// announcement is the only trace of them left in the request.
    #[test]
    fn deferring_mcp_tools_withholds_their_schemas_and_announces_their_names() {
        let request = deferred_mcp_request(&[
            ("github", "create_issue", "Open an issue on a repository."),
            ("github", "list_issues", "List issues on a repository."),
            ("slack", "send_message", "Post a message to a channel."),
        ]);

        assert_eq!(request.deferred_tools.len(), 3);
        for deferred in &request.deferred_tools {
            assert!(
                !request.enabled_tools.contains(&deferred.name),
                "{} still reaches the wire",
                deferred.name
            );
            assert!(
                request.tools.iter().any(|tool| tool.name == deferred.name),
                "{} must stay dispatchable and fetchable",
                deferred.name
            );
            assert!(
                !crate::aisdk::tools::enabled_tools(&request)
                    .iter()
                    .any(|tool| tool.name == deferred.name)
            );
        }
        assert!(request
            .enabled_tools
            .contains(&crate::capabilities::TOOL_SEARCH_TOOL.to_owned()));

        // One announcement, grouped by server, carrying names and nothing else:
        // a description per tool would spend most of what withholding saved.
        assert_eq!(request.ephemeral_contexts.len(), 1);
        let announcement = match &request.ephemeral_contexts[0] {
            ContextItem::User { content, .. } => content.clone(),
            other => panic!("the announcement must be a user context: {other:?}"),
        };
        assert!(announcement.contains("github: mcp__github__create_issue, mcp__github__list_issues"));
        assert!(announcement.contains("slack: mcp__slack__send_message"));
        assert!(
            !announcement.contains("Open an issue"),
            "descriptions belong to the fetched schema, not the announcement: {announcement}"
        );
    }

    /// With discovery off nothing is withheld, and a `tool_search` left in a
    /// conversation's persisted list must not survive into that run.
    #[test]
    fn discovery_off_declares_every_mcp_tool_and_strips_a_stale_tool_search() {
        let mut request = deferred_mcp_request(&[("github", "create_issue", "Open an issue.")]);
        request.mcp_tool_discovery = false;
        request.enabled_tools.push("mcp__github__create_issue".into());
        defer_mcp_tools(&mut request);

        assert!(request.deferred_tools.is_empty());
        assert!(request
            .enabled_tools
            .contains(&"mcp__github__create_issue".to_owned()));
        assert!(!request
            .enabled_tools
            .contains(&crate::capabilities::TOOL_SEARCH_TOOL.to_owned()));
    }

    /// `select:` is the form every instruction that names a tool tells the model
    /// to use, so it has to resolve exactly and hand back a callable definition.
    #[test]
    fn tool_search_select_returns_the_matched_schemas_in_a_functions_block() {
        let request = deferred_mcp_request(&[
            ("github", "create_issue", "Open an issue on a repository."),
            ("github", "list_issues", "List issues on a repository."),
        ]);

        let (output, matched) = run_tool_search_tool(
            &request,
            json!({"query": "select:mcp__github__create_issue"})
                .as_object()
                .expect("input object"),
        )
        .expect("an exact name resolves");

        assert_eq!(matched, vec!["mcp__github__create_issue".to_owned()]);
        assert!(output.starts_with("<functions>\n<function>{"), "{output}");
        assert!(output.ends_with("</function>\n</functions>"), "{output}");
        // The encoding the tool's own description promises: one line per tool,
        // carrying exactly the JSON the wire tool set would have carried.
        let line = output
            .lines()
            .find(|line| line.starts_with("<function>"))
            .expect("one function line");
        let entry: Value = serde_json::from_str(
            line.trim_start_matches("<function>")
                .trim_end_matches("</function>"),
        )
        .expect("each function line is JSON");
        assert_eq!(entry["name"], "mcp__github__create_issue");
        assert_eq!(entry["description"], "Open an issue on a repository.");
        assert_eq!(entry["parameters"]["required"], json!(["body"]));
        assert!(
            !output.contains("mcp__github__list_issues"),
            "a select must not hand out what it was not asked for: {output}"
        );
    }

    /// Keyword search is what a model reaches for when it knows the capability
    /// but not the name, so the server segment, the tool segment and the
    /// description all have to be reachable — and `+` has to filter, not rank.
    #[test]
    fn tool_search_ranks_keywords_and_treats_a_plus_term_as_a_filter() {
        let request = deferred_mcp_request(&[
            ("github", "create_issue", "Open an issue on a repository."),
            ("slack", "send_message", "Post a message to a channel."),
            ("slack", "list_channels", "List the channels in a workspace."),
        ]);
        let search = |query: &str| {
            run_tool_search_tool(
                &request,
                json!({"query": query}).as_object().expect("input object"),
            )
            .expect("a keyword search always answers")
            .1
        };

        assert_eq!(search("issue"), vec!["mcp__github__create_issue".to_owned()]);
        // The description is reachable even when neither name segment is.
        assert_eq!(search("channel"), vec![
            "mcp__slack__list_channels".to_owned(),
            "mcp__slack__send_message".to_owned(),
        ]);
        // A `+` term admits only what carries it; the rest of the query orders
        // what survives rather than narrowing it further.
        assert_eq!(
            search("+slack send"),
            vec![
                "mcp__slack__send_message".to_owned(),
                "mcp__slack__list_channels".to_owned(),
            ]
        );
        // The other side of the same rule: `message` alone would reach two
        // Slack tools, and `+github` keeps every one of them out.
        assert_eq!(
            search("+github message"),
            vec!["mcp__github__create_issue".to_owned()]
        );
        // A required term nothing carries empties the result rather than
        // degrading into a plain keyword search.
        assert!(search("+kubernetes message").is_empty());
        // A miss says what it searched and how much there was to search, so the
        // model can tell "wrong word" from "nothing configured".
        let (output, matched) = run_tool_search_tool(
            &request,
            json!({"query": "kubernetes"})
                .as_object()
                .expect("input object"),
        )
        .expect("a miss is an answer, not an error");
        assert!(matched.is_empty());
        assert!(output.contains("kubernetes"), "{output}");
        assert!(output.contains('3'), "{output}");
        assert!(!output.contains("<functions>"), "{output}");
    }

    /// `max_results` bounds a keyword search and nothing else: a `select:` that
    /// resolves four names has already been told exactly what to return.
    #[test]
    fn max_results_bounds_a_keyword_search_but_never_a_select() {
        let request = deferred_mcp_request(&[
            ("slack", "send_message", "Post a message."),
            ("slack", "read_message", "Read a message."),
            ("slack", "edit_message", "Edit a message."),
        ]);
        let bounded = run_tool_search_tool(
            &request,
            json!({"query": "message", "max_results": 2})
                .as_object()
                .expect("input object"),
        )
        .expect("a bounded search answers")
        .1;
        assert_eq!(bounded.len(), 2);

        let selected = run_tool_search_tool(
            &request,
            json!({
                "query": "select:mcp__slack__send_message,mcp__slack__read_message,mcp__slack__edit_message",
                "max_results": 1
            })
            .as_object()
            .expect("input object"),
        )
        .expect("a select answers")
        .1;
        assert_eq!(selected.len(), 3);
    }

    /// Calling a withheld tool is the mistake the announcement invites, so the
    /// refusal has to carry its own repair rather than read as a dead end.
    #[test]
    fn calling_a_withheld_tool_is_refused_with_the_call_that_fetches_it() {
        let mut request = deferred_mcp_request(&[("github", "create_issue", "Open an issue.")]);
        let call = ToolCall {
            id: "call-withheld".into(),
            name: "mcp__github__create_issue".into(),
            input: JsonObject::new(),
        };

        let reason = automatic_tool_rejection_reason(&request, &call)
            .expect("a withheld tool is not callable yet");
        assert!(reason.contains("tool_search"), "{reason}");
        assert!(
            reason.contains("select:mcp__github__create_issue"),
            "{reason}"
        );
        assert!(
            !reason.contains("not enabled"),
            "a repairable state must not read like a disabled one: {reason}"
        );

        // Once the schema has gone out, the same call is ordinary.
        let mut state = ToolSearchTurnState::default();
        assert!(state.surface(vec!["mcp__github__create_issue".into()]));
        surface_deferred_tools(&mut request, &state);
        assert_eq!(automatic_tool_rejection_reason(&request, &call), None);
        assert!(crate::aisdk::tools::enabled_tools(&request)
            .iter()
            .any(|tool| tool.name == "mcp__github__create_issue"));
        // Surfacing twice adds nothing: the state is the whole truth, and the
        // round loop re-derives from it after every settled tool.
        assert!(!state.surface(vec!["mcp__github__create_issue".into()]));
        surface_deferred_tools(&mut request, &state);
        assert_eq!(
            request
                .enabled_tools
                .iter()
                .filter(|name| *name == "mcp__github__create_issue")
                .count(),
            1
        );
    }

    /// A child dials the same servers, so it withholds the same tools — and it
    /// starts from an empty history, so the parent's fetches are not its own.
    #[test]
    fn a_child_re_withholds_every_tool_its_parent_had_already_fetched() {
        let mut parent = deferred_mcp_request(&[("github", "create_issue", "Open an issue.")]);
        let mut state = ToolSearchTurnState::default();
        state.surface(vec!["mcp__github__create_issue".into()]);
        surface_deferred_tools(&mut parent, &state);
        assert!(parent
            .enabled_tools
            .contains(&"mcp__github__create_issue".to_owned()));

        let mut child = agent_child_template(&parent);
        assert!(child.mcp_tool_discovery, "the servers are inherited");
        defer_mcp_tools(&mut child);
        assert_eq!(child.deferred_tools.len(), 1);
        assert!(
            !child
                .enabled_tools
                .contains(&"mcp__github__create_issue".to_owned()),
            "a child never read the parent's tool_search result"
        );
        assert!(child
            .enabled_tools
            .contains(&crate::capabilities::TOOL_SEARCH_TOOL.to_owned()));
    }

    /// Role names are injected into schemas as `enum` or `$defs`; unavailable roles
    /// never appear in the resolved set.
    /// Role names are injected into schemas as `enum` or `$defs`; unavailable roles
    /// never appear in the resolved set.
    #[test]
    fn available_role_names_reach_both_tool_schemas_as_machine_readable_values() {
        let (directory, state, mut parent, user) = named_agent_fixture(AgentDefinitionMemory::None);
        let document = current_agent_document(&parent, &state).unwrap();
        let mut changed = (*document).clone();
        set_conversation_agent_definitions(
            &mut changed,
            vec![
                AgentDefinition {
                    name: "zeta".into(),
                    ..user.clone()
                },
                AgentDefinition {
                    name: "alpha".into(),
                    ..user.clone()
                },
                AgentDefinition {
                    enabled: false,
                    name: "disabled-one".into(),
                    ..user.clone()
                },
            ],
        );
        state
            .document_store
            .commit(&directory.path().join("document.v1.json"), changed)
            .unwrap();
        let document = current_agent_document(&parent, &state).unwrap();
        let roles = available_agent_types(
            &document,
            request_agent_definitions(&document, &parent),
            &parent.workspace_id,
        );
        let names = roles
            .iter()
            .map(|role| role.name.clone())
            .collect::<Vec<_>>();
        assert_eq!(names, vec!["alpha".to_owned(), "zeta".to_owned()]);

        parent.tools = crate::catalog::tool_catalog();
        parent.enabled_tools = vec!["agent_spawn".into(), workflow::WORKFLOW_TOOL.into()];
        inject_agent_type_schemas(&mut parent, &roles, false);

        let wire = |request: &RunModelRequest, tool: &str| {
            step_request(request)
                .tools
                .into_iter()
                .find(|entry| entry.name == tool)
                .unwrap_or_else(|| panic!("step 里找不到 {tool}"))
                .input_schema
        };
        assert_eq!(
            wire(&parent, "agent_spawn")["properties"]["agent_type"]["enum"],
            json!(["alpha", "zeta"])
        );
        assert_eq!(
            wire(&parent, workflow::WORKFLOW_TOOL)["$defs"]["agentType"]["enum"],
            json!(["alpha", "zeta"])
        );
        assert!(!wire(&parent, "agent_spawn")
            .to_string()
            .contains("disabled-one"));

        inject_agent_type_schemas(&mut parent, &[], false);
        let empty = wire(&parent, "agent_spawn");
        assert!(empty["properties"].get("agent_type").is_none(), "{empty}");
        assert!(empty.get("not").is_none(), "{empty}");
        assert!(wire(&parent, workflow::WORKFLOW_TOOL)
            .get("$defs")
            .is_none());

        // Required mode must reach the sidecar frame rather than only the schema
        // constructor.
        inject_agent_type_schemas(&mut parent, &roles, true);
        let required = wire(&parent, "agent_spawn");
        assert_eq!(
            required["required"],
            json!(["prompt", "name", "agent_type"])
        );
        assert!(
            required["properties"].get("context").is_none(),
            "{required}"
        );
        assert!(required.get("not").is_none(), "{required}");
        assert_eq!(
            required["properties"]["agent_type"]["enum"],
            json!(["alpha", "zeta"])
        );
        // The workflow schema shape is unchanged; only its description changes.
        let script = wire(&parent, workflow::WORKFLOW_TOOL)["properties"]["script"]["description"]
            .as_str()
            .expect("script description")
            .to_owned();
        assert!(script.contains("REQUIRED"), "{script}");
        assert!(script.contains("throws synchronously"), "{script}");

        state.document_store.flush(Duration::from_secs(10)).unwrap();
    }

    /// Role descriptions appear on one tool description only; both schemas retain
    /// machine-readable role names.
    /// Role descriptions appear on one tool description only; both schemas retain
    /// machine-readable role names.
    #[test]
    fn role_descriptions_land_on_exactly_one_tool_description_per_run() {
        let (directory, state, mut parent, _user) =
            named_agent_fixture(AgentDefinitionMemory::None);
        let roles = vec![
            crate::builtin_schemas::AgentRoleSummary {
                name: "alpha".into(),
                description: "第一段说明。".into(),
            },
            crate::builtin_schemas::AgentRoleSummary {
                name: "zeta".into(),
                description: String::new(),
            },
        ];
        let block = "Available agent types:\n- alpha: 第一段说明。";

        let wire = |request: &RunModelRequest, tool: &str| {
            step_request(request)
                .tools
                .into_iter()
                .find(|entry| entry.name == tool)
                .unwrap_or_else(|| panic!("step 里找不到 {tool}"))
                .input_schema
        };
        let carries = |request: &RunModelRequest, tool: &str| {
            let schema = wire(request, tool);
            schema["description"]
                .as_str()
                .expect("tool schema description")
                .contains(block)
        };

        parent.tools = crate::catalog::tool_catalog();

        parent.enabled_tools = vec!["agent_spawn".into(), workflow::WORKFLOW_TOOL.into()];
        inject_agent_type_schemas(&mut parent, &roles, false);
        assert!(carries(&parent, workflow::WORKFLOW_TOOL));
        assert!(!carries(&parent, "agent_spawn"));
        assert!(!wire(&parent, workflow::WORKFLOW_TOOL)["description"]
            .as_str()
            .expect("tool schema description")
            .contains("- zeta"));
        assert_eq!(
            wire(&parent, "agent_spawn")["properties"]["agent_type"]["enum"],
            json!(["alpha", "zeta"])
        );

        parent.tools = crate::catalog::tool_catalog();
        parent.enabled_tools = vec![workflow::WORKFLOW_TOOL.into()];
        inject_agent_type_schemas(&mut parent, &roles, false);
        assert!(carries(&parent, workflow::WORKFLOW_TOOL));

        // With only `agent_spawn` enabled, its schema carries the description.
        parent.tools = crate::catalog::tool_catalog();
        parent.enabled_tools = vec!["agent_spawn".into()];
        inject_agent_type_schemas(&mut parent, &roles, false);
        assert!(carries(&parent, "agent_spawn"));

        // When every description is empty, omit the block rather than leaving a
        // blank heading.
        let silent = roles
            .iter()
            .map(|role| crate::builtin_schemas::AgentRoleSummary {
                name: role.name.clone(),
                description: String::new(),
            })
            .collect::<Vec<_>>();
        parent.tools = crate::catalog::tool_catalog();
        parent.enabled_tools = vec!["agent_spawn".into(), workflow::WORKFLOW_TOOL.into()];
        inject_agent_type_schemas(&mut parent, &silent, false);
        for tool in ["agent_spawn", workflow::WORKFLOW_TOOL] {
            assert!(
                !wire(&parent, tool)["description"]
                    .as_str()
                    .expect("tool schema description")
                    .contains("Available agent types"),
                "{tool}"
            );
        }

        state.document_store.flush(Duration::from_secs(10)).unwrap();
        drop(directory);
    }

