    #[test]
    fn a_role_whose_bound_model_is_gone_disappears_and_is_indistinguishable_from_absent() {
        let (directory, state, parent, user) = named_agent_fixture(AgentDefinitionMemory::None);
        let document = current_agent_document(&parent, &state).unwrap();
        let mut changed = (*document).clone();
        let provider_id = parent.provider.id.clone();
        let live_model_id = parent.model.id.clone();
        set_conversation_agent_definitions(
            &mut changed,
            vec![
                // Bound to a model this provider really carries: stays visible.
                AgentDefinition {
                    name: "bound-live".into(),
                    model_selection: AgentModelSelection::Explicit {
                        provider_id: provider_id.clone(),
                        model_id: live_model_id.clone(),
                    },
                    ..user.clone()
                },
                // Same model ID, a provider that does not exist. The pair is the
                // identity, not the bare ID, so this must NOT borrow the live one.
                AgentDefinition {
                    name: "bound-missing-provider".into(),
                    model_selection: AgentModelSelection::Explicit {
                        provider_id: "provider-that-was-deleted".into(),
                        model_id: live_model_id.clone(),
                    },
                    ..user.clone()
                },
                // Real provider, model ID it never had.
                AgentDefinition {
                    name: "bound-missing-model".into(),
                    model_selection: AgentModelSelection::Explicit {
                        provider_id: provider_id.clone(),
                        model_id: "model-that-was-removed".into(),
                    },
                    ..user.clone()
                },
                // Inherit rides the parent's model, which exists by construction.
                AgentDefinition {
                    name: "inheriting".into(),
                    model_selection: AgentModelSelection::Inherit,
                    ..user.clone()
                },
            ],
        );
        state
            .document_store
            .commit(&directory.path().join("document.v1.json"), changed)
            .unwrap();
        let document = current_agent_document(&parent, &state).unwrap();

        let names = available_agent_type_names(
            &document,
            request_agent_definitions(&document, &parent),
            &parent.workspace_id,
        );
        // The whole point: a role whose model cannot resolve is not offered at
        // all, rather than being offered and then failing at spawn.
        assert_eq!(
            names,
            vec!["bound-live".to_owned(), "inheriting".to_owned()]
        );

        // Naming a hidden role must produce the SAME bytes as naming one that
        // was never configured, so the model cannot probe the user's provider
        // setup by comparing error messages. Drive the REAL spawn path rather
        // than asserting against the helper directly — asserting on
        // `unknown_agent_type_error` would only prove the helper equals itself
        // and would still pass if the spawn guard were deleted.
        let spawn_error = |agent_type: &str| {
            let pool = AgentPool::new();
            std::thread::scope(|_scope| {
                let execution = run_agent_spawn(
                    &pool,
                    &test_kernel_shadow(),
                    &parent,
                    ToolCall {
                        id: format!("spawn-{agent_type}"),
                        name: "agent_spawn".into(),
                        input: serde_json::from_value(json!({
                            "prompt": "审查这次改动并给出结论",
                            // Both paths must name the agent, or each fails for
                            // the same missing-`name` error.
                            "name": "role-probe",
                            "agent_type": agent_type
                        }))
                        .unwrap(),
                    },
                    &state,
                    &discard_event,
                    &approve_tool,
                    false,
                    1,
                )
                .unwrap();
                assert!(!execution.result.success, "{}", execution.result.output);
                execution.result.output
            })
        };

        let hidden = spawn_error("bound-missing-provider");
        let absent = spawn_error("never-configured");
        assert_eq!(
            hidden.replace("bound-missing-provider", "X"),
            absent.replace("never-configured", "X"),
            "a hidden role must be indistinguishable from an absent one"
        );
        // And the leak this exists to prevent: neither the disabled provider's
        // ID nor any hint that a model binding was involved may surface.
        assert!(!hidden.contains("provider-that-was-deleted"), "{hidden}");
        assert!(!hidden.contains("提供商"), "{hidden}");
        assert!(!hidden.contains("模型"), "{hidden}");

        let hidden_model = spawn_error("bound-missing-model");
        assert_eq!(
            hidden_model.replace("bound-missing-model", "X"),
            absent.replace("never-configured", "X")
        );
        assert!(
            !hidden_model.contains("model-that-was-removed"),
            "{hidden_model}"
        );

        state.document_store.flush(Duration::from_secs(10)).unwrap();
    }

    /// The `Unavailable` state is the renderer's durable record that a binding
    /// was found dead. Unlike a transient `Explicit` miss it is NOT disguised as
    /// an unknown name: the user configured this role and can repair it, and
    /// telling them it does not exist would send them to create a duplicate.
    ///
    /// Nothing leaks by saying so — a name that was never configured still gets
    /// the unknown-name text, so the two cases stay distinguishable only for
    /// roles the user already knows about.
    #[test]
    fn an_unavailable_role_is_refused_by_name_rather_than_disguised_as_absent() {
        let (directory, state, parent, user) = named_agent_fixture(AgentDefinitionMemory::None);
        let document = current_agent_document(&parent, &state).unwrap();
        let mut changed = (*document).clone();
        set_conversation_agent_definitions(
            &mut changed,
            vec![AgentDefinition {
                name: "broken-role".into(),
                model_selection: AgentModelSelection::Unavailable,
                ..user.clone()
            }],
        );
        state
            .document_store
            .commit(&directory.path().join("document.v1.json"), changed)
            .unwrap();
        let document = current_agent_document(&parent, &state).unwrap();
        let definitions = request_agent_definitions(&document, &parent);

        // Still hidden from the model: it cannot run, so offering it would only
        // train the model to retry something that can never work.
        assert!(
            available_agent_type_names(&document, definitions, &parent.workspace_id).is_empty()
        );

        let refusal =
            resolve_agent_definition(&document, definitions, &parent.workspace_id, "broken-role")
                .unwrap_err();
        assert!(
            refusal.contains("model bound to named-agent definition"),
            "{refusal}"
        );
        assert!(
            !refusal.contains("does not exist or does not apply to the current workspace"),
            "an unavailable role must not be reported as absent: {refusal}"
        );

        // A name that was never configured keeps the unknown-name wording, so
        // the distinction only ever applies to roles the user has already seen.
        let absent =
            resolve_agent_definition(&document, definitions, &parent.workspace_id, "never-made")
                .unwrap_err();
        assert!(
            absent.contains("does not exist or does not apply to the current workspace"),
            "{absent}"
        );

        // Defence in depth: even if a future call path skipped the resolver, a
        // binding must not silently borrow the parent's model.
        let unavailable = AgentDefinition {
            name: "broken-role".into(),
            model_selection: AgentModelSelection::Unavailable,
            ..user
        };
        let binding_error =
            initial_agent_definition_binding(&parent, &document, &unavailable).unwrap_err();
        assert!(
            binding_error.contains("model bound to named-agent definition"),
            "{binding_error}"
        );

        state.document_store.flush(Duration::from_secs(10)).unwrap();
    }

    #[test]
    fn a_disabled_provider_hides_the_roles_bound_to_it() {
        let (directory, state, parent, user) = named_agent_fixture(AgentDefinitionMemory::None);
        let document = current_agent_document(&parent, &state).unwrap();
        let mut changed = (*document).clone();
        let provider_id = parent.provider.id.clone();
        let live_model_id = parent.model.id.clone();
        set_conversation_agent_definitions(
            &mut changed,
            vec![AgentDefinition {
                name: "bound-live".into(),
                model_selection: AgentModelSelection::Explicit {
                    provider_id: provider_id.clone(),
                    model_id: live_model_id.clone(),
                },
                ..user.clone()
            }],
        );
        // A model has no enabled state of its own: it is either in the
        // provider's list or absent, and an absent one is refused by document
        // validation long before a role could resolve it. The provider switch is
        // the only remaining way to hide a still-listed pair.
        for provider in &mut changed.assets.api_providers {
            if provider.id == provider_id {
                provider.enabled = false;
            }
        }
        state
            .document_store
            .commit(&directory.path().join("document.v1.json"), changed)
            .unwrap();
        let document = current_agent_document(&parent, &state).unwrap();

        assert!(available_agent_type_names(
            &document,
            request_agent_definitions(&document, &parent),
            &parent.workspace_id
        )
        .is_empty());

        state.document_store.flush(Duration::from_secs(10)).unwrap();
    }

    #[test]
    fn a_hidden_role_stays_hidden_through_the_separator_folded_pass() {
        let (directory, state, parent, user) = named_agent_fixture(AgentDefinitionMemory::None);
        let document = current_agent_document(&parent, &state).unwrap();
        let mut changed = (*document).clone();
        set_conversation_agent_definitions(
            &mut changed,
            vec![AgentDefinition {
                name: "code-reviewer".into(),
                model_selection: AgentModelSelection::Explicit {
                    provider_id: parent.provider.id.clone(),
                    model_id: "model-that-was-removed".into(),
                },
                ..user.clone()
            }],
        );
        state
            .document_store
            .commit(&directory.path().join("document.v1.json"), changed)
            .unwrap();
        let document = current_agent_document(&parent, &state).unwrap();

        // Hidden under its exact name...
        let exact = resolve_agent_definition(
            &document,
            request_agent_definitions(&document, &parent),
            &parent.workspace_id,
            "code-reviewer",
        )
        .unwrap_err();
        // ...and equally hidden when reached through the separator-folded pass,
        // which is a second success branch and would otherwise hand back the
        // very definition the exact name refuses.
        let folded = resolve_agent_definition(
            &document,
            request_agent_definitions(&document, &parent),
            &parent.workspace_id,
            "code_reviewer",
        )
        .unwrap_err();
        assert_eq!(
            exact.replace("code-reviewer", "X"),
            folded.replace("code_reviewer", "X")
        );
        assert!(!folded.contains("model-that-was-removed"), "{folded}");

        state.document_store.flush(Duration::from_secs(10)).unwrap();
    }

    /// Step-level `agentType` applies the named role's system prompt, provider/model,
    /// and allowed tools; step-level model IDs remain forbidden.
    #[test]
    fn a_workflow_step_can_run_as_a_named_role_but_never_names_a_model() {
        let (directory, state, parent, user) = named_agent_fixture(AgentDefinitionMemory::None);
        let document = current_agent_document(&parent, &state).unwrap();
        let mut changed = (*document).clone();
        let other_model = parent.provider.models[1].clone();
        // Edit the fixture's own definition in place rather than replacing the
        // list: the identity ledger is keyed to it, and a freshly minted
        // definition would fail `verify_definition_identity_ledger` for a reason
        // that has nothing to do with what this test is about.
        let definitions = vec![AgentDefinition {
            model_selection: AgentModelSelection::Explicit {
                provider_id: parent.provider.id.clone(),
                model_id: other_model.id.clone(),
            },
            revision: user.revision + 1,
            ..user.clone()
        }];
        let role_name = definitions[0].name.clone();
        set_conversation_agent_definitions(&mut changed, definitions);
        state
            .document_store
            .commit(&directory.path().join("document.v1.json"), changed)
            .unwrap();

        // The role reaches the step template: its own model, which the parent
        // was not running. Its PROMPT is the parent conversation's — a role has
        // none of its own.
        let mut template = agent_child_template(&parent);
        assert_ne!(template.model.id, other_model.id);
        apply_named_role_to_fresh_template(&parent, &state, &mut template, &role_name).unwrap();
        assert_eq!(template.model.id, other_model.id);
        assert!(
            template
                .assembled_system_prompt
                .starts_with(parent.assembled_system_prompt.trim()),
            "{}",
            template.assembled_system_prompt
        );
        assert!(template.agent_definition_binding.is_some());

        // An unknown role fails with the ordinary unknown-name wording.
        let miss =
            apply_named_role_to_fresh_template(&parent, &state, &mut template, "nope").unwrap_err();
        assert!(
            miss.contains("does not exist or does not apply to the current workspace"),
            "{miss}"
        );

        // A raw model in `agent()` options throws synchronously; the unhandled
        // error fails the workflow while the call still returns a spawn receipt.
        let call = ToolCall {
            id: "wf-model".into(),
            name: "workflow".into(),
            input: json!({"script": "export const meta = { name: \"x\", description: \"d\" }\nreturn await agent(\"步骤\", { model: \"some-model-id\" })", "name": "role-model-run"})
            .as_object()
            .unwrap()
            .clone(),
        };
        let pool = AgentPool::new();
        let shadow = test_kernel_shadow();
        let execution = std::thread::scope(|_scope| {
            workflow::run_workflow_tool(
                &pool,
                &shadow,
                &parent,
                call,
                &state,
                &discard_event,
                &approve_tool,
                false,
                1,
            )
        })
        .unwrap();
        assert!(execution.result.success, "{}", execution.result.output);
        pool.wait_settled_for_tests(Duration::from_secs(30));
        let envelopes = pool.take_undelivered_results();
        assert_eq!(envelopes.len(), 1);
        // The refusal must direct the model to usable role names and the schema's
        // enumerated `agentType` values.
        assert!(
            envelopes[0].content.contains("agentType")
                && envelopes[0].content.contains("$defs.agentType"),
            "{}",
            envelopes[0].content
        );
        let driver = pool
            .all()
            .into_iter()
            .find(|agent| agent.kind == SubagentRunKind::WorkflowStep)
            .expect("驱动器已注册");
        assert_eq!(driver.record().status, SubagentRunStatus::Failed);

        state.document_store.flush(Duration::from_secs(10)).unwrap();
    }

    /// A role's conversation template seeds `agent_spawn` children only. A
    /// workflow step running as that role starts from its prompt alone: the
    /// script is the step's whole instruction, and a canned opening history
    /// would sit between it and the model.
    #[test]
    fn a_workflow_step_never_opens_with_its_roles_conversation_template() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = thread::spawn(move || {
            let (mut stream, _) = listener.accept().unwrap();
            let body = read_http_request_with_body(&mut stream);
            write_json_response(&mut stream, "200 OK", &responses_text_output("done"));
            body
        });

        let (directory, state, mut parent, user) =
            named_agent_fixture(AgentDefinitionMemory::None);
        parent.provider.base_url = format!("http://{address}/v1");
        let anchor = directory.path().join("document.v1.json");
        crate::conversations::store(&anchor)
            .unwrap()
            .put_template(
                "template_role_opening",
                "",
                &[ContextItem::User {
                    id: "template-user".into(),
                    content: "ROLE-TEMPLATE-MARKER {input}".into(),
                    images: Vec::new(),
                    files: Vec::new(),
                    created_at: "2026-09-30T00:00:00Z".into(),
                }],
            )
            .unwrap();
        let mut changed = (*current_agent_document(&parent, &state).unwrap()).clone();
        changed.assets.api_providers = vec![parent.provider.clone()];
        let role_name = user.name.clone();
        set_conversation_agent_definitions(
            &mut changed,
            vec![AgentDefinition {
                template_id: Some("template_role_opening".into()),
                revision: user.revision + 1,
                ..user
            }],
        );
        state.document_store.commit(&anchor, changed).unwrap();

        let call = ToolCall {
            id: "wf-role-template".into(),
            name: "workflow".into(),
            input: json!({
                "script": format!("export const meta = {{ name: \"x\", description: \"d\" }}\nreturn await agent(\"STEP-PROMPT\", {{ agentType: \"{role_name}\" }})"),
                "name": "role-template-run",
            })
            .as_object()
            .unwrap()
            .clone(),
        };
        let pool = AgentPool::new();
        let shadow = test_kernel_shadow();
        let execution = workflow::run_workflow_tool(
            &pool,
            &shadow,
            &parent,
            call,
            &state,
            &discard_event,
            &approve_tool,
            false,
            1,
        )
        .unwrap();
        assert!(execution.result.success, "{}", execution.result.output);
        pool.wait_settled_for_tests(Duration::from_secs(30));
        let body = server.join().unwrap();
        assert!(body.contains("STEP-PROMPT"), "{body}");
        assert!(!body.contains("ROLE-TEMPLATE-MARKER"), "{body}");

        state.document_store.flush(Duration::from_secs(10)).unwrap();
    }

    #[test]
    fn ordinary_subagents_reload_project_instructions() {
        let workspace = tempfile::tempdir().unwrap();
        let app_data = tempfile::tempdir().unwrap();
        std::fs::write(
            workspace.path().join("MEWORK.md"),
            "# Child project rule\nUse the verified project convention.",
        )
        .unwrap();
        let mut child = run_request(ProviderFamily::OpenaiResponses);
        child.workspace_path = workspace.path().to_string_lossy().into_owned();
        child.workspace_id = "workspace-child-memory".into();
        child.app_data_path = app_data.path().to_string_lossy().into_owned();
        child.subagent_depth = 1;
        child.ephemeral_contexts.push(ContextItem::User {
            id: "quoted-project-marker".into(),
            content: format!(
                "Literal documentation example: {} not a host context {}",
                project_memory::PROJECT_MEMORY_PROMPT_START,
                project_memory::PROJECT_MEMORY_PROMPT_END
            ),
            images: Vec::new(),
            files: Vec::new(),
            created_at: "2026-07-24T00:00:00Z".into(),
        });

        let state = ProjectMemoryRunState::discover(&mut child, None)
            .unwrap()
            .expect("ordinary child project memory");
        assert!(state.trust_lease.is_none());
        assert!(child.project_memory_context_id.is_some());
        assert!(child
            .ephemeral_contexts
            .iter()
            .any(|context| context.id() == "quoted-project-marker"));
        assert!(child.ephemeral_contexts.iter().any(|context| {
            matches!(
                context,
                ContextItem::User { content, .. }
                    if content.contains(project_memory::PROJECT_MEMORY_PROMPT_START)
                        && content.contains("Use the verified project convention.")
            )
        }));
    }

    #[test]
    fn nested_project_instructions_load_only_after_successful_read_and_reload_after_restart() {
        let workspace = tempfile::tempdir().unwrap();
        let app_data = tempfile::tempdir().unwrap();
        std::fs::write(workspace.path().join("MEWORK.md"), "startup root").unwrap();
        std::fs::create_dir_all(workspace.path().join("pkg/deep")).unwrap();
        std::fs::write(
            workspace.path().join("pkg/MEWORK.md"),
            "nested package instruction",
        )
        .unwrap();
        std::fs::write(workspace.path().join("pkg/deep/main.rs"), "fn main() {}").unwrap();

        let mut request = run_request(ProviderFamily::OpenaiResponses);
        request.workspace_path = workspace.path().to_string_lossy().into_owned();
        request.workspace_id = "workspace-nested-read".into();
        request.app_data_path = app_data.path().to_string_lossy().into_owned();
        request.security_level = SecurityLevel::FullAccess;
        request.tools = catalog::tool_catalog()
            .into_iter()
            .filter(|tool| tool.name == "read")
            .collect();
        request.enabled_tools = vec!["read".into()];
        let mut memory = ProjectMemoryRunState::discover(&mut request, None)
            .unwrap()
            .expect("project memory");
        assert!(request.ephemeral_contexts.iter().all(|context| {
            !matches!(
                context,
                ContextItem::User { content, .. } if content.contains("nested package instruction")
            )
        }));

        let failed = ToolResult {
            success: false,
            output: "not read".into(),
            images: Vec::new(),
            diff: None,
            executed_at: Utc::now().to_rfc3339(),
            duration_ms: 0,
        };
        let read_call = ToolCall {
            id: "nested-read".into(),
            name: "read".into(),
            input: serde_json::from_value(json!({"path":"pkg/deep/main.rs"})).unwrap(),
        };
        memory
            .load_for_read(&mut request, &read_call, &failed, None, None)
            .unwrap();
        assert_eq!(request.ephemeral_contexts.len(), 1);
        let mut unverified_success = failed.clone();
        unverified_success.success = true;
        memory
            .load_for_read(&mut request, &read_call, &unverified_success, None, None)
            .unwrap();
        assert_eq!(
            request.ephemeral_contexts.len(),
            1,
            "a successful-looking result without the host-only opened-file identity must not load"
        );
        let mut structured_output_state = StructuredOutputTurnState::default();
        let mut tool_search_state = ToolSearchTurnState::default();
        let mut identities = ToolFileIdentities::default();
        let execution = execute_model_tool_with_turn_states(
            &request,
            read_call.clone(),
            &AppState::default(),
            &mut structured_output_state,
            &mut tool_search_state,
            &|_, _, _| panic!("full-access read must not prompt"),
            false,
            Some(&mut identities),
            None,
        );
        assert!(execution.result.success, "{}", execution.result.output);
        let opened_file = identities
            .opened_read_file
            .expect("read must return its verified canonical identity");
        assert_eq!(
            opened_file.as_path(),
            std::fs::canonicalize(workspace.path().join("pkg/deep/main.rs"))
                .unwrap()
                .as_path()
        );
        memory
            .load_for_read(
                &mut request,
                &execution.call,
                &execution.result,
                Some(&opened_file),
                None,
            )
            .unwrap();
        assert!(request.ephemeral_contexts.iter().any(|context| {
            matches!(
                context,
                ContextItem::User { content, .. } if content.contains("nested package instruction")
            )
        }));
        let loaded_contexts = request.ephemeral_contexts.len();
        memory
            .load_for_read(
                &mut request,
                &execution.call,
                &execution.result,
                Some(&opened_file),
                None,
            )
            .unwrap();
        assert_eq!(request.ephemeral_contexts.len(), loaded_contexts);

        let mut restarted = run_request(ProviderFamily::OpenaiResponses);
        restarted.workspace_path = request.workspace_path.clone();
        restarted.workspace_id = request.workspace_id.clone();
        restarted.app_data_path = request.app_data_path.clone();
        let mut restarted_memory = ProjectMemoryRunState::discover(&mut restarted, None)
            .unwrap()
            .expect("restarted project memory");
        assert!(restarted.ephemeral_contexts.iter().all(|context| {
            !matches!(
                context,
                ContextItem::User { content, .. } if content.contains("nested package instruction")
            )
        }));
        restarted_memory
            .load_for_read(
                &mut restarted,
                &execution.call,
                &execution.result,
                Some(&opened_file),
                None,
            )
            .unwrap();
        assert!(restarted.ephemeral_contexts.iter().any(|context| {
            matches!(
                context,
                ContextItem::User { content, .. } if content.contains("nested package instruction")
            )
        }));
    }

    fn structured_output_schema() -> crate::subagent_schema::Schema {
        crate::subagent_schema::compile(&json!({
            "type": "object",
            "properties": {"verdict": {"type": "string"}, "score": {"type": "integer"}},
            "required": ["verdict"],
            "additionalProperties": false
        }))
        .unwrap()
    }

    /// S8 assertion (h): the injected descriptor must never be reachable by the
    /// parent — not through the catalog, not through the parent's own
    /// `enabled_tools`, and not through the executor at depth 0.
    #[test]
    fn structured_output_is_child_only_and_absent_from_the_global_catalog() {
        assert!(!catalog::tool_catalog()
            .iter()
            .any(|tool| tool.name == STRUCTURED_OUTPUT_TOOL));

        let mut main = run_request(ProviderFamily::OpenaiResponses);
        assert!(!main
            .enabled_tools
            .iter()
            .any(|name| name == STRUCTURED_OUTPUT_TOOL));
        // Even a forged parent descriptor plus grant cannot execute it.
        main.tools.push(structured_output_descriptor(
            &main.prompt_profile,
            &structured_output_schema(),
        ));
        main.enabled_tools.push(STRUCTURED_OUTPUT_TOOL.into());
        main.output_schema = Some(structured_output_schema());
        let parent = execute_model_tool(
            &main,
            ToolCall {
                id: "call-main-structured".into(),
                name: STRUCTURED_OUTPUT_TOOL.into(),
                input: serde_json::from_value(json!({"verdict": "ok"})).unwrap(),
            },
            &AppState::default(),
            &approve_tool,
            false,
        );
        assert!(!parent.result.success);
        assert!(
            parent.result.output.contains(
                "The structured-result tool is only for a subagent returning this run's result"
            ),
            "{}",
            parent.result.output
        );

        // Manual execution and approval reject this name directly instead of
        // treating it as an unknown tool.
        let manual = security::classify(
            crate::model::SecurityLevel::FullAccess,
            std::path::Path::new("."),
            std::path::Path::new("."),
            &[],
            &ToolExecutionRequest {
                conversation_id: "c1".into(),
                workspace_path: ".".into(),
                tool_name: STRUCTURED_OUTPUT_TOOL.into(),
                input: serde_json::from_value(json!({"verdict": "ok"})).unwrap(),
            },
        )
        .expect_err("a replayed timeline entry must not be hand-run");
        assert!(
            manual.contains(
                "Orchestration tool structured_output may only be scheduled by the model run loop"
            ),
            "{manual}"
        );
    }

    /// S8 assertion (i): `classify_tool_authorization` runs for EVERY tool call
    /// before category dispatch, so a missing classification is a total child
    /// failure, not a per-call rejection.
    #[test]
    fn structured_output_has_an_auditable_classification_on_every_path() {
        let decision = security::classify_model_call(
            crate::model::SecurityLevel::RequestApproval,
            std::path::Path::new("."),
            std::path::Path::new("."),
            &[],
            &ToolExecutionRequest {
                conversation_id: "c1".into(),
                workspace_path: ".".into(),
                tool_name: STRUCTURED_OUTPUT_TOOL.into(),
                input: serde_json::from_value(json!({"verdict": "ok"})).unwrap(),
            },
        )
        .expect("a child-only tool still needs a decision");
        assert!(!decision.requires_approval);
        assert!(!decision.mandatory_prompt);

        let mut child = run_request(ProviderFamily::OpenaiResponses);
        child.subagent_depth = 1;
        child.output_schema = Some(structured_output_schema());
        child.tools.push(structured_output_descriptor(
            &child.prompt_profile,
            &structured_output_schema(),
        ));
        child.enabled_tools.push(STRUCTURED_OUTPUT_TOOL.into());
        classify_tool_authorization(
            &child,
            &ToolCall {
                id: "call-auth".into(),
                name: STRUCTURED_OUTPUT_TOOL.into(),
                input: serde_json::from_value(json!({"verdict": "ok"})).unwrap(),
            },
        )
        .expect("the run loop authorizes every call before dispatch");
    }

    /// The per-spawn schema reaches the provider through `input_schema`, the
    /// only channel that can express it — `ToolParameterType` has no object
    /// variant. Constraint keywords stay verbatim; the host adds only a root
    /// `description` (the run's finishing semantics) when the caller schema
    /// carries none, because the tool description seed is empty by design.
    #[test]
    fn the_spawn_schema_becomes_the_child_tools_wire_schema() {
        let schema = structured_output_schema();
        let profile = PromptProfile::builtin_english();
        let descriptor = structured_output_descriptor(&profile, &schema);
        assert!(descriptor.parameters.is_empty());
        assert_eq!(descriptor.description, "");
        let wire = tool_schema(
            &descriptor,
            &crate::prompt_profile::PromptProfile::builtin_english(),
            &crate::workspace_set::WorkspaceSet::default(),
        );
        let mut expected = schema.as_value().clone();
        expected["description"] = json!(format!(
            "{} {}",
            profile.text(PromptKey::SubagentStructuredOutputRootSeed),
            profile.text(PromptKey::SubagentStructuredOutputLifecycle)
        ));
        assert_eq!(wire, expected);
        // Every caller-authored keyword survives untouched.
        let mut wire_without_injection = wire.clone();
        wire_without_injection
            .as_object_mut()
            .unwrap()
            .remove("description");
        assert_eq!(wire_without_injection, *schema.as_value());
        assert_eq!(
            structured_output_descriptor(&profile, &schema).label,
            "Structured result"
        );
    }

    /// A text-only model must not be offered a tool whose whole point is an image. Before this
    /// gate the host would capture the screenshot, write the PNG, and only then replace the
    /// result with "this model cannot see images" — the side effect happened and the model
    /// learned nothing. Two whole tools now, not two variants of one.
    #[test]
    fn preview_tools_needing_vision_leave_a_text_only_models_request() {
        let mut request = run_request(ProviderFamily::Anthropic);
        request.tools = catalog::tool_catalog();
        request.enabled_tools = request.tools.iter().map(|tool| tool.name.clone()).collect();
        let advertised = |request: &RunModelRequest| -> Vec<String> {
            crate::aisdk::tools::enabled_tools(request)
                .into_iter()
                .map(|tool| tool.name.clone())
                .collect()
        };

        request
            .model
            .set_capability(crate::model::ModelCapability::ImageRecognition, true);
        let seeing = advertised(&request);
        assert!(seeing.iter().any(|name| name == "preview_screenshot"));
        assert!(seeing.iter().any(|name| name == "preview_upload_image"));

        request
            .model
            .set_capability(crate::model::ModelCapability::ImageRecognition, false);
        let text_only = advertised(&request);
        let removed: Vec<&String> = seeing
            .iter()
            .filter(|name| !text_only.contains(name))
            .collect();
        assert_eq!(removed, vec!["preview_screenshot", "preview_upload_image"]);
        // Everything else the preview surface can do is still offered.
        assert!(text_only.iter().any(|name| name == "preview_snapshot"));
        assert!(text_only.iter().any(|name| name == "preview_click"));

        // The static catalog schemas stay complete: they are the authoritative baseline, and both
        // tools keep their runtime dispatch and security policy.
        for name in ["preview_screenshot", "preview_upload_image"] {
            assert!(crate::builtin_schemas::builtin_tool_schema(
                name,
                &PromptProfile::builtin_english()
            )
            .is_some());
        }
    }

    /// The lifecycle text is a host contract and must also be supplied when callers
    /// provide a root schema description; post-commit side effects are rejected by
    /// this round's drain.
    #[test]
    fn the_lifecycle_clause_reaches_a_caller_authored_root_description() {
        let authored = "Return the audit verdict for the file under review.";
        let schema = crate::subagent_schema::compile(&json!({
            "type": "object",
            "description": authored,
            "properties": {"verdict": {"type": "string"}},
            "required": ["verdict"],
            "additionalProperties": false
        }))
        .unwrap();
        let profile = PromptProfile::builtin_english();
        let wire = tool_schema(
            &structured_output_descriptor(&profile, &schema),
            &profile,
            &crate::workspace_set::WorkspaceSet::default(),
        );
        let root = wire
            .get("description")
            .and_then(Value::as_str)
            .expect("the root description must survive as a string");
        assert!(
            root.starts_with(authored),
            "调用方原文必须逐字保留在最前：{root}"
        );
        assert!(
            root.ends_with(profile.text(PromptKey::SubagentStructuredOutputLifecycle)),
            "生命周期契约必须追加到自带根描述的 schema 上：{root}"
        );
        assert!(
            !root.contains(profile.text(PromptKey::SubagentStructuredOutputRootSeed)),
            "调用方写过根描述时不再补种子，只补契约：{root}"
        );
    }

    /// S8's ordering hazard: `AgentRunOverrides::apply` intersects
    /// `enabled_tools` and runs LAST, so injecting before it silently strips the
    /// one tool a named agent is required to call.
    #[test]
    fn structured_output_survives_a_named_agents_tool_allowlist() {
        let parent = run_request(ProviderFamily::OpenaiResponses);
        let mut template = agent_child_template(&parent);
        assert!(
            !template
                .enabled_tools
                .iter()
                .any(|name| name == STRUCTURED_OUTPUT_TOOL),
            "the child template must not carry it without a schema"
        );
        assert!(template.output_schema.is_none());
        // Model a definition whose allowlist mentions neither child-only tool.
        template.enabled_tools.retain(|name| name == "read");
        install_structured_output(&mut template, structured_output_schema()).unwrap();
        assert!(template
            .enabled_tools
            .iter()
            .any(|name| name == STRUCTURED_OUTPUT_TOOL));
        assert!(template
            .tools
            .iter()
            .any(|tool| tool.name == STRUCTURED_OUTPUT_TOOL));
        assert!(template.output_schema.is_some());
    }

    /// S8 assertions (d) and the counting rule behind it: only a REJECTED value
    /// burns an attempt, and the message says how many are left.
    #[test]
    fn a_rejected_structured_result_burns_one_attempt_and_a_valid_one_lands() {
        let mut child = run_request(ProviderFamily::OpenaiResponses);
        child.subagent_depth = 1;
        child.output_schema = Some(structured_output_schema());
        child.tools.push(structured_output_descriptor(
            &child.prompt_profile,
            &structured_output_schema(),
        ));
        child.enabled_tools.push(STRUCTURED_OUTPUT_TOOL.into());

        let mut structured_output_state = StructuredOutputTurnState::default();
        let mut tool_search_state = ToolSearchTurnState::default();
        let call = |input: Value,
                    state: &mut StructuredOutputTurnState,
                    search: &mut ToolSearchTurnState| {
            execute_model_tool_with_turn_states(
                &child,
                ToolCall {
                    id: "call-structured".into(),
                    name: STRUCTURED_OUTPUT_TOOL.into(),
                    input: serde_json::from_value(input).unwrap(),
                },
                &AppState::default(),
                state,
                search,
                &approve_tool,
                false,
                None,
                None,
            )
        };

        for attempt in 1..=MAX_STRUCTURED_OUTPUT_ATTEMPTS {
            let rejected = call(
                json!({"verdict": 1}),
                &mut structured_output_state,
                &mut tool_search_state,
            );
            assert!(!rejected.result.success);
            assert!(
                rejected.result.output.contains("/verdict"),
                "{}",
                rejected.result.output
            );
            assert!(
                rejected
                    .result
                    .output
                    .contains(&format!("Attempt {attempt} of")),
                "{}",
                rejected.result.output
            );
            assert_eq!(structured_output_state.attempts, attempt);
            assert_eq!(
                structured_output_state.exhausted(),
                attempt == MAX_STRUCTURED_OUTPUT_ATTEMPTS
            );
            assert!(structured_output_state.value.is_none());
        }
        assert_eq!(
            subagent_run_status(Some("structured_output_retry_limit")),
            SubagentRunStatus::Failed,
            "a run that never produced a valid value did not merely stop"
        );

        let mut fresh = StructuredOutputTurnState::default();
        let accepted = call(
            json!({"verdict": "ok", "score": 7}),
            &mut fresh,
            &mut tool_search_state,
        );
        assert!(accepted.result.success, "{}", accepted.result.output);
        assert_eq!(fresh.value, Some(json!({"verdict": "ok", "score": 7})));
        assert_eq!(fresh.attempts, 0, "a success must not burn an attempt");
        // An extra field is rejected by the schema, not silently accepted.
        let extra = call(
            json!({"verdict": "ok", "unexpected": true}),
            &mut fresh,
            &mut tool_search_state,
        );
        assert!(!extra.result.success, "{}", extra.result.output);
    }

    /// The persisted document is renderer-writable, so a schema read back from
    /// it re-runs the spawn-time precheck. A record whose schema no longer
    /// compiles refuses restoration — fail closed — rather than rehydrating an
    /// agent without the constraint the parent contracted for.
    #[test]
    fn a_forged_persisted_output_schema_refuses_restoration() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = serve_json_sequence(
            listener,
            vec![
                json!({
                    "model": "model-test",
                    "status": "completed",
                    "output": [
                        {"type":"function_call","status":"completed","call_id":"call-wait","name":"task_wait",
                            "arguments": json!({"tasks":["a9"]}).to_string()}
                    ],
                    "usage": {"input_tokens":1,"output_tokens":1,"total_tokens":2}
                }),
                responses_text_output("主代理完成"),
            ],
        );

        let workspace = tempfile::tempdir().unwrap();
        let mut request = loop_request_for(address, workspace.path());
        let state = AppState::default();
        reserve_subagent_execution_mode(
            &agent_child_template(&request),
            &state,
            "a9",
            SubagentRunKind::General,
        )
        .unwrap();
        let execution_mode_receipt = String::new();
        request.contexts.push(ContextItem::Tool {
            id: "ctx_old_spawn".into(),
            tool_name: "agent_spawn".into(),
            round: Some(1),
            model_turn_id: Some("old-spawn-turn".into()),
            provider_call_id: None,
            requested_input: None,
            input: serde_json::from_value(json!({"prompt":"历史任务","name":"a9"})).unwrap(),
            result: ToolResult {
                success: true,
                output: "子代理 a9 已派生".into(),
                images: Vec::new(),
                diff: None,
                executed_at: "2026-07-13T00:00:00Z".into(),
                duration_ms: 0,
            },
            subagent: Some(SubagentRunRecord {
                kind: SubagentRunKind::General,
                name: Some("a9".into()),
                label: None,
                inherits_model_memory: false,
                fork_model_binding: None,
                agent_definition: None,
                execution_mode_receipt,
                task: "历史任务".into(),
                status: SubagentRunStatus::Completed,
                contexts: Vec::new(),
                updates: Vec::new(),
                structured_output: None,
                // An unsupported keyword can only appear here through document
                // tampering: `parse_output_schema` rejected it at spawn time.
                output_schema: Some(json!({"type": "object", "zzz_probe": true})),
                usage: ModelUsage::default(),
            }),
            notice: None,
            attestation: String::new(),
            created_at: "2026-07-13T00:00:00Z".into(),
        });
        let response = run_model(request, &state, &discard_event, &approve_tool).unwrap();
        let captured = server.join().unwrap();

        assert_eq!(captured.len(), 2, "the child must never run");
        let wait = response
            .contexts
            .iter()
            .find_map(|context| match context {
                context @ ContextItem::Tool { tool_name, .. } if tool_name == "task_wait" => {
                    Some(context)
                }
                _ => None,
            })
            .expect("the refused wait still records its tool context");
        let ContextItem::Tool {
            result, subagent, ..
        } = wait
        else {
            unreachable!()
        };
        assert!(!result.success);
        assert!(
            result.output.contains("restoration was refused"),
            "{}",
            result.output
        );
        assert!(
            result.output.contains("zzz_probe"),
            "the refusal must name the offending keyword: {}",
            result.output
        );
        assert!(
            subagent.is_none(),
            "a refused rehydration must not overwrite the historical record"
        );
    }

    /// Startup-recovered failed runs deliver a host-synthesized `task_wait` card at
    /// the round boundary with resume guidance. The delivery slot is consumed once
    /// after `generated.checkpoint()`.
    #[test]
    fn fold_workflow_restart_notices_delivers_the_resume_handle_once() {
        let parent = run_request(ProviderFamily::OpenaiResponses);
        let state = AppState::default();
        state.seed_workflow_restart_notices(vec![crate::workflow_store::InterruptedRun {
            conversation_id: parent.conversation_id.clone(),
            run_id: "runabc".into(),
            script_name: "audit".into(),
            reusable_steps: 3,
            freshly_interrupted: true,
        }]);

        let mut request_contexts = Vec::new();
        let mut generated = Vec::new();
        let mut exchanges: Vec<Exchange> = Vec::new();
        let delivered = fold_workflow_restart_notices(
            &parent.prompt_profile,
            1,
            &parent.conversation_id,
            &state,
            &mut exchanges,
            &mut request_contexts,
            &mut generated,
        );
        assert_eq!(
            delivered,
            vec![(parent.conversation_id.clone(), "runabc".to_owned())]
        );
        assert_eq!(request_contexts.len(), 1);
        assert_eq!(generated.len(), 1);
        let ContextItem::Tool {
            tool_name,
            result,
            input,
            ..
        } = &generated[0]
        else {
            unreachable!("the restart notice must be a host box card")
        };
        assert_eq!(tool_name, BOX_TOOL);
        assert!(result.success);
        assert!(result.output.contains("[runabc]"), "{}", result.output);
        assert!(result.output.contains("resume_run_id"), "{}", result.output);
        assert!(
            result.output.contains("3 reusable step results"),
            "{}",
            result.output
        );
        // The card holds the whole message; the call carries only the empty argument.
        assert_eq!(input, &crate::wire_history::box_call_input());
        assert!(result.output.contains("<status>failed</status>"), "{}", result.output);
        assert!(
            result.output.contains("<task-id>workflow:runabc</task-id>"),
            "{}",
            result.output
        );

        // The delivery slot is one-shot and cannot deliver again at the next
        // round boundary.
        assert!(fold_workflow_restart_notices(
            &parent.prompt_profile,
            2,
            &parent.conversation_id,
            &state,
            &mut exchanges,
            &mut request_contexts,
            &mut generated,
        )
        .is_empty());
        assert_eq!(generated.len(), 1);
    }

    /// A subagent the previous process lost is reported once. One that died mid-work gets a failed
    /// task notification carrying the last text the history received from it — including a
    /// response no request ever carried anywhere. One whose final reply startup recovered is
    /// delivered as its completed result and wakes nothing. An agent whose result the history
    /// shows a request carrying to the model — folded, or waited on — is settled without a word. The
    /// timeline counts for nothing either way: a delivery card only the timeline holds does not
    /// stop the notice.
    #[test]
    fn fold_subagent_restart_notices_reports_a_lost_agent_once_and_skips_settled_ones() {
        let workspace = tempfile::tempdir().unwrap();
        let mut parent = run_request(ProviderFamily::OpenaiResponses);
        parent.app_data_path = workspace.path().to_string_lossy().into_owned();
        let state = AppState::default();
        record_history(
            &parent,
            None,
            &[json!({"role": "tool", "content": [
                {"type": "tool-result", "toolCallId": "call-fold", "toolName": BOX_TOOL,
                 "output": {"type": "text", "value":
                    "<task-notification>\n<task-id>folded</task-id>\n<status>completed</status>\n</task-notification>"}},
                {"type": "tool-result", "toolCallId": "call-wait", "toolName": "task_wait",
                 "output": {"type": "text", "value": "[waited · completed]\nall good"}}
            ]})],
        );
        // The reviewer's own requests only ever carried its first pass back to its model.
        record_history(
            &parent,
            Some("reviewer"),
            &[
                json!({"role": "user", "content": "审查"}),
                json!({"role": "assistant", "content": [
                    {"type": "text", "text": "first pass: the router looks fine"}
                ]}),
            ],
        );
        record_response(
            &parent,
            Some("reviewer"),
            None,
            1,
            "tool-calls",
            json!({"role": "assistant", "content": [
                {"type": "text", "text": "first pass: the router looks fine"},
                {"type": "tool-call", "toolCallId": "c0", "toolName": "read", "input": {"path": "router.rs"}}
            ]}),
        );
        // What it said next arrived, and the process died before any request carried it.
        record_response(
            &parent,
            Some("reviewer"),
            None,
            2,
            "tool-calls",
            json!({"role": "assistant", "content": [
                {"type": "text", "text": "partial finding: the retry loop never backs off"},
                {"type": "tool-call", "toolCallId": "c1", "toolName": "read", "input": {"path": "retry.rs"}}
            ]}),
        );
        // Only the timeline claims `silent` got its result; the history never carried it.
        let mut request_contexts = vec![ContextItem::Tool {
            id: "ctx_fold_silent".into(),
            tool_name: BOX_TOOL.into(),
            round: Some(1),
            model_turn_id: None,
            provider_call_id: None,
            requested_input: None,
            input: crate::wire_history::box_call_input(),
            result: ToolResult {
                success: true,
                output: crate::wire_history::task_notification(
                    "silent",
                    "completed",
                    "Background task silent completed",
                    "done",
                    None,
                ),
                images: Vec::new(),
                diff: None,
                executed_at: Utc::now().to_rfc3339(),
                duration_ms: 0,
            },
            subagent: None,
            notice: None,
            attestation: String::new(),
            created_at: Utc::now().to_rfc3339(),
        }];
        let lost = |name: &str| crate::subagent_ledger::LostSubagent {
            conversation_id: parent.conversation_id.clone(),
            name: name.into(),
            spawn_call_id: None,
            record: None,
            recovered: None,
        };
        let finished = crate::subagent_ledger::LostSubagent {
            recovered: Some(crate::subagent_ledger::RecoveredReply {
                request_id: "req-finisher".into(),
                round: 2,
                text: "final report: nothing to fix".into(),
                structured_output: Some(json!({"verdict": "clean"})),
            }),
            ..lost("finisher")
        };
        // A conversation whose only lost agent finished is not woken for it.
        state.seed_subagent_restart_notices(vec![finished.clone()]);
        assert!(!state
            .conversations_with_restart_notices()
            .contains(&parent.conversation_id));
        state.seed_subagent_restart_notices(vec![
            lost("reviewer"),
            lost("silent"),
            lost("folded"),
            lost("waited"),
        ]);
        assert!(state
            .conversations_with_restart_notices()
            .contains(&parent.conversation_id));

        let mut generated = Vec::new();
        let mut exchanges: Vec<Exchange> = Vec::new();
        let settled = fold_subagent_restart_notices(
            &parent.prompt_profile,
            3,
            &parent.conversation_id,
            &parent.app_data_path,
            &state,
            &mut exchanges,
            &mut request_contexts,
            &mut generated,
        );
        assert_eq!(
            settled,
            vec!["finisher", "reviewer", "silent", "folded", "waited"]
        );
        assert_eq!(generated.len(), 3, "只有账本里没有交付的三个代理需要投递");
        let notices = generated
            .iter()
            .map(|card| {
                let ContextItem::Tool {
                    tool_name,
                    input,
                    result,
                    ..
                } = card
                else {
                    unreachable!("the restart notice must be a host box card")
                };
                assert_eq!(tool_name, BOX_TOOL);
                assert_eq!(input, &crate::wire_history::box_call_input());
                result.output.clone()
            })
            .collect::<Vec<_>>();
        let finisher_output = &notices[0];
        assert!(
            finisher_output.contains("<task-id>finisher</task-id>"),
            "{finisher_output}"
        );
        assert!(
            finisher_output.contains("<status>completed</status>"),
            "{finisher_output}"
        );
        assert!(
            finisher_output.contains("<result>\n[finisher · "),
            "找回的最终回复按完成结果投递：{finisher_output}"
        );
        assert!(
            finisher_output.contains("final report: nothing to fix"),
            "{finisher_output}"
        );
        assert!(
            finisher_output.contains("clean"),
            "结构化结果随之投递：{finisher_output}"
        );
        let reviewer_output = &notices[1];
        assert!(
            reviewer_output.contains("<task-id>reviewer</task-id>"),
            "{reviewer_output}"
        );
        assert!(
            reviewer_output.contains("<status>failed</status>"),
            "{reviewer_output}"
        );
        assert!(
            reviewer_output.contains("partial finding: the retry loop never backs off"),
            "最后一段正文取自响应账本，哪怕没有请求带过它：{reviewer_output}"
        );
        assert!(!reviewer_output.contains("first pass"), "{reviewer_output}");
        assert!(reviewer_output.contains("new name"), "{reviewer_output}");
        let silent_output = &notices[2];
        assert!(
            silent_output.contains("<task-id>silent</task-id>"),
            "{silent_output}"
        );
        assert!(
            silent_output.contains(PromptKey::TaskRestartNoOutput.builtin_en()),
            "{silent_output}"
        );
        assert!(!state
            .conversations_with_restart_notices()
            .contains(&parent.conversation_id));

        // The queue is one-shot: the next boundary delivers nothing again.
        assert!(fold_subagent_restart_notices(
            &parent.prompt_profile,
            4,
            &parent.conversation_id,
            &parent.app_data_path,
            &state,
            &mut exchanges,
            &mut request_contexts,
            &mut generated,
        )
        .is_empty());
        assert_eq!(generated.len(), 3);

        // Once a delivery has gone out in a request, a startup that claims the same entry again
        // (the process died before settling it) finds it and stays quiet.
        record_history(
            &parent,
            None,
            &[json!({"role": "tool", "content": [
                {"type": "tool-result", "toolCallId": "call-notice", "toolName": BOX_TOOL,
                 "output": {"type": "text", "value": "<task-notification>\n<task-id>reviewer</task-id>\n<status>failed</status>\n</task-notification>"}},
                {"type": "tool-result", "toolCallId": "call-finisher", "toolName": BOX_TOOL,
                 "output": {"type": "text", "value": "<task-notification>\n<task-id>finisher</task-id>\n<status>completed</status>\n</task-notification>"}}
            ]})],
        );
        state.seed_subagent_restart_notices(vec![lost("reviewer"), finished]);
        assert_eq!(
            fold_subagent_restart_notices(
                &parent.prompt_profile,
                5,
                &parent.conversation_id,
                &parent.app_data_path,
                &state,
                &mut exchanges,
                &mut request_contexts,
                &mut generated,
            ),
            vec!["reviewer", "finisher"]
        );
        assert_eq!(generated.len(), 3, "已送达的投递不再重发");
    }

    /// The history decides whether a lost agent had finished: its last response ended the run —
    /// no calls, not paused, not cut off, nothing after it that took the agent further — or, bound
    /// to a schema, carried a value the schema accepts. The recovered text is the whole final
    /// round's.
    #[test]
    fn recover_final_reply_reads_the_history() {
        use crate::subagent_ledger::{recover_final_reply, LostSubagent};
        let workspace = tempfile::tempdir().unwrap();
        let mut parent = run_request(ProviderFamily::OpenaiResponses);
        parent.app_data_path = workspace.path().to_string_lossy().into_owned();
        let store = crate::history::history_store(&parent.app_data_path).unwrap();
        let lost = |name: &str| LostSubagent {
            conversation_id: parent.conversation_id.clone(),
            name: name.into(),
            spawn_call_id: None,
            record: None,
            recovered: None,
        };
        let text =
            |text: &str| json!({"role": "assistant", "content": [{"type": "text", "text": text}]});
        let working = json!({"role": "assistant", "content": [
            {"type": "text", "text": "looking"},
            {"type": "tool-call", "toolCallId": "c1", "toolName": "read", "input": {"path": "a.rs"}}
        ]});
        let paused = json!({"attempt": 1, "finishReason": "stop", "rawFinishReason": "pause_turn"});

        // Nothing received: nothing to recover.
        assert_eq!(recover_final_reply(&store, &lost("mute")), None);

        // A plain final reply; the round's paused steps are joined the way the host joins them.
        record_response(
            &parent,
            Some("done"),
            None,
            1,
            "tool-calls",
            working.clone(),
        );
        record_response_with(&parent, Some("done"), None, 2, paused.clone(), text("part one"));
        record_response(&parent, Some("done"), None, 2, "stop", text("part two"));
        let recovered = recover_final_reply(&store, &lost("done")).expect("最终回复可以找回");
        assert_eq!(recovered.text, "part one\npart two");
        assert_eq!(recovered.round, 2);
        assert_eq!(recovered.request_id, "req-history");
        assert_eq!(recovered.structured_output, None);

        // Still working, paused, or cut off: not a final reply.
        record_response(
            &parent,
            Some("busy"),
            None,
            1,
            "tool-calls",
            working.clone(),
        );
        assert_eq!(recover_final_reply(&store, &lost("busy")), None);
        record_response_with(&parent, Some("paused"), None, 2, paused, text("part one"));
        assert_eq!(recover_final_reply(&store, &lost("paused")), None);
        record_response(&parent, Some("cut"), None, 1, "length", text("half a sent"));
        assert_eq!(recover_final_reply(&store, &lost("cut")), None);

        // A reply the host went on past is not the final one: another request of the same agent
        // after it — a nudge, a continuation — says so.
        let answered = record_history(
            &parent,
            Some("nudged"),
            &[json!({"role": "user", "content": "go"})],
        );
        record_response(
            &parent,
            Some("nudged"),
            Some(answered),
            1,
            "stop",
            text("done?"),
        );
        assert!(recover_final_reply(&store, &lost("nudged")).is_some());
        record_history(
            &parent,
            Some("nudged"),
            &[json!({"role": "user", "content": "not yet"})],
        );
        assert_eq!(recover_final_reply(&store, &lost("nudged")), None);

        // So does a `Stop` hook that blocked the stop, even when the process died before the
        // continuation it asked for left: the decision is on disk before the host acts on it.
        record_response(&parent, Some("hooked"), None, 1, "stop", text("done?"));
        record_stop_hook(&parent, Some("hooked"), 1, false, false);
        assert!(
            recover_final_reply(&store, &lost("hooked")).is_some(),
            "放行的 Stop 钩子不改变结局"
        );
        record_stop_hook(&parent, Some("hooked"), 1, true, false);
        assert_eq!(
            recover_final_reply(&store, &lost("hooked")),
            None,
            "拦下停止的 Stop 钩子把代理送回去继续干活"
        );

        // A hook that halted ends the run on the reply, whatever another hook asked for.
        record_response(&parent, Some("halted"), None, 1, "stop", text("stop here"));
        record_stop_hook(&parent, Some("halted"), 1, true, false);
        record_stop_hook(&parent, Some("halted"), 1, true, true);
        assert!(recover_final_reply(&store, &lost("halted")).is_some());

        // Past the continuations a run is granted, the host ends it instead of continuing.
        for round in 1..=3 {
            record_response(
                &parent,
                Some("spent"),
                None,
                round,
                "stop",
                text(&format!("try {round}")),
            );
            record_stop_hook(&parent, Some("spent"), round, true, false);
            record_history(
                &parent,
                Some("spent"),
                &[json!({"role": "user", "content": "keep going"})],
            );
        }
        record_response(&parent, Some("spent"), None, 4, "stop", text("try 4"));
        record_stop_hook(&parent, Some("spent"), 4, true, false);
        assert_eq!(
            recover_final_reply(&store, &lost("spent")).map(|reply| reply.text),
            Some("try 4".to_owned()),
            "续跑次数用完之后，宿主就在这条回复上结束"
        );

        // Bound to a schema: the round's accepted `structured_output` value is the result.
        let schema = json!({
            "type": "object",
            "properties": {"verdict": {"type": "string"}},
            "required": ["verdict"],
            "additionalProperties": false
        });
        let mut bound_record: crate::model::SubagentRunRecord = serde_json::from_value(json!({
            "name": "bound",
            "task": "judge",
            "status": "interrupted",
            "contexts": [],
            "updates": [],
        }))
        .unwrap();
        bound_record.output_schema = Some(schema);
        let bound = LostSubagent {
            record: Some(bound_record),
            ..lost("bound")
        };
        record_response(
            &parent,
            Some("bound"),
            None,
            1,
            "tool-calls",
            json!({"role": "assistant", "content": [
                {"type": "text", "text": "judged"},
                {"type": "tool-call", "toolCallId": "s1", "toolName": "structured_output", "input": {"verdict": 3}}
            ]}),
        );
        assert_eq!(
            recover_final_reply(&store, &bound),
            None,
            "未通过 schema 的值不算结果"
        );
        record_response(
            &parent,
            Some("bound"),
            None,
            2,
            "tool-calls",
            json!({"role": "assistant", "content": [
                {"type": "text", "text": "judged again"},
                {"type": "tool-call", "toolCallId": "s2", "toolName": "structured_output", "input": {"verdict": "clean"}}
            ]}),
        );
        let recovered = recover_final_reply(&store, &bound).expect("结构化结果可以找回");
        assert_eq!(
            recovered.structured_output,
            Some(json!({"verdict": "clean"}))
        );
        assert_eq!(recovered.text, "judged again");
    }

    /// Startup puts a recovered reply back on the agent's card: the record it already has, or —
    /// for a child that settled before any record was written — the one its spawn left in the
    /// ledger entry, written onto the spawn card. The record reads completed, holds the reply
    /// once however often startup repeats, and is re-signed.
    #[test]
    fn a_recovered_reply_is_reattached_to_the_agent_card() {
        use crate::subagent_ledger::{LostSubagent, RecoveredReply};
        let workspace = tempfile::tempdir().unwrap();
        let mut parent = run_request(ProviderFamily::OpenaiResponses);
        parent.app_data_path = workspace.path().to_string_lossy().into_owned();
        let state = AppState::default();
        let spawn_card =
            |id: &str,
             name: &str,
             call: &str,
             subagent: Option<crate::model::SubagentRunRecord>| ContextItem::Tool {
                id: id.into(),
                tool_name: "agent_spawn".into(),
                round: Some(1),
                model_turn_id: None,
                provider_call_id: Some(call.into()),
                requested_input: None,
                input: json!({"name": name, "task": "review"})
                    .as_object()
                    .unwrap()
                    .clone(),
                result: ToolResult {
                    success: true,
                    output: "ok".into(),
                    images: Vec::new(),
                    diff: None,
                    executed_at: Utc::now().to_rfc3339(),
                    duration_ms: 0,
                },
                subagent,
                notice: None,
                attestation: String::new(),
                created_at: Utc::now().to_rfc3339(),
            };
        let record = |name: &str, contexts: Vec<ContextItem>| -> crate::model::SubagentRunRecord {
            let mut record: crate::model::SubagentRunRecord = serde_json::from_value(json!({
                "name": name,
                "task": "review",
                "status": "interrupted",
                "contexts": [],
                "updates": [],
            }))
            .unwrap();
            record.execution_mode_receipt = "receipt".into();
            record.contexts = contexts;
            record
        };
        let first_round = ContextItem::Assistant {
            id: "ctx_round_one".into(),
            content: "looking".into(),
            round: Some(1),
            model_turn_id: None,
            interrupted: false,
            sources: Vec::new(),
            created_at: Utc::now().to_rfc3339(),
        };
        parent.contexts = vec![
            spawn_card("ctx_spawn_quick", "quick", "call-quick", None),
            spawn_card(
                "ctx_spawn_slow",
                "slow",
                "call-slow",
                Some(record("slow", vec![first_round.clone()])),
            ),
        ];
        let store = persisted_conversation_for(&parent);
        let reply = |round: usize, text: &str| RecoveredReply {
            request_id: "req-child".into(),
            round,
            text: text.into(),
            structured_output: None,
        };
        let quick = LostSubagent {
            conversation_id: parent.conversation_id.clone(),
            name: "quick".into(),
            spawn_call_id: Some("call-quick".into()),
            record: Some(record("quick", Vec::new())),
            recovered: Some(reply(1, "quick answer")),
        };
        let slow = LostSubagent {
            conversation_id: parent.conversation_id.clone(),
            name: "slow".into(),
            spawn_call_id: Some("call-slow".into()),
            record: Some(record("slow", Vec::new())),
            recovered: Some(reply(2, "slow answer")),
        };
        for _ in 0..2 {
            assert!(reattach_recovered_subagent(&store, &state, &quick));
            assert!(reattach_recovered_subagent(&store, &state, &slow));
        }
        let reply_id = |round| round_identity("req-child", round, "assistant").unwrap();
        let contexts = store
            .conversation(&parent.conversation_id)
            .unwrap()
            .unwrap()
            .contexts;
        let held = |id: &str| {
            let Some(ContextItem::Tool {
                subagent: Some(record),
                attestation,
                ..
            }) = contexts.iter().find(|context| context.id() == id)
            else {
                panic!("{id} 必须带着记录");
            };
            assert!(!attestation.is_empty(), "写回的记录重新签名");
            record.clone()
        };
        let quick_record = held("ctx_spawn_quick");
        assert_eq!(quick_record.status, SubagentRunStatus::Completed);
        assert_eq!(
            quick_record.execution_mode_receipt, "receipt",
            "从账目里的骨架写出记录"
        );
        assert_eq!(quick_record.contexts.len(), 1, "重复启动也只接回一次");
        assert_eq!(quick_record.contexts[0].id(), reply_id(1));
        let slow_record = held("ctx_spawn_slow");
        assert_eq!(slow_record.status, SubagentRunStatus::Completed);
        assert_eq!(
            slow_record
                .contexts
                .iter()
                .map(ContextItem::id)
                .collect::<Vec<_>>(),
            vec!["ctx_round_one".to_owned(), reply_id(2)],
            "已有的转录保留，最终回复接在后面"
        );
        let ContextItem::Assistant { content, .. } = &slow_record.contexts[1] else {
            unreachable!()
        };
        assert_eq!(content, "slow answer");
    }

    /// A progress update section in a `task_wait` output is not the agent's result, and neither
    /// is another agent's section whose name merely starts the same way.
    #[test]
    fn a_progress_update_in_task_wait_output_is_not_a_delivered_result() {
        let workspace = tempfile::tempdir().unwrap();
        let mut request = run_request(ProviderFamily::OpenaiResponses);
        request.app_data_path = workspace.path().to_string_lossy().into_owned();
        let profile = request.prompt_profile.clone();
        let wait = |output: String| {
            json!({"role": "tool", "content": [
                {"type": "tool-result", "toolCallId": "call-wait", "toolName": "task_wait",
                 "output": {"type": "text", "value": output}}
            ]})
        };
        record_history(
            &request,
            None,
            &[
                wait(format!(
                    "[helper · {}]\nhalfway",
                    profile.text(PromptKey::TaskProgressUpdateLabel)
                )),
                wait("[helper-two · completed]\ndone".into()),
            ],
        );
        let store = crate::history::history_store(&request.app_data_path).unwrap();
        assert!(!agent_result_reached_model(
            &store,
            &request.conversation_id,
            "helper",
            &profile
        ));
        record_history(&request, None, &[wait("[helper · failed]\nboom".into())]);
        assert!(agent_result_reached_model(
            &store,
            &request.conversation_id,
            "helper",
            &profile
        ));
    }

    /// S9 unit seam: one delivery per undrained terminal result, identical in
    /// both sinks, carrying the S4 cost footer and the S8 structured block
    /// under the distinguishing id prefix — and the claim is one-shot.
    /// Host-generated `task_wait` tool contexts are not user contexts.
    #[test]
    fn fold_undrained_agent_results_delivers_once_into_both_sinks() {
        let parent = run_request(ProviderFamily::OpenaiResponses);
        let state = AppState::default();
        let pool = AgentPool::new();
        let template = agent_child_template(&parent);
        let shared = pool
            .register(
                "a1".into(),
                "a1".into(),
                "后台审查".into(),
                template,
                SubagentRunKind::General,
                &state,
                Vec::new(),
                Vec::new(),
                AgentLiveStatus::Running,
                "call-spawn".into(),
                None,
            )
            .unwrap();
        shared.complete_turn(
            shared.identity(),
            Vec::new(),
            "审查完成".into(),
            AgentLiveStatus::Idle,
            &ModelUsage {
                total_tokens: Some(321),
                ..Default::default()
            },
            450,
            Some(json!({"verdict": "ok"})),
        );

        let mut request_contexts = Vec::new();
        let mut generated = Vec::new();
        let mut exchanges: Vec<Exchange> = Vec::new();
        let shadow = crate::kernel_shadow::KernelShadow::new(agents::MAX_LIVE_AGENTS);
        fold_undrained_agent_results(
            &pool,
            &shadow,
            &discard_event,
            1,
            &parent.conversation_id,
            &state,
            &parent.prompt_profile,
            &mut exchanges,
            &mut request_contexts,
            &mut generated,
        );
        assert_eq!(request_contexts.len(), 1);
        assert_eq!(generated.len(), 1);
        // Background results retain their proper tool-context role in the timeline.
        let ContextItem::Tool {
            id,
            tool_name,
            result,
            round,
            model_turn_id,
            requested_input,
            subagent,
            attestation,
            input,
            ..
        } = &generated[0]
        else {
            panic!("the delivery must be a synthesized tool context");
        };
        assert_eq!(tool_name, BOX_TOOL);
        assert!(id.starts_with("ctx_agent-result_"), "{id}");
        assert!(matches!(
            &request_contexts[0],
            ContextItem::Tool { id: context_id, .. } if context_id == id
        ));
        assert!(result.success, "collecting the result itself succeeded");
        assert_eq!(*round, Some(1));
        assert!(model_turn_id.is_none());
        assert!(requested_input.is_none());
        assert!(
            subagent.is_none(),
            "a delivery never carries a child record"
        );
        // The host attests its own card; an empty token is treated as a forged
        // renderer card during persistence.
        assert!(!attestation.is_empty(), "the host must attest its own card");
        // The card is the exchange the model reads: the one empty argument,
        // and the whole notification as the result — no bookkeeping in `input`.
        assert_eq!(input, &crate::wire_history::box_call_input());
        let content = &result.output;
        assert!(
            content.starts_with("<task-notification>\n<task-id>a1</task-id>\n<status>completed</status>\n"),
            "{content}"
        );
        assert!(
            content.contains(&format!(
                "<result>\n[a1 · {}]",
                PromptKey::TaskStatusCompleted.builtin_en()
            )),
            "the body is the bare result envelope: {content}"
        );
        assert!(
            content.contains("<usage>\n<subagent_tokens>321</subagent_tokens>\n<tool_uses>0</tool_uses>\n<duration_ms>450</duration_ms>\n</usage>"),
            "{content}"
        );
        assert_eq!(
            crate::wire_history::host_task_notification(&generated[0]).as_ref(),
            Some(content)
        );
        assert!(!content.contains("宿主自动送达"), "{content}");
        assert!(content.contains("审查完成"), "{content}");
        assert!(
            content.contains(
                PromptKey::SubagentStructuredResultBlock
                    .builtin_en()
                    .split("{body}")
                    .next()
                    .unwrap()
            ),
            "{content}"
        );
        assert!(content.contains("\"verdict\""), "{content}");
        // Usage is structured, so each value occurs only once in `<usage>`.
        assert!(!content.contains("本轮开销"), "{content}");
        let notification = crate::wire_history::host_task_notification(&generated[0])
            .expect("a host delivery card renders as a task notification");
        assert!(
            notification.starts_with("<task-notification>\n"),
            "{notification}"
        );
        assert!(
            !notification.contains("<system-reminder>"),
            "upstream ships the notification bare: {notification}"
        );
        // The carrier is a tool result now, so nothing has to deny being the user.
        assert!(
            !notification.contains("SYSTEM NOTIFICATION"),
            "{notification}"
        );
        assert!(
            notification.contains("<task-id>a1</task-id>"),
            "{notification}"
        );
        assert!(
            notification.contains("<status>completed</status>"),
            "{notification}"
        );
        assert!(
            notification.contains("<subagent_tokens>321</subagent_tokens>"),
            "{notification}"
        );
        assert!(
            notification.contains("<duration_ms>450</duration_ms>"),
            "{notification}"
        );
        assert!(notification.contains("审查完成"), "{notification}");

        // One-shot: a second fold delivers nothing more.
        fold_undrained_agent_results(
            &pool,
            &shadow,
            &discard_event,
            1,
            &parent.conversation_id,
            &state,
            &parent.prompt_profile,
            &mut exchanges,
            &mut request_contexts,
            &mut generated,
        );
        assert_eq!(generated.len(), 1);
    }

    /// When real tool results are pending, delivery shares their exchange rather than
    /// entering `request.contexts`, preventing duplicate canonical-history delivery.
    #[test]
    fn a_fold_rides_the_tool_results_the_round_still_owes_the_model() {
        let parent = run_request(ProviderFamily::OpenaiResponses);
        let state = AppState::default();
        let pool = AgentPool::new();
        let template = agent_child_template(&parent);
        let shared = pool
            .register(
                "a1".into(),
                "a1".into(),
                "后台审查".into(),
                template,
                SubagentRunKind::General,
                &state,
                Vec::new(),
                Vec::new(),
                AgentLiveStatus::Running,
                "call-spawn".into(),
                None,
            )
            .unwrap();
        shared.complete_turn(
            shared.identity(),
            Vec::new(),
            "审查完成".into(),
            AgentLiveStatus::Idle,
            &ModelUsage::default(),
            0,
            None,
        );

        let mut exchanges = vec![
            // A pause_turn continuation owes the model nothing, so it is not a
            // carrier; the batch of real results behind it is.
            Exchange::new(json!([]), Vec::new()),
            Exchange::new(
                json!([]),
                vec![ToolExecution {
                    call: ToolCall {
                        id: "call-read".into(),
                        name: "read_file".into(),
                        input: JsonObject::new(),
                    },
                    result: ToolResult {
                        success: true,
                        output: "文件内容".into(),
                        images: Vec::new(),
                        diff: None,
                        executed_at: Utc::now().to_rfc3339(),
                        duration_ms: 1,
                    },
                    subagent: None,
                }],
            ),
        ];
        let mut request_contexts = Vec::new();
        let mut generated = Vec::new();
        let shadow = crate::kernel_shadow::KernelShadow::new(agents::MAX_LIVE_AGENTS);
        fold_undrained_agent_results(
            &pool,
            &shadow,
            &discard_event,
            2,
            &parent.conversation_id,
            &state,
            &parent.prompt_profile,
            &mut exchanges,
            &mut request_contexts,
            &mut generated,
        );

        assert!(
            request_contexts.is_empty(),
            "a delivery that rode along must not also reach the model through history"
        );
        assert_eq!(generated.len(), 1, "the durable card is minted either way");
        assert!(
            exchanges[0].host_deliveries.is_empty(),
            "a continuation-only exchange is no carrier"
        );
        assert_eq!(exchanges[1].host_deliveries.len(), 1);
        let delivery = &exchanges[1].host_deliveries[0];
        assert_eq!(
            Some(delivery.clone()),
            crate::wire_history::host_task_delivery(&generated[0]),
            "the ride and the persisted card must render the same bytes and the same call id"
        );
        let notice = &delivery.body;
        assert!(notice.contains("<task-id>a1</task-id>"), "{notice}");
        // Omit the entire `<usage>` block when metrics are unavailable.
        assert!(!notice.contains("<usage>"), "{notice}");
    }

    /// A user-stopped task result is delivered like any other: the fold mints the
    /// host-synthesized card carrying whatever the task produced before it stopped.
    #[test]
    fn fold_delivers_stopped_results_like_any_other() {
        let parent = run_request(ProviderFamily::OpenaiResponses);
        let state = AppState::default();
        let pool = AgentPool::new();
        let template = agent_child_template(&parent);
        let shared = pool
            .register(
                "a1".into(),
                "a1".into(),
                "后台审查".into(),
                template,
                SubagentRunKind::General,
                &state,
                Vec::new(),
                Vec::new(),
                AgentLiveStatus::Running,
                "call-spawn".into(),
                None,
            )
            .unwrap();
        shared.complete_turn(
            shared.identity(),
            Vec::new(),
            "被用户停止前的部分输出".into(),
            AgentLiveStatus::Stopped,
            &ModelUsage::default(),
            10,
            None,
        );

        let mut request_contexts = Vec::new();
        let mut generated = Vec::new();
        let shadow = crate::kernel_shadow::KernelShadow::new(agents::MAX_LIVE_AGENTS);
        fold_undrained_agent_results(
            &pool,
            &shadow,
            &discard_event,
            1,
            &parent.conversation_id,
            &state,
            &parent.prompt_profile,
            &mut Vec::new(),
            &mut request_contexts,
            &mut generated,
        );
        assert_eq!(generated.len(), 1, "停止结果必须进时间线通知");
        assert_eq!(request_contexts.len(), 1, "{request_contexts:?}");
        let notice = crate::wire_history::host_task_notification(&generated[0])
            .expect("宿主卡必须能投影成通知");
        assert!(notice.contains("<status>stopped</status>"), "{notice}");
        assert!(notice.contains("被用户停止前的部分输出"), "{notice}");
        // Claiming is one-shot: the delivered envelope cannot survive to another fold.
        assert!(pool.take_undelivered_results().is_empty());
        // The persistent record retains its terminal status and transcript for
        // `task_list` and `task_wait`.
        assert_eq!(shared.record().status, SubagentRunStatus::Stopped);
    }

    /// `stop_conversation_task` maps task cancellation to `Interrupted`; that envelope
    /// is claimed once and delivered, so the model learns the task was closed.
