        shared.complete_turn(
            shared.identity(),
            Vec::new(),
            "（子代理运行被中断）".into(),
            AgentLiveStatus::Interrupted,
            &ModelUsage::default(),
            10,
            None,
        );

        let mut request_contexts = Vec::new();
        let mut generated = Vec::new();
