    /// A cancellation signaled by the probe sink must propagate as `Cancelled`, not
    /// as a tool failure that would start a further model request during settlement.
    #[test]
    fn web_search_maps_a_tripped_probe_to_a_stopped_outcome() {
        let app_data = tempfile::tempdir().unwrap();
        let mut parent = run_request(ProviderFamily::OpenaiResponses);
        parent.app_data_path = app_data.path().to_string_lossy().into_owned();
        parent.tools = catalog::tool_catalog();
        parent.enabled_tools = parent.tools.iter().map(|tool| tool.name.clone()).collect();
        // Nothing listens on port 1. The retry probe observes the same tripped
        // cancellation flag as the connection failure path.
        parent.provider.base_url = "http://127.0.0.1:1/v1".into();
        parent.web_search = crate::model::WebSearchSettings {
            max_searches_per_call: 0,
            backend: Some(SearchBackend::Native),
            ..Default::default()
        };
        let sink = |_event: ModelStreamEvent| -> Result<(), String> {
            Err("联网搜索 web_search:search-1 已被用户停止".into())
        };
        let outcome = run_prepared_web_search_for_test(&parent, "核对来源 A", &sink, 7);
        assert!(
            matches!(outcome, Err(AsyncToolError::Cancelled)),
            "探针报错必须映射成 Cancelled"
        );
    }

    /// Host-executed collection polls the probe every 500 ms and maps cancellation to
    /// `Cancelled` while I/O remains pending.
    #[test]
    fn a_host_executed_search_maps_a_tripped_probe_to_a_stopped_outcome_too() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = thread::spawn(move || {
            // Accept the connection but send no response, leaving the worker in
            // a read so the probe runs.
            if let Ok((stream, _)) = listener.accept() {
                thread::sleep(Duration::from_secs(3));
                drop(stream);
            }
        });

        let app_data = tempfile::tempdir().unwrap();
        let mut parent = run_request(ProviderFamily::OpenaiResponses);
        parent.app_data_path = app_data.path().to_string_lossy().into_owned();
        parent.tools = catalog::tool_catalog();
        parent.enabled_tools = parent.tools.iter().map(|tool| tool.name.clone()).collect();
        parent.web_search = crate::model::WebSearchSettings {
            max_searches_per_call: 0,
            // Firecrawl permits anonymous access, and the loopback address passes
            // HTTP endpoint validation.
            backend: Some(SearchBackend::Provider(
                crate::model::ResolvedSearchProvider {
                    kind: crate::model::SearchProviderKind::Firecrawl,
                    api_host: format!("http://{address}"),
                    engines: Vec::new(),
                    basic_auth_username: String::new(),
                },
            )),
            ..Default::default()
        };
        let sink = |_event: ModelStreamEvent| -> Result<(), String> {
            Err("联网搜索 web_search:search-1 已被用户停止".into())
        };
        let outcome = run_prepared_web_search_for_test(&parent, "核对来源 A", &sink, 7);
        assert!(
            matches!(outcome, Err(AsyncToolError::Cancelled)),
            "探针报错必须映射成 Cancelled"
        );
        let _ = server.join();
    }

    /// The catalog-provider path performs host HTTP, normalizes and blacklists results,
    /// truncates to budget, then returns an untrusted envelope without touching credentials.
    #[test]
    fn a_catalog_provider_search_returns_normalized_results_through_the_untrusted_envelope() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = thread::spawn(move || {
            let (mut stream, _) = listener.accept().unwrap();
            let request = read_http_request_with_body(&mut stream);
            write_json_response(
                &mut stream,
                "200 OK",
                &json!({
                    "success": true,
                    "data": { "web": [
                        {
                            "title": "Kept",
                            "markdown": "K".repeat(4_000),
                            "url": "https://kept.example/a"
                        },
                        {
                            "title": "Blocked",
                            "markdown": "advert",
                            "url": "https://ads.example/x"
                        }
                    ]}
                }),
            );
            request
        });

        let app_data = tempfile::tempdir().unwrap();
        let mut parent = run_request(ProviderFamily::OpenaiResponses);
        parent.app_data_path = app_data.path().to_string_lossy().into_owned();
        parent.tools = catalog::tool_catalog();
        parent.enabled_tools = parent.tools.iter().map(|tool| tool.name.clone()).collect();
        parent.web_search = crate::model::WebSearchSettings {
            max_searches_per_call: 0,
            backend: Some(SearchBackend::Provider(
                crate::model::ResolvedSearchProvider {
                    kind: crate::model::SearchProviderKind::Firecrawl,
                    api_host: format!("http://{address}"),
                    engines: Vec::new(),
                    basic_auth_username: String::new(),
                },
            )),
            execution: crate::model::SearchExecutionConfig {
                max_results: 5,
                compression_cutoff: 100,
                domain_filter: crate::model::SearchDomainFilterMode::Exclude,
                include_domains: Vec::new(),
                exclude_domains: vec!["*://ads.example/*".into()],
            },
            ..Default::default()
        };
        let output =
            run_prepared_web_search_for_test(&parent, "mework release notes", &discard_event, 1)
                .expect("检索应成功");
        let request = server.join().unwrap();

        assert!(request.starts_with("POST /v2/search "), "{request}");
        assert!(request.contains("mework release notes"), "{request}");

        let output: Value = serde_json::from_str(&output).expect("结果是 JSON");
        assert_eq!(output["untrustedWebContent"], true);
        let results = output["results"].as_array().expect("results 是数组");
        assert_eq!(results.len(), 1);
        assert_eq!(results[0]["url"], "https://kept.example/a");
        assert!(
            results[0]["id"]
                .as_str()
                .is_some_and(|id| id.ends_with("-1")),
            "每条结果要带一个可被 [cite:id] 回指的 id：{}",
            results[0]
        );
        let content = results[0]["content"].as_str().expect("content 是字符串");
        assert!(content.ends_with("..."), "超预算的正文要被截断");
        assert!(
            content.chars().count() < 4_000,
            "{}",
            content.chars().count()
        );
    }

